local config = {
  str_voice_1200501_1 = "不要碎碎念啦！大哥！和克娜莉的管子一樣煩人……",
  str_voice_1200501_2 = "影鎮對於暴力有一套自己的說法，跟上面的人玩的「公平遊戲」不一樣。影狼那傢伙也說過這件事。啊，怎樣都好啦。",
  str_voice_1200501_3 = "我厭惡暴力，但如果是那些向未成年人販賣黑酒的敗類，我不介意打碎他們的下顎。",
  str_voice_1200501_4 = "之前我也在影鎮中遊蕩，但是我已經離開了那不平靜的日子。現在，我只想重建好我的家鄉。",
  str_voice_1200501_5 = "鯊齒島，我的家鄉，我不會讓它再毀於暗鬼之手的。",
  str_voice_1200501_7 = "都一起受過傷了，不是兄弟的話不然是什麼？來擼個貓？",
  str_voice_1200501_8 = "我衝動的時候一定要攔住我啊！敲碎人家的下巴事小，輕易樹敵事大呀！",
  str_voice_1200501_9 = "我喜歡貓，但不喜歡長得像大叔的大貓，不行嗎？所以下次不要讓我和那傢伙一起行動。",
  str_voice_1200501_10 = "啊，突如其來的空檔時間。發呆一下吧？大哥，我那裡有閒置的貓窩，你如果不嫌棄的話，一起來嗎？",
  str_voice_1200501_11 = "等我先刷乾淨身上的貓毛，再給你一個露出四十二顆牙齒的微笑！都說了，我是非暴力主義者。",
  str_voice_1200501_12 = "人生在世，也不能總是打打殺殺……",
  str_voice_1200501_13 = "大哥有看到我的貓嗎？牠有點膽小，又不知道躲到哪裡去了。",
  str_voice_1200501_14 = "你要不要鯊魚牙粉當調味料啊，我這裡剛換了一批，還有很多。",
  str_voice_1200501_15 = "大哥的生日？那就讓我與鋸子共舞來為大哥慶祝吧！",
  str_voice_1200501_16 = "待到有點無聊了，如果能有隻貓……",
  str_voice_1200501_17 = "看到我的牙齒了嗎？不好意思啦，嚇到你了。",
  str_voice_1200501_18 = "似乎到了貓咪們出來活動的時候了！",
  str_voice_1200501_19 = "宵夜吃什麼好呢？炸薯條還是甜菜捲？",
  str_voice_1200501_20 = "鯊齒島雖然小，但是它是屬於我的，不是什麼白夜城或啟光的。",
  str_voice_1200501_21 = "影鎮唯一的規矩，那就是沒有規矩，真是一群暴力狂……",
  str_voice_1200501_22 = "重建鯊齒島！",
  str_voice_1200501_23 = "如果能見到暗鬼的大哥，這兩把鋸子就是見面禮。",
  str_voice_1200501_24 = "如果沒有伊斯塔萬，影鎮遲早成為暴力的漩渦。",
  str_voice_1200501_25 = "我家鄉的重建多虧了浮空商會的幫忙，但那個老闆娘真是黑啊……",
  str_voice_1200501_26 = "一切都為了蔬菜湯、酸角汁，還有無酵餅。",
  str_voice_1200501_27 = "無端宣洩暴力的傢伙才更可惡，或許暗鬼就是那些人變成的！",
  str_voice_1200501_28 = "這居然能飛！古代的東西真了不起啊！",
  str_voice_1200501_29 = "吼！巨像的大哥！這裡的人還不少嘛！現在是要打架了嗎？不會吧，我第一天來啊！",
  str_voice_1200501_30 = "希望這樣的力量永無用武之地。",
  str_voice_1200501_31 = "齒輪！轉得更快了！",
  str_voice_1200501_32 = "去撕碎敵人吧！",
  str_voice_1200501_34 = "這裡是愛貓俱樂部嗎？",
  str_voice_1200501_35 = "可以構成正當防衛了。",
  str_voice_1200501_36 = "小貓咪都躲好了嗎——",
  str_voice_1200501_37 = "旋轉！",
  str_voice_1200501_38 = "鋸碎！鋸碎！",
  str_voice_1200501_39 = "撕裂！",
  str_voice_1200501_40 = "切割！",
  str_voice_1200501_41 = "誰！剛才誰推我？！",
  str_voice_1200501_42 = "就這樣？",
  str_voice_1200501_43 = "抱歉，我得先開溜了。有緣再見！",
  str_voice_1200501_44 = "明明是休息時間……好啦好啦瞭解啦——",
  str_voice_1200501_45 = "你不是對可愛有什麼誤解？",
  str_voice_1200501_46 = "唷！難道你也是同一個圈子的？！啊，不，沒什麼……",
  str_voice_1200501_47 = "嗯……感覺挺貴重的，先收下了。",
  str_voice_1200501_48 = "啊！這個可以給貓咪啊！謝啦！",
  str_voice_1200501_49 = "別找麻煩，否則我會找上你！特別是別動我的孩子們，否則……咪咪～～～別怕，到把鼻這裡來！",
  str_voice_1200501_50 = "看到我別驚訝！以前我的老家有很多這樣的鯊魚頭！只不過那是暗鬼過境前的事情了，唉。",
  str_voice_1200501_52 = "白夜極光？那是什麼啊……",
  str_voice_1200501_53 = "嘿！大哥！",
  str_voice_1200501_54 = "啊——早啊！",
  str_voice_1200501_55 = "現在幾點了啊？",
  str_voice_1200501_56 = "夜生活才剛剛開始！",
  str_voice_1200501_57 = "哈哈！新年，不錯！",
  str_voice_1300471_1 = "你竟然會親自到這種地方來，果然跟緋大人說的一樣。",
  str_voice_1300471_2 = "軍團長大人曾說過，你是個很溫柔的人，不，絕對不是緋大人，我不相信哈哈……咳咳，抱歉……",
  str_voice_1300471_3 = "飛星是原本不屬於這個世界的東西，就像是被海浪送上陸地的珍珠一樣。",
  str_voice_1300471_4 = "我感受到門的那一側有什麼在蠢蠢欲動……很好，它們可以為我所用了。",
  str_voice_1300471_5 = "終於要接受它成為我的一部分嗎，這顆飛星似乎已經準備好了，然而我也……",
  str_voice_1300471_6 = "飛星完整釋放的力量很可怕，但我別無選擇，我必須學會完全支配它。",
  str_voice_1300471_7 = "你的期待是怎樣的呢？或許我可以幫上忙……如果不行的話，我可以找薇薇安試試看？",
  str_voice_1300471_8 = "我感受到你的心意了，今天過後，一切都會和往常一樣。但是！但是！我還是不會放棄的！",
  str_voice_1300471_9 = "從零界歸來之後，我知道我已經有一點不一樣了……大元帥看我的眼神……也有點奇怪。",
  str_voice_1300471_10 = "我有時候也會對著夜色中的銀河出神，或許有其他的飛星掠過呢。",
  str_voice_1300471_11 = "陌生的工作，我也會努力試試看的。",
  str_voice_1300471_12 = "研究跟戰鬥很多時候是相通的，啊！……我忘了你沒有戰鬥能力。",
  str_voice_1300471_13 = "不可以碰這個，飛星很容易失控的，如果你讓它蠢蠢欲動的話……",
  str_voice_1300471_14 = "雖說我不是巨像專家，但這裡的線路真的沒有接錯嗎？",
  str_voice_1300471_15 = "生日快樂！是軍團長大人告訴我的！",
  str_voice_1300471_16 = "今天有研究任務需要準備嗎？最好和軍團長大人有關。",
  str_voice_1300471_17 = "是還沒睡醒，還是來不及睡？",
  str_voice_1300471_18 = "這個時間還在工作的都是啟光的好夥伴吧！不工作的話就走遠點……",
  str_voice_1300471_19 = "來看星星嗎？都比不過我的飛星喔！",
  str_voice_1300471_20 = "我們相信啟光正在做的事，對所有人來說都是最正確的。",
  str_voice_1300471_21 = "紅油那群人……那種東西和我們毫無關係，至少軍團長大人是這樣說的。",
  str_voice_1300471_22 = "為了啟明之光！",
  str_voice_1300471_23 = "這些東西十分危險，但飛星毫不在意，只是簡單地埋葬它們而已。",
  str_voice_1300471_24 = "你說緋……軍團長大人對部下的態度什麼的，啊啊啊臉好燙！",
  str_voice_1300471_25 = "不管什麼時候，薇絲都不會做出辜負大家的事情。",
  str_voice_1300471_26 = "很嚴厲……但依然有很溫柔的時候，欸？你不是問緋大人的事嗎？",
  str_voice_1300471_27 = "不要隨便打聽薇絲和3號地下城的事，軍團長大人知道會生氣的。",
  str_voice_1300471_28 = "現在我們有可以仰賴的新力量了嗎？",
  str_voice_1300471_29 = "這裡有什麼值得研究的對象呢，啟光派我來這裡沒什麼道理啊……除、除非，緋大人也在這……",
  str_voice_1300471_30 = "我感應到了黑色的新星！",
  str_voice_1300471_31 = "零界之海的大門敞開了。",
  str_voice_1300471_32 = "飛星的重負，我會試著駕馭它們！",
  str_voice_1300471_33 = "我做好準備了……",
  str_voice_1300471_34 = "大家準備好了嗎",
  str_voice_1300471_35 = "飛星盈能滿格！",
  str_voice_1300471_36 = "現在需要我的力量了！！",
  str_voice_1300471_37 = "飛星，為同伴獻上祝福！",
  str_voice_1300471_38 = "融化黑暗時代的攻勢！",
  str_voice_1300471_39 = "飛星！",
  str_voice_1300471_40 = "黑雪！",
  str_voice_1300471_41 = "飛星在指引我們！",
  str_voice_1300471_42 = "呼，緋大人有沒有在看呢？",
  str_voice_1300471_43 = "這樣的我果然無法達到她的期望……",
  str_voice_1300471_44 = "這些人都選擇了巨像嗎，也可能是選擇了「你」呢。",
  str_voice_1300471_45 = "你的心意，卓婭收到了。看起來是隨便選的東西呢。",
  str_voice_1300471_46 = "我這就轉送給緋大人，她一定會喜歡！！",
  str_voice_1300471_47 = "嗯嗯，你果然是樂善好施的人。",
  str_voice_1300471_48 = "這居然是……謝、謝謝。",
  str_voice_1300471_49 = "零界之海很美，但是一片孤寂。如果不是緋，我可能會永遠沉浸在那裡、最終溺斃。她是黑夜裡的明燈，如同隆冬中盛放的櫻花……",
  str_voice_1300471_50 = "如果可以的話，我想帶著飛星去探索「零界」那邊的祕密，那個毫無生機的世界是否曾經和我們一樣呢？或許那從雲端流下的歌聲是現在唯一的線索了。",
  str_voice_1300471_52 = "白夜——極光。",
  str_voice_1300471_53 = "有些事情！",
  str_voice_1300471_54 = "晚……啊不，早安。",
  str_voice_1300471_55 = "午安，請問有看見緋大人嗎？",
  str_voice_1300471_56 = "這才是真正的晚安！",
  str_voice_1300471_57 = "好吧，新年快樂！",
  str_voice_1300511_1 = "-一臉凶狠？啊……我是遠視，不過也可能是想吃掉你而已。\n-嘰嘰嘰～",
  str_voice_1300511_2 = "-喔……\n-我在檢查子彈，不要打擾我。否則我一槍幹掉你。安靜。\n-嘰。",
  str_voice_1300511_3 = "不要把我和另外那對活寶相提並論。你可以試試看把他們丟去舊都，看能活多久。哼。",
  str_voice_1300511_4 = "-作為親密無間的夥伴，必須好好保養……-你說親密無間的夥伴嘰？\n-噓……我在擦槍呢。",
  str_voice_1300511_5 = "-我們要練槍，你要不要來當靶？\n-會痛怎麼辦嘰？\n-呵，妳覺得呢？\n-嘰，不負責！",
  str_voice_1300511_7 = "我、我可沒在看那些姐姐！身為專業的槍手，怎麼可能被那種事情分散注意力！！",
  str_voice_1300511_8 = "-如果能找到一個比我高的女孩子當搭檔，倒也不錯？\n-你說什麼嘰！！",
  str_voice_1300511_9 = "我是個無情的槍手，可不會留下你說的那種記錄，明白嗎？那都是這傢伙幹的。",
  str_voice_1300511_10 = "既然你這麼忙，不如把這裡交給我們，我會替你好、好、打、理的……如何？",
  str_voice_1300511_11 = "……我需要微笑嗎？可能會嚇到你喔。哎，隨便吧，只要有錢拿都可以。",
  str_voice_1300511_12 = "我的側臉是不是超級酷？很符合冷靜傭兵的形象吧？",
  str_voice_1300511_13 = "-要不要來一場桌遊？誰輸了就成為晚餐吧。\n-開玩笑！是開玩笑！",
  str_voice_1300511_14 = "這裡禁菸嗎？所以呢？呵，多管閒事的話會被做成皮包喔，小鬼。",
  str_voice_1300511_15 = "生日？那祝你快樂。哈哈，被我的鱷魚笑容嚇到了？",
  str_voice_1300511_16 = "有新任務？",
  str_voice_1300511_17 = "無聊的工作。",
  str_voice_1300511_18 = "空氣不好！咳咳！嘰嘰！",
  str_voice_1300511_19 = "請回吧，這巨像已經歸我們了。",
  str_voice_1300511_20 = "-聒噪的傢伙太多了，有時候恨不得一槍一個幹掉他們。\n-那……嘰！",
  str_voice_1300511_21 = "榴彈的話，還是啟光做得最好，又輕，炸得又響。",
  str_voice_1300511_22 = "亡命！狙擊！",
  str_voice_1300511_23 = "-餵沙蟲。\n-還要切碎。",
  str_voice_1300511_24 = "想要我們徹底服你，還要很長一段時間，畢竟你和醒山還是有不小的差距呢……",
  str_voice_1300511_25 = "-熊和鵝根本就不用槍，他們的武器都是用來嚇唬人的。\n-喔！嘰！",
  str_voice_1300511_26 = "十年的機油，沾著五年份的槍機淤泥，美味、美味。",
  str_voice_1300511_27 = "可惡！彈殼又卡住了！真是萬惡之源！",
  str_voice_1300511_28 = "能不能開砲？用它去轟暗鬼吧！",
  str_voice_1300511_29 = "我是索克，這傢伙是貝可。我們剛剛打賭，看你哪一天會被暗鬼吃掉，你要一起參加這個賭局嗎？",
  str_voice_1300511_30 = "射擊精準度提升了！",
  str_voice_1300511_31 = "由我們打穿！",
  str_voice_1300511_32 = "又是一群活靶。",
  str_voice_1300511_34 = "把這種事當成業餘愛好的可以靠邊站了。",
  str_voice_1300511_35 = "鎖定目標。",
  str_voice_1300511_36 = "已就位。",
  str_voice_1300511_37 = "打！",
  str_voice_1300511_38 = "打穿它！嘰！",
  str_voice_1300511_39 = "砰！轟隆！",
  str_voice_1300511_40 = "輪到我們了！",
  str_voice_1300511_41 = "有腿軟的嗎？現在是溜走的最後機會。",
  str_voice_1300511_42 = "-正常發揮而已。\n-嘰嘰！",
  str_voice_1300511_43 = "-貝可，快躲到我嘴裡來！\n-閃了嘰閃了嘰……！",
  str_voice_1300511_44 = "-報酬一塊都不能少。\n-嘰！",
  str_voice_1300511_45 = "這就是全部？",
  str_voice_1300511_46 = "這個好！我喜歡！",
  str_voice_1300511_47 = "啊啊！這次的很值錢嘛！",
  str_voice_1300511_48 = "這這這！太感謝了！嘰！",
  str_voice_1300511_49 = "不用為了彈藥不足煩惱真不錯，但偶爾也會懷念流浪廢土和奸商討價還價的日子……殺價技巧？沒有技巧，把槍往櫃檯上一丟就完成了。",
  str_voice_1300511_50 = "-當遮天蔽日的暗鬼湧過來時，你會做什麼？\n-當然是開火！嘰！-是擔心暗鬼不夠多啊，笨鳥。",
  str_voice_1300511_52 = "-白夜。\n-極光！極光！極光！",
  str_voice_1300511_53 = "你好嘰！",
  str_voice_1300511_54 = "嘰嘰！",
  str_voice_1300511_55 = "醒了沒？",
  str_voice_1300511_56 = "睡了沒？",
  str_voice_1300511_57 = "-新年？那得祝你快樂了。\n-嘰！",
  str_voice_1300521_1 = "唔啊啊啊怎麼辦，已經遲到了，還是請假吧，用什麼藉口呢？牙痛已經用過了……",
  str_voice_1300521_2 = "你知道白夜城的阿褐嗎？我如果像她一樣瘋狂工作，毛遲早會掉光的！還是啟光分部輕鬆啊！",
  str_voice_1300521_3 = "被當場抓到的感覺真的很不好，不要每次都來找我，我也是會心虛的好嗎！",
  str_voice_1300521_4 = "有你們幾個就夠了嘛！我帶了毛毯，可以睡了嗎？",
  str_voice_1300521_5 = "我來了。我沒來。你覺得我在哪裡？啊不要打我！",
  str_voice_1300521_7 = "希望信使公會在今年的績效考核時，能饒我一命！",
  str_voice_1300521_8 = "你等一下，我記得有個東西可以送給你……啊，暫時找不到了。下次給你。",
  str_voice_1300521_9 = "嗨！你又來了！只要不是來催工作進度，多孚可以陪你聊上一整天！",
  str_voice_1300521_10 = "香脆的爆米花……",
  str_voice_1300521_11 = "別、別、別，我的工作已經夠多了！還有成千上萬的信件等著我呢！",
  str_voice_1300521_12 = "我先走了……那個，我回來了……我果然還是先走好了！",
  str_voice_1300521_13 = "那——什麼……我表哥姪女的上司昨天因為登記錯資訊被罰款了，因此這次的信件——",
  str_voice_1300521_14 = "啊！我突然有點急事，要走了要走了，和你的約定，那就下次了，不好意思！",
  str_voice_1300521_15 = "生日？喔喔～那今天放假慶祝吧～",
  str_voice_1300521_16 = "你怎麼比我還晚到啊！",
  str_voice_1300521_17 = "拖鞋？來不及穿……",
  str_voice_1300521_18 = "啊！我沒有在摸魚！",
  str_voice_1300521_19 = "被鴿子放鴿子不是很正常嗎！",
  str_voice_1300521_20 = "沒人管，自由自在真是太好了，就是沒錢……",
  str_voice_1300521_21 = "啟光很公正！只是似乎每個人都有三隻眼……盯得太緊啦……",
  str_voice_1300521_22 = "信使公會！郵件必達！偶爾放鴿子……",
  str_voice_1300521_23 = "打牠們好麻煩……還是一邊躲一邊前進吧……",
  str_voice_1300521_24 = "你說薇薇安大人！她真的很好！但是不能摸魚……",
  str_voice_1300521_25 = "溫蒂待的地方可真累，因此才那麼厲害吧，換成是我，早就走啦～",
  str_voice_1300521_26 = "打工只是糊口，只有摸魚才感覺自己賺到啦～",
  str_voice_1300521_27 = "能不能……不工作呢，或者上班時不用打卡……",
  str_voice_1300521_28 = "很有趣，但又好像很麻煩……",
  str_voice_1300521_29 = "你好，我叫多孚。有任何信件要寄都可以找我，雖然我不一定會馬上到，但我盡量。咕咕咕。",
  str_voice_1300521_30 = "好像能飛得更快了！",
  str_voice_1300521_31 = "又要上工了嗎……你們先去，我馬上就到。",
  str_voice_1300521_32 = "下、下次！多孚一定到！",
  str_voice_1300521_34 = "救人還是逃跑。",
  str_voice_1300521_35 = "厲害的人總是最後出場！",
  str_voice_1300521_36 = "不能逃……",
  str_voice_1300521_37 = "多孚！走～",
  str_voice_1300521_38 = "鴿影鴿現！",
  str_voice_1300521_39 = "爆、爆肝了！",
  str_voice_1300521_40 = "躲！躲開！",
  str_voice_1300521_41 = "糟糕……當隊長的話，就不能摸魚了……",
  str_voice_1300521_42 = "加油、加油、加油……欸？！已經結束了嗎？！",
  str_voice_1300521_43 = "抱歉，我的腳……又像灌了鉛一樣動不了……",
  str_voice_1300521_44 = "哪裡適合好好睡一覺呢……",
  str_voice_1300521_45 = "希望是有助於睡眠的東西……",
  str_voice_1300521_46 = "咯咯咯！這東西很不錯嘛！",
  str_voice_1300521_47 = "這麼好！我夢裡也會看到它的！",
  str_voice_1300521_48 = "以、以後一定不會放你鴿子！只有你喔！",
  str_voice_1300521_49 = "我的懶惰大概沒救了……可是勤奮也改變不了什麼，我們「皮金家族」早已風光不再。如果被開除就……就……好像就繳不起房租了，還是稍微工作一下吧。",
  str_voice_1300521_50 = "果然那時候！唔啊——該、該怎麼，想想還是小命要緊！可也不能扔下他們……但是小命……但是他們……",
  str_voice_1300521_52 = "白夜……極光。",
  str_voice_1300521_53 = "你來了嗎？",
  str_voice_1300521_54 = "難以置信，我今天準時起床了！",
  str_voice_1300521_55 = "見面嗎？不放鳥。",
  str_voice_1300521_56 = "一起打混嗎？不放鳥。",
  str_voice_1300521_57 = "新的一年，一定不放鳥。",
  str_voice_1300581_1 = "作為騎士，要嚴守、嚴格、嚴……雖、雖然是新晉冊封的，但依舊是騎士！因此要嚴明守紀！",
  str_voice_1300581_2 = "「黎明旗槍」是榮譽的證明……我保證會好好練習使用！不會再戳到別人的衣服了！",
  str_voice_1300581_3 = "學院的學習，騎士團的訓練，演講任務和宣傳工作……時、時間不夠用了！怎麼想都不夠用！",
  str_voice_1300581_4 = "雖然我看起來很不擅長戰鬥的樣子，但是我可以為大家提供庇護！盡量不打到大家的頭！",
  str_voice_1300581_5 = "旗幟所在的地方，大家的心靈會安定，目光有方向，所以我會記好旗幟的！啊，不是，是會舉好旗幟的！",
  str_voice_1300581_7 = "雖然大家的外表不同，但您一定和我一樣是個努力的人吧！……是、是吧？",
  str_voice_1300581_8 = "要相信我們現在做的事一定會有回報，不論是做什麼，也不論是多麼細小的事，都會有價值！",
  str_voice_1300581_9 = "因、因為您為我加油，所以我才想加倍努力！不要看我的肩膀小，我還能扛起更多東西！",
  str_voice_1300581_10 = "我感到寶貴的時間在流逝……嗯，原來如此，休息的時候也要拼盡全力休息！",
  str_voice_1300581_11 = "我知道了！我要把旗幟插在這裡吧！……欸？不是嗎？不、不需要旗幟嗎？",
  str_voice_1300581_12 = "嗚哇！請不要嚇我！下次您出現的時候，最好還是申請一下吧！",
  str_voice_1300581_13 = "雖然我很容易緊張，但是這次我準備好了！這次嚇不到我了……應該吧！",
  str_voice_1300581_14 = "認真、努力、永不放棄！……唔，這樣的座右銘是不是有點短？",
  str_voice_1300581_15 = "今、今天是您的誕生之日，請讓我來為您慶祝！請放心，我演練很久了！",
  str_voice_1300581_16 = "工作的時間到了，我們一起加油吧！",
  str_voice_1300581_17 = "每日訓練都應該在早上進行，感謝您的監督，我會好好完成！",
  str_voice_1300581_18 = "為了保證每日活力充沛，按照預定計劃，我們很快就要休息了！",
  str_voice_1300581_19 = "不愧是您，這個時間還能堅持自己的修行……我、我可不能打瞌睡了！",
  str_voice_1300581_20 = "成為白夜城騎士是我莫大的榮耀，向白夜起誓，我將永遠忠誠！",
  str_voice_1300581_21 = "白夜城與啟光開放交流時我年紀太小，未能參加，實在很遺憾！",
  str_voice_1300581_22 = "白夜至上！",
  str_voice_1300581_23 = "暗鬼是整片大陸的敵人，白夜城會將牠們徹底殲滅，維護和平！",
  str_voice_1300581_24 = "那個紅髮的人為什麼總是把我當作小孩？我明明已經是騎士了！",
  str_voice_1300581_25 = "我會向拉斐爾大人學習！每天元氣滿滿地為大家提供治療！",
  str_voice_1300581_26 = "我喜歡「努力」，只要努力就一定會有回報！",
  str_voice_1300581_27 = "討厭的東西……討厭好吃懶做，還有可怕的東西。",
  str_voice_1300581_28 = "十分輝煌！感受到了前人的智慧！能創造出巨像的人一定很努力！",
  str_voice_1300581_29 = "初次見面，艾米倍感幸……倍、倍感榮幸，從今日開始，我會擔任掌旗者引領大家前進！",
  str_voice_1300581_30 = "成長就是最好的回報！",
  str_voice_1300581_31 = "我現在可以獨當一面了！",
  str_voice_1300581_32 = "我看見了旗幟上更耀眼的光！",
  str_voice_1300581_34 = "我帶好旗幟了！",
  str_voice_1300581_35 = "啊？旗幟、現在要用嗎？",
  str_voice_1300581_36 = "我有好好準備！",
  str_voice_1300581_37 = "光明的旗幟！請保護我們！",
  str_voice_1300581_38 = "這是黎明的恩惠！",
  str_voice_1300581_39 = "加油！",
  str_voice_1300581_40 = "向著希望！",
  str_voice_1300581_41 = "我、我會、會好好帶隊的！",
  str_voice_1300581_42 = "太好了！真的成功了！",
  str_voice_1300581_43 = "欸？我做錯了什麼嗎？",
  str_voice_1300581_44 = "今、今天也要認真訓練呢！",
  str_voice_1300581_45 = "只是有點意外而已。",
  str_voice_1300581_46 = "這個、我真的收下了！真的唷！",
  str_voice_1300581_47 = "畢竟是您送的禮物！",
  str_voice_1300581_48 = "我很想要這個，謝謝您！",
  str_voice_1300581_49 = "成為騎士之後，我有幸得到「部下」這個簡單卻深奧的職位。加百列大人非常照顧我，讓我學到如何努力！",
  str_voice_1300581_50 = "那場可怕的危機裡，白夜城內也發生混亂的事故，還好白夜回應我的願望，給了我光的旗幟。",
  str_voice_1300581_51 = "在我還能努力的時候，我一定會非常努力的！要知道在這個世界上，還有很多想要努力卻失去機會的人。",
  str_voice_1300581_52 = "白夜極、極光！",
  str_voice_1300581_53 = "您、您好！",
  str_voice_1300581_54 = "早安！",
  str_voice_1300581_55 = "午安！",
  str_voice_1300581_56 = "晚安！",
  str_voice_1300581_57 = "新年快樂！",
  str_voice_1300591_1 = "有人說你是隱藏富豪……欸？你不富裕嗎？騙人的吧，沒有錢怎麼變厲害呀，白夜城的公主就超厲害的說。",
  str_voice_1300591_2 = "你不覺得強勢的女人很可怕嗎？尤其是那種金髮的，會貼上來說「你真可愛」的那種，太可怕了，嗚嗚……",
  str_voice_1300591_3 = "為什麼總是有看起來很厲害的暗鬼要找你麻煩啦？話說你是什麼地方的王子嗎？巨像四捨五入等於白馬的說！",
  str_voice_1300591_4 = "啊，我平時用來攻擊的火焰是這條圍、圍、圍巾、圍巾的說……纏、纏住了，好麻煩……",
  str_voice_1300591_5 = "話說去哪裡找言靈啦，沒有言靈沒辦法在信使公會裡升職的說，沒有培訓嗎？自己抓？不是吧……",
  str_voice_1300591_7 = "非常抱歉，我不小心弄壞導航了……備用？啊，前天摔壞的那個……話說你不是可以導航嗎？那就不需要儀器的說。",
  str_voice_1300591_8 = "為什麼一下子那麼多人跟著？……我就是因為沒看出來你有什麼特別的，才一天到晚跟著你看的說！",
  str_voice_1300591_9 = "真羨慕你能被這麼多人包圍啊，明明看起來沒什麼力量……好吧好吧，誰叫你比較珍貴的說。",
  str_voice_1300591_10 = "話說你為什麼老是遇到被暗鬼包圍的危機啦？真的不是你自己找上門的嗎？其實是吧？",
  str_voice_1300591_11 = "等一下，我找找派單……昨天明明放進箱子裡的說……欸？我每次都是這個狀態嗎？我就是這種設定的說……",
  str_voice_1300591_12 = "哪天我請前輩飛過來，讓你瞧瞧真正的翅膀的說……畢竟我沒有呢。",
  str_voice_1300591_13 = "不是麻將是麻雀！為什麼會有人分不清楚啦？這樣發音很有問題的說！",
  str_voice_1300591_14 = "我是一個人生活。家雀本是同屋住，不知不覺各自飛的說。",
  str_voice_1300591_15 = "沒有忘的說，我昨天準備了禮物……呃，忘記拿了。",
  str_voice_1300591_16 = "歡迎回來，反正我一個人也做不了什麼的說，乖乖等你啦。",
  str_voice_1300591_17 = "我好像把派單忘在房間裡了……等等，我昨天在哪裡睡的啊？",
  str_voice_1300591_18 = "啊，我在寫工作清單的說……姑且會稍微努力一下啦。",
  str_voice_1300591_19 = "你還沒打算休息嗎？真的假的，這個時間還在忙，太強的說！",
  str_voice_1300591_20 = "在信使公會裡像我這樣普通的傢伙也能受到照顧，夠幸運的說。",
  str_voice_1300591_21 = "想要好好工作就要面對那個可怕的金髮收信人……好可怕的說。",
  str_voice_1300591_22 = "必達，嗯，要必達的說。",
  str_voice_1300591_23 = "看見那些傢伙張開的嘴巴了嗎？能一口一隻小雀的說，嗚，可怕。",
  str_voice_1300591_24 = "她哪是什麼橢圓導彈啦，毛絨絨的明明就是顆球的說。",
  str_voice_1300591_25 = "每天鴿鴿咕咕叫，不會放人鴿子才奇怪，話說她就是鴿子的說。",
  str_voice_1300591_26 = "讓我在安全的地方生活吧……我就偶爾羨慕一下不平凡而已的說。",
  str_voice_1300591_27 = "嗚，我不太擅長面對奇怪的東西的說，好麻煩，好可怕……",
  str_voice_1300591_28 = "巨像？第一次看到，他脖子好長，好白，好禿……好怪的說。",
  str_voice_1300591_29 = "嗚哇，好離譜，你們這裡的這些人看起來好厲害的說，不需要我也可以吧……等等，別丟下我！拜託——",
  str_voice_1300591_30 = "嗚哇！這是什麼感覺？！",
  str_voice_1300591_31 = "呃，這種時候要說什麼才對？",
  str_voice_1300591_32 = "進化的說？！……啊，還是很普通。",
  str_voice_1300591_34 = "知道了知道了，我來的說。",
  str_voice_1300591_35 = "我會出力的說，大概。",
  str_voice_1300591_36 = "欸，你就只是看著嗎？",
  str_voice_1300591_37 = "你加油，我先走……不能溜嗎？！",
  str_voice_1300591_38 = "嗚哇，好危險，溜了……我這麼短嗎？！",
  str_voice_1300591_39 = "那是什麼？火焰？",
  str_voice_1300591_40 = "好麻煩……的火焰！",
  str_voice_1300591_41 = "要我領隊嗎？真的嗎真的嗎？",
  str_voice_1300591_42 = "結束了，要撿點什麼嗎？",
  str_voice_1300591_43 = "戰敗了……沒事啦，活得好好的！",
  str_voice_1300591_44 = "好了好了，我閉嘴……你確定要我閉嘴嗎？我閉嘴的話你會覺得寂寞嗎？",
  str_voice_1300591_45 = "嗚哇，你是哪裡弄來的東西？有點怪的說……",
  str_voice_1300591_46 = "這麼好的禮物的說，送給普通的我嗎？嗚……",
  str_voice_1300591_47 = "這……我不喜歡這個的說，你不會不知道吧？",
  str_voice_1300591_48 = "你總是對普通的我這麼好的說，嗚，感動……",
  str_voice_1300591_49 = "說什麼？……嗚哇，你們幫每個人都寫檔案嗎？好麻煩的說……呃，不要生氣啊，自暴自棄隨便記錄是什麼意思啦？",
  str_voice_1300591_50 = "圍巾是別人送給我的說，不然我一隻普通小雀怎麼可能有條件添購能放技能的寶物啦，能放技能耶！",
  str_voice_1300591_52 = "啊，白夜極光——",
  str_voice_1300591_53 = "有些事的說！",
  str_voice_1300591_54 = "早安的說！",
  str_voice_1300591_55 = "午安的說！",
  str_voice_1300591_56 = "晚安的說！",
  str_voice_1300591_57 = "新年快樂的說！",
  str_voice_1300741_1 = "如果沒事的話，我想一個人待著……",
  str_voice_1300741_2 = "即使太陽也不能永遠發光，塌縮、湮滅會迎來新生……一遍又一遍。",
  str_voice_1300741_3 = "希望在黑暗到來之時，我們都得到安息……",
  str_voice_1300741_4 = "塞卡姐姐的話總是能讓我安心……就好像，說出了很多我想說的話。",
  str_voice_1300741_5 = "你讓我成長了很多，謝謝。感覺……很溫暖。",
  str_voice_1300741_6 = "也許總有一天，我可以依靠自己走出過去的噩夢吧……",
  str_voice_1300741_7 = "你對我很感興趣嗎？抱歉要讓你失望了。",
  str_voice_1300741_8 = "為什麼要特別關心我？我不配……我身上，有過去的印記……",
  str_voice_1300741_9 = "謝謝你，導航員。你和塞卡姐姐一樣……讓我心安。如果能一直這樣下去，就好了……",
  str_voice_1300741_10 = "它們就像我自己……有一層緊閉的外殼，和灰暗冰冷的內在。",
  str_voice_1300741_11 = "我不喜歡這個地方……可以回到原來的角落裡嗎？……算了，如果你堅持的話。",
  str_voice_1300741_12 = "塞卡姐姐呢？……沒什麼，只是問問……",
  str_voice_1300741_13 = "……我曾經沒有選擇，但如今……也為時已晚了吧？",
  str_voice_1300741_14 = "它們……通常都在快速地衰變輪迴……比我有活力。",
  str_voice_1300741_15 = "……希望這一天你能忘記不好的事……希望你永遠溫暖。",
  str_voice_1300741_16 = "嗯。我還在這裡，哪裡也沒去。",
  str_voice_1300741_17 = "在日光新生之後，我們又見面了。",
  str_voice_1300741_18 = "希望在日光消退之前，我們都能找到……合適的角落。",
  str_voice_1300741_19 = "睡不著嗎……如果你也被噩夢困擾，那我們就有共同點了……",
  str_voice_1300741_20 = "啟光有照顧我的人……但我會戰鬥的，不需要憐憫和同情。",
  str_voice_1300741_21 = "我不太瞭解，如果非要說的話……那座白色的城，不太想見到。",
  str_voice_1300741_22 = "為了……啟明之光。",
  str_voice_1300741_23 = "就像噩夢的產物一樣，能消滅它們的話……就多少能償還了。",
  str_voice_1300741_24 = "塞卡姐姐，在啟光負責心理治療……她總會幫助我……緩解情緒。",
  str_voice_1300741_25 = "好友……不敢說，但紅與黑，是同軍團的……重要的戰友。",
  str_voice_1300741_26 = "能一個人待著比較好……我喜歡，能夠安心的時候。",
  str_voice_1300741_27 = "噩夢，和不屬於我的過往……我討厭它們。",
  str_voice_1300741_28 = "它讓我感到不安……或許因為它是能夠升入高空的東西。",
  str_voice_1300741_29 = "……自我介紹嗎……我叫白矮星。沒什麼更多想說的，我……我要自己待一下。",
  str_voice_1300741_30 = "想要變得更堅強。",
  str_voice_1300741_31 = "……這樣提升，真的有意義嗎？",
  str_voice_1300741_32 = "塞卡姐姐，妳看到了嗎……",
  str_voice_1300741_33 = "過去不是詛咒，而是讓我成長的恩賜。",
  str_voice_1300741_34 = "我也能幫上忙嗎……",
  str_voice_1300741_35 = "情緒……快到極限了……",
  str_voice_1300741_36 = "必須——釋放！",
  str_voice_1300741_37 = "崩塌在引力之中吧——",
  str_voice_1300741_38 = "屈服，於引力之下！",
  str_voice_1300741_39 = "都走開！",
  str_voice_1300741_40 = "消失！",
  str_voice_1300741_41 = "……我真的不擅長社交。",
  str_voice_1300741_42 = "情緒，釋放完畢了……",
  str_voice_1300741_43 = "已經感受不到疼痛了……就這樣吧……",
  str_voice_1300741_44 = "只是在發呆，別看我了……",
  str_voice_1300741_45 = "喔。該說謝謝嗎？",
  str_voice_1300741_46 = "……好像還有點意思。",
  str_voice_1300741_47 = "你不用這麼照顧我……",
  str_voice_1300741_48 = "啊，這個剛好可以用來緩解情緒……",
  str_voice_1300741_49 = "如果我陰鬱的氣質造成你的困擾，那我道歉……但我無法控制，這是深植於意識深處的……病根。",
  str_voice_1300741_50 = "噩夢，過往……那些甚至都不屬於我的記憶為什麼會洶湧而來？我的母親，所說的又是真是假？",
  str_voice_1300741_51 = "總之，我會珍惜啟光這個大家庭，但也必須探究噩夢的源頭，和母親所說的故事……",
  str_voice_1300741_52 = "白夜……極光。",
  str_voice_1300741_53 = "……那個……",
  str_voice_1300741_54 = "……早安。",
  str_voice_1300741_55 = "……午安。",
  str_voice_1300741_56 = "……晚安。",
  str_voice_1300741_57 = "祝你……新年快樂。",
  str_voice_1300801_1 = "你、你要先坐一下嗎、我為你、不是、是請我的「搬運助理」，它們可以為你倒杯茶……你要、多來幾杯嗎？",
  str_voice_1300801_2 = "呀！嚇，嚇到我了……書？我在、看，啟光人要掌握的……二十條社交指南……是錢、錢德菈推薦、給我的。",
  str_voice_1300801_3 = "啟光的專業貨車「卡斯」……雖然看起來、巨大笨重，但是、但是在開採大型礦脈時，非……非常實用。",
  str_voice_1300801_4 = "「搬運助理」，一共有，有，幾個？二、二十三個，看得出來嗎？",
  str_voice_1300801_5 = "不只是戰鬥實力……社交能力、也想、提升。要是能像、莉莉姆一樣擅長、就好了。",
  str_voice_1300801_6 = "很想、家……一個人、有一點、孤獨，但「搬運助理」，很……溫暖，科研室的大家、也很可愛。",
  str_voice_1300801_7 = "看不見我、看不見我、看不見我、看不見我……",
  str_voice_1300801_8 = "直視對方的眼睛……深呼、吸……肢體、接觸——果然還是、還是不行，嗚哇！！",
  str_voice_1300801_9 = "雖然，還是很害怕……但是、和你交流好像、沒有那麼困難。",
  str_voice_1300801_10 = "等一下、還有工作……要不要偷懶、一下……不行不行！",
  str_voice_1300801_11 = "千萬別是我，千萬別是我，千萬別是我……啊啊啊，該怎麼辦啊！",
  str_voice_1300801_12 = "來握手……當然是和、「搬運助理」！",
  str_voice_1300801_13 = "光塵、來自光珀、分解，挖這些東西，不容易……",
  str_voice_1300801_14 = "社交對象的行為難以預測，談話範圍、話題都難以預測……唉……",
  str_voice_1300801_15 = "祝你生日快樂，祝你生日快樂……嗚哇，已經是極限了……",
  str_voice_1300801_16 = "材、材料的硬度，是、是指材料抵抗其他物、體……啊！是你！",
  str_voice_1300801_17 = "早、早餐，好了！「搬運助理」十分擅長。",
  str_voice_1300801_18 = "晚餐時間、到了。今天餐廳、會分配什麼食物呢？",
  str_voice_1300801_19 = "該、睡覺了！不然會，長不高。我已經，夠矮了。",
  str_voice_1300801_20 = "事實是，啟光的集體化模式，在目前環境下，極具優勢……",
  str_voice_1300801_21 = "紅油扳手、有很多粗糙、古老，但奇特的、技術，值得、研究……",
  str_voice_1300801_22 = "為了、啟明之、之光！",
  str_voice_1300801_23 = "是暗鬼——離，離我遠一點，「搬運助理」救我！",
  str_voice_1300801_24 = "其實、我不太擅長、玩遊戲……不過貢露、貢露前輩會邀請我。",
  str_voice_1300801_25 = "「彼岸號」、好帥啊——嗯？卡戎是他的主人……卡戎是誰？",
  str_voice_1300801_26 = "天天天哪，你也喜歡模型嗎！最新款的彼岸號列車模型簡直不得了。",
  str_voice_1300801_27 = "潮濕……「搬運助理」都要生鏽了。",
  str_voice_1300801_28 = "喔喔喔喔——巨像！！必須、必須記錄下來、太、太酷了！",
  str_voice_1300801_29 = "不行不行、鼓起勇氣啊，尤尼梅特，加、加油！初，初次見面！我是啟光機械維修#￥！#%……￥……",
  str_voice_1300801_30 = "測試、通過！",
  str_voice_1300801_31 = "「搬運助理」，愈用愈熟練了。",
  str_voice_1300801_32 = "即使機率很低，也必須、成功。",
  str_voice_1300801_34 = "報、報導！",
  str_voice_1300801_35 = "可以繼續推進。",
  str_voice_1300801_36 = "工程已經、確認。",
  str_voice_1300801_37 = "精準操作。",
  str_voice_1300801_38 = "完美作業。",
  str_voice_1300801_39 = "同舟共濟、進行。",
  str_voice_1300801_40 = "專家、策略。",
  str_voice_1300801_41 = "領導、別人啊……好困難……",
  str_voice_1300801_42 = "光珀在哪？光珀，在哪？",
  str_voice_1300801_43 = "誰來，救救我，救%*……&&*",
  str_voice_1300801_44 = "出、出現了！靈、靈、靈、靈光一閃！",
  str_voice_1300801_45 = "謝謝……",
  str_voice_1300801_46 = "好、喜歡——矜持矜持，咳咳。",
  str_voice_1300801_47 = "真的真的，太感謝了。",
  str_voice_1300801_48 = "啊這是！！咳咳，不，不好意思。",
  str_voice_1300801_49 = "我嘗試過、和別人交流，但總是，不得要領。沒有朋友，無法讀懂……空氣，不過幸好還有「搬運助理」。",
  str_voice_1300801_50 = "我可能、還是不知道、怎麼和別人交流，但是啟光的大家、跟我說，不用思考那麼多，做自己就夠了。",
  str_voice_1300801_52 = "白夜極光。",
  str_voice_1300801_53 = "這個。",
  str_voice_1300801_54 = "早安。",
  str_voice_1300801_55 = "￥%抱歉，按錯了，呃欸……",
  str_voice_1300801_56 = "這個，比直接說話好一些……",
  str_voice_1300801_57 = "祝賀新一年……新年。",
  str_voice_1300821_1 = "我來幫您搬一些箱子吧？裡面裝的是什麼呀？是材料嗎？沒關係啦，我都搬得動唷，嘿嘿～",
  str_voice_1300821_2 = "我以前有不小心撞到女王陛下，女王陛下好像有說，身上的防護魔法被打破了什麼的……是不是生氣了呢……",
  str_voice_1300821_3 = "想要寶石就要承受它的重量，不過我不想要這麼大的角呀，它們以前明明小小的，很可愛……現在卻……",
  str_voice_1300821_4 = "如果要放鬆眼睛，就請凝視這綠色的光芒吧！啊，您稍等一會，我調整一下，馬上就好！……欸嘿！",
  str_voice_1300821_5 = "讓我想想什麼是最好的東西……啊，有了！北境的雪與松樹，五月的清風，願為您帶來復甦與生長～",
  str_voice_1300821_7 = "請不要再問啦，羊角的重量怎麼可以隨便告訴別人呢……啊，我有忘記說，您只能看不能碰嗎？",
  str_voice_1300821_8 = "和您一起看起來很有趣的樣子呢！嗯，一定很有趣喔！嘿嘿，沒關係啦，我就在旁邊看看就好！",
  str_voice_1300821_9 = "我有一顆閃亮的星星，在額頭上……您沒有嗎？……我其實第一次見您就在想了，想要送您一顆！",
  str_voice_1300821_10 = "其實這不是羊角而是大樹枝唷，可以取下來的，欸！……嘿嘿嘿，騙您的，您上當了嗎？",
  str_voice_1300821_11 = "這麼重要的職位……還是下次吧？……欸？一定要嗎？我該坐著還是站著？要、要發光嗎？",
  str_voice_1300821_12 = "新鮮的小雪花，您要嚐嚐嗎？涼涼的呢……嗯！是諾爾小姐創造的！",
  str_voice_1300821_13 = "請、請不要碰我的角，很危險，您會很危險，我也會很危險的！",
  str_voice_1300821_14 = "該怎麼辦才好呢？那個也好，這個也不錯，好猶豫呀～",
  str_voice_1300821_15 = "禮物是漂亮的祝福綠光喔！這裡！……真是的，您看看我的角嘛～",
  str_voice_1300821_16 = "您要出發了嗎，冒險家？……啊，沒關係，我就不去了啦～",
  str_voice_1300821_17 = "早上起來時，我總是會昏昏沉沉的，感覺頭好重……是真的好重。",
  str_voice_1300821_18 = "歡迎回來，您辛苦了……請、請問您有時間嗎？我想請教一些問題。",
  str_voice_1300821_19 = "唔……您一直都這麼有精神嗎？是怎麼做到的呢？",
  str_voice_1300821_20 = "小心圍起寶物，讓它不受紛擾，所以在漫長的時間後才能熠熠生輝～",
  str_voice_1300821_21 = "浮在天上的巨城，明明聽起來那麼重，卻沒有支撐，好厲害呀！",
  str_voice_1300821_22 = "嘿嘿，暮冬而生～",
  str_voice_1300821_23 = "暗鬼……好可怕，如果被牠們包圍的話……您一定要跑呀！",
  str_voice_1300821_24 = "您千萬不能撞到她的鏡子，不然尼珀里絲姐姐會生氣的。",
  str_voice_1300821_25 = "嘿嘿，跟諾爾小姐在一起很輕鬆的，有小雪人在我就不怕摔倒啦～",
  str_voice_1300821_26 = "嘿嘿，那個……您可能看不太出來，我其實會自己做衣服呢！",
  str_voice_1300821_27 = "說了不可以做的事就是不可以做唷！如果不聽勸告就會受懲罰唷！",
  str_voice_1300821_28 = "巨像好大，或許比我家還大！您以前一個人住這裡嗎？會孤單嗎？",
  str_voice_1300821_29 = "您就是傳聞中的冒險家嗎！呀！這可真是奇妙的際遇！……啊，失禮了，我是、我、我該怎麼介紹自己比較好呢？",
  str_voice_1300821_30 = "角、成長了嗎？騙人的吧……",
  str_voice_1300821_31 = "發光的石頭？啊，那是角啦！",
  str_voice_1300821_32 = "看我發現了什麼？幸運者的寶珠！",
  str_voice_1300821_34 = "不、不可以撞到別人……",
  str_voice_1300821_35 = "那個，要發光了！",
  str_voice_1300821_36 = "只能看不能碰唷！",
  str_voice_1300821_37 = "向您許諾！綠光！",
  str_voice_1300821_38 = "幸運永遠在您身邊！",
  str_voice_1300821_39 = "綠色的寶石！",
  str_voice_1300821_40 = "幸運的寶珠！",
  str_voice_1300821_41 = "欸？這……該怎麼辦才好啦……",
  str_voice_1300821_42 = "我、我做到了嗎？成功了嗎？",
  str_voice_1300821_43 = "很抱歉……我果然還是不行……",
  str_voice_1300821_44 = "呀——不要摸我的角～",
  str_voice_1300821_45 = "要把這個搬走嗎？咦？不重呢～",
  str_voice_1300821_46 = "我可以收嗎？謝謝您！",
  str_voice_1300821_47 = "原來是要給我的嗎？那我搬走好了！",
  str_voice_1300821_48 = "嘿嘿，原來如此，這是禮物！我好喜歡！",
  str_voice_1300821_49 = "明明已經不能再長大了，可是它還是一點一點在生長，如果重量繼續增加，怎麼辦才好呀……",
  str_voice_1300821_50 = "我以前住在被雪與綠松圍繞的石頭城裡，因為遇到您而有機會見到了外面的風景～",
  str_voice_1300821_52 = "嘿嘿，白夜極光！",
  str_voice_1300821_53 = "啊、啊那個……",
  str_voice_1300821_54 = "早安呀，冒險家～",
  str_voice_1300821_55 = "請問您有時間嗎？",
  str_voice_1300821_56 = "請問您對發光的角有興趣嗎？",
  str_voice_1300821_57 = "嘿嘿～祝您新年快樂～",
  str_voice_1400071_1 = "想成為生長在高處的植物。",
  str_voice_1400071_2 = "昨晚，似乎夢到了……一隻兔子……",
  str_voice_1400071_3 = "要如何才能擁有安寧的生活呢……或許就是現在……？",
  str_voice_1400071_4 = "現在的我，不會再被任何人抓住……！",
  str_voice_1400071_5 = "除了自由，什麼都不重要……沒錯，什麼都……",
  str_voice_1400071_7 = "……您的這份溫柔，我還不擅長接受。但，謝謝……",
  str_voice_1400071_8 = "這份好意讓我想起一件很久遠以前的往事。算了，無聊的舊話而已……",
  str_voice_1400071_9 = "又見面了。要一起吹吹風嗎？午後的清風……啊，抱歉，忘記您不太擅長隨風搖曳這種事。",
  str_voice_1400071_10 = "哼哼～哼～～哼～～咳！……",
  str_voice_1400071_11 = "我喜歡這裡，有風的香氣。",
  str_voice_1400071_12 = "……下一個目標是誰？洗耳恭聽。",
  str_voice_1400071_13 = "請問……您有看到……唔，沒事。打擾了，我會自己去找……",
  str_voice_1400071_14 = "祝武運昌隆。",
  str_voice_1400071_15 = "今天是您的生日？那我祝福您。",
  str_voice_1400071_16 = "和在紅油扳手時不太一樣，但我會努力。",
  str_voice_1400071_17 = "這陣風真舒服……",
  str_voice_1400071_18 = "風，已帶您回家。",
  str_voice_1400071_19 = "這裡的風景很不錯呢～尤其是夜晚……",
  str_voice_1400071_20 = "雖然這裡的人都很聒噪……但是，我並不討厭他們，因為他們人真的很好。",
  str_voice_1400071_21 = "在影鎮中，最慘的不是那些貧窮的大人，而是貧窮的孤兒們。",
  str_voice_1400071_22 = "自由自在，無拘無束。",
  str_voice_1400071_23 = "暗鬼的攻擊性是天生的，其實算是簡單的生物，比起某些邪惡的人心……",
  str_voice_1400071_24 = "那個……您看到那隻喝柴油的兔子了嗎？沒有？……還想問他要不要一起去吹吹風呢。",
  str_voice_1400071_25 = "醒山老大是我們的核心，沒有他，紅油扳手就是一盤散沙。",
  str_voice_1400071_26 = "如果您看到兔子……請放過牠……",
  str_voice_1400071_27 = "我覺得，現在的麗薇已經能夠自己面對那個傢伙……無需他人協助。",
  str_voice_1400071_28 = "好大的地方，還能住人……而且飛在空中，感覺好安心……",
  str_voice_1400071_29 = "葉子與花瓣均可殺敵，而最鋒利的，卻是人心……",
  str_voice_1400071_30 = "草刃，更加鋒利了。勞您費心。",
  str_voice_1400071_31 = "強大是自由的基礎。",
  str_voice_1400071_32 = "花朵也是利刃。",
  str_voice_1400071_34 = "那個人在隊伍裡嗎……",
  str_voice_1400071_35 = "四葉草！待命！",
  str_voice_1400071_36 = "指明方向吧——",
  str_voice_1400071_37 = "切碎目標！",
  str_voice_1400071_38 = "利刃！散去！",
  str_voice_1400071_39 = "四葉草！攻擊！",
  str_voice_1400071_40 = "鋒銳的花朵！",
  str_voice_1400071_41 = "……我可以自己選擇隊員嗎？",
  str_voice_1400071_42 = "目標清除。請讓我擦拭草葉上的暗塵。",
  str_voice_1400071_43 = "暫時撤退。請保護好自己！",
  str_voice_1400071_44 = "在這裡，連心也可以安靜下來……",
  str_voice_1400071_45 = "謝謝您的禮物。",
  str_voice_1400071_46 = "好貴重啊！我可以收下嗎？",
  str_voice_1400071_47 = "……感謝。您真的在努力嘗試呢。",
  str_voice_1400071_48 = "這是我一直想要的！那、那個，真的可以嗎？！",
  str_voice_1400071_49 = "永遠不要以愛之名綁架一名孤兒。原本以為內心會被愛意灌注，未曾想到卻陷入了冰冷的牢籠……還好，萬事皆有轉機。",
  str_voice_1400071_50 = "孤兒……像我這樣的孩子，很多。但幸運的是我遇到了師父，他似乎來自遙遠的東方……",
  str_voice_1400071_52 = "白夜極光。",
  str_voice_1400071_53 = "那個……",
  str_voice_1400071_54 = "早安。",
  str_voice_1400071_55 = "午、午安。",
  str_voice_1400071_56 = "晚安。",
  str_voice_1400071_57 = "新、新年快樂。",
  str_voice_1400081_1 = "今天狀態如何？需不需要用這把鎚子敲打一下？嘿嘿，嚇你的啦。",
  str_voice_1400081_2 = "待機的時候試著幫你的船做了日常維護，就像醒山大哥說的，不勞動者不得食！",
  str_voice_1400081_3 = "也不知道醒山大哥現在怎麼樣了？畢竟他總是做傻事，是個讓人操心的傢伙，沒有我盯著的話……",
  str_voice_1400081_4 = "真是了不起的工程學奇蹟啊……這麼厲害的巨像卻必須聽從你的命令，總覺得……唔，沒什麼！你真厲害！",
  str_voice_1400081_5 = "我已不是落下的小石子。在黑夜裡，哪怕我正在逃避，也有人為我打了光……現在輪到我了。",
  str_voice_1400081_7 = "你這個人真是……怎麼有辦法在這世界活到現在？",
  str_voice_1400081_8 = "雖然不是紅油的人，但你確實跟那些軟骨頭不一樣。作為老大算是勉強合格啦。雖然比起醒山大哥還差那麼一點點。",
  str_voice_1400081_9 = "如果當時救了我的人是你而不是醒山大哥的話……也許……唔！沒什麼！",
  str_voice_1400081_10 = "更換關鍵部位的軸承的話……重新計算轉速……咦，你什麼時候來的？",
  str_voice_1400081_11 = "我比較擅長幕後工作……算啦，既然你這麼堅持……",
  str_voice_1400081_12 = "喂！別踩到我的工具啦！對對對，就是你的右腳！",
  str_voice_1400081_13 = "喂，有空嗎，幫我綁辮子……今天頭髮太蓬了，我自己不好弄。",
  str_voice_1400081_14 = "這條圍巾是我最重要的寶物，洗的時候要小心……沒有要你去洗啦！",
  str_voice_1400081_15 = "你期待我唱生日快樂歌給你聽嗎？……幫你做個音樂盒還差不多。",
  str_voice_1400081_16 = "唷，你來啦。我還以為你會一去不回呢。",
  str_voice_1400081_17 = "我本來打算去幫你增加一點「人工日光」，看來現在不用了。",
  str_voice_1400081_18 = "你要不要偶爾嘗試看看……算了，技術人員也挺辛苦的。",
  str_voice_1400081_19 = "有時候強光比黑夜更可怕。你們這……倒還好啦。",
  str_voice_1400081_20 = "就算是拿戰利品也得挑一下吧？那群老爺們怎麼總是撿些垃圾……",
  str_voice_1400081_21 = "聽說啟光推崇科學技術……別誤會！我在紅油扳手內的地位也很高！",
  str_voice_1400081_22 = "休息一下吧，別一直喊。",
  str_voice_1400081_23 = "暗鬼怕強光這一點，我倒是多少能理解。",
  str_voice_1400081_24 = "看看歐緹的樣子就知道技術人員有多辛苦了，氣到神志不清。",
  str_voice_1400081_25 = "誰需要他救，明明是他自己忍不住出手……雖然我滿感謝他的。",
  str_voice_1400081_26 = "手工製造。就是鑽研技術、用各種零件組裝啦！",
  str_voice_1400081_27 = "我討厭沒本事的傢伙，更討厭沒本事還逞強的傢伙！就算是自己也一樣。",
  str_voice_1400081_28 = "你真的不和我們合作嗎？沒有要搶你的巨像，只是拉回去看看！真的！",
  str_voice_1400081_29 = "別搞錯了喔，我只是瞞著醒山大哥，幫他來看看你到底有什麼本事而已！",
  str_voice_1400081_30 = "功率提升！",
  str_voice_1400081_31 = "這點程度的優待不是理所當然的嗎？",
  str_voice_1400081_32 = "作為照亮黑夜的明燈而啟動。",
  str_voice_1400081_34 = "早就該讓我上場啦！",
  str_voice_1400081_35 = "聚光燈準備完畢！",
  str_voice_1400081_36 = "鏘鏘鏘～",
  str_voice_1400081_37 = "強光的威力，來體驗體驗～",
  str_voice_1400081_38 = "消除恐懼，開拓光路！",
  str_voice_1400081_39 = "亮不亮？",
  str_voice_1400081_40 = "都閃瞎算了。",
  str_voice_1400081_41 = "嗯哼！都聽我指揮喔！",
  str_voice_1400081_42 = "嘿嘿～畢竟有我在嘛！",
  str_voice_1400081_43 = "別傻傻站著呀笨蛋，先閃人吧！",
  str_voice_1400081_44 = "不用擔心我的身高！先擔心你的巨像吧！哼！",
  str_voice_1400081_45 = "……這是什麼東西啊？",
  str_voice_1400081_46 = "喔喔喔！這個超棒！",
  str_voice_1400081_47 = "……最好是能用得到的東西啦。",
  str_voice_1400081_48 = "好東西！還是你比較懂喔！",
  str_voice_1400081_49 = "不要只憑外表判斷，我可是在垃圾場裡長大的，組裝任何裝備都沒問題……喔，那地方叫戰利品堆放場才對……",
  str_voice_1400081_50 = "哼哼～你要是不認真一點，這艘船說不定哪天就要被我們紅油扳手接管了喔！喂……摸我的頭幹什麼！我沒有在開玩笑！",
  str_voice_1400081_52 = "白夜極光。",
  str_voice_1400081_53 = "能聽到吧……",
  str_voice_1400081_54 = "只是問問你醒來沒。",
  str_voice_1400081_55 = "能來一下嗎？",
  str_voice_1400081_56 = "如果你還沒睡的話。",
  str_voice_1400081_57 = "請去別的地方聽「新年快樂」吧。",
  str_voice_1400161_1 = "別在我剛起床的時候找我談事情。這時候所有人都是我的敵人。",
  str_voice_1400161_2 = "如果可以，請讓我離那些長毛的傢伙們遠一點。",
  str_voice_1400161_3 = "法蘭茲那傢伙，又不知道去哪裡了，這樣離開也好。",
  str_voice_1400161_4 = "有人在欺負小狗？帶我過去吧。我會讓那傢伙跟自己的雙手說再見……",
  str_voice_1400161_5 = "子彈要好好檢查，否則在需要打爆那些攻擊弱小動物的人時，彈殼容易卡住……",
  str_voice_1400161_6 = "準度更高了，我會把它對準那些無可救藥的傢伙——暗鬼、噪音製造者、和虐待小動物的禽獸。",
  str_voice_1400161_7 = "就算是毛茸茸的小東西，打擾到我一樣要挨子彈。當然，你也一樣。",
  str_voice_1400161_8 = "這群傢伙總是讓我一個人！你！來代替我吧。",
  str_voice_1400161_9 = "誰敢打擾我睡覺，一律當暗鬼處理，包括你。",
  str_voice_1400161_10 = "稍微小睡一下吧，你！把那些動物帶走，不要來打擾我。",
  str_voice_1400161_11 = "要我站崗？好吧，反正我經常熬夜。",
  str_voice_1400161_12 = "你累了？那也不能休息，我可是經常熬夜的。",
  str_voice_1400161_13 = "討厭的小傢伙又來蹭我！卡夫卡，你要狠下心來呢……",
  str_voice_1400161_14 = "偶爾也要休息，法蘭茲呢？法蘭茲！我不是說過要待在離我三公尺以內的嗎！",
  str_voice_1400161_15 = "你的生日？要我祝福嗎？",
  str_voice_1400161_16 = "現在是那群毛小孩活動的時間，好好看住！別讓牠們亂跑！",
  str_voice_1400161_17 = "誰准你打擾我休息！啊，原來是早上了！看來又熬夜了。",
  str_voice_1400161_18 = "沒人來交接？這群懶散的東西，總有一天我會在夜裡給他們一槍……",
  str_voice_1400161_19 = "累死了！不想值班了，睡覺去！",
  str_voice_1400161_20 = "人人都好，但人人都少根筋！全靠我一個人站崗，看看我的黑眼圈！",
  str_voice_1400161_21 = "啟光的人處心積慮想把我的槍拿去研究，怎麼可能！真是一群科學瘋子！",
  str_voice_1400161_22 = "讓那些欺負弱小的人，嚐嚐被按在地上摩擦的滋味。",
  str_voice_1400161_23 = "只要槍還在，來一個暗鬼就殺一個，讓牠們真正地「回家」。",
  str_voice_1400161_24 = "那隻大蜥蜴！竟然意外地有點可愛……嗯？什麼，我有說什麼嗎？",
  str_voice_1400161_25 = "很久沒見到那對熊和企鵝了。還在找冷氣機嗎？有機會我送他們一些零件好了。",
  str_voice_1400161_26 = "控制自己，卡夫卡……毛茸茸的傢伙，以後再繼續摸……",
  str_voice_1400161_27 = "噪音！噪音！偌大的紅油沙漠，居然連張安靜的床都沒有",
  str_voice_1400161_28 = "這傢伙可真大，聽說還有什麼自我意識？如果這樣，那就叫他站崗好了。",
  str_voice_1400161_29 = "我是卡夫卡。我有三個訴求：別讓我站崗，單人隔音宿舍，還有把這群動物從我身邊趕走！",
  str_voice_1400161_30 = "更快，更準。",
  str_voice_1400161_31 = "法蘭茲！上！",
  str_voice_1400161_32 = "換上威力更大的子彈吧！",
  str_voice_1400161_33 = "射擊！拼命地射擊！",
  str_voice_1400161_34 = "別放過敵人！",
  str_voice_1400161_35 = "搜尋敵人中……",
  str_voice_1400161_36 = "超電槍！瞄準！",
  str_voice_1400161_37 = "開火！",
  str_voice_1400161_38 = "無處可躲！",
  str_voice_1400161_39 = "超電！散射！",
  str_voice_1400161_40 = "近距離射擊！",
  str_voice_1400161_41 = "我來盯緊他們。",
  str_voice_1400161_42 = "小菜一碟嘛。",
  str_voice_1400161_43 = "壓力太大，發揮失常……",
  str_voice_1400161_44 = "這裡沒有動物？太好了！啊，但有點無聊呢……",
  str_voice_1400161_45 = "禮物？好吧，那我就收下了。",
  str_voice_1400161_46 = "這個禮物，還真是不錯……",
  str_voice_1400161_47 = "看起來很值錢呢，謝啦。",
  str_voice_1400161_48 = "這個？啊！大感謝！",
  str_voice_1400161_49 = "紅油扳手？其實一開始我並不想加入他們，但是那隻大蜥蜴，真的是無法讓人拒絕呢。",
  str_voice_1400161_50 = "想知道我是怎麼得到這把步槍的嗎？那是個有趣的故事，不過你得先將這些黏人的小傢伙趕走。",
  str_voice_1400161_51 = "我的家原本是座小城堡，不是這隻大蜥蜴！如果不是因為暗鬼……不想說了。我要睡覺了。",
  str_voice_1400161_52 = "白夜極光！",
  str_voice_1400161_53 = "在不在？",
  str_voice_1400161_54 = "雖然是早上。",
  str_voice_1400161_55 = "有空嗎？",
  str_voice_1400161_56 = "你在值班嗎？",
  str_voice_1400161_57 = "誰要說啊……新年快樂。",
  str_voice_1400351_1 = "對信使公會來說，超出業務範圍的工作是不存在的喔！",
  str_voice_1400351_2 = "我一直很好奇，你們是怎麼把那架比艙門還要大的風琴運進來的？？",
  str_voice_1400351_3 = "耀西覺得你很可愛，真的是耀西說的，絕對不是我！",
  str_voice_1400351_4 = "什麼？？耀西，竟然說現在的它比覺醒前的我還要強！我能不眠不休它能嗎？",
  str_voice_1400351_5 = "可以看到我瞳孔中閃爍的雷光嗎！那是送完貨之後的不加班之光！",
  str_voice_1400351_7 = "有人竟然說信使公會是冒險家組成的，我們才沒有那麼閒！",
  str_voice_1400351_8 = "偷偷帶了北境的軟糖給你！出差時帶回來的，你不可以分給其他人喔。",
  str_voice_1400351_9 = "我的生活裡好像只有工作，你最好也是！這樣的話我們可以有好多共同話題！",
  str_voice_1400351_10 = "-你發呆的樣子真可愛。欸被聽到了？！咳、耀、耀西，你不要說那種奇怪的話！\n-嘎！",
  str_voice_1400351_11 = "雖然不太擅長做這種事……",
  str_voice_1400351_12 = "想好委託的內容了嗎？阿褐沒有一整天的時間在這裡等你喔。",
  str_voice_1400351_13 = "精神是寫在臉上的，但和黑眼圈和臥蠶都沒有關係喔！",
  str_voice_1400351_14 = "請不要在意那隻懶鴿子，找遍整個公會也沒有第二個那樣的傢伙喔。",
  str_voice_1400351_15 = "雙倍生日快樂！一份是我，另一份是耀西送給你的！",
  str_voice_1400351_16 = "你好像永遠有忙不完的事情，和阿褐一樣！",
  str_voice_1400351_17 = "晚安？喔喔，別在意，阿褐剛剛是在對耀西問好。",
  str_voice_1400351_18 = "要跟阿褐一起去外面旅行的話，這個時間還來得及喔。",
  str_voice_1400351_19 = "嗯？這個時間還沒睡的恐怕只有我了喔。",
  str_voice_1400351_20 = "有任何工作就交給我們吧，公會裡每一個人都和我一樣，愛加班。",
  str_voice_1400351_21 = "商會偶爾會擅自拆開他人的信件，紅油的人都不會做這種事。",
  str_voice_1400351_22 = "信使公會！郵件必達！",
  str_voice_1400351_23 = "除非是委託，否則信使不會主動介入與暗鬼的戰鬥喔。",
  str_voice_1400351_24 = "公會長老都滿和藹的，因為大多數信使工作都不需要人監督啦。",
  str_voice_1400351_25 = "遊手好閒的信使？你說多孚嗎，她再這樣下去大概很快就會被開除吧。",
  str_voice_1400351_26 = "耀西剛才說，巧克力榛果好吃到哭！",
  str_voice_1400351_27 = "請不要跟多孚談論阿褐的事情，千萬不要！",
  str_voice_1400351_28 = "遇到天氣不好的時候，阿褐和耀西可以在巨像外面一起飛喔！",
  str_voice_1400351_29 = "小可愛，有你的信！！",
  str_voice_1400351_30 = "我可以試試剛學到的東西嗎？",
  str_voice_1400351_31 = "眼界開闊！",
  str_voice_1400351_32 = "這樣的我可能會製造出麻煩喔！",
  str_voice_1400351_34 = "是加班吧！",
  str_voice_1400351_35 = "準備好了！",
  str_voice_1400351_36 = "最後一擊是我來嗎？？",
  str_voice_1400351_37 = "耀西，和我一起！",
  str_voice_1400351_38 = "讓雷光響徹吧！",
  str_voice_1400351_39 = "已掃清道路。",
  str_voice_1400351_40 = "障礙清除！",
  str_voice_1400351_41 = "信使都是天生的開路先鋒！",
  str_voice_1400351_42 = "不要小看信使的爪子和羽毛啊！",
  str_voice_1400351_43 = "其實這已經超出業務範圍了啦——",
  str_voice_1400351_44 = "這個大傢伙飛起來的時候也要拍動翅膀嗎？",
  str_voice_1400351_45 = "謝謝，雖然……但是……謝謝！！",
  str_voice_1400351_46 = "哇噢！阿褐很開心！耀西也是！",
  str_voice_1400351_47 = "阿褐開心收下了，只要是你送的！",
  str_voice_1400351_48 = "為什麼？你總是知道耀西最喜歡的東西！",
  str_voice_1400351_49 = "使命必達！公會的服務範圍沒有界限，我也沒有！如果有複雜的委託請聯絡離你最近的公會駐點喔！",
  str_voice_1400351_50 = "時時刻刻，我和我的同伴都在大陸上奔波，穿越漆黑的古城，和閃耀的沙漠。只要有我們在，再遙遠的距離都可以重新連接起來！",
  str_voice_1400351_52 = "白夜極光！",
  str_voice_1400351_53 = "你聽我說！",
  str_voice_1400351_54 = "早上了早上了！快醒醒！",
  str_voice_1400351_55 = "午時已到！嘎！",
  str_voice_1400351_56 = "你聽我說啊！嗝！",
  str_voice_1400351_57 = "新年快樂嗎？不加班的話……",
  str_voice_1400401_1 = "要不要吃吃看跳跳糖？科學班的大家都很喜歡這個味道。啊，抱歉拿錯了，那是炸藥。",
  str_voice_1400401_2 = "你見過煙火嗎？哼哼～我能把惹我的白痴炸得比煙火更壯觀喔？",
  str_voice_1400401_3 = "爆炸就是浪漫！連這個都沒辦法理解？真是不懂少女心啊！",
  str_voice_1400401_4 = "煙火……好美啊！你難道不想變成那樣嗎？沒事啦，我可是專業的呀！",
  str_voice_1400401_5 = "想調配一些新品項……小不點說紅的不錯，你最喜歡的焰色反應是哪一種？",
  str_voice_1400401_6 = "親愛的朋友，你掉的是這顆金炸彈？還是這顆銀炸彈？還是這一包普通的炸彈呢？啊哈，要不然都給你吧！",
  str_voice_1400401_7 = "跳跳糖很棒吧？發生在唇齒之間的爆炸也一樣美好呢～",
  str_voice_1400401_8 = "最近有沒有什麼想爆破的東西呀？無論大小都可以喔，堆滿委託書的辦公室？或者白夜城？",
  str_voice_1400401_9 = "哇！你從哪裡冒出來的！啊啊啊啊，差點以為心臟要爆炸了……",
  str_voice_1400401_10 = "再不做點什麼就無聊得頭都要爆炸了……我可以去找小不點一起玩嗎？",
  str_voice_1400401_11 = "來啦來啦！我會讓場面熱鬧起來的！",
  str_voice_1400401_12 = "冰鎮碳酸飲料不錯呢！冰鎮的碳酸跟硝酸也不錯呢！啊，酸重複了～",
  str_voice_1400401_13 = "聞聞看，是祕製炸彈的甜美香氣喔～沒事啦，聞一聞不會炸～",
  str_voice_1400401_14 = "帶上防風鏡～帶上背包～帶上這個那個～走，去玩點刺激的！",
  str_voice_1400401_15 = "先送你這個，再送你這個，這些都是什麼？是橢圓的小禮物！",
  str_voice_1400401_16 = "你歸隊了！不放煙火慶祝一下嗎？啊，已經點火了。",
  str_voice_1400401_17 = "你醒了嗎？我在你床頭放了不少小東西呢，你沒看見嗎？",
  str_voice_1400401_18 = "你回來得正好！要來點沙蟲嗎？涼拌的！很香唷！",
  str_voice_1400401_19 = "你要睡了嗎？要不要我幫你製造一點助眠音效？會睡得更好喔！",
  str_voice_1400401_20 = "在紅油每天都可以出去兜風，食物什麼的荒漠上隨便都可以撿啦～",
  str_voice_1400401_21 = "啊，我離開啟光之前在地下藏了一些寶貝，不知道被找到了沒有～",
  str_voice_1400401_22 = "及時炸掉！",
  str_voice_1400401_23 = "黑黑瘦瘦的，炸掉炸掉～黑黑胖胖的，炸掉炸掉～",
  str_voice_1400401_24 = "老大喜歡帶人到處撿垃圾，會帶回好多研究材料！",
  str_voice_1400401_25 = "小不點會和我一起做垃圾分類……啊，她好像說是戰利品分類？",
  str_voice_1400401_26 = "叮鈴匡啷的金屬啦，砰砰砰的爆炸啦，跳跳跳的跳跳糖啦～",
  str_voice_1400401_27 = "我可受不了沒什麼聲音的平靜生活啦，來手動製造點聲響吧！",
  str_voice_1400401_28 = "我知道！巨像看起來都好好拆的樣子喔，肋骨什麼的不需要吧？",
  str_voice_1400401_29 = "初次見面！我是比比比約恩～剛才裝進你口袋的炸彈就當是見面禮吧，不用客氣喔！",
  str_voice_1400401_30 = "威力～最大化——！",
  str_voice_1400401_31 = "新的配方！",
  str_voice_1400401_32 = "可以開煙火大會了！真是讓人超級期待呀～",
  str_voice_1400401_33 = "接下來要挑哪個幸運兒送到天上去呢～？",
  str_voice_1400401_34 = "熱鬧起來吧！",
  str_voice_1400401_35 = "可以倒數計時了唷！",
  str_voice_1400401_36 = "讓你看看最棒的煙火！",
  str_voice_1400401_37 = "華麗地炸裂吧！",
  str_voice_1400401_38 = "燃燒著綻放於天際！",
  str_voice_1400401_39 = "砰～砰嗄～砰～～",
  str_voice_1400401_40 = "煙滅～沙啦啦啦♪",
  str_voice_1400401_41 = "來，一人拿一個炸彈喔。",
  str_voice_1400401_42 = "嗯嗯！不錯的煙火大會！",
  str_voice_1400401_43 = "頭髮都燒焦了……嗚……",
  str_voice_1400401_44 = "猜猜炸彈在我的左手還是右手？……啊，當然是兩手都有啦！",
  str_voice_1400401_45 = "不錯欸！",
  str_voice_1400401_46 = "這個太好玩啦！開心！",
  str_voice_1400401_47 = "不錯欸！下次連它一起點了！",
  str_voice_1400401_48 = "這個超棒、超好玩！暫時收起來！",
  str_voice_1400401_49 = "話說回來有一次我差點把紅油扳手的老家炸了……哇，別緊張！那只是意外而已啦！雖然我還蠻喜歡那次的效果……",
  str_voice_1400401_50 = "無聊的事情，討厭的傢伙？就把他們都砰砰砰！砰！啪～就好了嘛～你說是吧？",
  str_voice_1400401_51 = "我老家在硝石礦脈那邊，負責專門的研究，會幫大家好多忙！啊，不過我現在幹的事也一樣啦～爆破嘛～",
  str_voice_1400401_52 = "白夜極光！砰！",
  str_voice_1400401_53 = "砰！快出來！",
  str_voice_1400401_54 = "你看見床頭的煙火了沒～",
  str_voice_1400401_55 = "哼哼～我剛炸了一場～",
  str_voice_1400401_56 = "快出來快出來！",
  str_voice_1400401_57 = "新年就是要爆炸！",
  str_voice_1400411_1 = "為人熱情是我的職業習慣，希望您不會反感。這邊請。",
  str_voice_1400411_2 = "總覺得身後的這面牆上缺了什麼，我知道了！是《吊橋上的女人》的現代復刻。",
  str_voice_1400411_3 = "天鵝湖、王族教堂、拉赫半山吊塔……我們該從哪裡開始介紹呢？",
  str_voice_1400411_4 = "整座白夜城都在我的心中，我對每一個街區如數家珍，我對每一粒微塵充滿敬意。",
  str_voice_1400411_5 = "優雅女士的祕訣？就藏在我的行李箱裡喔。可不要隨便打開，這些都是女士的小祕密呢。",
  str_voice_1400411_6 = "走過光明的大道，再和黎明前的黑暗擦身而過。我是紅，也是白，歡迎來到白夜！",
  str_voice_1400411_7 = "有一綹頭髮沒有綁到？真是失禮了，即使是二十四小時工作也應該保持優雅。",
  str_voice_1400411_8 = "紅女士？好懷念啊。有時候回想起以前的日子，覺得還挺不可思議的～",
  str_voice_1400411_9 = "過去我一直作為一名參與者，親身經歷白夜城發生的一切。不過現在我覺得自己是一名旁觀者了。",
  str_voice_1400411_10 = "您也會抓住機會休息呀。我其實也是，要忙裡偷閒嘛。來杯咖啡嗎？特調的。",
  str_voice_1400411_11 = "這裡的一切我都瞭若指掌。說吧，想去哪裡看看？",
  str_voice_1400411_12 = "嗯，這香草的氣息，獨特的風味，果然還是咖啡好啊～",
  str_voice_1400411_13 = "身為職業女子，行坐端正、儀容得體是必備的修養。",
  str_voice_1400411_14 = "需要私人導遊嗎？在白夜之下，是否有您想去的地方？",
  str_voice_1400411_15 = "生日快樂！為您的誕辰獻上祝福。那麼，由我來帶您去慶祝的地方吧。",
  str_voice_1400411_16 = "今天由我來招待您！獻上最誠摯的微笑。",
  str_voice_1400411_17 = "早安，一切已準備就緒，您隨時可以出發。",
  str_voice_1400411_18 = "我的職責還在進行中，來，這邊請。",
  str_voice_1400411_19 = "請勿擔心，我偶爾也會成為黑暗中的引路人。",
  str_voice_1400411_20 = "我已看見白夜的指引升起，從今往後，守望那片土地就夠了。",
  str_voice_1400411_21 = "真理沒有引路者，那些追求之人，就如同患著名為心盲的病症。",
  str_voice_1400411_22 = "白夜至上。",
  str_voice_1400411_23 = "導遊與戰士，各自指向不同的路徑。我會為他們指引最適合的明路。",
  str_voice_1400411_24 = "城主大人對白夜城的忠心，便是效力之人能得到的最好回報。",
  str_voice_1400411_25 = "能夠與那位夫人享有同樣的家族榮譽，我十分榮幸。",
  str_voice_1400411_26 = "向您介紹，在每日的咖啡與紅茶中所蘊含的穩定與秩序。",
  str_voice_1400411_27 = "希望您能遠離不守秩序的人，當然，還有破壞秩序的東西。",
  str_voice_1400411_28 = "我曾聽說關於您和巨像的傳聞，得以一見，我很榮幸。",
  str_voice_1400411_29 = "您找不到路嗎？有我在，不用擔心。",
  str_voice_1400411_30 = "導航地圖擴大了。",
  str_voice_1400411_31 = "我是高牆下的引路人。",
  str_voice_1400411_32 = "我是迷霧中的指路者。",
  str_voice_1400411_33 = "我是潔白之城的真顏。",
  str_voice_1400411_34 = "是缺導遊還是戰士？",
  str_voice_1400411_35 = "不聽話的旅客在哪裡？",
  str_voice_1400411_36 = "請盡情提問吧！",
  str_voice_1400411_37 = "請看、這就是名勝！",
  str_voice_1400411_38 = "各位，目的地到了！",
  str_voice_1400411_39 = "請保持隊伍整齊。",
  str_voice_1400411_40 = "請勿推擠。",
  str_voice_1400411_41 = "這次也是精緻的領隊呢！",
  str_voice_1400411_42 = "完全感覺不到疲累～",
  str_voice_1400411_43 = "啊——我誠摯地向您表示歉意……",
  str_voice_1400411_44 = "我已為各位在巨像上準備好座位。有什麼重要的事，您現在可以說了～",
  str_voice_1400411_45 = "該不會是辦公用品吧？……您的好意我領了。",
  str_voice_1400411_46 = "這確實是一名職業導遊的必備物品！",
  str_voice_1400411_47 = "一如往常，您的好意我心領了。",
  str_voice_1400411_48 = "太妙了！這正是一名優雅女士終生追求的！",
  str_voice_1400411_49 = "作為白夜城的引路人，我會盡到自己的職責，還請您集中精神，您一旦跟不上，就會迷失方向。",
  str_voice_1400411_50 = "我對白夜城的瞭解不只是因為熟悉，還有……一些難以忘懷的記憶。這座城市和它的居民一樣，都努力活著呢。",
  str_voice_1400411_51 = "我已經藏起當年的獠牙，現在只是單純享受這難得的安穩生活。不過女士還是很注重個人隱私的，所以答應我，不要多問～",
  str_voice_1400411_52 = "白夜極光。",
  str_voice_1400411_53 = "您好！",
  str_voice_1400411_54 = "早安，您準備好了嗎？",
  str_voice_1400411_55 = "午安，您是否休息夠了？",
  str_voice_1400411_56 = "白夜城的夜晚，也值得欣賞。",
  str_voice_1400411_57 = "新年快樂。祝福您，新年有新氣象。",
  str_voice_1400441_1 = "可以請妳先解釋一下為什麼沒有完成自己的工作嗎？就是在說妳，卓婭！",
  str_voice_1400441_2 = "給大元帥的報告裡不允許有這麼多錯誤！天哪，為什麼現在才發現……",
  str_voice_1400441_3 = "居里，去和大家打招呼吧！這孩子以前沒有那麼害羞的。",
  str_voice_1400441_4 = "動作標準！身手要快！啊啊啊？不好意思，剛剛不是在說你！",
  str_voice_1400441_5 = "死線是很多人工作的原動力！果然不能放任大家的壞習慣嗎……",
  str_voice_1400441_6 = "請不用擔心！雖然工作更加複雜了，但是我處理事務也更加熟練了，一定能完成的！",
  str_voice_1400441_7 = "請交給我吧，身為參謀人員，這些本來就是我的工作。",
  str_voice_1400441_8 = "好啊……那你可以和我一起制定計劃嗎？不會佔用太多時間的！",
  str_voice_1400441_9 = "啟光是我的家，我熟悉那裡的一草一木，現在這裡也是了……",
  str_voice_1400441_10 = "動力的情況如何？今日的檢查路線是這樣的……嗯，現在是她的輪值時間，晚上還要寫總結……",
  str_voice_1400441_11 = "又要回到紙、筆和打字機面前了嗎？",
  str_voice_1400441_12 = "請加油吧！每分每秒都很重要，我會盡量幫助你的！",
  str_voice_1400441_13 = "有沒有興趣改良一下房屋佈局呢？這能大大提升工作效率喔。",
  str_voice_1400441_14 = "雖然計劃定好了，但是也要有人實施才行呢，不能鬆懈～",
  str_voice_1400441_15 = "要適時休息喔～今天就休息吧，以及，生日快樂～",
  str_voice_1400441_16 = "有看到偷懶的傢伙嗎？有的話一定要告訴我喔。",
  str_voice_1400441_17 = "早安！就由我來安排這些吧，不會很麻煩的。",
  str_voice_1400441_18 = "按照計劃來看，應該快到休息時間了呢～",
  str_voice_1400441_19 = "現在不是休息的時候，計劃似乎有點小紕漏，我還是應該檢查一下……",
  str_voice_1400441_20 = "啟光的一切都井然有序，看著大家按照計劃進行工作，太愉快了！",
  str_voice_1400441_21 = "四處橫行，漫無目的，紅油扳手是怎麼活到現在的……",
  str_voice_1400441_22 = "為了啟明之光！",
  str_voice_1400441_23 = "沒有計劃的牠們，就是烏合之眾而已。",
  str_voice_1400441_24 = "不論是身為戰士還是參謀都要加倍努力，才能讓大元帥更加信任我。",
  str_voice_1400441_25 = "雖然……雷霆有取代大元帥的野心，但她是不會用陰險招數的！",
  str_voice_1400441_26 = "看到計劃書上「已執行」一欄中打了一堆勾……整個人都輕快許多了呢。",
  str_voice_1400441_27 = "什麼事都要按照計劃執行！不能承諾了又沒達成！",
  str_voice_1400441_28 = "要管理這麼大的傢伙，究竟需要什麼樣的組織系統呢……",
  str_voice_1400441_29 = "你好，薇薇安會負責所有細節！請相信啟光的管理能力，畢竟我們這裡可是另類的修羅場……",
  str_voice_1400441_30 = "欸？居里是不是長大了一點……",
  str_voice_1400441_31 = "居里！蛻變吧！",
  str_voice_1400441_32 = "驚雷將響徹不止！",
  str_voice_1400441_33 = "化身刺破雷雲的閃光！",
  str_voice_1400441_34 = "大家請看我這邊！",
  str_voice_1400441_35 = "我的電光正走遍全身！",
  str_voice_1400441_36 = "計劃完整，準備完畢！",
  str_voice_1400441_37 = "將雷閃注入疾光！",
  str_voice_1400441_38 = "鐳擊！以大地為導體！！",
  str_voice_1400441_39 = "出鞘！",
  str_voice_1400441_40 = "細刃！接招！",
  str_voice_1400441_41 = "讓我為大家制定一個必勝計劃吧～",
  str_voice_1400441_42 = "完成了計劃！勝利手到擒來！",
  str_voice_1400441_43 = "如果不按照計畫行事是不可能成功的……",
  str_voice_1400441_44 = "有需要更新的新資訊嗎？",
  str_voice_1400441_45 = "我可以當成是辛勤工作的獎勵吧？",
  str_voice_1400441_46 = "太好了，居里也會喜歡的！",
  str_voice_1400441_47 = "這個很貴吧？沒有超出預算嗎？",
  str_voice_1400441_48 = "太感謝你了！我很早就想要這個了！",
  str_voice_1400441_49 = "對於我來說，或許地下城很寬敞，但是居里屬於地上的世界，她嚮往蔚藍的天空。",
  str_voice_1400441_50 = "如果我不屬於啟光，我一定會是一個勇敢的冒險家，行走在戈壁、祕境，還有舊都！",
  str_voice_1400441_51 = "我出身的地方並不是迦南城，而是屬於啟光聯邦的一座小城鎮，可是……它被毀了。",
  str_voice_1400441_52 = "白夜極光。",
  str_voice_1400441_53 = "你好！",
  str_voice_1400441_54 = "早安啊！你在嗎？",
  str_voice_1400441_55 = "午安，不知你是否有時間？",
  str_voice_1400441_56 = "晚安，不知道是否打擾到你了？",
  str_voice_1400441_57 = "祝賀，新年快樂！",
  str_voice_1400451_1 = "我相信唯一真理，光與暗是真理的形狀……毀滅到來時，引導庶民由腐朽走向新生……",
  str_voice_1400451_2 = "帶走我腐爛的皮膚，帶走我骯髒的血液，帶走我無知的意識……",
  str_voice_1400451_3 = "紅色聖釘與我的血液融為一體。十字尖錘不僅會審判敵人，還直指……我的心臟……",
  str_voice_1400451_4 = "啊……血液正在流失，多麼痛苦，多麼絕望，這是我應背負的苦難……唯有如此才能獲得救贖。",
  str_voice_1400451_5 = "世間一切都是罪孽，我有罪，我贖罪……無論維多利亞大人下達什麼樣的命令，都應無異議、無條件、無反抗地執行。",
  str_voice_1400451_6 = "死亡不是終結，而是改變……痛苦不是折磨，而是救贖。",
  str_voice_1400451_7 = "不要害怕，這枚聖釘是為我準備的。您看，就像這樣……",
  str_voice_1400451_8 = "「我對真理懺悔……惡業、愚迷、驕狂皆為我罪……。」啊，我在懺悔……有興趣嗎？要一起懺悔嗎？",
  str_voice_1400451_9 = "這世界上要是只有我一個人如此痛苦、如此不安、如此無助就好了……可是您顯然也體會到同樣的絕望。",
  str_voice_1400451_10 = "安靜地待在這？沒有問題……只要您需要……要我做任何事情都可以……",
  str_voice_1400451_11 = "這也是一種修行嗎？還是……懲罰嗎？",
  str_voice_1400451_12 = "我的血肉正遭到啃食，我的靈魂正受到撕咬，啊……這正是幸福的前兆。",
  str_voice_1400451_13 = "這條教義沒有背熟……我應該抄寫一千遍……",
  str_voice_1400451_14 = "我懺悔……契法對維多利亞大人實在是不敬，我攻擊她了……我有罪。",
  str_voice_1400451_15 = "我的誕生是罪過，但您卻是世界的寶物……祝賀您。",
  str_voice_1400451_16 = "陽光正在刺痛我，可是我必須忍受……",
  str_voice_1400451_17 = "您好，您想瞭解一下真理結社嗎？……為什麼要跑呢？啊，我還在流血……",
  str_voice_1400451_18 = "今天的懲罰還剩一半沒有完成。",
  str_voice_1400451_19 = "只有此刻，被黑暗擁抱的此刻，被渺小感受淹沒的此刻，才令人安心。",
  str_voice_1400451_20 = "真理結社是我的歸宿、我的終點、我的……家……",
  str_voice_1400451_21 = "我雖然託生於那個地方，但卻並不屬於那裡，那是我人生的劫難。",
  str_voice_1400451_22 = "願真理祝福您。",
  str_voice_1400451_23 = "暗鬼，只需要一點血液……就可以將牠們消滅殆盡……",
  str_voice_1400451_24 = "維多利亞大人，請寬恕我的罪，我是個骯髒的怪物……",
  str_voice_1400451_25 = "我曾問浮士德，「白箱」能給予我解脫嗎？他說時機未到。",
  str_voice_1400451_26 = "教義、懺悔、救贖都讓我安心……還有白色方糖……",
  str_voice_1400451_27 = "忤逆維多利亞大人的傢伙，必須撕碎，必須斬殺……",
  str_voice_1400451_28 = "十分舒適……令人不安……如果能在裡面蓋一間懺悔室就好了……",
  str_voice_1400451_29 = "忠於結社、忠於信念、忠於維多利亞大人，我將牢不可破的誓言釘入身體……懺悔吧！即使是怪物也能獲得救贖。",
  str_voice_1400451_30 = "鞭笞我、憐愛我……",
  str_voice_1400451_31 = "我的血液是污穢的……請寬恕我……",
  str_voice_1400451_32 = "如果可以用這罪惡之血清洗世界。",
  str_voice_1400451_33 = "虔誠會為我指引方向……",
  str_voice_1400451_34 = "如您所願……",
  str_voice_1400451_35 = "我已做好準備。",
  str_voice_1400451_36 = "痛苦是罪惡的救贖。",
  str_voice_1400451_37 = "我會奉獻……我的一切……",
  str_voice_1400451_38 = "我會犧牲……我的所有……",
  str_voice_1400451_39 = "滾燙的……",
  str_voice_1400451_40 = "骯髒、卑劣的……",
  str_voice_1400451_41 = "真理會寬恕我，對嗎？",
  str_voice_1400451_42 = "朝聖之路就在前方……這是第一步。",
  str_voice_1400451_43 = "啊……我是悲傷的怪物，我是羸弱的怪物……",
  str_voice_1400451_44 = "迷茫？那就懺悔吧……",
  str_voice_1400451_45 = "……不配…",
  str_voice_1400451_46 = "不該如此……",
  str_voice_1400451_47 = "真的要這樣嗎……",
  str_voice_1400451_48 = "謝謝……",
  str_voice_1400451_49 = "他們曾保護我、尊敬我，將我捧上神壇；也曾傷害我、厭棄我，將我逼入無盡的深淵。",
  str_voice_1400451_50 = "暗鬼會傷害光靈，光靈亦會傷害光靈……我既不是暗鬼也不是光靈，我只是怪物，卑劣又無助的怪物。",
  str_voice_1400451_51 = "真理結社是我唯一的容身之所……我不必理解，不必思考，只要接受真理的引導，然後前進就夠了。",
  str_voice_1400451_52 = "白夜極光。",
  str_voice_1400451_53 = "您好……",
  str_voice_1400451_54 = "清晨……如期降臨。",
  str_voice_1400451_55 = "您為何，不出現？",
  str_voice_1400451_56 = "我在等待，夜晚的懲罰……",
  str_voice_1400451_57 = "新年，便是恩賜。",
  str_voice_1400481_1 = "那些人說什麼影鎮人對白夜城的建設沒有貢獻？要是早個幾年，那些傢伙的嘴早就爛了。",
  str_voice_1400481_2 = "怕痛的話趁早還是離開吧？我得把主要心力放在知更身上，你得自己照顧好自己。",
  str_voice_1400481_3 = "你最近有跟知更一起活動嗎？也是，那傢伙會理人才怪。",
  str_voice_1400481_4 = "我尊重底層的人，因為我曾是、也依然是其中的一員。可有些傢伙總是不懂這個道理……",
  str_voice_1400481_5 = "我已經不是從前那個莽撞又弱小的流浪漢了——現在的我，不是那麼簡單就能打倒的。",
  str_voice_1400481_6 = "暗鬼、天災、強盜……在這世間，不知道什麼時候刀刃就會架到脖子上。但既然已經走上無法回頭的路，我就永遠不會後悔。",
  str_voice_1400481_7 = "哎唷哎唷，我還一直以為你是那種最無聊的傢伙呢。現在你至少比他們多了幾分幽默。",
  str_voice_1400481_8 = "你是個了不起的傢伙，但「帝王」和「賢君」不可能長久共存，你只能擇一。我建議你學學我們的影主。",
  str_voice_1400481_9 = "很好，我們原則上認同你的行事方式。我們甚至有一些共同點，真有意思。有考慮過加入影鎮嗎？",
  str_voice_1400481_10 = "平常只會教訓我，但看看你現在不也是一副吊兒郎當的樣子。啊啊，果然天下烏鴉一般黑。",
  str_voice_1400481_11 = "哈？讓我看場子？這算什麼？",
  str_voice_1400481_12 = "衣服送去乾洗了，連衣服都整理不好的菜鳥不值得信賴。",
  str_voice_1400481_13 = "再怎麼說老、啊不，我也是個女生嘛……還是有羞恥心的，嘿。",
  str_voice_1400481_14 = "被任何一絲情感左右的瞬間都會釀成致命的危險——知更例外。",
  str_voice_1400481_15 = "好好享受，畢竟沒人知道下一個生日會變成什麼樣子。",
  str_voice_1400481_16 = "唷，拆船工！",
  str_voice_1400481_17 = "開工，開工。守時是專業的表現，一分不多，一秒不少。",
  str_voice_1400481_18 = "知更呢？我已經八分鐘沒有看見她了。知更呢？知更！",
  str_voice_1400481_19 = "按照合約，現在是下班時間了，但是還要加班，商會長這個奸商！",
  str_voice_1400481_20 = "弱者別因為好奇心而加入幫派，最後會被啃得連骨頭都不剩。",
  str_voice_1400481_21 = "只要給錢，依照程序辦事，白夜城也好，紅油扳手也好，隨他們。",
  str_voice_1400481_22 = "影子在注視著你。",
  str_voice_1400481_23 = "我恨不得咬碎那些暗鬼，將牠們撕成一片一片，但又必須保持理智。",
  str_voice_1400481_24 = "誇誇知更？你在開玩笑嗎！三十個字根本不夠我講！",
  str_voice_1400481_25 = "商會長吝嗇得很，簡直一毛不拔，但有時候又大方得不可思議。",
  str_voice_1400481_26 = "喜歡什麼？知更啊，除了知更還能是什麼？",
  str_voice_1400481_27 = "不長眼的笨蛋，不專業的同僚，不敢拼的懦夫，每一個都是噩夢。",
  str_voice_1400481_28 = "得想辦法把他拉到影鎮去……怎麼樣，拆船工，做個交易嗎？",
  str_voice_1400481_29 = "喂，需要幫手嗎？臨時的喔，我在商會還有正當工作。速戰速決吧，要解決掉誰？",
  str_voice_1400481_30 = "手裡的傢伙愈來愈順手了呢。",
  str_voice_1400481_31 = "力量再次匯聚。",
  str_voice_1400481_32 = "知更！從現在開始，沒有人能再欺負我們了！",
  str_voice_1400481_33 = "賭上「烈雀」之名，鳥兒們必將高飛。",
  str_voice_1400481_34 = "不錯，那我就陪你打打看。",
  str_voice_1400481_35 = "刀刃已經打磨好了。",
  str_voice_1400481_36 = "早就不耐煩了……",
  str_voice_1400481_37 = "可別求饒啊！",
  str_voice_1400481_38 = "害怕的話就閉上眼睛！",
  str_voice_1400481_39 = "解決你只要五秒。",
  str_voice_1400481_40 = "現在就讓你安息。",
  str_voice_1400481_41 = "打架了，拖油瓶們！知更呢？",
  str_voice_1400481_42 = "這種勝利，我早就習慣了！對不對，知更？",
  str_voice_1400481_43 = "下次要是害知更也遇上這種事，我一定饒不了你……",
  str_voice_1400481_44 = "沒問題！我會奉陪到最後！",
  str_voice_1400481_45 = "我先收下，但如果是什麼奇怪的東西就揍你！",
  str_voice_1400481_46 = "居然是……你怎麼會知道，巧合嗎？",
  str_voice_1400481_47 = "不錯嘛，珍品，你很有經商的眼光。",
  str_voice_1400481_48 = "被人這麼放在心上，我都變得不像自己了……",
  str_voice_1400481_49 = "我和知更都經歷過那個戰爭時代，然而因戰爭而產生的殘暴陋習才是我們需要警惕的事，它讓人貪婪，踐踏尊嚴和生命。",
  str_voice_1400481_50 = "「我們終會成為他們……」多麼慰藉人心啊，就好像飢餓與歧視真的會消失一樣。只有天真的孩童會這麼認為。",
  str_voice_1400481_51 = "對於至親，滴水之恩、湧泉相報；對於敵人，以牙還牙、以眼還眼。我和知更終於可以不再依附他人生存，但我們也不會忘記「朋友」以及「兄弟」為我們付出的一切。",
  str_voice_1400481_52 = "白夜極光。",
  str_voice_1400481_53 = "拆船工！",
  str_voice_1400481_54 = "早呀！清醒了沒？",
  str_voice_1400481_55 = "找你呢，人呢？",
  str_voice_1400481_56 = "喔！晚安啊。",
  str_voice_1400481_57 = "來慶祝吧，難得的新年。",
  str_voice_1400541_1 = "如果說什麼飲料最好喝，那就是結束一天的工作後，去時常光顧的店中接過一杯免費冷飲～",
  str_voice_1400541_2 = "只有穿了筆挺的制服，才會讓人有認真工作、執行使命的感覺！因此要每天熨燙～",
  str_voice_1400541_3 = "生活會賜予我們很多東西。一定要認真對待，不論搞砸多少事，都要有重來的勇氣！",
  str_voice_1400541_4 = "如果能每天努力一點，將來一定能成為很棒的人，就像卡蓮隊長那樣，雷厲風行，完美可靠。",
  str_voice_1400541_5 = "要什麼時候才能被城主大人認可呢……總之先去修好那些我不小心打壞的路燈吧。",
  str_voice_1400541_6 = "支撐不下去時，看著這盞提燈就能產生信心，這並不奇怪，您湊過來，眼神穿過燈光，您也會看見。",
  str_voice_1400541_7 = "認真是騎士精神的一種，持續實踐，就能獲得榮譽。可惜，白夜城的大貴族們並不懂。",
  str_voice_1400541_8 = "有人說我太過認真。就像我手中這量尺，弧是弧、直是直，您認為呢？……啊？真的是這樣？",
  str_voice_1400541_9 = "我……並不瞭解公爵大人為何給我如此重要的職位，難道是因為我重新繪製了那些地圖嗎？",
  str_voice_1400541_10 = "啊哈哈，我在思考接下來的工作該怎麼進行，沒有在發呆啦！",
  str_voice_1400541_11 = "工作就是生命，這可不是單純求溫飽，而是崇高的使命！",
  str_voice_1400541_12 = "一旦工作就要打起精神來，否則說不定就會搞砸什麼，加油吧！",
  str_voice_1400541_13 = "要怎麼培養專注力呢？您知道更好的方法嗎？",
  str_voice_1400541_14 = "記憶力好還不如做記錄，因此紙和筆要隨身攜帶……等等，我回去拿一下。",
  str_voice_1400541_15 = "生日快樂！本、本來想送點什麼，但是這個月手頭太緊了！下次一定送！",
  str_voice_1400541_16 = "正在值班，看來今天一切安好，巨像也很穩定，暫時不會掉下去。",
  str_voice_1400541_17 = "要打起精神來！上班了！",
  str_voice_1400541_18 = "又是平安無事的一天……可喜可賀。",
  str_voice_1400541_19 = "啊！我在值班！……請您看我的眼神，我是絕對不會打瞌睡的。",
  str_voice_1400541_20 = "白夜城能成為大陸第一城市，全仰賴它所堅持的騎士精神。",
  str_voice_1400541_21 = "聽說啟光聯邦內部有一套執行良好的政務規則，如果能用在白夜城……",
  str_voice_1400541_22 = "白夜至上！",
  str_voice_1400541_23 = "暗鬼是永遠的敵人，只要見到，就一定要殲滅！",
  str_voice_1400541_24 = "……呵呵，聽說白夜城的城區又被四天使摧毀了，地圖又要重畫了……呵呵……",
  str_voice_1400541_25 = "城主大人對於政務很細心，為了讓他偶爾能休息，我會努力。",
  str_voice_1400541_26 = "我喜歡認真的人，尤其是那些認真工作、充滿專注的感覺～",
  str_voice_1400541_27 = "如果白夜城走向衰敗，一定是那些大貴族們所為……",
  str_voice_1400541_28 = "這裡可真大，簡直是座小白夜城，而且還浮在空中……",
  str_voice_1400541_29 = "生活給您的所有，都是恩賜。我是娜汀，用手中的提燈照亮白夜城的人。",
  str_voice_1400541_30 = "燈，更加明亮了。",
  str_voice_1400541_31 = "提燈就能擊敗敵人。",
  str_voice_1400541_32 = "提燈之光，照亮長夜。",
  str_voice_1400541_33 = "我終於……可以守衛長夜了。",
  str_voice_1400541_34 = "拜託了！",
  str_voice_1400541_35 = "光，匯聚……",
  str_voice_1400541_36 = "提燈已亮。",
  str_voice_1400541_37 = "光明！常駐！",
  str_voice_1400541_38 = "在提燈之光下！",
  str_voice_1400541_39 = "請治癒我們！",
  str_voice_1400541_40 = "光！擊敗敵人！",
  str_voice_1400541_41 = "請跟隨這盞提燈。",
  str_voice_1400541_42 = "白夜永恆！",
  str_voice_1400541_43 = "提燈黯淡……",
  str_voice_1400541_44 = "新的地方，需要學習新東西呢。",
  str_voice_1400541_45 = "多謝您的禮物。",
  str_voice_1400541_46 = "哇，這個好！謝謝您！",
  str_voice_1400541_47 = "我真的可以收下嗎！？",
  str_voice_1400541_48 = "我會回送您的！一定！",
  str_voice_1400541_49 = "我是個普通人，我能做到的就是發揮普通人所具有的天賦——認真、努力和專注。",
  str_voice_1400541_50 = "騎士應該守口如瓶，無論是好的消息，還是負面的訊息，統統要收於內心，不可隨口亂說。",
  str_voice_1400541_51 = "白夜城中也有陰影，因此便有了守夜人……啊，那只是傳說啦，或許吧，或許。",
  str_voice_1400541_52 = "白夜極光！",
  str_voice_1400541_53 = "您好！",
  str_voice_1400541_54 = "早安！",
  str_voice_1400541_55 = "請問您在忙嗎？",
  str_voice_1400541_56 = "請問您休息了嗎？",
  str_voice_1400541_57 = "祝您新年快樂！",
  str_voice_1400571_1 = "欸～～菲莉詩的毛看起來亂亂的嗎？因為梳理起來很麻煩呀。不過摸起來手感很好喔！要不要摸摸看？",
  str_voice_1400571_2 = "情報部的工作繁瑣又細緻，真的好麻煩唷～～但也有好處唷。比如，我告訴你薇絲的祕密，你給我小魚乾～～",
  str_voice_1400571_3 = "不行呀～～硬是要求我做的話，我絕對不會去做。因為我不喜歡和大家做一樣的事，貓咪不是都這樣嗎？",
  str_voice_1400571_4 = "怎麼辦呀，菲莉詩好像又變得更厲害了，傷腦筋。",
  str_voice_1400571_5 = "菲莉詩很弱小，但尤彌很強大。尤彌一直保護著菲莉詩，雖然……我們無法見面，但我知道。",
  str_voice_1400571_6 = "睡吧，睡吧，菲莉詩。當妳醒來，會看到好多好多的小魚乾堆滿休息室喵，沒有暗鬼喵，也沒有日蝕喵。",
  str_voice_1400571_7 = "嗯？菲莉詩的心理報告上寫著有關尤彌的內容和菲莉詩愛睡覺的事，欸～～人家知道的啦～人家是貓貓嘛～",
  str_voice_1400571_8 = "這種廉價的魚罐頭也想收買我！？還有這——麼便宜的魚子醬。你一定是在開玩笑！",
  str_voice_1400571_9 = "啊……剛才尤彌出現了嗎？尤彌是個孤獨的孩子，如果碰到她，請溫柔對待她吧。菲莉詩怎樣都無所謂啦～～",
  str_voice_1400571_10 = "燈光暖呼呼的，溫度非常適宜，環境條件完美，好懶喔——什喵都不想做。",
  str_voice_1400571_11 = "雖然不是不行，可是又有麻煩事來找我了喵。",
  str_voice_1400571_12 = "請問你看見我的帽子了嗎喵？哎呀呀，我又忘記了喵～",
  str_voice_1400571_13 = "保持衛生很關鍵喵。一定要勤洗手勤漱口，如果能保持距離就更好了喵。",
  str_voice_1400571_14 = "來，現在是慾望的謎題喵，猜猜看我想要什麼喵？",
  str_voice_1400571_15 = "欸～～你想聽菲莉詩唱生日快樂歌喵？只唱一句喔。祝你生日快樂～～",
  str_voice_1400571_16 = "午後的時間多麼美妙，要是能睡一會就好了喵。欸？我可沒想偷懶喵～～",
  str_voice_1400571_17 = "喵？沒見識過起床氣嗎喵？薇薇安竟然一口氣幫我設定了十個鬧鈴，可惡喵。",
  str_voice_1400571_18 = "又到了日常匯報的時間了喵，可是菲莉詩還什喵都沒有做呢～～",
  str_voice_1400571_19 = "好睏……已經撐不住了喵……呼、呼，叭嘰叭嘰，好多好多的魚喵……",
  str_voice_1400571_20 = "啟光的大家對待工作都太認真刻板了喵，偶爾也應該偷懶喵一下～～",
  str_voice_1400571_21 = "我很羨慕有翅膀的生物喵，特別是那些輕盈的羽毛，呵呵～～",
  str_voice_1400571_22 = "那就為了啟明之光喵～～",
  str_voice_1400571_23 = "暗鬼呀，臭臭喵，不太注意個人衛生呢喵。",
  str_voice_1400571_24 = "噓，小聲一點～～薇薇安長官睡著啦，果然工作太累了喵。",
  str_voice_1400571_25 = "希羅娜長官的尾巴……不是玩具。可是，根本忍不住喵！",
  str_voice_1400571_26 = "只偷偷給你看一下喵！傳說中的金色小魚乾，這可是菲莉詩的寶貝喵！",
  str_voice_1400571_27 = "什、什喵，要跑八百公尺？菲莉詩絕對做不到，一百公尺都做不到喵。",
  str_voice_1400571_28 = "好大呀，可以也幫菲莉詩佈置一個房間喵？菲莉詩要在地上全鋪上軟軟的毯子喵～～",
  str_voice_1400571_29 = "欸？自我介紹，不要喵，好麻煩。菲莉詩現在只想好好的睡一覺喵，昨天晚上又工作到半夜呢，已經撐不住了喵，呼嚕嚕～～",
  str_voice_1400571_30 = "喵嗚嗚～～菲莉詩又變強了～",
  str_voice_1400571_31 = "有沒有什麼偷懶的辦法喵？",
  str_voice_1400571_32 = "想要輕快的步伐，想聽另一種聲音～",
  str_voice_1400571_33 = "美麗的夢要開始了喵，讓菲莉詩睡一會喵。",
  str_voice_1400571_34 = "哈欠……要開始了喵？",
  str_voice_1400571_35 = "突然間變得好睏。",
  str_voice_1400571_36 = "唔，眼皮在打架。",
  str_voice_1400571_37 = "喵——站住，不准動，讓我休息一下喵～",
  str_voice_1400571_38 = "喵——你們，真是蠢死了喵。",
  str_voice_1400571_39 = "弄完就休息～",
  str_voice_1400571_40 = "到此為止喵！",
  str_voice_1400571_41 = "知道啦～知道啦～",
  str_voice_1400571_42 = "欸？幹掉了呀～",
  str_voice_1400571_43 = "哎呀，失敗了呢～",
  str_voice_1400571_44 = "啊～好想睡一下呀～",
  str_voice_1400571_45 = "嗯，啊，讓菲莉詩睡一下喵～",
  str_voice_1400571_46 = "喵？尤彌也有份嗎？太好了！",
  str_voice_1400571_47 = "欸？要感謝你嗎，那就謝謝？",
  str_voice_1400571_48 = "喵！我們想要這個很久了，太好了喵~",
  str_voice_1400571_49 = "就算是用力地祈願，用力地加油，又能實現什麼呢？菲莉詩覺得呢，還不如睡覺喵～",
  str_voice_1400571_50 = "菲莉詩，也會有小小的願望喵……曾與我一同前行的那隻貓貓，我只希望，牠能回來就好了喵。",
  str_voice_1400571_51 = "只要菲莉詩希望，尤彌會永遠是尤彌，讓她遠離痛苦，讓她實現願望……喵，除了相見。",
  str_voice_1400571_52 = "白夜極光喵～～",
  str_voice_1400571_53 = "喵～",
  str_voice_1400571_54 = "嗚～～菲莉詩被吵醒了喵……",
  str_voice_1400571_55 = "小魚乾～小魚乾～",
  str_voice_1400571_56 = "煩死了喵！你人呢！",
  str_voice_1400571_57 = "哈～新年了喵？",
  str_voice_1400681_1 = "像我這麼勇猛的人，才不會使用裝死這種技倆呢……小時候的事情能比較嗎？當、然、不、能！",
  str_voice_1400681_2 = "醒山那種粗魯的大個，他如果想抓你，你就用力踢他膝蓋，超級管用，就像這樣，嘿！",
  str_voice_1400681_3 = "荒漠要嘛暴熱，要嘛超冷，像你這種沒有羽毛的傢伙，根本活不了三天吧？嘖嘖嘖……",
  str_voice_1400681_4 = "為什麼我這麼執著於「風速」？看見我短小有力的翅膀沒？不懂嗎？那就再看看！靠近一點，來！",
  str_voice_1400681_5 = "旅行三件組——隔熱防冷超輕羽毛套裝、酷斃了防風鏡、高科技噴射背包，厲害吧！",
  str_voice_1400681_6 = "危險也沒關係，途中可以轉彎，也可以逃走！最重要的是能飛出第一公尺，最重要的是勇於挑戰！",
  str_voice_1400681_7 = "喔呀？你想摸摸我翅膀嗎？來來來，不怕被翅膀搧的話你就摸呀！怕什麼，頂多被搧到昏迷而已～",
  str_voice_1400681_8 = "來來，你過來點，不要怕……我想對你幹嘛？難道不是想幹嘛就幹嘛嗎？你以為你能反抗嗎？嘿嘿！",
  str_voice_1400681_9 = "不要怕，跟著我大搖大擺地往前走！誰欺負你我就教訓誰！……嘿，至於我，我和你關係好嘛～",
  str_voice_1400681_10 = "無聊得我都快掉毛了，快陪我動一下！什麼？動起來掉的毛和閒到掉的毛能比較嗎？",
  str_voice_1400681_11 = "嗯，很有眼光，不愧是你！從現在開始這裡就是我的地盤了，哇哈哈！",
  str_voice_1400681_12 = "你轉過身去讓我看看吧？……果然沒有尾巴毛欸，不會覺得冷嗎？",
  str_voice_1400681_13 = "等我幫噴射背包充氣……怎麼充？吹啊！……吹完加燃料。",
  str_voice_1400681_14 = "怎麼迎敵？無論如何先衝出去呀，大不了衝到一半再轉彎嘛！",
  str_voice_1400681_15 = "今天是你生日呀？那等等喔……你看，我掉的一點羽毛，給你拿去玩呀～",
  str_voice_1400681_16 = "喔！終於回來啦！快打起精神、活動一下你那雙孱弱的雙手！",
  str_voice_1400681_17 = "醒了沒呀？來，我幫你搧幾下就清醒啦……幫你什麼？幫你膝蓋按摩！",
  str_voice_1400681_18 = "美味的～沙蟲乾、蜥蜴乾、蚯蚓乾，你也來一口吧？嘿，來嘛～",
  str_voice_1400681_19 = "睡不著嗎？我幫你搧一搧！……搧風啦，不要那麼緊張～",
  str_voice_1400681_20 = "嘿嘿，信使公會超酷的，雖然規模比較小，但什麼都能做唷！",
  str_voice_1400681_21 = "嘖嘖，收件人是紅油扳手的人又怎樣？還不是玩不到兩下就沒了～",
  str_voice_1400681_22 = "信使公會，使命必達！",
  str_voice_1400681_23 = "暗鬼很可怕嗎？嗯？只要牠們有膝蓋，我就是無敵的！",
  str_voice_1400681_24 = "多孚那傢伙，又放我鴿子，總有一天我要拔到她的羽毛！",
  str_voice_1400681_25 = "她聲音又大，又有「言靈」，送貨超快，羽毛也掉得超多，酷——",
  str_voice_1400681_26 = "我喜歡蒐集羽毛、風速飛行、還有瞄準膝蓋！",
  str_voice_1400681_27 = "我最——討厭黏糊糊的東西了，想到羽毛會黏到就……咿呀！",
  str_voice_1400681_28 = "巨像不是「言靈」嗎？有什麼差別呀？……喔，不是活的呀，奇怪。",
  str_voice_1400681_29 = "對！我就是荒漠上高速移動的橢圓導彈，人稱風速小螺旋，可愛又勇猛的信使——溫蒂！",
  str_voice_1400681_30 = "更快、更強、的我！",
  str_voice_1400681_31 = "哇喔——我真是酷斃了！",
  str_voice_1400681_32 = "小風變成小颶風！",
  str_voice_1400681_33 = "現在的我、挑戰這片大陸！",
  str_voice_1400681_34 = "要我放慢速度？",
  str_voice_1400681_35 = "風速準備好！",
  str_voice_1400681_36 = "風速讓你看！",
  str_voice_1400681_37 = "風速找地方降落！",
  str_voice_1400681_38 = "風速太多我也不知道叫什麼！",
  str_voice_1400681_39 = "風速踢腿！",
  str_voice_1400681_40 = "風速襲擊！",
  str_voice_1400681_41 = "風速出擊，跟得上我嗎？",
  str_voice_1400681_42 = "風速勝利，不愧是我！",
  str_voice_1400681_43 = "風、差一點就要裝死了喂！",
  str_voice_1400681_44 = "要叫我寄什麼？哪裡都行喔。",
  str_voice_1400681_45 = "給我東西幹嘛？要送貨？",
  str_voice_1400681_46 = "嘿嘿嘿，你這傢伙，很懂嘛～",
  str_voice_1400681_47 = "老樣子，收件人填我的名字？",
  str_voice_1400681_48 = "收到啦～喜歡的禮物～欸嘿​​！",
  str_voice_1400681_49 = "找收件人還不容易？荒漠上活著的傢伙就那麼多，一個個問就行啦……除非收件人掛了，哈哈。",
  str_voice_1400681_50 = "「言靈」通常都是被馴服的生物，我還沒有呢，要不隨便抓一隻算了？……嘿，你過來一點，別怕……",
  str_voice_1400681_51 = "看過黑壓壓的暗鬼嗎？我剛剛送貨的時候就看到了……沒辦法啦，速度快的小鳥早獨立，誰叫我這麼猛呢～",
  str_voice_1400681_52 = "白夜極光！",
  str_voice_1400681_53 = "我馬上去找你！",
  str_voice_1400681_54 = "你還睏嗎？",
  str_voice_1400681_55 = "快來！風速快來！",
  str_voice_1400681_56 = "我去找你～不要緊張～",
  str_voice_1400681_57 = "唷呼！新年快樂！",
  str_voice_1400831_1 = "疑問解答，翻譯轉換，回覆：莉莉姆是莉莉的複製體，非機械，而是女僕。",
  str_voice_1400831_2 = "解答：一號發言模式程式化。翻譯轉換：只是因為一號的個性比較死板而已。",
  str_voice_1400831_3 = "翻譯轉換：請將一號當成普通的女僕分配工作，請將二號當成不認真工作的女僕分配大量工作。",
  str_voice_1400831_4 = "資訊公開：莉莉姆已安裝個性化程式，具有固定思考模式，根據判斷權限，允許省略。",
  str_voice_1400831_5 = "資訊公開：一號，判斷權限等級一，保密等級三，資料庫等級三，進化鎖等級二。",
  str_voice_1400831_6 = "-介紹：莉莉姆二號，資料庫等級四，進化鎖等級一。\n-翻譯：有點傻，不長進。",
  str_voice_1400831_7 = "翻譯轉換：請勿擔心，一號受傷時可以治療，可以替換。",
  str_voice_1400831_8 = "資訊公開：莉莉姆擁有共識，最高指令為守護莉莉，次級指令為守護您。",
  str_voice_1400831_9 = "請勿驚訝，一號能依靠自身判斷省略個性化程式，進一步告白：一號希望與您深入交流。",
  str_voice_1400831_10 = "錯誤偵測……偵測完成，指令通過。莉莉姆將為您提供服務，請隨時吩咐。",
  str_voice_1400831_11 = "身分轉換，翻譯轉換：一號——「招牌女僕」，隨時歡迎客人來訪。",
  str_voice_1400831_12 = "眼神空洞，解答：一號會仔細保養眼睛，請勿擔心。",
  str_voice_1400831_13 = "一號已將房間清掃完畢，沒有留下一絲灰塵。",
  str_voice_1400831_14 = "自主說明：除了一號、二號以外，還有其他莉莉姆。",
  str_voice_1400831_15 = "0522執行：莉莉姆將為您慶祝生日，祝您生日快樂。",
  str_voice_1400831_16 = "歡迎回來，主人。陳述：紅茶已經準備好了。",
  str_voice_1400831_17 = "早安，主人。陳述：早餐已準備就緒。",
  str_voice_1400831_18 = "歡迎回來，主人。詢問：您選擇晚餐還是甜點？",
  str_voice_1400831_19 = "辛苦了，主人。詢問：您是否需要現在入浴？",
  str_voice_1400831_20 = "指令通過：三級判定為守護啟光，指令通過者——萊因哈特。",
  str_voice_1400831_21 = "指令驗證，通過，解鎖：莉莉姆四號，跟隨真理結社。",
  str_voice_1400831_22 = "為了，莉莉之光。",
  str_voice_1400831_23 = "解答：消滅命令，優先等級為四，擊退命令，優先等級為三。",
  str_voice_1400831_24 = "對象判定：狂熱的研究者，危險等級二，不可與她獨處。",
  str_voice_1400831_25 = "對象判定：白貓，有洩漏資料風險，危險等級二。",
  str_voice_1400831_26 = "解答：莉莉姆喜歡清潔活動和更加輕便的金屬裝備。",
  str_voice_1400831_27 = "判斷權限等級一，允許「討厭」，解答：一號討厭污垢。",
  str_voice_1400831_28 = "判定：感應到連接訊號，波長相似，追蹤，失敗，執行實體追蹤。",
  str_voice_1400831_29 = "指令驗證，通過。一號，身分轉換，女僕。主人，向您陳述：莉莉姆將成為守護您的力量。",
  str_voice_1400831_30 = "判定：能力增強。",
  str_voice_1400831_31 = "強化成功，權限升級。",
  str_voice_1400831_32 = "陳述：資料庫權限已解鎖。",
  str_voice_1400831_33 = "-介紹主人，莉莉。\n-二號，報到。",
  str_voice_1400831_34 = "身分轉換，執行者。",
  str_voice_1400831_35 = "攻擊，準備完畢。",
  str_voice_1400831_36 = "保險，解除。",
  str_voice_1400831_37 = "模式：區域排除。",
  str_voice_1400831_38 = "-指令：區域排除。\n-收到！",
  str_voice_1400831_39 = "模式：保護。",
  str_voice_1400831_40 = "模式：擊退。",
  str_voice_1400831_41 = "身分轉換，指揮者。",
  str_voice_1400831_42 = "報告，任務成功。",
  str_voice_1400831_43 = "報告，任務失敗。",
  str_voice_1400831_44 = "詢問：美好的一天，您有什麼需要？",
  str_voice_1400831_45 = "判斷：一般等級物品。",
  str_voice_1400831_46 = "一號代表，收下喜歡的禮物。",
  str_voice_1400831_47 = "發言美化，有些普通。",
  str_voice_1400831_48 = "一號，莉莉姆，喜歡您的禮物。",
  str_voice_1400831_49 = "陳述：莉莉姆作為女僕，能正常發言，但根據問卷，一號的發言模式受到顧客歡迎。",
  str_voice_1400831_50 = "資訊公開：一號剛甦醒時是普通的女僕，於28號地下城發現主人莉莉，解鎖最高指令。",
  str_voice_1400831_51 = "介紹：莉莉姆的共同點，程式、命令、不可篡改……翻譯，思考模式、使命、無法違抗。",
  str_voice_1400831_52 = "白夜極光。",
  str_voice_1400831_53 = "主人。",
  str_voice_1400831_54 = "早安，主人。",
  str_voice_1400831_55 = "請問您是否享用下午茶。",
  str_voice_1400831_56 = "翻譯轉換：莉莉姆需要您。",
  str_voice_1400831_57 = "謹賀，新年快樂，主人。",
  str_voice_1400861_1 = "禮儀之劍所造成的傷害都會轉為治癒他人的良藥，很諷刺，但也很真實，不是嗎？",
  str_voice_1400861_2 = "我偶爾會接受委託擔任葬禮司儀，送別逝者，安撫悲傷的親屬，也常常有人說，我很適合這份職務。",
  str_voice_1400861_3 = "請交給我，我十分擅長這類的事情，只需要讓大家躺下，稍微安詳一些就可以了吧？",
  str_voice_1400861_4 = "我只是簡單地，化悲痛為力量，為還活著的事物，盡我所能做出最大貢獻。",
  str_voice_1400861_5 = "戰場上遭背棄的人呀，你們的名字不會被遺忘，會有人為你們祈禱，祈禱背棄你們之人走入滅亡。",
  str_voice_1400861_6 = "我緬懷，表示哀思，獻上敬意，讚頌逝者的功德，詠懷過去的光輝——為了，更美好的未來！",
  str_voice_1400861_7 = "一端是鋒利的刺，一端是無害的花藤，請勿擔心，我自然會將適合的那一端向著您。",
  str_voice_1400861_8 = "我會銘記您的容貌，您的善良、溫暖，永不褪色的品格。都會永遠留存在我心中。",
  str_voice_1400861_9 = "我為您帶來了一些花藤，這是我十分喜歡的白色花朵，在我還擁有生命時，願它傳遞溫暖給您。",
  str_voice_1400861_10 = "這是一個簡單的遊戲，讓我們來猜猜，下一個離開的是誰？如果您感到不安的話，就祈禱吧……",
  str_voice_1400861_11 = "我想在陽光能照耀到的盡頭，種一些花藤，願它多帶一吋陽光到陰影裡。",
  str_voice_1400861_12 = "我當然會放下手中的劍，基於禮儀，我會祈禱之後再發動攻擊。",
  str_voice_1400861_13 = "可憐的孩子，我看見您在發抖，請伸出手來吧，我會幫助您止住顫抖。",
  str_voice_1400861_14 = "因為很多時候，笑起來更容易解決問題，不是嗎？",
  str_voice_1400861_15 = "今天是重要的日子，慶祝您在擁有生命時，無比重要的日子。",
  str_voice_1400861_16 = "歡迎回來，如果您需要，我可以再幫您祈禱一會。",
  str_voice_1400861_17 = "早安，能在醒來後不久，就見​​到您的面容，我很高興。",
  str_voice_1400861_18 = "請儘管去探索有限的生命，在躺下之前，盡情地擁抱現實吧。",
  str_voice_1400861_19 = "您睡不著嗎？那可真是太嚴重了，需要我來幫您閉上眼睛嗎？",
  str_voice_1400861_20 = "我原諒一切，只認定白夜就是光，哪怕只換來一句——不遺忘。",
  str_voice_1400861_21 = "絕無冒犯，出於職務禮儀，我希望瞭解「真理」需要什麼樣的致詞？",
  str_voice_1400861_22 = "白夜至上。",
  str_voice_1400861_23 = "我為那些可憐的暗鬼祈禱，祈禱牠們能夠迅速地，與世長辭。",
  str_voice_1400861_24 = "請讓我以通俗易懂的方式表達沉痛的心情，我很遺憾——他們真可愛。",
  str_voice_1400861_25 = "「希望你能在葬禮上為我唸點什麼，和父親不一樣的」，她曾這麼對我說。",
  str_voice_1400861_26 = "喜愛，是雨後的草坪，新發的嫩芽，和破碎屋頂洞中灑落的光。",
  str_voice_1400861_27 = "我理所當然地厭惡著祕密的信件和背信棄義的人。",
  str_voice_1400861_28 = "肅穆的氣氛，簡潔的線條，如祭奠的大殿……讓我感到十分安心。",
  str_voice_1400861_29 = "感謝您的邀請，請叫我尤萊雅就好。我的祈禱不偏向任何一方，畢竟，應盡的禮儀是對生衰的敬畏。",
  str_voice_1400861_30 = "不變的是，祈禱。",
  str_voice_1400861_31 = "讓祈禱的話語，更有力量。",
  str_voice_1400861_32 = "增加了，救贖和寄託。",
  str_voice_1400861_33 = "直到曾期盼的景象，到來。",
  str_voice_1400861_34 = "參加儀式嗎？",
  str_voice_1400861_35 = "請注目。",
  str_voice_1400861_36 = "我需要宣布。",
  str_voice_1400861_37 = "這是一段致詞。",
  str_voice_1400861_38 = "致詞，願各位遠離死亡。",
  str_voice_1400861_39 = "祈禱。",
  str_voice_1400861_40 = "哀悼。",
  str_voice_1400861_41 = "主持儀式嗎？",
  str_voice_1400861_42 = "禮畢，感謝各位。",
  str_voice_1400861_43 = "告別時間……到了嗎……",
  str_voice_1400861_44 = "您真貼心，作為回禮，請讓我送您一程吧。",
  str_voice_1400861_45 = "這是要，放在我的墓碑前嗎？",
  str_voice_1400861_46 = "這真是，如同祝福一般的禮物。",
  str_voice_1400861_47 = "不如將它，帶入我的長眠之所吧。",
  str_voice_1400861_48 = "多虧了您，我總會感恩生命。",
  str_voice_1400861_49 = "花藤所能承載的希望，極其有限……所以我需要禮儀的武裝，讓我得以保持寬容，選擇原諒。",
  str_voice_1400861_50 = "讓我們先來介紹一下，她的事蹟吧，她曾拿著一封，把自己送上戰場的信件，而毫不知情。",
  str_voice_1400861_51 = "那天，我懷著沉痛，深切悼念過去，該告別的是污染的苦楚，該迎接的是灑脫的新生。",
  str_voice_1400861_52 = "白夜極光。",
  str_voice_1400861_53 = "向您問候。",
  str_voice_1400861_54 = "早安，您好。",
  str_voice_1400861_55 = "午安，您是否安康？",
  str_voice_1400861_56 = "晚安，我佈置了一些白花～",
  str_voice_1400861_57 = "新年快樂，願您長壽～",
  str_voice_1500181_1 = "聽了芭芭拉的新專輯嗎？弱爆了，都應該直送垃圾場燒毀，一點樂隊的樣子都沒有。",
  str_voice_1500181_2 = "非要找我聊天？好，你喜歡什麼類型的音樂？想清楚再回答，畢竟我不想跟品味太差的傢伙打交道。",
  str_voice_1500181_3 = "對這力量感到好奇嗎？是啊，強大，容易失控，讓周圍人對我敬而遠之……爽翻了！哈哈哈哈！",
  str_voice_1500181_4 = "生如烈日，死如風暴！聚變的太陽已經升起，顫慄吧！",
  str_voice_1500181_5 = "別廢話了，接下來要去哪裡？我已經等不及把那些該死的傢伙化為灰燼了。",
  str_voice_1500181_6 = "做力量的主人，而不是奴僕！無論如何，我的可能性，由我自己說了算！",
  str_voice_1500181_7 = "你這裡也聚集了一群活寶啊，哼，讓人想起醒山那傢伙，活寶們總是那麼相似。",
  str_voice_1500181_8 = "有意思……我能感受到，在你眼中也燃燒著永不熄滅的火。搞不好你比我還要衝動得多……",
  str_voice_1500181_9 = "這片沉淪的土地需要新的太陽，但不會是我。你的話，說不定能成為那個人……",
  str_voice_1500181_10 = "無聊死了，誰把我放在這裡的電吉他拿走了？在我抓到之前決定自己想被烤成幾分熟吧……",
  str_voice_1500181_11 = "舞台的中心嗎？哼，這個位置本來就該屬於我！",
  str_voice_1500181_12 = "不斷破壞的我，也能保護誰嗎……？",
  str_voice_1500181_13 = "由我為大家放一首金屬音樂吧！嗨起來！",
  str_voice_1500181_14 = "能不能別打擾我，我要練琴！",
  str_voice_1500181_15 = "特別為您辦個金屬音樂的生日派對啊！",
  str_voice_1500181_16 = "你駕馭得了我嗎？",
  str_voice_1500181_17 = "呵。我以為你已經掛了。",
  str_voice_1500181_18 = "這點小事還要我來？",
  str_voice_1500181_19 = "深夜裡太安靜了啊！不行！得來段搖滾提提神！",
  str_voice_1500181_20 = "雖然是一群活寶、呆瓜、浪子的組合，但是也只有他們才能接受我的音樂。",
  str_voice_1500181_21 = "白夜城的老傢伙們，和他們聽的古典樂一樣，死板、不知變通。",
  str_voice_1500181_22 = "金屬不死！",
  str_voice_1500181_23 = "世界上最美好的事情，就是烤焦暗鬼。",
  str_voice_1500181_24 = "那個大呆瓜，自己就是個小丑，所以找的同伴也都是小丑。",
  str_voice_1500181_25 = "約娜無論是戰鬥方式還是音樂愛好都很有品味，我欣賞她！",
  str_voice_1500181_26 = "世界為何如此糟糕，是因為金屬樂太少。",
  str_voice_1500181_27 = "對不起，我不跟金屬音樂品味太差的人說話。",
  str_voice_1500181_28 = "如果能站在牠的腦袋上開場演唱會，不知道有多爽！",
  str_voice_1500181_29 = "就是你嗎？哼……看起來還算是個有點意思的傢伙，可別讓我太無聊啊，不然的話……",
  str_voice_1500181_30 = "需要……更多力量……",
  str_voice_1500181_31 = "不想死的話，最好離我遠一點。",
  str_voice_1500181_32 = "金色的風暴，很美嗎？",
  str_voice_1500181_33 = "末日的太陽再也不會落下了！",
  str_voice_1500181_34 = "可以放肆撒野囉？",
  str_voice_1500181_35 = "你敢直視這光芒嗎！",
  str_voice_1500181_36 = "確定要玩這麼大？",
  str_voice_1500181_37 = "瞬間就解決掉！",
  str_voice_1500181_38 = "在烈陽裡燃盡吧！",
  str_voice_1500181_39 = "就倒在這裡​​吧！",
  str_voice_1500181_40 = "太陽！暴風！",
  str_voice_1500181_41 = "小鬼們，不是早就躁動得不耐煩了嗎！",
  str_voice_1500181_42 = "我還沒玩夠啊！安可時間安可時間！",
  str_voice_1500181_43 = "哈！有趣……強敵嗎。",
  str_voice_1500181_44 = "好想敲敲那架鋼琴。",
  str_voice_1500181_45 = "討好我也沒用。",
  str_voice_1500181_46 = "你……該不會是我的頭號粉絲吧？",
  str_voice_1500181_47 = "嗯，不錯，給你一張演唱會的VIP門票吧！",
  str_voice_1500181_48 = "想得到要送我這個，看來你也是同道中​​人呢！",
  str_voice_1500181_49 = "確實有些人對我的音樂說三道四，哼，陳腐的老傢伙和他們的規矩遲早完蛋，我才懶得跟注定滅亡的東西浪費口水。",
  str_voice_1500181_50 = "我明白醒山對我的期待——不只是掃蕩敵人的燎原烈火，也是引領同伴的指路明燈。只是我不知道……也不在乎自己能否做到。",
  str_voice_1500181_51 = "要贏得紅油組織的尊重，除了力量之外，任何花招都沒用。但你讓我看到了另一種可能。也許有一天，我能夠真正達成老哥對我的期望。",
  str_voice_1500181_52 = "白夜！極光！",
  str_voice_1500181_53 = "你人在哪？",
  str_voice_1500181_54 = "還沒睡醒嗎？該起來了！",
  str_voice_1500181_55 = "你在做什麼？有空就來一趟。",
  str_voice_1500181_56 = "演唱會才正要開始，睡什麼！",
  str_voice_1500181_57 = "新的風暴正在降臨！",
  str_voice_1500701_1 = "為何而戰？愚蠢的提問……不為自身而戰，難道要為庭院裡不存在的金色果實而戰嗎？",
  str_voice_1500701_2 = "無需武器，既然擁有雙翼和烈爪，要嘛讓喋血之焰焚盡一切，要嘛親自上前粉碎一切。",
  str_voice_1500701_3 = "龍族之怒，讓該承受者去承受，讓該吞嚥者去吞嚥，這不是能拿去打擾那位影主的藉口。",
  str_voice_1500701_4 = "審判？那是牠們的聲音，過於吵鬧。牠們點燃我的血液，希望我摧毀一切，但很可惜，我不願意。",
  str_voice_1500701_5 = "別誤會，流於這心臟中的仇恨與我想要發洩的仇恨，毫不相干。畢竟我們愈是強大，就愈是盲目。",
  str_voice_1500701_6 = "暗與血不過是虛妄的表象，恨或愛，皆化為塵土，再臨之龍，已墮入其中——",
  str_voice_1500701_7 = "龍之血脈中僅流淌著仇恨，但我向來只讓「心情」做決定，你很快就會理解。",
  str_voice_1500701_8 = "你對這遮起來的右眼感到好奇嗎？或許我應該拿下眼罩，讓你體驗一次被仇恨掐住脖子的感覺。",
  str_voice_1500701_9 = "可愛的小鬼，不要想著能為我帶來什麼，你只需要順從我的話語，或者，無盡地辯駁。",
  str_voice_1500701_10 = "巨龍從不沉睡，當你閉上眼睛的那一刻，就等於將處決自己的權力交到別人手中。",
  str_voice_1500701_11 = "像你這樣不知道是哪來的小鬼，還想要得到我的青睞嗎？……反駁我吧，現在。",
  str_voice_1500701_12 = "讓無知之人背負命運和詛咒，這可真是不錯的興趣。",
  str_voice_1500701_13 = "我們總有一天會被自身的愚蠢吞噬，在那之前好好掙扎吧，理應掙扎。",
  str_voice_1500701_14 = "有什麼事？正好我心情不錯……不，請你讓我更愉快一些吧。",
  str_voice_1500701_15 = "你在期待什麼？生日快樂嗎？……真是麻煩又可愛的小鬼。",
  str_voice_1500701_16 = "啊——我知道，有個小鬼來了。",
  str_voice_1500701_17 = "可愛的小鬼，過來握手吧，你的掙扎會是不錯的問候，不是嗎？",
  str_voice_1500701_18 = "你總是會按時回到我身邊呢……即便那個特殊之人不是我。",
  str_voice_1500701_19 = "這個時間，清醒又可憐的傢伙不多……桑咚，你去陪陪那小鬼吧。",
  str_voice_1500701_20 = "對我來說，與影主一起回到影鎮是最好的選擇，於是我就這麼做了。",
  str_voice_1500701_21 = "從白夜的傀儡，變成啟光的傀儡……不，那裡似乎有更好的稱號。",
  str_voice_1500701_22 = "巨龍，正注視著你。",
  str_voice_1500701_23 = "我偶爾也會想，乾脆變成那黑暗的樣子，痛快與她為敵也不錯。",
  str_voice_1500701_24 = "值得尊敬之人，獨一無二，因此他所期望的事，我會完成。",
  str_voice_1500701_25 = "你能想像她與我出自同一血脈嗎？她甚至連我的存在都不知道。",
  str_voice_1500701_26 = "愚蠢之人的反抗與掙扎，還有比這更吸引人的事嗎？",
  str_voice_1500701_27 = "一想到那滑稽而愚蠢的妹妹，和造成這一切的元凶，我就覺得噁心。",
  str_voice_1500701_28 = "抱歉，畢竟我上一秒還對這白色巨龍感到親切，現在卻只想拆了他。",
  str_voice_1500701_29 = "你只需要知道，這映於瞳孔之像，來自於我們那充滿死霧的故鄉。至於我的名字，我會讓你慢慢知曉……",
  str_voice_1500701_30 = "純粹的只有慾望而已。",
  str_voice_1500701_31 = "無用的遺落之血啊。",
  str_voice_1500701_32 = "龍之火焰？那不過是嘆息。",
  str_voice_1500701_33 = "故里終會化為焚場。",
  str_voice_1500701_34 = "直視仇恨。",
  str_voice_1500701_35 = "這樣，就足夠了。",
  str_voice_1500701_36 = "無需忍耐，去吧。",
  str_voice_1500701_37 = "桑咚，送他們下地獄。",
  str_voice_1500701_38 = "那麼，將一切碾成齏粉！",
  str_voice_1500701_39 = "嘆息吧！",
  str_voice_1500701_40 = "消失吧。",
  str_voice_1500701_41 = "踏出憎惡，卻無比懷念。",
  str_voice_1500701_42 = "贏了，那又怎麼樣？",
  str_voice_1500701_43 = "那麼，要咬牙說些誓言復仇的話嗎？",
  str_voice_1500701_44 = "很好，讓我心裡舒服……不，果然還不夠。",
  str_voice_1500701_45 = "這是什麼？……連桑咚都不願意碰它。",
  str_voice_1500701_46 = "比起這禮物，你猶豫的樣子更可愛呢。",
  str_voice_1500701_47 = "桑咚，把這小鬼送的東西拿走。",
  str_voice_1500701_48 = "光是你這個表情，就夠讓我喜歡了。",
  str_voice_1500701_49 = "兩度凝視總讓我不禁思索，不如就於她面前降臨，然後宣告，我們所追尋的事物就是一個笑話。",
  str_voice_1500701_50 = "向無辜者的復仇永無可能化解這份融血之恨，而那作為出口的復仇對象，早已不復存在。",
  str_voice_1500701_51 = "血，記憶，復仇的漩渦，沉澱的歷史，它們在名為「龍」的身分之中糾葛，噁心極了。",
  str_voice_1500701_52 = "白夜，極光。",
  str_voice_1500701_53 = "小鬼。",
  str_voice_1500701_54 = "早上了，過來跟我打招呼。",
  str_voice_1500701_55 = "先告訴我，你在哪？",
  str_voice_1500701_56 = "過來，陪陪桑咚。",
  str_voice_1500701_57 = "新年？來，慶祝給我看。",
  str_voice_1500761_1 = "人類無一特別，一樣有過去，一樣有祕密，我熱愛都是「一樣」的大家。至於光靈……那是什麼？",
  str_voice_1500761_2 = "謊言與真實沒有多大的差別，甚至連界限都沒有，當我說「這句話是謊言」時，真假就毫無意義。",
  str_voice_1500761_3 = "如果你對於神祕的深海感到好奇，只需攀上白夜城，在大殿裡呼呼睡去，便可到達那裡。",
  str_voice_1500761_4 = "航行的勇者，不要把觸手當作小島，如果你連真實和虛假都分不清，那可是……十、分、危、險。",
  str_voice_1500761_5 = "你要小心潛伏於深海的怪物，牠們浮上水面攻擊航行的船隻，只是為了綁幾位心愛的勇者回去。",
  str_voice_1500761_6 = "就像遊走的觀測者，總是置身事外，然而當我想要介入其中時，卻發現有些晚了……因此，才需要強硬。",
  str_voice_1500761_7 = "一聽就知道真假的言語不是十分方便嗎？如果你能分辨出其中真實的意涵……你應該不會說「不能」吧？",
  str_voice_1500761_8 = "我總會在謊言中藏匿真話，總希望聽到的人能夠分辨出我的心思，你相信嗎？畢竟你看起來十分單純的樣子。",
  str_voice_1500761_9 = "無需介意，不要害怕。無論如何，那長滿可愛觸手的怪物都希望航行的勇者能見到地平線上的曙光。",
  str_voice_1500761_10 = "今天影鎮在舉辦活動，如果你不去看看那就太可惜了……你不會真的打算去吧？",
  str_voice_1500761_11 = "這感覺究竟是什麼？我似乎能夠感受到你的信賴，這是出自於愛意嗎？航行的勇者。",
  str_voice_1500761_12 = "隨便碰這些觸手是很危險的。比如，碰莉奧娜的龍就會受傷。",
  str_voice_1500761_13 = "這裡有朝一日也會被淹沒，在那之前，你跟我一起逃走吧。",
  str_voice_1500761_14 = "我得離開了，否則會被可怕的傢伙追上，不用等我，有緣再見。",
  str_voice_1500761_15 = "今天是深海實現大家願望的日子，我的願望是陪在你身邊，你呢？",
  str_voice_1500761_16 = "歡迎回來，航行的勇者，深海已經預料到你的到來。",
  str_voice_1500761_17 = "見到你十分高興，但你來得太早了，我原本想背著你偷偷逃走。",
  str_voice_1500761_18 = "零星的燈火將要消失，你呢？還想要留在這裡嗎？在我身邊？",
  str_voice_1500761_19 = "這個時間還能見到你，你是想與我一同前往深海嗎？我知道了……",
  str_voice_1500761_20 = "混沌的環境裡我能找到更多樂趣，況且那裡有很多我熱愛的人類。",
  str_voice_1500761_21 = "虛偽是一門藝術，那座白色小島明明使用著它，卻對它一無所知。",
  str_voice_1500761_22 = "觸手正注視著你們。",
  str_voice_1500761_23 = "就算是在深海中，也會有無聊的東西，彷若灰塵……比如暗鬼。",
  str_voice_1500761_24 = "養狗的人居然能相信其他物種的忠誠，是因為狗會搖尾巴嗎？",
  str_voice_1500761_25 = "那條暴怒的長龍，為何總是會露出十分呆滯的表情？真是有趣。",
  str_voice_1500761_26 = "陰雨天、古書、《勇者出海》的故事，你可以猜測我喜歡哪一個。",
  str_voice_1500761_27 = "我討厭無聊的東西，也討厭說謊，所以說了真話。",
  str_voice_1500761_28 = "他被稱為巨像嗎？怪物在深海中十分常見，或許他也來自深海。",
  str_voice_1500761_29 = "初次見面，我是欺詐師，名字就叫克萊肯好了。還請千萬不要相信我說的話，包括我現在說的，全部不要相信。",
  str_voice_1500761_30 = "總覺得沒什麼提升。",
  str_voice_1500761_31 = "謊言更進一步，真遺憾，還是謊言。",
  str_voice_1500761_32 = "當霧氣凝結成水，「虛構」便成為真相。",
  str_voice_1500761_33 = "無言的門扉開啟，深海的面貌初現。",
  str_voice_1500761_34 = "需要向誰說謊？",
  str_voice_1500761_35 = "霧氣已經夠濃厚。",
  str_voice_1500761_36 = "眼見就是真實嗎？",
  str_voice_1500761_37 = "古老的傳說在此刻甦醒！",
  str_voice_1500761_38 = "願你有朝一日，見到深海！",
  str_voice_1500761_39 = "噓——",
  str_voice_1500761_40 = "太晚了。",
  str_voice_1500761_41 = "你似乎……意外地信任我？",
  str_voice_1500761_42 = "很抱歉，我們失敗了。",
  str_voice_1500761_43 = "讓你露出如此表情的……是我嗎……",
  str_voice_1500761_44 = "很高興見到你，這當然是真心話。",
  str_voice_1500761_45 = "嗯，不如把你自己送我吧。",
  str_voice_1500761_46 = "如果我說不喜歡，那是騙你的。",
  str_voice_1500761_47 = "謝謝，我會珍惜你的。",
  str_voice_1500761_48 = "你真是……",
  str_voice_1500761_49 = "在影鎮，觸手是陰雨中的自然現象，只要讓披風濕潤，打開五十度角以上，它們就會出現在任何人身邊。",
  str_voice_1500761_50 = "來自古老書籍的怪物，得到了類似人類的情感，可是上岸後牠卻不知該如何在陸地上生存下去，十分煩惱。",
  str_voice_1500761_51 = "洶湧的黑潮席捲而來時，觸手怪物想要躲避危機，然而根本無處可逃，最終被影主吞噬掉了。",
  str_voice_1500761_52 = "白夜極光。",
  str_voice_1500761_53 = "可愛的勇者。",
  str_voice_1500761_54 = "夜深了，不是嗎？",
  str_voice_1500761_55 = "早安，我想你已經醒了。",
  str_voice_1500761_56 = "太陽正好升起。",
  str_voice_1500761_57 = "明天就是新年了～",
  str_voice_1500781_1 = "請和我……保持距離，會比較好……我怕我一不小心……會打暈你，抱歉。",
  str_voice_1500781_2 = "抱歉……我想你應該可以照顧好自己……我不太會照顧人……沒辦法幫你太多。",
  str_voice_1500781_3 = "你最近……是不是常常跟烈雀相處？她總是喜歡照顧別人，對誰都很親切……沒什麼，我只是想確認一下。",
  str_voice_1500781_4 = "不管變成什麼樣子，我都不在意別人對我的看法……只要他們離我遠一點，就無所謂……欸？看起來沒什麼變化嗎？",
  str_voice_1500781_5 = "我已經不是以前那個無力又弱小的幼童，現在的我……還是保持距離，比較好……不要，靠太近。",
  str_voice_1500781_6 = "我知道……總有一天要靠自己的力量，解決那份仇恨……或許是現在。",
  str_voice_1500781_7 = "抱歉，我原本以為你和外面的人一樣粗魯……但其實，你比他們好得多……至少會注意距離。",
  str_voice_1500781_8 = "那個……我覺得你是很厲害的人，而且還能夠變得更加厲害，所以你要不要……去找烈雀學學？",
  str_voice_1500781_9 = "我們有很多相似的地方……我想烈雀也會認同這一點，所以，那個……你有考慮過來影鎮嗎？",
  str_voice_1500781_10 = "……難得有休息的時間……我不會讓人打擾你的……當然，除了烈雀。",
  str_voice_1500781_11 = "是要讓我當圍事吧……明白了，不用擔心，我做過。",
  str_voice_1500781_12 = "抱歉……我不太會用那種鋒利的武器，也沒辦法……當面下手。",
  str_voice_1500781_13 = "……如果獲得力量……就能了結那一切。",
  str_voice_1500781_14 = "你有時間嗎？不會耽誤你太久……其實我只是想問一下……烈雀在哪裡？",
  str_voice_1500781_15 = "那個……祝你生日快樂……抱歉，我沒買到禮物……還不小心砸了店。",
  str_voice_1500781_16 = "我還在商會兼職工作……如果你也需要人手幫忙，請提前告訴我。",
  str_voice_1500781_17 = "……現在太早了，不好控制……我建議我們之間的距離再遠一點。",
  str_voice_1500781_18 = "商會的事忙完了，你有什麼想去的地方嗎……我和烈雀陪你去吧。",
  str_voice_1500781_19 = "或許我該對你說「晚安」了……就像我平常聽到的那樣。",
  str_voice_1500781_20 = "哪怕是在那樣的地方……我們也漸漸有了屬於自己的容身之所。",
  str_voice_1500781_21 = "白夜城的生活環境確實更好……但事到如今，我和烈雀都沒打算去了。",
  str_voice_1500781_22 = "影子在注視著你。",
  str_voice_1500781_23 = "……那隻奪取我父母生命的暗鬼，我會親手了結牠。",
  str_voice_1500781_24 = "烈雀是我的親人……我很少叫她姐姐……她比姐姐更加重要。",
  str_voice_1500781_25 = "感謝涉小姐的照顧，希望她下次不要靠我太近……我很容易感到窒息。",
  str_voice_1500781_26 = "……喜歡的東西……那個，我可以，可以說……是烈雀嗎？",
  str_voice_1500781_27 = "討厭突然靠近的東西……另外，仇恨暗鬼。",
  str_voice_1500781_28 = "這座巨像……白色的看起來很乾淨……像是我們曾經想去的地方。",
  str_voice_1500781_29 = "我是知更……抱歉，適當保持距離……因為我們是初次見面，各自再後退兩公尺，重新開始介紹吧。",
  str_voice_1500781_30 = "離目標……近了嗎？",
  str_voice_1500781_31 = "原來力量是這樣匯聚的。",
  str_voice_1500781_32 = "烈雀，我變強了。",
  str_voice_1500781_33 = "就算污泥滿身也無所謂……只要有力量。",
  str_voice_1500781_34 = "得把管子帶著。",
  str_voice_1500781_35 = "測量好了。",
  str_voice_1500781_36 = "再等一會也可以。",
  str_voice_1500781_37 = "就算是求饒……也沒辦法停下來了。",
  str_voice_1500781_38 = "這次例外，請好好看著吧！",
  str_voice_1500781_39 = "讓開。",
  str_voice_1500781_40 = "離我遠一點！",
  str_voice_1500781_41 = "要戰鬥？……也叫上烈雀吧。",
  str_voice_1500781_42 = "勝利的感覺……還是習慣一下比較好。",
  str_voice_1500781_43 = "失敗了……不想……讓烈雀知道。",
  str_voice_1500781_44 = "……在、在看我？看到烈雀了嗎？",
  str_voice_1500781_45 = "隨便收下禮物……真的沒問題嗎？",
  str_voice_1500781_46 = "居然是……你知道我的喜好？",
  str_voice_1500781_47 = "我悄悄收下了，悄悄地。",
  str_voice_1500781_48 = "這個是……謝謝你，真的。",
  str_voice_1500781_49 = "那幾年……或許正是因為太過艱難，人們才會變得如此冷漠、爭奪、踐踏彼此。",
  str_voice_1500781_50 = "天真的信任，不會讓飢餓與歧視消失，我們都深諳此理。也只有依靠我們自己的力量……才能生存下去。",
  str_voice_1500781_51 = "她把我的仇恨也背負在自己身上……但我必須要自己解決才行，不能把她捲入進來……因為烈雀，並不適合仇恨。",
  str_voice_1500781_52 = "……白夜極光。",
  str_voice_1500781_53 = "咳、那個……",
  str_voice_1500781_54 = "早安……",
  str_voice_1500781_55 = "咳，好巧……",
  str_voice_1500781_56 = "還沒休息嗎？",
  str_voice_1500781_57 = "新年快樂，要慶祝嗎？",
  str_voice_1500841_1 = "這是關於贖罪的笑話：找一隻羔羊，將牠推下懸崖或放逐荒野；與牠是否有罪無關，只要有角就好了。",
  str_voice_1500841_2 = "舒瓦茲能有今天是因為他有位好伴侶……呵，那個看起來行將就木的傢伙其實沒那麼老。",
  str_voice_1500841_3 = "最一開始以惡魔身分出生的傢伙，卻拿著能讓惡魔化為灰燼的手杖，當然適合管理地獄的大門。",
  str_voice_1500841_4 = "陳舊的寶座並非奪來之物，而是贏得尊重的象徵，它會在烈火淬鍊之後，變得嶄新。",
  str_voice_1500841_5 = "那些醞釀詭計的傢伙不敢肆無忌憚，那些自上而下的壓榨也不會毫無底線，因為他們知道，有影子在注視著。",
  str_voice_1500841_6 = "當我再回到此地之後，影鎮的傳說成了一種描述——主事者，影子會從末端開始，掌握地面的每一吋。",
  str_voice_1500841_7 = "我守護的正義跟你口中的不一樣，它混沌但不容扭曲，現在的你還無法理解，還需要時間。",
  str_voice_1500841_8 = "無依無靠，苟且偷生，我想你也跟最初的我一樣，終有一天會無法忍受被泥濘吞噬。",
  str_voice_1500841_9 = "作為領航者，你還可以做得更好，但經驗的學習往往伴隨著墜毀的風險……跟在我身邊吧，你會輕鬆許多。",
  str_voice_1500841_10 = "切莫一意孤行……不，我是說，不忙的時候也來看看我，有棋局，有故事。",
  str_voice_1500841_11 = "我習慣於隱藏在影子中生活……好吧，現在已經沒有那個必要了……坐在這裡就可以吧？",
  str_voice_1500841_12 = "每一步棋都應當追求至臻至妙，所以，深思熟慮之後再出手。",
  str_voice_1500841_13 = "我希望你也好自為之，也就是說，影子也會一直盯著你的。",
  str_voice_1500841_14 = "若是被那個小傢伙知道我在這裡，會很麻煩……",
  str_voice_1500841_15 = "生日？既然今天是特別的日子，去我那拿一兩件藏品來吧。",
  str_voice_1500841_16 = "歡迎回來，被賦予責任之人，我想你已經準備好要做些什麼了。",
  str_voice_1500841_17 = "很好，你能夠在這個時間出現，就像影子總會先一步到達。",
  str_voice_1500841_18 = "如果你感到疲憊，可以稍微坐一會，再開始行動。",
  str_voice_1500841_19 = "現在的年輕人似乎習慣在這個時間活動，嗯，隱於黑暗。",
  str_voice_1500841_20 = "眾所周知，白夜城的秩序有一半是靠影鎮在維持。",
  str_voice_1500841_21 = "跟啟光的傢伙們說，這種剖腹藏珠的事不要再做了。",
  str_voice_1500841_22 = "影子在注視著你。",
  str_voice_1500841_23 = "對方是不知道真相的生物，那麼在爭奪生存權利時，不必留情。",
  str_voice_1500841_24 = "那個看起來很老的傢伙總是在奇怪的地方令人討厭，比如下棋作弊。",
  str_voice_1500841_25 = "那位熱血之人很清楚，想要改變情況就要坐到最有責任的位置上。",
  str_voice_1500841_26 = "在我的房間裡，擺著一些收藏櫃，裡面有不少大師的傑作。",
  str_voice_1500841_27 = "無信之人、無義之人、無禮之人，這類傢伙往往沒有什麼存在的價值。",
  str_voice_1500841_28 = "曾經聽聞巨像既是庇護的手段，也是使命的證明。",
  str_voice_1500841_29 = "收起你的好奇心，你只需要知道，我是徘徊在影鎮的舊時代亡魂，是現在統治白夜城的傢伙最不想面對的人。",
  str_voice_1500841_30 = "愈是接近頂峰，就愈是無聊。",
  str_voice_1500841_31 = "對於影子來說，這是更深一層。",
  str_voice_1500841_32 = "一如既往，影鎮會包容你。",
  str_voice_1500841_33 = "身已為影……",
  str_voice_1500841_34 = "協規同力。",
  str_voice_1500841_35 = "不過是代價。",
  str_voice_1500841_36 = "讓一切結束吧！",
  str_voice_1500841_37 = "反抗吧，在面對墳墓之前！",
  str_voice_1500841_38 = "崛起吧，在被黑暗吞噬之前！",
  str_voice_1500841_39 = "威壓！",
  str_voice_1500841_40 = "震懾！",
  str_voice_1500841_41 = "無妨，我可以統領行動。",
  str_voice_1500841_42 = "勝利，歸功於眾人。",
  str_voice_1500841_43 = "失敗沒有價值，但反思有。",
  str_voice_1500841_44 = "很好，在這裡，很多人能以另外一副面孔活下去。",
  str_voice_1500841_45 = "不必費心，我不會回禮。",
  str_voice_1500841_46 = "嗯，我能感受到它的貴重。",
  str_voice_1500841_47 = "雖然並不需要，但我會考慮回禮。",
  str_voice_1500841_48 = "哈哈，我該把它放在我的收藏櫃中。",
  str_voice_1500841_49 = "混沌之影從不映射任何東西，它們如蜘蛛網一般遍布影鎮各處，維持著影鎮獨特的秩序。",
  str_voice_1500841_50 = "在白夜城還未分離之時，黑暗反而更加根深蒂固，只要它不曾落在自己頭上，眾人就視而不見。",
  str_voice_1500841_51 = "確保資金來源，幫助和收養苦子、孤兒，教他們抗衡命運，這就是在陰影中，培養新秩序的方式。",
  str_voice_1500841_52 = "白夜極光。",
  str_voice_1500841_53 = "責任之人。",
  str_voice_1500841_54 = "記住，提早行動。",
  str_voice_1500841_55 = "準備萬全了嗎？",
  str_voice_1500841_56 = "暗隱於理，隱於序。",
  str_voice_1500841_57 = "去慶祝吧，新年了。",
  str_voice_1500881_1 = "我不能把手套脫下來，萬一傷到人就不好了……因為，那個，我的手上有刺毛毛。",
  str_voice_1500881_2 = "別看著我了，好嗎？你再怎麼看我也不會變的……我可不是那種能隨心所欲變化的蜥蜴。",
  str_voice_1500881_3 = "紅油扳手的大家常常會在一起，狂歡聚會，然後我通常都待在角落，除非……不小心興奮了。",
  str_voice_1500881_4 = "我的樣子怎麼了嗎？……可是，荒漠裡的毛蜥蜴都是長這樣的呀，欸？沒有聽說過嗎？",
  str_voice_1500881_5 = "興奮狀態就是用「毛蜥蜴的力量」，那種時候會感覺血液都沸騰起來了，力氣十足。",
  str_voice_1500881_6 = "鼓起勇氣，不畏困難！無論想做什麼、想找什麼，我衝上去就是一顆手榴彈……哎呀，抱歉，不小心興奮了。",
  str_voice_1500881_7 = "我可不是小孩子了！……所以沒關係，可以戰鬥，而且我還有好多炸彈！也會騎機車！",
  str_voice_1500881_8 = "你不開心嗎？怎麼辦……那，我把尾巴借給你？……欸？難道你，其實，沒有興趣嗎？",
  str_voice_1500881_9 = "其實，這個手套滿不方便的，要是有一天，我可以……沒事，能夠像這樣待在你旁邊就夠啦。",
  str_voice_1500881_10 = "給你看一下我的改造手榴彈吧？等一下喔，我慢慢拿出來，要是拉環被手套勾到就糟糕了。",
  str_voice_1500881_11 = "如果我興奮起來不小心打壞了什麼東西，對不起，我一定會賠償……用手榴彈抵債？",
  str_voice_1500881_12 = "我果然還是不行……不然，讓我休息一下再試試看吧，等一下下就好……",
  str_voice_1500881_13 = "其實有些傷口，是我自己弄的，因為……休息的時候，尾巴不太老實。",
  str_voice_1500881_14 = "我不擅長面對人多的地方……如果被盯著，會很害羞……",
  str_voice_1500881_15 = "我決定今天要為你慶祝，好不容易鼓起勇氣！祝你快樂！",
  str_voice_1500881_16 = "歡迎回來，我有好好守在這邊，沒有離開。",
  str_voice_1500881_17 = "等一下，等我貼個OK繃……你要貼嗎？可以防止受傷。",
  str_voice_1500881_18 = "別、別看！我還在整理尾巴……所以，毛亂亂的，會很奇怪嗎？",
  str_voice_1500881_19 = "我在晚上看得很清楚，所以你不要擔心……啊，對喔，這裡並不黑。",
  str_voice_1500881_20 = "其實要融入紅油扳手並沒有那麼困難，只要，那個……會玩就行。",
  str_voice_1500881_21 = "我找過很多地方，但是聽說白夜城在天上，要怎麼去嘛……",
  str_voice_1500881_22 = "及時、及時……及時做什麼？",
  str_voice_1500881_23 = "黑的東西，我看得很清楚。你要是害怕，就帶上我吧，我加油！",
  str_voice_1500881_24 = "不能弄壞機車，因為這個才剛修好不久，小不點會生氣的。",
  str_voice_1500881_25 = "因為我堅持要加入紅油扳手，大哥就跟我母親約定，會好好照顧我。",
  str_voice_1500881_26 = "欸？問我喜歡什麼？……看起來酷酷的東西，比較喜歡。",
  str_voice_1500881_27 = "為什麼、會有蜥蜴乾這樣的食物？……嗚，不行，絕對吃不下去……",
  str_voice_1500881_28 = "巨像好厲害！要是我多努力一下，能不能變成像它一樣呢？",
  str_voice_1500881_29 = "我、我是瑪姬……那個，雖然有很多不擅長的事，但我會鼓起勇氣！……克服的。",
  str_voice_1500881_30 = "興奮起來了！",
  str_voice_1500881_31 = "尾巴在躁動……",
  str_voice_1500881_32 = "變成大蜥蜴！",
  str_voice_1500881_33 = "我要引爆一切！",
  str_voice_1500881_34 = "要鼓起勇氣！",
  str_voice_1500881_35 = "毛蜥蜴的力量！",
  str_voice_1500881_36 = "我早就準備好了！",
  str_voice_1500881_37 = "不過是丟手榴彈而已，加油！",
  str_voice_1500881_38 = "衝過去！把手榴彈塞進牠們嘴裡！",
  str_voice_1500881_39 = "丟炸彈！",
  str_voice_1500881_40 = "統統炸飛！",
  str_voice_1500881_41 = "好可怕……但是，血液沸騰起來了！",
  str_voice_1500881_42 = "戰鬥結束了？那我冷靜一下……",
  str_voice_1500881_43 = "我還有勇氣，再來一次……",
  str_voice_1500881_44 = "尾、尾巴不是用來展示的……也不好看，真的。",
  str_voice_1500881_45 = "這個……不收下，不行嗎？",
  str_voice_1500881_46 = "啊，這個……我該怎麼答謝你呢。",
  str_voice_1500881_47 = "我會收下的。……謝謝？",
  str_voice_1500881_48 = "謝謝！這個看起來好酷、好厲害！",
  str_voice_1500881_49 = "紅油扳手的前輩們都穿著很霸氣的服裝，我也想努力融入進去，就……全換了，後悔都來不及……",
  str_voice_1500881_50 = "改造手榴彈在一般狀態下威力並不大，但只要我使用了「毛蜥蜴的力量」，就會——很厲害！",
  str_voice_1500881_51 = "我本來是想出來找父親，但是一直都沒有消息，所以，我就跟上來了，因為能去更遠的地方。",
  str_voice_1500881_52 = "白夜極……光？",
  str_voice_1500881_53 = "打擾一下？",
  str_voice_1500881_54 = "早安，你有空嗎？",
  str_voice_1500881_55 = "來玩嗎？我好興奮呀！",
  str_voice_1500881_56 = "晚上……你冷嗎？",
  str_voice_1500881_57 = "新年快樂，一定要……克服缺點。",
  str_voice_1500901_1 = "愛的～紅油～是脊髓的味～道打飛那隻暗鬼！漂～亮～的蜥蜴斬～鮮血是三十八度七小心背後的敵人～！",
  str_voice_1500901_2 = "期待嗎？期待嗎！芭芭拉新專輯的名字是，鏘鏘鏘——《時刻♥機油熱戀》，裡面還附有芭芭拉的特典寫真，是泳裝喔～",
  str_voice_1500901_3 = "暗鬼四處逃竄，處處危機四伏，準備好電鋸和扳手……嗯？戰鬥？我是說演唱會啦～～",
  str_voice_1500901_4 = "芭芭拉我呀～可是在「激鬥應援」活動中，連續三天不眠不休的表演了超過六百首歌呢～～",
  str_voice_1500901_5 = "芭芭拉很可怕？一點也不！芭芭拉是完美的偶像，單純可愛的元氣少女，都是你的錯覺啦、錯覺。",
  str_voice_1500901_6 = "歌聲能夠治癒人心！芭芭拉的夢想是成為大～～家的偶像，用音樂為世界帶來溫暖和愛！",
  str_voice_1500901_7 = "欸～～你會來參加芭芭拉的握手會嗎？只要購買專輯，就可以得到握手券。不過排在隊尾要注意安全，小心被暗鬼吃掉。",
  str_voice_1500901_8 = "如果是你的話，芭芭拉會為你安排離舞台最近的車喔！那是會員專屬的位置！",
  str_voice_1500901_9 = "跟我一起念：扳手～～芭芭拉一定會好好保存這張與你的合照！還有你的微笑，芭芭拉絕對不會忘記！",
  str_voice_1500901_10 = "我想為紅油扳手的大家寫一首歌，主題是「狂野沙漠」，邀請誰來當嘉賓比較好呢？",
  str_voice_1500901_11 = "好好做這份工作，粉絲數量也會增加吧！為了保住最受歡迎的「紅油歌手」大位，芭芭拉要努力！",
  str_voice_1500901_12 = "欸？你們為什麼停止歡呼了？不要在意入侵者，演唱繼續～",
  str_voice_1500901_13 = "芭芭拉很高興有你們在！請一定要活著回來聽明天的演唱會啊！",
  str_voice_1500901_14 = "無懈可擊的表情管理可是偶像的必修課，來，微、笑～",
  str_voice_1500901_15 = "祝你生日快樂～～祝你生日快樂～～一起解決暗鬼吧～～",
  str_voice_1500901_16 = "演唱會馬上就要開始了！",
  str_voice_1500901_17 = "啊——咳咳，哆唻咪發——嗯？我在鍛鍊嗓子啦～",
  str_voice_1500901_18 = "舉起你們的雙手、讓我看到你們的熱情～！",
  str_voice_1500901_19 = "呀吼♪～～膽敢礙事的傢伙，全部幹掉，用圓鋸機問候你～～",
  str_voice_1500901_20 = "紅油扳手的大家是世界上最最最最最——可愛的人！",
  str_voice_1500901_21 = "欸——白夜城有合唱團？還有專業的音樂家？導航員，你不能變心喔！",
  str_voice_1500901_22 = "紅油扳手！拿出氣勢來！",
  str_voice_1500901_23 = "破壞演唱會秩序的傢伙，必須要好——好地教育一頓。",
  str_voice_1500901_24 = "有人去蕾吉娜的專場了嗎？沒關係喔，芭芭拉不、會、介、意、呢。",
  str_voice_1500901_25 = "最好的夥伴——小不點！！芭芭拉的舞台裝置、麥克風都由她製作～",
  str_voice_1500901_26 = "魚肉料理真的很～～好吃，尤其是生魚片，但是很少能吃到。",
  str_voice_1500901_27 = "完美的偶像熱愛所有事物喔～～即使是蕾吉娜的噪音也不討厭唷。",
  str_voice_1500901_28 = "在哪裡布置舞台比較好呢？甲板上？還是艦橋上？超——苦惱！",
  str_voice_1500901_29 = "呀吼～～愛戀紅油、激熱甜心，大家的偶像芭芭拉全速趕來♥。歡呼聲在哪裡？再熱烈一點！再熱烈一點！！",
  str_voice_1500901_30 = "光芒♥四射！",
  str_voice_1500901_31 = "讓搖滾震撼靈魂！",
  str_voice_1500901_32 = "音樂！熱情！點燃沙漠！！",
  str_voice_1500901_33 = "芭芭拉的歌聲會永遠陪伴左右！",
  str_voice_1500901_34 = "熱情、狂野、羈絆、愛！",
  str_voice_1500901_35 = "大家～～準備好了嗎～～",
  str_voice_1500901_36 = "音樂！跟上節奏！",
  str_voice_1500901_37 = "真心熱鋸！",
  str_voice_1500901_38 = "搖滾甜心！",
  str_voice_1500901_39 = "啦啦啦～～嘟比嘟比噠～～",
  str_voice_1500901_40 = "心心戀戀～～",
  str_voice_1500901_41 = "為我應援吧！",
  str_voice_1500901_42 = "再一首？芭芭拉聽見啦～",
  str_voice_1500901_43 = "芭芭拉，無論摔倒多少次，都要爬起來繼續走下去。",
  str_voice_1500901_44 = "能不能在這裡辦一場演唱會呢～",
  str_voice_1500901_45 = "禮物要統一交給經紀人喔～",
  str_voice_1500901_46 = "你給的禮物——我就偷偷收下啦。",
  str_voice_1500901_47 = "芭芭拉也送你一份簽名照好了。",
  str_voice_1500901_48 = "不、不行，偶像是戀愛禁止的，可是……",
  str_voice_1500901_49 = "芭芭拉當然也經歷過痛苦的事情，那個時候是音樂拯救了芭芭拉。現在，我也想用音樂拯救大家！",
  str_voice_1500901_50 = "成為偶像的道路艱辛又漫長，可是芭芭拉不會放棄。開著車在沙漠裡巡迴表演，一點一點累積人氣，只要有一個人露出微笑，芭芭拉就會感到幸福。",
  str_voice_1500901_51 = "因為過人的偶像實力和超——努力的精神，芭芭拉現在已經有了很多粉絲啦！但是呢，蕾吉娜總是想超越芭芭拉！",
  str_voice_1500901_52 = "白夜極光！",
  str_voice_1500901_53 = "嗨——！",
  str_voice_1500901_54 = "早安，打起精神來～",
  str_voice_1500901_55 = "嗨！讓我看見你的熱情——",
  str_voice_1500901_56 = "愛的演唱會！要開始囉！",
  str_voice_1500901_57 = "新年——快樂——",
  str_voice_1600011_1 = "有什麼緊急的事情嗎？看你的樣子也不像是有什麼正事吧？……如果真的沒有，那我先失陪了。",
  str_voice_1600011_2 = "你現在說的事情那麼重要嗎？這個距離……太近了……",
  str_voice_1600011_3 = "自律是莫大的美德，我的意思是——無論鏡子還是花瓣都別亂碰好嗎？",
  str_voice_1600011_4 = "從前，白水仙總是凝視鏡湖……另一朵花呢？另一朵花，是什麼？",
  str_voice_1600011_5 = "北國之花與明鏡，重新連接的兩個世界，到底哪邊才是真實的呢？",
  str_voice_1600011_6 = "白水仙再次盛放，我們，雙生的鏡影，接續古老的寓言，於此進行我們的故事。",
  str_voice_1600011_7 = "如果不能順其自然，就只好彼此勉強，你難道希望這種事發生嗎？",
  str_voice_1600011_8 = "我會稍微感謝你一點，但無法為你帶來更大的利益。這樣，也可以嗎？",
  str_voice_1600011_9 = "如果有一天我們能找回自己……但願新的記憶裡也依然有你。",
  str_voice_1600011_10 = "閒適的日子，就連天空都是淨藍的～",
  str_voice_1600011_11 = "你的表情也不像是可以拒絕的樣子……",
  str_voice_1600011_12 = "保持距離，注意言行，這樣一來，姐姐也會稍微接受你一點。",
  str_voice_1600011_13 = "該不會要我誇你吧？……讓我思考一下。",
  str_voice_1600011_14 = "如同小石頭落入湖中……我的心中，稍微有些不安。",
  str_voice_1600011_15 = "今天並不特別，我們只需要像往常那樣在一起，像往常一樣享有安寧。",
  str_voice_1600011_16 = "嗯？是因為我的事情而來嗎？",
  str_voice_1600011_17 = "嗯，我想到了，你的優點……能夠在正午前變得清醒。",
  str_voice_1600011_18 = "我聽到你回來的聲音了，所以不用特別的強調，就這樣。",
  str_voice_1600011_19 = "很明顯，你打擾到我了……所以，早點休息。",
  str_voice_1600011_20 = "北境是我們唯一能夠生存的地方，特別是對姐姐來說……",
  str_voice_1600011_21 = "遵照女王陛下的吩咐，我會用鏡子，好好關注白夜城的。",
  str_voice_1600011_22 = "暮冬而生。",
  str_voice_1600011_23 = "無需評論，那種普通的有害物質無法侵入北境。",
  str_voice_1600011_24 = "她便是北境，庇護所有純潔之物，這也是我敬仰她的原因。",
  str_voice_1600011_25 = "雖然她有點吵鬧，但女王說過，她為北境宮殿增添生氣，這是好事。",
  str_voice_1600011_26 = "白色的花朵，清閒的時間，乾淨的味道……姐姐。",
  str_voice_1600011_27 = "我討厭不乾淨的東西，連說出口都覺得厭惡。",
  str_voice_1600011_28 = "這樣潔淨的白色很難得，看得出你有在珍惜它。",
  str_voice_1600011_29 = "不要做出失禮的行為，不要說娜席里絲沒提醒你。真是的，果然北境之外皆為蠻荒。",
  str_voice_1600011_30 = "等待，更多花開。",
  str_voice_1600011_31 = "更清晰的是過去，還是未來？",
  str_voice_1600011_32 = "連接吧，兩個世界的命運！",
  str_voice_1600011_33 = "終於，跨越了遙遠維度。",
  str_voice_1600011_34 = "儘早結束吧。",
  str_voice_1600011_35 = "北國之花，正待盛放",
  str_voice_1600011_36 = "不用你來提醒……",
  str_voice_1600011_37 = "凋落與綻放——",
  str_voice_1600011_38 = "這是天國的春華——",
  str_voice_1600011_39 = "清淨一點。",
  str_voice_1600011_40 = "本該潔淨。",
  str_voice_1600011_41 = "北境的規矩是只說一遍。",
  str_voice_1600011_42 = "難道不是如你所願的完美嗎？",
  str_voice_1600011_43 = "真是的……衣服都被弄髒了……",
  str_voice_1600011_44 = "你喜歡白色的水仙花嗎？那就讓你多看一眼好了。",
  str_voice_1600011_45 = "果然不應該對你有所期待……哼。",
  str_voice_1600011_46 = "竟然還不錯？我收下了。",
  str_voice_1600011_47 = "預料之中的禮物，所以沒有期待。",
  str_voice_1600011_48 = "這次……還滿不錯的，感謝你一下好了。",
  str_voice_1600011_49 = "我忘了唯一的留戀與記憶，從此外面的世界怎麼樣都與我無關……",
  str_voice_1600011_50 = "每一瓣白花，每一處散落的花瓣，它們的時光不會回溯，正如我的愛亦無從追索。",
  str_voice_1600011_51 = "北國守護著世界的祕密，白水仙被封印的記憶，將是對大陸最後的警示。",
  str_voice_1600011_52 = "白夜極光。",
  str_voice_1600011_53 = "你……人呢？",
  str_voice_1600011_54 = "……早安。",
  str_voice_1600011_55 = "你無需過於掛心，只是……",
  str_voice_1600011_56 = "你若是正打算休息，那就算了……",
  str_voice_1600011_57 = "姑且祝你新年快樂吧。",
  str_voice_1600041_1 = "喂，小聲告訴我，我和那個大傢伙誰更受歡迎？……哈？怎麼可能？都瞎了嗎，明明企鵝才更可愛吧？",
  str_voice_1600041_2 = "有人嗎——！救命啊——啊，是你！快快快拿點肉罐頭來！再不開飯我就要被餓昏頭的庫瑪當做存糧吃掉了啊！",
  str_voice_1600041_3 = "哼哼，小看我們的話不會有好下場喔。我們是大陸小有名氣的傭兵，咳，尤其在那次意外爆破之前……",
  str_voice_1600041_4 = "巨像上就不能建一座游泳池嗎？庫瑪那傢伙愈來愈壯，帶著他偷鑽冰箱乘涼已經快鑽不進去了……",
  str_voice_1600041_5 = "-……好熱。\n-啊！我知道了我知道了！總之別倒在這裡！你這個白色的土包子超礙事，快起來！……真是的，喊到我都覺得熱了……",
  str_voice_1600041_6 = "-好無聊啊，來玩玩棒球打砲彈的遊戲吧？超級刺激！\n-好，來吧。\n-你要做什麼？離我一遠點！等等——！！",
  str_voice_1600041_7 = "喔吼～對我們的舞蹈有興趣嗎？看不出來你還滿有品味的嘛！誠心誠意拜師的話……也不是不能教你。嘿嘿。",
  str_voice_1600041_8 = "這個，味道不錯，分你。",
  str_voice_1600041_9 = "嘖，真……真拿你沒辦法，就特別允許你觸碰本大爺纖密柔順的羽毛好了……不要逆著摸啊！",
  str_voice_1600041_10 = "喂喂，你在發什麼呆呢？乾脆我們一起翹班，找個地方涼快一下去吧？",
  str_voice_1600041_11 = "找個地方睡個午覺吧。這傢伙的肚子靠起來很舒服喔，就像我現在……這樣……ZZZ",
  str_voice_1600041_12 = "不……不要戳我肚子！",
  str_voice_1600041_13 = "啊……我只是輕輕跳一下，地板就出現裂縫了。",
  str_voice_1600041_14 = "我們不是胖，是福態！福態！因為當傭兵賺的錢很多嘛！",
  str_voice_1600041_15 = "來來！開生日派對！跳舞！跳舞！",
  str_voice_1600041_16 = "唷！一起來嗨啊！",
  str_voice_1600041_17 = "早上吃什麼？有冰淇淋嗎？",
  str_voice_1600041_18 = "今天來得好晚啊，吃的呢吃的呢？",
  str_voice_1600041_19 = "嗝，我還想再吃一頓宵夜。",
  str_voice_1600041_20 = "到處走，沒人管，很好啊。",
  str_voice_1600041_21 = "紅油扳手的兄弟們簡直太嗨了，等有一天我們變得正常了，就要和他們一起去嗨！嗨！",
  str_voice_1600041_22 = "-極地！",
  str_voice_1600041_23 = "不能吃，好煩。",
  str_voice_1600041_24 = "真是搞不懂卡夫卡那個小丫頭！給我們留東西吃，卻又趕我們走！唉，女人！",
  str_voice_1600041_25 = "恐爾貢的鯊魚牙粉，很好吃，就是份量少了一點。",
  str_voice_1600041_26 = "結束工作，躺在冰塊上的那瞬間，就是……天堂。",
  str_voice_1600041_27 = "熱死了、熱死了、熱死了",
  str_voice_1600041_28 = "這裡真是奇怪的地方，什麼人都有，而且冷氣很舒服。",
  str_voice_1600041_29 = "唷吼吼！大陸最強搭檔在此！打架的事就交給我們，記得給足的食物就可以囉！",
  str_voice_1600041_30 = "我長高了！",
  str_voice_1600041_31 = "變強了！毛皮也更有光澤！",
  str_voice_1600041_32 = "感覺……不錯。",
  str_voice_1600041_33 = "嘿嘿，現在的我們無人能敵啦，搭檔！",
  str_voice_1600041_34 = "別扯我們後腿喔！",
  str_voice_1600041_35 = "庫瑪！準備發射！",
  str_voice_1600041_36 = "要瞄準一點啊！",
  str_voice_1600041_37 = "-來了！\n-等等！啊——",
  str_voice_1600041_38 = "-還有這一招！\n-已經無所謂了……",
  str_voice_1600041_39 = "偷襲！沒想到吧！",
  str_voice_1600041_40 = "炸～飛～！",
  str_voice_1600041_41 = "我們來打頭陣！",
  str_voice_1600041_42 = "沒有我們打不贏的架！",
  str_voice_1600041_43 = "搞砸了……可惡……",
  str_voice_1600041_44 = "……想喝冰啤酒。",
  str_voice_1600041_45 = "這能吃嗎？",
  str_voice_1600041_46 = "庫瑪！你看！我收到這個！",
  str_voice_1600041_47 = "這麼貴重，難道要有工作了？",
  str_voice_1600041_48 = "真好！給你吃我珍藏的罐頭。",
  str_voice_1600041_49 = "-北方啦，北方！你沒去過吧？那裡和這邊完～全不一樣，真想讓你也看看那裡的景色。對吧庫瑪？\n-沒錯。",
  str_voice_1600041_50 = "過去的事其實無所謂啦，只要能開開心心地填飽我自己和這傢伙的肚子就好，和庫瑪搭檔的旅程永遠不要結束就好。這種話說出來有點難為情……不，不准笑！",
  str_voice_1600041_51 = "-想不想看看過去的樣子！那時候我們的毛皮可不是這個顏色！我還會咯咯咯地叫呢。\n-真難聽。",
  str_voice_1600041_52 = "-白夜？\n-極光！！",
  str_voice_1600041_53 = "唷！正在找你！",
  str_voice_1600041_54 = "早啊！今天真是不錯！",
  str_voice_1600041_55 = "你也來？",
  str_voice_1600041_56 = "別睡啦！快來幫幫我！",
  str_voice_1600041_57 = "-新年？\n-會快樂啦，絕對快樂！",
  str_voice_1600051_1 = "一起喝杯茶嗎？帶新朋友一起，與我們度過人生最後的歡愉時刻吧——",
  str_voice_1600051_2 = "讓我為你的靈魂牽上絲線、一起在下午茶時間跳個痛快如何？來嘛——",
  str_voice_1600051_3 = "這個機械爪？碰到人之後一點也不痛喔，至少我從沒聽到誰「用過」之後來找我抱怨的……對吧～",
  str_voice_1600051_4 = "美妙的哭聲，它們是我的玩具、我的精靈。父親和妹妹都無法理解它們有多悅耳——你呢？",
  str_voice_1600051_5 = "光潔的貴族家有個後院，遺忘的後院裡有座舊墳，潮濕的舊墳底有個沉睡的女人，女人的笑容中——你看到了什麼？",
  str_voice_1600051_6 = "緊閉的石棺已經開啟，索求嗎？渴望嗎？那麼，將手從喉嚨中探出，去摘取鮮美的果實吧——",
  str_voice_1600051_7 = "那個眼神，你有什麼企圖？啊……還是說，想加入這個大——家庭、成為光鮮亮麗的皇族嫡系呢～",
  str_voice_1600051_8 = "好吧，我特別允許你靠近。但是如果抓壞我的裙擺，我就踩你的臉作為懲罰——可以吧～？",
  str_voice_1600051_9 = "恐懼，興奮，直直地盯著我的你，表情到底是哪一種？還是說——要我慢慢猜呢？真是個壞孩子啊……",
  str_voice_1600051_10 = "「每逢無光之夜，黑蜘蛛就會從墳墓中崛起、吞食那些迷路的市民……」誰寫的傳聞，太蠢了！",
  str_voice_1600051_11 = "喔？讓我待在這裡，不怕我嚇到別人嗎？在傳聞中，我可是墳墓裡的怪物呢。",
  str_voice_1600051_12 = "你剛才碰到我了對不對？……如果蜜雅出來，說不定會哭。",
  str_voice_1600051_13 = "想喝紅茶，想吃點心……想喝紅茶，想吃點心……",
  str_voice_1600051_14 = "這樣笑的話就會像芭芭雅嘎吧。嗯，畢竟都是我的臉。",
  str_voice_1600051_15 = "突然出現，不好意思，她說讓我來比較好……為你慶祝、生日。",
  str_voice_1600051_16 = "你，遲到了。去哪裡了？",
  str_voice_1600051_17 = "太早了！你不知道該在什麼時候來找我嗎？",
  str_voice_1600051_18 = "……難道你期待我說歡迎嗎？歡、迎——",
  str_voice_1600051_19 = "怪談的時間到了，要和我出去——看看黑蜘蛛嗎？",
  str_voice_1600051_20 = "你以為我屬於那裡嗎？那個看起來是白色的城池？怎麼可能——",
  str_voice_1600051_21 = "這些機械，那些研究者想必也樂在其中呢——當然，我很感謝他們。",
  str_voice_1600051_22 = "暗影於底。",
  str_voice_1600051_23 = "暗鬼？啊——那些傢伙，是可以隨意折磨的玩具～",
  str_voice_1600051_24 = "那可憐的妹妹，若是讓我站在她面前，她會是什麼表情呢？哈——",
  str_voice_1600051_25 = "雖然她總是佔用這副身體，但只要抱怨一下，她就會讓我出來的。",
  str_voice_1600051_26 = "怎麼了，想要討好我們嗎？那——拿紅茶和點心來吧。",
  str_voice_1600051_27 = "你覺得我怎麼樣，討厭嗎？怎麼了，你不是想聊這個話題嗎？",
  str_voice_1600051_28 = "這裡的某個地方，散發出讓我不愉快的氣味——",
  str_voice_1600051_29 = "過來，再過來一點，你的貴族小姐邀請你加入茶會呢！我和她，大家都笑得很開心的茶會喔——",
  str_voice_1600051_30 = "你對我很有興趣呢～不是嗎？",
  str_voice_1600051_31 = "妹妹，我們已經今非昔比了呢……",
  str_voice_1600051_32 = "臣服吧！我以你們的靈魂為食！",
  str_voice_1600051_33 = "我在刑罰的愛巢裡等你，卡蓮——！",
  str_voice_1600051_34 = "一起，玩嗎？",
  str_voice_1600051_35 = "比茶點還要美味……",
  str_voice_1600051_36 = "我、想、開、動、了——",
  str_voice_1600051_37 = "哭吧、叫吧，悅耳的靈魂！",
  str_voice_1600051_38 = "這甜膩的、恐懼的香氣！！",
  str_voice_1600051_39 = "無法逃脫的！",
  str_voice_1600051_40 = "刑罰——！",
  str_voice_1600051_41 = "屬於我一個人的，地獄遊樂場……",
  str_voice_1600051_42 = "如你們所願，收割你們。",
  str_voice_1600051_43 = "無聊無聊無聊！",
  str_voice_1600051_44 = "這條深色的裙子，我其實……不太喜歡。",
  str_voice_1600051_45 = "一副沒有誠意的樣子，是想被我撕爛嗎？",
  str_voice_1600051_46 = "討好我的樣子，真可愛。",
  str_voice_1600051_47 = "難道是想看我生氣的樣子嗎？",
  str_voice_1600051_48 = "你若總是這麼好……下一次，就讓她來感謝你吧。",
  str_voice_1600051_49 = "希、希望你沒有被我們嚇到，在白夜城的傳聞中，吞噬人魂的黑蜘蛛，確實就是我們……這其實是祕密，雖然她總是想說出來……",
  str_voice_1600051_50 = "什麼時候變成這樣的呢？父親還愛我的時候，母親還能陪在我身邊時候，妹妹還只會整天哭鬧的時候……戰爭還沒發生的時候。",
  str_voice_1600051_51 = "他準備將白夜城的祕密隨我一同埋葬——但總有一天它們會重新登場的……等著吧，父親大人……",
  str_voice_1600051_52 = "白、夜、極、光。",
  str_voice_1600051_53 = "你，過來！",
  str_voice_1600051_54 = "我有事找你！",
  str_voice_1600051_55 = "那、那個……你在嗎？",
  str_voice_1600051_56 = "你在幹嘛？",
  str_voice_1600051_57 = "哈，新年？你快樂嗎？",
  str_voice_1600101_1 = "怎麼啦，又不開心啦？你看小兔子來安慰你啦……是不是好點了～",
  str_voice_1600101_2 = "我一直悉心照料著一個無人問津的小世界，或許有朝一日，那個世界的力量會成為拯救我們的關鍵。",
  str_voice_1600101_3 = "既不細心也沒有責任感……只是長得高大一點還留了鬍子就可以被當成大人嗎？不對唷！",
  str_voice_1600101_4 = "「口袋世界」變得愈來愈不安分，稍不留神就會傷到身邊的人！女王陛下說過，一定要學會控制這種力量！加倍努力！",
  str_voice_1600101_5 = "我的糖果盒馬上就會變成敵人的棺材，我的力量好可怕呀、哇——",
  str_voice_1600101_6 = "這個世界將會有更多童話，這些童話會因為大家的夢想而充滿生命力！就像這本新誕生的一樣，記錄著我們的旅程！",
  str_voice_1600101_7 = "精靈當然是為女王陛下工作，記錄北境大地的故事就是我的職責～想看嗎？",
  str_voice_1600101_8 = "我在蓋糖果小屋，你覺得窗戶用什麼口味比較好？這是北境的習俗啦。",
  str_voice_1600101_9 = "你在問我的意見？！！我以為你一直都把我當成小孩子……嗚啊我好感動！",
  str_voice_1600101_10 = "快把那堆柴火移走，這裡禁止一切火源！嗯？我不管我不管，總之就是禁、止！",
  str_voice_1600101_11 = "你好！是要聽睡前故事嗎？這裡有《小雪人和十二顆星辰》、《精靈小屋》、《龍的孩子》……還有很多喔！想聽哪個？",
  str_voice_1600101_12 = "想看魔術嗎？看我的口袋，我現在就可以變出……當當！糖果！",
  str_voice_1600101_13 = "你想當什麼精靈？我可以在故事中把你寫成你希望的樣子唷！",
  str_voice_1600101_14 = "從我口袋中選一樣東西吧！然後把它送給你珍視的人！",
  str_voice_1600101_15 = "祝你生日快樂！！雪人、糖果、童話書、小樹苗、送你什麼好呢？",
  str_voice_1600101_16 = "歡迎回來，外出辛苦啦，先吃顆糖果補充能量吧～",
  str_voice_1600101_17 = "嗚哇——早安，我昨天好像夢見糖果大船……你呢？",
  str_voice_1600101_18 = "我們去找個溫暖的地方，一起坐著，一起吃糖，一起看故事書吧。",
  str_voice_1600101_19 = "嗯……？怎麼了？睡不著嗎？我講故事給你聽吧？",
  str_voice_1600101_20 = "北境就好像是童話故事中的森林一樣，有各式各樣的精靈。",
  str_voice_1600101_21 = "嗯……我從來沒有去過別的地方，但我知道故事裡的地下小屋！",
  str_voice_1600101_22 = "暮冬～而生。",
  str_voice_1600101_23 = "牠們也有在故事中出現，是會一點一點漫過來的黑色海水！",
  str_voice_1600101_24 = "小諾爾，超可愛！而且還是童話故事的原型唷，我應該讀給你聽過吧？",
  str_voice_1600101_25 = "姐姐總是靜靜地看著鏡子，就好像故事中的白水仙一樣呢。",
  str_voice_1600101_26 = "童話、糖果、糖果紙、手工製作糖果屋，我喜歡的東西可多啦！",
  str_voice_1600101_27 = "嗯……討厭不知道如何描述的東西，既不能記錄下來，也沒辦法說。",
  str_voice_1600101_28 = "巨像更像童話故事中的巨龍，跟我見到的其他龍都不一樣呢！",
  str_voice_1600101_29 = "你看起來很有故事的樣子，你會介意我把你寫成主角嗎？說不定會在北境變成暢銷書喔～！",
  str_voice_1600101_30 = "口袋快裝不下了！",
  str_voice_1600101_31 = "來囉來囉！大——遊行要開始囉！！",
  str_voice_1600101_32 = "一起加入這夢幻旅程吧！",
  str_voice_1600101_33 = "大家所希望的全部，都在童話中！",
  str_voice_1600101_34 = "新故事的素材！",
  str_voice_1600101_35 = "精靈們！為了女王陛下的榮耀！",
  str_voice_1600101_36 = "大鬧一場吧！！",
  str_voice_1600101_37 = "獻給童話的國度！",
  str_voice_1600101_38 = "美妙的夢境再次啟航！",
  str_voice_1600101_39 = "要珍惜書本呀！",
  str_voice_1600101_40 = "破壞行為禁止！",
  str_voice_1600101_41 = "精靈小隊，集合！",
  str_voice_1600101_42 = "真厲害！這可以寫進故事裡了！",
  str_voice_1600101_43 = "嗚啊，這樣就不好玩了啊……",
  str_voice_1600101_44 = "我教你變魔術好不好？先變一個盒子，再放些糖果進去！",
  str_voice_1600101_45 = "你忘啦～？我可是創造系呀。",
  str_voice_1600101_46 = "這是我創造不出來的東西！超感謝！",
  str_voice_1600101_47 = "我也變個禮物回送給你吧？",
  str_voice_1600101_48 = "哇塞！超開心！一萬個感謝！",
  str_voice_1600101_49 = "保姆莉塔就是我唯一的家人，她常講我小時候的故事給我聽。真是太危險了，一不小心我的小命就沒了。",
  str_voice_1600101_50 = "爸爸媽媽總是在遠行，聽說好像去了很遠很遠的地方。對，要爬過冰封的雪山，不知道會不會遇見冰雪精靈？",
  str_voice_1600101_51 = "那些不應該出現在童話書裡的章節就應該刪掉……童話世界的結局總是美好的，我們的故事也是，會有好結局的唷～",
  str_voice_1600101_52 = "白夜～極光。",
  str_voice_1600101_53 = "你好呀～",
  str_voice_1600101_54 = "唔……早安～",
  str_voice_1600101_55 = "我有糖果想跟你分享～",
  str_voice_1600101_56 = "那個，我睡不著……",
  str_voice_1600101_57 = "祝你新年快樂唷～",
  str_voice_1600111_1 = "為何而戰？我以血火之仇為食，但這恐怕不是你要的答案吧。",
  str_voice_1600111_2 = "火藍之劍以敵人的恐懼為食，但這雙翼與龍鱗則不然，因為邪物永遠觸碰不到它們。",
  str_voice_1600111_3 = "龍族之怒與緋所掌握的劍道有許多相同之處——永恆、致命、絕對無情。但距離大元帥，還有很遙遠的距離……",
  str_voice_1600111_4 = "我將對古老君王與那不潔殘物，降下審判！你最好不要與之有任何瓜葛——",
  str_voice_1600111_5 = "龍心乃淬火的殺意，莫問我等為何毫無憐憫，那是弱者的墓誌銘。",
  str_voice_1600111_6 = "光與影鑄成真龍兩面，生或死，皆為滾滾宏聲！復仇之血，已升騰而起——",
  str_voice_1600111_7 = "是的，我的血液之中還流淌仇恨以外的事物，謝謝你讓我重新意識到這件事。上一個做到的人是大元帥。",
  str_voice_1600111_8 = "我知道涅墨西斯、貢露他們是怎麼看我的，但是……起碼在這裡，我不希望你也如此。",
  str_voice_1600111_9 = "你為這顆疲累的心臟帶來希望，現在我要為你做同樣的事情。加油，同胞！！",
  str_voice_1600111_10 = "危險會趁我們鬆懈之時襲來。巨龍就算沉睡，也會睜開一隻眼睛。",
  str_voice_1600111_11 = "胃口不小啊，但願你的膽識也是一樣。",
  str_voice_1600111_12 = "有什麼事？長話短說，我還有公務要處理，時間不多。",
  str_voice_1600111_13 = "打招呼的方式都不記得嗎？別抖，站好！",
  str_voice_1600111_14 = "想要提升自己的能力？很好，我會為你擬定訓練計劃，明天早上六點來我房間！",
  str_voice_1600111_15 = "對於堅持奮戰的人，理應有所表示，所以過來坐下吧，我的同胞。",
  str_voice_1600111_16 = "你來了。正好，一起行動吧，把握出擊時間，擬定好計劃就走。",
  str_voice_1600111_17 = "很好，珍惜訓練的時間，事不宜遲，我們趕快開始吧。",
  str_voice_1600111_18 = "打起精神來，現在不是鬆懈的時候！",
  str_voice_1600111_19 = "想要擁有強健體魄就需要充分休息，去睡吧，我守在這裡。",
  str_voice_1600111_20 = "在我迷惘時，啟光向我展示新的信念，幫助我不被仇恨吞噬。",
  str_voice_1600111_21 = "對那座浮空城，我族已仁至義盡，剩下的只有失望，以及和莫名的仇恨。",
  str_voice_1600111_22 = "為了啟明之光！",
  str_voice_1600111_23 = "仇恨敵人，消滅敵人，這是無可爭論的，鐵與血的事實。",
  str_voice_1600111_24 = "她勇猛強大，意志堅定卻又不被意志本身所左右，我離她，還很遠。",
  str_voice_1600111_25 = "我從她身上見不到任何名為意志的東西，那隻懶貓到底在想什麼？",
  str_voice_1600111_26 = "除了訓練之外……這是我族的族徽，它帶給我力量。",
  str_voice_1600111_27 = "尾巴的事無所謂，我真正厭惡的是腐朽制度與殘暴統治。",
  str_voice_1600111_28 = "你，會凝視這座巨像嗎？就像我常常凝視我族的族徽一樣。",
  str_voice_1600111_29 = "沒見過我等相貌的光靈？好吧……這不怪你，我們的數量確實不多，即便在過去也是如此。希羅娜，參上，請多指教。",
  str_voice_1600111_30 = "劍藝更加純粹。",
  str_voice_1600111_31 = "我族的遺落之血在沸騰！",
  str_voice_1600111_32 = "我的劍與雙眼，早已燃起火焰。",
  str_voice_1600111_33 = "隕落之王的舊堡，必將鑄成鐵棺！",
  str_voice_1600111_34 = "都抬起頭來！",
  str_voice_1600111_35 = "可以用真實的樣子戰鬥了嗎？",
  str_voice_1600111_36 = "我已忍讓多時……",
  str_voice_1600111_37 = "龍說，判你死刑！",
  str_voice_1600111_38 = "在光影中碎裂吧——",
  str_voice_1600111_39 = "龍息！",
  str_voice_1600111_40 = "消失吧！",
  str_voice_1600111_41 = "有不服者，最好現在說出來。",
  str_voice_1600111_42 = "陷於殺戮，但……無比甘甜。",
  str_voice_1600111_43 = "你們……有讓我毀滅殆盡的價值……",
  str_voice_1600111_44 = "我看見你的努力了，現在就當作是休息時間吧。",
  str_voice_1600111_45 = "這種東西……好吧，還是謝謝了。",
  str_voice_1600111_46 = "很細心，值得讚賞！謝了，同胞！！",
  str_voice_1600111_47 = "謝了，又讓你費不必要的心意。",
  str_voice_1600111_48 = "我的同胞，我珍惜你的情誼，永遠！",
  str_voice_1600111_49 = "若我族歸來，當下的一切都將變得脆弱又不值一提。但那也只是如果，發生的事，已不能重寫……",
  str_voice_1600111_50 = "龍族是罪惡和殘暴時代的見證，白夜的歷史卻不肯承認它。若不是遇到啟光，遇到大元帥，我又該於何處容身……",
  str_voice_1600111_51 = "他們說，龍火將覆滅一切，包括我們的記憶與歷史。有趣，彷彿螻蟻懼怕星火般，罪人們意外地擁有如此明智的覺悟？",
  str_voice_1600111_52 = "白夜極光！",
  str_voice_1600111_53 = "我的同胞。",
  str_voice_1600111_54 = "把握時間，提早進行。",
  str_voice_1600111_55 = "午休已過，打起精神來！",
  str_voice_1600111_56 = "時間不早了，我簡單陳述。",
  str_voice_1600111_57 = "祝賀，新年已至！",
  str_voice_1600191_1 = "預言已至，必須要向真理之主獻上禮物，叫聖釘前來吧，否則，他又會過度懺悔了。",
  str_voice_1600191_2 = "真理之典是完美的，可惜那位審判者與他效忠的宮廷不懂得欣賞，真是遺憾。",
  str_voice_1600191_3 = "販賣靈魂？非也，我只是收留無主的心靈，送去真理的國度。",
  str_voice_1600191_4 = "還需要更多的奉獻，我們才可以進入真理的領域。當然，我們所崇信的「真理」各有不同……",
  str_voice_1600191_5 = "對生之甘露的貪婪被視為一種美德。當然，沉於甘露則會以瘋狂終結。",
  str_voice_1600191_6 = "聽著，為罪而埋葬之聲即將復活，如赤色烈日般重臨於大地，從此，將再無未被拯救之人！",
  str_voice_1600191_7 = "「我也有這樣的一面？」這可以當作對我的恭維嗎？",
  str_voice_1600191_8 = "我應該帶您去看看夜色，或許您會喜歡。那些年輕的生命，會在黑暗中一如既往地亢奮，探尋通往升格的道路。",
  str_voice_1600191_9 = "氣氛變得有些微妙呢……這是您想要的嗎？可不要讓牆後的耳朵發現……那可能會引起嫉妒喔……",
  str_voice_1600191_10 = "倦意都爬上額頭了呢，這裡就先交給我吧……只要您最終能跟隨我的步伐，一時的容忍倒也無礙……",
  str_voice_1600191_11 = "您似乎對古老生物有些特別的興趣……無妨，還請多多與我在一起吧。",
  str_voice_1600191_12 = "我可以慢慢教您，但那之前，您需要更努力地取悅我才行。",
  str_voice_1600191_13 = "想聽有關真理的宗旨嗎？我們向來提倡，用心的宣道……",
  str_voice_1600191_14 = "想聽些特別的聲音嗎？關於不老不死永生者的故事……",
  str_voice_1600191_15 = "我祝福您，年輕的生命，飲下這杯為您準備的甘露，與我同生吧？",
  str_voice_1600191_16 = "日光正盛之時，果然容易讓人怠惰……當然，您不用擔心我。",
  str_voice_1600191_17 = "對於某些存在來說，現在是準備休息的時間……您，打算一起來嗎？",
  str_voice_1600191_18 = "在逐漸清醒的時間裡，我總想來一杯溫暖的……您的問候。",
  str_voice_1600191_19 = "在這個時間活動，看來您也有晝伏夜出的天賦呢。",
  str_voice_1600191_20 = "您應當明白，真理是通往未來的道路，正確的指引會帶來安定。",
  str_voice_1600191_21 = "善與惡都是白夜城示人的面龐，而裁決之日會坦露那殘暴的真相。",
  str_voice_1600191_22 = "願真理，祝福您。",
  str_voice_1600191_23 = "當我確認牠們同是這世界的造物時，我看見了分隔於真理兩端的景象。",
  str_voice_1600191_24 = "浮士德是優秀的傳達者，在真理面前，他並非我的部下。",
  str_voice_1600191_25 = "我並不討厭頑固的人，就像在與石頭對話一般，我享受這份樂趣。",
  str_voice_1600191_26 = "我所喜愛之物，生命的甘露、古籍、以及被稱為「遺物」的武器。",
  str_voice_1600191_27 = "我並沒有厭惡之物，因為真理會平等地接納一切。",
  str_voice_1600191_28 = "在我看來，他們是連接通行的巨木，也是上古的密宗，接近著根源。",
  str_voice_1600191_29 = "眾人在血液之中，均有專屬於自己的情感與回憶……啊，真想早點瞭解您的「味道」呢。",
  str_voice_1600191_30 = "這是，新鮮的生命力～",
  str_voice_1600191_31 = "找到了，突破生命臨界點的方法——",
  str_voice_1600191_32 = "我將成為位階更高的存在——",
  str_voice_1600191_33 = "以瘋後之名，我將進入深紅的大殿——",
  str_voice_1600191_34 = "真理的影響將會更深。",
  str_voice_1600191_35 = "只需一個時機……",
  str_voice_1600191_36 = "皆當遵循指引……",
  str_voice_1600191_37 = "深紅！芒刺！鎮魂歌！",
  str_voice_1600191_38 = "見證、神蹟——！",
  str_voice_1600191_39 = "傾聽真理——",
  str_voice_1600191_40 = "感受真理——",
  str_voice_1600191_41 = "在你們被我支配之前，動起來。",
  str_voice_1600191_42 = "勝利的滋味，有如鮮活的生命般美好。",
  str_voice_1600191_43 = "累了，有把握的時候再喚我吧。",
  str_voice_1600191_44 = "沒有什麼比看見鮮活的您，更令人開心的事了……",
  str_voice_1600191_45 = "又拿來新玩具了呢，倒是沒少費心思……",
  str_voice_1600191_46 = "對我的喜好很敏銳呢，難不成想要「獎賞」嗎～？",
  str_voice_1600191_47 = "我當然會收下，這可是您重要的奉獻……",
  str_voice_1600191_48 = "作為獎勵，我會為您準備一些特別的東西……",
  str_voice_1600191_49 = "必須阻止它發生，升格的殊榮、覬覦的眼神並存……但我猜想，您大概很難理解它。",
  str_voice_1600191_50 = "血脈不過是一種提示，指引我走上追尋的路徑——賜予「永生」與「枯萎」，必定有真理的意義。",
  str_voice_1600191_51 = "吸血鬼？不，這並非與生俱來，而是某種恩賜。黑色典籍將這一切化作低語，在受恩之人的耳旁迴盪。",
  str_voice_1600191_52 = "白夜極光。",
  str_voice_1600191_53 = "那麼……",
  str_voice_1600191_54 = "對於您，該說早安吧。",
  str_voice_1600191_55 = "午安，您該放鬆一些。",
  str_voice_1600191_56 = "昏昏欲睡了嗎？",
  str_voice_1600191_57 = "新年，是屬於您的。",
  str_voice_1600251_1 = "哼……靈魂的孤獨與真正的藝術，本來就沒有幾個人能理解。藝術家都是孤獨的，我不適合團隊合作……",
  str_voice_1600251_2 = "唉……沒空啊。想看舞台劇？找了好多人？真的？——那我就破例再演出一次吧——",
  str_voice_1600251_3 = "接到噪音投訴？誰說我的老朋友是噪音？真是不懂欣賞的凡夫俗子啊……",
  str_voice_1600251_4 = "你看，「感受來自地獄列車的恐懼吧！」這樣一喊，我的老朋友就會衝出來。想看嗎？",
  str_voice_1600251_5 = "我永遠無法獲得寧靜，那是無止盡的詛咒，那是孤獨者的狂歡……",
  str_voice_1600251_6 = "聚焦吧！這正是最盛大的演出！卡戎和彼岸號，還有無數渴望生之演繹的靈魂，從地獄歸來！",
  str_voice_1600251_7 = "請稍等我一下……紅茶和小點心已經為你準備好了，親愛的觀眾，請就位！",
  str_voice_1600251_8 = "你孤身一人，逃得如此之快，走得如此之遠，為何不帶我一起？你要知道，無論你是什麼，無論你做什麼，我都永遠站在你這邊……",
  str_voice_1600251_9 = "遇見大元帥的那段時光是我這輩子最快樂的日子，彷彿得到了救贖……現在又讓我遇見了你！命運的劇本完成了！",
  str_voice_1600251_10 = "「命數已盡的人！掙扎吧，吶喊吧，你因恐懼而狂亂的臉龐，將成為我今夜的……」唔，這裡不太順口。",
  str_voice_1600251_11 = "夢幻般地劃開暗夜，我會助你駛向光芒的方向，可以讓我永遠站在這裡嗎？",
  str_voice_1600251_12 = "我只要有彼岸號就夠了，其他的朋友……沒有也罷。",
  str_voice_1600251_13 = "到了預定的車站，人們就會下車，大家都一樣……",
  str_voice_1600251_14 = "彼岸號好像也很中意你，那麼，就在舞台上為你留個位置吧！",
  str_voice_1600251_15 = "盛大的戲劇開幕！今天的主角是你！不要客氣，跳起來吧，哈哈！",
  str_voice_1600251_16 = "惡靈列車，已為你待命。",
  str_voice_1600251_17 = "真是的，這麼早就特別為我準備好了華麗的舞台嗎！",
  str_voice_1600251_18 = "我們已經步入了下一個舞台！來！你也一起吧！",
  str_voice_1600251_19 = "你來得正好，惡靈列車即將發車，若是想去彼岸就上車吧！",
  str_voice_1600251_20 = "我們和啟光很有緣分，兩度來此，現在是永遠的回歸地了。",
  str_voice_1600251_21 = "追求不過是自我意識的表現，強加並不是真理。",
  str_voice_1600251_22 = "為了啟明——之光！",
  str_voice_1600251_23 = "從地獄歸來的我們，將正面迎接曾經的恐懼。",
  str_voice_1600251_24 = "關於她的事我不敢多說什麼，畢竟有輸在先，但若是列車操縱……",
  str_voice_1600251_25 = "洞悉一切，義無反顧踏上孤獨的道路，這才是天才的領導者。",
  str_voice_1600251_26 = "孤獨的舞台、自由的生活、搖滾列車之旅，這一切都是我所熱愛的！",
  str_voice_1600251_27 = "藝術家的生活裡，不該存在沒品味的瘋子。",
  str_voice_1600251_28 = "就像彼岸號與我一樣，這座巨像也是你的夥伴吧。",
  str_voice_1600251_29 = "我就是惡靈和冥界的擺渡人，我不是地獄骷髏也不是光明始徒，我是卡戎，在血染的世界中無畏地飛馳。",
  str_voice_1600251_30 = "加快速度飛馳吧！",
  str_voice_1600251_31 = "前方到站、冥河。",
  str_voice_1600251_32 = "開往地獄的班次已經出發！",
  str_voice_1600251_33 = "這便是亡靈的專車呀哈哈！",
  str_voice_1600251_34 = "沒想到、還能……",
  str_voice_1600251_35 = "傾聽！這刺耳的鳴笛聲！",
  str_voice_1600251_36 = "動力滿格！",
  str_voice_1600251_37 = "地獄號！開動！",
  str_voice_1600251_38 = "亡、魂、借、道——",
  str_voice_1600251_39 = "動力測試！",
  str_voice_1600251_40 = "獄火訊號！",
  str_voice_1600251_41 = "聚光！你們的主角登場！",
  str_voice_1600251_42 = "我們來自地獄，怎麼可能會輸。",
  str_voice_1600251_43 = "逃跑吧，快抓住我的手！",
  str_voice_1600251_44 = "想看戲劇的下一幕嗎？來，說你想看！",
  str_voice_1600251_45 = "上次收到禮物，彷彿是上個世紀的事了……",
  str_voice_1600251_46 = "喔喔喔！難不成是知音相贈？！",
  str_voice_1600251_47 = "贈禮，這是多麼感人的一幕呀！",
  str_voice_1600251_48 = "太美妙了，這可是——來自親友的禮物！",
  str_voice_1600251_49 = "當你受到誤解、被過往的朋友疏遠，又能怎麼樣呢？偶爾自己喝點小酒，也不用惦念別人，這樣的日子不也很開心嗎！",
  str_voice_1600251_50 = "我永遠忘不了，母親映在車窗後的容顏……讓人忘記時間，我能一直這樣看下去……",
  str_voice_1600251_51 = "家人以前很寵我，但那個時候他們不明白，彼岸號也是我的家人，那個艱難時刻的抉擇簡直是造化弄人……",
  str_voice_1600251_52 = "白夜——極光！",
  str_voice_1600251_53 = "朋友唷！",
  str_voice_1600251_54 = "華麗的！早晨！",
  str_voice_1600251_55 = "請注目！",
  str_voice_1600251_56 = "現在正是！演出時間！",
  str_voice_1600251_57 = "這是！新年的新聲音！",
  str_voice_1600261_1 = "從燃燒的棺木里誕生，行走在虛無的土地上。那些破碎的肢體……這多麼沒道理，又無意義……",
  str_voice_1600261_2 = "我見過它焚盡文明的樣子，就是你腳下的它。也許你真的擁有滌蕩罪業的天賦……吧。",
  str_voice_1600261_3 = "別安慰我，我不傷心。不要像那些人一樣膚淺地關懷，求你了，不要。讓我一個人待著就好。",
  str_voice_1600261_4 = "皮膚和面容閉合、痊癒……我是逆行的生命。但碎過的軀體永遠帶有裂痕，永遠……",
  str_voice_1600261_5 = "末日從我身上碾了過去，就像穿進指甲裡的竹刺。現在它也依然壓著我的胸口，不過是從裡……向外……",
  str_voice_1600261_6 = "父親、母親……現在的我雖滿身瘡痍和痛楚，卻有了繼續戰鬥下去的理由……請你們繼續包裹著我、終有一日我將與你們再會……",
  str_voice_1600261_7 = "想聽聽舊日的故事嗎？關於我曾死去、走過淨界的故事……",
  str_voice_1600261_8 = "我的胸口像一口井，永遠燃燒、痛徹骨髓的火牢。它關押著什麼呢？要不要撕開、看一看？",
  str_voice_1600261_9 = "來，湊近點，趴在我胸口上。聽見了嗎？那是舊日之火的聲音……好了，在你也陷入淨界之前，退後吧。",
  str_voice_1600261_10 = "我又陷入了虛無。不對，也許這才是生命的常態。就像有的阿姨喜歡蝸居籠中，我也許就應該蜷縮在此自言自語吧。",
  str_voice_1600261_11 = "這裡……我並不反感。你的目光不像其他人，沒有那種虛偽的刺痛感。",
  str_voice_1600261_12 = "若是能永遠待在桶子裡就好了……那裡聽不見哀嚎，也聽不見尖叫。",
  str_voice_1600261_13 = "又被安排了無聊的工作……希望不會有人來監督……",
  str_voice_1600261_14 = "有人說話嗎……還是說，又是，我的錯覺嗎？",
  str_voice_1600261_15 = "今天就是你重生的日子嗎……你會痛嗎？不會痛就好了。",
  str_voice_1600261_16 = "又來了。不同於突然造訪的死亡，你總是很準時。",
  str_voice_1600261_17 = "又要面對新的一天了嗎，經歷這一切又是為了什麼呢……",
  str_voice_1600261_18 = "火獄稍微平息了……接下來，將會有更加刺耳的聲音吧。",
  str_voice_1600261_19 = "這個時間……該沉睡的沉睡了，要甦醒的甦醒了……胸口，痛。",
  str_voice_1600261_20 = "它也是在烈火中重生的土地。白色的……和記憶中一樣。",
  str_voice_1600261_21 = "在一切結束之前，我記得那穿著長衣的人...... 我還未來得及説聲，謝謝......",
  str_voice_1600261_22 = "白夜……至上。",
  str_voice_1600261_23 = "來自地獄的東西……就該回歸地獄。",
  str_voice_1600261_24 = "不小心，燒掉了阿姨的裙擺和樹枝……十分困擾吧……抱歉……",
  str_voice_1600261_25 = "那是雷電的裂痕……但她的眼神，說了……沒關係。",
  str_voice_1600261_26 = "喜歡……不太明白……但，能夠什麼都不想，只是待著就好了。",
  str_voice_1600261_27 = "不明白……存在的意義到底是什麼？意義……是什麼？",
  str_voice_1600261_28 = "很相似……巨像裡的能量，和這裡的業火。",
  str_voice_1600261_29 = "我叫烏列爾。我只是在漫無目的地燃燒生命而已。你可以嘗試為我的軀體賦予意義，但別抱太大的期望。",
  str_voice_1600261_30 = "還在做這些無謂之事。",
  str_voice_1600261_31 = "刺痛……它在失控……",
  str_voice_1600261_32 = "這到底是力量，還是一種詛咒……？！",
  str_voice_1600261_33 = "不要那樣看著我！這裡是地獄！！",
  str_voice_1600261_34 = "大家，不要太靠近我喔。",
  str_voice_1600261_35 = "淨界的容量已到高峰——",
  str_voice_1600261_36 = "胸口……快要裂開了……",
  str_voice_1600261_37 = "向你再度展現末日——",
  str_voice_1600261_38 = "帶你前往嶄新的地獄——",
  str_voice_1600261_39 = "渡化——",
  str_voice_1600261_40 = "向虛無……",
  str_voice_1600261_41 = "恐怕，連灰燼都不會留下……",
  str_voice_1600261_42 = "羨慕這些終於解脫的靈魂。",
  str_voice_1600261_43 = "會有嗎？能容納地獄的，更大的地獄？",
  str_voice_1600261_44 = "你不懼怕淨界的力量嗎？……讓人很好奇呢……",
  str_voice_1600261_45 = "……為什麼要給我東西呢。",
  str_voice_1600261_46 = "喔？這個似乎有點意思呢。",
  str_voice_1600261_47 = "抱歉，這個……談不上喜歡呢。",
  str_voice_1600261_48 = "啊，這個……有點喜歡。謝謝……",
  str_voice_1600261_49 = "我從燃燒的棺木裡誕生，行走在虛無的土地上，又住進白夜的囚籠裡。",
  str_voice_1600261_50 = "或許我們都在戰爭爆發那天死去了，現在的一切都是靈魂幻滅前的泡影。那可就太無趣了。",
  str_voice_1600261_51 = "我從不回顧往事，因為我已經死過一次、兩次、無數次，我與淨界已經合一，我與地獄將永不分離。",
  str_voice_1600261_52 = "白夜……極光。",
  str_voice_1600261_53 = "那個……",
  str_voice_1600261_54 = "那個，你……在嗎？",
  str_voice_1600261_55 = "你有……時間嗎？",
  str_voice_1600261_56 = "這個時間，你還在嗎……",
  str_voice_1600261_57 = "新年……也不是很快樂。",
  str_voice_1600271_1 = "聽見我內心的鳴響了吧？這應是某種必然。我會珍惜這份羈絆的。",
  str_voice_1600271_2 = "閃電、雷鳴，讓許多人對我望而卻步，也拒絕聆聽來自面罩下的傾訴。你不同，導航員。",
  str_voice_1600271_3 = "……不用擔心我的忠誠。就算我曾背棄過很多人，但如果卡蓮決定信任你，那我當然不會有一絲異心。",
  str_voice_1600271_4 = "想起了一些過去的事情。但那都不再是米迦勒的故事了，而且現在不是閒聊的時候。",
  str_voice_1600271_5 = "雷鳴的聲音更大了，它響徹我的頭腦和軀體。但是路途清晰，我不會再像從前那樣有絲毫遲疑。",
  str_voice_1600271_6 = "用力量維護秩序，以規則改造世界——現在如此，以後亦將如此。一同走到現在，我很感激，謝謝。",
  str_voice_1600271_7 = "與無法開口的對象建立羈絆，我理解這份不易。我會珍惜的。",
  str_voice_1600271_8 = "感謝你的執著，導航員。如果我的心聲時而飄忽不定，請原諒我——那只是有些往事死灰復燃而已。",
  str_voice_1600271_9 = "雖渴望更多的交流，但這樣的我也許無法做到……你能聽到我靜默的訴說，已實屬萬幸，我本該別無所求。",
  str_voice_1600271_10 = "要不要讓這傢伙打起精神來呢……啊，抱歉，忘了你聽得見。",
  str_voice_1600271_11 = "監察、整頓、糾錯、執行。什麼時候開始工作？",
  str_voice_1600271_12 = "只有與我身處同一段命運中的人，才能聽見這聲音。",
  str_voice_1600271_13 = "……嗯？剛才正在冥想，抱歉沒注意到你。",
  str_voice_1600271_14 = "接近我時，你不怕嗎？……和拉斐爾一樣，不怕觸電？",
  str_voice_1600271_15 = "今天是重要的日子，來慶祝吧，你對什麼有興趣？",
  str_voice_1600271_16 = "早安，導航員。有新的指令嗎？",
  str_voice_1600271_17 = "早安，我已在你睜眼之前完成該做的事，等待你新的指令。",
  str_voice_1600271_18 = "導航員，我隨時都在等待你的指令，請不用擔心。",
  str_voice_1600271_19 = "晚安，請放心，我正在等待你的指令。我記得確實該說……晚安。",
  str_voice_1600271_20 = "我會履行自己的道義。對白夜城的忠誠，亦是出於此。",
  str_voice_1600271_21 = "感謝拉斐爾的治療，感謝啟光的幫助……能讓我脫胎換骨。",
  str_voice_1600271_22 = "白夜至上。",
  str_voice_1600271_23 = "只要有命令，我就會消滅牠們。",
  str_voice_1600271_24 = "她似乎聽不見我的聲音，但她虛無的火焰，確實在那時消散了。",
  str_voice_1600271_25 = "啟光那位追求力量的人，這種感覺，或許能稱為——熟悉。",
  str_voice_1600271_26 = "喜歡就是，我覺得很有意思。",
  str_voice_1600271_27 = "我已經告別了我所厭惡的東西，不再回頭。",
  str_voice_1600271_28 = "導航員，巨像體積龐大，切勿亂停亂放。",
  str_voice_1600271_29 = "我是米迦勒，靜默雷電的駕馭者。無論你是否可以聽到我的話，自我介紹結束，該做事了——",
  str_voice_1600271_30 = "我發生了變化。",
  str_voice_1600271_31 = "不用在乎其他枝微末節的東西。",
  str_voice_1600271_32 = "雷電進一步甦醒了。",
  str_voice_1600271_33 = "在米迦勒面前顫抖吧！",
  str_voice_1600271_34 = "速戰速決。",
  str_voice_1600271_35 = "雷電，蓄勢待發。",
  str_voice_1600271_36 = "指引我。",
  str_voice_1600271_37 = "你，想要與雷電競速嗎？！",
  str_voice_1600271_38 = "在雷鳴的通途之中，裂解吧！",
  str_voice_1600271_39 = "無人可逃。",
  str_voice_1600271_40 = "雷擊、轟鳴！",
  str_voice_1600271_41 = "其他人，能跟得上我嗎？",
  str_voice_1600271_42 = "摧枯拉朽的力量，帶來理所當然的勝利。",
  str_voice_1600271_43 = "這副軀體……還不夠嗎。",
  str_voice_1600271_44 = "和曾經的夥伴重逢，甚至再度成為隊友，這樣的機會可不多呢。",
  str_voice_1600271_45 = "……這個……嗯……好吧。",
  str_voice_1600271_46 = "啊，這個，稍微有點喜歡……",
  str_voice_1600271_47 = "謝謝你，一直送我東西。",
  str_voice_1600271_48 = "喜歡。喜歡這個，想要。謝、謝謝……",
  str_voice_1600271_49 = "我從小就和其他家族成員不一樣。你也許聽過那個名字：特洛伊，象徵權謀與喉舌……所以，我一直都格格不入。",
  str_voice_1600271_50 = "我的能力在某個雨天覺醒——不，準確地說，是在經歷了圈套和欺騙之後。但我並不恨他，只是對自己的弱小感到失望。",
  str_voice_1600271_51 = "最後，我透過一次死亡而重生了。有許多人幫助了我，我也以行動報答了他們。但，失去的羈絆已無從挽回，唯有繼續踐行自己的道義……",
  str_voice_1600271_52 = "白夜極光。",
  str_voice_1600271_53 = "你是否聽見？",
  str_voice_1600271_54 = "早安。我在等待你。",
  str_voice_1600271_55 = "日安。我的指令有所更新。",
  str_voice_1600271_56 = "你是否已打算休息？",
  str_voice_1600271_57 = "新年快樂，羈絆之人啊。",
  str_voice_1600281_1 = "啊啊對不起對不起、又是我嗎？！欸？只是普通的打招呼？",
  str_voice_1600281_2 = "啊啊，到底什麼時候才能變成被大家無條件信任的後盾呢？……也許明天就可以了吧？！",
  str_voice_1600281_3 = "您問我在做什麼？沒什麼沒什麼，就是一些聖水導彈啦～不過到底能治療還是傷害拉斐爾也不太清楚就是了。",
  str_voice_1600281_4 = "看看拉斐爾研究的新藥！這次一定可以派上用場！我叫它「天威神罰無上治癒穿甲彈」！",
  str_voice_1600281_5 = "卡～蓮～姐～姐～在～哪～裡？今天還沒分配任務給拉斐爾啦！為什麼總是忘記啦！",
  str_voice_1600281_6 = "喔吼吼，這些都是感謝拉斐爾妙手回春的「感謝信」喔！雖然這麼多年來總共也沒幾封啦，但偶爾讀一讀還是很感動呢……",
  str_voice_1600281_7 = "那個……拉斐爾……可以提一個要求嗎？您……來當我的臨床實驗者吧。欸？為、為什麼要後退一步？",
  str_voice_1600281_8 = "那個，上次不小心移除了患者的一條手臂，您可以拿去還給她嗎？欸嘿嘿嘿——",
  str_voice_1600281_9 = "有病患嗎？！誰！傷者在哪裡！拉斐爾、救濟者5號全彈發射！你們都安全了——應該吧！！",
  str_voice_1600281_10 = "又是空閒的一天。拉斐爾對大家很重要，一定不能辜負大家的期待。今天再熬夜做點新東西出來吧？",
  str_voice_1600281_11 = "這裡交給我吧！我應該能做好吧！啊，一定沒問題！約翰的職業笑容、啟動！！",
  str_voice_1600281_12 = "有人要找拉斐爾嗎？您要找拉斐爾嗎？您、受、傷、了、嗎？",
  str_voice_1600281_13 = "大家總是對拉斐爾充滿了希望，希望拉斐爾能多休息一會之類的！",
  str_voice_1600281_14 = "虎牙又長長了呢……為、為什麼只有牙齒在成長……",
  str_voice_1600281_15 = "生日快樂！我特別為您準備了一百零八顆聖水導彈，希望您開心唷！",
  str_voice_1600281_16 = "啊、您、您回來了！",
  str_voice_1600281_17 = "早安！拉斐爾今天也很有精神，您沒精神嗎？拉斐爾來祝您一臂之力吧！",
  str_voice_1600281_18 = "完全沒關係！拉斐爾還可以接待更多的患者！您呢？要來嗎？",
  str_voice_1600281_19 = "良好的睡眠才會有良好的精神，您有好好休息嗎？拉斐爾來祝您一臂之力吧！",
  str_voice_1600281_20 = "白夜城超棒的！祂在那個時候收留了無家可歸的我，還讓我的研究繼續下去！",
  str_voice_1600281_21 = "啟光也超棒的！以前去交流學習的時候，和大家一起玩導彈！",
  str_voice_1600281_22 = "白夜至上！",
  str_voice_1600281_23 = "很遺憾，牠們無可救藥，只能淨化掉了。",
  str_voice_1600281_24 = "那個時候我在她身邊就好了，雖然加百列總是說無所謂，可是……！",
  str_voice_1600281_25 = "小米迦勒最近看起來好多了……剛開始的時候，真讓人擔心呢。",
  str_voice_1600281_26 = "拉斐爾會繼續研究、探索、嘗試醫學領域，希望大家都能痊癒！",
  str_voice_1600281_27 = "無法救治的患者，不過無法救治患者的拉斐爾才是最討厭的……",
  str_voice_1600281_28 = "拉斐爾知道巨像唷！以前還有看過，您這個看起來白白的很棒嘛！",
  str_voice_1600281_29 = "我！我是拉斐爾！請相信我，我會在各個方面助您一臂之力的，請多指教！",
  str_voice_1600281_30 = "喔、吼、吼、吼！",
  str_voice_1600281_31 = "謝謝！您果然獨具慧眼！",
  str_voice_1600281_32 = "現在是更厲害的拉斐爾！！",
  str_voice_1600281_33 = "為了不負約翰之名，我將全力以赴！！",
  str_voice_1600281_34 = "各位！拉斐爾來啦！",
  str_voice_1600281_35 = "等等我！馬上就好了！",
  str_voice_1600281_36 = "可、可以了！應該吧！",
  str_voice_1600281_37 = "全彈發射，認真的！！",
  str_voice_1600281_38 = "聖水導彈，大放送！！",
  str_voice_1600281_39 = "嗚呼——！",
  str_voice_1600281_40 = "聖水放送！",
  str_voice_1600281_41 = "拉斐爾，冷靜地接下了重任！！",
  str_voice_1600281_42 = "只要有拉斐爾在，就不會再有人受傷了！Yeah！",
  str_voice_1600281_43 = "對不起，請讓我再試一次！就一次！拜託！！",
  str_voice_1600281_44 = "希望不要再收到投訴信了！總是給大家添麻煩，也滿不好意思的～",
  str_voice_1600281_45 = "呀，原來拉斐爾也能收到禮物嗎？",
  str_voice_1600281_46 = "喔，這個有意思！感謝！",
  str_voice_1600281_47 = "超感謝！拉斐爾很開心！",
  str_voice_1600281_48 = "這個是？！能收下嗎！！嗚啊——",
  str_voice_1600281_49 = "以前的日子真是艱苦。尤其小時候跟師父他們一起漂泊……啊，對不起！和您說了一些負面的事！",
  str_voice_1600281_50 = "您有沒有聽過約翰家族呢？很有名喔，如果不是我們，不知有多少人撐不過……欸？沒聽過！？",
  str_voice_1600281_51 = "師傅，拉斐爾長大啦。現在遇到了很多很多好人，也可以幫上大忙啦。您在星空中好好看著吧……",
  str_voice_1600281_52 = "白夜極光！",
  str_voice_1600281_53 = "您好嗎？",
  str_voice_1600281_54 = "您醒了嗎？",
  str_voice_1600281_55 = "您快看看！",
  str_voice_1600281_56 = "您快醒醒！先別睡！",
  str_voice_1600281_57 = "嗚呼！祝您新年快樂！",
  str_voice_1600381_1 = "試驗場的斷壁殘垣時時提醒著我，那個逝去時代的產物有多麼厲害。嗯，我確實犯了錯誤，但失敗乃成功之母，對吧？",
  str_voice_1600381_2 = "這個世界的悲慘與我無關，我不想裝出一副同情的樣子。啟光還滿好玩的不是嗎？",
  str_voice_1600381_3 = "我的座駕是年代久遠的產物，只有完全不考慮工藝和成本才會做出這種東西。嗯！真是挖到寶了。",
  str_voice_1600381_4 = "世上的規則與我無關！賭上研究者的榮譽，我一定會解出答案的！",
  str_voice_1600381_5 = "要數數我的戰績嗎？你看，無論哪個遊戲，我的成績都在榜上屹立不搖。",
  str_voice_1600381_6 = "「王座」是遙遠時代的遺物，只有第一個破解它的祕密的人，才有資格使用。",
  str_voice_1600381_7 = "我的任務就是過關，其他的一切都與我無關不是嗎？每個人都有自己的關卡要過呀。",
  str_voice_1600381_8 = "那個祕境的巨型陷阱坑也是一大奇觀，真希望我能有空去緬懷一下。不過，那裡似乎被一群遊民給佔領了呢。",
  str_voice_1600381_9 = "我們都是被文明拋棄的孩子……你真的完全也不知道那個時代的故事？啊，也是，畢竟對外公開的文獻上不會記載這些。",
  str_voice_1600381_10 = "無法撼動的鐵騎與軍勢，而這還不是我的全部……嘖嘖，壞毛病又出現了，我還是調整一下心理年齡比較好。",
  str_voice_1600381_11 = "研究者需要更多旁觀心理，可能這能帶給你不一樣的視角吧。",
  str_voice_1600381_12 = "這裡的遊戲也不賴嘛，操作巨像之類的……嗯？沒有這種遊戲嗎？",
  str_voice_1600381_13 = "回歸這樣的姿態，反而覺得外界的一切既陌生又新鮮了，真神奇。",
  str_voice_1600381_14 = "名為「世界」的副本已經更新了，要一起挑戰嗎？",
  str_voice_1600381_15 = "送你一份參賽資格，久違的「王座盃」！你若能贏我，我就把王座讓給你！",
  str_voice_1600381_16 = "看看誰來了——我的手下敗將！",
  str_voice_1600381_17 = "多說無用，猜拳開始。剪刀、石頭、布！……哈哈，你輸了！",
  str_voice_1600381_18 = "所以，想好要怎麼挑戰我了嗎？手下敗將～",
  str_voice_1600381_19 = "打起精神來，對於研究者來說，遊戲才剛剛開始！",
  str_voice_1600381_20 = "啟光正是研究者的天堂，拭目以待，我們會開發出更厲害的東西。",
  str_voice_1600381_21 = "白夜城派來的小拉斐爾研究能力很不錯嘛，不過跟我比還差得遠！",
  str_voice_1600381_22 = "為了啟明之光！",
  str_voice_1600381_23 = "暫時停止對牠們的深入研究了……下一次，我會更加謹慎。",
  str_voice_1600381_24 = "我們的現任大元帥才是最棒的，有時候我甚至覺得她像守關大魔王。",
  str_voice_1600381_25 = "手下敗將！年紀不大口氣倒是不小，跟我比操作機器，他還早得很。",
  str_voice_1600381_26 = "喜歡的東西？遊戲、研究、古老的機械、第一名的王座。",
  str_voice_1600381_27 = "沒有遊戲樂趣的世界一定會變得很無趣吧！",
  str_voice_1600381_28 = "機械技術、生物技術、光能技術……或許巨像才是完美的造物。",
  str_voice_1600381_29 = "你身上有和我相似的氣息，我們以前認識嗎？還是你以前也參加過「王座盃」，那你一定不會不認識我！",
  str_voice_1600381_30 = "成功過關！咻！",
  str_voice_1600381_31 = "恐懼時代的無上力量，醒了！",
  str_voice_1600381_32 = "沒人能將我從王座上拖下來！",
  str_voice_1600381_33 = "後悔和我對戰吧！",
  str_voice_1600381_34 = "第二名的分數差得有點遠啊！",
  str_voice_1600381_35 = "讓我盡興地玩一場吧！",
  str_voice_1600381_36 = "新記錄即將誕生！",
  str_voice_1600381_37 = "遊戲開始！",
  str_voice_1600381_38 = "要不要按一按試試看呢～",
  str_voice_1600381_39 = "震撼連招！",
  str_voice_1600381_40 = "機甲技能！",
  str_voice_1600381_41 = "遊戲開始！我是「啟光」陣營！",
  str_voice_1600381_42 = "真有趣！二周目二周目！",
  str_voice_1600381_43 = "還有這種規則？可惡……",
  str_voice_1600381_44 = "你終於考慮好了？可以讓我玩一下你們的巨像？",
  str_voice_1600381_45 = "我猜猜看，是新遊戲還是強化卡？",
  str_voice_1600381_46 = "從來沒在啟光見過這麼好玩的東西！",
  str_voice_1600381_47 = "我猜猜，你開發了什麼新的玩法？",
  str_voice_1600381_48 = "果然還是你知道我喜歡玩什麼！",
  str_voice_1600381_49 = "這份的力量似乎沒能保護創造它的時代，如今我重新將它發掘出來，它能保護我們的時代嗎？",
  str_voice_1600381_50 = "或許有一天這個時代會和那些古老帝國一樣，以同樣的方式滅亡，但這些遊戲會一直進行下去，直到分出勝負為止。",
  str_voice_1600381_51 = "關於那場實驗，我的記憶完好無損，但我不想與你分享這些無用的知識。看你一副傻呼呼的樣子就知道，你還停留在「經驗不足」階段。",
  str_voice_1600381_52 = "白夜極光！",
  str_voice_1600381_53 = "快出來！",
  str_voice_1600381_54 = "快來！遊戲開始了！",
  str_voice_1600381_55 = "時間正好，來對戰吧！",
  str_voice_1600381_56 = "不要打瞌睡喔！",
  str_voice_1600381_57 = "過關一年，再來一年！",
  str_voice_1600601_1 = "來打個招呼。「彈頭」、「彈匣」和「彈殼」，這是紅油扳手技術部特製的「厄運」系列機械手臂。至於怎麼製作的……嗯，你可以直接去問小不點。",
  str_voice_1600601_2 = "沒有人會和錢過不去，這只是一份工作。不過，出於人道主義精神，我會讓他們痛痛快快、舒舒服服地消失。",
  str_voice_1600601_3 = "「幫助弱小和婦女」是我的行為準則，尤其是小孩子，無論任何情況下我都不會對他們拔槍。",
  str_voice_1600601_4 = "力量將衝破束縛——呵，開玩笑，我是不會解開手銬的，這可是我的人設。",
  str_voice_1600601_5 = "小心點，朋友，我射出的子彈快到足夠讓任何人毫無痛苦地走向終點。",
  str_voice_1600601_6 = "不錯啊，順其自然，活在當下。我能這麼說當然是因為——我有這個自信。",
  str_voice_1600601_7 = "我不喜歡動手……不過人生有時候就是這麼無奈。嘖，可別讓我在子彈刻上你的名字。",
  str_voice_1600601_8 = "生命的最後，我會喝個爛醉，倒在酒館門前。當不知名的仇人將子彈射向我的心臟，我將毫無知覺，沉睡的姿態一如往常。",
  str_voice_1600601_9 = "我從不對別人的生活指指點點。不過你是特別的——無論遇到什麼都別放在心上，時間總會撫平一切。",
  str_voice_1600601_10 = "放輕鬆，這種悠閒的時刻才應該好好享受，工作什麼的再說吧。",
  str_voice_1600601_11 = "如果你付我足夠的報酬——好吧，沒問題。",
  str_voice_1600601_12 = "砰！嚇到你了？呵呵。",
  str_voice_1600601_13 = "出於禮貌我應該和你握手——你可以從我的機械臂中隨意挑選。",
  str_voice_1600601_14 = "通緝犯？我腦袋的價格，連我自己都很心動。",
  str_voice_1600601_15 = "欸～今天是你生日啊，真好啊，值得慶祝的幸運日～",
  str_voice_1600601_16 = "哎——好久沒有活動筋骨了，帶路的，你可要跟上節奏喔。",
  str_voice_1600601_17 = "悠閒的早餐時間是美好一天的開始，尤其是再配上一杯茶。",
  str_voice_1600601_18 = "尖叫聲和噪音！搞音樂的那群傢伙，到了這個時間總是躁動不安。",
  str_voice_1600601_19 = "喝一杯嗎？加冰、加鹽還是加點柳橙汁？",
  str_voice_1600601_20 = "紅油扳手是狂人和流浪者聚集的垃圾場，我當然也是其中之一。",
  str_voice_1600601_21 = "白夜城真好啊！揮霍著舊世界的遺產，騎士團裡也都是美麗的少女。",
  str_voice_1600601_22 = "及時行樂，隨遇而安。",
  str_voice_1600601_23 = "暗鬼？靠著吸食暗能過活的可憐生物，早點讓牠們安息吧。",
  str_voice_1600601_24 = "蕾吉娜和芭芭拉嗎？啊——難以抉擇，畢竟我又愛搖滾樂又喜歡美少女。",
  str_voice_1600601_25 = "黑潮這傢伙，雖然是個肌肉笨蛋，但在紅油扳手內算是正常人。",
  str_voice_1600601_26 = "觀察和散步，能讓人平心靜氣。光靈又怎樣？不過是沙漠裡的沙子而已。",
  str_voice_1600601_27 = "緊張的氛圍總令人聯想到滿身臭汗，何必把自己逼得那麼緊？",
  str_voice_1600601_28 = "真是宏偉的造物，只要給我一個角落就好，看來能告別餐風露宿了。",
  str_voice_1600601_29 = "別動，下一秒這枚子彈就會穿過你的腦袋——開個玩笑～我是約娜，路過的平凡槍手。讓我們把煩人的瑣事放在一旁，心平氣和地坐下來聊聊吧。",
  str_voice_1600601_30 = "保持低調。",
  str_voice_1600601_31 = "一發，正中目標！",
  str_voice_1600601_32 = "開槍是我的天賦。",
  str_voice_1600601_33 = "來，聽聽這槍聲交織而成的交響樂！",
  str_voice_1600601_34 = "搞定他，兄弟們。",
  str_voice_1600601_35 = "子彈上膛。",
  str_voice_1600601_36 = "瞄準。",
  str_voice_1600601_37 = "吃子彈吧！",
  str_voice_1600601_38 = "再見，朋友。",
  str_voice_1600601_39 = "好事成雙。",
  str_voice_1600601_40 = "無人生還。",
  str_voice_1600601_41 = "為我的敵人準備好棺材。",
  str_voice_1600601_42 = "呵，這沒什麼了不起的。",
  str_voice_1600601_43 = "小心狙擊。",
  str_voice_1600601_44 = "差點忘了，還有要解決的事，速戰速決吧。",
  str_voice_1600601_45 = "啊？……嗯，這感覺倒是很新鮮。",
  str_voice_1600601_46 = "謝啦～我會好好珍藏。",
  str_voice_1600601_47 = "子彈，酒杯和你的禮物。",
  str_voice_1600601_48 = "等價交換，這份禮物值得一杯冰啤酒！",
  str_voice_1600601_49 = "人生？我對人生沒有特別的期待……活一天是一天，在哪裡都無所謂，有口飯吃就行了。",
  str_voice_1600601_50 = "槍手的終點是決鬥，顯然我的槍更快。我親手埋葬我的恩師，並為他灑滿了一地的彈殼。",
  str_voice_1600601_51 = "我總是任由命運拉扯，被推到哪裡就在哪裡停留。如果哪裡都好，紅油扳手至少是我待過最舒服的地方。",
  str_voice_1600601_52 = "白夜極光。",
  str_voice_1600601_53 = "帶路的。",
  str_voice_1600601_54 = "啊，早。",
  str_voice_1600601_55 = "過來，該活動了。",
  str_voice_1600601_56 = "出個聲，告訴我你還活著。",
  str_voice_1600601_57 = "坐下吧，新年到了。",
  str_voice_1600771_1 = "如此完美的巨像還是第一次見到，看來……命運已然昭示。",
  str_voice_1600771_2 = "自巨像升入天空，俯瞰地面眾生之時，我知道世界已經被改變了。",
  str_voice_1600771_3 = "命運的羈絆已經為你帶來很多夥伴，在這些「弦」沒有斷裂之前，你是安全的，請放心。",
  str_voice_1600771_4 = "白夜將逐漸淡薄，這是我看到的未來​​，我衷心希望那是個失誤。",
  str_voice_1600771_5 = "記住，極光是我們的根本，它將為我們擊敗那最終的威脅。",
  str_voice_1600771_6 = "北境是我的朋友，也是你們的朋友，一如冬日之後便是初春。",
  str_voice_1600771_7 = "看來你有空，願意和我聊聊過去的事情嗎？你是如何找到這座巨像的呢？",
  str_voice_1600771_8 = "我在北境的居所，名為冬宮——一座建立在山峰的宮殿，那裡的風景，不亞於此。",
  str_voice_1600771_9 = "你或許就是我一直在等待的那個人，那個讓大陸擁有「未來」的人。",
  str_voice_1600771_10 = "作為北境的統治者，我很少有如此悠閒的時光，這麼說來，讓我懷念起了冬宮裡的那把長椅。",
  str_voice_1600771_11 = "在你尋找命運之時，我可以代你看好他，這座巨像。",
  str_voice_1600771_12 = "現在的情勢，與我在北境之時大相逕庭，好在尚可輕鬆應對。",
  str_voice_1600771_13 = "這座巨像或許不是世界上唯一的巨像，他不會孤單，你……也不會。",
  str_voice_1600771_14 = "我有時候……能聽到巨像在說話，看來他也有表達的慾望。",
  str_voice_1600771_15 = "我已經記不得自己的生日了……但是還是要祝福你，生日快樂。",
  str_voice_1600771_16 = "平靜的一天，宛如北境的大部分時光。",
  str_voice_1600771_17 = "來得正好，與我一起沐浴在陽光下吧。",
  str_voice_1600771_18 = "偶爾的休息是為將來做準備，喝一杯紅茶，小憩片刻吧。",
  str_voice_1600771_19 = "我已習慣不眠不休，這是作為北境女王的代價，你去休息吧。",
  str_voice_1600771_20 = "我們將自己的命運冰凍在無垠的山脈裡。也許，變化就要發生了……",
  str_voice_1600771_21 = "白夜城就如無雪的北境，保守就是他們的雪山。一日崩壞，驚天動地。",
  str_voice_1600771_22 = "暮冬而生。",
  str_voice_1600771_23 = "暗鬼，牠們口中的母親，究竟是誰……？",
  str_voice_1600771_24 = "娜席里絲的冰冷是有原因的，你不知道她曾經歷過什麼。",
  str_voice_1600771_25 = "雖是貴族，卡蓮卻沒有傲慢之心，她是為了真正的白夜城而生的。",
  str_voice_1600771_26 = "南方的紅茶、冬日的陽光，若世界一直如此，想必我也能享受。",
  str_voice_1600771_27 = "嫌隙是我們永遠的敵人，威脅程度更勝暗鬼。",
  str_voice_1600771_28 = "源於過去，卻處處彰顯著先進的科技，他有很多祕密……",
  str_voice_1600771_29 = "我是北境的統治者，無需驚訝，是命運讓我們相見，也是命運讓我來到這座巨像之上。",
  str_voice_1600771_30 = "真正的力量……湧現出來了。",
  str_voice_1600771_31 = "寒冰是我的保護。",
  str_voice_1600771_32 = "寒冰，亦為極光之刃。",
  str_voice_1600771_33 = "我們的朋友，是北境的寒冰。",
  str_voice_1600771_34 = "從容應對。",
  str_voice_1600771_35 = "極光，掌握……",
  str_voice_1600771_36 = "極寒之力！",
  str_voice_1600771_37 = "冰解之時，終結。",
  str_voice_1600771_38 = "應降臨的，速即降臨。",
  str_voice_1600771_39 = "極光之刃。",
  str_voice_1600771_40 = "最終的裁決。",
  str_voice_1600771_41 = "隨我一起走向勝利。",
  str_voice_1600771_42 = "無數勝利中的一次。",
  str_voice_1600771_43 = "偶爾的後退，不要氣餒。",
  str_voice_1600771_44 = "你的未來會很漫長，請堅持下去。",
  str_voice_1600771_45 = "謝謝，但無需花費太多心思。",
  str_voice_1600771_46 = "嗯，著實合我心意，謝謝。",
  str_voice_1600771_47 = "你花了不少心思，感謝你。",
  str_voice_1600771_48 = "看來你真是我選中之人……",
  str_voice_1600771_49 = "北境擁有最古老的禮儀。現在想來，那位遠道而來的使節閣下，應該很不習慣。",
  str_voice_1600771_50 = "運籌帷幄之中，決勝千里之外，我們需要依靠頭腦，也只有如此才能擊敗暗鬼。",
  str_voice_1600771_51 = "我並非全知全能，但我以全力護佑子民們，過去如此，未來如此。只有堅定一致，才能面對那最終的威脅。",
  str_voice_1600771_52 = "白夜極光。",
  str_voice_1600771_53 = "堅持之人。",
  str_voice_1600771_54 = "喚醒之風正在吹拂。",
  str_voice_1600771_55 = "我所期待之人，回答我。",
  str_voice_1600771_56 = "有我在，無須恐懼黑夜。",
  str_voice_1600771_57 = "季節已完成輪迴。",
  str_voice_1600891_1 = "責任意指居高位者應當做出表率，守護民眾，同時亦應當更加嚴格地要求自己，鍛鍊出名符其實的力量。",
  str_voice_1600891_2 = "我有自己要走的路，我不會成為他。他除了公敵以外沒有敵人，他除了律法以外沒有親人。",
  str_voice_1600891_3 = "我被已經死去的聲音所左右了嗎？但我現在踏出的每一步，都代表我的意志，都來自於真實。",
  str_voice_1600891_4 = "我會盡我所能地去反省，去悔恨，在還能感受到疼痛之時，心懷希望，不斷前行。",
  str_voice_1600891_5 = "如果你問那金色水面下浮動的影子，那是在等待我展露出破綻時，好將我拖入湖中吞噬的東西。",
  str_voice_1600891_6 = "將該埋葬者埋葬，為了不再逃避而捨棄慾望，循著晨星的方向前行，永恆多深，就走多遠。",
  str_voice_1600891_7 = "按照審判律，你有上訴的權利，但首先，你要有立足的理由……我並沒有說你觸犯了審判律，請不要緊張。",
  str_voice_1600891_8 = "如果你執意要以身犯險，你去吧，我不阻攔……但請讓我和你一起，至少會安全許多。",
  str_voice_1600891_9 = "你現在所踏出的每一步，都會成為拯救你的基石，所以前行吧，無需擔心前路，身後會有黎明。",
  str_voice_1600891_10 = "你還在嗎？請……讓我找個地方休息一下，我想我無法支撐自己太久。當然，只要一下。",
  str_voice_1600891_11 = "請勿過度期待，我沒有這麼多東西可以拿來支撐自己，有的不過只是血肉骨皮，靈魂與記憶。",
  str_voice_1600891_12 = "我所履行的，只有我認可的義務；我所決定的，只有是否繼續前行。",
  str_voice_1600891_13 = "這把手杖對我來說還是太長了一點，但在它折斷之前，不必更換。",
  str_voice_1600891_14 = "應當心懷家園，心胸寬闊……這是我所受過的教導，也是認同。",
  str_voice_1600891_15 = "誕生似乎並不一定帶來歡樂，但我找來了一些蘋果，希望你開心。",
  str_voice_1600891_16 = "你總是會出現在我觸手可及的地方，這對我來說是種體貼。",
  str_voice_1600891_17 = "早安，在更早之前，我預見晨星在正上方的天空。",
  str_voice_1600891_18 = "日光黯淡了？我來補充一些光吧……這是審判長笑話，不有趣嗎？",
  str_voice_1600891_19 = "我看見你面露疲憊，不用拖著沉重的身體努力，休息一會吧。",
  str_voice_1600891_20 = "在日出時將秩序升起，是為了在日落以後還能生存下去。",
  str_voice_1600891_21 = "除去身分，我仍會發問，如何辨明真理不是虛無，不是逃避？",
  str_voice_1600891_22 = "白夜至上。",
  str_voice_1600891_23 = "空洞或許也是一種幸福，畢竟在擁有意識之後，世界會完全不同。",
  str_voice_1600891_24 = "我總是欽佩尤萊雅小姐的強大與獨立，還有那份送走一切的氣魄。",
  str_voice_1600891_25 = "那份坦然會讓卡蓮小姐擁有更廣闊的路途，與我全然不同。",
  str_voice_1600891_26 = "「借禮之劍」是我出於自己的意願所選擇的武器，我很喜歡。",
  str_voice_1600891_27 = "與過去一樣，我依舊厭惡名為自私自大和自以為是的那種本性。",
  str_voice_1600891_28 = "雖然都是過去的遺物，但他對你來說，一定有著更光明的意義。",
  str_voice_1600891_29 = "初次見面，我是白夜城審判長——伊倫汀。如果你有合理的訴求，那就讓回應願望的泉森，藉沉默的雷光顯現。",
  str_voice_1600891_30 = "接受推動。",
  str_voice_1600891_31 = "將石子包裹，砥礪為珍珠。",
  str_voice_1600891_32 = "讓雷電成為黑暗裡閃光的線。",
  str_voice_1600891_33 = "等待晨星。",
  str_voice_1600891_34 = "保持緘默。",
  str_voice_1600891_35 = "審判已到。",
  str_voice_1600891_36 = "臨行之時。",
  str_voice_1600891_37 = "無需申辯，平靜一點。",
  str_voice_1600891_38 = "讓雷電寂靜，讓風雨安寧。",
  str_voice_1600891_39 = "割裂！",
  str_voice_1600891_40 = "判斷，下達。",
  str_voice_1600891_41 = "請……等一下，我無法走那麼快。",
  str_voice_1600891_42 = "收拾殘骸吧，該離開了。",
  str_voice_1600891_43 = "我還可以繼續，還可以走……",
  str_voice_1600891_44 = "若是時間允許……今天，來講講水面以下的故事吧。",
  str_voice_1600891_45 = "我以個人的名義收下，但依舊困擾。",
  str_voice_1600891_46 = "我接受你的好意，並希望答謝你。",
  str_voice_1600891_47 = "以我們的關係，並不會被誤解。",
  str_voice_1600891_48 = "感謝你，細心溫和，一如既往。",
  str_voice_1600891_49 = "讓痛苦與煩惱、哀傷與悲嘆，都隱於水面之下，就算它們在那裡蔓延，也不會妨礙我行動。",
  str_voice_1600891_50 = "這無法逃離的束縛，是我自己為自己上的枷鎖，一如金色的沼澤和森林，還有我所恐懼的影子。",
  str_voice_1600891_51 = "因為這雙腿曾經被斬斷過，為了站起來，只能用雷光之線臨時縫合，能成功活下來，已經夠了。",
  str_voice_1600891_52 = "白夜極光。",
  str_voice_1600891_53 = "你好。",
  str_voice_1600891_54 = "早安。",
  str_voice_1600891_55 = "不知是否打擾到你？",
  str_voice_1600891_56 = "希望今夜月色不錯，晚安。",
  str_voice_1600891_57 = "新年又至，願你能快樂。",
  str_voice_1300461_1 = "-巨像為何開得這麼急？\n-因為導航員大人怕遲到啦♪\n-趁熱呼呼吃霸王餐呀♪",
  str_voice_1300461_2 = "-噢♪\n-優雅偉大的導航員大人♪-請千萬不要低頭♪\n-您的髮際線啊、-就快離您而去啦♪",
  str_voice_1300461_3 = "-您又來看我們了呀。-又來了啦！\n-遊手好閒的樣子、-還是單身吧？是單身呢！",
  str_voice_1300461_4 = "-大人們最在意，-在家中捧在手裡，\n-在外面送不出去，-厚厚的臉皮，\n-強大的魅力♪",
  str_voice_1300461_5 = "-噢-奇形怪狀的東西♪\n-我們親愛的對手啊♪ -打你們就像打西瓜♪",
  str_voice_1300461_6 = "-何必如此介意？\n-何必如此著急？\n-我們只是偶然經過的路人♪它們的黃泉引路人♪",
  str_voice_1300461_7 = "-黎明學院的大人們♪-個個都很愚蠢呢♪\n-白夜城的那些貴族♪-還更加愚蠢呢♪",
  str_voice_1300461_8 = "-世界上的人們，-愈高愈蠢♪\n-愈老愈笨♪-您請放心♪您矮小年輕♪",
  str_voice_1300461_9 = "-噢♪\n-無聊的大人們很多♪-您卻不是其中一個♪\n-是因為您天真可愛♪-是因為您腦袋空空♪",
  str_voice_1300461_10 = "-無聊的地方，-無聊的大人們，\n-他們如何消磨時光♪-他們不如消磨自己♪",
  str_voice_1300461_11 = "-讓我們唱歌嗎？\n-您想得太多啦，\n-太美啦。",
  str_voice_1300461_12 = "-您還沒聽夠嗎？\n-您這麼享受嗎？",
  str_voice_1300461_13 = "-您若是沒事做♪-就拍拍頭頂♪\n-會變得清涼♪-會變得乾淨♪",
  str_voice_1300461_14 = "-遠見四條腿，-近看兩條腿，\n-導航員大人是什麼？-反正積一堆～",
  str_voice_1300461_15 = "-您知道時間到了嗎？♪\n-我們為您點蠟燭的時間到啦～",
  str_voice_1300461_16 = "-又是您，\n-您又回來了。\n-還活著呢。",
  str_voice_1300461_17 = "-起得愈早，-頭髮愈少，\n-您不多休息嗎？-這麼勤勞嗎？",
  str_voice_1300461_18 = "-您出去了，-您回來了，\n-鼻子沒變紅，-臉也沒變腫～",
  str_voice_1300461_19 = "-這麼晚了為什麼還要逞強？\n-是意志嗎？\n-是失眠吧？",
  str_voice_1300461_20 = "-得到一點，-自視甚高，\n-生在地面，-卻想飛天～",
  str_voice_1300461_21 = "-他們看見真理了嗎？\n-蒙著眼睛看見了嗎？",
  str_voice_1300461_22 = "白夜至上呢♪",
  str_voice_1300461_23 = "-廢物與廢物聯手♪\n-青蛙與青蛙合作♪",
  str_voice_1300461_24 = "-您被卡蓮收拾得不夠慘嗎？\n-不夠慘吧？\n-真夠慘啊！",
  str_voice_1300461_25 = "-親愛的朋友，-總是教我們，\n-溫和努力，-送人離去！",
  str_voice_1300461_26 = "-不自以為是，\n-有自知之明，\n-您是嗎？您會是嗎？",
  str_voice_1300461_27 = "-完全不行的大人們，\n-他們為何不照鏡子？\n-他們為何看不清自己？",
  str_voice_1300461_28 = "-這就是您的巨像嗎？\n-就這麼大嗎？\n-就這麼白嗎？",
  str_voice_1300461_29 = "-親愛的朋友，\n-我們來自白夜城。-小嘴抹了蜜，\n-張口吐芬芳，-真芬芳呢。",
  str_voice_1300461_30 = "我們做主♪",
  str_voice_1300461_31 = "大人們需要獲得更多歌頌。",
  str_voice_1300461_32 = "唱到把他們統統送走為止♪",
  str_voice_1300461_33 = "-穿透他們，\n-直擊靈魂！",
  str_voice_1300461_34 = "您要我們加入？",
  str_voice_1300461_35 = "等不及啦？",
  str_voice_1300461_36 = "讓我們，唱它——",
  str_voice_1300461_37 = "-噢♪\n-黑白祭禮的詩歌♪",
  str_voice_1300461_38 = "-在它的碑頭♪\n-飄揚♪",
  str_voice_1300461_39 = "真無聊♪",
  str_voice_1300461_40 = "真好笑♪",
  str_voice_1300461_41 = "-噢，\n-對面的小智障♪\n-長得真夠醜呢♪",
  str_voice_1300461_42 = "-被我們收拾得不夠慘嗎？\n-真夠慘啊！",
  str_voice_1300461_43 = "-走吧～\n-走吧～\n-空手回家～",
  str_voice_1300461_44 = "-雨停了嗎？\n-天晴了嗎？\n-您覺得您又行了嗎？",
  str_voice_1300461_45 = "-您會送禮物？\n-就這禮物嗎？",
  str_voice_1300461_46 = "-這次算您送對了，\n-送對啦！",
  str_voice_1300461_47 = "-您選了這樣的禮物嗎？\n-不是吧？",
  str_voice_1300461_48 = "-您是多麼努力，\n-我們該謝謝您啦～",
  str_voice_1300461_49 = "-貴族♪-迂腐♪\n-白痴♪-無聊♪\n-毫無存在價值的大人們～",
  str_voice_1300461_50 = "-多麼激烈的戰鬥，\n-多麼厲害的招式，\n-他們立於戰場，要與母雞互啄～",
  str_voice_1300461_51 = "-皮耶爾總是會笑，-迪亞姆會成為騎士，\n-卡拉維護我們，-尼爾常常看書。\n-可憐的您還分不清嗎？",
  str_voice_1300461_52 = "白夜極光♪",
  str_voice_1300461_53 = "導航員大人，您好♪",
  str_voice_1300461_54 = "-早安♪\n-您還沒醒？\n-您還不行？",
  str_voice_1300461_55 = "-午安♪\n-您很閒嗎？",
  str_voice_1300461_56 = "-晚安♪\n-保重您的頭髮♪",
  str_voice_1300461_57 = "-新年啦♪\n-不祝福您不行啦♪",
  str_voice_1300531_1 = "真糟糕，老闆您的笑容簡直命中我的心臟！請掏出錢包吧，讓所有人都知道，能夠跟隨老闆是一件多麼幸運的事！",
  str_voice_1300531_2 = "親愛的老闆，小動物真的十分可愛，百分百值得您掏錢！如果有來生，我希望成為老闆的小狗！",
  str_voice_1300531_3 = "看看裝滿這個背包的好東西吧！如果您都不滿意，那我還能把我今天的時間賣給您，老闆您只需要付這個金額～",
  str_voice_1300531_4 = "您有什麼事請儘管來找我吧，我已不再是無力之人了。您需要武器還是護盾？收費絕對公道！",
  str_voice_1300531_5 = "百枚白夜幣，我轉頭；千枚白夜幣，我開口；萬枚白夜幣，我選擇愛您。但我是個商販，不該收的一分不收。",
  str_voice_1300531_7 = "親愛的老闆，您可千萬別嫌我話多。那是因為我無法控制自己對您的仰慕之情，尤其是在您付錢的時候！",
  str_voice_1300531_8 = "老闆，您可真是善良，讓我感動不已。我真希望能一直陪在您身邊，特別是在老闆想要買東西的時候！",
  str_voice_1300531_9 = "我能為您免費提供的東西不多，但唯有絕不背叛，是我所能夠承諾的東西。",
  str_voice_1300531_10 = "時間就是金錢……但只要能待在我親愛的老闆身邊，我知道您會為我核銷的！",
  str_voice_1300531_11 = "親愛的老闆，十萬元，我今天就是您的狗，如果可以，我真想讓您看看我搖動的尾巴！",
  str_voice_1300531_12 = "老闆，勞務費、吩咐費、見不到您費，您該付錢啦～",
  str_voice_1300531_13 = "今天也是大豐收！下一次該賣點什麼，賣給誰好呢？",
  str_voice_1300531_14 = "嗯？我似乎感受到了什麼氣息？難道是小動物？不，果然還是錢！",
  str_voice_1300531_15 = "親愛的老闆，生日快樂！蛋糕、禮物、祝福，您的消費金額是十萬！",
  str_voice_1300531_16 = "老闆！您終於回來了！老闆不在的時候，我有好好計費～",
  str_voice_1300531_17 = "早安，老闆，今天是美好的一天，我給您看看昨日的帳單？",
  str_voice_1300531_18 = "老闆～您需要用餐嗎？需要點心嗎？想來點休閒娛樂嗎？",
  str_voice_1300531_19 = "老闆，您還是去休息吧，不然等一下又要收到帳單了～",
  str_voice_1300531_20 = "紅油扳手真棒呀，簡直就是未開發的市場，每天賺得口袋滿滿～",
  str_voice_1300531_21 = "那些討索真理的人是不明白嗎？免費的才是最貴的！真不像話呀。",
  str_voice_1300531_22 = "及時收款～",
  str_voice_1300531_23 = "一群不會付錢的傢伙，他們知道貨幣的好處嗎？",
  str_voice_1300531_24 = "技術是很昂貴的東西，那麼我當然很注意與她打好關係啦～",
  str_voice_1300531_25 = "不是動物的傢伙居然用頭套來假扮成動物？簡直難以置信。",
  str_voice_1300531_26 = "簡短地向您說明，我喜歡可愛的小動物，金錢和無價的東西。",
  str_voice_1300531_27 = "收到您的詢問訂單，請讓我如此回答，我討厭貪婪。",
  str_voice_1300531_28 = "我以商販之眼保證，這威猛的巨像，象徵著您的身分，一定很昂貴～",
  str_voice_1300531_29 = "哈哈，野生的新老闆出現了！親愛的老闆，您想買些什麼？小店應有盡有，只有您想不到沒有您買不到！",
  str_voice_1300531_30 = "還能夠賺更多～",
  str_voice_1300531_31 = "這都是為了親愛的老闆！",
  str_voice_1300531_32 = "一分銷售技巧，一分賺到！",
  str_voice_1300531_34 = "老闆講話了！",
  str_voice_1300531_35 = "攻擊手段，到貨啦！",
  str_voice_1300531_36 = "報酬準備好了嗎？",
  str_voice_1300531_37 = "老闆付錢，我幫您咬人！",
  str_voice_1300531_38 = "攻擊大放送，打折出售概不退換！",
  str_voice_1300531_39 = "向老闆展示！",
  str_voice_1300531_40 = "這才是好刀！",
  str_voice_1300531_41 = "通通收費♪",
  str_voice_1300531_42 = "這是勝利的帳單！",
  str_voice_1300531_43 = "您別難過，這次我算您便宜一點……",
  str_voice_1300531_44 = "紅油飲料、蜥蜴點心，怎麼樣？您也來一份吧？",
  str_voice_1300531_45 = "或許我下次能收到更貴重的禮物？",
  str_voice_1300531_46 = "這可真是太貴重了，真希望您能多送點！",
  str_voice_1300531_47 = "這份禮物，還不如老闆的笑容珍貴呢。",
  str_voice_1300531_48 = "老闆您總會提醒我，這份情誼無價，感謝您。",
  str_voice_1300531_49 = "您可千萬要小心，金錢有時會讓人成為惡鬼。但我不同，您可以盡情地付錢給我～",
  str_voice_1300531_50 = "若是感到寂寞，就請養一條小狗吧，野獸與人不同，牠們單純很多。當然，養我也可以！",
  str_voice_1300531_52 = "白夜極光！",
  str_voice_1300531_53 = "親愛的老闆！",
  str_voice_1300531_54 = "美麗的早晨，是為老闆來的！",
  str_voice_1300531_55 = "美麗的中午，是為老闆來的！",
  str_voice_1300531_56 = "晚上是為老闆來的，該結帳了！",
  str_voice_1300531_57 = "敬賀新年！僅收您一萬元！",
  str_voice_1400731_1 = "-分不清楚帕蒂和帕西嗎？那你可要記好啦！\n-帕西會戳你的屁股！\n-帕蒂會啃你的手！",
  str_voice_1400731_2 = "-有飯吃就好了，-沒有其他煩惱。\n-感情是什麼？-好吃嗎？\n-你吃給我們看一下！快呀！",
  str_voice_1400731_3 = "-我們是小惡魔，-所以有角；\n-我們是小狗，-所以有尾巴；\n-我們有三叉戟，所以要欺負你！",
  str_voice_1400731_4 = "-狗火，狗鼻子，-因為是狗狗所以才有這些能力，\n-不是很正常嗎？-對喔，你沒有尾巴，你不知道。",
  str_voice_1400731_5 = "-地獄火焰燒起來，燒起來，燒起來♪\n-地獄火焰燒起來，快逃呀，帕皮♪",
  str_voice_1400731_6 = "-地獄的大門打開了，-其實很早以前就打開了，\n-但我們是看門人，-不該出來的不會讓它出來！",
  str_voice_1400731_7 = "-快讓我們欺負你一下！-反對無效！\n-欺負老大的時候！-老大也沒說什麼！",
  str_voice_1400731_8 = "-帕蒂和帕西不能離開對方，-離開對方心臟會停下來，\n-帕皮呢？-讓帕皮也停下來吧！",
  str_voice_1400731_9 = "-你害怕地獄嗎？-如果掉下去了，\n-就喊我們的名字，我們會幫你開門，然後帶你回來。",
  str_voice_1400731_10 = "-好無聊，\n-好想玩點什麼……\n-帕皮快逃吧，我們追你！哈哈哈！",
  str_voice_1400731_11 = "-提問！我們到底是什麼？\n-再給你一次機會回答！\n-對！是守門小惡魔！哈哈哈。",
  str_voice_1400731_12 = "-現在開始捉迷藏，\n-三、二、一！……\n-找、到、你、了！哈哈哈哈！",
  str_voice_1400731_13 = "-帕西有尾巴，-帕蒂也有尾巴，\n-老大的尾巴呢？-從來沒看過。",
  str_voice_1400731_14 = "-首先，點上狗火！\n-然後，舉起惡魔的叉子！\n-最後，追趕帕皮！",
  str_voice_1400731_15 = "-今天要為你慶祝！\n-捉迷藏嗎？-挖寶藏嗎？\n-要不要尾巴？一起玩吧！",
  str_voice_1400731_16 = "-內有萌犬，\n-歡迎入內！\n-進來了就讓我們追趕你吧！",
  str_voice_1400731_17 = "-帕皮來了，-已經醒了嗎？\n-沒有尾巴看不出來，-好可憐喔。",
  str_voice_1400731_18 = "-餓了，-還想吃點什麼，\n-帕皮身上有肉嗎？-讓我們啃啃吧！",
  str_voice_1400731_19 = "-帕蒂好睏喔。-帕皮來了唷。\n-怎麼辦……？-再和帕皮玩一會吧。",
  str_voice_1400731_20 = "-有人說過，-那裡有想要的生活，\n-生活無所謂，-「想要的」比較重要！",
  str_voice_1400731_21 = "-浮空的，-白色的，\n-很乾淨有食物，-那個人想去的地方。",
  str_voice_1400731_22 = "狗狗在看著你！",
  str_voice_1400731_23 = "-暗鬼不好吃，\n-一大群的時候很可怕，\n-只有幾個就沒關係，-全部消滅！",
  str_voice_1400731_24 = "-朋友不可以吃，-可以追，\n-那隻有翅膀的，-烏鴉，\n-是可以追的朋友。",
  str_voice_1400731_25 = "-喜歡狗狗的，-陰沉的人，\n-雖然沒有表情，-但是是好人！",
  str_voice_1400731_26 = "-喜歡的東西是食物，-欺負別人，\n-尾巴和惡魔角，-喜歡狗狗的人！",
  str_voice_1400731_27 = "-討厭對狗狗不好的人！\n-討厭血的氣味！",
  str_voice_1400731_28 = "-真好！-這裡面很寬敞！\n-可以亂跑，-玩捉迷藏。\n-可以啃他？-可以。",
  str_voice_1400731_29 = "-帕蒂、-帕西、-帕皮！\n-帕皮是誰，-帕皮是小狗……\n-誰來當小狗？當然是你當啦哈哈！",
  str_voice_1400731_30 = "-嗯嗯！\n-美味的力量！",
  str_voice_1400731_31 = "-火變大了！\n-鼻子更加靈敏！",
  str_voice_1400731_32 = "-小惡魔力量增強！\n-地獄力量增強！",
  str_voice_1400731_33 = "-看到了！\n-地獄之門！\n-就在這裡！",
  str_voice_1400731_34 = "汪汪出擊！",
  str_voice_1400731_35 = "尾巴站起來了！",
  str_voice_1400731_36 = "給你看看叉子？",
  str_voice_1400731_37 = "地獄的火焰，烤焦牠們！",
  str_voice_1400731_38 = "開啟，地獄之門！捲起來，地獄之火！",
  str_voice_1400731_39 = "-砰！\n-哈哈！",
  str_voice_1400731_40 = "烤熟！",
  str_voice_1400731_41 = "-小惡魔領隊！\n-出發！",
  str_voice_1400731_42 = "快看看我們找到了什麼寶貝！",
  str_voice_1400731_43 = "-嗚……\n-一點都不好玩！",
  str_voice_1400731_44 = "喂！帶了什麼好吃的給我們嗎？",
  str_voice_1400731_45 = "-嗚哇，\n-聞起來很難吃……",
  str_voice_1400731_46 = "-嗯嗯！\n-這個聞起來真棒！",
  str_voice_1400731_47 = "-是帕皮帶來的！\n-不能嫌棄！",
  str_voice_1400731_48 = "-這個！\n-這個！\n-超棒！",
  str_voice_1400731_49 = "-狗狗最適合捉迷藏，-不管目標在哪裡，\n-只要你留下氣味，-只要你還活著，\n-我們就能找到！",
  str_voice_1400731_50 = "-在影鎮裡可以隨意弄到食物，-可以被商會的人抓住，\n-纏著他們要吃的，-他們跑不掉也沒辦法。",
  str_voice_1400731_51 = "-那時候學會了用「狗火」，-吃烤熟的食物不容易弄壞肚子，\n-只要有力量，-幼小的生物也能活下去。",
  str_voice_1400731_52 = "-白夜！\n-極光！",
  str_voice_1400731_53 = "唷！帕皮！",
  str_voice_1400731_54 = "-早！\n-汪！",
  str_voice_1400731_55 = "-午飯！\n-加飯！",
  str_voice_1400731_56 = "-晚上了！\n-來玩！",
  str_voice_1400731_57 = "-狗年！\n-快樂！",
  str_voice_1400791_1 = "稅務官的工作並不繁重，只需要收取白夜幣和記錄，這是我所擅長的事，因此處理起來很快。",
  str_voice_1400791_2 = "常有人說我沒有心，但我認為心靈是盛放信念之地，我有好好地將信念展示出來，不是嗎？",
  str_voice_1400791_3 = "事物的價值由衡量標準決定。目前的局勢是城主權重，衛隊長言輕；三年之後，將是城主言輕，衛隊長權重。",
  str_voice_1400791_4 = "古老的家族終會沒落，但能留下公正裁決的傳統……至少，它在我身上有所體現。",
  str_voice_1400791_5 = "「裁決天平」是由信仰驅動的道具，以「基準」為信念，藉由提問來衡量，沒有對錯，只有輕重。",
  str_voice_1400791_6 = "裁決之人會接受以同樣標準審判嗎？答案當然是肯定的，真正的公平才可透過人之眼判斷——",
  str_voice_1400791_7 = "我常會思考，在這裡與您對話會為我帶來什麼價值？……請別介意，這只是出於習慣。",
  str_voice_1400791_8 = "我隱隱約約感覺到，您身上出現了不一樣的價值？這附加之物來自於什麼？為何您不同於他人？",
  str_voice_1400791_9 = "有時候，我會突然想付給您十枚白夜幣，這很奇怪嗎？但我理解它，就像理解您對於我的意義。",
  str_voice_1400791_10 = "在擔心時間的問題嗎？繼續休息吧，空閒讓人心胸開闊，而開闊的心胸會產生相應的價值。",
  str_voice_1400791_11 = "您為何喚我前來？雖然不太明白，但我會積極衡量自身為您帶來價值。",
  str_voice_1400791_12 = "很抱歉，我……除了會使用天平之外，沒有別的技能。",
  str_voice_1400791_13 = "您是否明白，世事大多沒有正確與否，只有程度的輕重。",
  str_voice_1400791_14 = "不可輕賤，不可過量……僅僅兩句話，已經十分困難。",
  str_voice_1400791_15 = "生日的價值是公眾認可的，來慶祝吧，慶祝百枚白夜幣的份量。",
  str_voice_1400791_16 = "歡迎回來，現在最黃金的工作時間，至少值十枚白夜幣。",
  str_voice_1400791_17 = "早安，建議您進行相當於三枚白夜幣的運動量，它的價值將會加倍。",
  str_voice_1400791_18 = "您會在經歷一天的活動後，做出相當於一枚白夜幣的總結嗎？",
  str_voice_1400791_19 = "我不會催您休息，無論何種選擇，只要出於您的意志，就有價值。",
  str_voice_1400791_20 = "「天平」正是白夜城賜予我們的，融於整個家族的使命和意義。",
  str_voice_1400791_21 = "我的確想衡量一下，那些人口中，真理的價值。",
  str_voice_1400791_22 = "白夜至上。",
  str_voice_1400791_23 = "很遺憾，十隻普通暗鬼的總價加起來，甚至不值一枚白夜幣。",
  str_voice_1400791_24 = "公爵小姐確實幫助我許多，但她似乎並不喜歡我付給她白夜幣。",
  str_voice_1400791_25 = "令人難以理解，她的標準是否源自於她金色的信念？",
  str_voice_1400791_26 = "是指喜歡做的事嗎？那麼，檢查天平和帳目，以及折合換算。",
  str_voice_1400791_27 = "公正者應當摒除自身喜惡……只是，我不擅長面對模糊不清之物。",
  str_voice_1400791_28 = "這十分罕見，他是超出了「裁決天平」衡量能力的物體。",
  str_voice_1400791_29 = "初次見面，我為衡量之人，但您的價值並不取決於我的衡量，它取決於您的表現。",
  str_voice_1400791_30 = "衡量，將更加準確。",
  str_voice_1400791_31 = "潛力增值。",
  str_voice_1400791_32 = "更加明晰的裁決。",
  str_voice_1400791_33 = "奪回公平！",
  str_voice_1400791_34 = "我知道，加碼。",
  str_voice_1400791_35 = "校準完成。",
  str_voice_1400791_36 = "請確認砝碼。",
  str_voice_1400791_37 = "裁決將被見證——",
  str_voice_1400791_38 = "接受眾生的審判吧——",
  str_voice_1400791_39 = "平等的——",
  str_voice_1400791_40 = "公正的——",
  str_voice_1400791_41 = "為了公平的決斷。",
  str_voice_1400791_42 = "理應做出公正的判定。",
  str_voice_1400791_43 = "因微小的誤差，淪落至此……",
  str_voice_1400791_44 = "示好是對等的，您想要什麼？",
  str_voice_1400791_45 = "根據它的價值，回應為「我收下了」。",
  str_voice_1400791_46 = "感謝，這將是很有價值的東西。",
  str_voice_1400791_47 = "在它的價值上，或許該增添一份情感。",
  str_voice_1400791_48 = "感謝，以我所有，願盡數回報給您。",
  str_voice_1400791_49 = "冷漠與功利主義自然有其原因，如同天賦、武器一樣……至少，能讓我活得更好。",
  str_voice_1400791_50 = "普世的做法，是將理性當作判斷基準，但實際上，只是因為我們無法正確地駕馭情感，才不敢使用。",
  str_voice_1400791_51 = "不受情感影響，能幫助我進行更公正的決斷，但當我被她稱為無情怪物的時候，我為不公正而感到難過。",
  str_voice_1400791_52 = "白夜極光。",
  str_voice_1400791_53 = "開始審問。",
  str_voice_1400791_54 = "早安，您應當珍惜手中的白夜幣。",
  str_voice_1400791_55 = "午安，您增值的機會到了。",
  str_voice_1400791_56 = "晚安，請選擇。",
  str_voice_1400791_57 = "祝，新年快樂。",
  str_voice_1400811_1 = "人氣票選？那種東西，難道有人能比得過我嗎？……什麼！？我的得票竟然最低？",
  str_voice_1400811_2 = "沒——錯，我遲早會打敗醒山成為紅油扳手的首領！嗯？我和他的勝率？目前……七百二十八敗三平零勝。",
  str_voice_1400811_3 = "為了拿那個什麼「清潔環境第一名」，我可是把所有的汽車打掃一遍！結果竟然是騙我的……但即使這樣也好高興。",
  str_voice_1400811_4 = "一百七十二、一百七十三……哈哈，我今天解決了一百七十三隻暗鬼！！！你呢？！",
  str_voice_1400811_5 = "為了能「變強」，必須提高文化水準——歐緹教過我，但才一個星期她就宣布我畢業了。難道……我真的是天才？",
  str_voice_1400811_6 = "失敗？我太習慣了，但那打不倒我。挑戰與衝撞、熱血與激情，遇到再大的困難我都會克服，這就是黑潮的一生！",
  str_voice_1400811_7 = "從今天開始，你就是我的兄弟了！肝膽相照！別擔心，我絕對會好好保護你的！",
  str_voice_1400811_8 = "讓我教教你，什麼才是男人吧！聽好，男人生命中最重要、最重要的三個東西，是渦輪、運動鞋和蛋白粉。",
  str_voice_1400811_9 = "為什麼要擔心呢？你明明已經做得很好了！明天的狂風暴雨、山崩地裂就留給明天！燃燒此刻就夠了！",
  str_voice_1400811_10 = "啊——好無聊，無聊到身體都快僵住了。先做做暖身運動吧，哈嚏！",
  str_voice_1400811_11 = "好眼光！我可是紅油扳手最可靠的人！",
  str_voice_1400811_12 = "對，我是懼高……但懼高又不是……對，我還有點怕蟲子……",
  str_voice_1400811_13 = "我又弄來了一瓶新噴漆！螢光色，現在可以好好改裝一下汽車了。",
  str_voice_1400811_14 = "真男人就應該睡在沙漠裡！蓋上被子——不是沙子！",
  str_voice_1400811_15 = "哇！今天是你生日！其實我也……不對我的生日是幾號啊？",
  str_voice_1400811_16 = "哼～早起的紅油成員有……怎麼白夜城衛兵已經開始巡邏了！快跑！",
  str_voice_1400811_17 = "導航員，晨跑嗎？我可是紅油扳手跑得最快的，你開車我都能跟上！",
  str_voice_1400811_18 = "肚子好餓，今天晚上不會又吃沙蟲吧，噁。",
  str_voice_1400811_19 = "呼……呼嚕……嗯！？敵襲！？不對，今天明明不是我站崗！",
  str_voice_1400811_20 = "紅油扳手在我這個「二當家」的帶領下蒸蒸日上……欸！你別跟醒山說！",
  str_voice_1400811_21 = "為白夜城跑腿的商隊超級有錢，大肥羊！要是能天天碰到就好了。",
  str_voice_1400811_22 = "打倒暗鬼和白夜城，紅油扳手萬歲！",
  str_voice_1400811_23 = "暗鬼？也沒有多強啦，小意思，一分鐘就撂倒。",
  str_voice_1400811_24 = "你說約娜？糟糕，回憶起噩夢了，啊啊啊啊——",
  str_voice_1400811_25 = "我跟蕾吉娜關係變差，是從我說渦輪的聲音才是最完美的音樂開始。",
  str_voice_1400811_26 = "變強，男人就是要變強。鍛鍊肌肉，不要整天和跟弱雞一樣。",
  str_voice_1400811_27 = "我討厭白夜城衛兵，一頭銀髮，身高一八五，還……比我帥的那種。",
  str_voice_1400811_28 = "這傢伙也太大了，簡直是為我量身訂製！嗯？他是你的？不能給我嗎？",
  str_voice_1400811_29 = "速度的火焰！激情的風暴！渦輪中誕生的狂徒，黑潮參上！多多指教！這簡介是歐緹幫我寫的。",
  str_voice_1400811_30 = "感覺不錯！",
  str_voice_1400811_31 = "接下來更要全力以赴。",
  str_voice_1400811_32 = "唔喔喔喔喔喔喔力量在體內翻滾！！",
  str_voice_1400811_33 = "加足馬力，全速前進！",
  str_voice_1400811_34 = "快點快點！",
  str_voice_1400811_35 = "就是現在！",
  str_voice_1400811_36 = "看我一拳打飛你們！！！",
  str_voice_1400811_37 = "盡情釋放！",
  str_voice_1400811_38 = "消失殆盡！！",
  str_voice_1400811_39 = "轉速全開！！",
  str_voice_1400811_40 = "八檔聚變！！",
  str_voice_1400811_41 = "我是隊長？理所當然！",
  str_voice_1400811_42 = "今天的我，也很強！",
  str_voice_1400811_43 = "可惡，我偏不信……再來再來！",
  str_voice_1400811_44 = "別，別亂碰！啊——糟糕，熄火了，這可不是個好兆頭啊。",
  str_voice_1400811_45 = "欸欸欸——我也有禮物？",
  str_voice_1400811_46 = "這也太棒了吧！",
  str_voice_1400811_47 = "這……這……你你你……我……",
  str_voice_1400811_48 = "這也太用心了，嗚……嗚嗚嗚！",
  str_voice_1400811_49 = "講講以前的故事嗎？我對過去已經沒什麼印象了。紅油扳手的人沒有過去也沒有未來，只有現在。",
  str_voice_1400811_50 = "或許吧——或許有誤會，或許有什麼理由能夠解釋這些事情。但那些藉口卻治癒不了我的情緒，用暴力解決問題不是挺好的嗎？",
  str_voice_1400811_51 = "我想，當我和兄弟們駕駛著「風壓」汽車穿梭在曠野上的時候，我只知道一件事：我從來都不後悔加入紅油扳手。",
  str_voice_1400811_52 = "白夜極光。",
  str_voice_1400811_53 = "導航員。",
  str_voice_1400811_54 = "早上了！來鍛鍊嗎？",
  str_voice_1400811_55 = "等一下我要去挑戰醒山！",
  str_voice_1400811_56 = "好事！要不要來？",
  str_voice_1400811_57 = "明年我一定會贏！欸？新年了？",
  str_voice_1400911_1 = "我們身在命運的長流之中，一點一點向前，它只是捲著您前進，不在乎您是否準備好。",
  str_voice_1400911_2 = "非常、抱歉，我本不該說這些話……只是我不演奏時，會難以藏匿，會總是想起……",
  str_voice_1400911_3 = "有時候，我會因無法控制突如其來的顫抖，而在演奏中停下……很感激，城主大人沒有責罵我。",
  str_voice_1400911_4 = "就算已不想再面對，那噩夢中，盤根錯節的恐懼……卻也總是會擅自闖入，不肯饒恕我……",
  str_voice_1400911_5 = "過去是纏繞的絲線，在手腕上，在脖頸上，當我終於想起要解開它們時，卻找不到頭緒。",
  str_voice_1400911_6 = "我總是夢見那一天，夢見跌入沒有出口的深淵。直到如今，仍是落葉，沒有方向，不知去留……",
  str_voice_1400911_7 = "如果您心意已決，那就向前走吧，不必回頭，讓我留在過去，讓我守在那裡……如果您回來，歡迎您……",
  str_voice_1400911_8 = "有一天，我將要消失，會留下一些思念。願您帶著，再離去。就算丟進雲海，也好過無人聞問……",
  str_voice_1400911_9 = "真希望，我能一直靠近美夢……像清風、像雨霧、像筆直的小徑，像有光的路途。如您一般……",
  str_voice_1400911_10 = "我會演奏得更好，所以，請待在這裡，哪裡都不要去，拜託您，不要這麼快離開……",
  str_voice_1400911_11 = "您會離開我嗎？如雲中的鳥，如過境的雁……我保證，不給您帶來困擾……所以，留下吧。",
  str_voice_1400911_12 = "當明日再來，陰雲散去……願您的痛苦，得以痊癒。",
  str_voice_1400911_13 = "請取走這些淚水吧……讓它們停下……讓我也忘記。",
  str_voice_1400911_14 = "我知道，我需要演奏，只要不停止……或許就不會，流下眼淚。",
  str_voice_1400911_15 = "生日總是如期而至，但願您在出生第一天所見的光明，能陪伴您每一刻。",
  str_voice_1400911_16 = "歡迎回來，希望您的影子和聲音，能多停留一會。",
  str_voice_1400911_17 = "希望早晨，不總是清冷，而是像您到來之後那般，溫暖……",
  str_voice_1400911_18 = "我聽到了，您來的聲音，在斷續的琴弦上，在隱隱的燈火中。",
  str_voice_1400911_19 = "非常抱歉，到了這個時間……我總是，有點無法克制自己……",
  str_voice_1400911_20 = "白夜城裡，陽光無法照耀的地方，也刻著，密密麻麻的傷痕。",
  str_voice_1400911_21 = "希望啟光平和，也希望已經停止的鬥爭，永遠不會再被開啟。",
  str_voice_1400911_22 = "白夜至上……",
  str_voice_1400911_23 = "那是……困擾我內心的黑暗……是無法消抹的往日創傷。",
  str_voice_1400911_24 = "我能夠聽見，金色的她有不留痕跡的過往，在隱隱作痛……",
  str_voice_1400911_25 = "卡蓮十分堅強，能夠面對。我希望她……不會苛責自己。",
  str_voice_1400911_26 = "喜歡，與記憶中相似的……臂膀、依靠、守護、寧靜與和平。",
  str_voice_1400911_27 = "我不想面對它們……噩夢、寒冷、以及沒有出口的……迷宮。",
  str_voice_1400911_28 = "他擁有這麼大的翅膀，或許能夠將哀傷，都帶去遠方……",
  str_voice_1400911_29 = "後悔已是音符，在最初的那一刻定型為哀戚，不斷被奏起……初次見面，我是一名演奏者，名為克蘿伊。",
  str_voice_1400911_30 = "琴聲……更加悠遠……",
  str_voice_1400911_31 = "能夠感受到，琴弦在訴說……",
  str_voice_1400911_32 = "這樣……就能擺脫了嗎？",
  str_voice_1400911_33 = "或許能看見什麼，與從前不同……",
  str_voice_1400911_34 = "演奏……《夢幻曲》。",
  str_voice_1400911_35 = "下一曲，演奏什麼……",
  str_voice_1400911_36 = "將思緒寄於演奏之中……",
  str_voice_1400911_37 = "這是……哀傷的琴音。",
  str_voice_1400911_38 = "琴弦上，有無可避免的過去。",
  str_voice_1400911_39 = "想要驅散……",
  str_voice_1400911_40 = "驅散陰霾……",
  str_voice_1400911_41 = "如果有我能做到的……",
  str_voice_1400911_42 = "希望它，不會轉瞬即逝。",
  str_voice_1400911_43 = "如果不是我……拖累大家……",
  str_voice_1400911_44 = "還是……彈奏一曲，振作一下吧……",
  str_voice_1400911_45 = "不藉由話語，我不明白……",
  str_voice_1400911_46 = "這得來不易的禮物，我會十分珍惜。",
  str_voice_1400911_47 = "您總是會送我些什麼……",
  str_voice_1400911_48 = "多麼珍貴，我該如何珍惜，才足夠？",
  str_voice_1400911_49 = "我常常逃避，到詞曲中，到琴弦裡……但我知道，必須訴說自己的罪過，不可掩飾，需要直白……",
  str_voice_1400911_50 = "母親的身體並沒有強壯到能夠承受孕育生命的風險，如果不是因為我……她本該擁有安寧……",
  str_voice_1400911_51 = "在他最恐懼的時候，我沒能陪在他的身邊，直到最後，他都念著我的名字……",
  str_voice_1400911_52 = "白夜極光……",
  str_voice_1400911_53 = "那個……",
  str_voice_1400911_54 = "早安，您是否已經醒了？",
  str_voice_1400911_55 = "午安，其實我有些想拜託您的事……",
  str_voice_1400911_56 = "晚安，請小心著涼。",
  str_voice_1400911_57 = "願您新的一年，沒有悲傷～",
  str_voice_1500091_1 = "啊……這裡有太陽的力量。那是真理結社加密過的暗門，打開看看吧？說不定會發生有趣的事。",
  str_voice_1500091_2 = "憤怒與恐懼，累積得太多。它們就在黑暗中伺機待發……想知道更多嗎？",
  str_voice_1500091_3 = "真理的聲音是吻，是涓涓小河，是……維多利亞大人給的抄本果然很生澀，不好背啊。",
  str_voice_1500091_4 = "低語全數消失……我們渾然一體。共享這份喜樂吧，我會帶給您最大的愉悅——",
  str_voice_1500091_5 = "偉大的信仰值得付出一切，內心的安寧，神智，乃至生命和靈魂……",
  str_voice_1500091_6 = "真理早已不再向我傳達福音，因為我已經是其中的一員……把手給我，接下來便是天國。",
  str_voice_1500091_7 = "我欽佩您的信念和坦誠。但在絕對的愉悅面前，它必將動搖，不信的話就靠近點——",
  str_voice_1500091_8 = "有時，彼此的信念或許只有一線之差～哈哈，在下言盡於此，自行領悟吧。",
  str_voice_1500091_9 = "我從來沒有為您而戰喔，別搞錯了。只是因為您對我而言，也是一種愉悅而已……維多利亞大人也是一樣呢。",
  str_voice_1500091_10 = "願您能聽見，那陽光中傳遞的低語聲……哈哈，被聽出來了嗎，那種欠缺真誠的感覺。還得再練練呢。",
  str_voice_1500091_11 = "終於願意與我聆聽那低語了？有趣！真是有趣！",
  str_voice_1500091_12 = "貴安，這位先生，有興趣瞭解一下真理結社嗎？",
  str_voice_1500091_13 = "說到我的粉絲會——成員們都是體貼、可愛的女性，我很感謝她們。",
  str_voice_1500091_14 = "無法引導更多人追隨真理，總是令我難以入睡。",
  str_voice_1500091_15 = "慶祝吧，您將在此刻重獲新生！",
  str_voice_1500091_16 = "已經決定加入我們了嗎？",
  str_voice_1500091_17 = "從清晨開始禱告，直至夜幕黃昏……",
  str_voice_1500091_18 = "倘若逃避世界的真相，即使睜開雙眼，也依舊處於黑暗混沌之中。",
  str_voice_1500091_19 = "看啊，新星為您點亮……與我一起，驅散這瀆神的噩夢吧。",
  str_voice_1500091_20 = "真理結社乃是駛向天國之帆，告別虛無之翼。",
  str_voice_1500091_21 = "渺小眾生苟且偷生，可嘆可憐，還有一絲悲哀的可敬。",
  str_voice_1500091_22 = "願真理祝福您。",
  str_voice_1500091_23 = "舊時代積下的灰塵，終有一天能清掃乾淨。",
  str_voice_1500091_24 = "維多利亞大人是最完美的女性。如何，要加入真理結社嗎？",
  str_voice_1500091_25 = "聖釘恐怕根本沒有聽到我說了什麼，不過這不妨礙我們愉快地合作。",
  str_voice_1500091_26 = "我曾在旅行中見識了許多，也更加堅定了自己的信念。",
  str_voice_1500091_27 = "天哪，我怎麼會有討厭的東西呢？如果硬要說的話——除了真理以外的一切。",
  str_voice_1500091_28 = "令人敬佩的龐然大物，但在真理面前卻不值一提。",
  str_voice_1500091_29 = "愉悅之聲奏響，真理之國降臨，信徒得救，非信徒則化為齏粉。加入我們，獲得永逸的喜樂——",
  str_voice_1500091_30 = "我將轉達您的誠意——",
  str_voice_1500091_31 = "聲音正在腦海裡變得洪亮！",
  str_voice_1500091_32 = "追求真理的同胞們！",
  str_voice_1500091_33 = "一切慾念皆為原罪。",
  str_voice_1500091_34 = "沒有人可以逃脫。",
  str_voice_1500091_35 = "解放遠古的力量！",
  str_voice_1500091_36 = "真理說準備好了。",
  str_voice_1500091_37 = "這是真實的噩夢。",
  str_voice_1500091_38 = "我將撕裂現實。",
  str_voice_1500091_39 = "信仰永恆不變。",
  str_voice_1500091_40 = "真理即是唯一。",
  str_voice_1500091_41 = "我會為您示範一些有趣的事……",
  str_voice_1500091_42 = "追求真理的同胞們，這僅僅是個開始。",
  str_voice_1500091_43 = "……這份挫敗，也是您的安排嗎？",
  str_voice_1500091_44 = "想知道箱子裡面是什麼嗎？祕密。",
  str_voice_1500091_45 = "謝謝，但是……您比我還不擅長推銷呢。",
  str_voice_1500091_46 = "有趣，之前小看您了。",
  str_voice_1500091_47 = "呵呵，被看穿了呢。",
  str_voice_1500091_48 = "感謝，向您獻上吻手禮。",
  str_voice_1500091_49 = "您可聽聞，舊日於罪火中覆滅，甲士成骸，銀劍粉碎……",
  str_voice_1500091_50 = "放棄無知傲慢，穿越熔岩與荒漠的試煉，才可得到甘霖。",
  str_voice_1500091_51 = "我去過永恆國度，親眼見過背叛真知者和異徒的下場……雖然我不認為自己會殊途同歸，但也暫時接受了維多利亞大人的盛意。",
  str_voice_1500091_52 = "白夜極光。",
  str_voice_1500091_53 = "我的朋友啊……",
  str_voice_1500091_54 = "早安，我的朋友。",
  str_voice_1500091_55 = "午安，我的朋友。",
  str_voice_1500091_56 = "晚安，我的朋友。",
  str_voice_1500091_57 = "我的朋友，新年快樂！",
  str_voice_1500421_1 = "這鐵顎的用處？上一個這麼問的傢伙，腦袋就像核桃一樣碎了一地。這就是它的用處。",
  str_voice_1500421_2 = "你為什麼不為巨像取個女孩的名字呢？這樣你和她一起上戰場時才會不離不棄。",
  str_voice_1500421_3 = "認為我可笑！？天知道還有什麼傢伙在未來等著我們！戰爭就一直在我們身邊！",
  str_voice_1500421_4 = "能用槍解決敵人，絕不用刀。到時候叫貢露幫我弄幾發穿甲彈，讓那群傢伙知道什麼是絕望。",
  str_voice_1500421_5 = "平日多流一桶汗，戰時少流一瓶血。",
  str_voice_1500421_6 = "人們都說子彈不長眼睛，可惜它們卻躲著我前進！哈哈！",
  str_voice_1500421_7 = "今日天氣不錯，和我一起來場長途越野訓練？",
  str_voice_1500421_8 = "在戰場上沒人跟你談公正平等，只要贏了，用什麼爛招都行！要不要我教你？",
  str_voice_1500421_9 = "讓我看看你在戰場上的表情！啊？就這樣？簡直是嬰兒！哈哈！",
  str_voice_1500421_10 = "真是個不錯的週末，是來找我下棋的嗎？不是？那請離開吧，我自己一個人下。",
  str_voice_1500421_11 = "哈哈！你是希望我來看看你嗎？是不是沒人看著你，你就要無聊到快死了？",
  str_voice_1500421_12 = "聽說啟光的新兵訓練越來不像樣了？訓練基地的教官都是混飯吃的嗎？再這樣就一個個送去當靶子！！",
  str_voice_1500421_13 = "你閒得快抽筋了，有空還是去訓練一下，免得關鍵時刻閃到腰。",
  str_voice_1500421_14 = "沒有戰爭，當兵的人就什麼都不是。我可不想當一隻白吃白喝的蛀蟲。",
  str_voice_1500421_15 = "你還要過生日？那就來一場特別訓練吧？保證你宛如重生——",
  str_voice_1500421_16 = "這裡太安靜了。好想對什麼開幾槍啊！！",
  str_voice_1500421_17 = "起床了！懶鬼！這裡可不是你舒服的外婆家！",
  str_voice_1500421_18 = "一整天都沒什麼敵人，太無聊了！快找個暗鬼群把我扔下去吧！",
  str_voice_1500421_19 = "說起來，很久沒有通宵訓練了……既然你也在，不如一起嗎？",
  str_voice_1500421_20 = "啟光最近都忙著做生意，讓一群算帳的傢伙打仗，遲早被人打個稀爛。",
  str_voice_1500421_21 = "白夜城的騎士真是每個都死腦筋，居然在戰場上要求決鬥，在想什麼啊？",
  str_voice_1500421_22 = "為了啟明之光！",
  str_voice_1500421_23 = "領頭的爛，中間的不會指揮，低級只會聽從命令，烏合之眾！",
  str_voice_1500421_24 = "緋總是把「武士道」這個詞掛在嘴邊，耍什麼蠢啊？打仗本來就是能偷襲就偷襲！",
  str_voice_1500421_25 = "有機會我一定要跟萊因哈特說，休養生息也該適可而止，該備戰了！",
  str_voice_1500421_26 = "和平？呸！很多人在和平時就是混日子，只有戰爭才能讓他們有價值！",
  str_voice_1500421_27 = "真正軍人的歸宿是最後一顆子彈，否則在無聊的時光中終究會空虛。",
  str_voice_1500421_28 = "改天我也去弄個巨像！真想朝它腦袋上丟幾顆導彈！",
  str_voice_1500421_29 = "聽說有很多仗可以打啊！我是巴頓，啟光聯邦軍團長，讓我們去幹掉那些垃圾吧！現在，馬上！",
  str_voice_1500421_30 = "讓我去擊退敵人們！",
  str_voice_1500421_31 = "更加鋒利了。",
  str_voice_1500421_32 = "老兵永不死。",
  str_voice_1500421_33 = "我！即是軍團！",
  str_voice_1500421_34 = "是！",
  str_voice_1500421_35 = "子彈上膛了。",
  str_voice_1500421_36 = "大幹一場吧！",
  str_voice_1500421_37 = "用巴頓軍刀終結你們！",
  str_voice_1500421_38 = "嚐嚐彈雨的滋味吧！",
  str_voice_1500421_39 = "謝爾曼-改變！",
  str_voice_1500421_40 = "擊倒你們！",
  str_voice_1500421_41 = "跟我上！掃除敵人！",
  str_voice_1500421_42 = "垃圾！不是我的對手！",
  str_voice_1500421_43 = "先撤退吧！回頭再來！",
  str_voice_1500421_44 = "真閒，和我來一盤兵棋推演吧？",
  str_voice_1500421_45 = "啊，多謝。",
  str_voice_1500421_46 = "這個還不錯，可以用一用……",
  str_voice_1500421_47 = "這很貴重呢，我就收下了。",
  str_voice_1500421_48 = "哈哈！這個感覺和打仗一樣爽啊！",
  str_voice_1500421_49 = "現在這些局面都是小意思，幾年前那才是真正的戰爭！有機會我說給你聽。",
  str_voice_1500421_50 = "只有戰爭，才能讓我在這個歲數就成為軍團長。不過，潘戈就倒楣了，打仗嘛，總有人要挨子彈的。",
  str_voice_1500421_51 = "別看白夜城的四天使都是一群小姑娘，打起仗來卻不含糊，晚點要想個計策……",
  str_voice_1500421_52 = "白夜極光！",
  str_voice_1500421_53 = "喂！你在吧！",
  str_voice_1500421_54 = "早！",
  str_voice_1500421_55 = "你有空吧！",
  str_voice_1500421_56 = "睡了沒？",
  str_voice_1500421_57 = "哈！新年來了！",
  str_voice_1500751_1 = "啊——真是的！真想駭進紅油扳手那群蠢蛋的腦子裡面看看，至少把「沙蟲」改寫成「正常早餐」吧！",
  str_voice_1500751_2 = "不要小看技術人員，只要我想，你的地基也不保……你還能飛上天？那我就連翅膀一起毀囉！",
  str_voice_1500751_3 = "長得矮又怎樣？是偷吃誰家蜥蜴乾了嗎？見過那些光長個子不長腦子的傢伙嗎？紅油基地裡到處都是！",
  str_voice_1500751_4 = "我家的電纜有自驅能源，看看這扭力，可比外面那些卡拉肯強多了吧。",
  str_voice_1500751_5 = "嗚哇！這堆電纜又亂了！完了完了……為什麼你會被擊倒？……哈，我就說你完了吧。",
  str_voice_1500751_6 = "誰家的通訊頻道這麼破爛？對，是我駭的，怎麼樣？有本事順著訊號來戰，沒本事就少廢話！",
  str_voice_1500751_7 = "有個巨像了不起嗎？不要偷偷廢話，不服氣的話約個地方決勝負啊，把你打成廢鐵就結束了。",
  str_voice_1500751_8 = "我哪裡無情了？我除了提醒你珍惜時間，還能激勵你發憤向上呢，不然你老是在外面被人欺負，像話嗎？",
  str_voice_1500751_9 = "不錯，我欣賞你，今天就把說話技巧都傳授給你，免得你以後和別人對罵的時候吃虧。",
  str_voice_1500751_10 = "電纜配置完畢，通訊偵測完畢，恕我直言，在座的各位都是……嗚哇，怎麼又開始暴走了？哪又出漏洞了嗎？",
  str_voice_1500751_11 = "可以，今天我一定幫你把方圓十里的通訊頻道都駭過一遍……嗯？不需要嗎？可我已經駭了一半……",
  str_voice_1500751_12 = "待在這讓我想起紅油裡那隻破爛蜥蜴和某個大姐的哭訴……想到就頭痛。",
  str_voice_1500751_13 = "這些傢伙扭得還不如我的電纜器好看，賣力一點好嗎？",
  str_voice_1500751_14 = "那群笨蛋隊友總是弄壞裝備，一點都不知道「愛惜」兩個字怎麼寫。",
  str_voice_1500751_15 = "今天我讓你見識一下技術人員的能力！生日想怎麼過？要不要飛上天？",
  str_voice_1500751_16 = "兩分十五秒前我就知道你要回來了，這就是天才的通訊技術，懂嗎？",
  str_voice_1500751_17 = "這破巨像怎麼停，讓我稍微試一下……嗚哇！怎麼開始震動了？！",
  str_voice_1500751_18 = "有什麼困難？讓我來，隨便就……等等，算了，你繼續！",
  str_voice_1500751_19 = "你來得正好，通訊頻道裡有人在叫囂……那傢伙約你去迦南城見面！",
  str_voice_1500751_20 = "加入紅油扳手的理由？一句兩句說不清楚，混著混著就留下來了吧。",
  str_voice_1500751_21 = "來點任務，最好是駭進啟光通訊的那種……怕什麼？我幫他們找漏洞呢。",
  str_voice_1500751_22 = "我們紅油從沒怕過任何人！",
  str_voice_1500751_23 = "見了暗鬼我必拆，從裡到外拆個精光！挫骨揚灰！",
  str_voice_1500751_24 = "叫黑潮那傢伙離我一遠點。修不好的東西除了廢鐵之外就是他的腦子。",
  str_voice_1500751_25 = "有本事讓他來啊！看他一臉得意，再大的扳手還不是要我和小不點修！",
  str_voice_1500751_26 = "我配的裝置都順利運行中，幫我弄點高熱量食物來讓我補充一下。",
  str_voice_1500751_27 = "最麻煩的事就是有漏洞，如果再加上弄丟眼鏡……我一定會崩潰。",
  str_voice_1500751_28 = "你的巨像居然不是破銅爛鐵，內裝完整，功能完備！我看上了！",
  str_voice_1500751_29 = "我，歐緹。從今天開始，誰敢搞你家的通訊系統就報我的名字，馬上就能把對方嚇到腿軟！",
  str_voice_1500751_30 = "配置升級，輕鬆。",
  str_voice_1500751_31 = "居然能秒殺嗎？",
  str_voice_1500751_32 = "不就跟平時一樣……好起來了！",
  str_voice_1500751_33 = "來點作用……對，這就是標準答案！",
  str_voice_1500751_34 = "上就上。",
  str_voice_1500751_35 = "要搞誰，說吧。",
  str_voice_1500751_36 = "怕什麼？ 打倒它們吧。",
  str_voice_1500751_37 = "嗚哇！這電纜又要暴走了！",
  str_voice_1500751_38 = "我擊不出來啊！……啊，它們自己倒了？",
  str_voice_1500751_39 = "別亂動！",
  str_voice_1500751_40 = "攻擊奏效了？",
  str_voice_1500751_41 = "等等，要我來帶隊嗎？！",
  str_voice_1500751_42 = "哈，一堆破銅爛鐵。",
  str_voice_1500751_43 = "這……沒辦法！沒辦法！！",
  str_voice_1500751_44 = "就這也想……嗚哇！不要突然湊過來！",
  str_voice_1500751_45 = "看出來了，你不太會挑禮物。",
  str_voice_1500751_46 = "看出來了，你……很會挑禮物！",
  str_voice_1500751_47 = "我就知道你會送這個出來。",
  str_voice_1500751_48 = "你真是個人才，很懂我！",
  str_voice_1500751_49 = "只要是有關機械設備的問題就沒有我解決不了的，如果有，就證明那是個鐵做的垃圾！",
  str_voice_1500751_50 = "爛車、爛槍、爛扳手……我修好的破爛數不勝數，你這有什麼破爛都一起端上來吧。",
  str_voice_1500751_51 = "我可是被技術養大的人，崇尚科學交流，友善平等……誰、誰惹事？我一定一天之內讓他後悔。",
  str_voice_1500751_52 = "白夜極光。",
  str_voice_1500751_53 = "喂喂？",
  str_voice_1500751_54 = "你醒了嗎？",
  str_voice_1500751_55 = "快來！對罵時間！",
  str_voice_1500751_56 = "你睡了？我不信！",
  str_voice_1500751_57 = "省點力氣！明年再見吧～",
  str_voice_1500921_1 = "條律即是萬物運行的法則，難以理解我為何執著於它嗎？很簡單，因為我們取得智慧的意義就在其中。",
  str_voice_1500921_2 = "反駁的重點在於指出對方的錯誤，這是一種優異的特質，偶爾用雙手實踐也不錯，比如教訓某個懺悔狂！",
  str_voice_1500921_3 = "你說數字「1」？不不不，我說的是文字「一」，文字「一」和數字「1」有什麼不一樣？這麼簡單的問題我相信你不會不明白吧？",
  str_voice_1500921_4 = "準確來說，「獵石」也不是個輪子，而是某個遺跡裡面的遺物……但它明明就是個輪子呀！",
  str_voice_1500921_5 = "條律會在黑暗中為你點亮燈光，從現在開始，先整理一下思緒，想想你希望變成什麼樣的存在吧！",
  str_voice_1500921_6 = "星辰下降臨，無名過去的遺物，被稱為「獵石」的荊棘之輪——追逐吧，一如我的執著，一如那條律。",
  str_voice_1500921_7 = "用完的東西要放回原位，按照大小分類，按照字母排序，擺正擺好……你不用去，我已經幫你整理完了。",
  str_voice_1500921_8 = "你要我跟你走我就要跟你走嗎？才不要……你不讓我跟你走我才要跟你走！懂了吧！",
  str_voice_1500921_9 = "好不容易才找到你，我得仔細想想下一步要對你做什麼，而且只要能待在這裡，我還可以想更久！",
  str_voice_1500921_10 = "要嘛你跟我走，要嘛我帶你走，你可以慢慢考慮，或者我來幫你選……你不講話我就當作你同意了！",
  str_voice_1500921_11 = "你最好別在我面前跑，否則我會忍不住想開始追。嗯！最好不要背對我……眼神不要總是盯著這裡……也別移開視線！",
  str_voice_1500921_12 = "你不覺得這樣不好嗎？難道只有我一個人覺得很沒意思嗎？",
  str_voice_1500921_13 = "為什麼不放棄？因為我不想放棄吧，難道還有其他理由嗎？你說呀。",
  str_voice_1500921_14 = "明辨是非，腳踏實地，目視遠方！",
  str_voice_1500921_15 = "禮物，祝福，聽說還要唱歌，一項都不能少，今天要整齊體面！",
  str_voice_1500921_16 = "既然你都回來了，那我們應該要做些什麼吧？不然你來幹嘛？",
  str_voice_1500921_17 = "你一定已經訂好行程表了吧！……不是吧，沒有嗎？",
  str_voice_1500921_18 = "我比你想像得更頑固，可能哪天你會看到我就想逃吧。",
  str_voice_1500921_19 = "你應該按照行程表行動，比如現在就去休息……嗯？難道不是嗎？",
  str_voice_1500921_20 = "既然決定加入，那當然要一心追尋，放心，我會替真理救贖你。",
  str_voice_1500921_21 = "那就從眼前的目標出發，一步一步走上浮空城吧，反正又不是登天。",
  str_voice_1500921_22 = "我覺得應該改成「讓真理祝福你」！",
  str_voice_1500921_23 = "啊，真是的……難以置信！能讓那種隨意的傢伙，隨意奪取生命嗎？",
  str_voice_1500921_24 = "奉那位至高存在的命令，我來……什麼？你連那位大人都不知道嗎？",
  str_voice_1500921_25 = "別那麼三八，我只是隨口說說……那傢伙的笑容上就多了些青筋呢。",
  str_voice_1500921_26 = "鍥而不捨……等等，喜歡是什麼意思？物品嗎？愛好嗎？信念嗎？",
  str_voice_1500921_27 = "長相隨意，行為無序，而且還毫無目的，這種傢伙我怎麼能容忍？",
  str_voice_1500921_28 = "我當然知道巨像是什麼，他代表你是個特殊傢伙，不是嗎？",
  str_voice_1500921_29 = "你問我名字我就要介紹我的名字嗎？你不怕我說假話嗎？我要是打死不說呢？……你不想知道了？我叫「契法」～",
  str_voice_1500921_30 = "達成，下一個。",
  str_voice_1500921_31 = "總有一天我會把「獵石」甩掉，總有一天！",
  str_voice_1500921_32 = "條律即是真理，懂了吧！",
  str_voice_1500921_33 = "沒有迷失的曠野。",
  str_voice_1500921_34 = "為什麼要我來？",
  str_voice_1500921_35 = "我可沒說準備好了！",
  str_voice_1500921_36 = "通知你？才不要！",
  str_voice_1500921_37 = "束縛？不，這是執著！",
  str_voice_1500921_38 = "謹遵條律、絕無動搖！",
  str_voice_1500921_39 = "站住！",
  str_voice_1500921_40 = "等著瞧吧！",
  str_voice_1500921_41 = "聽著，勿犯條律之戒。",
  str_voice_1500921_42 = "條律必將有罪有罰！",
  str_voice_1500921_43 = "追上他們，一個也別放過……",
  str_voice_1500921_44 = "閒聊？好呀。那先約定，不管我說什麼你都別生氣。",
  str_voice_1500921_45 = "太小不看，太大不收。",
  str_voice_1500921_46 = "要是我表現出很喜歡的樣子，豈不是……",
  str_voice_1500921_47 = "這太……你都送了，我是不會還你的。",
  str_voice_1500921_48 = "對啦，我就是喜歡這個啦，怎麼樣嘛！",
  str_voice_1500921_49 = "難以被破壞，無法被銷毀，不管多少次都會生長出來，不管丟到哪裡都會跑回來，「獵石」也太頑固了吧？",
  str_voice_1500921_50 = "信仰樸素的條律，依靠並維護秩序，忠於內心的意志，堅定而莊嚴，這是邁向偉大真理的第一步！",
  str_voice_1500921_51 = "為何而生存？為何而鬥爭？有一天，當我忽然抬頭，看見星辰照亮天上的黑暗，便得到了內心的啟示。",
  str_voice_1500921_52 = "白夜極光！",
  str_voice_1500921_53 = "我提醒你。",
  str_voice_1500921_54 = "三秒內給我回覆。",
  str_voice_1500921_55 = "你也該出現了。",
  str_voice_1500921_56 = "我來檢查你睡著了沒。",
  str_voice_1500921_57 = "新年快樂，來，一起說！",
  str_voice_1600061_1 = "人多難以決策，獨自一人時頭腦反而會變得清晰無比。",
  str_voice_1600061_2 = "審判庭，元老院，我等身在其中，首先要知曉自己的位置，才可採取正確的行動。",
  str_voice_1600061_3 = "雖然我不想讓宴會早早結束，但我更不能浪費這美好的午夜——那是頭腦最清晰的時刻。",
  str_voice_1600061_4 = "過去需要力量，現在需要秩序。雖然不想承認，但這的確是他教會我的道理。",
  str_voice_1600061_5 = "白夜城不會用權力透支民眾剛建立的信心，特別是在這混亂時代，母親一定也會這麼認為。",
  str_voice_1600061_6 = "黑蜘蛛？那只是用來麻痺現實疼痛的無聊傳說。若真的存在，衛隊早就解決了。",
  str_voice_1600061_7 = "信賴多是背叛萌芽的溫床，但閣下似乎和外面那些人不一樣。我看人一向很準。",
  str_voice_1600061_8 = "冰華的美紋越多，便越脆弱，白夜城亦然……你其實早就看出來這一點了吧。",
  str_voice_1600061_9 = "最為難得之事便是相互的認可和尊重，我有將傳承推向頂峰的決意，也希望請你見證。",
  str_voice_1600061_10 = "請容我提醒，你還有任務在身，這副毫無幹勁的樣子……唉，反正你沒有工作考核。",
  str_voice_1600061_11 = "很美麗的地方，希望你的指揮力能與之相得益彰。",
  str_voice_1600061_12 = "當下的寬容不代表對現狀的滿意。",
  str_voice_1600061_13 = "有什麼事需要一起討論嗎？兩個人思路會更清楚……",
  str_voice_1600061_14 = "如果你遇見衛隊的人……希望拉斐爾沒有給你添麻煩。",
  str_voice_1600061_15 = "今天是你的誕生日，祝福你，願你能夠變得更加強大。",
  str_voice_1600061_16 = "簡報已到，何時行動？",
  str_voice_1600061_17 = "很好，早點做好行動準備。",
  str_voice_1600061_18 = "大部分工作已經結束，需要統一整理報告書。",
  str_voice_1600061_19 = "稍微休息一下吧，想必明天也還有很多需要處理的事。",
  str_voice_1600061_20 = "白夜城將會為這片大陸開拓出新的未來，為此需要繼續努力不懈。",
  str_voice_1600061_21 = "作為對抗黑暗的力量，啟光是不容忽視的。",
  str_voice_1600061_22 = "白夜至上！",
  str_voice_1600061_23 = "暗鬼是植根於這個世界的黑暗，只有消滅牠們，才能拯救一切。",
  str_voice_1600061_24 = "希望拉斐爾不要叫我姐姐，我的年齡沒有那麼大。",
  str_voice_1600061_25 = "加百列盡職盡責，但鞭策自己的動力較低，希望她在工作上更加投入。",
  str_voice_1600061_26 = "喜歡的東西？很簡單，兵法、看競技比賽……其他還有，雪花糕。",
  str_voice_1600061_27 = "我討厭沒有時間觀念的人，請記住。",
  str_voice_1600061_28 = "這座巨像十分完整，他或許能承載我的……不，什麼都沒有。",
  str_voice_1600061_29 = "我乃舒瓦茲城主之女、白夜城的守護者、卡蓮·德·舒瓦茲。有我在，這座美麗的城市，將不會重蹈覆轍。",
  str_voice_1600061_30 = "長槍，鋒銳如常！",
  str_voice_1600061_31 = "從此，黑暗將無所遁形。",
  str_voice_1600061_32 = "我的長槍會刺破夜空。",
  str_voice_1600061_33 = "聽從號令、唯有前進！",
  str_voice_1600061_34 = "卡蓮，準備就緒。",
  str_voice_1600061_35 = "下一擊，透穿命門。",
  str_voice_1600061_36 = "不用每次都問！",
  str_voice_1600061_37 = "黑暗，正在凋零！",
  str_voice_1600061_38 = "冰花於霜天中怒放！",
  str_voice_1600061_39 = "散開！冰花！",
  str_voice_1600061_40 = "穿透敵人！",
  str_voice_1600061_41 = "戰機尚在，迅速出擊！",
  str_voice_1600061_42 = "意料之中，我們沒有行動失敗的傳統。",
  str_voice_1600061_43 = "請不要氣餒。失利將成為基石。",
  str_voice_1600061_44 = "如果閣下只是來聊天的話，注意一下時間比較好。",
  str_voice_1600061_45 = "但願你不是因為別有所圖才這樣做。",
  str_voice_1600061_46 = "沒想到會從你手上得到我需要的……謝謝。",
  str_voice_1600061_47 = "謝謝，我知道這是你的好意。",
  str_voice_1600061_48 = "你總是明白我需要什麼，謝謝你。",
  str_voice_1600061_49 = "我一直試圖瞭解他，那位白夜城的統治者，我的父親。抱歉，但我的確還不習慣那樣稱呼他，因為一些讓人無法忘懷的往事……",
  str_voice_1600061_50 = "舊傷痊癒得很慢，沒有人會願意再去探尋這座城市的過去。短短十幾年，發生了太多事，說是家族​​變故也毫不為過。但沒人願意告訴我真相……",
  str_voice_1600061_51 = "安寧的夜晚，卻多幾分清冷。現在我只能從家人的畫像重溫過去，可笑嗎？可嘆吧。這座城的核心，究竟隱藏什麼樣的祕密……",
  str_voice_1600061_52 = "白夜極光。",
  str_voice_1600061_53 = "打擾一下。",
  str_voice_1600061_54 = "早安。",
  str_voice_1600061_55 = "午安。",
  str_voice_1600061_56 = "時間已晚。",
  str_voice_1600061_57 = "謹賀新年。",
  str_voice_1600141_1 = "白夜城，那是信念留存之處，它永不淪陷。無論再來幾次暗潮危機，都是如此。",
  str_voice_1600141_2 = "尊卑無序，貴賤無別，要如何管理此地？憑藉所謂的羈絆？好，我拭目以待。",
  str_voice_1600141_3 = "白夜城是極光下的新星，它是永恆的港灣。我對它的感情，你不會懂的。",
  str_voice_1600141_4 = "看著此處一團和氣，我也感到些許懷念。懷念平和尚在時，和約書亞一起那段毫無警覺的日子……",
  str_voice_1600141_5 = "我的孩子們……若是她們決意相許，只願你能擔此重責。否則——你會被我碾為齏粉。",
  str_voice_1600141_6 = "作為最高的統治者，很多時候需要使用雷霆手段，方顯仁德之心。",
  str_voice_1600141_7 = "不知己，不知敵，在我眼裡與無知的庶民沒有區別。你在進步，但還不夠。",
  str_voice_1600141_8 = "紅油扳手和啟光最多只能算是隱患，但日蝕……抱歉，有些情報我還無法與你分享。",
  str_voice_1600141_9 = "這巨像，在你頭腦之中吧？看來你的體質也跟她一樣呢。命運多麼頑皮，將我們都牽引到這混亂的漩渦中。",
  str_voice_1600141_10 = "物資、運送，人員安排，視野、路線、行進規劃……這裡意料之中地如同一團亂麻。",
  str_voice_1600141_11 = "我沒有義務幫你整頓巨像。當做膜拜的機會吧，我盡量保持我的耐心。",
  str_voice_1600141_12 = "言語雖是風，卻也是利劍，能夠用它解決敵人，何必動用武力。",
  str_voice_1600141_13 = "勝利者無需解釋，失敗者莫言苦衷。",
  str_voice_1600141_14 = "有時候，你需要隱藏自己的精明，那才是真正的精明。",
  str_voice_1600141_15 = "生日？那你可以休息一天了。",
  str_voice_1600141_16 = "據說你能與他對話，我也可以嗎？",
  str_voice_1600141_17 = "歡迎回來，巨像之主。",
  str_voice_1600141_18 = "能夠駕馭如此龐大之物，想必你一定有過人之處。",
  str_voice_1600141_19 = "何必事必躬親？交給我吧。",
  str_voice_1600141_20 = "無論如何，我都會守護白夜城，因為它是我的家人。",
  str_voice_1600141_21 = "善守者，藏於九地之下，這就是啟光聯邦的戰略，防守、反攻。",
  str_voice_1600141_22 = "白夜至上。",
  str_voice_1600141_23 = "日蝕是可怕的對手，但是一定會倒在白夜城之下。",
  str_voice_1600141_24 = "卡蓮必須加倍努力，否則她的一切都會籠罩在我的陰影下，這是她的宿命。",
  str_voice_1600141_25 = "伊斯塔萬應該知道我同樣也在監視他……呵，彼此、彼此。",
  str_voice_1600141_26 = "秩序是文明的基石，構成秩序的單位是家族。故，無家，不成國。",
  str_voice_1600141_27 = "無意義的爭論是最愚蠢的，真正有力的雄辯乃是及時的行動。",
  str_voice_1600141_28 = "巨像之大……或許我們要專門為他開闢停留之所。",
  str_voice_1600141_29 = "一份自我介紹是必要的見面禮儀——白夜城統治者，舒瓦茲公爵。我們應該有很多話，可以聊……",
  str_voice_1600141_30 = "有趣。",
  str_voice_1600141_31 = "白夜至上。",
  str_voice_1600141_32 = "白夜城將在你需要的時候打開大門。",
  str_voice_1600141_33 = "白夜引導眾生。",
  str_voice_1600141_34 = "與我共赴戰場。",
  str_voice_1600141_35 = "還可以再承受一次——",
  str_voice_1600141_36 = "開始吧！",
  str_voice_1600141_37 = "接下，你們的墓誌銘——！",
  str_voice_1600141_38 = "我要、諸星都動搖——！！",
  str_voice_1600141_39 = "主宰之刃！",
  str_voice_1600141_40 = "白夜！庇護！",
  str_voice_1600141_41 = "許久沒有親自上陣了！",
  str_voice_1600141_42 = "我為統帥，豈有不勝之理？",
  str_voice_1600141_43 = "所有失敗，都會成為光榮的印記。",
  str_voice_1600141_44 = "嗯……這裡的核心很有趣呢。",
  str_voice_1600141_45 = "嗯，謝謝贈與。恕我沒有回禮。",
  str_voice_1600141_46 = "如此貴重的禮物……舒瓦茲家族收下了。",
  str_voice_1600141_47 = "它……價值不菲。",
  str_voice_1600141_48 = "我會將它作為家族的寶物，傳與後人。",
  str_voice_1600141_49 = "白夜城的由來、貴族派系、舒瓦茲家族的祕密，我的故事你永遠也聽不完。",
  str_voice_1600141_50 = "我以一生維繫白夜興盛，不為自己，為的是人民。信或不信是你的自由。",
  str_voice_1600141_51 = "約書亞、卡蓮，還有……到此為止吧。再嗟嘆下去，我們終將錯過一切。",
  str_voice_1600141_52 = "白夜極光。",
  str_voice_1600141_53 = "巨像之主。",
  str_voice_1600141_54 = "感謝秩序吧，它賜予你清晨。",
  str_voice_1600141_55 = "維護秩序者，你要勤勉。",
  str_voice_1600141_56 = "想必你還未眠。",
  str_voice_1600141_57 = "賀詞就免了，去慶祝吧。",
  str_voice_1600291_1 = "啊啦……果然陰天就適合發呆呢……不過就算撥開烏雲，也很難看到太陽啦……",
  str_voice_1600291_2 = "光——合——作——用——中——不是高中生啦。我的年紀已經——啊啦，不能說啦……不然就只能滅口啦。",
  str_voice_1600291_3 = "日常工作都完成了喔，因為有小騎警的幫助～啊啦，說起這個，有他的留言呢。不過裡面都是罵我的髒話啦，哈哈哈……",
  str_voice_1600291_4 = "籠子啊……與其說是用來關住我的，不如說是保護你的呢……啊啦，什麼意思呢……",
  str_voice_1600291_5 = "總覺得，有個超級眼熟的人在呢。啊，不是你啦……你不止是眼熟喔。嗯～思考果然是很累的呢～",
  str_voice_1600291_6 = "風，森林，從過去吹來的時光。記憶在復甦，飛出這絢爛的牢籠——！",
  str_voice_1600291_7 = "你很在意我呢～卡蓮甜心安排的工作我都甩給那孩子啦，我們可以好好聊聊～",
  str_voice_1600291_8 = "有禮物給你～在……啊啦，不在呢。抱歉，記性愈來愈差啦～記性，愈來愈差啦……",
  str_voice_1600291_9 = "之前我有想過呢……稍微對你打開籠子沒關係吧？可是，萬一又發生那樣的事……嗯？哪樣的事呢，突然忘記了。",
  str_voice_1600291_10 = "無所事事的樣子，你我步調意外地一致呢……",
  str_voice_1600291_11 = "啊啦，這裡也不錯呢。視野很好，太陽爐的溫度也適中，非常適合……睡覺呢……",
  str_voice_1600291_12 = "嗯——剛才……卡蓮要我幹什麼……忘記了。",
  str_voice_1600291_13 = "啊啦，有何貴幹？風兒已經告訴過我，你要來了唷。",
  str_voice_1600291_14 = "有什麼話想對我說都可以說唷，我會聽的……嗯？真的會聽喔。",
  str_voice_1600291_15 = "生日……嗯……嗯嗯……要唱歌對吧？……祝你生日快樂♪",
  str_voice_1600291_16 = "回來啦～別那麼忙啊～",
  str_voice_1600291_17 = "日光確實已經出來了嗎？……你可真是勤勞呢～",
  str_voice_1600291_18 = "……呼……啊啦，差一點就要睡著了，沒關係，應該看不出來吧。",
  str_voice_1600291_19 = "……呼……嗯？沒關係，我的眼睛還睜著喔……醒著喔……",
  str_voice_1600291_20 = "我來的時候，受到白夜城的禮遇，也因此心懷感激，望其和平。",
  str_voice_1600291_21 = "那個曾經幫助我的人……來自啟光，我會記得他的，我保證。",
  str_voice_1600291_22 = "白夜至上～",
  str_voice_1600291_23 = "如果我說……我因為這種生物的存在而記得憤怒，你會意外嗎？",
  str_voice_1600291_24 = "我剛來的時候，他還是個調皮的孩子……啊啦，不能再說了。",
  str_voice_1600291_25 = "親愛的拉斐爾，治療啦、工作啦，都做得不錯……做飯就……啊哈哈。",
  str_voice_1600291_26 = "在舒適的日光中，在溫暖的太陽爐旁，能夠午睡最好啦～",
  str_voice_1600291_27 = "嗯……討厭是種什麼樣的情緒？稍微，有點忘記了。",
  str_voice_1600291_28 = "啊啦，第一次見的時候就感受到了，他和我的籠子有點像呢～",
  str_voice_1600291_29 = "啊啦，你就是傳聞中的……我的名字叫加百列喔。其他的都不太重要呢，我們還有很長很長的相處時間，像春日的午後一樣漫長……",
  str_voice_1600291_30 = "何必這麼著急呢？",
  str_voice_1600291_31 = "籠子……在顫動。",
  str_voice_1600291_32 = "回憶正在生長——",
  str_voice_1600291_33 = "牢籠消失了……",
  str_voice_1600291_34 = "好熱鬧呢～",
  str_voice_1600291_35 = "春天就要來了呢。",
  str_voice_1600291_36 = "拜託了，我的使者——",
  str_voice_1600291_37 = "肆意生長吧——",
  str_voice_1600291_38 = "吹吧、春日的新風——",
  str_voice_1600291_39 = "啊，抱歉～？",
  str_voice_1600291_40 = "不可饒恕喔～",
  str_voice_1600291_41 = "啊啦，偶爾也要以身作則啦。",
  str_voice_1600291_42 = "做人呢，最重要就是開心啦。",
  str_voice_1600291_43 = "啊啦——輸掉了。回去喝杯茶吧？",
  str_voice_1600291_44 = "要一起午休嗎？睡一覺很舒服的～不用考慮任何事情，放空……",
  str_voice_1600291_45 = "給我的嗎？嗯～～～並不討厭啦……",
  str_voice_1600291_46 = "啊啦！很有趣呢～稍微打起了點精神～",
  str_voice_1600291_47 = "謝謝～很不錯的禮物呢～",
  str_voice_1600291_48 = "啊啦！這個、你怎麼知道我最喜歡這個呢～！",
  str_voice_1600291_49 = "那場戰爭，我經歷過啦。但又不確定到底發生了什麼事。發生了嗎？好像是吧，稍微有點頭疼呢。",
  str_voice_1600291_50 = "籠子，之前碎過……不過後來似乎修好了。被誰呢？那個熟悉的人。啊，果然想不起來了。",
  str_voice_1600291_51 = "不要再回想了。除了迷霧般的灰煙，就只剩冰冷的鐵籠。也許有一天，你會幫我回想起來吧……",
  str_voice_1600291_52 = "白夜極光～",
  str_voice_1600291_53 = "你好呀～",
  str_voice_1600291_54 = "不小心被陽光喚醒了呢～",
  str_voice_1600291_55 = "今天，午後的日光真不錯呢～",
  str_voice_1600291_56 = "趁我還醒著～",
  str_voice_1600291_57 = "啊啦～新年快樂～",
  str_voice_1600641_1 = "正面獲勝才能獲得最終勝利，從背後放冷箭者，遲早會被另一發冷箭幹掉。",
  str_voice_1600641_2 = "應該讓紅男爵活動一下，以保持良好的狀態。",
  str_voice_1600641_3 = "接下來的工作是檢查整座巨像，如果能為我所用，恐怕能發揮更大的力量。",
  str_voice_1600641_4 = "恐懼令人畏懼，卻會使我強大。",
  str_voice_1600641_5 = "權力與地位應當自己爭取，並非他人所賜。",
  str_voice_1600641_6 = "你應當瞭解我的實力，那些別人不能完成的任務，請一併交給我。",
  str_voice_1600641_7 = "居上位者，很多時候不需要擁有過人的能力，而是需要擁有下決策的勇氣。",
  str_voice_1600641_8 = "野心是一團火焰，會灼傷弱者；對於我，卻是指引前進的亮光。",
  str_voice_1600641_9 = "終有一天我會成為啟光的大元帥，此時最好的副將就是萊因哈特，或者……你。",
  str_voice_1600641_10 = "居然沒有任何事務……那就冥想吧，這也是身心的自我訓練。",
  str_voice_1600641_11 = "嗯，為了獲取你的支持，暫時答應你的請求。",
  str_voice_1600641_12 = "作為軍團長，表面可以裝作輕鬆，內心則時時刻刻要保持警戒。",
  str_voice_1600641_13 = "「里希特霍芬」在漏電？不，那是我故意的，放心，我能夠操控它。",
  str_voice_1600641_14 = "空有強大的武器而無法駕馭，就如同幼兒抱著金磚在鬧市中遊蕩。",
  str_voice_1600641_15 = "今天破例一次，用紅男爵為你切生日蛋糕。",
  str_voice_1600641_16 = "不能懈怠，要時時保有上進之心。",
  str_voice_1600641_17 = "早安！開始一天的事務吧！",
  str_voice_1600641_18 = "距離休息的時間還很久，繼續吧。",
  str_voice_1600641_19 = "我不會累的，必要時能夠全天不眠不休。",
  str_voice_1600641_20 = "堂堂正正，這便是啟光聯邦教與我的信念，因此我不會隱藏野心。",
  str_voice_1600641_21 = "以家族與血統為根基的白夜城，是沒有未來的。",
  str_voice_1600641_22 = "啟明之光！",
  str_voice_1600641_23 = "暗鬼！哼，有何可怕的？無非是我晉升之路的地基而已。",
  str_voice_1600641_24 = "要想擊敗萊因哈特，先要擊敗我才行。",
  str_voice_1600641_25 = "作為參謀，薇薇安是很完美的部下，但她不適合當領導者。",
  str_voice_1600641_26 = "當力量有所提升時，地位隨之而來。",
  str_voice_1600641_27 = "耍陰謀的小人，即便偶爾得逞，最終仍會被正道碾碎。",
  str_voice_1600641_28 = "如果能將巨像編入我的軍團……這樣就擁有一支空軍了。",
  str_voice_1600641_29 = "未來的啟光大元帥在此。我是雷霆，支持我，你的面前便就是一片坦途。",
  str_voice_1600641_30 = "這本就是我應當的實力。",
  str_voice_1600641_31 = "里希特霍芬！轟鳴！",
  str_voice_1600641_32 = "紅男爵！加速！",
  str_voice_1600641_33 = "還有什麼能夠阻擋我呢？",
  str_voice_1600641_34 = "我才應該是隊長。",
  str_voice_1600641_35 = "紅男爵！蓄能！",
  str_voice_1600641_36 = "紅男爵！可超載！",
  str_voice_1600641_37 = "超載模式！啟動！",
  str_voice_1600641_38 = "紅男爵！雷擊！",
  str_voice_1600641_39 = "里希特霍芬！",
  str_voice_1600641_40 = "紅男爵！",
  str_voice_1600641_41 = "我天生應當此職。",
  str_voice_1600641_42 = "小事一樁。",
  str_voice_1600641_43 = "呃，敗給壓力了……",
  str_voice_1600641_44 = "嗯……要如何做，才能掌握這麼強大的巨像？",
  str_voice_1600641_45 = "嗯，你不必如此。",
  str_voice_1600641_46 = "很好，我會考慮一下與你的關係。",
  str_voice_1600641_47 = "謝謝。我會記住它的。",
  str_voice_1600641_48 = "你的慷慨，讓我有了久違的感動，謝謝。",
  str_voice_1600641_49 = "我能夠成為軍團長，並不是因為我是萊因哈特的同學，而是因為我的功績。",
  str_voice_1600641_50 = "雖然錯過了與暗鬼的決戰，但是那些四處遊蕩的暗鬼都是我一一剿滅的，就憑這一點，也不亞於其他三位軍團長。",
  str_voice_1600641_51 = "有時候，我在想自己真的能夠取代萊因哈特嗎？當年，在我受傷之時，是她救了我……",
  str_voice_1600641_52 = "白夜極光。",
  str_voice_1600641_53 = "請回答！",
  str_voice_1600641_54 = "雷霆呼叫，呼叫！",
  str_voice_1600641_55 = "收到請回覆。",
  str_voice_1600641_56 = "申請特殊呼叫，結束。",
  str_voice_1600641_57 = "許可新年，放行！",
  str_voice_1600231_1 = "呼……今天能鼓起勇氣跟人打招呼嗎……咿呀不是說真的要打招呼啦！請不要點我！！",
  str_voice_1600231_2 = "巨像上……有沒有能一個人待著的陰暗角落呢……不想被任何人找到啊，那個還沒完成啊……",
  str_voice_1600231_3 = "是有點在意這裡……什麼？……啊抱、抱歉！我只是在閒逛、閒逛……",
  str_voice_1600231_4 = "害怕、任何人都會害怕……如果有朝一日可以走出陰影，我也許會知道安東她們的祕密……",
  str_voice_1600231_5 = "又響起來了，安東的耳語！嗚啊啊為什麼要靠近我，我也不是故意要召喚妳們的——",
  str_voice_1600231_6 = "-克娜莉。\n-可憐、易碎的克娜莉。別害怕，妳聽到了嗎？\n-我們的聲音，我們的陪伴。\n-如此……溫柔的黑暗，我不再是一個人了……",
  str_voice_1600231_7 = "您……您問我……剛剛……在和誰說話？但……她們……就在這裡啊……？",
  str_voice_1600231_8 = "那……安東也很喜歡它呢……看來您是可以信任的……",
  str_voice_1600231_9 = "總覺得……如果是和您一起的話，無論去哪裡都不會害怕了。所以……能……能靠近一點嗎？",
  str_voice_1600231_10 = "這音調有點奇怪……沒有不好的感受，反而讓人安心，應該不會又把人吹到送醫吧……要開始囉。",
  str_voice_1600231_11 = "大、大家說我很適合做這件事，真的嗎？為什麼感覺視線變多了……",
  str_voice_1600231_12 = "我曾……受到那位大人幫助……烈雀、知更、修拉德都是如此……",
  str_voice_1600231_13 = "安東的特殊能力……是能讓人睡著呢，突然，好睏……",
  str_voice_1600231_14 = "燈光……太亮了，好刺眼……不、不行，必須要回到角落裡……",
  str_voice_1600231_15 = "-祝您生日快樂～ \n-祝您生日快樂。\n-祝……祝導航員……生日快樂……",
  str_voice_1600231_16 = "咿！已、已經回來了？！沒有，沒事……",
  str_voice_1600231_17 = "-噓！克娜莉還在睡覺！\n-但是開店的時間快到了，不叫醒她真的好嗎……",
  str_voice_1600231_18 = "-克娜莉，陪我玩西洋骨牌吧！\n-安東，現在是工作時間……啊有客人來了！",
  str_voice_1600231_19 = "在這個時間喝咖啡？還是濃縮的？會睡不著覺的……",
  str_voice_1600231_20 = "影鎮籠罩在浮空島的陰影之下，魚龍混雜……但也正因如此才能包容一切。",
  str_voice_1600231_21 = "-無聊。\n-沒勁。\n-假的一樣。\n-嗯……。",
  str_voice_1600231_22 = "影子在注視著呢……",
  str_voice_1600231_23 = "那些……可怕的東西……不想再看到牠們，不想再看到牠們……",
  str_voice_1600231_24 = "烈雀喝不了無糖咖啡……但還是每次都點，我會偷偷幫她加奶油。",
  str_voice_1600231_25 = "溫牛奶再加三顆糖……這是知更的，她總是安安靜靜，像隻小貓一樣。",
  str_voice_1600231_26 = "-放在冰箱裡的巧克力甜點……總會莫名減少，為什麼呢？\n-好好吃。",
  str_voice_1600231_27 = "-從前，有一座咖啡館……\n-咿呀——\n-欸？我又不是在講鬼故事！",
  str_voice_1600231_28 = "好大……能裝下好幾個「假日」咖啡廳了，還有……好多的人……",
  str_voice_1600231_29 = "……啊，好像是迷路了！不，不是這樣的，我叫克娜莉，這位是安東和她的……親戚們……吧？",
  str_voice_1600231_30 = "明明不想變強啊……",
  str_voice_1600231_31 = "竟然如此信任我……",
  str_voice_1600231_32 = "鬧鬼？不對，是我自己召喚出來的！",
  str_voice_1600231_33 = "痛苦與悲傷，終將……在音樂中獲得救贖。",
  str_voice_1600231_34 = "安東，我們要加油……",
  str_voice_1600231_35 = "我……我聽到牠們的聲音了！",
  str_voice_1600231_36 = "吹嗎？現在嗎？！",
  str_voice_1600231_37 = "咿呀呀呀呀非常抱歉！！",
  str_voice_1600231_38 = "安東，要注意力道呀！",
  str_voice_1600231_39 = "好可怕……",
  str_voice_1600231_40 = "和「家人」們一起……",
  str_voice_1600231_41 = "就讓我、勉勉強強地來帶領大家吧！",
  str_voice_1600231_42 = "真的贏了？不敢相信……",
  str_voice_1600231_43 = "抱歉……所以我就應該回到角落裡待著……",
  str_voice_1600231_44 = "抱歉……安東不是故意的……我也不是故意的……",
  str_voice_1600231_45 = "……我……我怎麼能收您的禮物……",
  str_voice_1600231_46 = "真的！我真的可以收下嗎？",
  str_voice_1600231_47 = "哇——這些都是給克娜莉的禮物嗎！",
  str_voice_1600231_48 = "給……您的咖……咖啡，是送給您的回禮。",
  str_voice_1600231_49 = "她的名字叫安東，她的名字也叫安東呢……一開始我也很迷糊，但仔細聽的話會發覺聲線不一樣喔。",
  str_voice_1600231_50 = "我的父母，我希望能見他們一面，告訴他們我已經能好好地和安東說話了呢。這份作為禮物的單簧管，也精心地保存了下來……",
  str_voice_1600231_51 = "奶奶，希望奶奶也能來到這裡……嗯？那位大人嗎？啊啊那位大人就算了，我、我不敢看那位大人的眼睛！不是因為我膽小，安東也不敢的！大家都不敢！",
  str_voice_1600231_52 = "白、白夜極光。",
  str_voice_1600231_53 = "您、您好……",
  str_voice_1600231_54 = "早安！",
  str_voice_1600231_55 = "午安，請問您想來點下午茶嗎？",
  str_voice_1600231_56 = "剛、剛才有奇怪的聲音！",
  str_voice_1600231_57 = "祝您新年快樂……",
  str_voice_1400321_1 = "您有任何問題都可以大方地依靠我，我會幫助您的，這是我的職責所在。",
  str_voice_1400321_2 = "我是審判庭的成員，雖然不能進行最終的裁決……沒關係，我並不在意這個，只要能為信仰工作就夠了。",
  str_voice_1400321_3 = "我已經說過了請別一直看著我的單翼，就是，您的視線讓我有點不知所措，感覺有點太熱烈了……",
  str_voice_1400321_4 = "羽翼越豐滿越是需要懂得收斂，我需要更加小心，免得它被碰壞了。",
  str_voice_1400321_5 = "信仰讓我的眼睛更加明亮，那些凡夫俗子所無視之事物，在我眼前昭然若揭了。",
  str_voice_1400321_7 = "您好像看不見那些條文和約束，只做自己篤信的事情……很羨慕呢，這份執著。",
  str_voice_1400321_8 = "您的指令很簡潔，和彼亞塔曼大人非常相似……我並不反感喔，相反地，我很欣賞。",
  str_voice_1400321_9 = "我有些小小的問題，但也算不上不安，只是想知道您會邀請我嗎？我是說等到一切都結束的時候，我會是您夥伴中的一員嗎？",
  str_voice_1400321_10 = "也不在這裡嗎……那時候明明留下了……",
  str_voice_1400321_11 = "您對我期待很高呢……沒有關係，我能夠勝任，也一定能夠回應您的期待！",
  str_voice_1400321_12 = "糖果和毒藥是同一種東西。",
  str_voice_1400321_13 = "單翼是使命的象徵，這是信仰賜予我的禮物。",
  str_voice_1400321_14 = "擁有信仰之人，他的苦難只是暫時的。",
  str_voice_1400321_15 = "這一天，命運將您帶到世間。祝您生日快樂。",
  str_voice_1400321_16 = "歡迎您，信仰的夥伴。",
  str_voice_1400321_17 = "質疑者，終會被信仰引導。",
  str_voice_1400321_18 = "不用經常來看我，這是多餘的，知道了嗎？",
  str_voice_1400321_19 = "光與暗並無主次，只有位居其中之人才會執著於強分彼此。",
  str_voice_1400321_20 = "令白夜城繁榮的是那一顆顆堅定之心。",
  str_voice_1400321_21 = "沒有信仰的啟光聯邦，是無法成為「啟明之光」的。",
  str_voice_1400321_22 = "白夜至上。",
  str_voice_1400321_23 = "日蝕，必須被毀滅。",
  str_voice_1400321_24 = "作為審判庭的代表，伊倫汀大人是為了守護白夜城的榮耀而生的。",
  str_voice_1400321_25 = "彼亞塔曼大人的公正之心並非其性格使然，乃是信仰所致。",
  str_voice_1400321_26 = "信仰將會淨化一切，也將為世界帶來新生。",
  str_voice_1400321_27 = "如果有追捕褻瀆者的任務，讓我來，這種事情做多少都不夠呢。",
  str_voice_1400321_28 = "但那個高度發展的舊文明，據說消失的原因也是失去了信仰……",
  str_voice_1400321_29 = "您好，請您不要老是盯著它……我的單翼，它有點怕生。",
  str_voice_1400321_30 = "可以飛向更廣闊的天空了。",
  str_voice_1400321_31 = "我會負起更多的責任。",
  str_voice_1400321_32 = "我將是……信仰的代言！",
  str_voice_1400321_34 = "新的工作？",
  str_voice_1400321_35 = "我將使用信仰之力。",
  str_voice_1400321_36 = "小心。",
  str_voice_1400321_37 = "將信仰之力——",
  str_voice_1400321_38 = "散華！散華！",
  str_voice_1400321_39 = "片翼！",
  str_voice_1400321_40 = "淨化！",
  str_voice_1400321_41 = "就讓審判開始吧！",
  str_voice_1400321_42 = "一切都如信仰預示的那樣。",
  str_voice_1400321_43 = "這都是命運的旨意……",
  str_voice_1400321_44 = "我的羽翼？也可以給您看看，但請不要觸碰它。",
  str_voice_1400321_45 = "我不希望您花心思在這上面。",
  str_voice_1400321_46 = "啊……這個能讓我感受到寧靜。謝謝。",
  str_voice_1400321_47 = "我感受到了您的誠意，感謝您的餽贈。",
  str_voice_1400321_48 = "這正是我所祈求之物！祝福您！",
  str_voice_1400321_49 = "信徒的苦難結束了，現在該輪到那些褻瀆者了。彼亞塔曼先生，就算這單翼還隱隱作痛，我也絕不會退卻……",
  str_voice_1400321_50 = "在那場暗潮危機中，我失去了家人、羽翼，支撐我到現在的，就是信仰。",
  str_voice_1400321_52 = "白夜極光。",
  str_voice_1400321_53 = "信仰的夥伴。",
  str_voice_1400321_54 = "早安，祝福已至。",
  str_voice_1400321_55 = "信仰在呼喚您。",
  str_voice_1400321_56 = "晚安，虔誠之人，",
  str_voice_1400321_57 = "謹賀新年，今年的信仰也沒有改變。",
  str_voice_1400851_1 = "一進一出，須有記錄，方可成為正式借貸。",
  str_voice_1400851_2 = "想要看箱子裡的東西？不行。",
  str_voice_1400851_3 = "不因弱者而伸出援手，不因強權而低下頭顱，這便是我的原則。",
  str_voice_1400851_4 = "紙與筆是我的利器，猶如士兵手中的刀劍。",
  str_voice_1400851_5 = "我的瑪蒙之箱中藏有貪婪的見證，也是無數人性命的依存。",
  str_voice_1400851_6 = "如果要知曉更多的記錄，則需要無處不在的得力幫手，是的，就是那些鳥兒們。",
  str_voice_1400851_7 = "人與人的悲歡並不相通。瞭解這一點的話，就會理解我的原則。",
  str_voice_1400851_8 = "作為見證人，還是要求外表整潔的，所以這身西裝，我買了三十套。",
  str_voice_1400851_9 = "我的箱子中擁有很多人的祕密，不僅有影鎮，也有白夜城的那些貴族。",
  str_voice_1400851_10 = "難得有空閒……肩頸也痛了好一陣子，去找人按摩好了。",
  str_voice_1400851_11 = "想要休息一下了？沒問題，讓我看顧這座巨像，寫下關於他的記錄吧。",
  str_voice_1400851_12 = "你見過鳥兒們笑的樣子嗎？",
  str_voice_1400851_13 = "我的角？據說那代表惡魔的貪婪，然而最貪婪的，卻是人們的慾望。",
  str_voice_1400851_14 = "我的筆下，見證了最高貴的庶民，以及最卑劣的騎士。",
  str_voice_1400851_15 = "我記得你的檔案，所以在今天祝你生日快樂。",
  str_voice_1400851_16 = "平靜的一天，記錄如常。",
  str_voice_1400851_17 = "清晨，是磨礪筆尖的好時刻。",
  str_voice_1400851_18 = "雖然即將入夜，然而我還要整理今日的記錄，不能休息。",
  str_voice_1400851_19 = "這些記錄，必須放入瑪蒙之箱中，才能安心……",
  str_voice_1400851_20 = "好的記錄會根除此地的混亂。",
  str_voice_1400851_21 = "世人常有醜惡，若有記錄，則遺臭萬年，即便是白夜城，也是如此。",
  str_voice_1400851_22 = "我在，我見證。",
  str_voice_1400851_23 = "牠們……是用什麼來記錄？如果沒有記憶，真可悲呢。",
  str_voice_1400851_24 = "伊斯塔萬背負得太多，他就像影鎮的化身——永遠是白夜城的影子。",
  str_voice_1400851_25 = "雖然涉的行事詭詐多變，她的原則也很簡單——那就是利益至上。",
  str_voice_1400851_26 = "優美的字跡是諸神賜予世間的最好禮物。",
  str_voice_1400851_27 = "如果一個人沒有原則，那麼他還有靈魂嗎？",
  str_voice_1400851_28 = "他似乎擁有久遠的記憶，那會是什麼呢？",
  str_voice_1400851_29 = "我用紙與筆寫下影鎮的過去，記錄暗巷中的混亂和秩序。見證人，珍，在此。",
  str_voice_1400851_30 = "我已寫下新的記錄。",
  str_voice_1400851_31 = "我的見證，愈加清晰。",
  str_voice_1400851_32 = "瑪蒙之箱，保留更多記錄。",
  str_voice_1400851_33 = "無盡的記錄，這是我選擇的道路。",
  str_voice_1400851_34 = "我會是戰鬥的見證人。",
  str_voice_1400851_35 = "準備清算。",
  str_voice_1400851_36 = "可以開始了。",
  str_voice_1400851_37 = "結束這一切吧！",
  str_voice_1400851_38 = "終了吧！貪婪之人！",
  str_voice_1400851_39 = "粉碎吧！",
  str_voice_1400851_40 = "誰也別想逃離！",
  str_voice_1400851_41 = "我會記下所有人的表現。",
  str_voice_1400851_42 = "勝利一場，記下了。",
  str_voice_1400851_43 = "如果能不讓它進入記錄就好了……",
  str_voice_1400851_44 = "眼見為實，文字為證。",
  str_voice_1400851_45 = "我會將這件禮物記在帳本上。",
  str_voice_1400851_46 = "謝謝，它能好好幫助我！",
  str_voice_1400851_47 = "我會還你的，一定會。",
  str_voice_1400851_48 = "這！我無法用言語表達感謝了……",
  str_voice_1400851_49 = "伊斯塔萬、涉都曾經邀請我加入他們，然而我只想當影鎮的記錄者，對統治影鎮沒有興趣。",
  str_voice_1400851_50 = "如果能用心去看的話，無論是貴族還是平民，其實都有屬於和不屬於他們自己的兩副面孔。",
  str_voice_1400851_51 = "影鎮遭到暗鬼襲擊，我的母親也因此而喪生，許多人怒斥曾經坐視不管的白夜城，然而我對他們卻並不忌恨。",
  str_voice_1400851_52 = "白夜極光。",
  str_voice_1400851_53 = "在嗎？",
  str_voice_1400851_54 = "早。",
  str_voice_1400851_55 = "午安。",
  str_voice_1400851_56 = "晚安。",
  str_voice_1400851_57 = "新年快樂。",
  str_voice_1600021_1 = "臨窗一扇，風雨如霽。沒想到在這巨像上，也有如此靜謐之所。",
  str_voice_1600021_2 = "世事如夢幻，可是人生中免不了有所羈絆，就像你與這座巨像，我與這柄長刀。",
  str_voice_1600021_3 = "生死兩難之際必須當機立斷，但……這並不是誰都能做到的，我也是。",
  str_voice_1600021_4 = "武者應當專於一念之間，不可分心。緋，妳即便是有所提升，也不能炫耀。",
  str_voice_1600021_5 = "英魂的故事在心中迴盪，那是留在雲山中的記憶之音……我，不會再猶豫了！",
  str_voice_1600021_6 = "櫻龍、榮角、轉瞬而逝的力量、以及向死而生的決意，這便是我所有擁有的、全部！",
  str_voice_1600021_7 = "春雨霏霏，芳草正盛，世界已經有復甦的樣子，一起來看看嗎？",
  str_voice_1600021_8 = "死亡不可怕，可怕的是沒有意義的犧牲，你會為了什麼而獻出自己呢？",
  str_voice_1600021_9 = "雖說塵世宛如夢幻，可有了這巨像，以及你……世界似乎不一樣了。",
  str_voice_1600021_10 = "呼——久違的閒暇。難得有機會，我想靜思一下，希望不會有其他人來打擾……",
  str_voice_1600021_11 = "能得到你委託，十分榮幸，希望我能夠回應你的期待。",
  str_voice_1600021_12 = "榮角是這把刀的名字，它陪伴在我身邊，已經很多年了。",
  str_voice_1600021_13 = "……在我的故鄉，總是有很多櫻花，在清冷時節盛開。",
  str_voice_1600021_14 = "要找個地方坐下，一起靜思嗎？能夠緩解疲勞，對工作有益。",
  str_voice_1600021_15 = "我為你準備了一杯熱茶，幾朵櫻花，今天是你的生日，願你快樂。",
  str_voice_1600021_16 = "回來了。一切安好。",
  str_voice_1600021_17 = "我已完成對軍團的訓練，你如果有什麼需要幫忙的，可以告訴我。",
  str_voice_1600021_18 = "請勿擔心，我還在這。",
  str_voice_1600021_19 = "現在是休息時間了，請不用在意我，我會再留一會。",
  str_voice_1600021_20 = "我們感謝啟光，對於我和榮角來說，這裡是最適合的安身之所。",
  str_voice_1600021_21 = "或許你有聽過我談論故鄉，它在跨越過這片大陸的遙遠東方。",
  str_voice_1600021_22 = "為了啟明之光。",
  str_voice_1600021_23 = "光靈與暗鬼，自古以來就注定對立，只能刀劍相向，指著對方。",
  str_voice_1600021_24 = "她代表啟光邀請我，是有恩於我的人，那強大的背影，我至今難忘。",
  str_voice_1600021_25 = "雖然我們只是因為公務而有接觸較多，但我確實欣賞她的計劃能力。",
  str_voice_1600021_26 = "冥想、櫻花、榮角刀……對我來說的重要之事，能算是喜愛嗎？",
  str_voice_1600021_27 = "雖然稱不上是厭惡，但我並不願意，與沒有覺悟之人同行。",
  str_voice_1600021_28 = "你聽過傳聞中的白色巨龍嗎？就像這座巨像，願他能去到遠方。",
  str_voice_1600021_29 = "吾名為，緋。人生如夢亦似幻，相見為緣。榮角與我，暫時助你。",
  str_voice_1600021_30 = "我距離目標……又近了一步。",
  str_voice_1600021_31 = "我還需要擺脫私心。",
  str_voice_1600021_32 = "無懼生死、當如春花既散——",
  str_voice_1600021_33 = "櫻龍，隨我一起追尋命運的終章吧！",
  str_voice_1600021_34 = "一起，改寫命運吧。",
  str_voice_1600021_35 = "一心無二——",
  str_voice_1600021_36 = "刀已出鞘。",
  str_voice_1600021_37 = "向死則生——！",
  str_voice_1600021_38 = "櫻花大葬——！",
  str_voice_1600021_39 = "落下吧！",
  str_voice_1600021_40 = "弧光！",
  str_voice_1600021_41 = "我不會辜負使命的。",
  str_voice_1600021_42 = "這確實是，懷著覺悟的戰鬥。",
  str_voice_1600021_43 = "……戰敗並不是恥辱。",
  str_voice_1600021_44 = "櫻花綻放之途，正是我記憶中回歸的路徑。",
  str_voice_1600021_45 = "謝謝，不用這麼照顧我。",
  str_voice_1600021_46 = "這份禮物……請讓我回報些什麼給你。",
  str_voice_1600021_47 = "我想你應該花了許多心思，感謝。",
  str_voice_1600021_48 = "這……啊，我很喜歡。不，我十分喜歡……",
  str_voice_1600021_49 = "幫助你是為了完成自己的使命，我雖身在啟光，擔任軍團長的重要職務，但並不是出生在這裡的人……",
  str_voice_1600021_50 = "我離鄉時雖然年幼，但身上不可避免地已經刻下了那裡的印記，例如我的風骨，還有我的名字……",
  str_voice_1600021_51 = "世事無常，我和栄角一起離開了雲山，然而加入啟光時卻只剩我一個人……現在你出現，希望不要再有變故才好……",
  str_voice_1600021_52 = "白夜極光。",
  str_voice_1600021_53 = "向你問好。",
  str_voice_1600021_54 = "早安。",
  str_voice_1600021_55 = "打擾一下。",
  str_voice_1600021_56 = "夜已近。",
  str_voice_1600021_57 = "新年好。",
  str_voice_1500331_1 = "可惜巨像沒有說明書，我只能不斷地探索你了！嗯？這句話的邏輯並不奇怪呀？畢竟……畢竟……等等，讓我再想想！",
  str_voice_1500331_2 = "能夠一起啟動巨像，說明我們的羈絆也許是命中注定，所以就別在意一開始弄壞巨像的損失吧……",
  str_voice_1500331_3 = "今天的作戰安排是……！！我太大聲了嗎？抱歉，我還以為這樣能傳達得更好……沒成功嗎？",
  str_voice_1500331_4 = "我再也不會否定自己了，因為我終於找到謎團的出口，和自己的價值，絕不希望失敗重演……",
  str_voice_1500331_5 = "日積月累的力量，會成為致勝的關鍵……就算有過去甩不掉的噩夢，也不妨礙我越變越強！",
  str_voice_1500331_6 = "我將永遠保持信念。如同夜空中的極光，無所畏懼！",
  str_voice_1500331_7 = "為什麼你以前就沒能成功啟動巨像呢？一般來講，只要找對方法就可以解決問題……所以，我、就是那個……方法？",
  str_voice_1500331_8 = "我以前單獨處理任務時總要繃緊神經，現在終於有搭檔了！而且還是不用發薪水的那種……唔，要不然，分你一點當補貼？",
  str_voice_1500331_9 = "可能是因為在你身旁待了一段時間？所以才會不由自主地想知道你們的事情，並期盼你們的未來走向好結局！",
  str_voice_1500331_10 = "呼——行程表上還有多少事項呢？再稍微努力一下……你也辛苦了，趁現在好好休息吧！",
  str_voice_1500331_11 = "將事務都交給我處理當然沒問題，我會努力解決這一切的！不過要是你也來幫忙就更好了呢！",
  str_voice_1500331_12 = "有什麼事嗎？我來幫忙解決！《突發事件解決守則》已經背好了！",
  str_voice_1500331_13 = "有人暈飛行？我剛上巨像的時候也這樣，沒關係，睡一覺就好了！",
  str_voice_1500331_14 = "有人將光照了進來，從此我的世界裡，有了一些堅不可摧的東西！",
  str_voice_1500331_15 = "先藏起來，再關燈，禮物準備完畢……欸？你什麼時候來的？！",
  str_voice_1500331_16 = "歡迎回來，辛苦了！所以，那個……換班，我就休息一下下。",
  str_voice_1500331_17 = "你醒了嗎？我已完成定期聯絡了，商議一下今天的行程事務吧！",
  str_voice_1500331_18 = "還有一點，巨像的相關報告，就快處理完了……說不定能提前……",
  str_voice_1500331_19 = "沒想到你也為了處理工作而熬到這個時間……真是太辛苦了！",
  str_voice_1500331_20 = "優秀的制度，平等的學習機會，能被啟光收養，我十分幸運！",
  str_voice_1500331_21 = "曾去白夜城遊學的經歷，讓我學到不少，你要是也去過就好了！",
  str_voice_1500331_22 = "為了啟明之光！",
  str_voice_1500331_23 = "我們每個人都有拿起武器的理由，而我……也有屬於自己的理由。",
  str_voice_1500331_24 = "卡戎長官他雖然看起來散漫，但也有很多優點的，比如……我再想想。",
  str_voice_1500331_25 = "雖然她的性格偶爾會讓人頭疼，但她的研究……嗯！會讓人加倍頭疼！",
  str_voice_1500331_26 = "搖籃曲和黑白色的琴鍵……這、這都是很高雅的東西，對吧？",
  str_voice_1500331_27 = "失敗很讓人討厭呀，特別是……成功近在眼前，卻因天真而失敗。",
  str_voice_1500331_28 = "巨像在外界看來大多是工具或武器，但我認為他更像夥伴，對吧？",
  str_voice_1500331_29 = "我叫薇絲唷！你應該還記得吧！……呼，太好了。我還在擔心自己的存在感會不會太弱呢～",
  str_voice_1500331_30 = "我還可以更強！",
  str_voice_1500331_31 = "這前方、是未知的命運嗎？",
  str_voice_1500331_32 = "至高的祝福和恩惠，確實就在這裡。",
  str_voice_1500331_33 = "走吧，前往那充滿謎團的未來！",
  str_voice_1500331_34 = "我會努力的！",
  str_voice_1500331_35 = "早已準備就緒！",
  str_voice_1500331_36 = "要不要來份說明？",
  str_voice_1500331_37 = "我將毫無保留！！",
  str_voice_1500331_38 = "無謂的戰鬥、該結束了！",
  str_voice_1500331_39 = "目標追蹤！",
  str_voice_1500331_40 = "絕不迷失！",
  str_voice_1500331_41 = "帶隊嗎！沒問題！真的！",
  str_voice_1500331_42 = "嗯！勝利是當然的！",
  str_voice_1500331_43 = "為了你的安全，先撤退吧……我們隨時都可以再來！",
  str_voice_1500331_44 = "嗚哇！嚇了我一跳……這是什麼試膽遊戲嗎？",
  str_voice_1500331_45 = "嗯？為何要突然送我禮物？",
  str_voice_1500331_46 = "原來如此，這是為了增進感情！",
  str_voice_1500331_47 = "我收下了，並沒有不喜歡，真的沒有！",
  str_voice_1500331_48 = "謝謝！我會珍惜的，請期待我的回禮！",
  str_voice_1500331_49 = "我曾經也能作為一份優秀的「希望」發光發熱，直到幻想被打破……但沒關係，就算失去了天賦，我也不打算放棄……",
  str_voice_1500331_50 = "命運可能多舛，但絕不會沒有希望。你這個「希望」不就來了嗎！……另外，其實你把我當「希望」也是可以的。",
  str_voice_1500331_51 = "你有沒有想過，當有關我們的、暗鬼的、乃至整片天空的祕密都被揭示時，世界會發生什麼？……你，還能繼續堅持信念嗎……",
  str_voice_1500331_52 = "白夜極光！",
  str_voice_1500331_53 = "搭檔！在嗎？",
  str_voice_1500331_54 = "早安，狀態如何？",
  str_voice_1500331_55 = "你應該沒在午休吧？",
  str_voice_1500331_56 = "工作辛苦了！",
  str_voice_1500331_57 = "新的一年，也請多多關照～",
  str_voice_1500131_1 = "我喜歡這裡！我要用冰做出一個等比例的巨像！等等，我發現這好像有點難。",
  str_voice_1500131_2 = "注意保護環境，人人有責！在我們北境，這樣的開發可是會被女王陛下懲罰喔！",
  str_voice_1500131_3 = "我要在一顆大——冰球上雕出薇絲的臉，你說她會感到驚喜，還是會生氣？",
  str_voice_1500131_4 = "我從未如此擁抱過寒冰，它們變得不一樣了……堆個雪人吧？",
  str_voice_1500131_5 = "這是……快看，這閃耀的冰晶！我能在裡面見到虹光的影子，這可是鮮為人知的現象！",
  str_voice_1500131_6 = "雪人，我們走！去繽紛的夢境，彩虹和陽光在前面等著我們！",
  str_voice_1500131_7 = "北境裡有很多不切實際的傢伙，你明白吧？比如……咳！我什麼也沒說！",
  str_voice_1500131_8 = "對我的巨劍很感興趣嗎？你等一下唷，我把它翻過來給你看看，它的背面也很有意思！",
  str_voice_1500131_9 = "我有很多故事，冰晶的故事，雪花的故事，只要你和我約定保守祕密，我就講給你聽～",
  str_voice_1500131_10 = "閒下來的時候變多了呢，想要和我的冰晶們一起玩嗎？穿好羽絨外套喔！",
  str_voice_1500131_11 = "有點大材小用，但是諾爾並不介意！我會監督各位，讓各位好好愛護環境的！",
  str_voice_1500131_12 = "這裡的設備，防水嗎？……其實我想為你下場雪，你想看嗎？",
  str_voice_1500131_13 = "我可以玩玩冰晶嗎？就玩小小的那種，保證不會給你添麻煩！",
  str_voice_1500131_14 = "看！冰雕的小船！冰雕的小雪杉樹！冰雕的……小小的你！",
  str_voice_1500131_15 = "祝你生日快樂！送你九百顆星星！你開心嗎？",
  str_voice_1500131_16 = "唷，要一起去冰上冒險嘛？你帶上你的小背包，我帶上你！",
  str_voice_1500131_17 = "早安！早安！早上你覺得如何？早上的我很有精神唷！",
  str_voice_1500131_18 = "快來，你來的正是時候，一起來和小雪人跳舞吧！",
  str_voice_1500131_19 = "我們可以點燃營火，圍在一起，我講故事給你聽，你講故事給我聽。",
  str_voice_1500131_20 = "我記得映在那裡的彩虹，記得落下的雨水，記得變得柔軟的土地！",
  str_voice_1500131_21 = "從現在開始，我要去很多地方！先去浮空城，再去地下城！",
  str_voice_1500131_22 = "暮冬而生！",
  str_voice_1500131_23 = "破壞環境的傢伙們不可饒恕！不要怕，我不會讓牠們傷害你！",
  str_voice_1500131_24 = "你聽過露易絲寫的故事嗎？很厲害唷！基本上都說中了呢！",
  str_voice_1500131_25 = "每次我和我的小雪人跳舞的時候，我總覺得她似乎有點羨慕呢。",
  str_voice_1500131_26 = "我喜歡幫助他人，喜歡閃亮亮的東西！很簡單吧！",
  str_voice_1500131_27 = "我沒有討厭的東西唷！但是不愛護環境的行為可不行，要好好教訓！",
  str_voice_1500131_28 = "這裡是你的家吧？我能感受到唷……有你的寄託，有你的希望～",
  str_voice_1500131_29 = "聽好了！雪杉樹對北境來說十分重要，它們幫助村民抵禦風雪，雖然主要還是靠女王陛下的魔法啦～",
  str_voice_1500131_30 = "我喜歡這種感覺！再來再來！",
  str_voice_1500131_31 = "冰雪與魔法的盛宴！",
  str_voice_1500131_32 = "冰晶，將會絢爛！",
  str_voice_1500131_33 = "讓冰晶映照整片銀河吧！",
  str_voice_1500131_34 = "要去冒險了嗎？",
  str_voice_1500131_35 = "把牠們都凍起來！",
  str_voice_1500131_36 = "獻給大自然！",
  str_voice_1500131_37 = "雪與風的精靈！",
  str_voice_1500131_38 = "有諾爾在！",
  str_voice_1500131_39 = "北風呀！",
  str_voice_1500131_40 = "冰雪唷！",
  str_voice_1500131_41 = "新的冒險！大家一起加油吧！",
  str_voice_1500131_42 = "我們真是合作無間呢！",
  str_voice_1500131_43 = "怎麼辦，慶祝的冰花用不上了……",
  str_voice_1500131_44 = "一閃一閃小星星，雪境裡的亮晶晶！",
  str_voice_1500131_45 = "謝謝，但沒有更有趣的東西了嗎？",
  str_voice_1500131_46 = "我喜歡這個！就算是女王陛下也會喜歡吧！",
  str_voice_1500131_47 = "謝謝，只要是你送的，無趣也沒關係。",
  str_voice_1500131_48 = "天啊，我該怎麼表示這份喜歡呢？我太喜歡了！",
  str_voice_1500131_49 = "女王陛下說，我可以出門旅行了，於是我背上了行李，踏上了旅程，遇到了許多好心人～",
  str_voice_1500131_50 = "很久很久以前，很多人都離開了，消失在那年，那月，那日的那道彩虹之中。",
  str_voice_1500131_51 = "旅途中有自由與夢想，有大家的笑容，還有我與我所珍視的各位，重要的約定～",
  str_voice_1500131_52 = "白夜極光！",
  str_voice_1500131_53 = "我可愛的夥伴！",
  str_voice_1500131_54 = "新的一天到來了！",
  str_voice_1500131_55 = "午安呀！一起冒險嗎？",
  str_voice_1500131_56 = "你準備好了嗎！",
  str_voice_1500131_57 = "新的一年也一起旅行吧！",
  str_voice_1400611_1 = "光靈的情緒是很奇妙的東西，它們就像具有實體的精靈。",
  str_voice_1400611_2 = "想要學會如何掌控情緒嗎？那種東西不用學啦，因為你現在有我！",
  str_voice_1400611_3 = "放心地表達自己吧，我是你的後盾。有時候你和那孩子一樣固執呢……",
  str_voice_1400611_4 = "隨著研究的深入，我們終有一天也可以幫到那孩子吧……",
  str_voice_1400611_5 = "這些「精靈」們不光可以用於戰鬥，更能修復我們內心的創傷……",
  str_voice_1400611_6 = "抱歉……可能有時候我也需要一個情緒出口，我會盡量不造成你的困擾。",
  str_voice_1400611_7 = "嘿！今天有什麼新鮮事要分享嗎？我隨時都在這裡喔。",
  str_voice_1400611_8 = "想說什麼就儘管說吧，我可以為你空出很多時間。這是我的職責所在。",
  str_voice_1400611_9 = "過來吧，我感知到你有一些微妙的情緒在擾動呢。要摸摸頭嗎？",
  str_voice_1400611_10 = "嗚啊——「放鬆」和「無聊」，這兩種情緒果然非常接近呢……",
  str_voice_1400611_11 = "心理治療的時間到了嗎？別害羞，讓我們促膝長談吧！",
  str_voice_1400611_12 = "歡迎回來，導航員！有什麼事儘管告訴我吧～",
  str_voice_1400611_13 = "你好呀！要聊聊嗎？",
  str_voice_1400611_14 = "如果感覺到不愉快，歡迎隨時找我～",
  str_voice_1400611_15 = "生日快樂！今天充滿了愉快的情緒呢！",
  str_voice_1400611_16 = "巨像的情緒很穩定，交給我吧，小事一樁！",
  str_voice_1400611_17 = "氣色很好呀！看來有好好休息～",
  str_voice_1400611_18 = "如果太累可是會累積負面情緒唷～是時候休息啦～",
  str_voice_1400611_19 = "如果睡不著，歡迎你來找塞卡聊聊～",
  str_voice_1400611_20 = "在旁人看來，啟光地下城的生活很緊張，然而那裡井然有序！",
  str_voice_1400611_21 = "聽說白夜城有獨特的情緒治療術，不知道是真的還是傳聞～",
  str_voice_1400611_22 = "為了啟明之光！",
  str_voice_1400611_23 = "暗鬼是討厭的傢伙！只有討厭的情緒！",
  str_voice_1400611_24 = "貢露科研長真得懂得很多呢，就連心理學也略知一二。",
  str_voice_1400611_25 = "小白白超可愛的喔～別看他年齡在我之上，心裡一直都還是個孩子！",
  str_voice_1400611_26 = "我喜歡傾聽，尤其是傾聽別人的訴說。",
  str_voice_1400611_27 = "負面情緒是很不好的！一定要發洩出來才行喔！",
  str_voice_1400611_28 = "巨像，是有情緒的，需要好好傾聽才行。",
  str_voice_1400611_29 = "初次見面！我是錢德菈·塞卡，大家的心理治療師和情緒保管者！請多多指教！",
  str_voice_1400611_30 = "情緒變得更強烈了！",
  str_voice_1400611_31 = "在互相幫助中互相提升！",
  str_voice_1400611_32 = "你很懂得培養夥伴！",
  str_voice_1400611_33 = "情緒，像煙火一樣釋放吧！",
  str_voice_1400611_34 = "請多指教！",
  str_voice_1400611_35 = "情緒已集全！",
  str_voice_1400611_36 = "來囉來囉！！",
  str_voice_1400611_37 = "釋放吧，心靈！",
  str_voice_1400611_38 = "心靈之焰、準備好了！",
  str_voice_1400611_39 = "牛刀小試！",
  str_voice_1400611_40 = "壞情緒！釋放！",
  str_voice_1400611_41 = "願大家都有好心情！",
  str_voice_1400611_42 = "勝利的氣味真甜美呢！",
  str_voice_1400611_43 = "把負面情緒交給我吧！",
  str_voice_1400611_44 = "有不順心的事嗎？由我來為你保管吧！",
  str_voice_1400611_45 = "很有心呢～多謝！",
  str_voice_1400611_46 = "是我喜歡的類型！真是善解人意！",
  str_voice_1400611_47 = "你很喜歡送我東西呢～",
  str_voice_1400611_48 = "愉悅的情緒快要溢出來了～！嘿嘿！",
  str_voice_1400611_49 = "就算擁有灰暗不清的過去，我們也不能沉淪在消極的想法裡過完這一生，不是嗎？",
  str_voice_1400611_50 = "貢露小姐對我非常關照呢，可以說如果沒有她的支持，我的研究也不會如此順利。果然身邊貴人多多～",
  str_voice_1400611_51 = "現在，啟光的大家就是我的親人。當然導航員也是！希望我們可以一起創造出更多、更多、更多有趣的情緒呢～！",
  str_voice_1400611_52 = "白夜極光！",
  str_voice_1400611_53 = "你好呀！",
  str_voice_1400611_54 = "早安呀！",
  str_voice_1400611_55 = "中午了唷！",
  str_voice_1400611_56 = "晚上了呢！",
  str_voice_1400611_57 = "新年快樂！",
  str_voice_1500361_1 = "你似乎能和它交談呢……不少人最後都瘋了。別在意，小事。",
  str_voice_1500361_2 = "你說吧，我聽著。在老大回來之前，你想說多少我都有時間假裝聆聽。",
  str_voice_1500361_3 = "存在是毫無意義的，特別是當你參透了存在的意義。聽不懂？正常。連老大也弄不清楚。",
  str_voice_1500361_4 = "影子重疊影子，黑暗在加倍聚集……被斬斷而再生之物要崩塌了，你無需知曉。",
  str_voice_1500361_5 = "是狗還是狼，是影子還是真實，都無所謂，你不需要對此有興趣……看著就好。",
  str_voice_1500361_6 = "看見它們了嗎？美麗，安靜，無處不在。你身後就是——如出一轍，又截然不同。",
  str_voice_1500361_7 = "如果是擔心我的能力，你大可放心。我有更重要的事要做，懶得用影子對付你。",
  str_voice_1500361_8 = "嗯……好像開始有點欣賞你了。你的影子開始散發出味道了，知道嗎？別過來，我不想聞。",
  str_voice_1500361_9 = "不想承認，但你和老大有相似之處。你們都是影子的主人，在光與暗的世界上、踩著影子自由行走。",
  str_voice_1500361_10 = "哇，喔，那個，真是無聊透頂。誰來結束這一切吧。",
  str_voice_1500361_11 = "如果可以的話，請換別人。連我的狗都不願意待在這裡。",
  str_voice_1500361_12 = "又怎麼了？你總該是為了什麼事來的吧？",
  str_voice_1500361_13 = "這裡比想像中還無聊……你是這裡的主人吧，想點辦法。",
  str_voice_1500361_14 = "你，站遠點……影子們正在躁動中，被咬了我可不管。",
  str_voice_1500361_15 = "嘖，真麻煩，這種事無所謂吧，有想要的東西就直接說。",
  str_voice_1500361_16 = "啊，你回來了。我以為你失蹤了。",
  str_voice_1500361_17 = "你是個勤勉的人，那又怎麼樣，和我沒關係……",
  str_voice_1500361_18 = "要出門，還是不出門？快點決定，別耽誤時間。",
  str_voice_1500361_19 = "狗都睡了你還不睡……我可沒打算等你……你還要做什麼？",
  str_voice_1500361_20 = "以前是「像我這樣的人只配在影鎮」，現在是「我們就該在影鎮」。",
  str_voice_1500361_21 = "白夜城……誰愛去就去吧，我沒有興趣。",
  str_voice_1500361_22 = "嘖，影子始終注視著你。",
  str_voice_1500361_23 = "暗鬼？有什麼好在意的嗎？一擁而上，啃死，結束。",
  str_voice_1500361_24 = "不認識，影鎮裡的那個是章魚，是早該絕滅的傢伙。",
  str_voice_1500361_25 = "嘖，長條的蟲子，也不知道每天在燃燒個什麼東西。",
  str_voice_1500361_26 = "喜歡的東西？啊——辛辣食物、犬、沒人來煩我。",
  str_voice_1500361_27 = "討厭的東西，自以為是的傢伙。",
  str_voice_1500361_28 = "這是你家是吧？無所謂，反正我也不是沒在別人家睡過。",
  str_voice_1500361_29 = "真沒想到你能找到我，介紹自己很麻煩，你自己看吧。",
  str_voice_1500361_30 = "好吧，給你認可。",
  str_voice_1500361_31 = "光的背面，它們正在聚集。",
  str_voice_1500361_32 = "它們無聲無息地降臨了。",
  str_voice_1500361_33 = "去吞噬那些沉溺於虛假歡愉的傢伙們吧——",
  str_voice_1500361_34 = "聽我說，把我換掉。",
  str_voice_1500361_35 = "我才是你們的主人！",
  str_voice_1500361_36 = "迎接、死亡的顏色——",
  str_voice_1500361_37 = "驅散、光明！！",
  str_voice_1500361_38 = "撕裂光芒吧！！",
  str_voice_1500361_39 = "咬碎！",
  str_voice_1500361_40 = "吞噬！",
  str_voice_1500361_41 = "隊長？認真的？",
  str_voice_1500361_42 = "那種東西，統稱弱者。",
  str_voice_1500361_43 = "很挫敗吧？抱歉，我不在乎。",
  str_voice_1500361_44 = "真麻煩……放棄吧，我是不會有反應的。",
  str_voice_1500361_45 = "啊，禮物，真好，就、等、著、這、個、呢。",
  str_voice_1500361_46 = "……哈。碰巧猜中的嗎？我也就只對這個有點期待了。",
  str_voice_1500361_47 = "……嘖，我收下了，啊，真、開、心。",
  str_voice_1500361_48 = "你還是老樣子，知道我會期待什麼。",
  str_voice_1500361_49 = "很多東西對我來說都是身外之物，無論衣著，還是親人眷屬。都是遲早會離你而去的存在——別反駁，因為這就是事實。",
  str_voice_1500361_50 = "羈絆是最可笑的東西。盼望你追求不切實際的傢伙們把這個念頭塞進你的腦袋，然後囚禁你。抱歉，我可不奉陪。",
  str_voice_1500361_51 = "不排除有一天我也會陷入俗套，但那種可能性非常非常非常小。拭目以待吧。檔案就到這裡了，別點了，沒有了，煩死了。",
  str_voice_1500361_52 = "白夜極光。",
  str_voice_1500361_53 = "喂，在不在？",
  str_voice_1500361_54 = "我的狗都醒了。",
  str_voice_1500361_55 = "找你有事。",
  str_voice_1500361_56 = "睡了沒？等你兩分鐘。",
  str_voice_1500361_57 = "嘖，是新年了，怎樣？",
  str_voice_1500121_1 = "唷，除了說教之外，我可以陪你聊上一宿！怎麼樣，正義執行也有親民的一面喔！",
  str_voice_1500121_2 = "這都是啟明之光給我的考驗，真頭痛，這個世界要是沒有我怎麼辦！",
  str_voice_1500121_3 = "我看見了你心中的正義，它們正在閃閃發光。啟光需要你這樣的傢伙，你懂我意思吧？",
  str_voice_1500121_4 = "如果你認為我只是在喊口號，那可大錯特錯了。這是信條，也是我的道義，至死不渝。",
  str_voice_1500121_5 = "漂亮……這樣下去，不到三天我就會超過大元帥吧！到時候要怎麼給她留點面子呢……",
  str_voice_1500121_6 = "我會讓每個人的心中，都有聲音在敲擊，在迴響——夥伴啊，光明之路就在前方，相信正義吧！",
  str_voice_1500121_7 = "不用謝我。作為你的夥伴，這是分內之事！也希望你可以把啟光作為你的家人喔。",
  str_voice_1500121_8 = "無需懼怕，只要是正義之人​​。站在我身邊，讓啟明之光也眷顧你吧。",
  str_voice_1500121_9 = "哪怕沒有居所，哪怕不被理解，我們都應當心懷信仰。當然，我相信你是能夠理解的那一個。",
  str_voice_1500121_10 = "喂，沒動靜了？喂——正義在呼喚你喔——還是說，你正躲在角落做什麼見不得人的事？",
  str_voice_1500121_11 = "瞭解！要我把正義兩個字刻在主介面上嗎？我馬上開始！",
  str_voice_1500121_12 = "這帽子很酷吧！這是那位來自遠東的戰友贈予我的禮物。",
  str_voice_1500121_13 = "武器有點長？不用擔心，這是用於裁決的刀刃，與我相配。",
  str_voice_1500121_14 = "你真有精神，不管怎麼看都是很適合我的夥伴！",
  str_voice_1500121_15 = "我知道你努力了很久，今天就盡情慶祝，盡情享樂吧！",
  str_voice_1500121_16 = "歡迎回來，正義的夥伴！",
  str_voice_1500121_17 = "早！等你很久了，我已經迫不及待要開始新的一天了！",
  str_voice_1500121_18 = "不管你何時歸來，我都會等待並歡迎你，我的夥伴！",
  str_voice_1500121_19 = "很好，我知道你記得我說的話，你想和我徹夜討論正義對吧！",
  str_voice_1500121_20 = "為了啟明之光而盡我所能，並保持清醒，持續監督。",
  str_voice_1500121_21 = "表面白，裡面黑，我們早已看穿那座浮空城的偽裝！",
  str_voice_1500121_22 = "為了啟明之光！保衛迦南！",
  str_voice_1500121_23 = "任何進犯正義、侵略啟光的傢伙我都不會放過，直接消滅！",
  str_voice_1500121_24 = "強大、公正，堅持正義，毫無疑問，沒人比大元帥更適合領導啟光。",
  str_voice_1500121_25 = "她讓我明白來自遙遠之地的人也有堅持的正義，真是鼓舞人心。",
  str_voice_1500121_26 = "執行者就該懲奸除惡，我會做我該做的事並解決他人的問題！",
  str_voice_1500121_27 = "討厭的東西？不用擔心，那些令人厭惡的東西，我都會親手清除！",
  str_voice_1500121_28 = "在我登上這座巨像之前，我是持批判態度的。但你在，就不一樣！",
  str_voice_1500121_29 = "你看起來不錯，或許我們能來探討一下關於正義的信仰。希望不會有手刃你的那一天……",
  str_voice_1500121_30 = "不朽勳章！",
  str_voice_1500121_31 = "新的力量帶來新的曙光！",
  str_voice_1500121_32 = "越來越靠近了、離大元帥的距離！",
  str_voice_1500121_33 = "鐵腕、利刃、無懈可擊！",
  str_voice_1500121_34 = "懲惡揚善！",
  str_voice_1500121_35 = "雷光，擊穿那些黑暗吧……",
  str_voice_1500121_36 = "盡情後悔吧！",
  str_voice_1500121_37 = "退後，雜碎！",
  str_voice_1500121_38 = "這是最後機會，遺言呢！",
  str_voice_1500121_39 = "懲戒！",
  str_voice_1500121_40 = "正義降臨！",
  str_voice_1500121_41 = "是正義執行的時間！",
  str_voice_1500121_42 = "正義從不缺席！",
  str_voice_1500121_43 = "別攔著我！讓我上去跟他們玉石俱焚——！",
  str_voice_1500121_44 = "不用感謝，我在這裡，只做我理應做的事！",
  str_voice_1500121_45 = "喔？有那麼點意思吧。多謝。",
  str_voice_1500121_46 = "心有靈犀啊！不愧是正義的夥伴！",
  str_voice_1500121_47 = "多謝，不談價值，不論意義。",
  str_voice_1500121_48 = "我的夥伴，你給了我十分有意義的禮物！",
  str_voice_1500121_49 = "即便孤身一人，也不能丟失心中的信念，那是旗幟，是支柱，是每個人都應該留存的啟明之光。",
  str_voice_1500121_50 = "我就是為了摧毀這個世界的虛偽和骯髒而存在的！哪怕不被他人理解也無所謂。",
  str_voice_1500121_51 = "我的家族留給我的究竟是什麼？我要背負的究竟是什麼？不，我只是選擇了成為我自己。",
  str_voice_1500121_52 = "白夜極光！",
  str_voice_1500121_53 = "正義的夥伴！",
  str_voice_1500121_54 = "一日之際在於晨！",
  str_voice_1500121_55 = "午後不可鬆懈！",
  str_voice_1500121_56 = "今日還遠未結束！",
  str_voice_1500121_57 = "新年！為正義慶祝！",
  str_voice_1500211_1 = "修剪玫瑰、為刺所傷、不斷撕裂的傷口不斷癒合——濃厚的愛就會從身體裡奔湧而出！",
  str_voice_1500211_2 = "我熱愛您，但更愛那個孩子。她像叢生的玫瑰，我願讓她用帶刺的藤蔓緊緊包裹我、包裹我、永遠不要離開！！",
  str_voice_1500211_3 = "我們正在玩捉迷藏，您要一起嗎？啊，還有一個沒找到，還有一個……什麼時候從愛的懷抱裡溜走的呢？小、可、愛……",
  str_voice_1500211_4 = "愛意的花園又擴大了呢。像逐光的蝴蝶一樣落入我的愛網吧，然後再也不要離開……",
  str_voice_1500211_5 = "我看到每一朵花的經絡裡奔流著屬於我的愛意，就如那孩子一樣，我將為它們築起最精緻的囚籠。",
  str_voice_1500211_6 = "過來吧，留在我身邊吧，不要再背叛我。然後在安全的柵欄中，在溫暖花園中，迎來盛大的綻放！",
  str_voice_1500211_7 = "不錯的天氣。我可以牽起您的手嗎？不用擔心，只是參觀，沒有禁錮……",
  str_voice_1500211_8 = "柵欄是愛、是擁抱、是奉獻！她不明白我的用心，您明白嗎？您明白對吧！",
  str_voice_1500211_9 = "多麼濃郁的愛意！世上能理解我的恐怕只有您了，就像高山與流水的共鳴！靠近點，是時候分享一些祕密了……",
  str_voice_1500211_10 = "無精打采的樣子，像極了缺少關懷的野花。該做多大的囚籠比較合適呢……嗯？啊，我只是在自言自語。",
  str_voice_1500211_11 = "又到了園藝時間。我會把這裡打造成愛的國度——枝葉繁茂，密不透風的那種……",
  str_voice_1500211_12 = "原來是您來了，怪不得從剛才開始，我就感受到一股清風。",
  str_voice_1500211_13 = "您身上有花香呢，而且與我所培育的花朵們不同……十分特別。",
  str_voice_1500211_14 = "為什麼不情願，是柵欄不夠舒適嗎……嗯？我在說我的花兒呢。",
  str_voice_1500211_15 = "在值得紀念的這一天，收下我的愛意吧！我相信您會永生難忘！",
  str_voice_1500211_16 = "歡迎回到愛的花園，我已等候您多時了。",
  str_voice_1500211_17 = "您帶了晨露來嗎？我可愛的花朵們，已經迫不及待要綻放了。",
  str_voice_1500211_18 = "啊——歡迎回來，我知道您會回到我身邊的，回到溫暖的花園……",
  str_voice_1500211_19 = "您真好……我的花兒們總是在夜晚失去精神，但您，依舊綻放著。",
  str_voice_1500211_20 = "以花園來說，並不壞。不過我本以為，那個孩子也會來這裡……",
  str_voice_1500211_21 = "空中的花園、荒漠的花園、雪境的花園、那孩子會在哪呢？",
  str_voice_1500211_22 = "那麼，為了啟明之光。",
  str_voice_1500211_23 = "我需要好好清理那些，危害到可愛花朵們的害蟲……",
  str_voice_1500211_24 = "哪怕是天涯海角，我也會找到她，然後，好好地保護起來。",
  str_voice_1500211_25 = "如果要談論除了那孩子以外的其他人……那麼，就談論您的事吧。",
  str_voice_1500211_26 = "充滿著情感、燃燒般的玫瑰！喜歡？不，那已經是溺愛！",
  str_voice_1500211_27 = "呵呵，對於他人的心意視而不見之人，就算是您，也不會包容吧……",
  str_voice_1500211_28 = "我能感受到，巨像滿載著您的情感，就像我的花兒一般。",
  str_voice_1500211_29 = "小小的、小小的種子們，園丁尤拉在此。準備好於愛的澆灌下盛放了嗎？",
  str_voice_1500211_30 = "多麼可貴的體驗！",
  str_voice_1500211_31 = "愛的國度已經綻放！",
  str_voice_1500211_32 = "迷失的羔羊終將回家！",
  str_voice_1500211_33 = "這才是，真正的絢麗人生！！",
  str_voice_1500211_34 = "來吧，去那花園中。",
  str_voice_1500211_35 = "愛意即將奔流而出。",
  str_voice_1500211_36 = "喔吼吼～！",
  str_voice_1500211_37 = "為你而獻——",
  str_voice_1500211_38 = "以愛之名——",
  str_voice_1500211_39 = "生長吧！",
  str_voice_1500211_40 = "綻放吧！",
  str_voice_1500211_41 = "排排坐，小花朵……",
  str_voice_1500211_42 = "這份濃烈的愛意終有一天會傳達到你所在的地方。",
  str_voice_1500211_43 = "這……就叫做凋零嗎……",
  str_voice_1500211_44 = "今天天氣很好，你願意來參觀我的花園嗎？",
  str_voice_1500211_45 = "真遺憾，我需要您更多的愛意。",
  str_voice_1500211_46 = "啊——！這個……您在哪裡得到的？！",
  str_voice_1500211_47 = "心意大於愛意，感謝您。",
  str_voice_1500211_48 = "啊——！被您滿溢的愛，包裹的感覺！",
  str_voice_1500211_49 = "您看到了嗎？在我美麗的花園裡，每一朵花都有自己的名字，威廉先生，瑪麗小姐……啊——下一朵，要取什麼名字呢？",
  str_voice_1500211_50 = "我經歷了驚訝、憤恨與落寞，現在只有對她的無盡思念。但唯愛不變，唯愛永恆。",
  str_voice_1500211_51 = "現在的我，已築起最華麗溫暖的子房。她隨時可以循著愛的芬芳回家，而我會摒棄前嫌地張開懷抱。",
  str_voice_1500211_52 = "白夜，極光。",
  str_voice_1500211_53 = "您好——",
  str_voice_1500211_54 = "早晨來了。",
  str_voice_1500211_55 = "您一定在吧？",
  str_voice_1500211_56 = "在夜晚，我總掛念著您……",
  str_voice_1500211_57 = "舊年已逝，愛意不減。",
  str_voice_1400171_1 = "下次的作戰地點在哪裡？我來先規劃好撤退路線！打不過大家就一起撤退，一個都不落下！",
  str_voice_1400171_2 = "嗯嗯！好像哪裡有奇怪的動靜！不快點躲起來的話……！",
  str_voice_1400171_3 = "嗚嗚……又因為挖穿艙室被罵了……我只是在研究舊工藝材質，以防萬一而已啦……",
  str_voice_1400171_4 = "最近開始研究光學迷彩了！有了它我們就能在敵人的眼皮下逃走囉！",
  str_voice_1400171_5 = "看看看，最新款的鑽頭！呼～光是撫摸它就彷彿聞到了剛挖開的潮濕泥土的香氣～",
  str_voice_1400171_6 = "有了這樣的力量，再怎麼堅硬的地面都跟奶油蛋糕一樣！啊，突然有點想吃了……",
  str_voice_1400171_7 = "你太沒有危機意識啦，就像我跟我的小隊成員們強調的那樣——計劃、預判，未雨綢繆是很重要的！",
  str_voice_1400171_8 = "好想念爺爺啊，也許是他一直默默守護著我，我才能每次都成功逃脫，化險為夷。又或者……是因為那另一隻兔子？",
  str_voice_1400171_9 = "你可一定要把我定的路線記牢啊，失敗沒有關係，只要活下來，就還沒有輸！",
  str_voice_1400171_10 = "嗯……計劃E就這樣吧……接下來是計劃F……",
  str_voice_1400171_11 = "好咧！我這就來確認一下附近的避難方向！",
  str_voice_1400171_12 = "什、什麼聲音？啊，是你。好險好險，我差一點就想逃走了。",
  str_voice_1400171_13 = "訂購的裝備怎麼還沒到貨，真是的，那就只好再等等……又過五分鐘了！",
  str_voice_1400171_14 = "跟你在一起就覺得很安全呢，啊，不過撤退路線我有好好準備唷！",
  str_voice_1400171_15 = "祝你生日快樂！我準備了好多慶祝計劃，A到J你選哪一個？",
  str_voice_1400171_16 = "你回來啦！我已經想好了逃走路線啦……嗯？不逃走嗎？",
  str_voice_1400171_17 = "早安！讓我們開始討論新的計劃吧！比如說「路線」之類的！",
  str_voice_1400171_18 = "哇呀！歡、歡迎回來，我可沒有在做什麼可疑的事唷！沒有喔！",
  str_voice_1400171_19 = "還沒休息嗎？睡不著嗎？是因為缺乏安全感嗎？我幫你打個洞吧！",
  str_voice_1400171_20 = "雖然大家不太喜歡住地下，但常常跑來跑去這一點還是很棒的唷！",
  str_voice_1400171_21 = "聽說啟光的人都住在一個好大的地洞裡，他們一定有很厲害的電鑽！",
  str_voice_1400171_22 = "及時逃走！",
  str_voice_1400171_23 = "果然還是很可怕，果然還是很想逃走，但是，我已經能面對了！",
  str_voice_1400171_24 = "說來慚愧，因為他每天都戴著頭套，我都快忘記他本來的樣子了。",
  str_voice_1400171_25 = "那位小個子夥伴讓我覺得很親切唷，而且還會幫我調整鑽頭呢！",
  str_voice_1400171_26 = "我喜歡新的挖掘器材、新的洞口和新的撤退計劃！",
  str_voice_1400171_27 = "封閉空間真的很可怕！沒有洞口怎麼行！",
  str_voice_1400171_28 = "巨像真的好棒呀，好快好厲害呀！所以……我可以挖洞嗎？",
  str_voice_1400171_29 = "撤退專家菈比在此！這個大鑽頭很嚇人嗎？放心放心，是用來確保逃跑路線的啦！",
  str_voice_1400171_30 = "鑽頭變強啦！",
  str_voice_1400171_31 = "果然，遁地才是王道！",
  str_voice_1400171_32 = "太好了！我的鑽頭升級啦！",
  str_voice_1400171_33 = "不管想去哪！鑽過去！突破它！",
  str_voice_1400171_34 = "後方的安全就交給我吧！",
  str_voice_1400171_35 = "萬無一失！",
  str_voice_1400171_36 = "等你下令！",
  str_voice_1400171_37 = "不會讓你們逃走！",
  str_voice_1400171_38 = "封鎖你的退路！",
  str_voice_1400171_39 = "路線確保！",
  str_voice_1400171_40 = "障礙排除！",
  str_voice_1400171_41 = "安全第一喔，各位！",
  str_voice_1400171_42 = "想從跑路專家手裡溜走？",
  str_voice_1400171_43 = "不要慌，跟我來！",
  str_voice_1400171_44 = "悄悄跟你說……我其實準備了一條祕密逃跑通道！",
  str_voice_1400171_45 = "嗯……讓我想想怎麼使用吧。",
  str_voice_1400171_46 = "真的要給我？謝謝！",
  str_voice_1400171_47 = "嗯！希望能派上用場！",
  str_voice_1400171_48 = "太棒了！收到了最想要的禮物！",
  str_voice_1400171_49 = "撤退法則：第一，清楚自己為了什麼而撤退！第二，要像風一樣灑脫！第三，所有的情緒要放在撤退之後！",
  str_voice_1400171_50 = "老大很強，我現在身邊有一群可靠的夥伴，所以再也不用一個人逃跑了……我會守住大家的退路！",
  str_voice_1400171_51 = "實在跑不掉怎麼辦？那我就像當年的爺爺一樣擋在你前面就好了，為了那個時刻，得再長高一點才行呢～",
  str_voice_1400171_52 = "白夜極光！",
  str_voice_1400171_53 = "敲敲，你在嗎？",
  str_voice_1400171_54 = "早安！",
  str_voice_1400171_55 = "要不要活動一下？",
  str_voice_1400171_56 = "你在休息了嗎？",
  str_voice_1400171_57 = "開洞！慶祝新年！",
  str_voice_1300491_1 = "真閒，老大，你來和我過過招吧！啊？你說那幾位想來試試……不了不了，我才不想和女人打。",
  str_voice_1300491_2 = "暗鬼沒什麼了不起的，我一劍一個。想當年經歷各種磨練的時候……等一下，什麼叫下次讓我單獨上前線？",
  str_voice_1300491_3 = "總是叫你老大，也不知道真正的老大那邊聽到會不會生氣。算了，大不了你們兩個到時候打一架。",
  str_voice_1300491_4 = "來！剛才是誰不服？過來和塞留古大人過兩招！別被我打哭啊！！",
  str_voice_1300491_5 = "很多時候人們想的太複雜了，這世界上很多道理，無非是我勝過你，或者你勝過我而已。",
  str_voice_1300491_7 = "不要在意我的兩柄大劍，也別在意我的豹頭。不影響吃飯，也不影響視野，也別再有其他問題了，煩！",
  str_voice_1300491_8 = "這兩把劍確實不錯，但是對我來說已經有點輕了。老大，什麼時候幫我弄把更好的武器？更強更鋒利的那種！",
  str_voice_1300491_9 = "老大，你在意我的豹頭頭盔嗎？這不是我原本的頭，只是後來適應了而已。等一下，不要摸它！更不能搓！",
  str_voice_1300491_10 = "站著好無聊啊，有什麼人啊鬼啊的東西，讓我打一打吧？再這樣下去要被商會的傢伙超過了……",
  str_voice_1300491_11 = "叫我看管東西當然沒問題。但不准用「看家」這種詞！說了多少次了！",
  str_voice_1300491_12 = "再說一遍，我不是什麼大貓！不要一直靠過來！",
  str_voice_1300491_13 = "武力是我的生命，不靠這個，我沒辦法在影鎮混下去。",
  str_voice_1300491_14 = "老大的話就是一切，啊，不是說你喔，是我在影鎮的老大。",
  str_voice_1300491_15 = "讓我幫你切個生日蛋糕？",
  str_voice_1300491_16 = "待著也是待著，不如揮幾下劍來練練。",
  str_voice_1300491_17 = "感覺偶爾也要洗一下這顆豹頭，不過會不會有什麼問題啊？",
  str_voice_1300491_18 = "是錯覺嗎，我覺得更有精神了！",
  str_voice_1300491_19 = "喵嗚——突然很想這樣叫兩聲。",
  str_voice_1300491_20 = "別看影鎮很亂，那裡可是很多人唯一能去的地方呢。",
  str_voice_1300491_21 = "如果沒有碰上伊斯塔萬，或許我就加入紅油扳手了，哈哈！",
  str_voice_1300491_22 = "有光即有影！",
  str_voice_1300491_23 = "統統切碎！",
  str_voice_1300491_24 = "沒有伊斯塔萬，就沒有我塞留古，就為了那一招，我會跟他一輩子。",
  str_voice_1300491_25 = "那對小惡狗？剛剛入會的小傢伙，要學的事情還很多呢。",
  str_voice_1300491_26 = "有什麼衝突，吃頓烤肉就能解決了，如果解決不了，就再來一頓。",
  str_voice_1300491_27 = "有本事就正面來，暗地裡放冷箭的傢伙，算個什麼東西？",
  str_voice_1300491_28 = "這傢伙還真大，能不能搭乘他去白夜城轉一圈啊？",
  str_voice_1300491_29 = "你就是這座巨像的管理人？厲害啊，從今天起我就叫你老大了！雖然我還有個老大，但沒關係，這是我尊重你們的證明！",
  str_voice_1300491_30 = "這兩柄劍該換了！",
  str_voice_1300491_31 = "這不是砍瓜切菜的好機會嗎？！",
  str_voice_1300491_32 = "我才是伊斯塔萬幫的第一打手！",
  str_voice_1300491_34 = "跟著我就行了！",
  str_voice_1300491_35 = "有本事就來過兩招！",
  str_voice_1300491_36 = "準備吃我一劍！",
  str_voice_1300491_37 = "倒在腳下吧！",
  str_voice_1300491_38 = "別想跑！",
  str_voice_1300491_39 = "斬了你！",
  str_voice_1300491_40 = "斬！再斬！",
  str_voice_1300491_41 = "要跟上我的速度喔！",
  str_voice_1300491_42 = "贏得太輕鬆了！",
  str_voice_1300491_43 = "再來一次！！喂，再來一次！！",
  str_voice_1300491_44 = "真閒，想找人練練！",
  str_voice_1300491_45 = "送我這個不如和我打一架。",
  str_voice_1300491_46 = "哈哈，我正想要呢！你還真懂我啊！",
  str_voice_1300491_47 = "無功不受祿！說吧，要我幹什麼？",
  str_voice_1300491_48 = "太對我胃口了！都不好意思只說謝謝了！",
  str_voice_1300491_49 = "這豹頭是我的頭盔啊！我就隨便戴一下，沒想到就拿不下來了。那位老大推薦我把這個作為個人特色，是挺帥的。",
  str_voice_1300491_50 = "其實，如果能摘下我的頭盔，我也不願意摘下來，我的臉可是比這豹頭可怕多了，那是暗鬼「賞」給我的。",
  str_voice_1300491_52 = "白夜極光！",
  str_voice_1300491_53 = "老大，有空嗎？",
  str_voice_1300491_54 = "早啊！老大！",
  str_voice_1300491_55 = "老大你在哪？",
  str_voice_1300491_56 = "老大你還沒休息吧？",
  str_voice_1300491_57 = "新年好啊！來喝！",
  str_voice_1300221_1 = "越老的柴油就越香，讓人喝一瓶想兩瓶、喝兩瓶想三瓶……",
  str_voice_1300221_2 = "鋸子和我都需要補充動力了，不知道去哪裡能弄到一些柴油啊？",
  str_voice_1300221_3 = "好險，差點把頭套給弄掉了，如果讓別人看到我的真面目那就……",
  str_voice_1300221_4 = "我聽到了熟悉的鑽頭聲音，菈比！她會不會也到這裡來了……？",
  str_voice_1300221_5 = "別看我之前瘦小，現在喝了柴油，再加上這把鋸子，把他們全幹掉！幹掉！",
  str_voice_1300221_7 = "柴油特調味道不錯喔，嚐嚐看？欸？真的不要？菈比就很喜歡……",
  str_voice_1300221_8 = "怎樣啦，別看我個子矮，要揍趴比我大幾倍的傢伙也不在話下！多依賴我一點也沒問題啦！",
  str_voice_1300221_9 = "真奇怪，明明看起來完全不同，不知為什麼覺得這裡讓人想起紅油扳手。這就是所謂……家的感覺嗎。",
  str_voice_1300221_10 = "呼啊……好睏。啊，可別打著趁我睡著偷偷摘掉頭套看看之類的鬼主意……",
  str_voice_1300221_11 = "站這裡就行了？真的不用把房間裡任何東西劈開？",
  str_voice_1300221_12 = "有在意的據點嗎，動手之前要不要我去偵察一下？呃……不動手？真可惜……",
  str_voice_1300221_13 = "這個老巢真的好寬敞，還有暖和的被窩可以睡，要是能更常見到菈比就好了……嗯？啊，菈比是……沒，沒什麼！",
  str_voice_1300221_14 = "頭套下面？沒什麼好看的。就算你這樣盯著看也沒用，我絕對不會拿下來！畢竟已經發過誓了，為了菈比……",
  str_voice_1300221_15 = "讓我來切生日蛋糕啊！沒問題，整個切碎。",
  str_voice_1300221_16 = "頭兒，現在流行展覽兔子嗎？！",
  str_voice_1300221_17 = "頭兒！搞到東西了沒啊？",
  str_voice_1300221_18 = "頭兒！你回來啦！我們今天幹一票大的！？",
  str_voice_1300221_19 = "一杯柴油、一碟碎麵包乾，當宵夜了……",
  str_voice_1300221_20 = "紅油扳手！一群瘋子的大集合！不過，我喜歡哈哈哈！",
  str_voice_1300221_21 = "我討厭啟光那群死板的傢伙，但是他們的技術可真不錯，聽說有動力更大的電鋸！",
  str_voice_1300221_22 = "菈比萬歲！",
  str_voice_1300221_23 = "一群比我還蠢的蠢貨！",
  str_voice_1300221_24 = "菈比的鑽頭刺中了我的心！不信，我把心鋸開給她看～菈比～",
  str_voice_1300221_25 = "我和四葉草只是曾經的搭檔，沒什麼特殊情感……不過她確實挺可憐的，唉。",
  str_voice_1300221_26 = "我愛菈比，我想和她永遠在一起，就是這麼簡單。我無法容忍任何人傷害她！",
  str_voice_1300221_27 = "一到戰場上就腿軟的傢伙，就像濕透的木柴，根本派不上用場嘛！",
  str_voice_1300221_28 = "好大！比我們那裡的大蜥蜴不知道強多少……",
  str_voice_1300221_29 = "說吧，想讓我去鋸了誰？小看這鋸子和我，下場可都會很淒慘喔！",
  str_voice_1300221_30 = "感覺血液都燃起來了！",
  str_voice_1300221_31 = "轉吧！轉得更快！",
  str_voice_1300221_32 = "更多柴油！動力更強！",
  str_voice_1300221_34 = "算我一個！",
  str_voice_1300221_35 = "別以為你逃得掉！",
  str_voice_1300221_36 = "連鋸子都等不及了！",
  str_voice_1300221_37 = "鋸開！鋸開！",
  str_voice_1300221_38 = "碎了你們！",
  str_voice_1300221_39 = "嚐嚐我的電鋸！",
  str_voice_1300221_40 = "嗚咦——！",
  str_voice_1300221_41 = "嘿嘿，我是頭兒啦！",
  str_voice_1300221_42 = "看到我的表現了嗎，菈比？",
  str_voice_1300221_43 = "大家快撤退，我留下拖住他們！",
  str_voice_1300221_44 = "噸噸噸，給我更多柴油！哈哈。",
  str_voice_1300221_45 = "這東西有什麼用？",
  str_voice_1300221_46 = "給我的……？這個我想要很久了……",
  str_voice_1300221_47 = "很值錢嘛！說，打算叫我幹嘛？",
  str_voice_1300221_48 = "嘿，老大！來口柴油吧！",
  str_voice_1300221_49 = "我不是兔子，是為了愛選擇成為兔子！和她成為同類的話，也能消除一些不安吧。雖然可能只是我一廂情願……",
  str_voice_1300221_50 = "父母，你見過自己的父母嗎？反正我沒見過。或者說，那根本就不是我媽，只是賣掉我的人，而已。",
  str_voice_1300221_52 = "白夜極光！",
  str_voice_1300221_53 = "來杯柴油？",
  str_voice_1300221_54 = "哈哈，早。",
  str_voice_1300221_55 = "是不是該吃午飯了？",
  str_voice_1300221_56 = "有點睏了。",
  str_voice_1300221_57 = "新年快樂！噸！",
  str_voice_1601051_1 = "三、二、一～猜猜我是誰？Bingo～你在做什麼呀？有沒有什麼事情是伊芙可以為你做的呢？",
  str_voice_1601051_2 = "伊芙最喜歡哥哥了，誰也不許傷害他！……啊，不好意思，伊芙當然也不允許有人欺負你。",
  str_voice_1601051_3 = "呀！外面剛剛飛過去的是什麼？是鳥嗎？和巨像一樣……喔……原來只是小信使啊……",
  str_voice_1601051_4 = "我好像又聽到暗鬼的嘶吼了……這些，總是讓我想到以前的事……嗯，我已經不害怕了。你看，伊芙完全好、咳、好了、咳咳，抱歉啦。",
  str_voice_1601051_5 = "我記得身體裡雷電翻騰的感覺，危險又可怕。這股強大的力量讓我覺得自己無所不能，但我知道……絕不能再讓自己失控。",
  str_voice_1601051_6 = "我一直都記得哥哥因為我受過的苦……我沒有打算逃避自己過去犯下的錯誤。所以我要幫他分擔更多事情！先從家務做起吧？",
  str_voice_1601051_7 = "你真是溫柔的人，你、咳、你對我這麼好，要不要考慮加入紅油扳手呀哈哈。開玩笑的啦。",
  str_voice_1601051_8 = "伊芙最近遇到了一個好朋友，對我很好，對朋友也很好，你問我他是誰？偷偷跟你說……他會駕駛巨像！",
  str_voice_1601051_9 = "雖然哥哥還是我心中的第一位，不過，現在你可以排在第二位……和多恩並列第二位吧？",
  str_voice_1601051_10 = "那個，你現在很忙嗎？如果不是很忙的話……可不可以跟我說說你們的故事？還有外面的世界？",
  str_voice_1601051_11 = "這件事……可以交給伊芙嗎？謝謝你！我會好好負責的，不會給你添麻煩的。應該……沒問題吧？",
  str_voice_1601051_12 = "要是能在艦橋待上一整天，真的是別無所求了——風景真美呀。",
  str_voice_1601051_13 = "嗯……伊芙有很多想學習的東西，要從哪個開始呢？",
  str_voice_1601051_14 = "我現在很幸福。從來沒想過，我也可以擁有像現在這樣的生活呢。",
  str_voice_1601051_15 = "祝你生日快樂～祝你生日快樂～",
  str_voice_1601051_16 = "你回來啦……要是什麼好玩的事情，能講給我聽聽嗎？",
  str_voice_1601051_17 = "好……好睏啊……你這麼早就起床了嗎？好辛苦呀……",
  str_voice_1601051_18 = "哥哥最近好像也很忙……希望他能早點休息，你也是喔。",
  str_voice_1601051_19 = "不……不行了……我要睡了，你也要……早點休息……啊……",
  str_voice_1601051_20 = "紅油扳手是世界上最棒的地方，有哥哥，和有趣的大家。",
  str_voice_1601051_21 = "在啟光……雖然有不太好的回憶……但我知道，那不是啟光的錯。",
  str_voice_1601051_22 = "是哥哥常說的那句話嗎？及時行樂？",
  str_voice_1601051_23 = "我能感應到牠們的存在和嘶吼……但，我不是牠們的同伴……絕對不是！",
  str_voice_1601051_24 = "等等，多恩！今天的花我已經澆過水了！",
  str_voice_1601051_25 = "約恩會做好看的煙火給我看……欸？那是……炸彈嗎？！",
  str_voice_1601051_26 = "製作物品啦、野餐啦……還有新衣服，這些都很喜歡！這座巨像我也喜歡！",
  str_voice_1601051_27 = "只要是傷害哥哥的人都是壞人，所以我以前也很壞……對吧？",
  str_voice_1601051_28 = "最喜歡巨像了！可以看到很多很多美麗的風景！",
  str_voice_1601051_29 = "重新做一次……自我介紹吧？我叫伊芙，是醒山的妹妹，請……咳，請多指教。一路上給大家添了很多麻煩呢，但我已經沒事了！將將～",
  str_voice_1601051_30 = "要小心力量……",
  str_voice_1601051_31 = "我聽到了……那些聲音……",
  str_voice_1601051_32 = "我能好好控制自己和雷電了。",
  str_voice_1601051_33 = "我，一定會保護好哥哥！",
  str_voice_1601051_34 = "我……我加油。",
  str_voice_1601051_35 = "我已經沒問題了！",
  str_voice_1601051_36 = "可以開始了嗎？",
  str_voice_1601051_37 = "這些嘶吼聲，我很熟悉——",
  str_voice_1601051_38 = "雷電穿透雲層——",
  str_voice_1601051_39 = "電閃。",
  str_voice_1601051_40 = "火花。",
  str_voice_1601051_41 = "我？嗯……一定可以的！",
  str_voice_1601051_42 = "我成功啦？！",
  str_voice_1601051_43 = "我沒能保護好大家……",
  str_voice_1601051_44 = "這裡真好看！和我以前待過的地方完全不一\n樣呢！",
  str_voice_1601051_45 = "嗯……謝謝你。",
  str_voice_1601051_46 = "送給我的嗎？我很喜歡～",
  str_voice_1601051_47 = "雖然跟想像中不一樣……但是謝謝！",
  str_voice_1601051_48 = "你又猜到我喜歡什麼了～",
  str_voice_1601051_49 = "我在隔離艙裡的時候，每晚都會聽到暗鬼的低吼……我好害怕，但紅油扳手的大家都會來安慰過我，讓我知道我不是孤身一人……",
  str_voice_1601051_50 = "多恩是傻瓜……一朵花而已，居然說比自己的生命還重要……",
  str_voice_1601051_51 = "哥哥為了我承受了很多不該承受的事情……那本來就是我一個人的過錯，不應該讓哥哥替我背負……我要努力保護好哥哥，和大家！",
  str_voice_1601051_52 = "白夜極光！",
  str_voice_1601051_53 = "你好呀！",
  str_voice_1601051_54 = "早……早呀……",
  str_voice_1601051_55 = "唔……午飯吃什麼呢？",
  str_voice_1601051_56 = "要早點休息才行喔！",
  str_voice_1601051_57 = "新年快樂！伊芙希望你新的一年平平安安，開開心心！",
  str_voice_1501041_1 = "相對萬物的永恆來說，花開也不過是短短的一瞬。",
  str_voice_1501041_2 = "你喜歡曬太陽嗎？我好像很久沒站在太陽下了。陽光照在皮膚上的溫度很神奇。雖然偶爾還是會起雞皮疙瘩，但這種溫暖……好像也不錯。",
  str_voice_1501041_3 = "你不用太擔心我，我的耳朵很靈，這裡的路也記熟了——啊！是桌角……？",
  str_voice_1501041_4 = "這並不是什麼值得誇耀的力量，也許它還有很多不穩定的因素……再怎麼說，這可是暗鬼的力量啊？",
  str_voice_1501041_5 = "那個女人……一定已經在某處完成了比之前更加駭人的研究，想想就覺得害怕……",
  str_voice_1501041_6 = "這個世界上一定還有像我和伊芙這樣的存在。等我找到他們之後……一定要盡可能地幫助他們。",
  str_voice_1501041_7 = "嗯，現在我們是可以互說祕密的關係了。不如你先說說你的祕密？",
  str_voice_1501041_8 = "我做夢都沒想到自己還能像這樣隨心所欲地生活。伊芙、醒山、還有紅油扳手的人們……他們現在都是我的朋友了，你也是。",
  str_voice_1501041_9 = "花是我和伊芙的回憶，瘦弱的我們曾擁抱在一起，努力汲取少得可憐的溫暖。但現在我們不再害怕孤獨，因為我們種下了代表你的花。",
  str_voice_1501041_10 = "你的手停下來了吧？就算看不見，我也能感覺到。",
  str_voice_1501041_11 = "我可以答應你，但你得幫我給伊芙的花澆水。",
  str_voice_1501041_12 = "有什麼事嗎？我正準備再熟悉一下房間構造呢。",
  str_voice_1501041_13 = "巨像裡的空氣和其他地方都不一樣，這也許就是天空的味道吧？",
  str_voice_1501041_14 = "你在那邊嗎？難怪這裡忽然熱鬧了起來。",
  str_voice_1501041_15 = "生日快樂，這可是我特地編的花環喔。",
  str_voice_1501041_16 = "今天有什麼安排嗎？嗯……要不要一起去散個步，曬個太陽？",
  str_voice_1501041_17 = "早安。朝陽微亮，天已破曉。是不是很美？",
  str_voice_1501041_18 = "入夜了，有點涼，別感冒了。",
  str_voice_1501041_19 = "你不會是準備熬夜吧？為什麼要跟自己的身體過不去？",
  str_voice_1501041_20 = "伊芙的家，就是我的家。伊芙的家人就是我的家人。",
  str_voice_1501041_21 = "啟光……對我來說，那個地方除了可悲的回憶以外一無所有。",
  str_voice_1501041_22 = "及時行樂。紅油扳手那群人天天在喊，想不記住都難。",
  str_voice_1501041_23 = "我在赤眼谷的暗鬼之中稱霸過一段時間，還滿厲害的對吧？",
  str_voice_1501041_24 = "我發誓，會永遠向著太陽的方向，無論多麼熾熱難耐。",
  str_voice_1501041_25 = "醒山居然是伊芙的親哥哥，真是難以置信……他們兩個根本不像啊？",
  str_voice_1501041_26 = "伊芙喜歡花，我也喜歡。",
  str_voice_1501041_27 = "烈火燃燒時的聲音……總會把我拉回那痛苦的記憶。",
  str_voice_1501041_28 = "這就是穿過風暴的巨像嗎？聞起來……挺酷的。",
  str_voice_1501041_29 = "又見面了呢，來談談我們的合作條件吧：不能欺負伊芙、不能惹伊芙不高興、不能讓伊芙餓肚子。",
  str_voice_1501041_30 = "力量變強了……",
  str_voice_1501041_31 = "要好好控制力量……",
  str_voice_1501041_32 = "有些花，一生只綻放一次。",
  str_voice_1501041_33 = "剎那即是永恆。",
  str_voice_1501041_34 = "我明白了。",
  str_voice_1501041_35 = "芳華綻放。",
  str_voice_1501041_36 = "把握好機會。",
  str_voice_1501041_37 = "就是現在，上吧！",
  str_voice_1501041_38 = "請記住這個瞬間。",
  str_voice_1501041_39 = "我來幫忙！",
  str_voice_1501041_40 = "結束了。",
  str_voice_1501041_41 = "讓我來可以嗎？",
  str_voice_1501041_42 = "顯而易見的結果。",
  str_voice_1501041_43 = "深呼吸，不要慌。",
  str_voice_1501041_44 = "我記得這裡是要向左轉……然後……",
  str_voice_1501041_45 = "謝謝你的禮物。",
  str_voice_1501041_46 = "你比我想像中更善解人意。",
  str_voice_1501041_47 = "我會好好珍惜的。",
  str_voice_1501041_48 = "想不到我們心有靈犀？",
  str_voice_1501041_49 = "母親……還有那個女人，她們都是只知道研究與實驗的怪胎，但若是沒有她們，我也沒辦法見到伊芙。也許，這就是宿命吧。",
  str_voice_1501041_50 = "在實驗室裡有伊芙陪伴的日子，我至今難以忘懷。是她的純真和善良……讓我覺得或許外面的世界沒有那麼糟糕，陽光或許可以接受。",
  str_voice_1501041_51 = "一切都成為了過去，我們不再需要忍受痛苦的折磨。如果這樣的日子能一直持續…………不，它必須持續下去，為此我願意做任何事。",
  str_voice_1501041_52 = "白夜極光。",
  str_voice_1501041_53 = "嗨，導航員。",
  str_voice_1501041_54 = "太陽又出來了……",
  str_voice_1501041_55 = "記得攝取營養喔。",
  str_voice_1501041_56 = "夜幕讓人心情愉悅。",
  str_voice_1501041_57 = "新年快樂，我的新年願望是看到伊芙更多的笑容。你的新年願望是什麼？嗯，有志氣，你一定能實現的。",
  str_voice_1401011_1 = "噓！您看見那裡的敵人了嗎？想活命就趕快溜吧！……跑的時候小心別摔倒。順便補充一句，我開玩笑的。",
  str_voice_1401011_2 = "東西不見了嗎？該不會是在懷疑我吧？偷東西和惡作劇是有差別的！我幫您找！順便證明這事不是我幹的！",
  str_voice_1401011_3 = "我絕不會在工作的時候惡作劇，但現在是非工作時間……嗯？有沒有很好奇我做了什麼？",
  str_voice_1401011_4 = "果然因為之前的戰鬥而出了點問題呢……啊，您來得正好！我正在調整設備，您能幫忙聽一下音量嗎？",
  str_voice_1401011_5 = "感謝您的信任，我會繼續努力的！不管是工作還是惡作劇，都會繼續努力的！",
  str_voice_1401011_6 = "通訊員需要有耐心和專注力，還要能迅速應變各種事態，並以最準確的方式傳達！",
  str_voice_1401011_7 = "非工作時間插播一條訊息：導航員的房間裡出現了毛毛蟲，而且這條毛毛蟲真的不是我放的！",
  str_voice_1401011_8 = "親愛的導航員，為了向您表達好感，從今天開始我會給您更多驚喜！",
  str_voice_1401011_9 = "適當的惡作劇能夠增進雙方的友誼，但太過分的事我是不會做的，畢竟我可不想引起您的反感。",
  str_voice_1401011_10 = "咳咳、因為太閒了所以來場猜謎遊戲吧。我剛剛為您準備了一個陷阱，在……您猜猜在哪裡？",
  str_voice_1401011_11 = "好的。聯絡員安希雅聽候指示。為了保證通訊及時和傳達準確……什麼？不是要進行通訊工作嗎？",
  str_voice_1401011_12 = "我待會有份臨時的工作，結束以後會立刻回來！",
  str_voice_1401011_13 = "從這邊走，掉到陷阱裡的話要自己爬上來……喔，已經掉下去了？",
  str_voice_1401011_14 = "導航員，您想知道貼在您背後的紙條上寫著什麼嗎？不告訴您。",
  str_voice_1401011_15 = "生日快樂！這是禮物！……哈哈，上當了！真正的禮物在您身後！",
  str_voice_1401011_16 = "工作還順利嗎？有通訊任務的話，隨時叫我。",
  str_voice_1401011_17 = "早安！今天有訊息需要發送嗎？嗯？怎麼總是沒有？",
  str_voice_1401011_18 = "晚安！一天結束了，要把需要報告的事情做一下總結了！",
  str_voice_1401011_19 = "已經是深夜了，這時候發送訊息對方是收不到的，但是我有緊急聯絡手段！",
  str_voice_1401011_20 = "啟光是我的家，永遠都是我的家。我會為了守護這裡不惜一切。",
  str_voice_1401011_21 = "不在啟光的話，我會去影鎮。那裡對我的惡作劇接受度會比較高。",
  str_voice_1401011_22 = "為了啟明之光！",
  str_voice_1401011_23 = "艾斯特拉大陸有朝一日一定可以完全擺脫暗鬼的。",
  str_voice_1401011_24 = "薇絲小姐很厲害的，充滿幹勁又很可靠——我想像她一樣！",
  str_voice_1401011_25 = "悄悄告訴您，我其實也對希羅娜長官的尾巴有興趣，看起來很好玩。",
  str_voice_1401011_26 = "最喜歡金屬樂了，那節奏感和力量感讓人熱血沸騰！",
  str_voice_1401011_27 = "我可不喜歡那些公私不分的傢伙，工作的時候就要好好工作！",
  str_voice_1401011_28 = "雖然我知道巨像是什麼，但我還是不禁感嘆「哇！第一次看到這種東西！」",
  str_voice_1401011_29 = "測試測試，音量測試。您好，這裡是啟光通訊員安希雅！由於還沒有收到您發來的工作委託，我就先這樣隨意行動囉！",
  str_voice_1401011_30 = "提高音量！",
  str_voice_1401011_31 = "及時檢修通訊設備也是工作的一環喔！",
  str_voice_1401011_32 = "要聽聽看我身為通訊員的工作心得嗎？",
  str_voice_1401011_33 = "目標是：通訊範圍！無限大——！",
  str_voice_1401011_34 = "我來負責聯絡！",
  str_voice_1401011_35 = "調整完畢。",
  str_voice_1401011_36 = "音波就緒。",
  str_voice_1401011_37 = "超級音波！",
  str_voice_1401011_38 = "震天動地！",
  str_voice_1401011_39 = "震懾嗎？",
  str_voice_1401011_40 = "別動！",
  str_voice_1401011_41 = "大家隨時保持聯絡！",
  str_voice_1401011_42 = "一切順利！",
  str_voice_1401011_43 = "快跑！",
  str_voice_1401011_44 = "喂喂，聽——得——到——嗎？！喔，聽得到啊。",
  str_voice_1401011_45 = "禮物？是驚嚇盒嗎？",
  str_voice_1401011_46 = "哇！真的可以收下嗎？",
  str_voice_1401011_47 = "我其實滿期待您送驚嚇盒給我的！",
  str_voice_1401011_48 = "謝謝！請讓我為您準備回禮吧！",
  str_voice_1401011_49 = "我不擅長戰鬥，但我逐漸找到了適合自己的道路——成為一名通訊員，為大家及時傳遞訊息，超正經的那種！",
  str_voice_1401011_50 = "有一次我偷偷拆掉了一名啟光執勤人員的彈匣。他發現彈匣丟了，只好放棄當天的洩憤行為，屋頂也就少了一些彈孔。",
  str_voice_1401011_51 = "有時我也會做一些偵察工作，不論面對哪種危機情況，通訊員都要盡可能保證情報能夠及時傳遞！",
  str_voice_1401011_52 = "白夜極——光——！",
  str_voice_1401011_53 = "通訊測試！",
  str_voice_1401011_54 = "您收到了一則新訊息！",
  str_voice_1401011_55 = "收到請回覆！",
  str_voice_1401011_56 = "晚安！導航員！",
  str_voice_1401011_57 = "新年快樂！希望新的一年也可以收到好消息！",
  str_voice_1501001_1 = "我留在這裡，完全是出於我自己的意願，與小白無關。",
  str_voice_1501001_2 = "小白與那些草履蟲不同，或許這就是你為什麼能駕駛巨像的原因。",
  str_voice_1501001_3 = "有時候無需和那些草履蟲們多說什麼，直接命令就好了。",
  str_voice_1501001_4 = "即使再困難，我也不需要草履蟲的幫助。",
  str_voice_1501001_5 = "感受到這股危險的氣息了嗎，今後靠近我的時候，要小心了。",
  str_voice_1501001_6 = "驚訝嗎，小白？這就是我的真正能力，但是我毫不在意。",
  str_voice_1501001_7 = "堂泰斯家族自古擔負著守護星空墓穴的責任，因此我也繼承了這個使命，無從選擇。",
  str_voice_1501001_8 = "我的能力來自於家族，但現在的我所經歷的這些……會成為只屬於我的寶貴力量。",
  str_voice_1501001_9 = "很多人說我嫁給了墓穴，但終有一天我會離開它。在我的使命結束以後，以我自己的力量離開。",
  str_voice_1501001_10 = "小白很閒嗎？那我們對調一下吧，如何？你來這坐著。",
  str_voice_1501001_11 = "小白無法妥善履行自己的職責嗎？好吧，就幫幫小白吧。",
  str_voice_1501001_12 = "即便知道我的過去，又能如何？無非只是哀嘆一聲罷了。",
  str_voice_1501001_13 = "希望你不要和那些草履蟲一樣東問西問。",
  str_voice_1501001_14 = "請不要讓我和其他人待在一起，我喜歡安靜……我沒叫你離開。",
  str_voice_1501001_15 = "生日……很久沒有聽到這個詞了。那就……生日快樂，小白。",
  str_voice_1501001_16 = "請不要一直花時間和我打招呼，去做小白應該做的事情。",
  str_voice_1501001_17 = "清晨總是那麼安靜，但草履蟲們醒來後就會變得很吵鬧。",
  str_voice_1501001_18 = "中午時分的耀眼陽光，小白獨自享受吧，我要先去休息。",
  str_voice_1501001_19 = "我要欣賞一下寧靜的夜晚。小白，不要讓那些草履蟲來打攪我。",
  str_voice_1501001_20 = "雖然那些人看起來都很古怪，不過好在不會打擾到我。",
  str_voice_1501001_21 = "請安心，我不會強迫他們用草履蟲大小的腦袋思考。",
  str_voice_1501001_22 = "嗯，願真理祝福你。",
  str_voice_1501001_23 = "連草履蟲都比不上的可憐生物。",
  str_voice_1501001_24 = "維多利亞女士很強大，但是她想窺視墓穴的祕密，為時尚早。",
  str_voice_1501001_25 = "契法就像她的環架一樣冥頑不靈，這一點與我不同。",
  str_voice_1501001_26 = "寧靜的夜晚，如果能有一絲微風就再好不過了。",
  str_voice_1501001_27 = "這片大陸上，有太多吵鬧的草履蟲了。",
  str_voice_1501001_28 = "如此巨大的傢伙，飛起來卻可以那麼安靜，不愧是遠古的造物。",
  str_voice_1501001_29 = "我是希卡蕾，亡陵的守護人……為何露出一副驚訝的表情？好吧，希望這個頭銜沒有嚇到你。",
  str_voice_1501001_30 = "這是我真正的能力。",
  str_voice_1501001_31 = "法利亞，覺醒了。",
  str_voice_1501001_32 = "亡陵的力量，已經掌握。",
  str_voice_1501001_33 = "也許……能夠掙脫亡陵的束縛。",
  str_voice_1501001_34 = "只需要我自己就足夠了。",
  str_voice_1501001_35 = "出現吧。",
  str_voice_1501001_36 = "法利亞，準備開啟。",
  str_voice_1501001_37 = "法利亞，開啟！",
  str_voice_1501001_38 = "法利亞，釋放！",
  str_voice_1501001_39 = "死亡的氣息。",
  str_voice_1501001_40 = "草履蟲們，再見。",
  str_voice_1501001_41 = "與人一起行動，很不習慣。",
  str_voice_1501001_42 = "只有這點程度？",
  str_voice_1501001_43 = "讓我斷後。",
  str_voice_1501001_44 = "想看看真正的墓穴嗎？小白？",
  str_voice_1501001_45 = "這還不能引起我的注意，小白。",
  str_voice_1501001_46 = "嗯，這個還差不多。",
  str_voice_1501001_47 = "堂泰斯家族會記得小白的禮物。",
  str_voice_1501001_48 = "你……謝謝。",
  str_voice_1501001_49 = "堂泰斯家族並非真理結社的下屬，而是其盟友，這一定要分清楚。",
  str_voice_1501001_50 = "法利亞……它是星空墓穴的鑰匙，只能由亡陵之衛掌握。你不需要對此瞭解太多，我認為有必要的時候就會說明。",
  str_voice_1501001_51 = "出生之時，我的使命就是守護這座墓穴，直至我死去，或……新生。",
  str_voice_1501001_52 = "白夜極光。",
  str_voice_1501001_53 = "小白，你好。",
  str_voice_1501001_54 = "早安，小白。",
  str_voice_1501001_55 = "喔，午安……",
  str_voice_1501001_56 = "入夜了，小白，晚安。",
  str_voice_1501001_57 = "新年快樂。",
  str_voice_1500981_1 = "我不是故意在蛋糕上放辣椒的，我以為它只是比較長的櫻桃。",
  str_voice_1500981_2 = "那些黑色的花朵……真漂亮。",
  str_voice_1500981_3 = "我無法理解你的言辭，但……你看起來很開心，也許我應該跟著笑起來。",
  str_voice_1500981_4 = "我不記得自己是誰，不記得自己為什麼會在這裡。我只知道……自己的使命是封印那棵樹。",
  str_voice_1500981_5 = "詛咒的芳香侵蝕著每位來訪者的心智，他們沉迷其中無法自拔，最終化為我們的養分。",
  str_voice_1500981_6 = "那些徬徨的靈魂漂浮於詛咒之樹的邊緣，他們低語著我們無法理解的言語，試圖剝開我的理智。",
  str_voice_1500981_7 = "你確實和其他人有些不同，我已經很久沒有過這種感覺了。",
  str_voice_1500981_8 = "曾經也有過試圖觸及我記憶的存在，那些故事都沒能擁有美好的結局，因為就連我也無法理解過去的自己。",
  str_voice_1500981_9 = "我希望每當全新的自己醒來時，映入眼簾的是你的面容。",
  str_voice_1500981_10 = "安靜的空氣……與世隔絕的感覺……",
  str_voice_1500981_11 = "就像平常那樣做就好了。",
  str_voice_1500981_12 = "那些屍體上開出的花朵，我想多看幾次……但伊斯塔萬叔叔不允許我隨便這麼做。",
  str_voice_1500981_13 = "不用擔心，我的身體不會有問題，一直以來都是如此。",
  str_voice_1500981_14 = "空裔……我想我擁有關於他們的記憶……在腦海的深處，在那我無法觸及的地方。",
  str_voice_1500981_15 = "生日快樂，希望你接下來的日子也過得開心。",
  str_voice_1500981_16 = "一天之中最好的時段，要好好利用……",
  str_voice_1500981_17 = "早安，今天也請加油。",
  str_voice_1500981_18 = "你回來了，是忘了什麼東西嗎？",
  str_voice_1500981_19 = "我是不需要睡眠的，不用擔心。",
  str_voice_1500981_20 = "影鎮……危險，但又讓我很安心，我覺得自己很適合這裡。",
  str_voice_1500981_21 = "我偶爾會見到啟光來的人……關係算不錯……吧。",
  str_voice_1500981_22 = "伊斯塔萬叔叔……一直在注視著你。",
  str_voice_1500981_23 = "可怕的生物……最重要的是……牠們沒有情感……",
  str_voice_1500981_24 = "伊斯塔萬叔叔……有著非常深沉的情感，所以才有這麼多人追隨他吧。",
  str_voice_1500981_25 = "克萊肯……似乎不是很願意陪我閒聊。",
  str_voice_1500981_26 = "那些屍體上開出的花很吸引我，但我不能確定那是不是名為喜歡的情感。",
  str_voice_1500981_27 = "我沒有什麼討厭的東西，大家對我來說沒有什麼區別……",
  str_voice_1500981_28 = "巨像……一個讓我有點懷念的詞語，我也好想跟他們說說話……",
  str_voice_1500981_29 = "初次見面……我的名字是庫絲庫塔，來自影鎮……這樣會太正式了嗎？",
  str_voice_1500981_30 = "詛咒的力量變強了……",
  str_voice_1500981_31 = "我還撐得住……",
  str_voice_1500981_32 = "詛咒的能量快要溢出來了。",
  str_voice_1500981_33 = "這副身體就快要沉睡了。",
  str_voice_1500981_34 = "我在。",
  str_voice_1500981_35 = "養分充足。",
  str_voice_1500981_36 = "隨時可以開始。",
  str_voice_1500981_37 = "這可以減輕你們的痛苦。",
  str_voice_1500981_38 = "願你們開出美麗的花朵。",
  str_voice_1500981_39 = "生命歸於塵土……",
  str_voice_1500981_40 = "安穩入睡吧。",
  str_voice_1500981_41 = "我試試看好了。",
  str_voice_1500981_42 = "這裡終會成為花海。",
  str_voice_1500981_43 = "我需要更換軀體了。",
  str_voice_1500981_44 = "我正在參觀你的巨像，有什麼事情嗎？",
  str_voice_1500981_45 = "謝謝你的禮物。",
  str_voice_1500981_46 = "……它看起來有點不一樣。",
  str_voice_1500981_47 = "這就是所謂的……心意？",
  str_voice_1500981_48 = "我感到……非常溫暖……",
  str_voice_1500981_49 = "我已經不記得這是第幾次醒來了。之所以缺失了這麼多的記憶與情感，一定表示我已經死過很多次了吧。",
  str_voice_1500981_50 = "我的能力適合悄無聲息地處理掉對方，所以伊斯塔萬叔叔讓我去做處刑人的工作。因為屍體上開出的花朵很漂亮，因此我就接受了。",
  str_voice_1500981_51 = "我曾經嘗試著和其他人聊些普通的話題，但那實在是太難了，我根本不知道該怎麼開口。",
  str_voice_1500981_52 = "白夜極光。",
  str_voice_1500981_53 = "你好。",
  str_voice_1500981_54 = "早安，新的一天開始了。",
  str_voice_1500981_55 = "午安，你在休息嗎？",
  str_voice_1500981_56 = "希望你有個好夢。",
  str_voice_1500981_57 = "新年快樂，希望新的一年能有個新的開始。",
  str_voice_1500561_1 = "主要靠聽覺，然後是耐心，接下來只要單挑就可以獵殺暗鬼了。嗯？單挑嗎？就是一個人單挑一群暗鬼嘛，很簡單。",
  str_voice_1500561_2 = "用槍的要訣是瞄準頭部。做不到的話，就走到暗鬼面前再瞄準。要是還不行……就把槍插到牠嘴裡。",
  str_voice_1500561_3 = "「牽掛」這種東西，能少一點是一點，不然會被拖累致死。所以……喂，那邊的小鬼，怎麼還不回家？外面到處都是暗鬼，你不要命了？！",
  str_voice_1500561_4 = "這把獵槍的舊主人是個到死都在和暗鬼戰鬥的英雄，上面風乾的血跡是他的勳章，這點我從未忘記。",
  str_voice_1500561_5 = "我喜歡暴風雪。如同漩渦般密不透風、遮天蔽日，感覺很安全。",
  str_voice_1500561_6 = "當個善良的好獵人，始終保持清醒的意識和清明的雙眼。不被冰雪的慘白迷惑，不被夜晚的漆黑干擾。",
  str_voice_1500561_7 = "身高、體型、死亡日期……屍體外側的切口、內部壞損的組織——所有的一切我都會記錄。記錄不僅讓我們瞭解死亡，更讓我們認識生命。",
  str_voice_1500561_8 = "疲勞的時候，可以試試在暴風雪中冥想。將你的一切都融入到鋪天蓋地的狂風和冰刺中，比睡覺還有效。",
  str_voice_1500561_9 = "這是我流浪生涯中短暫的停靠，老實說感覺有點奇怪。我的身體雖然逐漸生鏽，但心卻像冰雪一樣融化，這都是因為你，孩子。",
  str_voice_1500561_10 = "天氣真好啊，不過如果能起暴風雪的話就更好了……嗯？很奇怪嗎？",
  str_voice_1500561_11 = "需要我幫忙嗎？也行，之前你也幫我整理了筆記。",
  str_voice_1500561_12 = "我偶爾也會畫畫暗鬼的肖像，這樣紀錄就更生動了。",
  str_voice_1500561_13 = "對我的筆記本很好奇嗎？這也是我在廢墟裡發現的，保存得還不錯。",
  str_voice_1500561_14 = "野狗比狼更可怕，但如果你是熊，無論遇到什麼都不用擔心。",
  str_voice_1500561_15 = "生日快樂，孩子。時間推進，意味著經驗增長。",
  str_voice_1500561_16 = "喔，很有精神嘛。",
  str_voice_1500561_17 = "早啊，一日之計在於晨。",
  str_voice_1500561_18 = "晚安啊，好好吃頓晚飯吧。",
  str_voice_1500561_19 = "這麼晚了還在工作？噢，是為了預防遇到夜間出沒的稀有暗鬼吧。",
  str_voice_1500561_20 = "我認為北境比其他地方安全。不過那裡很冷，去之前記得好好鍛鍊身體。",
  str_voice_1500561_21 = "啟光有很多真正的軍人，如果有機會我也想加入他們。",
  str_voice_1500561_22 = "暮冬而生。",
  str_voice_1500561_23 = "令人不寒而慄的是，有些暗鬼和我們光靈很像。",
  str_voice_1500561_24 = "露易絲也喜歡記錄，能找到有相同愛好的朋友我很驚喜。",
  str_voice_1500561_25 = "女王將北境守護得很好，能出生在那裡是我的幸運。",
  str_voice_1500561_26 = "要是有另外一本筆記本能用來記錄「如何烹飪暗鬼」的食譜就太好了。",
  str_voice_1500561_27 = "不能浪費食物。現在隨隨便便扔掉，之後餓了就會後悔。",
  str_voice_1500561_28 = "巨像裡沒有暗鬼？這是好事。有的話也沒關係，有我在呢。",
  str_voice_1500561_29 = "旅行者的終點是迷路，流浪者的歸宿是孤獨。要看看我的筆記本嗎？這上面記載了我所看到的一切。坐下來，我慢慢講給你聽。",
  str_voice_1500561_30 = "獵人唯一的盟友是「忍耐」。",
  str_voice_1500561_31 = "要成為好獵人，耐心是不可或缺的。",
  str_voice_1500561_32 = "「與怪物戰鬥的人，需銘記不要讓自己也變成怪物」。",
  str_voice_1500561_33 = "即使終點沒有希望，還是應該做出無畏的選擇。",
  str_voice_1500561_34 = "做了決定，就別回頭。",
  str_voice_1500561_35 = "保持冷靜、保持專注——",
  str_voice_1500561_36 = "上膛！",
  str_voice_1500561_37 = "一槍一個！",
  str_voice_1500561_38 = "來啊！單挑！",
  str_voice_1500561_39 = "別動！",
  str_voice_1500561_40 = "閃開！",
  str_voice_1500561_41 = "不好好跟著我小心受傷！",
  str_voice_1500561_42 = "慶祝！用熱酒乾杯！",
  str_voice_1500561_43 = "自滿的獵人，會成為森林的獵物……",
  str_voice_1500561_44 = "獵人的工作不值得提起。我只會把工作內容記在本子上，你看。",
  str_voice_1500561_45 = "禮物嗎？其實不必的。",
  str_voice_1500561_46 = "喔喔，這個我喜歡！",
  str_voice_1500561_47 = "謝謝，我會回禮的。",
  str_voice_1500561_48 = "是我喜歡的……",
  str_voice_1500561_49 = "儘管現在的我很強壯，但年幼時，虛弱和纖細才是我的代名詞。我亦步亦趨地跟隨父親行走在雪原上，「記錄癖」也是那個時候養成的。",
  str_voice_1500561_50 = "北境雪原充斥著暴風雪、紅油沙漠席捲著沙塵暴，生活如此艱難……我擁有什麼？一桿獵槍、一本筆記本，還有一身舊衣服。",
  str_voice_1500561_51 = "露易絲說的對，流浪者終會停下腳步，在合適的地方「安家」。我將這個溫馨的計畫保存在心裡——但現在我仍然享受流浪的生活。",
  str_voice_1500561_52 = "白夜極光。",
  str_voice_1500561_53 = "在嗎？",
  str_voice_1500561_54 = "來得真早啊，孩子。",
  str_voice_1500561_55 = "你有好好午休嗎？",
  str_voice_1500561_56 = "有空嗎？",
  str_voice_1500561_57 = "新年快樂，我幫你抓了獵物。",
  str_voice_1600931_1 = "你願意讓我研究研究嗎？別那麼緊張，你只需要躺在那就行了。",
  str_voice_1600931_2 = "巨像可真是個好東西，有了他，我也就不用發愁在哪裡睡午覺了。",
  str_voice_1600931_3 = "啟光的科研人員怎麼淨是些小傢伙，不然就把薇薇安叫過來吧。",
  str_voice_1600931_4 = "莉莉的那些女僕真是不錯，不知道我能不能也弄一個，這樣我就不需要自己動手吃飯了。",
  str_voice_1600931_5 = "可別因為貢露個子小就小看她，那孩子的實力毋庸置疑，最重要的是身體素質比想像中更棒。",
  str_voice_1600931_6 = "你的出現還真是伴隨著不小的騷動，不過這也是當然的吧。",
  str_voice_1600931_7 = "年輕人，我很欣賞你，讓我解剖一下怎麼樣？",
  str_voice_1600931_8 = "要記得隨時保持平穩的心態，這樣你才能夠在最緊迫的時候看清楚最重要的東西。",
  str_voice_1600931_9 = "乾脆在你的巨像裡設一間新的研究室好了，反正我只要可以繼續進行生物研究，在哪裡都無所謂。",
  str_voice_1600931_10 = "這麼好的天氣真想找個地方睡午覺啊。",
  str_voice_1600931_11 = "要是有什麼有趣的事情發生了再來叫我，我可不喜歡浪費時間在雞毛蒜皮的小事上。",
  str_voice_1600931_12 = "我對你這十七年間是如何度過的有點好奇，有空就說給我聽聽吧。",
  str_voice_1600931_13 = "你們這裡沒有酒嗎？想喝到配給之外的酒水，就只能跑一趟影鎮了啊……",
  str_voice_1600931_14 = "我不在乎其他人對我的想法，只要過得開心就好了。",
  str_voice_1600931_15 = "生日快樂啊年輕人，怎麼樣，這充滿人情味的祝福？",
  str_voice_1600931_16 = "有人找我就說我在忙，再見。",
  str_voice_1600931_17 = "早啊年輕人，我回去繼續睡了。",
  str_voice_1600931_18 = "和平的一天接近尾聲了，可喜可賀。",
  str_voice_1600931_19 = "喔？想不到你還挺勤奮的。",
  str_voice_1600931_20 = "啟光固然強大，但有些過於死板。不過，只要不對我的研究造成影響就沒問題。",
  str_voice_1600931_21 = "影鎮是個魚龍混雜的地方，不過靠個人實力也能活下來。",
  str_voice_1600931_22 = "為了啟明之光。",
  str_voice_1600931_23 = "悲哀卻也有趣的造物，我對他們的進化軌跡很感興趣。",
  str_voice_1600931_24 = "你不覺得卡戎是個十足幽默的傢伙嗎？前提是你得跟他很熟。",
  str_voice_1600931_25 = "涅墨西斯真是個可愛的孩子，很有調戲的價值。",
  str_voice_1600931_26 = "萬物都有其價值，而我正是研究其價值的存在。",
  str_voice_1600931_27 = "我覺得啟光已經很死板了，但好像白夜城更勝一籌。",
  str_voice_1600931_28 = "我現在稱他為古董沒什麼問題吧？這可是所有科學家都想要研究的東西。",
  str_voice_1600931_29 = "沒想到真的能見到空裔族的人，這可真是變得有趣起來了呢。",
  str_voice_1600931_30 = "能力變強總歸不是壞事。",
  str_voice_1600931_31 = "向著更大的目標前進吧。",
  str_voice_1600931_32 = "這一切都是值得的。",
  str_voice_1600931_33 = "我將知曉一切。",
  str_voice_1600931_34 = "就聽你的吧。",
  str_voice_1600931_35 = "準備好了嗎？",
  str_voice_1600931_36 = "將它刻在記憶中吧。",
  str_voice_1600931_37 = "塵歸塵，土歸土。",
  str_voice_1600931_38 = "見證萬物的終結吧。",
  str_voice_1600931_39 = "利刃穿喉！",
  str_voice_1600931_40 = "放棄掙扎吧。",
  str_voice_1600931_41 = "運動時間到了。",
  str_voice_1600931_42 = "看來回去得好好休息一下。",
  str_voice_1600931_43 = "偶爾也會這樣，沒什麼。",
  str_voice_1600931_44 = "對我的研究有興趣嗎？",
  str_voice_1600931_45 = "還不錯。",
  str_voice_1600931_46 = "你還滿細心的。",
  str_voice_1600931_47 = "你很有想法嘛。",
  str_voice_1600931_48 = "這對我很有幫助，謝了。",
  str_voice_1600931_49 = "這個世界有太多無法解釋的事物，而研究它們便是我永恆的課題。",
  str_voice_1600931_50 = "9號地下城的事故依舊令我心有餘悸，我至今都難以甩開與潛庭之脊融合時，它為我帶來的虛無感。",
  str_voice_1600931_51 = "人就應該及時行樂。話雖這麼說，但我還是放不下迦南城。不過我的眼線隨時監視著它的每一處，這也是我能夠悠閒自得的原因。",
  str_voice_1600931_52 = "白夜極光。",
  str_voice_1600931_53 = "你好啊。",
  str_voice_1600931_54 = "真是個不錯的早上。",
  str_voice_1600931_55 = "睡午覺的時間到了。",
  str_voice_1600931_56 = "是時候回到床上去了。",
  str_voice_1600931_57 = "新年快樂，好好享受這個日子吧。",
  str_voice_1600961_1 = "這些衣服都是經過防水處理的，不用擔心被能力波及，唯一麻煩的可能就是頭髮了。",
  str_voice_1600961_2 = "沒錢了，要不要去找涉小姐借一點……但她總是靠在桌子的一側，光看就很難受。",
  str_voice_1600961_3 = "影鎮的生活真的好辛苦，有點懷念啟光的家了。",
  str_voice_1600961_4 = "我必須找到加百列，問清楚有關我祖父的事情……",
  str_voice_1600961_5 = "最近我覺得自己能夠更加熟練地使用渾冥之水了，控制能力的平衡真是件困難的事……",
  str_voice_1600961_6 = "我應該學會對抗這份能力帶來的副作用，但沒人知曉它的原理，我只能任由混亂侵蝕自己的心智。",
  str_voice_1600961_7 = "你是個真誠的孩子，我能感覺得到。",
  str_voice_1600961_8 = "有機會的話，我請你喝一杯咖啡吧……你應該不太喜歡苦的吧？我特別準備了白砂糖……",
  str_voice_1600961_9 = "你有過那種感覺嗎？那種……被邪惡逐漸侵佔自我的感覺，我覺得自己浪費了太多時間在無謂的事情上，我應該更有效率地運用這份能力……不，沒什麼。",
  str_voice_1600961_10 = "好想找個地方休息一下啊。",
  str_voice_1600961_11 = "我來嗎？我可能會搞砸某些事情，你最好再考慮一下……",
  str_voice_1600961_12 = "我把房間改造成了對稱結構，這下子住起來就舒服多了。",
  str_voice_1600961_13 = "沒想到巨像有這麼大的空間，我擔心自己能不能記得住路……",
  str_voice_1600961_14 = "我能養隻貓嗎？我會好好照顧牠的，可以嗎？",
  str_voice_1600961_15 = "生日快樂，希望你明年也繼續加油。",
  str_voice_1600961_16 = "工作的時間到了，我來看看有沒有委託……",
  str_voice_1600961_17 = "早安，你起得很早呢。",
  str_voice_1600961_18 = "娛樂時間，有什麼預定行程嗎？",
  str_voice_1600961_19 = "熬夜是不好的，早點睡吧……",
  str_voice_1600961_20 = "雖然我不喜歡影鎮，但也沒辦法，我只能經由這裡前往白夜城。",
  str_voice_1600961_21 = "啟光是個很好的地方，大家都向著同一個目標努力的樣子很棒……",
  str_voice_1600961_22 = "渾冥之水與我同在。",
  str_voice_1600961_23 = "為什麼這個世界上會存在這種東西……",
  str_voice_1600961_24 = "艾蕾雅妹妹是個成熟的孩子，她真的很厲害，我也想盡可能地幫助她。",
  str_voice_1600961_25 = "沒有涉小姐的話，我可能無法好好在影鎮生活吧。",
  str_voice_1600961_26 = "貓咪很可愛，特別是黑貓！我好喜歡牠們的眼睛……",
  str_voice_1600961_27 = "我剛到影鎮的時候遇到了很多欺騙我的壞人，我不想再見到他們了。",
  str_voice_1600961_28 = "有了這個……我就可以隨意進出白夜城了吧……",
  str_voice_1600961_29 = "你好，請問你認識加百列嗎？就是住在白夜城的那個……",
  str_voice_1600961_30 = "冥水的力量變強了。",
  str_voice_1600961_31 = "混亂的種子開始發芽了。",
  str_voice_1600961_32 = "我的視線更加渾濁了。",
  str_voice_1600961_33 = "這難以抑制的衝動……",
  str_voice_1600961_34 = "我盡力……",
  str_voice_1600961_35 = "隨時準備著。",
  str_voice_1600961_36 = "不要用力過猛……",
  str_voice_1600961_37 = "淹沒吧。",
  str_voice_1600961_38 = "沉入深淵吧。",
  str_voice_1600961_39 = "我來幫忙。",
  str_voice_1600961_40 = "希望這有用處。",
  str_voice_1600961_41 = "我真的不太適合當隊長……",
  str_voice_1600961_42 = "呼……比想像中輕鬆。",
  str_voice_1600961_43 = "別太氣餒，好嗎？",
  str_voice_1600961_44 = "有什麼事嗎？我想先休息一會……",
  str_voice_1600961_45 = "啊，謝謝。",
  str_voice_1600961_46 = "這個是……謝謝你。",
  str_voice_1600961_47 = "謝謝，我很開心。",
  str_voice_1600961_48 = "你怎麼知道我喜歡這個……",
  str_voice_1600961_49 = "我很仰慕自己的祖父，所以我想知道他為什麼要離家去幫助一個叫加百列的人……",
  str_voice_1600961_50 = "剛來影鎮的時候真的是很辛苦，還被騙光了錢財。要不是遇到了涉小姐，真不知道會變成什麼樣子……",
  str_voice_1600961_51 = "我得變得更加強大才行……只有這樣才能順利地控制這種能力，也能夠避免它再次吞噬我的理智。",
  str_voice_1600961_52 = "嗯？白夜……極光？",
  str_voice_1600961_53 = "你好。",
  str_voice_1600961_54 = "真是個不錯的早上。",
  str_voice_1600961_55 = "你需要午休嗎？",
  str_voice_1600961_56 = "要記得早點睡覺。",
  str_voice_1600961_57 = "新年快樂……",
  str_voice_1401021_1 = "嗯？有事嗎？沒事的話讓我一個人待著吧。",
  str_voice_1401021_2 = "巨像這種能自由飛在天上的大傢伙並不少見，那個浮在天上的島不也是嗎？不過想上去得坐空艇。",
  str_voice_1401021_3 = "我不太喜歡和別人接觸，煩人的傢伙太多了……話說，我為什麼突然提起了這個話題？",
  str_voice_1401021_4 = "一個人的時候，連思考時間都變多了，我可以想很多平時不會去想的事情。",
  str_voice_1401021_5 = "你有思考過這份能力的意義嗎？我偶爾會想，我們擁有的這一切，比起恩賜……更像是種詛咒。",
  str_voice_1401021_6 = "四處打架的生活也沒有想像中那麼有意思，可能我原本也不是這麼好動的孩子吧……直到那一天為止。",
  str_voice_1401021_7 = "你是個還算不錯的傢伙，我開始對空裔感到好奇了，但是其他人就……啊，我沒有別的意思，你別介意。",
  str_voice_1401021_8 = "我這一輩子也沒什麼特別的人生感觸，沒啥建議能給你……總之，你要多為自己著想一點。",
  str_voice_1401021_9 = "我的朋友雖然不多，但是我們都十分瞭解彼此，這才是我想要的。",
  str_voice_1401021_10 = "呼……真閒啊……",
  str_voice_1401021_11 = "好吧，雖然不知道該做什麼，總之做就是了。",
  str_voice_1401021_12 = "我正準備去休息呢，有事的話待會再說吧。",
  str_voice_1401021_13 = "這大傢伙……叫臨空者是嗎？真想跟他對話看看。",
  str_voice_1401021_14 = "這裡可比我生活的地方要安靜多了，有點不習慣。",
  str_voice_1401021_15 = "生日快樂，我沒準備什麼。有心意就夠了，對嗎？",
  str_voice_1401021_16 = "嗯？你來了啊，這裡到目前為止還沒什麼情況，真輕鬆。",
  str_voice_1401021_17 = "你可真是勤奮，不過也要記得在工作和休息間取得平衡。",
  str_voice_1401021_18 = "休息一下吧，已經到下班時間了。",
  str_voice_1401021_19 = "你想拖垮自己的身體嗎？我倒是不會攔著你……",
  str_voice_1401021_20 = "影鎮雖然亂七八糟，卻也滿適合我們這些獨行者生存的。",
  str_voice_1401021_21 = "我不喜歡貴族的作風，但白夜城也有屬於他們的溫暖。",
  str_voice_1401021_22 = "影子在注視著……一切。",
  str_voice_1401021_23 = "想必牠們也不懂為什麼要與我們為敵吧。",
  str_voice_1401021_24 = "烈雀啊……我行我素的傢伙，就連她對知更的那份保護慾也是如此。",
  str_voice_1401021_25 = "我該說話的時候還是會說的，知更可不太一樣，她總是沉默。",
  str_voice_1401021_26 = "喜歡什麼？看不見我嘴裡這些糖嗎？各種口味我都喜歡。",
  str_voice_1401021_27 = "我不喜歡場面話，不喜歡表面功夫，所以我討厭白夜城的某些貴族。",
  str_voice_1401021_28 = "我還以為巨像只是傳說。畢竟我又沒見過這種東西。",
  str_voice_1401021_29 = "名字，泰莎。先說好，合作固然重要，但我還是希望我們各做各的事。",
  str_voice_1401021_30 = "感覺還不錯。",
  str_voice_1401021_31 = "這力量還真難控制。",
  str_voice_1401021_32 = "我的力量要是爆發了會很不妙吧？",
  str_voice_1401021_33 = "雷電都快從我手裡蹦出來了，哈。",
  str_voice_1401021_34 = "沒辦法。",
  str_voice_1401021_35 = "迅如閃電。",
  str_voice_1401021_36 = "來試試吧。",
  str_voice_1401021_37 = "這可能會有點痛喔。",
  str_voice_1401021_38 = "電解！",
  str_voice_1401021_39 = "太弱了。",
  str_voice_1401021_40 = "交給我吧。",
  str_voice_1401021_41 = "隨便打打就好了吧。",
  str_voice_1401021_42 = "好吧，還算熱血。",
  str_voice_1401021_43 = "這下可有趣了。",
  str_voice_1401021_44 = "過來幹嘛？要嚐嚐電流的滋味嗎？",
  str_voice_1401021_45 = "東西不錯，我收下了。",
  str_voice_1401021_46 = "沒想到你還滿瞭解我的。",
  str_voice_1401021_47 = "這份心意我記下了。",
  str_voice_1401021_48 = "原來你知道我喜歡這個啊。",
  str_voice_1401021_49 = "我以前從沒想過用自己的能力來消滅任何人，更別說是白夜城的人。說實話，我並不明白當時理察口中所謂的「仇恨」是什麼。",
  str_voice_1401021_50 = "多數人認為我痛恨白夜城，但實際上並非如此。我的仇恨是針對撫養過我的理察，但他從未讓仇恨影響過我。",
  str_voice_1401021_51 = "的確，我需要這股力量來保護自己。但是看著日漸強大的能力，卻又讓我有種難以言喻的空虛。這一切是否會有盡頭呢？",
  str_voice_1401021_52 = "白夜極光。",
  str_voice_1401021_53 = "唷。",
  str_voice_1401021_54 = "早。",
  str_voice_1401021_55 = "你有午休的習慣嗎？",
  str_voice_1401021_56 = "晚安，祝你有個好夢。",
  str_voice_1401021_57 = "新年快樂，希望所有人都有所成長吧。",
  str_voice_1500711_1 = "朋友？你認為我需要那種東西？不過童年時確實有過一個來著……",
  str_voice_1500711_2 = "委託當然要收費。價錢？看是什麼內容了。",
  str_voice_1500711_3 = "你可不要把萬事屋想得太輕鬆……總是要接待一些奇怪的人，比如帶著狗的傢伙和帶著觸手的傢伙。",
  str_voice_1500711_4 = "我的力量確實在變強，但我距離這條項鍊的祕密仍然很遙遠。",
  str_voice_1500711_5 = "萬事屋裡沒有什麼拯救世界的夥伴。省省吧，別找了。",
  str_voice_1500711_6 = "這世上天生就沒有平等可言，只要有人的地方就沒有平等。",
  str_voice_1500711_7 = "你這小子還真是個怪傢伙，但我不討厭。",
  str_voice_1500711_8 = "你這小子和遠東那些臭小鬼完全不一樣。怎麼？我難得誇你一次，就老老實實接受吧。",
  str_voice_1500711_9 = "在影鎮可沒什麼人願意和他人深交，大家都被某種東西絆住了手腳，已經很難考慮生存以外的事情了。",
  str_voice_1500711_10 = "你這小子到底是很閒還是很忙呢？",
  str_voice_1500711_11 = "看場子是吧？懂了，反正萬事屋就是什麼都做。",
  str_voice_1500711_12 = "夠了。看夠了嗎。還是你想試試這個？",
  str_voice_1500711_13 = "有這種時間，不如去忙你自己的事情。",
  str_voice_1500711_14 = "我得快點找出這條項鍊裡的祕密。",
  str_voice_1500711_15 = "生日？你可以委託我喊出那幾個字，這次算你免費。",
  str_voice_1500711_16 = "很有精神啊小子，幫我處理一點業務如何？報酬肯定少不了你的。",
  str_voice_1500711_17 = "小子，你打算睡到什麼時候？要是在萬事屋我早就出去賺錢了。",
  str_voice_1500711_18 = "走，跟我喝一杯去，我請客，你喝果汁也行，我不在乎。",
  str_voice_1500711_19 = "很有魄力啊小子，這麼晚了還在努力，來喝一杯怎麼樣？",
  str_voice_1500711_20 = "影鎮是網羅情報的好地方，也沒人會對著他人廢話連篇，我喜歡。",
  str_voice_1500711_21 = "等我找到項鍊的祕密後就去紅油扳手吧，我還挺中意那群傢伙的。",
  str_voice_1500711_22 = "影子在注視著你。",
  str_voice_1500711_23 = "毫無內在的雜碎，沒有任何價值。",
  str_voice_1500711_24 = "伊斯塔萬可太懂得管理影鎮了，有他在，這裡還算太平。",
  str_voice_1500711_25 = "也不知道那個粉紅色頭髮的小女孩怎麼樣了。算了，還是別想了。",
  str_voice_1500711_26 = "我這輩子有酒喝就足夠了。",
  str_voice_1500711_27 = "曾經這裡還有幾個打工的，我嫌他們太沒用就開除了。",
  str_voice_1500711_28 = "這傢伙太大了，認個路都麻煩，而且相同的房間有點太多了。",
  str_voice_1500711_29 = "是有事想委託嗎，小子？最好別是什麼雞毛蒜皮的小事情，萬事屋一天能做的事情有限，我得做點取捨。",
  str_voice_1500711_30 = "還不錯。",
  str_voice_1500711_31 = "哼，也就這樣吧。",
  str_voice_1500711_32 = "項鍊的祕密……更近了。",
  str_voice_1500711_33 = "這種熱血沸騰的感受……久違了。",
  str_voice_1500711_34 = "喔？要上了？",
  str_voice_1500711_35 = "是時候了。",
  str_voice_1500711_36 = "看好了！",
  str_voice_1500711_37 = "燒光他們！",
  str_voice_1500711_38 = "燃盡一切！",
  str_voice_1500711_39 = "結束了。",
  str_voice_1500711_40 = "太慢了！",
  str_voice_1500711_41 = "我可不習慣帶隊。",
  str_voice_1500711_42 = "沒什麼難度。",
  str_voice_1500711_43 = "失敗？家常便飯罷了。",
  str_voice_1500711_44 = "有事就說吧，不要吞吞吐吐的。",
  str_voice_1500711_45 = "這是要賄賂我嗎？",
  str_voice_1500711_46 = "你還挺有眼光的。",
  str_voice_1500711_47 = "我收下了，謝謝。",
  str_voice_1500711_48 = "這是……！謝了小子。",
  str_voice_1500711_49 = "這世界對異於常人者的態度可沒那麼友好，有些人甚至只因為長相就會被其他人惡言相向，不過在影鎮還是好很多。",
  str_voice_1500711_50 = "直到今天，身在遠東時的記憶也恍如昨日，我腦海中依舊迴響著師父的教誨，以及一個……不知為何讓我非常在意，留著一頭粉色頭髮的小女孩。",
  str_voice_1500711_51 = "這項鍊……自我懂事以來便帶在身上，不但是我雙親的遺產，同時也是我力量的來源，裡面的祕密太多了，但我對此卻一無所知。",
  str_voice_1500711_52 = "白夜極光。",
  str_voice_1500711_53 = "唷。",
  str_voice_1500711_54 = "挺早的啊，小子。",
  str_voice_1500711_55 = "一到正午就想睡。",
  str_voice_1500711_56 = "睡吧小子，別熬夜。",
  str_voice_1500711_57 = "新年快樂，小子，這折扣券就送你了。",
  str_voice_1500971_1 = "治病救人？那是很久以前的事了……更何況，有些東西不值得救治。",
  str_voice_1500971_2 = "冰雪的柳葉刀，因為寒冷，刺進身體裡時就不會太痛苦。想嘗試一下嗎？",
  str_voice_1500971_3 = "我執行過什麼任務？很多。如果你想知道，我可以拿你示範一下。",
  str_voice_1500971_4 = "手術的訣竅？就是精準地切除。",
  str_voice_1500971_5 = "影鎮的黑暗消退之後，我也許還會回去當醫生吧。但在那之前，我要執刀的是另一台手術，一台為了影鎮的手術。",
  str_voice_1500971_6 = "我曾經的願望，是執柳葉刀救下更多的人。現在，我希望自己成為影鎮的柳葉刀，為這裡切除壞死的部分。",
  str_voice_1500971_7 = "空裔？有趣，能讓我研究一下你的身體嗎？我想知道，空裔的致命部位和普通光靈有沒有不同……哈哈，開玩笑的。",
  str_voice_1500971_8 = "需要動手術的話可以找我。雖然我現在不是醫生了，但技術反而更精湛了。為什麼？祕密。",
  str_voice_1500971_9 = "見過的病人愈多，就愈瞭解人的生命是如此脆弱，因此，就更瞭解如何救治他們，或是如何送走他們。",
  str_voice_1500971_10 = "閒來無事，學一些新知識如何？胸椎第七節在什麼位置，你想知道嗎？",
  str_voice_1500971_11 = "需要我的幫助嗎？可以。但先說好，我可是為了影主才做的。",
  str_voice_1500971_12 = "心臟手術嗎……起死回生可沒那麼容易啊。",
  str_voice_1500971_13 = "救人和殺人並不衝突，只是踐行信念的不同形式罷了。",
  str_voice_1500971_14 = "從最合適的角度下刀……喔，別在意，大動脈很脆弱，怎麼切都可以。",
  str_voice_1500971_15 = "生日快樂，導航員，準備許什麼生日願望呢？",
  str_voice_1500971_16 = "看起來很有精神嘛，記得勤洗手，以防生病。",
  str_voice_1500971_17 = "早起有利於身體健康。對空裔來說也是一樣吧。",
  str_voice_1500971_18 = "到晚餐時間了，不要餓著肚子做事，對身體不好。",
  str_voice_1500971_19 = "還在工作嗎？熬夜會增加心肌梗塞的機率，快去休息。",
  str_voice_1500971_20 = "影鎮上滿溢著活力與瘋狂，因此才需要特殊的手術。",
  str_voice_1500971_21 = "在白夜城當醫生，也許很不錯。不過可能有點悶吧。",
  str_voice_1500971_22 = "影子在注視著你。",
  str_voice_1500971_23 = "我曾相信所有東西都是有救的。但是，暗鬼例外。",
  str_voice_1500971_24 = "如果他能想到打架以外的手段……那他就不是塞留古了。",
  str_voice_1500971_25 = "影主給了我新的生活方式，給了我新的患者。",
  str_voice_1500971_26 = "壁爐的火光，總能讓人安定下來。長夜之中看到這樣的火，是一種慰藉吧。",
  str_voice_1500971_27 = "傷口、化膿、出血。治不好的話就直接燒了吧。我可是認真的。",
  str_voice_1500971_28 = "你的巨像看起來有很多陳舊的傷口，什麼時候要清潔？我來幫忙。",
  str_voice_1500971_29 = "找我來做什麼？我確實是個會動手術的醫生，但現在換了個職業……主要負責暗殺。",
  str_voice_1500971_30 = "或許我該切點什麼了。",
  str_voice_1500971_31 = "手術的能力，還得繼續磨練。",
  str_voice_1500971_32 = "這柳葉刀比過去更加鋒利。",
  str_voice_1500971_33 = "醫生的職責，我從未忘記過。",
  str_voice_1500971_34 = "患者是哪位？",
  str_voice_1500971_35 = "手術準備。",
  str_voice_1500971_36 = "患者請放鬆。",
  str_voice_1500971_37 = "藥到病除！",
  str_voice_1500971_38 = "清除頑疾！",
  str_voice_1500971_39 = "冰刃，凍結吧。",
  str_voice_1500971_40 = "接下來想要我切哪裡？",
  str_voice_1500971_41 = "好吧，這一次由我主刀。",
  str_voice_1500971_42 = "手術十分順利。",
  str_voice_1500971_43 = "頑疾要慢治，現在似乎不是時候。",
  str_voice_1500971_44 = "我在看哪裡？當然是看你的心臟了。",
  str_voice_1500971_45 = "喔，謝謝。",
  str_voice_1500971_46 = "喔？十分感謝。",
  str_voice_1500971_47 = "看起來不錯，我收下了。",
  str_voice_1500971_48 = "謝謝，我會珍惜它的。",
  str_voice_1500971_49 = "暗鬼留下的傷口有時很難處理。在白夜城學醫時，我花了很多力氣在這個難題上，還好我做得不錯。",
  str_voice_1500971_50 = "我的柳葉刀救過很多人，但唯獨沒有救下我的父母。暗鬼不吃這套，我只好換成了其他刀。",
  str_voice_1500971_51 = "影鎮的頑疾不是用普通的方式可以根治的。需要盡可能地切除、包紮，等待新的希望萌發。在那之前，我會一直做好我的工作。",
  str_voice_1500971_52 = "白夜極光。",
  str_voice_1500971_53 = "唷。",
  str_voice_1500971_54 = "早。",
  str_voice_1500971_55 = "唷，導航員。",
  str_voice_1500971_56 = "晚安，還沒睡嗎？",
  str_voice_1500971_57 = "新年快樂，導航員。",
  str_voice_1500241_1 = "-空裔是什麼啊？\n-是不同於光靈的另一個種族。",
  str_voice_1500241_2 = "-空裔打架很強嗎？\n-我想答案是否定的。",
  str_voice_1500241_3 = "-你聽好，這條線的這一邊是我的地盤！\n-蠢不蠢啊。",
  str_voice_1500241_4 = "-距離你成為我手下敗將的日子越來越近了。\n-又不是只有你一個人在成長，呆子。",
  str_voice_1500241_5 = "-說實話我對晉升興趣不大，只要能打架就行。\n-多為自己的未來著想一下吧。",
  str_voice_1500241_6 = "-哈哈哈哈哈，我是最強的！\n-那我就是超級最強了。",
  str_voice_1500241_7 = "-雖然你不會打架，但人還是不錯的。\n-你不用把她的話放在心上。",
  str_voice_1500241_8 = "-決勝負的時候到了，黑！\n-那就讓空裔來見證你敗北吧。",
  str_voice_1500241_9 = "-好閒啊……好無聊啊……就沒什麼事情做嗎？！\n-別在床上滾來滾去的，像個傻子一樣。",
  str_voice_1500241_10 = "-太無聊了！\n-稍微安靜一下。",
  str_voice_1500241_11 = "-有架要打？！\n-只是普通的執勤。",
  str_voice_1500241_12 = "-別亂用我的東西。\n-有什麼關係，妳也可以用我的啊。",
  str_voice_1500241_13 = "-喂，你覺得我們兩個誰比較強？\n-別隨便波及無關人員。",
  str_voice_1500241_14 = "-有時候我會覺得能在巨像上生活過於奢侈了。\n-妳又來了。",
  str_voice_1500241_15 = "-生日快樂！\n-喂，是我先說的！\n-隨便妳。",
  str_voice_1500241_16 = "你白天通常都在做什麼呢，順帶一提我剛剛自行訓練完畢。",
  str_voice_1500241_17 = "你還滿早的，至少比某個呆子要早得多了。",
  str_voice_1500241_18 = "-一到晚上就嗨起來了呢！\n-夜貓子真是讓人沒轍。",
  str_voice_1500241_19 = "良好的睡眠是維持身體健康的條件之一，因此你最好去睡覺。",
  str_voice_1500241_20 = "-你問我對啟光的感覺？沒什麼感覺，我又不瞭解。\n-團結統一，是啟光的特色。",
  str_voice_1500241_21 = "-比起白夜城我還是喜歡影鎮，至少沒那麼多表面功夫。\n-我們難得意見一致。",
  str_voice_1500241_22 = "為了啟明之光！",
  str_voice_1500241_23 = "-也不知道從哪冒出來的。\n-為何牠們會如此針對光靈？我想不通。",
  str_voice_1500241_24 = "-巴頓將軍是個十分豪爽的人。\n-我也想成為他那個樣子！",
  str_voice_1500241_25 = "-白矮星？無聊的傢伙。\n-每個人的個性都不一樣。",
  str_voice_1500241_26 = "-我喜歡打架，喜歡勝利！\n-我同意後者。",
  str_voice_1500241_27 = "-耍小手段的懦夫！\n-他們的尊嚴一文不值。",
  str_voice_1500241_28 = "-好大的傢伙，一定很強吧！\n-親眼目睹時代的遺產真讓我震驚。",
  str_voice_1500241_29 = "-你好，很高興見到你。\n-把你們這個地方最強的人叫出來！",
  str_voice_1500241_30 = "很好，給我打起精神！",
  str_voice_1500241_31 = "我變得更強了！",
  str_voice_1500241_32 = "十分合理的決定。",
  str_voice_1500241_33 = "-完美！\n-超級完美。",
  str_voice_1500241_34 = "收到！",
  str_voice_1500241_35 = "大鬧一場吧！",
  str_voice_1500241_36 = "請務必看準時機。",
  str_voice_1500241_37 = "給我咬緊牙關！",
  str_voice_1500241_38 = "-是時候了。\n-來了！",
  str_voice_1500241_39 = "爆炸！",
  str_voice_1500241_40 = "哈哈哈哈哈！",
  str_voice_1500241_41 = "-隊長是我的！\n-妳給我老實點。",
  str_voice_1500241_42 = "-小菜一碟！\n-任務完成。",
  str_voice_1500241_43 = "-氣死我了！\n-沒死就算幸運了。",
  str_voice_1500241_44 = "-嗯？你找我？還是找這傢伙？\n-有什麼事嗎？",
  str_voice_1500241_45 = "感謝你的心意，導航員。",
  str_voice_1500241_46 = "就是這個！你很懂嘛！",
  str_voice_1500241_47 = "還不錯啦，我就收下吧。",
  str_voice_1500241_48 = "我會珍惜的，謝謝。",
  str_voice_1500241_49 = "-哎呀，我突然開始懷念剛加入啟光那時候的事情了。\n-那時候妳比現在難管教多了。\n-妳說什麼？！",
  str_voice_1500241_50 = "-最近決鬥的平局越來越多，照這個情勢下去，我戰勝妳也只是早晚的事情了！\n-夢話留到夢裡再說。",
  str_voice_1500241_51 = "-妳戰鬥起來經常察覺不到自身周邊的危險，這很致命。\n-囉嗦！我在只有自己一個人的時候就會注意了！",
  str_voice_1500241_52 = "白夜極光！",
  str_voice_1500241_53 = "你好呀！",
  str_voice_1500241_54 = "早安，你今天也很有精神呢。",
  str_voice_1500241_55 = "吃完午飯好想睡覺！",
  str_voice_1500241_56 = "到了優秀士兵入睡的時候了。",
  str_voice_1500241_57 = "-新年快樂！\n-新的一年多指教。\n-別搶我的台詞！",
  str_voice_1601031_1 = "快看！這個可愛的沙漏，是我親手做的，怎麼樣？……我可不是只會審訊犯人的，有這麼意外嗎？",
  str_voice_1601031_2 = "你想看眼罩下面的那隻眼睛？第一次有人提出這種請求……你認真的嗎？",
  str_voice_1601031_3 = "要知道，讓別人哭泣這種事我可是超擅長的——當然是說處刑，你想到哪裡去了？",
  str_voice_1601031_4 = "常有人說我觀念不正，那什麼才是正確的？善和惡就那麼重要嗎？只要我開心不就好了。",
  str_voice_1601031_5 = "……還以為巨像是很有意思的地方，但似乎有點無趣呢？你這裡沒有需要處刑的人嗎？",
  str_voice_1601031_6 = "我的右眼可以讓你直視地獄——我的體術也可以。",
  str_voice_1601031_7 = "呵呵，你這樣接近我，似乎不知道我很危險呢……",
  str_voice_1601031_8 = "折磨人確實是我的愛好，不過你放心……對你，我還是會很溫柔的，暫時。",
  str_voice_1601031_9 = "看你一直很好奇……就給你看看我的手杖吧，但小心不要隨便亂摸——只有你，我不希望讓詛咒沾染。",
  str_voice_1601031_10 = "理智就要流逝了，我能感覺到。",
  str_voice_1601031_11 = "非要我來嘛……不過既然是你拜託我，那你就站遠一點吧，我要摘下眼罩了。",
  str_voice_1601031_12 = "你知道我想問你什麼的……維多利亞姐姐在嗎？",
  str_voice_1601031_13 = "我確實很喜歡鮮血，但這不能代表我不需要乾淨整潔的房間啊。",
  str_voice_1601031_14 = "真想聽聽你在審訊室裡發出的叫喊聲——當然這是不行的，對吧。",
  str_voice_1601031_15 = "生日禮物嗎？不如……帶你參觀一下我的審訊室？",
  str_voice_1601031_16 = "你回來啦……嗯？我接下來打算做什麼？當然是繼續審訊室的工作啦。",
  str_voice_1601031_17 = "一大早就聽到審訊室裡動聽的尖叫……真美妙。",
  str_voice_1601031_18 = "雖然還想繼續工作，不過維多利亞姐姐說適度休息也是必要的。",
  str_voice_1601031_19 = "深夜審問總會有意外的發現呢……嗯？你也還沒睡？",
  str_voice_1601031_20 = "真理……我並不是太感興趣呢，但維多利亞姐姐的目的就是我的目的。",
  str_voice_1601031_21 = "就算是白夜城的那些傢伙，面對我的右眼，也一樣會痛苦呻吟。",
  str_voice_1601031_22 = "願真理祝福你啦。",
  str_voice_1601031_23 = "連審判都不值得的傢伙們，直接處刑就好了。",
  str_voice_1601031_24 = "維多利亞姐姐太過溫柔了。不過沒關係，殘忍的事我來做就可以了～",
  str_voice_1601031_25 = "真應該讓那個總是徘徊在維多利亞姐姐身邊的傢伙嚐嚐災厄的滋味……",
  str_voice_1601031_26 = "鮮血、尖叫、痛苦扭曲的表情……太美妙了！",
  str_voice_1601031_27 = "為什麼總有人來管教我？我只要維多利亞姐姐就夠了。",
  str_voice_1601031_28 = "這麼多房間……那應該可以分我一間當作審訊室吧？",
  str_voice_1601031_29 = "真麻煩啊……我是艾希，通常我只有在審問的時候才會報出名字，不過維多利亞姐姐說過自我介紹是基本的禮貌……",
  str_voice_1601031_30 = "呵——就這樣？",
  str_voice_1601031_31 = "直視內心的恐懼吧！",
  str_voice_1601031_32 = "空虛之瞳在凝視你。",
  str_voice_1601031_33 = "來感受深淵吧！",
  str_voice_1601031_34 = "尖叫和鮮血……",
  str_voice_1601031_35 = "空虛之瞳——",
  str_voice_1601031_36 = "要開始審訊了嗎？",
  str_voice_1601031_37 = "——直視災厄吧！",
  str_voice_1601031_38 = "任何人都逃不掉——！",
  str_voice_1601031_39 = "痛苦吧！哭嚎吧！",
  str_voice_1601031_40 = "顫慄吧！",
  str_voice_1601031_41 = "讓我來帶隊？那他們死定了——",
  str_voice_1601031_42 = "嚐嚐恐懼的滋味吧！",
  str_voice_1601031_43 = "對不起，維多利亞姐姐……",
  str_voice_1601031_44 = "噓～看著我的眼睛，說說你都做了些什麼？",
  str_voice_1601031_45 = "你似乎不是很瞭解我呢。",
  str_voice_1601031_46 = "……你是怎麼知道我喜歡這個的！",
  str_voice_1601031_47 = "你居然能想到這一點，有點出乎我意料了……",
  str_voice_1601031_48 = "除了維多利亞姐姐，沒想到還有這麼瞭解我的人呢！",
  str_voice_1601031_49 = "我擁有被詛咒的血脈……在直視「空虛之瞳」之後，沒有人能免於陷入恐懼和瘋狂，包括——我那因此而逝去的父母。",
  str_voice_1601031_50 = "眼罩是維多利亞姐姐為我製作的，這是抑制「空虛之瞳」內詛咒之力的道具……這件事，你還不知道吧？",
  str_voice_1601031_51 = "我不介意自己的能力，也不介意成為審問官和處刑人，畢竟鮮血和旁人的痛苦呻吟會讓我得到滿足……",
  str_voice_1601031_52 = "白夜極光。",
  str_voice_1601031_53 = "在幹嘛？",
  str_voice_1601031_54 = "我在審訊室的時候你一直在睡覺嗎？",
  str_voice_1601031_55 = "審訊工作可以促進食慾呢，要來嗎？",
  str_voice_1601031_56 = "今天就到這裡，晚安。",
  str_voice_1601031_57 = "新的一年，是不是意味著——我可以在巨像上擁有一間審訊室了？",
  str_voice_1500991_1 = "雖說背負著詛咒降生，但我也有好運，因為詛咒的存在，我天生能夠踏著荊棘前行……唔，因為我的能力跟荊棘有點關係嘛。",
  str_voice_1500991_2 = "我並不覺得魔劍重，這些黑色的刺會幫我分擔的……欸？怎麼分擔，就是那個，這個……我也不知道該怎麼解釋啦。",
  str_voice_1500991_3 = "魔劍有月亮的名諱，有奇怪的力量，我無法與它分離，所以大概我也一樣……奇怪。",
  str_voice_1500991_4 = "沒關係，我會在這股詛咒帶來的力量毀滅我之前，找到解開詛咒的方法。",
  str_voice_1500991_5 = "荊棘的刺是為了保護自己而存在的，這把滿是荊棘的魔劍也是如此嗎？為何與詛咒一同降臨，又為何……給我力量？",
  str_voice_1500991_6 = "為什麼而戰、為什麼而堅持、為什麼而踏上旅途，我常常如此問自己，但那個答案十分簡單，我只是想……生存下去。",
  str_voice_1500991_7 = "請不要觸碰這把魔劍，我不確定它會帶給您什麼麻煩……不管多麼好奇也不可以碰，我不想傷到您。",
  str_voice_1500991_8 = "雖然我想盡可能一個人行動，但能像這樣與他人產生聯繫……也很不錯。",
  str_voice_1500991_9 = "因為珍惜，才不敢靠近，希望您能夠理解……但我就在這邊，就在離您不遠的地方。",
  str_voice_1500991_10 = "十三、十四、十五……啊，我在數身上的刺。有時候我會像這樣打發時間，也能順便檢查一下這些刺的狀況。",
  str_voice_1500991_11 = "交給我吧，我什麼都能做……欸？只需要待在這裡就好了嗎？……比我以前的工作還輕鬆不少呢。",
  str_voice_1500991_12 = "要珍惜衣服，畢竟已經沒得換了……呀，這裡是什麼時候劃破的？",
  str_voice_1500991_13 = "因為詛咒的關係，我的身上會出現一些黑刺，希望它們不要再增加了。",
  str_voice_1500991_14 = "這把魔劍上的黑色棘刺可以折下來，反正還會長出新的，很不可思議吧？",
  str_voice_1500991_15 = "我不太知道如何幫別人慶生，是需要……唱歌和鼓掌嗎？",
  str_voice_1500991_16 = "現在是工作時間了，要解決誰？……欸？這話題有點可怕嗎？",
  str_voice_1500991_17 = "早安，今天的我也很健康，應該能夠充滿活力地工作，您呢？",
  str_voice_1500991_18 = "不要太擔心工作了，去休息一下吧，或許一切會自然而然地好起來。",
  str_voice_1500991_19 = "晚上的溫度會降低，您要小心別著涼了……啊，不用擔心我，我已經習慣了。",
  str_voice_1500991_20 = "影鎮很好，能夠讓我得到作為傭兵賺錢的機會。",
  str_voice_1500991_21 = "真理結社那邊或許有更多的情報，但是……怎麼看都很可疑。",
  str_voice_1500991_22 = "好像有什麼東西在注視著您？",
  str_voice_1500991_23 = "暗鬼奪走了許多生命，希望大家、我的父母……不會遇上牠們。",
  str_voice_1500991_24 = "即使是我這樣的人，克娜莉小姐仍然說，歡迎我去店裡喝咖啡……",
  str_voice_1500991_25 = "珍小姐推薦工作給我，也會教我如何看僱傭契約，我很感謝她。",
  str_voice_1500991_26 = "其實……我很喜歡小動物，但卻害怕自己會不小心傷害到牠們。",
  str_voice_1500991_27 = "我雖然討厭自己受到詛咒的身軀，但是卻無法討厭這把魔劍……",
  str_voice_1500991_28 = "感覺您和巨像的關係，就像我和這把魔劍一樣呢，彼此連結、相互共生。",
  str_voice_1500991_29 = "您要僱用我嗎？我能幫忙戰鬥，且所需報酬並不高……只要是這把魔劍能力所及之處，我可以幫您解決任何東西。",
  str_voice_1500991_30 = "詛咒的力量……更加強大了。",
  str_voice_1500991_31 = "我明白，我應該舉起劍。",
  str_voice_1500991_32 = "總有一日，結束一切。",
  str_voice_1500991_33 = "就算道路充滿荊棘，也沒關係。",
  str_voice_1500991_34 = "要……保持距離。",
  str_voice_1500991_35 = "準備好了。",
  str_voice_1500991_36 = "按照您的指示。",
  str_voice_1500991_37 = "魔劍啊，借給我力量。",
  str_voice_1500991_38 = "斬斷荊棘，開闢道路！",
  str_voice_1500991_39 = "荊棘之刺。",
  str_voice_1500991_40 = "綻放光芒。",
  str_voice_1500991_41 = "欸？由我來……帶隊？",
  str_voice_1500991_42 = "太好了，這次勝利了。",
  str_voice_1500991_43 = "稍微有點勉強了……抱歉……",
  str_voice_1500991_44 = "除了揮劍以外，其他的活動我有點……啊，不過只是聊天的話，沒有問題。",
  str_voice_1500991_45 = "那個……這不是用來抵扣報酬的吧？",
  str_voice_1500991_46 = "這是……禮物？我真的可以收下嗎？",
  str_voice_1500991_47 = "那個……請讓我想想如何感謝您……",
  str_voice_1500991_48 = "謝謝！能收到這樣貴重的禮物，我很開心。",
  str_voice_1500991_49 = "大概很久以前，我的家族中也出現過類似症狀的人吧，所以才會流傳下古老的文書，以及這把魔劍。",
  str_voice_1500991_50 = "以前臥病在床時，會有可愛的小動物來到房間裡和我玩。但有了魔劍之後，牠們便不再來了……",
  str_voice_1500991_51 = "我知道，我的雙親無法繼續陪在我身邊，是因為詛咒……但我們都在尋找解決的方法，總有一天我們會再見的。",
  str_voice_1500991_52 = "白夜、極光。",
  str_voice_1500991_53 = "您好。",
  str_voice_1500991_54 = "那個，您醒了嗎？",
  str_voice_1500991_55 = "您有時間嗎？",
  str_voice_1500991_56 = "請問會打擾您休息嗎？",
  str_voice_1500991_57 = "希望今年事事順利。",
  str_voice_1300941_1 = "巨像上的大家都很溫柔……就算我經常發呆，大家也不會介意呢……",
  str_voice_1300941_2 = "剪短髮的原因嗎……其實沒什麼特別的……只是，覺得短髮很方便……",
  str_voice_1300941_3 = "我本來就不太會說話……沒、沒有不想說話，也不是在生氣……",
  str_voice_1300941_4 = "不用害怕這些水汽……它會保護你的……",
  str_voice_1300941_5 = "「春日之杖」和春天，我、我都最喜歡了……你呢？",
  str_voice_1300941_7 = "你、你一直在這裡嗎？雖然很感謝你，但我想獨處一會……",
  str_voice_1300941_8 = "你……就算知道我不會感覺到冷，也總是關心我呢……真是溫柔的人……",
  str_voice_1300941_9 = "對……對不起！我剛剛是不是恍神了……因為和你在一起，所以稍微有點太放鬆了……",
  str_voice_1300941_10 = "我、我可以自己一個人待在這裡嗎？那麼，發呆的話也沒關係吧……",
  str_voice_1300941_11 = "讓……讓我來嘛？第……第一次面對這麼多人雖然會有點緊張……但我會努力……",
  str_voice_1300941_12 = "水……是可以保護我的溫柔存在，像我的父母一般……",
  str_voice_1300941_13 = "空氣真新鮮呢……不如和我一起坐在雪地上發呆吧……？",
  str_voice_1300941_14 = "我不冷，不用擔心我……不過，「冷」……是什麼感覺呢？",
  str_voice_1300941_15 = "生日快樂！春日的氣息會永遠與你同在……",
  str_voice_1300941_16 = "我、我已經準備要去巡邏了……剛剛……我可沒有在打瞌睡喔……",
  str_voice_1300941_17 = "……因為要巡邏，所以我每天都很早起……不過你也很早呢……",
  str_voice_1300941_18 = "應該……快到休息的時間了吧？",
  str_voice_1300941_19 = "我已經習慣了這樣的日子……但，你該休息了……",
  str_voice_1300941_20 = "有廣闊的雪地和溫暖的陽光……是讓人安心的地方……",
  str_voice_1300941_21 = "那座白色的城市上面……應該有「春天」的樣子吧？",
  str_voice_1300941_22 = "慕冬而生……",
  str_voice_1300941_23 = "……那些害我無辜父母死去的入侵者……我……無法原諒……",
  str_voice_1300941_24 = "小諾爾，我們經常會交流關於溫度的疑惑……很奇怪嗎？",
  str_voice_1300941_25 = "女王陛下給了我選擇的權利……因此我決定繼承父母的遺志……",
  str_voice_1300941_26 = "平和的春天……安靜的雪地……以及、可以讓我一個人發呆的地方……",
  str_voice_1300941_27 = "一、一定要說的話……吵鬧的地方……會讓我有點緊張……",
  str_voice_1300941_28 = "是和雪地一樣純白的地方……雖然有很多人，但我會努力適應……",
  str_voice_1300941_29 = "我叫莉亞，是北境的巡邏員……啊……初次見面的時候該說什麼好呢……",
  str_voice_1300941_30 = "這是……力量？",
  str_voice_1300941_31 = "「春天」……是這樣的感覺嗎？",
  str_voice_1300941_32 = "這樣就更能好好保護大家……",
  str_voice_1300941_34 = "……有點緊張",
  str_voice_1300941_35 = "春日——待命！",
  str_voice_1300941_36 = "水汽準備好了……",
  str_voice_1300941_37 = "春日——之息！",
  str_voice_1300941_38 = "感受這溫柔的力量吧……！",
  str_voice_1300941_39 = "水蒸氣……蔓延！",
  str_voice_1300941_40 = "水汽……蒸發！",
  str_voice_1300941_41 = "我……我可以嗎？",
  str_voice_1300941_42 = "我……做到了！",
  str_voice_1300941_43 = "讓你受傷了……抱歉……",
  str_voice_1300941_44 = "那、那邊有點吵……我不是很習慣……",
  str_voice_1300941_45 = "是禮物呢……嗯……謝謝。",
  str_voice_1300941_46 = "有……有點意外呢……",
  str_voice_1300941_47 = "真是用心的禮物……",
  str_voice_1300941_48 = "開心的時候……該說什麼才好呢？",
  str_voice_1300941_49 = "我從女王陛下手中接過了「春日之杖」，繼承了父母的遺志……成為了新的巡邏員，這無關宿命……而是我必須要做的事……",
  str_voice_1300941_50 = "北境的冰雪天地……有清爽的空氣、和煦的陽光……還有可以獨自發呆的雪地……是我最喜歡的地方。",
  str_voice_1300941_51 = "我已經習慣了獨自在雪地巡邏的日子，偶爾也會聽路過的旅人們講述所見所聞……以及「春天」的樣子……真想親眼看看呢……",
  str_voice_1300941_52 = "白夜……極光……",
  str_voice_1300941_53 = "我在呢……",
  str_voice_1300941_54 = "早安……",
  str_voice_1300941_55 = "我吃過了……你呢？",
  str_voice_1300941_56 = "辛苦了……休息吧……",
  str_voice_1300941_57 = "我……願溫柔的你……在新的一年能擁有好運……",
  str_voice_1400951_1 = "您這地方真大啊，我想這輩子不會再見到比這還大的傢伙了。",
  str_voice_1400951_2 = "做我們這行的就講究信譽，您就不用擔心了。",
  str_voice_1400951_3 = "這身防護服是我自己做的，裡面有不少方便的設計，特別是防止氣味外洩這方面。",
  str_voice_1400951_4 = "要我送您一瓶我尾巴上的玩意嗎？關鍵時刻您可能用得上，不過平常拿著的時候得小心點。",
  str_voice_1400951_5 = "感覺傭兵生活已經有點累了，我最近在考慮其他的生活方式，不過還沒有什麼頭緒。",
  str_voice_1400951_6 = "這副模樣想在這個世界裡生存下去真的非常困難，好在影鎮的好人比想像中還多，我也算是受到不少照顧。",
  str_voice_1400951_7 = "您說面具嗎？那可不能摘下。這整套裝備是一體的，缺了哪一件都不行。",
  str_voice_1400951_8 = "您要是考慮長期合作的話，我這邊可以給您打個八折，畢竟是老客戶了，有這點折扣也很正常。",
  str_voice_1400951_9 = "您想不想抽空來我那做客？地方是小了點，但住起來還挺舒服的，偶爾換一換環境也挺不錯的。",
  str_voice_1400951_10 = "您這是要休息了嗎？那我也歇一會吧。",
  str_voice_1400951_11 = "我這就去，您稍微等一下。",
  str_voice_1400951_12 = "我上回去黑市看見兩個小孩在賣東西。在這年頭討生活真是不容易啊。",
  str_voice_1400951_13 = "我小時候還是見過那麼一兩個空裔的，真是可惜了。",
  str_voice_1400951_14 = "請多注意。不然像您這樣的人在影鎮馬上就會被盯上。",
  str_voice_1400951_15 = "生日快樂，成長真是件令人開心的事情。",
  str_voice_1400951_16 = "您好，先生，我們接下來要做什麼？",
  str_voice_1400951_17 = "早安，美好的一天從一杯牛奶開始。",
  str_voice_1400951_18 = "晚安，我剛從黑市選了一些小東西回來，您要看看嗎？",
  str_voice_1400951_19 = "先生您這樣的年輕人最好早點睡覺……當然我也不會強迫您。",
  str_voice_1400951_20 = "在影鎮可以不用在意自己的身分，生活在這裡挺不錯的。",
  str_voice_1400951_21 = "因為工作的原因，我也到過好幾次啟光。那地方給我的感覺就是發展得很快，人也比較熱情。",
  str_voice_1400951_22 = "您這是想要我說什麼呢？",
  str_voice_1400951_23 = "和那些東西打交道快二十年，已經有點麻木了。牠們都是從哪冒出來的啊？",
  str_voice_1400951_24 = "企鵝先生和熊先生的組合還挺逗趣的，聽他們說相聲永遠不會膩。",
  str_voice_1400951_25 = "恐爾貢先生人還不錯，我在考慮將來要不要去他的島上生活。",
  str_voice_1400951_26 = "其實我很喜歡陰暗潮濕的地方，這套裝備也能滿足我的需求。",
  str_voice_1400951_27 = "我還是滿不喜歡被別人打擾的，特別是當我在家裡的時候。",
  str_voice_1400951_28 = "這大傢伙可真棒，您是不是這個世界上唯一一個可以控制巨像的人啊？",
  str_voice_1400951_29 = "您好先生，有事請您儘管吩咐。",
  str_voice_1400951_30 = "我的業務能力更嫻熟了。",
  str_voice_1400951_31 = "這感覺真不錯，謝謝。",
  str_voice_1400951_32 = "這樣下去我應該能接更多委託。",
  str_voice_1400951_33 = "極限是用來突破的。",
  str_voice_1400951_34 = "馬上來。",
  str_voice_1400951_35 = "我有一個計畫。",
  str_voice_1400951_36 = "您想好了嗎？",
  str_voice_1400951_37 = "機會來了！",
  str_voice_1400951_38 = "我可不是好惹的啊。",
  str_voice_1400951_39 = "嚐嚐這個吧。",
  str_voice_1400951_40 = "您在看哪呢！",
  str_voice_1400951_41 = "很好，開工了。",
  str_voice_1400951_42 = "這還算是比較輕鬆的。",
  str_voice_1400951_43 = "實力差距還是太大了啊。",
  str_voice_1400951_44 = "您有事嗎？能盡可能找個陰涼的地方說嗎？",
  str_voice_1400951_45 = "您真是太客氣了。",
  str_voice_1400951_46 = "這玩意真不錯啊！",
  str_voice_1400951_47 = "我真是受寵若驚。",
  str_voice_1400951_48 = "這可真是……我都不知道該怎麼感謝您了。",
  str_voice_1400951_49 = "雖然同為光靈，但個體之間的差異還是很大。我的體質的確困擾了我很久，但現在已經無所謂了。",
  str_voice_1400951_50 = "要說有什麼印象深刻的事件的話……就是我二十歲那年影鎮被圍攻的事情吧，那次我真是覺得我死定了。",
  str_voice_1400951_51 = "感覺最近已經有點力不從心了。雖然身體還年輕得很，但是心態方面就……也許我確實該考慮退休了，恐爾貢先生那邊應該是個不錯的選擇。",
  str_voice_1400951_52 = "白夜極光。",
  str_voice_1400951_53 = "您好。",
  str_voice_1400951_54 = "一日之計在於晨。",
  str_voice_1400951_55 = "午安，您吃過了嗎？",
  str_voice_1400951_56 = "晚安，先生。",
  str_voice_1400951_57 = "新年快樂，這裡馬上就要熱鬧起來了。",
  str_voice_1400621_1 = "每當我從巨像上俯瞰時，都會為這個廣闊的世界發出感嘆，這都要感謝莉亞。",
  str_voice_1400621_2 = "我聽說這個世界比我們所能看見的大陸還要大上數十倍吧？真想看看其他地方是什麼樣子。",
  str_voice_1400621_3 = "我可以對自己的房間稍作改造嗎？我還是覺得待在有點自然氣息的地方更舒服。",
  str_voice_1400621_4 = "這些藤蔓雖然來自於我的能力，但它們陪伴我很久了，稱它們為朋友也不為過。",
  str_voice_1400621_5 = "為了保護朋友而想變強很奇怪嗎？為什麼你要露出那種像父親一樣的笑容……你也沒比我大幾歲吧？",
  str_voice_1400621_6 = "父親是個偉大的守林人，希望終有一天我能成為超越父親的存在。",
  str_voice_1400621_7 = "我們一起行動了這麼久，也算是朋友了吧……",
  str_voice_1400621_8 = "我覺得我們之間有很多相似的地方，身處的立場……身邊的人之類的……",
  str_voice_1400621_9 = "能夠遇到你這樣的朋友是我的榮幸，有機會的話我也會把風脈之森的其他人介紹給你認識。",
  str_voice_1400621_10 = "你的眼皮就像傍晚的花一樣，好像快要閉起來了。睡一下吧。",
  str_voice_1400621_11 = "我會盡我所能。",
  str_voice_1400621_12 = "這把劍？雖然是木製的，卻與鋼鐵一樣鋒利。",
  str_voice_1400621_13 = "在我用劍時，請離我遠一點，因為藤蔓可能會纏繞上你。",
  str_voice_1400621_14 = "這種房間……一時間還真難以適應。抱歉，這房間很好，只是沒有自然氣息。",
  str_voice_1400621_15 = "生日快樂。生日禮物，希望你會喜歡。",
  str_voice_1400621_16 = "現在是一天之中最為重要的時間，不能疏於鍛鍊。",
  str_voice_1400621_17 = "早安，你看起來……有點疲憊。",
  str_voice_1400621_18 = "晚安，夜晚的森林可是很危險的，還是不要靠近比較好。",
  str_voice_1400621_19 = "我能理解你現在的心情，畢竟時間總是不夠用，但適當休息也很重要。",
  str_voice_1400621_20 = "北境……與世無爭之地，然而代價就是與世隔絕。",
  str_voice_1400621_21 = "我聽說過紅油扳手那群人彼此之間自由奔放的相處方式。",
  str_voice_1400621_22 = "暮冬而生！",
  str_voice_1400621_23 = "可悲又可恨的生物，牠們理應從這個世界消失。",
  str_voice_1400621_24 = "女王陛下的氣度無人可比，她就是北境的守護者。",
  str_voice_1400621_25 = "莉亞她……對我來說是十分重要的朋友，很多方面都是。",
  str_voice_1400621_26 = "一個可以坦誠相待的朋友對我來說比什麼都重要。",
  str_voice_1400621_27 = "我可不想與那些虛偽、表裡不一的偽君子相處。",
  str_voice_1400621_28 = "巨像確實有趣，我也想要一座……我會有這種想法還是很正常的吧？",
  str_voice_1400621_29 = "我是西爾瓦，風脈之森的守林人，還請多指教。",
  str_voice_1400621_30 = "力量正在湧現。",
  str_voice_1400621_31 = "這就是修煉的成果。",
  str_voice_1400621_32 = "向強者之路邁進。",
  str_voice_1400621_33 = "我會守護大家。",
  str_voice_1400621_34 = "交給我。",
  str_voice_1400621_35 = "要上了！",
  str_voice_1400621_36 = "怎麼了？",
  str_voice_1400621_37 = "森林啊，起風吧。",
  str_voice_1400621_38 = "風啊，刺穿敵人。",
  str_voice_1400621_39 = "藤蔓。",
  str_voice_1400621_40 = "劍風。",
  str_voice_1400621_41 = "我會盡到職責。",
  str_voice_1400621_42 = "一次寶貴的勝利。",
  str_voice_1400621_43 = "是我的經驗不足……",
  str_voice_1400621_44 = "不知能為你做些什麼……送些藤蔓可好？",
  str_voice_1400621_45 = "這個……我可以收下嗎？",
  str_voice_1400621_46 = "這東西很有意思。",
  str_voice_1400621_47 = "謝謝你……導航員。",
  str_voice_1400621_48 = "咳，有你這樣的朋友真好！",
  str_voice_1400621_49 = "我十分憧憬自己的父親，就連我的劍術也是因為崇拜他而慢慢掌握的。但是他離開得太早了，而母親難以承受這樣的現實，她……算了，沒什麼。",
  str_voice_1400621_50 = "父母過早離世對於尚且年幼的我造成了很大打擊，是莉亞帶著我走出了陰霾，沒有她就沒有現在的我。",
  str_voice_1400621_51 = "說來有些慚愧，曾經有很長一段時間我都認為莉亞是個男孩子，每當回想起先前與她相處的時光，我都想找個地洞鑽進去。",
  str_voice_1400621_52 = "白夜極光。",
  str_voice_1400621_53 = "你好。",
  str_voice_1400621_54 = "早安，導航員。",
  str_voice_1400621_55 = "要一起吃個飯嗎？",
  str_voice_1400621_56 = "我先去睡覺了，你呢？",
  str_voice_1400621_57 = "新年快樂，時間好像轉眼就過去了呢。",
  str_voice_1500871_1 = "我身為白夜城的貴族，有義務保護像你這樣的人……你不需要我保護？……是我小看你了嗎。",
  str_voice_1500871_2 = "如果你現在沒什麼事做，可以陪我練習飛鏢……你在期待什麼，你只需要幫我拿著鏢盤就可以了。",
  str_voice_1500871_3 = "我的愛好很老氣嗎？可是我不覺得喜歡傳統戲劇有什麼問題，作為貴族，當然要重視傳統文化的傳承。",
  str_voice_1500871_4 = "使用雷槍作為武器當然是因為我很擅長長槍，而且長槍才符合優秀戰士的身分。",
  str_voice_1500871_5 = "你懷疑雷槍的精準度嗎？我想你多慮了，不管是用飛鏢還是雷槍，只要我想，哪怕是蚊子的翅膀都可以射穿！",
  str_voice_1500871_6 = "你要小心，現在環繞在我身旁的雷電，可不只是好看而已。",
  str_voice_1500871_7 = "身為貴族就要保持貴族的身分，我不會摒棄自己的尊嚴，當然也不會試圖凌駕於所有人之上——包括你。",
  str_voice_1500871_8 = "我確實有過於傲慢的時候……但這來自於我的身分與實力，一時難以修正，希望你不要誤解。",
  str_voice_1500871_9 = "真是奇怪，面對你，我似乎可以忘記身分帶來的一切。",
  str_voice_1500871_10 = "這……是休息的時間嗎？身為白夜城的優秀戰士，過於空閒似乎不是正確的事，不過……確實也需要休息了。",
  str_voice_1500871_11 = "……如果這是必須要做的事，那我會肩負起責任的，你只需要相信我就可以了。",
  str_voice_1500871_12 = "我似乎有點過於在意身分了，但人注定生下來便是不平等的。",
  str_voice_1500871_13 = "那些缺少判斷能力的平民，乖乖等著被保護就行了，不是嗎？",
  str_voice_1500871_14 = "戰鬥和訓練於我來說都是平常的事，無需擔心。",
  str_voice_1500871_15 = "我記得很清楚，今天是你的誕辰……你想要什麼呢？",
  str_voice_1500871_16 = "來了嗎？這是日常訓練的時間，我是說……現在我在練習飛鏢。",
  str_voice_1500871_17 = "問候就免了，不必特地為此浪費時間。",
  str_voice_1500871_18 = "對於一名戰士來說，時間還不算晚。",
  str_voice_1500871_19 = "保持良好的睡眠才可以維持健康的體魄。",
  str_voice_1500871_20 = "保護平民是貴族的義務，這才是白夜城該有的「秩序」。",
  str_voice_1500871_21 = "推崇科技的啟光，到底會有怎樣的規則？",
  str_voice_1500871_22 = "白夜至上！",
  str_voice_1500871_23 = "破壞白夜城的秩序與安寧的傢伙們，不應該存在於世上。",
  str_voice_1500871_24 = "城主殿下是德行兼備的人，但……收攏權勢是正確的決定嗎？",
  str_voice_1500871_25 = "雖是城主殿下的子嗣，但卡蓮小姐有點過於天真了。",
  str_voice_1500871_26 = "確切來說不能算愛好，觀賞戲劇已經是我生活中的一部分了。",
  str_voice_1500871_27 = "那些過著虛榮生活、所謂的「貴族」，真是愚昧又自大。",
  str_voice_1500871_28 = "巨像象徵著你的血統與身分，同時也能成為你的榮耀。",
  str_voice_1500871_29 = "初次見面，我名為貝芙麗，此次將與你共事。作為白夜城守衛隊成員，保護這裡的平民也是我的責任之一，請務必放心。",
  str_voice_1500871_30 = "極限……並不存在。",
  str_voice_1500871_31 = "還有成長的餘地。",
  str_voice_1500871_32 = "這才是我應當獲得的力量。",
  str_voice_1500871_33 = "讓長槍劃破夜空——",
  str_voice_1500871_34 = "隨時待命！",
  str_voice_1500871_35 = "給我方向吧。",
  str_voice_1500871_36 = "已經確實瞄準了！",
  str_voice_1500871_37 = "雷槍——貫穿吧！",
  str_voice_1500871_38 = "天衣無縫——！",
  str_voice_1500871_39 = "最後一擊！",
  str_voice_1500871_40 = "守護安寧！",
  str_voice_1500871_41 = "站到我身後去！",
  str_voice_1500871_42 = "這是我的使命。",
  str_voice_1500871_43 = "我還不夠強嗎……",
  str_voice_1500871_44 = "是該休息一會了……嗯？我手中的雷槍怎麼了？戰鬥練習也是一種休息。",
  str_voice_1500871_45 = "嗯，我收下了。",
  str_voice_1500871_46 = "這，真是適合我的禮物，謝謝。",
  str_voice_1500871_47 = "我感受到了你的心意。",
  str_voice_1500871_48 = "謝謝你……看來我要對你更用心了。",
  str_voice_1500871_49 = "我的家族地位尊貴、力量強大，我們享受了平民的尊崇，自然會身先士卒，保護他們——這是我們家族堅守的驕傲和責任。",
  str_voice_1500871_50 = "我跟那些過著虛榮生活、所謂的「貴族」不同，我秉承應盡的責任和義務，守護秩序和安寧。這樣才配得上貴族之名不是嗎？",
  str_voice_1500871_51 = "父親曾說我遲早會因傲慢而吃虧。我雖很早就已意識到問題所在，但傲慢已經深入骨髓裡，讓我無法輕易改變……",
  str_voice_1500871_52 = "白夜極光！",
  str_voice_1500871_53 = "我在。",
  str_voice_1500871_54 = "日安。",
  str_voice_1500871_55 = "休息要充足。",
  str_voice_1500871_56 = "願你度過平和的夜晚。",
  str_voice_1500871_57 = "新年，祈願吧。",
  str_voice_1600301_1 = "白夜城的商隊學精明了，都開始運空箱子了。只能先摸清車轍的痕跡，確認裡面有東西再動手了啊。",
  str_voice_1600301_2 = "小子，下次給我記住：這個要丟資源回收，聽懂了嗎？",
  str_voice_1600301_3 = "書？你的書我都發給兄弟們了，讓他們好好讀讀，隔天考試！……裡面有雜誌？我不管，反正拿到什麼考什麼！",
  str_voice_1600301_4 = "有什麼想說的直接說。問我「為什麼叫醒山這種奇怪的名字」？嘖，那你又為什麼要叫那種奇怪的名字？",
  str_voice_1600301_5 = "想看看我的扳手？只有被選中的傢伙才能使用它唷。啊，跟正義什麼的沒關係，只是因為它有一噸重。",
  str_voice_1600301_6 = "人會說謊，拳頭不會。拳頭只會打死人。……嗯，我說的這句真是好詞。應該不會輸給卡戎寫出來的東西。",
  str_voice_1600301_7 = "嗓門大有什麼不好？開心就要大笑，生氣就要大罵，這不是世上最淺顯易懂的道理嗎？",
  str_voice_1600301_8 = "還沒制定戰鬥計劃嗎？嗯，隨機應變？哈哈，不愧是導航員！根據搶到的武器決定計劃吧，這才是男人的浪漫啊！",
  str_voice_1600301_9 = "紅油扳手裡的所有人，都是我可以放心依賴的夥伴。至於你嘛……哈哈，也算！所以你什麼時候要搬到紅油扳手來住？",
  str_voice_1600301_10 = "把我擺在這裡然後自己去忙別的，還不如讓我去坐牢。對！我就是說給你聽的！",
  str_voice_1600301_11 = "這是要我來站崗嗎？既不能飆車，又不能打架，只能呆呆站著？唉……算了，反正我還有點耐心。",
  str_voice_1600301_12 = "以拳平事，以砲息戰！都不行？那就用我的頭顱裝滿烈酒，灑遍大地！",
  str_voice_1600301_13 = "吃飯、睡覺、生活。這是我們自己的戰爭，和那些外人是講不清的。",
  str_voice_1600301_14 = "喂，快幫巨像加速啊！油門在哪？也沒有換擋的地方嗎？",
  str_voice_1600301_15 = "唷！生日快樂！我忘記準備禮物了。來人！去給導航員搶點禮物回來！！",
  str_voice_1600301_16 = "戰鬥嗎？現在正是揮舞機械臂的好天氣呀！",
  str_voice_1600301_17 = "你醒了？真羨慕你們這些說睡就睡的人。",
  str_voice_1600301_18 = "夜幕降臨了，群山入睡了。蟲子要沿著黑暗的裙角爬出來了……",
  str_voice_1600301_19 = "你也睡不著嗎？走，吃宵夜去！我請客！",
  str_voice_1600301_20 = "別看我們這副吊兒郎當的樣子，紅油扳手是可靠的大家庭！",
  str_voice_1600301_21 = "無論如何都無法喜歡上那些軍爺啊。以前發生的事太多了……",
  str_voice_1600301_22 = "及時行樂！",
  str_voice_1600301_23 = "既難對付又不能吃，黑色蟲子們就該好好滾回自己該在的地方！",
  str_voice_1600301_24 = "她還能無憂無慮笑著的那個時候，我們都還沒意識到，活著是多麼辛苦呢。",
  str_voice_1600301_25 = "有些傢伙的確很可靠沒錯，但音樂品味……呃，我什麼也沒說。",
  str_voice_1600301_26 = "打劫、飆車就是我的娛樂活動。膚淺嗎？膚淺一點有什麼不好？",
  str_voice_1600301_27 = "見過山巒拔地而起的樣子嗎？如果哪天有人敢傷害我的家人，你就會見到那樣的奇觀。",
  str_voice_1600301_28 = "喔喔！這可真是寬敞明亮！我宣布這裡是紅油扳手的領地了，不接受反駁！",
  str_voice_1600301_29 = "歡迎來到紅油沙漠，小鬼。感受到風的變化了嗎？別怕，那不是沙塵暴，只是群山的氣息。",
  str_voice_1600301_30 = "燃起來了！",
  str_voice_1600301_31 = "阿哈！不愧是我！",
  str_voice_1600301_32 = "快點！再加速！",
  str_voice_1600301_33 = "讓你看看，沙漠霸王的實力！",
  str_voice_1600301_34 = "別拖拖拉拉的！",
  str_voice_1600301_35 = "血液燃起來了！",
  str_voice_1600301_36 = "往哪衝？",
  str_voice_1600301_37 = "都給我——規矩一點！！",
  str_voice_1600301_38 = "你迷路了嗎？！",
  str_voice_1600301_39 = "粉碎吧——！",
  str_voice_1600301_40 = "都燃起來吧！！",
  str_voice_1600301_41 = "都跟我來就行了！",
  str_voice_1600301_42 = "痛快！這樣一來熱身就算結束了吧？",
  str_voice_1600301_43 = "哈哈哈，傷痕可是男人的功勳啊！",
  str_voice_1600301_44 = "我在努力抑制自己搶劫的衝動。你這巨像實在太漂亮了。",
  str_voice_1600301_45 = "嗯……這是你的心意嗎？",
  str_voice_1600301_46 = "喔！你這小子眼光不賴喔！",
  str_voice_1600301_47 = "哈！這可比那些搶來的玩意好多了！",
  str_voice_1600301_48 = "喔喔！這個正是我想要的！多謝！！",
  str_voice_1600301_49 = "我和啟光的傢伙們的確說不上融洽。等時候到了，有些事情你自然會知道的，我現在懶得囉嗦。",
  str_voice_1600301_50 = "還習慣紅油扳手這群人的作風嗎？不習慣我也不在乎，這是我們自己的活法。艾斯特拉無盡而廣闊，同時卻也很小，小到只有紅油沙漠可以容納我們……",
  str_voice_1600301_51 = "沒錯，我的妹妹叫伊芙。我們經歷了太多不堪回首的事，而那些過去會成為讓羈絆更緊密地連結。希望命運也能對你有所眷顧，導航員。",
  str_voice_1600301_52 = "白！夜！極！光！",
  str_voice_1600301_53 = "在嗎，小子？",
  str_voice_1600301_54 = "起床了小子！",
  str_voice_1600301_55 = "現在是揮灑汗水的時間！",
  str_voice_1600301_56 = "早點去睡吧。",
  str_voice_1600301_57 = "新年到了！看你這矮小的身材，讓我帶著你把大腦也練出八塊腹肌，怎麼樣！",
  str_voice_1400671_1 = "巨像能飛到海邊嗎？聽說在海邊能看到美人魚呢。",
  str_voice_1400671_2 = "白夜城好像都是貴族呢，有沒有公主和王子呀～",
  str_voice_1400671_3 = "導航員先生之前從未見過光靈？那你都住在哪裡呢？",
  str_voice_1400671_4 = "有人說北境的森林中有可怕的巫婆，不過我完全不怕呢～",
  str_voice_1400671_5 = "女王陛下的冬宮是由冰雪建造的，非常漂亮，有機會帶你去～",
  str_voice_1400671_6 = "聽說最南邊是荒無人煙的沙漠。什麼時候帶我去呀～",
  str_voice_1400671_7 = "我想知道……你過去的事情。感覺會是個奇妙的故事呢。",
  str_voice_1400671_8 = "黑桃騎士和紅心王后是我的好朋友，所以也是你的好朋友呢。",
  str_voice_1400671_9 = "你問我是怎麼掌握光能術的嗎？啊，好像就是自己忽然就能施放了。",
  str_voice_1400671_10 = "黑桃騎士、紅心皇后，你們去哪裡了呀～",
  str_voice_1400671_11 = "待在這裡就好了嗎？好吧。他們兩個也會喜歡這裡的。",
  str_voice_1400671_12 = "這裡有圖書館嗎？如果有好看的童話故事書就好啦。",
  str_voice_1400671_13 = "總有人說我神出鬼沒……其實我就是個子小、走路輕而已。",
  str_voice_1400671_14 = "跳格子太好玩啦，我能玩上十天十夜不睡覺～",
  str_voice_1400671_15 = "過生日啦～可以吃蛋糕了嗎？",
  str_voice_1400671_16 = "今天似乎沒什麼事呢，一起去玩吧？",
  str_voice_1400671_17 = "早安，要不要去森林裡走一走？",
  str_voice_1400671_18 = "今天要去哪裡呢？",
  str_voice_1400671_19 = "啊……好睏呀，是不是應該睡覺了呢？",
  str_voice_1400671_20 = "北境的人們真的很好呢，就是……生活封閉了點。",
  str_voice_1400671_21 = "提到白夜城就想到貴族呢。不知道那裡有沒有平民呢？",
  str_voice_1400671_22 = "暮冬而生。",
  str_voice_1400671_23 = "討厭的傢伙！比童話裡的壞國王還討厭！",
  str_voice_1400671_24 = "西爾瓦哥哥雖然表面上冷漠，但他其實是個溫暖的人呢。",
  str_voice_1400671_25 = "莉亞姐姐真的很溫柔，只是有點太溫柔了……",
  str_voice_1400671_26 = "聽說大陸上有一種等身大的人偶，好想要……",
  str_voice_1400671_27 = "不要弄出太吵的聲響，我都要起雞皮疙瘩了！",
  str_voice_1400671_28 = "可不可以讓他帶著我四處旅行呢？這樣就是《愛麗絲環遊記》啦～",
  str_voice_1400671_29 = "這裡就是巨像嗎？我是愛麗絲，今後會經常來找你玩唷。",
  str_voice_1400671_30 = "領悟了一點呢！",
  str_voice_1400671_31 = "似乎長高了一點呢！",
  str_voice_1400671_32 = "可以去更遠的地方了！",
  str_voice_1400671_33 = "讓我看看那些從未見過的景色吧！",
  str_voice_1400671_34 = "一起來吧～",
  str_voice_1400671_35 = "可以了呢！",
  str_voice_1400671_36 = "要讓我出手嗎？",
  str_voice_1400671_37 = "出現吧！",
  str_voice_1400671_38 = "火焰！",
  str_voice_1400671_39 = "黑桃騎士！",
  str_voice_1400671_40 = "紅心王后！",
  str_voice_1400671_41 = "讓我走第一個嗎？",
  str_voice_1400671_42 = "大家都很厲害呢～",
  str_voice_1400671_43 = "大家快逃……",
  str_voice_1400671_44 = "要和我們玩嗎？一起來玩新遊戲吧～",
  str_voice_1400671_45 = "導航員先生，謝謝你！",
  str_voice_1400671_46 = "這個我喜歡！",
  str_voice_1400671_47 = "又收到了你的禮物……",
  str_voice_1400671_48 = "太可愛了！要融化了……",
  str_voice_1400671_49 = "我這雙兔耳朵在村子裡很受歡迎呢，可以讓你摸摸喔。",
  str_voice_1400671_50 = "如果不是莉亞姐姐和西爾瓦哥哥，恐怕我現在還留在北境呢。",
  str_voice_1400671_51 = "不要害怕這兩位夥伴，他們幫了我很多呢。",
  str_voice_1400671_52 = "白夜極光。",
  str_voice_1400671_53 = "你好～",
  str_voice_1400671_54 = "早安～",
  str_voice_1400671_55 = "午安呀。",
  str_voice_1400671_56 = "晚上啦。",
  str_voice_1400671_57 = "新年好。",
  str_voice_1701081_1 = "即使是越過灼熱的火焰、走到痛苦的盡頭，等待我們的也只有灰色的平原。",
  str_voice_1701081_2 = "我本是為了「守護」才接受了黑暗的力量。我本擁有維持自我的信心，最終卻成為了無情的「兵器」。",
  str_voice_1701081_3 = "這是懲罰。沒有終點、無法遺忘，不能真正意識到自己的「死」，也沒機會迎接滅亡。",
  str_voice_1701081_4 = "這是贖罪，要我睜開眼睛，要我好好看看，眼前的一切究竟變成了什麼樣子。",
  str_voice_1701081_5 = "因為我毀滅了本該守護的東西，所以要留在熾熱混濁的泥漿中不斷掙扎。",
  str_voice_1701081_6 = "真羨慕她能一直像木頭一般保持冷靜……而我卻總是無意義地燃燒，燒毀自己的驕傲，也燒毀自己的信念。",
  str_voice_1701081_7 = "為了守護國家，不論是作為獵手或是戰士，我都付出了全部的心血……但那又如何呢？到頭來我不過是個被遺棄的「獵兵」……",
  str_voice_1701081_8 = "罪人沒有資格因痛苦而流淚，只能繼續戰鬥……",
  str_voice_1701081_9 = "夠了……還是說點你的事吧，我想要暫時忘記過去。",
  str_voice_1701081_10 = "在心中開一個洞口，讓其中充滿永不止息的火焰。那叫做……「煉獄」嗎？",
  str_voice_1701081_11 = "嗯？我能做點什麼戰鬥以外的事情嗎……不，我是「兵器」，所以答案是「不行」。",
  str_voice_1701081_12 = "越想，心臟就越冷；越冷，火焰卻燒得越旺盛。",
  str_voice_1701081_13 = "那天，是我親手毀滅了一切——用憤怒的火焰。",
  str_voice_1701081_14 = "「落下吧」、「落下吧」，我聽見他們在喊，我聽見他們在笑。",
  str_voice_1701081_15 = "今天我很平靜，所以可以待在你身邊。說吧，你希望我做什麼。",
  str_voice_1701081_16 = "千年之後還能站在這裡，命運已經足夠眷顧我了。",
  str_voice_1701081_17 = "聽見了嗎？清晨，遠方傳來了哭聲。",
  str_voice_1701081_18 = "希望能夠有一天，我們可以不需要再戰鬥。",
  str_voice_1701081_19 = "休息吧，你已經戰鬥過，夠努力了。",
  str_voice_1701081_20 = "我只是不明白，為什麼……為王國而戰的英雄會被拋棄？！",
  str_voice_1701081_21 = "你說的那些城鎮，我想去看看……那裡的人如何生活，是否幸福。",
  str_voice_1701081_22 = "我們是最強大的戰士。",
  str_voice_1701081_23 = "細微的燈火已經燃盡，但我還有吞噬一切的熔岩，足夠消滅牠們。",
  str_voice_1701081_24 = "真相必須被隱瞞，因此祭劍座做出了那種選擇……所以我才憤怒！",
  str_voice_1701081_25 = "童謠座那個木頭，她不知道我為什麼燒她，為什麼憤怒。",
  str_voice_1701081_26 = "光靈，已經擁有如此廣闊的天地了嗎？太好了……",
  str_voice_1701081_27 = "起身，前進，面對敵人，燃起戰火，又在悔恨中平息。",
  str_voice_1701081_28 = "巨像和你在一起嗎？看起來他的結局會比我們好很多……",
  str_voice_1701081_29 = "我不懂你為什麼要救我，是讓我來贖罪的嗎？「寂靜獵兵」這名字早該消失了，我卻還是逃不過，哈哈……",
  str_voice_1701081_30 = "還不可以燃起火焰。",
  str_voice_1701081_34 = "不，我一個人就夠了。",
  str_voice_1701081_35 = "一個不留！",
  str_voice_1701081_36 = "全部毀滅！",
  str_voice_1701081_37 = "燃燒、全部焚盡！",
  str_voice_1701081_38 = "哀嘆、哀嘆、再到深淵！",
  str_voice_1701081_39 = "逃跑啊！",
  str_voice_1701081_40 = "叫喊啊！",
  str_voice_1701081_41 = "離我遠一點。",
  str_voice_1701081_42 = "必須平息……火焰……",
  str_voice_1701081_43 = "為什麼！為什麼會失敗？！",
  str_voice_1701081_44 = "小心，不要貿然靠近我。情緒平靜的時候，我自然會主動找你。",
  str_voice_1701081_45 = "放在那裡就可以了。",
  str_voice_1701081_46 = "我不知道自己能給你什麼。",
  str_voice_1701081_47 = "感謝你的好意，那我收下了。",
  str_voice_1701081_48 = "我……無以為報，謝謝你。",
  str_voice_1701081_49 = "我記得寒冷的冬夜，死灰一般的城鎮……刻在「心臟」上的罪孽，無可挽回。",
  str_voice_1701081_50 = "在決定加入那個計劃的時候，或許我們的結局就已經注定好了……不，我不該再多說了。",
  str_voice_1701081_51 = "我曾認為這個世界就快毀滅了……但現在才明白，無論誰生誰死，這個世界都會正常運轉……哈哈，我真笨啊。",
  str_voice_1701081_52 = "白夜極光。",
  str_voice_1701081_53 = "你在嗎？",
  str_voice_1701081_54 = "早。",
  str_voice_1701081_55 = "現在是正午時分。",
  str_voice_1701081_56 = "晚安，你……那個……",
  str_voice_1701081_57 = "今天是特別的，從前，現在。",
  str_voice_1701071_1 = "嗯？需要我指揮下次的作戰嗎？",
  str_voice_1701071_2 = "怎麼了？訓練結束的話再追加一些吧。",
  str_voice_1701071_3 = "我看起來很凶嗎……也許吧，可能我失去的不只是記憶。",
  str_voice_1701071_4 = "只要能殺光暗鬼，即使變成惡鬼也無妨吧。",
  str_voice_1701071_5 = "沒什麼不吉利的……這又不是真的棺材…………嗯，應該不是，我忘了。",
  str_voice_1701071_6 = "別整天盯著我，去做點有意義的事。",
  str_voice_1701071_7 = "沒錯，我的確遺失了一些記憶……不過這並不影響我殺暗鬼的效率。",
  str_voice_1701071_8 = "突然回憶起自己在一片黑麥田裡耕種……那真的是我嗎？",
  str_voice_1701071_9 = "盾能為你所用，也算是一大幸事。劍……嗎？恐怕還不行。",
  str_voice_1701071_10 = "既然這麼悠閒，那我就唱幾首在營中經常唱的歌吧。通常我開金嗓後大家就會衝過去搶著出去工作。",
  str_voice_1701071_11 = "明白，馬上就來。",
  str_voice_1701071_12 = "等候指令。",
  str_voice_1701071_13 = "我看起來很沒精神嗎？那是因為沒遇到暗鬼吧。",
  str_voice_1701071_14 = "希望明天是個北風呼嘯的……好日子。",
  str_voice_1701071_15 = "好久沒有為誰慶祝生日了，不過請接受我真摯的祝福。生日快樂。",
  str_voice_1701071_16 = "我現在的工作就是守衛這座巨像，並討伐所有敵人。當然，敵人只限暗鬼。",
  str_voice_1701071_17 = "早，召集所有人在臨空者號上先跑個五十圈吧。不行？淨是些麻煩的傢伙啊。",
  str_voice_1701071_18 = "是可以稍微放鬆一下的時間了，不過可別太晚休息。",
  str_voice_1701071_19 = "這麼晚還不睡嗎？放哨的事交給我吧。",
  str_voice_1701071_20 = "只記得和軍中同袍們服役的模糊往事……其他……抱歉，我真的不記得了。",
  str_voice_1701071_21 = "這片土地上雖然存有諸多勢力……但在我看來局面是越來越混亂了。",
  str_voice_1701071_22 = "我們是北方的守護者。",
  str_voice_1701071_23 = "這是我們最大的敵人，希望也是所有光靈唯一的敵人。",
  str_voice_1701071_24 = "弗萊格桑其實……算了，我不喜歡評價別人。",
  str_voice_1701071_25 = "你想瞭解弗雷雅啊……她是一位很優秀的訓誡教官，\n天資聰穎，在軍中很受歡迎。我只知道這些。",
  str_voice_1701071_26 = "……喜歡的東西之類的……也許有過吧。",
  str_voice_1701071_27 = "我討厭大型暗鬼，因為無法打飛太遠。",
  str_voice_1701071_28 = "如果那時有這種巨像，想必能拯救更多人吧。",
  str_voice_1701071_29 = "你好，「寂靜獵兵」戒衛座向你問好。隨時可以投入戰鬥。",
  str_voice_1701071_30 = "黑暗也會被寒冬淹沒。",
  str_voice_1701071_34 = "很好，準備獵殺。",
  str_voice_1701071_35 = "喔喔喔喔——！！",
  str_voice_1701071_36 = "殺！殺——！！",
  str_voice_1701071_37 = "殺了你——！！！",
  str_voice_1701071_38 = "休想——！！",
  str_voice_1701071_39 = "受死！！！",
  str_voice_1701071_40 = "太慢了！！！",
  str_voice_1701071_41 = "要我帶隊？你膽子不小……",
  str_voice_1701071_42 = "呼！……呼……贏了……別怕……",
  str_voice_1701071_43 = "怎麼可能……殺了你……絕對要殺了你——！！",
  str_voice_1701071_44 = "怎麼？想看我的單指倒立伏地挺身？",
  str_voice_1701071_45 = "……謝謝。",
  str_voice_1701071_46 = "……十分感謝。",
  str_voice_1701071_47 = "這似乎能派上用場。",
  str_voice_1701071_48 = "謝謝，雖然你可能看不出來，但我應該是很開心。",
  str_voice_1701071_49 = "我猜我大概是農戶出身的軍人……我還依稀記得那些同伴的相貌，但當我努力集中精神回憶的時候，記憶卻變得更加支離破碎。",
  str_voice_1701071_50 = "依稀記得我應徵入伍成為軍官……立功授勳得到國王覲見……接著就是暗鬼入侵，接受祭劍座的邀請，成為寂靜獵兵中的一員……",
  str_voice_1701071_51 = "我們從危機之中拯救了王國，又被人民害怕驅逐……再然後……再然後就……我似乎遺忘了很重要的東西……對我而言非常重要的東西……",
  str_voice_1701071_52 = "白夜極光。",
  str_voice_1701071_53 = "喂，喂？",
  str_voice_1701071_54 = "早，要我吹響號角叫大家起床嗎？",
  str_voice_1701071_55 = "吃飽了就繼續下午的訓練吧。",
  str_voice_1701071_56 = "該休息了，馬上熄燈。",
  str_voice_1701071_57 = "新年快樂，好像有人說我的劍不吉利……",
  str_voice_1701091_1 = "從前從前，在雪松和柏樹的森林裡，有一座白色的石頭之城，城裡有一位公主，她披著鹿皮。",
  str_voice_1701091_2 = "從前從前，有五位英雄在寒冷的極地，擊敗了可怕的暗鬼，可是王國……啊，每次我講到這裡，「焚霜座」總是會生氣。",
  str_voice_1701091_3 = "從前從前，王國的夜晚漆黑一片，有五個人走出王國，到遙遠的地方，買下了「月亮」，帶回了「星辰」……",
  str_voice_1701091_4 = "你看到我的夥伴了嗎？一個熄滅的、一個封閉的、一個迷失的，還有一個帶著劍，留在了那裡……",
  str_voice_1701091_5 = "我們是「眾多」的「星辰」之一，「星辰」的光輝照耀著眾人，但暗淡後的「星辰」只能一人懷抱著屈辱。",
  str_voice_1701091_6 = "為何我總是講「過去」的故事？非說原因不可的話，畢竟我是留在「過去」的人。",
  str_voice_1701091_7 = "拜訪者進入了石頭之城，披著鹿皮的公主承認，鹿很重要，但她不在意了。",
  str_voice_1701091_8 = "從前……不，我想說的是，我不能跟你走，我必須和黯淡的「星辰」在一起……不，不是指動作上的「走」，是指心理上的「走」。",
  str_voice_1701091_9 = "故事的後續發展留給你講就夠了。畢竟你的年紀小，會比我們活得更久……不，等等，好像也不一定。",
  str_voice_1701091_10 = "森林，森林，我希望你能聽聽我的苦惱……這是古老的童謠，不過我忘了它的唱法，只能用言語講述。",
  str_voice_1701091_11 = "要繼續嗎？上次的故事停留在……數年轉眼過去，「星辰」光輝黯淡。",
  str_voice_1701091_12 = "如果「星辰」變成流星落下，或許會摧毀好不容易回歸和平的大地。",
  str_voice_1701091_13 = "五人來到一個十字路口，有人說「我們就在這裡分道揚鑣吧」。",
  str_voice_1701091_14 = "那天，我選擇欣然接受「祭劍座」的攻擊，接受他斬碎一切的決定。",
  str_voice_1701091_15 = "我沒有什麼特別的東西能給你，只有早已鏽蝕的「英雄桂冠」。",
  str_voice_1701091_16 = "啊，還願意親近我的，大概只有你和那些純真的動物了吧。",
  str_voice_1701091_17 = "我沉睡了多久？能像現在這樣迎接清晨……真是一份禮物。",
  str_voice_1701091_18 = "盤踞的樹根中，無情的人甦醒了……把我喚醒，你不後悔嗎？",
  str_voice_1701091_19 = "夜晚，我們唯一能相見的地方居然是寒冷昏暗的亡者之路。",
  str_voice_1701091_20 = "從前從前，國王寫了一封信，信中說「把他們立刻殺死埋掉」。",
  str_voice_1701091_21 = "曾經灰暗的大地，如今已不再需要夜晚的繁星來點亮。",
  str_voice_1701091_22 = "我們是最具耐心的獵手。",
  str_voice_1701091_23 = "面對暗鬼要謹慎，就算不仇視牠們，消滅牠們也是正確的選擇。",
  str_voice_1701091_24 = "我提議「讓焚霜座離開」，所以焚霜座又憤怒了，燒壞了我的衣服。",
  str_voice_1701091_25 = "戒衛座比焚霜座更容易招惹麻煩，這是事實。",
  str_voice_1701091_26 = "我不喜歡，只不過，將古老的故事流傳下去也是我的職責之一。",
  str_voice_1701091_27 = "我不厭惡，只是我的「無情」偶爾也會影響我的判斷。",
  str_voice_1701091_28 = "如果你問我的意見……你要小心，不要讓他變成「兵器」。",
  str_voice_1701091_29 = "你是誰……啊，故事又開始了。從前從前，風穿過腐敗的森林，叫醒了已經黯淡的「星辰」。",
  str_voice_1701091_30 = "依舊……需要這力量嗎？",
  str_voice_1701091_34 = "獵殺時間到。",
  str_voice_1701091_35 = "狩獵之夜。",
  str_voice_1701091_36 = "月光，照亮我的獵物。",
  str_voice_1701091_37 = "為了讚頌生命而狩獵。",
  str_voice_1701091_38 = "為了迎接清晨而入夜。",
  str_voice_1701091_39 = "林莽之中。",
  str_voice_1701091_40 = "荒野之中。",
  str_voice_1701091_41 = "將敵人，盡數殲滅。",
  str_voice_1701091_42 = "只是盡到職責罷了。",
  str_voice_1701091_43 = "再來一次，不能放走敵人。",
  str_voice_1701091_44 = "「從前從前」的故事……不，我並不喜歡講故事，但還是要講給你聽才行。",
  str_voice_1701091_45 = "這是什麼？",
  str_voice_1701091_46 = "真神奇，既懷念又新鮮。",
  str_voice_1701091_47 = "我或許記得「好意」的珍貴。",
  str_voice_1701091_48 = "確認了，我想，我應該露出笑容。",
  str_voice_1701091_49 = "從前從前，「星辰」的五人就像他們誕生後所寫好的故事一樣，悄無聲息地消失……但有人問「你們不是四個人嗎」。",
  str_voice_1701091_50 = "將故事的空白填上……「焚霜座」總是憤怒、「戒衛座」常常沉默、「鎮魂座」沒有笑容，「祭劍座」拒絕了我的提議，但卻拿起劍……",
  str_voice_1701091_51 = "最後，會講故事的鹿的白骨在月光下看著拜訪者……它知道你會明白有關「五人」的一切，非常感謝。",
  str_voice_1701091_52 = "白夜極光……嗎？",
  str_voice_1701091_53 = "從前……",
  str_voice_1701091_54 = "啊，早安。",
  str_voice_1701091_55 = "午後，是好時候。",
  str_voice_1701091_56 = "我能見到月光。",
  str_voice_1701091_57 = "真讓人懷念，萬象更新之日。",
  str_voice_1701101_1 = "嗯，不管怎麼說我也是功名赫赫的戰士，還是會好好聽從你的指示進行戰鬥的。但可別因此得意忘形啊！",
  str_voice_1701101_2 = "雖然我之前常被稱作聖女，但是我並不接受懺悔之類的事喔，那種麻煩的事快點去找別的聖女吧。",
  str_voice_1701101_3 = "嗯？嗯？導航員你在哪裡啊，原來在這裡啊～不出所料，你真是毫不起眼呢。差一點就把你當成背景了。",
  str_voice_1701101_4 = "為什麼叫鎮魂座？因為我能看得到靈魂喔，比如你後面那些人……開玩笑的啦笨蛋，哈哈哈～",
  str_voice_1701101_5 = "導航員先生這樣毫無戒心地在我面前亂晃，真的是讓我忍不住想捅你一槍……",
  str_voice_1701101_6 = "我說啊，快點去工作吧。我又不會跑掉，不用一直盯著我。",
  str_voice_1701101_7 = "很閒的話要不要來陪我過幾招。別看我這樣，我曾經一拳打死過野狼喔，導航員先生的話，光是半拳就能把你打哭啦～",
  str_voice_1701101_8 = "不管你用哪種方式計算，我都未滿十九歲喔。還是你非常想瞭解那些質疑我的人會被如何「訓誡」呢？",
  str_voice_1701101_9 = "其實仔細想想你這傢伙人很不錯啦……啊，作為答謝，不如叫你一聲大哥哥？好……？好什麼好啊！我開玩笑的！",
  str_voice_1701101_10 = "哼～哼～哼～這麼悠閒真不錯，反正你應該也沒什麼特別想做的事吧。那我就大發慈悲地陪陪你～",
  str_voice_1701101_11 = "明白了明白了～就由偉大的寂靜聖女，寂靜獵兵中最強的鎮魂座弗雷雅來幫助沒用的導航員先生喔～什麼……還真的要工作？",
  str_voice_1701101_12 = "這件制服太輕飄飄了嗎？嗯～畢竟人家的魔法能在遠距離就把暗鬼變成飄著熟肉香氣的料理。根本沒必要像艾德拉斯那樣全副武裝吧～",
  str_voice_1701101_13 = "希望我「喵嗚」地叫……你啊……腦袋沒問題吧？這讓我很難不關心你的精神狀況。",
  str_voice_1701101_14 = "若是因為剛剛導航員一碰，我就直接來個回馬槍，也許就能獲得「不可觸碰之聖女」這樣的稱號吧。還蠻有趣的，呵呵呵。",
  str_voice_1701101_15 = "生日快樂呀～快過來讓我看看有沒有長高……欸！太、太近了吧！突然貼到面前你想幹嘛啊變態！",
  str_voice_1701101_16 = "今天的計劃準備好了嗎～哎？還沒計劃嗎？真是沒辦法，要不要幫你呢？",
  str_voice_1701101_17 = "早～啊～我還以為你準備直接睡到下午呢，總之，早安～",
  str_voice_1701101_18 = "我決定了！幫導航員先生制定今天的計畫！嗯？！\n已經這個時間了嗎……可，可惡，我好不容易下定決心幫忙了！",
  str_voice_1701101_19 = "好了～我要回去休息啦，值班就拜託導航員先生……不行嗎？怎麼能這樣～",
  str_voice_1701101_20 = "過去的事就讓它過去吧～沉睡了這麼久，我對過去那些事沒有太大的真實感……不過在你這裡悠哉地找尋下個目標還是挺不錯的。",
  str_voice_1701101_21 = "啟光和白夜城都是些看起來很死腦筋的傢伙呢。北境嘛……下次帶人家去玩吧！",
  str_voice_1701101_22 = "我們是邊境的安定者！",
  str_voice_1701101_23 = "討厭，非常討厭。\n即使我沒帶著訓誡之旗也會想一拳打爛這些骯髒造物的臉。",
  str_voice_1701101_24 = "弗萊格桑和辛西婭之前的關係真是複雜呢～聽說弗萊格桑在某次衝動下攻擊了辛西婭，不過現在感情應該好多了吧～",
  str_voice_1701101_25 = "啊啊～艾德拉斯很厲害呢，不管是戰技還是魔法，都算是數一數二的角色……嗯？導航員先生該不會這樣就吃醋了吧，真是意外地可愛呢。",
  str_voice_1701101_26 = "就……就喜歡巧克力和甜食之類的不行嗎！明明大家都喜歡吧……你閉嘴，不許發表意見……！",
  str_voice_1701101_27 = "討厭暗鬼和你……啊，別哭啊你，對、對不起……比起暗鬼……我還是挺喜歡你的。",
  str_voice_1701101_28 = "住起來很舒服，除此之外，沒什麼其他感想呢~抱歉喔。",
  str_voice_1701101_29 = "初次見面，我是「寂靜獵兵」鎮魂座。總之，戰鬥的事就交給我，你可不要笨手笨腳地添亂喔。",
  str_voice_1701101_30 = "哇喔，不愧是我呢！",
  str_voice_1701101_34 = "好，那就好好看著我吧！",
  str_voice_1701101_35 = "一個不留！",
  str_voice_1701101_36 = "雷聲在轟鳴。",
  str_voice_1701101_37 = "化為碎屑吧！",
  str_voice_1701101_38 = "愚蠢之輩……受死吧！",
  str_voice_1701101_39 = "迸發而出！",
  str_voice_1701101_40 = "還沒結束喔！",
  str_voice_1701101_41 = "我當然不會辜負你的期待。",
  str_voice_1701101_42 = "啊～理所當然呢，要好好感謝我喔。",
  str_voice_1701101_43 = "嗚……怎麼可能……抱歉……",
  str_voice_1701101_44 = "嗯？是特地來感謝我嗎？",
  str_voice_1701101_45 = "啊，還不錯。",
  str_voice_1701101_46 = "嗯哼……真是意外，我收下了！",
  str_voice_1701101_47 = "謝……謝……！別一直盯著我看啊！",
  str_voice_1701101_48 = "嗚……這、這個……謝謝！你人真好，我非常喜歡！",
  str_voice_1701101_49 = "我想想，嗯……小的時候啊……好像是出生在很厲害的家庭吧，所以才會造就如此完美的我不是嗎？",
  str_voice_1701101_50 = "不管是軍中聖女還是訓誡教官，其實都是很無聊的工作啦，每天都要聽比自己年長的人懺悔、嘮叨個不停，還要指責改正一些不守規矩的大人。明明都是大人了，稍微有點自覺啊！",
  str_voice_1701101_51 = "啊……其實我也不知道當時是什麼狀況啦，總之就聽了祭劍座的話，然後就變成現在這樣了～也沒什麼不好的對吧～",
  str_voice_1701101_52 = "白夜極光～哼哼～",
  str_voice_1701101_53 = "導航員先生～",
  str_voice_1701101_54 = "喂喂——起床了嗎？",
  str_voice_1701101_55 = "別睡啦別睡啦，快醒醒！",
  str_voice_1701101_56 = "啊啊，好睏……",
  str_voice_1701101_57 = "新年到了～！為春假獻上讚歌！",
  str_voice_1601111_1 = "不要看我的眼睛，那個顏色並不好看……",
  str_voice_1601111_2 = "你有那個能力，或許能夠瞭解我的痛苦，如果是真的，那就太好了……",
  str_voice_1601111_3 = "你似乎有一些特別的能力，那麼能抹消我的記憶嗎？",
  str_voice_1601111_4 = "不要被我身上的晶石嚇到，我不會讓它們跑到你身上的。",
  str_voice_1601111_5 = "這片花朵狀的晶石，是從我身上長出來的第一片血色結晶呢……",
  str_voice_1601111_6 = "不要在戰鬥中碰到我的晶石，否則你會被它困住的。",
  str_voice_1601111_7 = "信念？無論懷著怎樣的信念，都是不可能得到拯救的……",
  str_voice_1601111_8 = "你想瞭解我的過去？即便知道，又有什麼意義呢？還是……你能拯救我？",
  str_voice_1601111_9 = "我也能……找到普通人那樣的幸福嗎？或許在這裡已經有了……",
  str_voice_1601111_10 = "雲朵很好看……什麼也不想的狀態真好。",
  str_voice_1601111_11 = "為什麼要我站在這裡呢？好吧，聽你的……",
  str_voice_1601111_12 = "人與人之間是無法互相瞭解的，因為大家的悲歡並不能相通。",
  str_voice_1601111_13 = "不要詢問我的家人，我沒有姓氏……",
  str_voice_1601111_14 = "如果不用戰鬥，我真想去除身上的晶石，即便會因此而死……",
  str_voice_1601111_15 = "啊……生日快樂。",
  str_voice_1601111_16 = "今天，會有什麼事發生呢？有你在，應該不會無聊的。",
  str_voice_1601111_17 = "陽光很刺眼呢……你不覺得嗎？",
  str_voice_1601111_18 = "這麼快就晚上了？也好……",
  str_voice_1601111_19 = "日復一日，又是一天過去了。",
  str_voice_1601111_20 = "真理結社追求的事物能拯救我嗎？或許可以吧……",
  str_voice_1601111_21 = "白夜城已經遺棄了我，我也不懷念它。反正那裡只重視貴族吧。",
  str_voice_1601111_22 = "願真理……保護你。",
  str_voice_1601111_23 = "可憐的傢伙，它們也被什麼東西所束縛吧？",
  str_voice_1601111_24 = "浮士德有時候有點可怕，但是沒有他的話，我已經成為了一片晶石……",
  str_voice_1601111_25 = "我能感受到艾希身上的痛苦，不過她卻如此活潑，真令我羨慕。",
  str_voice_1601111_26 = "浮士德的白箱真的很神奇，它能治癒我的病痛。這真是上天給我的恩賜……",
  str_voice_1601111_27 = "雖然它能保護我，卻也會吞噬我……只要有可能，我一定要離開它。",
  str_voice_1601111_28 = "巨像？很大的東西呢……但是更令我在意的，是駕駛它的你……",
  str_voice_1601111_29 = "我是拜里厄。別被這血色晶石嚇到，它不會傷害你的……",
  str_voice_1601111_30 = "茶花，更加美麗了。",
  str_voice_1601111_31 = "血晶……在蔓延。",
  str_voice_1601111_32 = "血晶在盛開……",
  str_voice_1601111_33 = "或許……能擺脫血晶了？",
  str_voice_1601111_34 = "要一起嗎？",
  str_voice_1601111_35 = "晶石簇生。",
  str_voice_1601111_36 = "即將出現。",
  str_voice_1601111_37 = "領域！",
  str_voice_1601111_38 = "血晶！",
  str_voice_1601111_39 = "茶花！",
  str_voice_1601111_40 = "綻放！",
  str_voice_1601111_41 = "一起上吧。",
  str_voice_1601111_42 = "勝利了？好……",
  str_voice_1601111_43 = "唉，敗了就敗了吧……",
  str_voice_1601111_44 = "謝謝你的關心……我感覺好多了。",
  str_voice_1601111_45 = "為什麼要送這個呢……",
  str_voice_1601111_46 = "居然知道我喜歡這個……",
  str_voice_1601111_47 = "謝謝你了……",
  str_voice_1601111_48 = "沒想到你這麼瞭解我……",
  str_voice_1601111_49 = "我曾是白夜城的貴族，但是……現在已經回不去了。",
  str_voice_1601111_50 = "這血色晶石是一個瘋狂的家族將我擄走後植入我體內的……並非天生。",
  str_voice_1601111_51 = "如果時光能夠倒流，我寧願被血色晶石所殺，也不願意親人遭難……",
  str_voice_1601111_52 = "白夜……極光。",
  str_voice_1601111_53 = "在不在……",
  str_voice_1601111_54 = "早安。",
  str_voice_1601111_55 = "中午了。",
  str_voice_1601111_56 = "似乎有點晚了。",
  str_voice_1601111_57 = "希望在新的一年裡，能有人瞭解我。",
  str_voice_1601111_58 = "嗯，那個，你真的……",
  str_voice_1601111_59 = "一直以來，謝謝你的贈予……",
  str_voice_1501131_1 = "白夜城的樂師數量眾多，擅長演奏各種類型的音樂，但這並不代表他們懂音樂。",
  str_voice_1501131_2 = "神鳴之聲是最高級的音樂，然而現在只有我才能演奏，我一定要讓它廣為傳頌。",
  str_voice_1501131_3 = "艦橋上的鋼琴音色很好呢，你是在巨像裡彈了十七年的鋼琴嗎？聽說你還與薇絲做過四手聯彈，看來樂感不錯呀。",
  str_voice_1501131_4 = "那些僕從名為「神鳴」，是神賜予我的。我可以不眠不休地指揮它們，為大家徹夜演奏~",
  str_voice_1501131_5 = "我聽說空裔的感應能力很強，那你是否能感受到音樂的軌跡呢？",
  str_voice_1501131_6 = "我又聽到了神鳴之聲，那是超過世界上一切音樂的美妙之聲，它指引著我，帶領我尋找那終極樂章。",
  str_voice_1501131_7 = "我的視力沒有問題，戴眼鏡是為了讓我更有指揮家的感覺~",
  str_voice_1501131_8 = "你的感應能力很強……說不定可以成為一名優秀的指揮家。",
  str_voice_1501131_9 = "看到我手上的綢帶了嗎？結打得很漂亮吧？想讓我教你怎麼打漂亮的結嗎？我很擅長這個的。",
  str_voice_1501131_10 = "嗯……這首曲子不好聽嗎？那就換一首。《返鄉》？《歸來》？還是《遠航》？",
  str_voice_1501131_11 = "嗯，正好可以讓神僕們出來，這裡太安靜了，讓它們演奏一曲，活躍一下氣氛吧。",
  str_voice_1501131_12 = "這裡的房間很不錯呢，空間寬敞、光線充足，重點是隔音效果很好，非常適合練習演奏。",
  str_voice_1501131_13 = "你說我手上的綢帶？其實，它是這根指揮棒附帶的，只是纏在我手上而已。",
  str_voice_1501131_14 = "演奏可以靠天賦，而指揮不僅需要精通樂理，還要具備統籌能力，所以指揮家是很少見的。",
  str_voice_1501131_15 = "啊！我忘記準備禮物了。那就讓我的僕從們為你來首生日曲吧！",
  str_voice_1501131_16 = "又是悠閒的一天，讓我的僕從們為大家演奏一曲吧。",
  str_voice_1501131_17 = "你起得很早，是為了欣賞清晨的陽光嗎？還是為了聆聽這大自然的聲音？",
  str_voice_1501131_18 = "工作了一天很累吧，你需要休息。去艦橋上彈彈鋼琴放鬆一下吧~",
  str_voice_1501131_19 = "深夜是靈感迸發的時刻，所以我通常在夜裡創作。",
  str_voice_1501131_20 = "真理結社比白夜城好，起碼它承認音樂有多種不同的風格。",
  str_voice_1501131_21 = "白夜城很古老，白夜城很優雅，然而，白夜城不懂音樂。",
  str_voice_1501131_22 = "願真理祝福你，願音樂祝福你。",
  str_voice_1501131_23 = "可憐的傢伙，不懂欣賞音樂，也就沒有任何未來可言。",
  str_voice_1501131_24 = "維多利亞學識淵博，因此我才會跟隨她，一起去尋找神鳴的聲音。",
  str_voice_1501131_25 = "如果希卡蕾能擺脫那些條條框框的束縛，她的未來會更廣闊的。",
  str_voice_1501131_26 = "在大陸上，肯定有一篇樂譜能代表真正的神鳴。我一定會找到它的。",
  str_voice_1501131_27 = "循規蹈矩只能產生庸才，例如白夜城的那些所謂的「音樂家」。",
  str_voice_1501131_28 = "聽說操縱它的是一架鋼琴，看來音樂果然是萬能的！",
  str_voice_1501131_29 = "波娜瑟為你指引，一起去聆聽神鳴的樂章！",
  str_voice_1501131_30 = "樂章，更加華麗了。",
  str_voice_1501131_31 = "聆聽！那是神鳴的聲音。",
  str_voice_1501131_32 = "彗星，為我之聲而來。",
  str_voice_1501131_33 = "這！是神鳴的指引！",
  str_voice_1501131_34 = "神鳴會協助我們。",
  str_voice_1501131_35 = "樂章，完成。",
  str_voice_1501131_36 = "神僕，預備。",
  str_voice_1501131_37 = "神鳴！指引！",
  str_voice_1501131_38 = "神鳴！出現！",
  str_voice_1501131_39 = "共鳴的顫抖！",
  str_voice_1501131_40 = "共鳴的戰栗！",
  str_voice_1501131_41 = "讓大家聽從我的指揮吧。",
  str_voice_1501131_42 = "完美的演奏！",
  str_voice_1501131_43 = "讓我的僕從斷後。",
  str_voice_1501131_44 = "要看一下我是如何指揮的嗎？",
  str_voice_1501131_45 = "啊，多謝。",
  str_voice_1501131_46 = "哇，我喜歡這個！",
  str_voice_1501131_47 = "又收到你的禮物了！",
  str_voice_1501131_48 = "讓我為你譜寫一首樂曲吧！",
  str_voice_1501131_49 = "在這個世界上有一篇終極樂章，代表了神的聲音。那是我畢生追求的目標。",
  str_voice_1501131_50 = "那一天，神的聲音在我體內迴響，隕石從天而降，那樂章在我心中一閃而過，從此我便走上了追求它的道路。",
  str_voice_1501131_51 = "白夜城從來不懂音樂。也多虧了這一點，我才沒有被他們選中，而是繼續留在那個小鎮，直到我發現了它。",
  str_voice_1501131_52 = "白夜極光。",
  str_voice_1501131_53 = "有空嗎？",
  str_voice_1501131_54 = "要不要來一首起床曲？",
  str_voice_1501131_55 = "午間不演奏，休息一下吧。",
  str_voice_1501131_56 = "晚安，小夜曲將伴你入眠。",
  str_voice_1501131_57 = "新年好！要不要來一場音樂會？",
  str_voice_1601161_1 = "咦？這裡如此嚙合的話……啊！好點子！我先記下來！",
  str_voice_1601161_2 = "螢盞是根據什麼原理設計的呢……真的很奇妙。",
  str_voice_1601161_3 = "左輪女真的很能打呢，畢竟是她把我「打」進了紅油扳手。",
  str_voice_1601161_4 = "螺絲起子有很多型號，不要用錯啦！",
  str_voice_1601161_5 = "困難就像蓋得很緊的瓶蓋，有時候只需要一把結實的起子——找出它的弱點，就能輕鬆撬開啦。",
  str_voice_1601161_6 = "在這裡真的學到了很多。託你的福，機甲的裝備可以再改進！首先要有足夠的金屬……",
  str_voice_1601161_7 = "啟光曾專門為我設立了一個只有男生的班級，說是為了不打攪女生上課。哈哈……",
  str_voice_1601161_8 = "有一陣子，啟光安排我去了一座只有男人的工廠上班。那段日子過得還是挺清靜的。",
  str_voice_1601161_9 = "我的角和尾巴，似乎有某種特殊的吸引力……總之我也不太清楚。",
  str_voice_1601161_10 = "為什麼一直看著我？喔！你一定是想參觀我的工作吧，歡迎歡迎~",
  str_voice_1601161_11 = "我在這待久一點也沒關係嗎？終於可以研究巨像的結構了……",
  str_voice_1601161_12 = "好龐大的巨像，構造的技術真先進，是個優質的參考依據呢。",
  str_voice_1601161_13 = "前些日子又收到了奇怪的信……唉，不知道要怎麼辦才好。",
  str_voice_1601161_14 = "要看看我的工具箱嗎？它叫艾倫，裡面裝著很多有意思的工具呢！",
  str_voice_1601161_15 = "啊？今天原來是你的生日，那生日快樂~",
  str_voice_1601161_16 = "今天也要修理很多東西呢，不僅有巨像的日常維護，還要加緊完成紅油扳手那些人的要求……",
  str_voice_1601161_17 = "早安！我修東西的聲音，沒有吵到你吧？",
  str_voice_1601161_18 = "晚上了？這麼快啊，還有一些東西要修呢。",
  str_voice_1601161_19 = "這個零件圖……好難畫，恐怕要熬通宵了。",
  str_voice_1601161_20 = "紅油扳手真的很自由，即使有人看不慣你，只要打上一架就好啦。",
  str_voice_1601161_21 = "啟光的那些地下城裡不僅空氣沉悶，思想也很僵硬，完全不能適應。",
  str_voice_1601161_22 = "陸行者號！酷！",
  str_voice_1601161_23 = "這些討厭的暗鬼，應該用扳手好好擰一擰它們的腦子。",
  str_voice_1601161_24 = "眼鏡妹的技術真的很厲害，很難想像那都是她自學的。",
  str_voice_1601161_25 = "和左輪女相處的時候真的很輕鬆！因為她說話相當直爽，看到我也不臉紅。",
  str_voice_1601161_26 = "機械是不會騙人的，也沒有什麼暗示，行就是行，不行就是不行。",
  str_voice_1601161_27 = "哎呀，有些人說話能不能直白一點，天天暗示，我聽著都很累……",
  str_voice_1601161_28 = "比陸行者號強了不少……不過看起來很難控制的樣子。",
  str_voice_1601161_29 = "你就是導航員吧！幸會！我能修理很多東西的，甚至連巨像也沒問題！",
  str_voice_1601161_30 = "啊，零件變多了。",
  str_voice_1601161_31 = "要升級工具箱了！",
  str_voice_1601161_32 = "有了新靈感！",
  str_voice_1601161_33 = "機甲之魂！燃燒！",
  str_voice_1601161_34 = "到我了嗎？",
  str_voice_1601161_35 = "零件！集結完畢！",
  str_voice_1601161_36 = "扳手，來吧。",
  str_voice_1601161_37 = "機械的海洋！",
  str_voice_1601161_38 = "爆炸！零件！",
  str_voice_1601161_39 = "艾倫拳！",
  str_voice_1601161_40 = "用力砸！",
  str_voice_1601161_41 = "有我在，沒問題。",
  str_voice_1601161_42 = "大家果然很厲害呢。",
  str_voice_1601161_43 = "啊，扳手壞掉了……",
  str_voice_1601161_44 = "有事拜託我？可以是可以，不過手頭的工作有點多，稍等一會。",
  str_voice_1601161_45 = "謝謝~我很喜歡，哈哈。",
  str_voice_1601161_46 = "不知道要怎麼感謝你。",
  str_voice_1601161_47 = "好像總是收到你的禮物。",
  str_voice_1601161_48 = "太感謝了！不知道要怎麼回禮！",
  str_voice_1601161_49 = "陸行者號經常出故障啊……要不是兩年前我修好了她，她現在還不能動呢。",
  str_voice_1601161_50 = "啟光的很多男人看我不順眼呢……真奇怪。我是被他們趕出來的。",
  str_voice_1601161_51 = "我的角和尾巴據說是什麼隔代遺傳，曾祖父也這樣，而且一樣被男人們討厭呢。",
  str_voice_1601161_52 = "白夜極光。",
  str_voice_1601161_53 = "有人嗎？",
  str_voice_1601161_54 = "早安，今天要修什麼？",
  str_voice_1601161_55 = "中午要吃什麼呢？",
  str_voice_1601161_56 = "啊，腦袋快爆死了，休息一下吧。",
  str_voice_1601161_57 = "新的一年，機甲製造進度一定要推進個一成！",
  str_voice_1501141_1 = "你要不要試一下戴領結呢？雖然只是個小配件，但是搭上現在的這身衣服，似乎也蠻合適的。",
  str_voice_1501141_2 = "你知道賞金獵人是做什麼的嗎？其實和傭兵差不多，但相當自由，基本上只要完成懸賞，然後去領錢就好了。",
  str_voice_1501141_3 = "飛來飛去的這些小螢盞還真可愛，正好用來當做我手上這根燃索的訓練目標。放心！不會把它們打壞的！",
  str_voice_1501141_4 = "很多人說我十分迷人，不過那應該不是我的原因，而是琴酒的功勞。",
  str_voice_1501141_5 = "燃索不僅能套住敵人，還能讓對方燃燒呢！而且我這燃索有個特別的名字——「卡列尼娜」，請記住她！",
  str_voice_1501141_6 = "看到這匹馬了嗎？她叫做安娜，從小我們便是夥伴，即便是死亡也沒有把我們分開。",
  str_voice_1501141_7 = "我的安娜——就是那匹馬——經歷過死亡與復生，額頭上的印記就是證明。",
  str_voice_1501141_8 = "巨像上的走廊真的很寬闊，好想在這裡騎騎馬，馳騁一番呢！",
  str_voice_1501141_9 = "要和我喝一杯嗎？當然是你喝飲料，我喝琴酒啦。如果沒有琴酒，其他的酒也可以啦。",
  str_voice_1501141_10 = "既然沒有什麼事做，那就想一下之後要完成的事情，再制定個簡單的計畫吧。比如說，如何提升自己的能力……",
  str_voice_1501141_11 = "嗯……要我待在這裡嗎？不能四處走動的話，很無聊耶。",
  str_voice_1501141_12 = "聽說紅油沙漠裡有一間酒館有口味獨特的美酒，有空要不要去喝一杯？",
  str_voice_1501141_13 = "你一直在看我？別被我迷住唷。我的親衛隊可是很多的。",
  str_voice_1501141_14 = "有很多人抱怨影鎮裡沒什麼懸賞任務，哈哈，因為都被我完成了。",
  str_voice_1501141_15 = "生日快樂！辦個生日派對吧？你不用操心，我來安排！",
  str_voice_1501141_16 = "爽朗的一天，和我一起騎馬吧？不會的話我教你，這是貴族的基本訓練。",
  str_voice_1501141_17 = "早起是很好的習慣，這代表導航員先生是個自律的人。",
  str_voice_1501141_18 = "晚餐加一杯琴酒吧——不是給你的，是我要喝啦，這樣有助於睡眠。",
  str_voice_1501141_19 = "啊……睡眠套住了我的眼睛，要休息啦。你難道不睏嗎？",
  str_voice_1501141_20 = "雖然成員不多，但真理結社有著強大的祕技，甚至能將死物復生……",
  str_voice_1501141_21 = "影鎮真是龍蛇雜處。要不是這樣，那傢伙也沒辦法待下去。",
  str_voice_1501141_22 = "願真理套——啊不，祝福你。",
  str_voice_1501141_23 = "暗鬼？在我眼中，它們不過是一筆筆會動的懸賞金罷了。",
  str_voice_1501141_24 = "維多利亞應該是名門之後，否則她不可能掌握如此強大的光能術……",
  str_voice_1501141_25 = "雖然並非出身名門，然而希卡蕾是一名真正的貴族，尤其是她的責任感。",
  str_voice_1501141_26 = "如果有什麼東西能讓我紆尊降貴，那一定是一瓶上好的琴酒。",
  str_voice_1501141_27 = "每當有人打亂我的安排，我都想勒住那人的脖子，再緊一些……",
  str_voice_1501141_28 = "雖然它很大，但是飛得很快呢，有時間和安娜競速一下吧！",
  str_voice_1501141_29 = "賞金獵人吉納維芙向導航員先生問好。有什麼需要我幫助的嗎？只要報酬足夠，一切都好談。",
  str_voice_1501141_30 = "燃索，更加靈活了。",
  str_voice_1501141_31 = "如我所願，力量湧現了。",
  str_voice_1501141_32 = "安娜，馳騁戰場吧。",
  str_voice_1501141_33 = "燃索，爆發！",
  str_voice_1501141_34 = "去套住敵人吧！",
  str_voice_1501141_35 = "火焰！預備！",
  str_voice_1501141_36 = "可以釋放了。",
  str_voice_1501141_37 = "燃燒吧！",
  str_voice_1501141_38 = "臣服於此！",
  str_voice_1501141_39 = "品嚐這熾烈吧。",
  str_voice_1501141_40 = "付諸一炬！",
  str_voice_1501141_41 = "正確的選擇。",
  str_voice_1501141_42 = "簡單至極。",
  str_voice_1501141_43 = "沒套住敵人嗎……",
  str_voice_1501141_44 = "我可以套住你嗎？別擔心，我保證不會傷著你。",
  str_voice_1501141_45 = "啊，謝謝。",
  str_voice_1501141_46 = "感謝！等會要不要一起喝一杯？",
  str_voice_1501141_47 = "謝謝，我會記住的。",
  str_voice_1501141_48 = "啊！這套住了我的心！",
  str_voice_1501141_49 = "佩德羅堡是少數沒被「暗潮危機」毀滅的城鎮，有機會我會講講這段故事。",
  str_voice_1501141_50 = "如果不是維多利亞復活了我的愛馬「安娜」，我也不會加入真理結社。",
  str_voice_1501141_51 = "斯莫奇曾經令我受辱，害我的家族中道衰落，因此我一定要阻撓她的一切行動，徹底地超過她。",
  str_voice_1501141_52 = "白夜極光。",
  str_voice_1501141_53 = "打擾了。",
  str_voice_1501141_54 = "早安。",
  str_voice_1501141_55 = "午安。",
  str_voice_1501141_56 = "夜已經深了。",
  str_voice_1501141_57 = "新的一年，也要好好制定計畫。",
  str_voice_1601121_1 = "你從來不換衣服嗎？還是說同一款式的衣服買了三百件？",
  str_voice_1601121_2 = "不要總纏著我問這問那的，簡直像個不懂事的小鬼！",
  str_voice_1601121_3 = "有人說我的鞋子走起來很吵？管他的！我喜歡這樣！",
  str_voice_1601121_4 = "可以對著螢盞打一發火球嗎？反正它們能自己修理自己。",
  str_voice_1601121_5 = "要是能從巨像上往下丟火球，真不知道該有多爽！尤其是在追殺暗鬼時！",
  str_voice_1601121_6 = "你看到這渾身佈滿火焰的蠍尾獅了嗎？是不是很漂亮？",
  str_voice_1601121_7 = "我曾經和白夜城的貴族一起打過暗鬼。哈哈，沒想到吧？",
  str_voice_1601121_8 = "我睡覺時會打鼾，似乎還會引起火災，記得叫螢盞注意點！",
  str_voice_1601121_9 = "曼提柯爾是我的家族姓氏，你沒聽說過？無所謂。",
  str_voice_1601121_10 = "太無聊了……在這裡放一把火吧，反正有螢盞來清理。",
  str_voice_1601121_11 = "要我就這樣站在這裡？給人隨便看？能燒掉那些過路的傢伙嗎？",
  str_voice_1601121_12 = "你看起來沒什麼精神啊，要不要用火來洗個臉？不會很痛的。",
  str_voice_1601121_13 = "練習？我才不需要。火焰之力會自己找上門來，根本不用操心。",
  str_voice_1601121_14 = "最近看到了幾件漂亮的配件，回頭到影鎮下個訂單去。",
  str_voice_1601121_15 = "我幫你點生日蠟燭吧！",
  str_voice_1601121_16 = "今天有什麼架可以打嗎？",
  str_voice_1601121_17 = "好刺眼的陽光，就沒有人要去拉窗簾嗎？",
  str_voice_1601121_18 = "一天就這麼過去了，什麼也沒幹，連隻暗鬼都沒見到。",
  str_voice_1601121_19 = "還是夜裡好，安靜，沒有人吵鬧，就是有點無聊。",
  str_voice_1601121_20 = "影鎮很亂、有很多架打，但是也很自由，可以讓人放飛自我。",
  str_voice_1601121_21 = "白夜城不過是一群老土的貴族自嗨的地方而已。",
  str_voice_1601121_22 = "活在當下。",
  str_voice_1601121_23 = "太弱了，和它們戰鬥連熱身都算不上。",
  str_voice_1601121_24 = "如果沒來影鎮，也不會認識泰莎了。她才是酷妞，啥都不在乎。",
  str_voice_1601121_25 = "打歸打，鬧歸鬧，總得有人維持秩序。在影鎮，只有伊斯塔萬有辦法。",
  str_voice_1601121_26 = "戰鬥中生死一瞬的感覺，比什麼都刺激。",
  str_voice_1601121_27 = "什麼事情都按照規矩和計畫來，還不如讓我去死。",
  str_voice_1601121_28 = "真是個大傢伙，不知道騎著它在天上飛是種什麼感覺。",
  str_voice_1601121_29 = "我是斯莫奇。你就是巨像的主人？這裡有什麼好玩的？能放火嗎？",
  str_voice_1601121_30 = "火焰，更加熾烈了。",
  str_voice_1601121_31 = "去燒點更能打的傢伙吧！",
  str_voice_1601121_32 = "這是我的實力！",
  str_voice_1601121_33 = "跟隨我！蠍尾獅！",
  str_voice_1601121_34 = "消滅它們！",
  str_voice_1601121_35 = "看我的！",
  str_voice_1601121_36 = "去燒點什麼吧！",
  str_voice_1601121_37 = "哈！燒毀吧！",
  str_voice_1601121_38 = "火！無處不在！",
  str_voice_1601121_39 = "哪裡逃！",
  str_voice_1601121_40 = "倒下吧！",
  str_voice_1601121_41 = "其實我自己就行了。",
  str_voice_1601121_42 = "簡單、簡單。",
  str_voice_1601121_43 = "喔？居然失手了。",
  str_voice_1601121_44 = "難道你覺得我會動不動就胡亂放火？我確實會啦，但不會在這裡。",
  str_voice_1601121_45 = "我就收下了。",
  str_voice_1601121_46 = "居然還挺不錯的。",
  str_voice_1601121_47 = "收了你太多東西了！",
  str_voice_1601121_48 = "說吧，想要我做什麼？",
  str_voice_1601121_49 = "如果不是因為那次打鼾，我和伊斯塔萬應該不會那麼快就認識。",
  str_voice_1601121_50 = "看到這枚領徽了嗎？據說是用蠍尾獅的頭骨製成的。這是我的家傳信物。",
  str_voice_1601121_51 = "體內的火焰之力讓我逐漸感覺不到疼痛，這也是我追求刺激的原因。",
  str_voice_1601121_52 = "白夜極光。",
  str_voice_1601121_53 = "沒人在嗎？",
  str_voice_1601121_54 = "早！",
  str_voice_1601121_55 = "已經中午了？",
  str_voice_1601121_56 = "晚安吧！",
  str_voice_1601121_57 = "不過是普通的一天，有啥好慶祝的。",
  str_voice_1601121_58 = "喂！導航員！一起玩玩火吧？不會很痛的。",
  str_voice_1601121_59 = "你為什麼要送我這麼多東西？有什麼目的？",
  str_voice_1401271_1 = "抱、抱歉、對不起，讓我再想想…馬上就好……",
  str_voice_1401271_2 = "我、我沒哭，只是昨天晚上夢見我父母了……",
  str_voice_1401271_3 = "紅油沙漠的人，很多都以拾荒維生，其實就是撿破爛。那個……我以前也是。",
  str_voice_1401271_4 = "是不是……應該勇敢一點呢？很多人都說我膽子太小了。",
  str_voice_1401271_5 = "父親說這條紙帶來自白夜城，上面附有光能之力，或許這就是我能操縱它們的原因吧。",
  str_voice_1401271_6 = "復活……是那張赤箋的名字，也是我的願望……復活他們——我的父母。",
  str_voice_1401271_7 = "這裡的氣氛真的很不錯……有家的感覺。",
  str_voice_1401271_8 = "他們、他們是有名字的……內赫留多夫、瑪絲羅娜，我的父母……",
  str_voice_1401271_9 = "他們、他們是有名字的……內赫留多夫、瑪絲羅娜，我的父母……",
  str_voice_1401271_10 = "對、對不起！我、我沒有在偷懶，只是有些無聊……所以才玩一下紙片。",
  str_voice_1401271_11 = "我、我可以站在這裡嗎？不會妨礙到別人？那好吧……",
  str_voice_1401271_12 = "聽說巨像裡有很多資料，那會有靈魂的情報嗎？",
  str_voice_1401271_13 = "這裡……有沒有那種結局圓滿，最後大家都活得好好的書？",
  str_voice_1401271_14 = "我用這些紙片打掃了一下巨像，這、這不算多管閒事吧？",
  str_voice_1401271_15 = "你生日？用我的紙片做個紙杯蛋糕吧！",
  str_voice_1401271_16 = "今天工作很多嗎？跟我說吧……我幫你分擔一點。",
  str_voice_1401271_17 = "好早呀，導航員，有什麼事情要做嗎？",
  str_voice_1401271_18 = "我、我想在這裡看一下夜景，可以嗎？",
  str_voice_1401271_19 = "啊……想睡了，該休息還是要休息，身體要緊……導航員。",
  str_voice_1401271_20 = "據說維多利亞大人能實現很多人的願望，這就是我加入真理結社的原因。",
  str_voice_1401271_21 = "我生活的沙漠，就是紅油扳手的地盤，然而並非總能見到他們。",
  str_voice_1401271_22 = "願真理……祝福你。",
  str_voice_1401271_23 = "應該用暗鬼的血，來染紅我的紙帶……",
  str_voice_1401271_24 = "能加入真理結社，都是多虧了吉納維芙小姐，她的開朗真讓我羨慕……",
  str_voice_1401271_25 = "那位總是笑瞇瞇的哥哥學識很淵博呢，對靈魂的知識也懂很多。",
  str_voice_1401271_26 = "啊，好想看一場大團圓結局的戲劇……很久沒看了。",
  str_voice_1401271_27 = "那些科學家就永遠正確？所謂理性就一定是對的？",
  str_voice_1401271_28 = "好龐大的傢伙，他……應該也有靈魂吧？",
  str_voice_1401271_29 = "我、我是帕索洛，這些紙片是跟著我來的，不、不會給大家帶來困擾……",
  str_voice_1401271_30 = "喔，紙片變輕了。",
  str_voice_1401271_31 = "紙張、交錯、漩渦……",
  str_voice_1401271_32 = "千紙層疊，勝過鐵甲……",
  str_voice_1401271_33 = "千紙層疊，勝過鐵甲……",
  str_voice_1401271_34 = "讓我也加入吧……",
  str_voice_1401271_35 = "紙片，平整了。",
  str_voice_1401271_36 = "讓我來吧。",
  str_voice_1401271_37 = "層疊之力！",
  str_voice_1401271_38 = "他們！來了！",
  str_voice_1401271_39 = "撕裂！",
  str_voice_1401271_40 = "破碎吧！",
  str_voice_1401271_41 = "要我帶領大家？",
  str_voice_1401271_42 = "呼……贏了。",
  str_voice_1401271_43 = "大、大家快撤退！",
  str_voice_1401271_44 = "他、他們，不會弄髒這裡的……",
  str_voice_1401271_45 = "謝、謝謝！",
  str_voice_1401271_46 = "我？真的能收下嗎？",
  str_voice_1401271_47 = "要怎樣才能感謝你……",
  str_voice_1401271_48 = "很久沒有人對我這樣了……",
  str_voice_1401271_49 = "看到我的皮膚了嗎？小時候在紅油沙漠曬成這樣的。",
  str_voice_1401271_50 = "要不是暗鬼，我也不會離開紅油沙漠，我的父母……也就不會死了。",
  str_voice_1401271_51 = "赤箋上……有我父母的靈魂。偶爾能聽到他們在叫我的名字……",
  str_voice_1401271_52 = "白夜極光。",
  str_voice_1401271_53 = "那個……",
  str_voice_1401271_54 = "早、早安。",
  str_voice_1401271_55 = "午安。",
  str_voice_1401271_56 = "要不要休息？",
  str_voice_1401271_57 = "新年快樂。",
  str_voice_1601221_1 = "好的獵手對任何事的要求都很嚴苛，從任務到愛好，都應該如此。",
  str_voice_1601221_2 = "眼鏡可以幫助我看得更清楚，清晰的認知才能得到更好的結果。",
  str_voice_1601221_3 = "對我很好奇嗎？希望能更瞭解我嗎？想知道精準射擊的訣竅嗎？沒問題，只要付出相應的報酬。",
  str_voice_1601221_4 = "有更多消息嗎？我願洗耳恭聽。如果和古董有關，那就更好了。",
  str_voice_1601221_5 = "珍貴的寶物往往藏在人們心中，是無價之寶。",
  str_voice_1601221_6 = "細微的裂紋、受損的釉質、不完整的底足……都不能掩蓋稀世珍品真正的價值。那是不朽的奇蹟。",
  str_voice_1601221_7 = "已經知道了，你所有的戰績和能力我都瞭解過一遍了。尊貴稀有的人，才是我值得站在這裡的原因。",
  str_voice_1601221_8 = "我願意分你一點今天的任務所得。……太少了嗎？抱歉，我今天得到的只有這些。",
  str_voice_1601221_9 = "我考慮開一家古董店。如果你來光顧的話，我可以考慮打折。",
  str_voice_1601221_10 = "已經5小時25分45秒沒有接到任務了。空閒的時間，總有種微妙的不真實感。",
  str_voice_1601221_11 = "這是你派的兼職任務？就算是你，也還是要收報酬的，不過可以為你打9.76折。",
  str_voice_1601221_12 = "希望今後派任務的時候，能更常想到我。",
  str_voice_1601221_13 = "我不是一直在盯著你看，這只是槍手的職業病而已。",
  str_voice_1601221_14 = "呃，如果可以的話，還是把蠟燭放遠一點吧，我不喜歡離火太近。",
  str_voice_1601221_15 = "生日快樂！我想送你一件我的收藏當作禮物。",
  str_voice_1601221_16 = "希望我們都擦亮眼睛，這是接任務的最佳時段。",
  str_voice_1601221_17 = "要是在影鎮的話，應該開門營業了……可是，我沒有店舖。",
  str_voice_1601221_18 = "聽說在這個時段，影鎮很多商店都會打折。",
  str_voice_1601221_19 = "深夜裡聽著懷錶的聲音，會睡得更香甜。",
  str_voice_1601221_20 = "影鎮的消息很靈通。有時候，一些祕密任務的報酬會更多。",
  str_voice_1601221_21 = "啟光聯邦……給人感覺是個用信念在支撐的地方。",
  str_voice_1601221_22 = "赫拉從不闔眼。",
  str_voice_1601221_23 = "啊，我早已看透牠們了……毫無價值。",
  str_voice_1601221_24 = "涉會長確實是個好榜樣。聽說她是白手起家，或許我有空的時候應該多和她交流。",
  str_voice_1601221_25 = "阿褐是個多麼可愛的小傢伙啊，如果只為我送東西，而且不用錢的話，就更棒了。",
  str_voice_1601221_26 = "你不認為古老的座鐘有一種沉寂的魔力嗎？悶，卻固執地履行不必要的責任……",
  str_voice_1601221_27 = "呃，這是粉紅色嗎？……是我的修養讓我還能保持禮貌，今後不要再讓我看到它了，請導航員明白這點。",
  str_voice_1601221_28 = "有什麼方法能縮小它嗎？現在這個大小，將來放不進我的店舖裡呢。",
  str_voice_1601221_29 = "有什麼能幫得上忙的嗎？艾爾戈絲樂意為您效勞。如果是高風險高報酬的任務，就再好不過了。",
  str_voice_1601221_30 = "謝謝，新的珍品。",
  str_voice_1601221_31 = "又更近一步。",
  str_voice_1601221_32 = "成功，少不了精打細算。",
  str_voice_1601221_33 = "距離實現我的目標，不遠了。",
  str_voice_1601221_34 = "啊，被選中了。",
  str_voice_1601221_35 = "準備鑑賞。",
  str_voice_1601221_36 = "藏寶於民。",
  str_voice_1601221_37 = "真正的鑑賞家！",
  str_voice_1601221_38 = "破碎吧，贗品！",
  str_voice_1601221_39 = "讓我看看……",
  str_voice_1601221_40 = "慢走不送！",
  str_voice_1601221_41 = "會賺更多對嗎？",
  str_voice_1601221_42 = "賺了多少呢？",
  str_voice_1601221_43 = "賠本買賣……",
  str_voice_1601221_44 = "不要一直盯著我看。我需要工作、挑選、辨別……我很忙。但這並不代表我不能盯著你看，因為你很有價值。",
  str_voice_1601221_45 = "謝謝，它值多少？",
  str_voice_1601221_46 = "我會好好收藏的。",
  str_voice_1601221_47 = "啊，有種熟悉的感覺……真的很謝謝你。",
  str_voice_1601221_48 = "謝謝，我想這是我收到最好的珍品。",
  str_voice_1601221_49 = "為什麼這麼喜歡古董嗎？我父母過世前都是收藏家，這是天賦和傳承。不用急著安慰我，我已經不再為他們傷心了。",
  str_voice_1601221_50 = "小時候當然也對一切都充滿怨恨，但其實……相信人們都會從生活中慢慢體會到愛。怎麼，不像我會說的話？",
  str_voice_1601221_51 = "重新收藏他們的愛，懷抱活下去的希望，報答幫助自己的人……這居然是我的真心話。嗯，還有賺錢。",
  str_voice_1601221_52 = "白夜極光。",
  str_voice_1601221_53 = "要買東西嗎？",
  str_voice_1601221_54 = "早安，導航員。",
  str_voice_1601221_55 = "吃飽飯才有力氣完成任務。",
  str_voice_1601221_56 = "夜晚是購物的最佳時間。",
  str_voice_1601221_57 = "新年快樂！希望我們都能早日實現夢想。",
  str_voice_1601221_58 = "精準度，大幅提升了。",
  str_voice_1601221_59 = "導航員，你的理想是什麼？",
  str_voice_1601221_60 = "導航員，你在嗎？",
  str_voice_1601171_1 = "別為今天的失敗憂愁氣餒，你最終會走出來的。年輕人總會遇到不如意的事，但十年後再回頭看，都不算什麼。",
  str_voice_1601171_2 = "肌肉酸痛？是不是訓練過度了？晚上我幫你弄一頓好吃的。",
  str_voice_1601171_3 = "你看看，這就是年輕人的毛病——橫衝直撞、自以為是，每個人都以為自己會成為救世主……但年輕是沒有錯的。",
  str_voice_1601171_4 = "覺得我變厲害了？的確，最近我有偷偷練習，果然有效。",
  str_voice_1601171_5 = "別對我的話露出那種不信任的眼神，我見過太多了。上一次有那種眼神的人，已經不幸陣亡了。",
  str_voice_1601171_6 = "沒有人可以傷害我的戰友！我必須讓牠們牢記這點！刻進牠們愚蠢的腦袋裡！",
  str_voice_1601171_7 = "戰術上詳細盤算，戰鬥中奮勇出擊。身為指揮者，你應該很瞭解這點才對，不用我多說了吧。",
  str_voice_1601171_8 = "戰鬥中太緊張的話，就和戰友閒聊幾句，開個玩笑，能讓你放鬆不少，也更能好好面對戰鬥。",
  str_voice_1601171_9 = "你在最近幾次戰鬥中指揮得很好，讓我想起之前在別動隊的日子，那時候也有你這樣的人呢。",
  str_voice_1601171_10 = "總是閒著也不好，要做點什麼呢？磨刀、清理槍機，做幾下深蹲吧。",
  str_voice_1601171_11 = "把我調來這裡嗎……嗯，看起來和剛退役那時一樣，好在我經歷過，習慣了。",
  str_voice_1601171_12 = "雖然退役了，但偶爾還是要鍛鍊戰技。畢竟還是啟光的成員，必要的警覺還是要有。",
  str_voice_1601171_13 = "要想睡得香，就要吃得飽；要想吃得飽，後勤就要好。",
  str_voice_1601171_14 = "如果你感到疲倦就要及時提出來，那是身體發出的警訊，該休息了。",
  str_voice_1601171_15 = "生日快樂！給你的生日蛋糕。啊，別用那種眼神看我，我以前當過伙房兵。",
  str_voice_1601171_16 = "雖然你是巨像的指揮者，不過看起來也很像幹後勤的嘛……在檢查物資嗎？",
  str_voice_1601171_17 = "一日之計在於晨，有個清爽的早晨是好的開始。",
  str_voice_1601171_18 = "晚上就別工作了，吃飯、放鬆，這也是為了第二天能有好精神。",
  str_voice_1601171_19 = "晚上睡不著的話，做幾個伏地挺身，再洗個澡就好了。千萬別喝酒助眠！那都是鬼話！",
  str_voice_1601171_20 = "啟光聯邦的強大就在於人人都有自己的崗位，並且盡忠職守。",
  str_voice_1601171_21 = "哼，白夜城……他們的士兵只會跟著領隊無腦衝鋒，比暗鬼強不了多少。",
  str_voice_1601171_22 = "為了啟明之光！",
  str_voice_1601171_23 = "我只想看到牠們的屍體在我們面前堆積如山的樣子。",
  str_voice_1601171_24 = "我永遠能相信大元帥，她一直帶領我們走向勝利。",
  str_voice_1601171_25 = "雷文頓嘛……這傢伙給我一種熟悉的感覺，有時候也有點分不清楚，是她、還是他。",
  str_voice_1601171_26 = "別忽略後勤的功用！能在戰場上吃到一頓熱呼呼的食物，大家不知道有多高興！",
  str_voice_1601171_27 = "再厲害的戰士也擋不了酒精的摧殘，所以離那種東西越遠越好。",
  str_voice_1601171_28 = "好大的飛行器！看樣子能運不少東西。管理起來一定很頭痛，還好不是我的事，哈哈。",
  str_voice_1601171_29 = "別拘謹！我現在退役了，而且不喜歡軍隊那一套，所以你叫我老克就好，戰鬥和後勤的事都隨便你問。",
  str_voice_1601171_30 = "找到年輕時的感覺了。",
  str_voice_1601171_31 = "露點真本事吧！老克！",
  str_voice_1601171_32 = "我會戰鬥到最後。",
  str_voice_1601171_33 = "勝利女神將對我微笑！",
  str_voice_1601171_34 = "來了，小傢伙們。",
  str_voice_1601171_35 = "一切都準備萬全了！",
  str_voice_1601171_36 = "在等待致命的瞬間！",
  str_voice_1601171_37 = "你將倒下，就是現在！",
  str_voice_1601171_38 = "火！燃燒殆盡！",
  str_voice_1601171_39 = "這只是開始——",
  str_voice_1601171_40 = "現在是終結！",
  str_voice_1601171_41 = "讓我帶領大家。",
  str_voice_1601171_42 = "現在的暗鬼太弱了。",
  str_voice_1601171_43 = "我殿後！你們走！",
  str_voice_1601171_44 = "我在戰場上的時間比你人生還長，不用管我！",
  str_voice_1601171_45 = "喔？送我這個做什麼？",
  str_voice_1601171_46 = "謝謝，你的觀察力還不錯。",
  str_voice_1601171_47 = "這是……嗯，我收下了。",
  str_voice_1601171_48 = "感謝！背後可以交給你了！",
  str_voice_1601171_49 = "有時候當個普通的後勤人員也不錯，反正老克我一開始就是做這個工作，而且比軍隊要自由得多。",
  str_voice_1601171_50 = "別動隊……就是在十幾年前那場惡戰中覆滅的。每每想起那些犧牲的戰友，我寧可代替他們去死。",
  str_voice_1601171_51 = "看到戰友們一個個死去，我一度嘗試求死，幸好布雷斯特的話讓我振作起來。現在的我，是為那些犧牲的袍澤而活。",
  str_voice_1601171_52 = "白夜極光！",
  str_voice_1601171_53 = "戰友。",
  str_voice_1601171_54 = "早安，睡得好嗎？",
  str_voice_1601171_55 = "中午最好吃飽一點。",
  str_voice_1601171_56 = "充足的睡眠是隔天的基礎。",
  str_voice_1601171_57 = "新年快樂，希望明年也能一起戰鬥。",
  str_voice_1601171_58 = "既然來到你的巨像，我就得正式向你自我介紹。",
  str_voice_1601171_59 = "多謝你提供給我的物資。",
  str_voice_1601171_60 = "你對於這些日子的訓練有什麼想法？",
  str_voice_1601171_61 = "戰爭，是很殘酷的。",
  str_voice_1601171_62 = "我考你一個問題。",
  str_voice_1601191_1 = "我很喜歡研究機械，每次都能耗上一整天，但沒有很精通。你有認識好的機械師嗎？想請教一下……",
  str_voice_1601191_2 = "你是個好人，還會駕駛巨像，那就是好導航員了！你可以叫我雷文頓，或者小雷？阿雷？總之隨便你。",
  str_voice_1601191_3 = "機械齒輪，喀嚓喀嚓。喔，是在說我的巨劍，不然你以為在說什麼……",
  str_voice_1601191_4 = "暗鬼的話，我一刀可以切成兩半，兩刀可以切成四半，三刀那就是八半了……",
  str_voice_1601191_5 = "現在拿起劍，就好像拔鴿子毛，變得非常輕盈……不過說起來，其實我好像沒有真的拔過什麼東西的毛。",
  str_voice_1601191_6 = "啊！甜美的力量氣息！什麼？說錯了？反正你懂就好了……",
  str_voice_1601191_7 = "我總覺得你感覺起來比我大很多，不是說你很老的意思。穩重？可靠？老成持重？",
  str_voice_1601191_8 = "有導航員在，即使被人誤解，我也不會弄響巨劍的鋼纜了，奇怪。",
  str_voice_1601191_9 = "別看我比你小，我很厲害的，尤其有這條機械手臂。所以打起來的時候，你就在我身後躲好。",
  str_voice_1601191_10 = "我反覆思索著要不要在巨劍上做記號，記錄我砍了幾隻暗鬼。不過數量太多了……寫不下怎麼辦？",
  str_voice_1601191_11 = "在這裡，我能做什麼？嗯……可以思考如何更有效率地砍暗鬼之類的。",
  str_voice_1601191_12 = "什麼時候會下雨？你能告訴我嗎？我很喜歡雨天，因為能免費洗澡！",
  str_voice_1601191_13 = "你有砍過暗鬼嗎？喔對了確實沒有……你都是指揮者，有空我告訴你砍暗鬼是什麼感覺。",
  str_voice_1601191_14 = "那老頭的確很會打仗，聽說之前曾殺了不少暗鬼。要不是這樣，我真的不想跟他說話，很煩。",
  str_voice_1601191_15 = "生日啊，快樂……這份勁辣年糕我就大方送給你……",
  str_voice_1601191_16 = "導航員，能見到你，做巡邏工作都更起勁了。",
  str_voice_1601191_17 = "早安……我今天準備了新的招式。",
  str_voice_1601191_18 = "太晚還是別出來亂跑，如果被上級看到，會被抓去訓話……那感覺真不好受。喔，你好像就是這裡最大的上級，那沒事了哈。",
  str_voice_1601191_19 = "怎麼，你不需要睡覺？你在陪我巡邏嗎？我有點感動……不過，其實沒這個必要啊。",
  str_voice_1601191_20 = "啟光好的一點就是，如果有人死了，會有很多人照顧他的子女，我就是這樣被啟光養大的。",
  str_voice_1601191_21 = "聽說影鎮的人做什麼都要錢，那發呆的時候也要嗎？",
  str_voice_1601191_22 = "為了啟明之光！",
  str_voice_1601191_23 = "呸，雜碎！一刀一個，還不夠我砍！",
  str_voice_1601191_24 = "維達和我差不多，她有湯喝就高興了。我呢，有暗鬼砍就爽了。",
  str_voice_1601191_25 = "那個老頭超愛多管閒事，還總以一副過來人的語氣頤指氣使，他都退役了！",
  str_voice_1601191_26 = "下雨天和勁辣年糕……我不行了……有紙巾嗎？我吸我吸。",
  str_voice_1601191_27 = "看到我的臉和手了嗎？是暗鬼弄的，所以只要見到牠們我就要一刀一個。喔，應該是一刀兩個……",
  str_voice_1601191_28 = "好大的飛行傢伙！不知道啟光有沒有，反正我是沒看過。",
  str_voice_1601191_29 = "我是雷文頓，很多人都說我很強，沒錯。你看這巨劍，別人都說重，但我揮起來就跟揮隻小刀子差不多，你看你看……",
  str_voice_1601191_30 = "再給我一點，請。",
  str_voice_1601191_31 = "像打雷那樣轟隆隆地去戰鬥！",
  str_voice_1601191_32 = "雷聲將變得更猛烈！",
  str_voice_1601191_33 = "旋轉吧！懼怕吧！",
  str_voice_1601191_34 = "領頭的一定是我。",
  str_voice_1601191_35 = "我好了！",
  str_voice_1601191_36 = "讓我出去！",
  str_voice_1601191_37 = "衝鋒在前！雷文頓！",
  str_voice_1601191_38 = "永不！滿足！",
  str_voice_1601191_39 = "衝吧！帶著電流！",
  str_voice_1601191_40 = "打倒牠們的就是我！",
  str_voice_1601191_41 = "我，理所當然。",
  str_voice_1601191_42 = "請誇獎我！",
  str_voice_1601191_43 = "我下次一定可以的！",
  str_voice_1601191_44 = "1、2、3、4、5……還有誰來著？唔，忘了，我的手下敗將數不清……",
  str_voice_1601191_45 = "謝謝！千萬別客氣！",
  str_voice_1601191_46 = "能收下嗎？我臉紅了。",
  str_voice_1601191_47 = "導航員你真好！",
  str_voice_1601191_48 = "害羞了，我！別看我！",
  str_voice_1601191_49 = "我還在上學時就打過暗鬼，臉上的疤就是那次留下的。但是我的同學卻看不慣我，都不理我了。",
  str_voice_1601191_50 = "小時候暗鬼突襲我住的地方，當時我父母都去救人了，我是被鄰居救走的。喏，左手就是那時候失去的。",
  str_voice_1601191_51 = "在看我的機械手？這是啟光幫我裝的，因為我父母都在對抗暗鬼時犧牲了，還救了不少人呢。",
  str_voice_1601191_52 = "白夜極光。",
  str_voice_1601191_53 = "你出現了！",
  str_voice_1601191_54 = "早安，導航員。",
  str_voice_1601191_55 = "午餐吃了沒？",
  str_voice_1601191_56 = "晚上作個好夢。",
  str_voice_1601191_57 = "新年快樂！新一年希望你更厲害！",
  str_voice_1601191_58 = "我來了。",
  str_voice_1601191_59 = "我的巨劍正喀喀作響……",
  str_voice_1601191_60 = "我又變強了，這是當然的。",
  str_voice_1601191_61 = "你在做什麼？",
  str_voice_1601191_62 = "你又準備去巡查巨像嗎？",
  str_voice_1601151_1 = "您問我什麼是自由？這是個好問題呢。不過在我回答之前，您不打算探索屬於自己的答案嗎？",
  str_voice_1601151_2 = "是我忘記介紹了。貝瑟是我的小鹿，辛格和波伊特是我的鵑鳥。牠們是我的言靈，更是我最真摯的朋友。",
  str_voice_1601151_3 = "紗袋裡發光的小傢伙……不是螢盞喔。牠們是螢火，跟著我從風脈之森來到這裡。",
  str_voice_1601151_4 = "坦然接受命運的那一刻，我看見時間在增長、空間在蔓延。自那以後我知道，自由已然為我開啟大門。",
  str_voice_1601151_5 = "見到納努塞爾會獲得好運……還有這種傳言嗎？如果可以，我願把這份幸運傳遞給您。",
  str_voice_1601151_6 = "我的確可以與動植物交流，就像您也擁有感應能力。這些都是自然賜予我們的天賦。",
  str_voice_1601151_7 = "如果您想見我，請在心中默念我的名字吧。自然會在冥冥之中，指引我再次來到您身邊。",
  str_voice_1601151_8 = "我請貝瑟帶我散步，沒想到居然遇見您。看來貝瑟似乎是故意的呢，牠也許很喜歡您。",
  str_voice_1601151_9 = "辛格和波伊特正在唱著關於您的歌曲呢。沒想到，您在牠們心裡也留下了深刻的印象。",
  str_voice_1601151_10 = "我從您的眼睛裡，看見一種與所有光靈都不同的光芒。可以允許我猜測您在想什麼嗎？",
  str_voice_1601151_11 = "這裡的環境比想像中愜意呢。我願意接受這份來自自然的差遣，希望我的到來不會令您失望。",
  str_voice_1601151_12 = "也許您從未留意，但自然之力一直都在身邊引導您。",
  str_voice_1601151_13 = "風告訴雲，雲告訴雨，雨告訴大地，大地告訴風……一切終有答案。",
  str_voice_1601151_14 = "您好，有要送往白夜城的信件嗎？",
  str_voice_1601151_15 = "祝您生日快樂。又成長一歲，也許您對自然也能有新的認識呢。",
  str_voice_1601151_16 = "有時我需要處理一些信使公會的緊急事務，並不棘手。您那邊呢？",
  str_voice_1601151_17 = "抱歉，吵到您了嗎？辛格和波伊特醒來後，總愛這樣放聲歌唱呢。",
  str_voice_1601151_18 = "一起走嗎？讓貝瑟也帶著您，我們去森林深處小憩片刻。",
  str_voice_1601151_19 = "竟然能在夢中與您相見……或許，您能引導我繼續走下去……",
  str_voice_1601151_20 = "我們在天地之間，以自由的方式傳遞著愛與希望。",
  str_voice_1601151_21 = "終有一天，我會回到北境，回到那片溫暖的森林。終有一天……",
  str_voice_1601151_22 = "請您相信「信使公會，使命必達」。",
  str_voice_1601151_23 = "混亂而無序……我確信牠們並非自然所孕育。",
  str_voice_1601151_24 = "女王陛下是自然之力的使者，為每一個迷途的孩子指引方向。",
  str_voice_1601151_25 = "長翅膀的小雪人？那是塔塔喔。她是個單純、善良的孩子呢。",
  str_voice_1601151_26 = "世間一切存在皆為自然之旨意，我想它們都很可愛。",
  str_voice_1601151_27 = "披肩中有母親帶給我的溫暖，因此我不再畏懼嚴寒。",
  str_voice_1601151_28 = "螢盞與螢火，您與我，巨像與自然……一切似乎妙不可言。",
  str_voice_1601151_29 = "從很久以前，我就等候著這次相會。而今，自然之力終於指引我來到您面前。幸會，我是納努塞爾。",
  str_voice_1601151_30 = "聽見了，自然的呼喚。",
  str_voice_1601151_31 = "是風的歌聲……",
  str_voice_1601151_32 = "是水的舞步……",
  str_voice_1601151_33 = "是自由的氣息……",
  str_voice_1601151_34 = "心之所向。",
  str_voice_1601151_35 = "貝瑟，我們走。",
  str_voice_1601151_36 = "等待您的指引。",
  str_voice_1601151_37 = "順其自然。",
  str_voice_1601151_38 = "與自然同往！",
  str_voice_1601151_39 = "飛舞吧。",
  str_voice_1601151_40 = "螢火之森！",
  str_voice_1601151_41 = "隨我來吧。",
  str_voice_1601151_42 = "這是自然對我們的褒獎。",
  str_voice_1601151_43 = "或許這也是自然的安排……",
  str_voice_1601151_44 = "有沒有聽見自然的呼喚？",
  str_voice_1601151_45 = "謝謝，您不必如此費心的。",
  str_voice_1601151_46 = "謝謝您的好意，我收下了。",
  str_voice_1601151_47 = "有自然的氣息呢，我很喜歡。",
  str_voice_1601151_48 = "您為何如此瞭解我的喜好……難道是自然在引導您……",
  str_voice_1601151_49 = "很小的時候，我在風脈之森遇見貝瑟、辛格、波伊特，還有這些螢火。從那以後，我們就從來沒有分開過。",
  str_voice_1601151_50 = "我從貝瑟那裡，獲知了自己的身世與使命。我必須順應自然的指引繼續向前，完成天地間的輪迴。",
  str_voice_1601151_51 = "父母把我當作親生女兒一般疼愛。雖然可以在白夜城購置許多華服，但我覺得還是母親寄來的手工衣物最舒服。",
  str_voice_1601151_52 = "白夜極光。",
  str_voice_1601151_53 = "您來了？",
  str_voice_1601151_54 = "同自然一起睜開雙眼吧。",
  str_voice_1601151_55 = "閑靜的好時光。",
  str_voice_1601151_56 = "於夢中相見。",
  str_voice_1601151_57 = "新年是新的輪迴，值得快樂地迎接。",
  str_voice_1601151_58 = "導航員，您覺得累的時候，會去哪裡？",
  str_voice_1601151_59 = "導航員，您喜歡聽歌嗎？",
  str_voice_1601151_60 = "導航員，謝謝您。",
  str_voice_1601211_1 = "帶刺的荊棘不會傷人，因為它就靜靜佇立在那裡，而某些人的言語一出口卻會血流成河。所以究竟是哪個比較可怕？",
  str_voice_1601211_2 = "我思，故我在。所以說，不思考我就不在了。那我現在不思考，導航員你還能看見我嗎？",
  str_voice_1601211_3 = "正義可能會遲到，但從不缺席。喔，不過有時候遲得太誇張了，簡直是曠職……",
  str_voice_1601211_4 = "想要看我脖子上的硬幣？可以呀，別學我用牙齒咬就好。",
  str_voice_1601211_5 = "信念是最強大的支柱。喔，不過呢，蓋房子、造橋、建神殿需要的是穩紮穩打的石頭地基。",
  str_voice_1601211_6 = "你能看見那個短髮妹？喔，我對她再熟悉不過了……",
  str_voice_1601211_7 = "審判終究會降臨。喔，如果那些惡人在審判前就掛了會怎樣？算他們逃過一劫嗎？",
  str_voice_1601211_8 = "「人無信念便為野獸。」白夜城的牧師如是說。不過呢，也有兩個詞，一個是「衣冠禽獸」，一個叫「人面獸心」呢……",
  str_voice_1601211_9 = "你去過白夜城嗎？體會到那裡的人，他們的高貴與堅定嗎？哦，真是饒富趣味……",
  str_voice_1601211_10 = "百忙不如一閒。偶爾發呆真不錯，看看硬幣，摸摸荊棘……",
  str_voice_1601211_11 = "風景不錯，令我思緒萬千，想一下如何搞些不愉快的事情給白夜城那些傢伙吧。",
  str_voice_1601211_12 = "「光之神下，眾生平等。」喔，只不過有些人比其他人更「平等」。",
  str_voice_1601211_13 = "布滿尖刺的荊棘上，也會有花朵盛開，而且很漂亮呢。你看……",
  str_voice_1601211_14 = "堅定使我們向前……但如果一開始就走錯路，豈不是越走越偏？",
  str_voice_1601211_15 = "祝你生日快樂。唉，老套的賀詞，但我想不出新的了。",
  str_voice_1601211_16 = "普通的一天開始了。喔，不普通的話，我們也不會在這裡。",
  str_voice_1601211_17 = "導航員，為什麼人們總愛說清晨很美好？要是陰天怎麼辦？",
  str_voice_1601211_18 = "傍晚結束工作，開始休息，不過那些加班的人就可憐囉。",
  str_voice_1601211_19 = "夜深人靜……或許讓人更容易思考，喔，也讓人更容易入睡。",
  str_voice_1601211_20 = "真理是找不到的，它只存在於人們的口中，可惜他們不明白。",
  str_voice_1601211_21 = "白夜城的牧師們總說信念是一種動力，但是它可沒辦法填飽人們的肚子喔。",
  str_voice_1601211_22 = "願真理祝福你，如果真有的話。",
  str_voice_1601211_23 = "光之神創造了萬物，那暗鬼是不是也是祂搞出來的？",
  str_voice_1601211_24 = "契法與我唯一的共同點就是荊棘，其他什麼也沒有了。",
  str_voice_1601211_25 = "「不要放棄！」這是韋恩的口頭禪，他也的確這麼做了，只能說他真是「幸福」。",
  str_voice_1601211_26 = "據說荊棘花象徵著命運的折磨，然而我認為它代表反抗的靈魂。",
  str_voice_1601211_27 = "虛假的信念是狂熱者的最愛。越是虛假，他們愛得越深、越瘋狂。",
  str_voice_1601211_28 = "從外面看起來很大，但內部並不寬敞，還能飛，非常有趣。",
  str_voice_1601211_29 = "我是普律瑪，命運將你我連結在一起。可是仔細想想，說不定只是湊巧罷了。總之，你好。",
  str_voice_1601211_30 = "反抗的力量，更強大了。",
  str_voice_1601211_31 = "徽章上，新的紋路。",
  str_voice_1601211_32 = "荊棘之門，為我敞開。",
  str_voice_1601211_33 = "碎裂的……過去。",
  str_voice_1601211_34 = "該我上場了？",
  str_voice_1601211_35 = "潰裂之時近了。",
  str_voice_1601211_36 = "潰裂，在等待。",
  str_voice_1601211_37 = "裂碎吧！",
  str_voice_1601211_38 = "與往昔，決裂！",
  str_voice_1601211_39 = "將如芒在身。",
  str_voice_1601211_40 = "荊棘將其沒於血色。",
  str_voice_1601211_41 = "讓我帶隊？那大家自由發揮吧。",
  str_voice_1601211_42 = "無論如何，贏了就好。",
  str_voice_1601211_43 = "撤退轉進，其疾如風！",
  str_voice_1601211_44 = "這裡……也不大嘛。",
  str_voice_1601211_45 = "喔？還可以吧。",
  str_voice_1601211_46 = "有趣，真有趣。",
  str_voice_1601211_47 = "那就謝了。",
  str_voice_1601211_48 = "原來它這麼美麗……啊，多謝！",
  str_voice_1601211_49 = "「白夜至上。」不要覺得我會說這種話很奇怪，我以前可是修女呢，想不到吧？",
  str_voice_1601211_50 = "「白夜城會庇護其子民。」喔，那為什麼會讓父母死在我面前？而且還是多虧白夜城「公正」的判決。所以說，那ˋ句話只是屁話。",
  str_voice_1601211_51 = "臨淵履薄，這就是人人稱羨的白夜城貴族生活。如果能重新選擇，我寧可當個平民。",
  str_voice_1601211_52 = "白夜極光。",
  str_voice_1601211_53 = "嗨。",
  str_voice_1601211_54 = "早安，起得真早。",
  str_voice_1601211_55 = "午休囉。",
  str_voice_1601211_56 = "願你一夜無夢。",
  str_voice_1601211_57 = "新年快樂，如果能有好事發生就更好了。",
  str_voice_1601211_58 = "導航員，我是普律瑪。",
  str_voice_1601211_59 = "你有留意過我的硬幣嗎？",
  str_voice_1601211_60 = "你是不是看到那個短髮妹了？",
  str_voice_1601211_61 = "請問，你如何理解「信念」這個詞？",
  str_voice_1601211_62 = "你看過荊棘花盛開的樣子嗎？",
  str_voice_1300651_1 = "歡迎光寧！啊不對，這裡不素雲櫻旅店。咦？這樣講也沒關係嗎？",
  str_voice_1300651_2 = "你喜翻下雪嗎？來和塔塔打雪藏吧！別擔心，偶有好多雪球哦。",
  str_voice_1300651_3 = "先森，塔塔送信來給你啦！哎呀，明明放在帽子裡滴，怎麼不見了？",
  str_voice_1300651_4 = "啊，對不起！沒嚇到你吧？這顆白色圓球素塔塔滴小山雀，不素雪球喔。",
  str_voice_1300651_5 = "塔塔捏雪球滴技素又提升啦！嗯，偶決定要按造你滴樣子，堆一豬大雪人！",
  str_voice_1300651_6 = "先森喜翻花嗎？塔塔很喜翻喔，尤其素雪花和櫻花。什麼？雪花不是花嗎……",
  str_voice_1300651_7 = "先森先森，塔塔想糾贈自己滴口音，可以請你稍微子導偶一下嗎？",
  str_voice_1300651_8 = "盧果你遇到什麼煩心素，可以告訴塔塔喔，偶會幫你分擔滴！啊，開心滴素情也可以呀！",
  str_voice_1300651_9 = "先森去雲山做客滴俗候，記得告訴塔塔喔。偶一定會請假回去糟待先森！",
  str_voice_1300651_10 = "先森，你滴信寫好了嗎？就浪塔塔幫你送信吧，馬桑就能送到喔。",
  str_voice_1300651_11 = "偶來啦！啊呀，真素葛打雪藏滴好地荒！",
  str_voice_1300651_12 = "你縮什麼？信在偶滴尾巴裡？……哇呀，真滴素耶！謝謝先森啦。",
  str_voice_1300651_13 = "小山雀告訴塔塔，牠們想念雲山的櫻花了……",
  str_voice_1300651_14 = "先森，這裡有能泡溫泉滴地荒嗎？",
  str_voice_1300651_15 = "這葛圓圓滴大雪球好看嗎？送給你，祝你森日快樂！",
  str_voice_1300651_16 = "馬桑馬桑，偶馬桑就到啦！呼～你滴信在這裡，請簽搜。",
  str_voice_1300651_17 = "早安哇！先森你還在碎懶覺滴俗候，偶就已經起床啦。",
  str_voice_1300651_18 = "又忙碌了一天，每天滴這葛俗候，都好想泡溫泉呀。",
  str_voice_1300651_19 = "先森還不碎嗎？偶滴眼睛已經增不開啦。晚……安……",
  str_voice_1300651_20 = "在這裡不但可以打工鑽錢，還能認識很膩害滴前輩！",
  str_voice_1300651_21 = "塔塔很喜翻北境喔！辣裡和雲山一樣，都素偶滴故鄉。",
  str_voice_1300651_22 = "信屬公會！郵件必達！",
  str_voice_1300651_23 = "暗鬼長滴好恐怖……不過如果要去打牠們，可以叫偶來幫忙！",
  str_voice_1300651_24 = "納努塞爾姐姐？她素偶滴女神！偶以後也要層為她辣樣滴人！嗯！",
  str_voice_1300651_25 = "屁屁前輩素葛好人，有俗候還滿造顧偶們滴。",
  str_voice_1300651_26 = "一邊泡溫泉，一邊打雪藏，一邊賞櫻花……當難可以同俗做到啦！",
  str_voice_1300651_27 = "這封信要送到紅油扳手嗎？其俗……偶有點搜不了太熱滴地荒捏。",
  str_voice_1300651_28 = "哇～偶滴小山雀以後素不素也會變辣麼大呀？",
  str_voice_1300651_29 = "先森，你好哇。還記得偶嗎，偶素塔塔呀，以後也請多多關造囉。",
  str_voice_1300651_30 = "嗚哇！偶跳滴好高！",
  str_voice_1300651_31 = "雪球更多啦！",
  str_voice_1300651_32 = "雪球更大啦！",
  str_voice_1300651_33 = "偶滴口音好像有好一點啦！",
  str_voice_1300651_34 = "偶來幫忙啦！",
  str_voice_1300651_35 = "雪人，尊備好啦！",
  str_voice_1300651_36 = "就等你叫偶啦！",
  str_voice_1300651_37 = "雪人來啦！",
  str_voice_1300651_38 = "雪人滾滾！",
  str_voice_1300651_39 = "粗偶一球！",
  str_voice_1300651_40 = "雪球風暴！",
  str_voice_1300651_41 = "塔塔一定可以滴！",
  str_voice_1300651_42 = "這素塔塔應該做滴！",
  str_voice_1300651_43 = "偶素不素幫倒忙了……",
  str_voice_1300651_44 = "先森先森，信屬公會辣邊有葛調擦表，請問你有空填一下嗎？很快就好了喔～",
  str_voice_1300651_45 = "這素……寄給偶滴？",
  str_voice_1300651_46 = "嗚哇～偶要拿回去給阿嬤看！",
  str_voice_1300651_47 = "先森，你增素葛好人！",
  str_voice_1300651_48 = "嗚嗚，這是偶搜到最好滴禮物。",
  str_voice_1300651_49 = "遙遠滴東荒，有葛美膩滴地荒叫雲山。在辣裡，雪花與櫻花一起在空中灰舞，非常漂釀……再縮下去又要想家啦。",
  str_voice_1300651_50 = "從小到大，都素鄰居阿嬤造看偶長大滴。塔塔一定要魯力工作，層為一葛膩害滴人，報答阿嬤滴恩情！",
  str_voice_1300651_51 = "別看塔塔縮話有口音，偶在大陸桑有很多好捧友喔。欸？先森你當難也素塔塔滴好捧友啦！",
  str_voice_1300651_52 = "白夜極光！",
  str_voice_1300651_53 = "偶來啦！",
  str_voice_1300651_54 = "先森，早安哇。",
  str_voice_1300651_55 = "先森，要寄信嗎？",
  str_voice_1300651_56 = "先森，要早點碎呀。",
  str_voice_1300651_57 = "新的一年，還素打雪藏最快樂！",
  str_voice_1300651_58 = "先森現在在做森麼呀？",
  str_voice_1601261_1 = "只要是自由、平等的交易，就應該受到應有的尊重與保護。所以……你願意與我商談巨像的收購事宜嗎？",
  str_voice_1601261_2 = "需求導向理論是商人必須熟記的法則。可以告訴我你負責的產業是什麼導向嗎？",
  str_voice_1601261_3 = "任何事物的成立都依循規則。無論這個規則是法律還是信用，光明還是黑暗，這都是你與生存所簽訂的契約。",
  str_voice_1601261_4 = "在不得已的情況下，契約內容可以調整。但你必須保證自己誠實、守信、不隱瞞、不欺騙。否則，誰都幫不了你。",
  str_voice_1601261_5 = "我知道你在看哪裡。不過「不能看他人的尾巴」，這是紳士應該遵守的基本禮儀。",
  str_voice_1601261_6 = "這是弗蘭克，喔，那隻也叫弗蘭克。牠們是我可愛的寵物狗，我當然分得清誰是誰。嗯？看起來不像寵物嗎？",
  str_voice_1601261_7 = "「黑斗篷的供應商」……那是我曾經的綽號。在被父親收養前的綽號。",
  str_voice_1601261_8 = "我對於某些產業深惡痛絕……那些陰影裡的東西……它們既然有辦法流通，我自然也有辦法剷除。",
  str_voice_1601261_9 = "在收購、洽談、融資、銷售、經銷這些方面我都可以協助你……還是說，其實你想要的跟我一樣是愛情小說？",
  str_voice_1601261_10 = "運輸路線、聯絡節點、預約洽談……呼，終於有空休息一下了。那就來看我最喜歡的書吧，你要一起看嗎？",
  str_voice_1601261_11 = "希望我為你提供什麼樣的商務諮詢？不過在此之前，我們最好先簽訂一份雙方都認同的合約。",
  str_voice_1601261_12 = "哦，看看是誰來了。希望透過今天的商談，我們能達成共識。",
  str_voice_1601261_13 = "是的，還在忙。很抱歉，我的助理不在，請嚴格按照預約時間會面。空裔？哪怕是空裔也不行。",
  str_voice_1601261_14 = "叮鈴叮鈴，商議結束。有誰能替我送這位貴賓回家？",
  str_voice_1601261_15 = "生日快樂！我會抽空來為你慶生——空裔的生日可是絕佳的噱頭。",
  str_voice_1601261_16 = "日安，依舊是忙碌的一天。接下來要去參加什麼商務會談嗎？",
  str_voice_1601261_17 = "早安。一杯咖啡、一份報紙，這是我的早晨標配。",
  str_voice_1601261_18 = "結束了一天的工作，睡前看點書很好，記得早點休息。",
  str_voice_1601261_19 = "咦……你、你還沒睡！？我在看什麼？這是商業機密！",
  str_voice_1601261_20 = "這裡是最理想的商業化社會，因為遵守規則的人都能在此挖掘自己的財富。",
  str_voice_1601261_21 = "僅憑配給制度，啟光的人們真的能獲得自己想要的東西嗎？",
  str_voice_1601261_22 = "影子在注視著你。",
  str_voice_1601261_23 = "牠們的出現總是會擾亂交易市場，造成高額財務損失。",
  str_voice_1601261_24 = "涉女士在商務場合還是這麼不正經……真是拿她沒辦法。",
  str_voice_1601261_25 = "不知為何，克娜莉煮的咖啡給我一種似曾相識的感覺。",
  str_voice_1601261_26 = "規則之下自由與金錢流動的聲音。呃……你、你聽誰說我在收藏愛情小說？",
  str_voice_1601261_27 = "水下的髒東西總有一天會浮上來。或者，我親自潛下去。",
  str_voice_1601261_28 = "用來運輸應該能獲得高額利潤。你真的不打算成立一家運輸公司？",
  str_voice_1601261_29 = "抱歉，久等了吧。我是影鎮總商會的負責人貝菲爾。如果有什麼事想找我商談，請先聯絡我的助理預約時間。",
  str_voice_1601261_30 = "這是等價交換吧。",
  str_voice_1601261_31 = "是……看不見的手嗎？",
  str_voice_1601261_32 = "弗蘭克似乎很享受。",
  str_voice_1601261_33 = "迫不及待，下一場風暴！",
  str_voice_1601261_34 = "希望我們合作愉快。",
  str_voice_1601261_35 = "契約將要實現。",
  str_voice_1601261_36 = "請務必馬上簽署！",
  str_voice_1601261_37 = "開始吧！廷達！",
  str_voice_1601261_38 = "狩獵吧！弗蘭克！",
  str_voice_1601261_39 = "你會哭的。",
  str_voice_1601261_40 = "舔舐淚水吧！",
  str_voice_1601261_41 = "團隊管理？沒問題。",
  str_voice_1601261_42 = "我說過我們會獲利。",
  str_voice_1601261_43 = "錯判了市場的變化……",
  str_voice_1601261_44 = "嗯……看來你也與他簽訂了什麼契約吧。",
  str_voice_1601261_45 = "不需要我付錢嗎？",
  str_voice_1601261_46 = "謝謝，我會放在辦公室。",
  str_voice_1601261_47 = "感謝，我會適時回禮。",
  str_voice_1601261_48 = "這……太合我意了，難道你其實是位作家？",
  str_voice_1601261_49 = "我母親出身白夜城，我父親是生意人。父親被那東西摧毀了精神與健康……這也是我這麼痛恨這個產業的原因。",
  str_voice_1601261_50 = "曾經，影鎮某些傢伙以「黑斗篷的供應商」來稱呼我。那時我不太懂事，還差點破壞了浮空商會的運轉體系。",
  str_voice_1601261_51 = "在一次獨自行動時，我身受重傷……機緣巧合下，我成為伊斯塔萬的養女。好在，現在我已經懂得規則的必要性了。",
  str_voice_1601261_52 = "白夜極光。",
  str_voice_1601261_53 = "嗯？",
  str_voice_1601261_54 = "無利不起早。",
  str_voice_1601261_55 = "中午也在忙？",
  str_voice_1601261_56 = "商店都關門了。",
  str_voice_1601261_57 = "新的一年，祝我們依舊合作順利。",
  str_voice_1601291_1 = "新的委託是什麼？什麼時間要交付？請放心，我接下的委託一定會完成。",
  str_voice_1601291_2 = "影鎮沒有必須執行的法律或需要熟記的生存法則——這裡只有信用。遵守信用，才是我始終能站在這裡的原因。",
  str_voice_1601291_3 = "要讓更多人知道我們，讓他們相信我們的能力，我們要成為更有影響力的組織……嗯？抱歉，我沒注意到你在這裡。",
  str_voice_1601291_4 = "更多委託就意味著傭兵團需要更多人……但也意味著更多的傷亡。不過在現在這個階段，總得學會取捨。所以，還是多接一些委託吧。",
  str_voice_1601291_5 = "你在看我的披風嗎？實不相瞞，這是我自己畫的。如果你也喜歡的話，等我處理完這份委託，可以為你也繪製一件。",
  str_voice_1601291_6 = "白火傭兵團是靠著信用在影鎮立足，這與那些以公權力為導向的組織或國家天差地別。",
  str_voice_1601291_7 = "你……是在看我的面具嗎？我從很小的時候就戴著它了，也算是一位長輩留給我的紀念品。",
  str_voice_1601291_8 = "我曾經對地下產業非常反感……但人總是要成長，合作帶來的利潤確實很龐大。我手下也有很多人要靠這個吃飯。",
  str_voice_1601291_9 = "我能為你畫一幅肖像畫嗎？可別小看我的繪畫能力，有時候我就是靠著這個手藝才能跟那些地下幫派達成交易。",
  str_voice_1601291_10 = "是說，你這裡真乾淨，可以讓我的夥伴出來玩一下嗎？呃……但是不知道你會不會害怕牠們。",
  str_voice_1601291_11 = "請等我交接完最後一項……好了，現在可以全心全意執行你的委託了。",
  str_voice_1601291_12 = "我非常尊重影鎮的規則。雖然有些交易……算了，也正是因為這樣，傭兵團才有立足之地。",
  str_voice_1601291_13 = "我在這裡看到一些會飛的小東西……莫非你跟我擁有相同的喜好嗎？",
  str_voice_1601291_14 = "我很感激白火傭兵團團長過去對我的照顧與提攜，沒有他就不可能有今天的我。",
  str_voice_1601291_15 = "今天是你誕生的日子，路克攜白火傭兵團為你送上真摯的祝福。",
  str_voice_1601291_16 = "你一定在認真工作吧？請注意勞逸結合。放鬆方法的話……你想欣賞蝴蝶嗎？",
  str_voice_1601291_17 = "早安，很高興在這時候見到你。這代表你的作息與傭兵不同，你很健康。",
  str_voice_1601291_18 = "夜幕升起……也是完成委託的好時機。",
  str_voice_1601291_19 = "夜深了，你一定很清楚，不是所有生物都適合在這個時間保持清醒。",
  str_voice_1601291_20 = "影鎮很自由，但自由該不該有界線？沒有定論。",
  str_voice_1601291_21 = "軍人與傭兵，二者相去甚遠。因為執行命令是強制的，而遵守信用是自發的。",
  str_voice_1601291_22 = "影子……無處不在，注視著你。",
  str_voice_1601291_23 = "抱歉，但暗鬼對我來說算不上生命，我只想看到牠們的屍體。",
  str_voice_1601291_24 = "艾爾戈絲喜歡有年代感的東西，這點我在很早以前就發現了。",
  str_voice_1601291_25 = "伊斯塔萬……無論是幫派間的平衡，還是與人之間的交際手段，他身上有很多值得我學習的地方。",
  str_voice_1601291_26 = "昆蟲與光靈一樣是自然的產物，所有生物都該擁有羽化成蝶的權利。",
  str_voice_1601291_27 = "不尊重生命的人不配活著。任何生命皆然。",
  str_voice_1601291_28 = "聽說這是機械與生命的混合體？真是偉大的構造。",
  str_voice_1601291_29 = "你好，我是路克。有什麼事需要白火傭兵團的幫助嗎？請放心，我經手的委託一定會完成。",
  str_voice_1601291_30 = "白火傭兵團，變得更強了。",
  str_voice_1601291_31 = "牠們無聲無息地簇擁著我。",
  str_voice_1601291_32 = "隨心而聚！",
  str_voice_1601291_33 = "新的生命……不斷誕生！",
  str_voice_1601291_34 = "你的委託，求之不得。",
  str_voice_1601291_35 = "生命永不止息！",
  str_voice_1601291_36 = "牠們歸我支配！",
  str_voice_1601291_37 = "窒息在這力量之下！",
  str_voice_1601291_38 = "鎖鏈！展開！",
  str_voice_1601291_39 = "霧，宣告死亡。",
  str_voice_1601291_40 = "消除吧！",
  str_voice_1601291_41 = "我會壯大這支隊伍。",
  str_voice_1601291_42 = "這就是傭兵團的力量。",
  str_voice_1601291_43 = "……我還要更加努力。",
  str_voice_1601291_44 = "這裡或許能用來當做傭兵們的聯絡站。",
  str_voice_1601291_45 = "謝謝，我會擺在我的辦公桌上。",
  str_voice_1601291_46 = "無論什麼委託，我都會把它帶在身邊。",
  str_voice_1601291_47 = "是我一直很想要的……不知道該怎麼感謝你才好。",
  str_voice_1601291_48 = "這會成為我的珍藏，請務必給我回禮的機會。",
  str_voice_1601291_49 = "等待的滋味很不好受，尤其是得知你所等待的人，再也不會回來時。好在那些日子已經過去了，我再也不會夢到那個晚上了。",
  str_voice_1601291_50 = "團長不僅是稱職的養父，更是稱職的領導者。在他的教誨下，我深切地明白——言不信者，行不果。",
  str_voice_1601291_51 = "好奇我能力的由來嗎？其實很簡單——因為我尊重生命，生命也尊重我。我與所有生命共生。",
  str_voice_1601291_52 = "白夜極光。",
  str_voice_1601291_53 = "你好。",
  str_voice_1601291_54 = "早，我已經在工作了，你一定也是吧。",
  str_voice_1601291_55 = "午時應當沉浸在自然氣息中。",
  str_voice_1601291_56 = "晚安，蟲鳴伴你安眠。",
  str_voice_1601291_57 = "新年快樂，希望新的一年一切都會更順利。",
  str_voice_1500551_1 = "若有糾紛，請到審判庭見我。「程序是正義的蒙眼布」，所以我不會偏袒任何一方。",
  str_voice_1500551_2 = "偉大的光之神是萬事萬物的創造者、我等生靈的救世主，這點不容置疑。沒有什麼難以理解的，銘記在心即可。",
  str_voice_1500551_3 = "想旁聽我主持的審判？抱歉，我無法帶你入場，你必須自行前往審判庭登記並查驗身分。規則就是規則，無法打破。",
  str_voice_1500551_4 = "每當我握緊手中的權杖，父親的聲音就在我耳邊迴盪。「彼亞塔曼家不能有兩個男人同時上戰場」，他那時候這麼對我說。",
  str_voice_1500551_5 = "我去過前線，在硝煙瀰漫的戰場上留過汗與血。故我深刻地明白，一切都得來不易。",
  str_voice_1500551_6 = "嗯？被你發現也無妨。這個動力骨骼是啟光為我友情訂做的，否則我整個左臂都無法保住。",
  str_voice_1500551_7 = "比起精進自己的能力，很多人更喜歡藉由政治手腕達成目的。在我來看，也許你與那些人不同。",
  str_voice_1500551_8 = "若你早些年能在黎明學院學習，應該也是成績名列前茅的傑出學生吧。當然，現在也還不算太晚。",
  str_voice_1500551_9 = "上一個令我如此欽佩的人，是審判長大人。後生可畏！今後你會如何成長，著實令人期待。",
  str_voice_1500551_10 = "捉拿在逃的罪人，是我還算喜歡的休閒活動。你也有興趣嗎？不過，還是把體格練好再來找我吧。",
  str_voice_1500551_11 = "只要有可以供我閱讀卷宗的工作桌，在哪裡我都無所謂。嗯，這裡很寬敞，甚合我意。",
  str_voice_1500551_12 = "光之神下，眾生平等。我們每個人都有機會獲得神的恩典。",
  str_voice_1500551_13 = "不公正的事情還有很多，正如我遊記裡所記載的那樣。但那又如何？反正我會一一解決。",
  str_voice_1500551_14 = "遵循光之神的指引吧。神將使你看見本心——與人為善也與己為善。",
  str_voice_1500551_15 = "生日快樂，光之神自會保佑守法者喜樂平安。",
  str_voice_1500551_16 = "現在是工作時間，若是與工作無關的話題，還請留到休息時間再談。",
  str_voice_1500551_17 = "早安，趁著頭腦清晰，此時我會在腦中梳理那些未決之案。",
  str_voice_1500551_18 = "一天即將結束。如果可以，我還想要更多時間。",
  str_voice_1500551_19 = "你也要熬夜？這樣的作息可不是任何人都能承受。",
  str_voice_1500551_20 = "如我們永恆的光之神一樣，白夜城永不陷落！",
  str_voice_1500551_21 = "真理結社？竟敢使用「真理」二字混淆視聽，光之神不會寬恕他們。",
  str_voice_1500551_22 = "白夜至上！",
  str_voice_1500551_23 = "如果見到暗鬼，我會將其就地正法。牠們無需審判，即可認定有罪。",
  str_voice_1500551_24 = "那時的我怎樣都想不到，她居然會成為真理結社的一員……",
  str_voice_1500551_25 = "學院的前輩、工作的上司……審判長大人總是走在前方，令我望塵莫及。",
  str_voice_1500551_26 = "各歸其位、各司其職，秩序帶來的美感無可取代。",
  str_voice_1500551_27 = "無視一切規則、制度與法律的行為，令人厭惡。",
  str_voice_1500551_28 = "目前還沒有巨像相關的法律規範，看來是時候著手制定了。",
  str_voice_1500551_29 = "既然光之神安排我們相識，那麼……你好，我是韋恩·彼亞塔曼，一名審判官，任職於白夜城審判庭。",
  str_voice_1500551_30 = "這是有序地成長。",
  str_voice_1500551_31 = "力量……充滿全身！",
  str_voice_1500551_32 = "雷電為我而鳴。",
  str_voice_1500551_33 = "罪惡，無所遁形！",
  str_voice_1500551_34 = "求之不得。",
  str_voice_1500551_35 = "肅靜！",
  str_voice_1500551_36 = "保持冷靜！",
  str_voice_1500551_37 = "宣判！有罪！",
  str_voice_1500551_38 = "無處可逃！",
  str_voice_1500551_39 = "伏法！",
  str_voice_1500551_40 = "懲罰！",
  str_voice_1500551_41 = "我自會秉公判斷。",
  str_voice_1500551_42 = "公正的判決！",
  str_voice_1500551_43 = "調查得還不夠……",
  str_voice_1500551_44 = "我需要一處靜謐的祈禱之所。",
  str_voice_1500551_45 = "這是……作為朋友的禮物？",
  str_voice_1500551_46 = "謝謝，費心了。",
  str_voice_1500551_47 = "我收下了，多謝。",
  str_voice_1500551_48 = "很實用，我喜歡。",
  str_voice_1500551_49 = "那時我只能終日臥床，是光之神拯救了我。光之神以善照亮我，又指引我將其播撒於大地……我想，我應該沒有辜負神的旨意。",
  str_voice_1500551_50 = "影鎮的那夜我永生難忘。同僚在身旁相繼死去，無力感釘死我的腳趾，每根髮絲都在哭叫……我會找到真相，我只能找到真相！",
  str_voice_1500551_51 = "閱讀卷宗總能帶來意想不到的發現。不僅能幫助我工作，還能幫我查明叛亂的真相。當然，看看那些不同地區的判決也很有意思。",
  str_voice_1500551_52 = "白夜極光！",
  str_voice_1500551_53 = "請注意。",
  str_voice_1500551_54 = "早！",
  str_voice_1500551_55 = "進展如何？",
  str_voice_1500551_56 = "天黑了？",
  str_voice_1500551_57 = "遵紀守法，從新年開始。",
  str_voice_1601231_1 = "怎麼怎麼？遇到什麼麻煩了嗎？儘管交給我吧！",
  str_voice_1601231_2 = "早餐三塊麵包配一杯紅茶，午餐一份啟光工作餐，外加兩個布丁一個罐頭……啊……今天晚上只能吃蘋果了……",
  str_voice_1601231_3 = "噢！這是啟光治安官的統一工作服，是通過實習考核才可以穿上的正式服裝喔！但無論怎麼說……您也盯我盯太久了吧！",
  str_voice_1601231_4 = "治安官守則第一！維護安全，制止破壞秩序的行為！我手上的棍子可不是裝飾品！",
  str_voice_1601231_5 = "治安官守則第二！維護交通秩序，處理交通事故……唔……但是巨像適用交通法規嗎？",
  str_voice_1601231_6 = "治安官守則第三！執行任務時，要尊重並維護每個人的尊嚴……但是，暗鬼就不在這個保護範疇內了吧。",
  str_voice_1601231_7 = "治安官就是負責幫助他人、守護正義的職業，幫助您、關心您同樣是我的職責！",
  str_voice_1601231_8 = "能夠幫助到您，我自己也非常開心……不完全是出於工作啦……",
  str_voice_1601231_9 = "來協助我完成助人為樂的任務吧，今天還差最後一個呢！希望我做什麼就直接說吧～快努力想想呀，導航員。",
  str_voice_1601231_10 = "唉，把我叫過來卻什麼都不用做嗎？……我明白了，等待也是一種工作，柯蒂治安官隨時待命！",
  str_voice_1601231_11 = "來了來了，啟光聯邦治安官報到！",
  str_voice_1601231_12 = "唔……請先不要打擾我，每天巡邏日報可不能出錯。",
  str_voice_1601231_13 = "這點小事應該的啦，這也是您信任我的表現。",
  str_voice_1601231_14 = "嗯嗯，我有在聽喔！別著急，您慢慢說吧。",
  str_voice_1601231_15 = "生日快樂！生日願望是什麼呢？讓我幫您實現吧！",
  str_voice_1601231_16 = "接下來要做什麼呢，導航員？助人為樂的工作永無止境。",
  str_voice_1601231_17 = "早安，導航員！您昨晚睡得好嗎？吃早餐了嗎？咦？沒睡飽嗎……？",
  str_voice_1601231_18 = "晚安！今天也是充實的一天。",
  str_voice_1601231_19 = "現在已經到就寢時間了，您怎麼還——難道有什麼突發事件嗎？",
  str_voice_1601231_20 = "啟光的組織結構極為複雜，維護這裡的秩序並不是什麼輕鬆的事。",
  str_voice_1601231_21 = "我沒有不喜歡影鎮的人。好吧，只有一點點，也可能是我懷有成見……",
  str_voice_1601231_22 = "為了……啟明之光！",
  str_voice_1601231_23 = "欺負弱小、破壞秩序的傢伙，就應該得到應有的制裁！",
  str_voice_1601231_24 = "沒有長官的特別信任，我沒辦法從事這份夢想中的工作。",
  str_voice_1601231_25 = "我不想對那個人多作評論，但她身上確實有一部分我認同的東西。",
  str_voice_1601231_26 = "我喜歡幫助別人以及計算食物的熱……沒、沒什麼！您沒聽到吧？",
  str_voice_1601231_27 = "制定好的計畫被打亂，這種事情最討厭了！",
  str_voice_1601231_28 = "哇？這架鋼琴少說也有一天沒擦了吧……還有那些隨意堆放的雜物……都包在我身上吧，導航員！",
  str_voice_1601231_29 = "啟光治安官柯蒂，熱心為您服務！我能為您做點什麼嗎，導航員？",
  str_voice_1601231_30 = "晉、晉升？您認可我的工作能力了嗎？",
  str_voice_1601231_31 = "交、交給我沒問題嗎？",
  str_voice_1601231_32 = "感謝您的信任！……我會努力加油的！",
  str_voice_1601231_33 = "我似乎也感覺到有所成長了呢。",
  str_voice_1601231_34 = "現在可以前進了哦！",
  str_voice_1601231_35 = "隨、隨時待命！",
  str_voice_1601231_36 = "嗚……接下來就——",
  str_voice_1601231_37 = "治安官的制裁！",
  str_voice_1601231_38 = "我手上的棍子可不是裝飾品喔！",
  str_voice_1601231_39 = "雷電！火焰！",
  str_voice_1601231_40 = "執行！特殊任務！",
  str_voice_1601231_41 = "啟光治安官，出動！",
  str_voice_1601231_42 = "圓滿達成任務！",
  str_voice_1601231_43 = "對不起……是我的失誤……",
  str_voice_1601231_44 = "啟光聯邦治安官，熱心為您服務……哇！痛痛痛……",
  str_voice_1601231_45 = "如果您實在想道謝，就寄一封感謝信去治安隊吧～",
  str_voice_1601231_46 = "咦？特地送給我的嗎……？是花費不少心思的禮物呢！",
  str_voice_1601231_47 = "您這份心意比禮物更珍貴。",
  str_voice_1601231_48 = "謝謝！我真的好喜歡！",
  str_voice_1601231_49 = "您很在意嗎？我的體型……以前也被人嘲笑過……不過我現在已經沒關係了！",
  str_voice_1601231_50 = "幫助弱小、守護正義，這是我一直以來的夢想。",
  str_voice_1601231_51 = "如果不得不派遣我前往新的戰場，我一定會全力以赴……就像上次那樣。",
  str_voice_1601231_52 = "白夜極光！",
  str_voice_1601231_53 = "需要幫忙嗎？",
  str_voice_1601231_54 = "啟光聯邦治安官之禮！",
  str_voice_1601231_55 = "午安！有什麼困擾嗎？",
  str_voice_1601231_56 = "晚安，您辛苦了。",
  str_voice_1601231_57 = "新年快樂——！",
  str_voice_1500151_1 = "-想買畫就來找我們吧，買畫的過程中也可以委託一些附加服務唷！\n-最後和畫錢一起結算。",
  str_voice_1500151_2 = "-嗅嗅、嗅嗅……好像聞到了白夜幣的味道……",
  str_voice_1500151_3 = "-我們不生產藝術！\n-我們只是藝術的「搬運工」！",
  str_voice_1500151_4 = "-循規蹈矩的東西賣不出去啦～讓銀城幫你把這台鋼琴畫點塗鴉吧？\n-人家沒有想賣。",
  str_voice_1500151_5 = "-這些積壓的畫，只有真正懂藝術的人才能看出其中的價值。如何，我來向你說明吧？\n-人家也沒有要買。",
  str_voice_1500151_6 = "-從來沒換過的衣服、平凡的髮型……要不要我教你一些抓頭髮的訣竅？",
  str_voice_1500151_7 = "-一些複雜、偉大、高級的主題，往往需要用更簡單、直接的方式描述……\n-所以待會要吃什麼？",
  str_voice_1500151_8 = "-你問簽好的訂單運輸失敗怎麼辦？這可是商業機密！多虧銀城那傢伙有臨摹的本事……\n-你已經說出來了……",
  str_voice_1500151_9 = "-一根棒棒糖，在雪地裡走著走著，就變成了——冰爆棒棒糖！……不好笑嗎？這是加入表演的改良版啊！",
  str_voice_1500151_10 = "-一直待著不動的話……\n-訂單可不會自己跑來……",
  str_voice_1500151_11 = "-尋、覓、商、機、中！",
  str_voice_1500151_12 = "-哈啾……蜂那傢伙，用完髮膠從來不把蓋子蓋好。",
  str_voice_1500151_13 = "-別看我們這樣，高強度的傭兵工作我們也能完全勝任。",
  str_voice_1500151_14 = "-一名合格的畫商有時還需要懂第二外語……喵。呃，不好笑嗎？",
  str_voice_1500151_15 = "-生日快樂！多叫幾個有錢的朋友來開生日派對吧？\n-首先要有朋友。",
  str_voice_1500151_16 = "-薄荷冰爆棒棒糖，提神醒腦有益健康。來一根？",
  str_voice_1500151_17 = "-等、等一下！先別看我。我的髮膠呢！",
  str_voice_1500151_18 = "-散步時間到——！\n-……他追不上了，我們是不是跑太快了？",
  str_voice_1500151_19 = "-哈啊……狗在晚上需要睡覺，這天經地義。",
  str_voice_1500151_20 = "-我們還是比較習慣單槍匹馬。商會的人很麻煩，光仲介費就會撈一大筆。",
  str_voice_1500151_21 = "-不管是暴發戶還是裝模作樣的貴族，他們的藝術審美觀都平庸得很一致嘛！",
  str_voice_1500151_22 = "-影子在注視著你……\n-商機也是喔！",
  str_voice_1500151_23 = "-一群沒有品味與自我意識的雜碎……\n-只有被人利用的下場。",
  str_voice_1500151_24 = "-從某種角度來說……伊斯塔萬老闆是我們另一個「老師」。",
  str_voice_1500151_25 = "-沒想到那位看起來一本正經的貴族小姐也會幫我們一把！",
  str_voice_1500151_26 = "-二、三、四、五、六、七……數著戶頭裡有幾個零當然是最有意思的事！",
  str_voice_1500151_27 = "-最討厭接紅油沙漠的單子。白天好熱，晚上又好冷。",
  str_voice_1500151_28 = "-這面牆的設計能有效放大空間視覺……嗯？本來就有另一個房間嗎！",
  str_voice_1500151_29 = "-蜂！\n-銀城。\n-我們是天才畫商與臨時僱傭兵！\n-錯了，是天才僱傭兵和業餘畫商。",
  str_voice_1500151_30 = "-手上的傢伙好像更好用了！",
  str_voice_1500151_31 = "-有靈感了！",
  str_voice_1500151_32 = "-識貨！",
  str_voice_1500151_33 = "-喜歡你的品味！",
  str_voice_1500151_34 = "-訂單確認！",
  str_voice_1500151_35 = "-彈藥裝填！",
  str_voice_1500151_36 = "-瞄準完畢。",
  str_voice_1500151_37 = "-嚐嚐這個！",
  str_voice_1500151_38 = "-納命來吧！",
  str_voice_1500151_39 = "-真難看啊！",
  str_voice_1500151_40 = "-倒得漂亮。",
  str_voice_1500151_41 = "-只要有我們兩個就沒問題！",
  str_voice_1500151_42 = "-來了！\n-地獄訂單送達！",
  str_voice_1500151_43 = "-小傷，舔一舔就好！",
  str_voice_1500151_44 = "-買下這個大玩意應該要不少錢吧？",
  str_voice_1500151_45 = "-比起這個，再來點棒棒糖吧！",
  str_voice_1500151_46 = "-品味不錯哦！",
  str_voice_1500151_47 = "-還不如搔搔下巴。\n-來吧——",
  str_voice_1500151_48 = "-別猶豫了，招待你一次專人運送！\n-免費喔！",
  str_voice_1500151_49 = "-抓高頭髮是一位成功人士該有的品味！而且，抓高三公分之後我不就跟銀城一樣高了嗎……沒有嗎？！\n-完全沒有。",
  str_voice_1500151_50 = "-我很清楚這是什麼樣的工作，銀城那傢伙的實力也不該僅止於模仿……但在賺夠白夜幣之前，我們不會停手。",
  str_voice_1500151_51 = "-有時候會夢到一些以前的事：湛藍色的天空畫，占據整面牆的畫布……養父的身影依舊如此熟悉……",
  str_voice_1500151_52 = "-白夜！\n-極、光。",
  str_voice_1500151_53 = "-唷！來啦。",
  str_voice_1500151_54 = "-早安！",
  str_voice_1500151_55 = "-走，去吃肉吧！",
  str_voice_1500151_56 = "-睡前要出去晃晃嗎？",
  str_voice_1500151_57 = "-新年快樂！\n-至少今天要快樂！",
  str_voice_1601201_1 = "我知道，你一定是在好奇經常在我左右的巨型騎士。你可以叫他龐佩，也可以稱他「光明騎士」。",
  str_voice_1601201_2 = "對不起，我還不太習慣與人頻繁交流。你的意思是，以後我們更熟悉，就會好轉嗎？那就請你加油吧。",
  str_voice_1601201_3 = "獨處是一種境界，一種對自己更高的要求。唯有獨處能告訴我，自己內心的渴求。",
  str_voice_1601201_4 = "白夜城之外的世界……我已經從書中讀到很多。而也許有朝一日，我也可以親眼去見識。",
  str_voice_1601201_5 = "只要付出努力，沒有什麼書籍無法讀懂。知道嗎？最難讀懂的，其實是自己。",
  str_voice_1601201_6 = "原來你也曾經習慣獨自一人……那你後來怎麼交到這麼多朋友？別誤會，只是有點好奇罷了。",
  str_voice_1601201_7 = "從高處俯瞰街道與人群，你就會明白，人與人之間的悲喜並不相通。",
  str_voice_1601201_8 = "你可以多去看看白夜城相關的歷史研究。因為……因為這樣我們才能有更多共同語言。",
  str_voice_1601201_9 = "書上說，互相幫助才能稱得上是「朋友」。所以你打算幫我什麼嗎？嗯……需要的話我也會幫你。",
  str_voice_1601201_10 = "我知道，在房間裡待久了的確有點悶。這種時候，我會請龐佩帶我去屋頂看看天空和雲彩。",
  str_voice_1601201_11 = "嗯……這地方倒是很安靜，只要我待在這裡就可以了嗎？好吧，那你可不准再叫別人過來。",
  str_voice_1601201_12 = "白夜至上。我知道白夜城的信念可以拯救所有光靈……以及空裔。",
  str_voice_1601201_13 = "蒐集佚失的書卷，就好像拼圖。對我來說，這是一種遊戲。",
  str_voice_1601201_14 = "該幫龐佩塗潤滑油了。嗯……也順便拋光一下好了。",
  str_voice_1601201_15 = "嗯……生日派對我就不去了，提前祝你生日快樂。",
  str_voice_1601201_16 = "我找到一篇精彩的文章！裡面寫道……啊，或許你並不感興趣。",
  str_voice_1601201_17 = "每日此時，正是天空雲彩最美的時候。你不想看看嗎？",
  str_voice_1601201_18 = "什麼！你的晚餐只有三道菜嗎？真是難以想像……",
  str_voice_1601201_19 = "我也有好幾次忘記睡覺呢，都是因為看書太入迷。你今天是？",
  str_voice_1601201_20 = "世界的中心，光靈的頂點……最適合我生活的地方。",
  str_voice_1601201_21 = "遙遠的北方，那片流星劃過的天空下，是否還住著最初的光之子……",
  str_voice_1601201_22 = "白夜至上。",
  str_voice_1601201_23 = "那些骯髒醜陋的東西嗎？我當然知道。那些東西不配存在於世上。",
  str_voice_1601201_24 = "舒瓦茲殿下，引領白夜城繼續走在正道上的城主，我最尊敬的人。",
  str_voice_1601201_25 = "我當然知道卡蓮殿下。畢竟她是為數不多，可與我匹敵的同齡人。",
  str_voice_1601201_26 = "我喜歡閱讀。書籍、物品……甚至是光靈，都在我的閱讀範圍內。",
  str_voice_1601201_27 = "團體活動？從來沒參加過……可、可能我對人群過敏吧。",
  str_voice_1601201_28 = "我早就知道世上有這樣的造物，但沒想到竟然比龐佩還要巨大。",
  str_voice_1601201_29 = "光明騎士的傳說，將由我來續寫……啊，你就是空裔吧。白夜至上，海蒂·布萊德向你問安。",
  str_voice_1601201_30 = "我獲得了這股力量……你是怎麼做到的？",
  str_voice_1601201_31 = "可以去，更遠的地方。",
  str_voice_1601201_32 = "看見了……光明騎士之路。",
  str_voice_1601201_33 = "未來，隨之改變。",
  str_voice_1601201_34 = "嗯？好吧。",
  str_voice_1601201_35 = "可以開始了。",
  str_voice_1601201_36 = "總算輪到我了。",
  str_voice_1601201_37 = "光明騎士，與我同在！",
  str_voice_1601201_38 = "黑暗無所遁形！",
  str_voice_1601201_39 = "出來吧，龐佩！",
  str_voice_1601201_40 = "感到榮幸吧！",
  str_voice_1601201_41 = "我會讓一切馬上結束。",
  str_voice_1601201_42 = "對光明騎士來說，這不值得一提。",
  str_voice_1601201_43 = "屈辱的一戰……我不接受！",
  str_voice_1601201_44 = "嗯……那件事，還需要仔細斟酌一下。",
  str_voice_1601201_45 = "這是什麼……？我當然知道這是禮物！",
  str_voice_1601201_46 = "嗯……謝謝你，讓你費心了。",
  str_voice_1601201_47 = "一定要當面給我嗎？沒、沒什麼……",
  str_voice_1601201_48 = "你知道嗎……我很喜歡這份禮物！",
  str_voice_1601201_49 = "幸福有時會蒙蔽人的雙眼。我曾以為每個人都擁有專屬的家庭教師……也曾以為每個人都習慣獨自一人。",
  str_voice_1601201_50 = "夢境裡的惡魔張牙舞爪，那麼真實、那麼恐怖，彷彿要將我一口吞下……唯有書籍，能讓我從中解脫。",
  str_voice_1601201_51 = "又是那個熟悉的夢境。不同的是，這次有一位身穿白甲的騎士從光芒中走出來，驅散我眼前的黑暗。",
  str_voice_1601201_52 = "白夜極光。",
  str_voice_1601201_53 = "我知道……",
  str_voice_1601201_54 = "祝你早安。",
  str_voice_1601201_55 = "祝你日安。",
  str_voice_1601201_56 = "祝你晚安。",
  str_voice_1601201_57 = "新的一年，祝你一切平安。",
  str_voice_1601311_1 = "沒有任何儀式的生活，就像黑夜缺少星光、旅人迷失方向……多麼乏味啊。",
  str_voice_1601311_2 = "噓……聲音太大會嚇到我身旁的小兔子喔。",
  str_voice_1601311_3 = "不管是已經發生的事，還是未曾發生的事，我們都可以從歷史的篇章中覓得真知。",
  str_voice_1601311_4 = "一成不變的日子可不是壞事。要知道，曾經有太多同胞犧牲，只為了替後人求得安穩。",
  str_voice_1601311_5 = "唉呀？兔子家族又有新成員了嗎……小兔子乖乖，稍等片刻，我馬上準備香甜的胡蘿蔔。",
  str_voice_1601311_6 = "能力越強，責任越大。我不會逃避，更不會忘記初心。守護北境之心，只會更加堅強。",
  str_voice_1601311_7 = "閣下不必如此拘謹。有任何問題都可以問我，我一定會盡力給您滿意的答覆。",
  str_voice_1601311_8 = "有時候，您身上美好的特質會讓我想起一位許久未見的故人……多希望還能再見到她。",
  str_voice_1601311_9 = "建立儀式感其實很簡單。比如……可以將我與閣下相遇的日子，設定為屬於我們的友誼紀念日。",
  str_voice_1601311_10 = "您覺得無聊嗎？我可以講些北境的歷史小故事，也許能為您解悶呢。",
  str_voice_1601311_11 = "嗯？充滿儀式感的任命過程。哈哈，我非常樂意為您效勞。",
  str_voice_1601311_12 = "有時我能聽見山川向我傾訴。它們的語言很緩速，卻那樣勾人。",
  str_voice_1601311_13 = "小心喔，軟萌的小白兔生氣時也是會咬人的。",
  str_voice_1601311_14 = "每一個平凡的日子，都值得紀念。",
  str_voice_1601311_15 = "在這個屬於您的日子裡，我要送您一句古老的咒語……生日快樂！",
  str_voice_1601311_16 = "嗯～沒發生什麼事呢。這是最簡單的幸福，不是嗎？",
  str_voice_1601311_17 = "伸個懶腰或深呼吸……最簡單的儀式，就能開啟美好的一天。",
  str_voice_1601311_18 = "您忙完工作了嗎？也許我可以為您安排一場洗滌心靈的儀式？",
  str_voice_1601311_19 = "唉呀，這麼晚還沒睡嗎？莫非您在進行什麼禁忌的儀式？",
  str_voice_1601311_20 = "我每天都深深慶幸，自己能生活在這片潔白的大地上。",
  str_voice_1601311_21 = "無論啟光還是白夜城，都有屬於他們的生存之道。",
  str_voice_1601311_22 = "暮冬而生。",
  str_voice_1601311_23 = "沒有思想、唯有蠻力，可憐可悲的造物罷了。",
  str_voice_1601311_24 = "人們只看到女王的強大，卻不明白她為了守護北境付出的種種代價……",
  str_voice_1601311_25 = "在尊敬女王陛下這件事情上，娜席里絲可說是無可挑剔。",
  str_voice_1601311_26 = "嗯……就是因為生長在雪國，所以才更珍惜陽光帶來的溫暖。",
  str_voice_1601311_27 = "哈哈，千萬不要讓我聽到有誰在講女王陛下的壞話喔。",
  str_voice_1601311_28 = "歷史記載中的龐然大物，沒想到有生之年能看到實物。",
  str_voice_1601311_29 = "我是北境的子民——諾維亞，已在此恭候閣下多時。今日天氣甚好，莫非是為了歡迎閣下的到來？",
  str_voice_1601311_30 = "唉呀？溫暖的感覺……",
  str_voice_1601311_31 = "藍火在心中燃燒。",
  str_voice_1601311_32 = "歷史……在眼前重現。",
  str_voice_1601311_33 = "值得紀念的成長！",
  str_voice_1601311_34 = "走吧。",
  str_voice_1601311_35 = "已經準備妥當。",
  str_voice_1601311_36 = "在此恭候。",
  str_voice_1601311_37 = "需要一點儀式感。",
  str_voice_1601311_38 = "山川靈杖，賜我力量！",
  str_voice_1601311_39 = "我一直都在。",
  str_voice_1601311_40 = "不必再害怕。",
  str_voice_1601311_41 = "我的榮幸。",
  str_voice_1601311_42 = "一場完美的儀式！",
  str_voice_1601311_43 = "無法改寫的遺憾之章……",
  str_voice_1601311_44 = "也得瞭解一下這裡的歷史。",
  str_voice_1601311_45 = "您不必如此客氣。",
  str_voice_1601311_46 = "謝謝，讓您費心了。",
  str_voice_1601311_47 = "這個，要準備很久吧？",
  str_voice_1601311_48 = "我需要仔細思考如何回禮。",
  str_voice_1601311_49 = "那時的北境和現在沒有什麼不同，所有人都相信我是「山靈」，除了我自己……",
  str_voice_1601311_50 = "如何守護重要的人，守護這片寧靜的大地？我一直在思考這個問題，思考太多年了。",
  str_voice_1601311_51 = "這片刻的寧靜，已經是最珍貴的禮物。我想，我已經找到守護北境的方式了。",
  str_voice_1601311_52 = "白夜極光。",
  str_voice_1601311_53 = "唉呀？",
  str_voice_1601311_54 = "嗯～美好的早晨。",
  str_voice_1601311_55 = "感到疲倦嗎？",
  str_voice_1601311_56 = "那麼，晚安了。",
  str_voice_1601311_57 = "祝您擁有平安幸福的一年。",
  str_voice_1501321_1 = "嘻嘻，我脖子上的印記很漂亮吧？不過你要小心，不小心碰到會天打雷劈喔！哈哈哈，你真的信了？",
  str_voice_1501321_2 = "嚕啦啦～嚕啦啦～嘻嘻嘻，你也覺得我唱歌好聽嗎？那當然啦，畢竟多吃甜食，才會有甜美的歌喉嘛～",
  str_voice_1501321_3 = "胖胖的很好呀，我不覺得是缺點呢。你看，愛洛拉也胖胖的，但是每天都很開心唷～",
  str_voice_1501321_4 = "開心也是一天，難過也是一天，為什麼要折磨自己，讓自己難受呢？異鄉人，你說是吧？",
  str_voice_1501321_5 = "異鄉人，你為什麼不會使用光能術呀？為什麼可以指揮別人呀？我都快想破頭了，你就告訴我吧～",
  str_voice_1501321_6 = "以後要減少睡眠和玩耍的時間了，成長可能就是這麼殘酷吧……不過長大以後，就能吃更多甜食囉～",
  str_voice_1501321_7 = "異鄉人，想不到你的眼光還不錯嘛！愛洛拉也很喜歡身上這件紅色的裙子呢。",
  str_voice_1501321_8 = "噓……跟你說個祕密——愛洛拉睡覺時其實也在吃東西喔。吃什麼？嘻嘻嘻，那就是另一個祕密啦~",
  str_voice_1501321_9 = "愛洛拉特製愛心蜂蜜蛋糕，只獻給來自異鄉的你喔～當當當當！咦……怎麼不見了？難道是……被我吃掉了？",
  str_voice_1501321_10 = "異鄉人，你在發什麼呆呢？如果沒事的話，可以幫我聽看看這首歌好不好聽嗎？咳咳，啦啦啦～啦啦啦～",
  str_voice_1501321_11 = "太棒了，我還沒來這裡玩過呢！我可以在這裡隨便逛逛對吧？",
  str_voice_1501321_12 = "北境大部分地方都很冷，不吃點甜食怎麼禦寒呢？",
  str_voice_1501321_13 = "別看我每天嘻嘻哈哈的，身上也肩負著守護家鄉的任務呢！",
  str_voice_1501321_14 = "嗚哇……興奮到打破我「最長時間不睡覺」的紀錄了！",
  str_voice_1501321_15 = "今天是無聊的一天呢。嘻嘻嘻，逗你的啦。生日快樂唷～",
  str_voice_1501321_16 = "不要讓「一日三餐」這個說法限制我們的想像力嘛！你看我，每天都吃好多餐呢！",
  str_voice_1501321_17 = "什麼味道？別以為有好吃的就能誘惑我起床！好吧……你成功了。",
  str_voice_1501321_18 = "你聽見了嗎？柔軟的床鋪在召喚我呢！",
  str_voice_1501321_19 = "你怎麼……還沒睡？再不睡覺可就……可就長不高喔。",
  str_voice_1501321_20 = "北境有全世界最好吃的蜂蜜，不接受異議！",
  str_voice_1501321_21 = "聽說影鎮的商人為了賺錢，連性命都可以不要……這是真的嗎？",
  str_voice_1501321_22 = "那當然是——暮冬而生囉～",
  str_voice_1501321_23 = "哼，如果看見暗鬼，我會瞄準、射擊！絕不心軟！",
  str_voice_1501321_24 = "女王陛下很溫柔喔。她救了我的命，還教我怎麼使用光能術呢。",
  str_voice_1501321_25 = "水仙花姐姐看起來很安靜，但她舉辦的「鏡湖隱語」活動可熱鬧啦！",
  str_voice_1501321_26 = "嗯～哈！好像聞到了剛出爐的蜂蜜蛋糕！",
  str_voice_1501321_27 = "沒有漂亮的小裙子穿，愛洛拉是不會出門的！",
  str_voice_1501321_28 = "巨像可以「唰」地一下飛到很遠的地方吧？好厲害喔！",
  str_voice_1501321_29 = "你好呀，來自異鄉的客人。你想去北境嗎？我可以為你帶路喔！不用客氣，叫我愛洛拉就好囉！",
  str_voice_1501321_30 = "嗯～睡得好舒服呀！",
  str_voice_1501321_31 = "咦？胃口又變好了。",
  str_voice_1501321_32 = "可以去更遠的地方玩囉～",
  str_voice_1501321_33 = "更有力量守護北境啦！",
  str_voice_1501321_34 = "帶上我準沒錯！",
  str_voice_1501321_35 = "嗯，睡飽嚕！",
  str_voice_1501321_36 = "什麼時候輪到我呀？",
  str_voice_1501321_37 = "沉睡的魔力，甦醒！",
  str_voice_1501321_38 = "純白的野薔薇，綻放！",
  str_voice_1501321_39 = "找、到、囉！",
  str_voice_1501321_40 = "別跑哇！",
  str_voice_1501321_41 = "嘻嘻，很有眼光喔！",
  str_voice_1501321_42 = "嘻嘻嘻，可以好好睡一覺嚕！",
  str_voice_1501321_43 = "蜂蜜蛋糕都不香了……",
  str_voice_1501321_44 = "我能在這裡看一整天呢！",
  str_voice_1501321_45 = "哇！是送給我的嗎？",
  str_voice_1501321_46 = "嘻嘻嘻，是我喜歡的東西！",
  str_voice_1501321_47 = "難道是……蜂蜜蓋飯？！",
  str_voice_1501321_48 = "嗚嗚……你怎麼這麼懂我？",
  str_voice_1501321_49 = "聽說，我從小就展現了異於常人的——睡眠天賦。不要笑嘛！爸爸媽媽有說，能吃能睡才是福氣呢。",
  str_voice_1501321_50 = "為了找到香甜的蜂蜜，我獨自踏上前往森林的小路。在森林裡，我發現一片純白的野薔薇花叢。",
  str_voice_1501321_51 = "每逢新年，我都會帶著家鄉的特產去冬宮探望女王陛下喔～才、才不是因為想到處玩呢！",
  str_voice_1501321_52 = "白夜極光～",
  str_voice_1501321_53 = "啦啦啦～",
  str_voice_1501321_54 = "嗯……早……",
  str_voice_1501321_55 = "啊姆～好香！",
  str_voice_1501321_56 = "又可以睡覺哩～",
  str_voice_1501321_57 = "新年到囉～要快樂呀！",
  str_voice_1601331_1 = "我是女僕沒錯，但可不是你的女僕喔！",
  str_voice_1601331_2 = "載你一程？不行不行，我的背只屬於小林！",
  str_voice_1601331_3 = "好——無——聊——！有沒有家事可以做啊！！",
  str_voice_1601331_4 = "嚇到了？難道龍在這個世界是什麼稀奇的生物嗎？",
  str_voice_1601331_5 = "現在最好離我遠一點喔！我的本能在說牠不喜歡你們。",
  str_voice_1601331_6 = "欸，不玩了嗎？還不過癮呢！",
  str_voice_1601331_7 = "小林！！……什麼嘛，是你啊。",
  str_voice_1601331_8 = "這樣的世界我早就習慣了。這裡當然算不上最好，但至少不討厭。",
  str_voice_1601331_9 = "歡迎回家！飯已經煮好了。要是吃剩，可別怪我發火喔。",
  str_voice_1601331_10 = "呼啊……嗚啊……不行，還有衣服沒洗……",
  str_voice_1601331_11 = "收到！我最擅長看家了！",
  str_voice_1601331_12 = "我的衣服其實是身上的鱗片，所以不用每天換啦～",
  str_voice_1601331_13 = "唔——好想活動筋骨啊。放心啦，不會毀掉這裡。",
  str_voice_1601331_14 = "我的尾巴很美味喔～不過小林一直不願意吃，為什麼呢？",
  str_voice_1601331_15 = "Surprise！我知道唷，對你們來說，今天是重要的日子！",
  str_voice_1601331_16 = "你來了？新的一天有什麼計畫嗎？",
  str_voice_1601331_17 = "天氣真好！女僕可是一大早就開始忙碌了！",
  str_voice_1601331_18 = "不知不覺已經這個時間了啊……",
  str_voice_1601331_19 = "希望今天也能夢到小林！",
  str_voice_1601331_20 = "在這個世界不用綁手綁腳，我的朋友們一定會喜歡這裡！",
  str_voice_1601331_21 = "人們總是不斷戰鬥、不斷死去，無論哪個世界都一樣，真可憐。",
  str_voice_1601331_22 = "為了小林，征服新世界！",
  str_voice_1601331_23 = "呃……原來還有這種比人類更下等且愚蠢的種族啊。",
  str_voice_1601331_24 = "法夫納啊……唉，他就是那個樣子啦。",
  str_voice_1601331_25 = "呿……怎麼連艾爾瑪都跟過來了，陰魂不散的傢伙。",
  str_voice_1601331_26 = "幸、幸好我還藏了一條小林的毛巾！小林的味道！謝謝招待！",
  str_voice_1601331_27 = "我討厭沒有蛋黃的蛋。哼，我朋友赫瑞蘇格就是被那東西殺死的！",
  str_voice_1601331_28 = "他也是龍嗎？喂！還活著嗎？",
  str_voice_1601331_29 = "那個，我叫朵露，是小林家的女僕。請問一下，你知道我的主人在哪裡嗎？",
  str_voice_1601331_30 = "喔！又有幹勁了！",
  str_voice_1601331_31 = "嗷嗚！嘻嘻，嚇你的～",
  str_voice_1601331_32 = "要見識一下嗎？我真正的姿態！",
  str_voice_1601331_33 = "我聽到有人在祈求毀滅！",
  str_voice_1601331_34 = "呀吼！出發！",
  str_voice_1601331_35 = "熱身完成。",
  str_voice_1601331_36 = "好熱啊，對吧？",
  str_voice_1601331_37 = "給我永、遠、消、失！",
  str_voice_1601331_38 = "和這個世界一起燃燒吧！",
  str_voice_1601331_39 = "為什麼逃跑？",
  str_voice_1601331_40 = "再來！再來！",
  str_voice_1601331_41 = "交給我吧！",
  str_voice_1601331_42 = "呼啊～輕輕鬆鬆～",
  str_voice_1601331_43 = "嗚……不甘心……",
  str_voice_1601331_44 = "這裡比小林家大好多喔！",
  str_voice_1601331_45 = "喔？禮物啊，真稀奇呢。",
  str_voice_1601331_46 = "喔！這個好耶！",
  str_voice_1601331_47 = "謝謝～不過不要期待回禮喔！",
  str_voice_1601331_48 = "喔喔喔！摯友！以後你就是我的摯友了！",
  str_voice_1601331_49 = "本來想去異世界找食材，看樣子是傳送時失手了啊。",
  str_voice_1601331_50 = "久違地遇到戰爭！實在手癢，所以也算我一個吧！",
  str_voice_1601331_51 = "好像聞到了康娜的味道。畢竟這裡不是和平的世界，我有點擔心她。",
  str_voice_1601331_52 = "白夜極光！",
  str_voice_1601331_53 = "唷！",
  str_voice_1601331_54 = "早啊！",
  str_voice_1601331_55 = "午餐時間～",
  str_voice_1601331_56 = "呼啊……晚……安……",
  str_voice_1601331_57 = "新年快樂。今天小林總不用加班了吧？",
  str_voice_1601341_1 = "康娜想去上學。學校有朋友，學習也很有趣。",
  str_voice_1601341_2 = "好累……關機……",
  str_voice_1601341_3 = "喔，不得了，真不得了。",
  str_voice_1601341_4 = "可以吃掉這個嗎？想吃。",
  str_voice_1601341_5 = "想出去玩，想出去玩！",
  str_voice_1601341_6 = "朵露大人說了，討厭的傢伙，做掉！",
  str_voice_1601341_7 = "這個世界的人也很有意思。",
  str_voice_1601341_8 = "今天也很忙嗎？喔，我知道了。",
  str_voice_1601341_9 = "陪我玩！不要，藉口。陪我玩！",
  str_voice_1601341_10 = "一隻螞蟻……兩隻螞蟻……",
  str_voice_1601341_11 = "會一直盯著你唷。",
  str_voice_1601341_12 = "我會發電喔。你看，帥嗎？",
  str_voice_1601341_13 = "肚子餓了。下一餐是什麼時候？",
  str_voice_1601341_14 = "我知道，不聽話的孩子會被趕出家門……",
  str_voice_1601341_15 = "生日快樂。可以和你一起過嗎？",
  str_voice_1601341_16 = "今天的計畫是出去玩。嗯，每天都是出去玩。",
  str_voice_1601341_17 = "早安。呼啊——好睏，晚安。",
  str_voice_1601341_18 = "天黑了。朵露大人說有些蟲子晚上會發光，想去抓。一定很好吃。",
  str_voice_1601341_19 = "明天要帶我去哪裡玩？嗯，我會好好期待。",
  str_voice_1601341_20 = "大家都是溫柔的人。嗯，我喜歡和大家在一起。",
  str_voice_1601341_21 = "想和大家交朋友，可以嗎？",
  str_voice_1601341_22 = "征服新世界。",
  str_voice_1601341_23 = "不能吃，會肚子痛。",
  str_voice_1601341_24 = "朵露大人會照顧我，喜歡朵露大人。",
  str_voice_1601341_25 = "小林告訴我，法夫納是「宅男」。「宅男」是什麼意思？",
  str_voice_1601341_26 = "可愛的東西，喜歡。漂亮的東西，喜歡。",
  str_voice_1601341_27 = "一個人很無聊，不喜歡無聊。",
  str_voice_1601341_28 = "大傢伙！他可以當我的新朋友嗎？",
  str_voice_1601341_29 = "我叫康娜。嗯，迷路了。嗯，肚子餓了。有吃的嗎？好，我跟你走。",
  str_voice_1601341_30 = "充電完畢。",
  str_voice_1601341_31 = "我可以用力嗎？",
  str_voice_1601341_32 = "要認真了。",
  str_voice_1601341_33 = "玩膩了，去死。",
  str_voice_1601341_34 = "我會努力的。",
  str_voice_1601341_35 = "我準備好了！",
  str_voice_1601341_36 = "你看你看。",
  str_voice_1601341_37 = "康娜不會輸。",
  str_voice_1601341_38 = "貫穿，消滅。",
  str_voice_1601341_39 = "打雷了。",
  str_voice_1601341_40 = "劈啪！",
  str_voice_1601341_41 = "大家要聽話喔。",
  str_voice_1601341_42 = "多虧了大家的努力。",
  str_voice_1601341_43 = "不好玩……",
  str_voice_1601341_44 = "我現在很閒，在等人陪我玩。",
  str_voice_1601341_45 = "禮物！我喜歡禮物。",
  str_voice_1601341_46 = "喔喔！可愛！",
  str_voice_1601341_47 = "謝謝！還有嗎還有嗎？",
  str_voice_1601341_48 = "好喜歡！禮物和你都喜歡！",
  str_voice_1601341_49 = "回家路上，迷路了，然後出現在森林裡。",
  str_voice_1601341_50 = "遇到很多沒看過的食物，很有趣。",
  str_voice_1601341_51 = "看到天上飛的龍，很親切，就跟了上去。",
  str_voice_1601341_52 = "白夜極光。",
  str_voice_1601341_53 = "你好。",
  str_voice_1601341_54 = "早安。",
  str_voice_1601341_55 = "午安。",
  str_voice_1601341_56 = "晚安。",
  str_voice_1601341_57 = "新年快樂！你許願了嗎？我的願望是……不行。小林有說，願望不能告訴別人。",
  str_voice_1501351_1 = "嗯，朵露能打開世界之門，但我沒辦法。我們所屬的派系也不一樣。不過論力量我是不會輸給她的！",
  str_voice_1501351_2 = "龍的存在會擾亂這個世界的秩序，必須儘早和大家一起回去……不過還是等吃完飯再說吧～",
  str_voice_1501351_3 = "嘎嘣脆油炸酥？沙子石頭飯？蟹皇嫩肉？都、都是沒聽過的料理，快讓我吃吃看！",
  str_voice_1501351_4 = "為了更融入這個世界，必須學習這裡的規則，也就是說——找一份新工作。",
  str_voice_1501351_5 = "我也是會成長的，之前學習處理文件並沒有花很多時間……嗯？你是在誇獎我嗎？",
  str_voice_1501351_6 = "我曾被稱為聖海的巫女，但我不需要任何祭品，秩序本身就是我力量的源泉，況且那些祭品的味道很普通。",
  str_voice_1501351_7 = "美味佳餚是我日常生活最重要的部分，就像這個可麗餅。你要吃嗎？可以分你一點～",
  str_voice_1501351_8 = "唔呣，雖然有點擔心公司的工作……但既然來到這裡了，還是先享受這邊的生活吧。",
  str_voice_1501351_9 = "犧牲自己領導大家……你和小林一樣是大家的支柱呢。不過還是不要太勉強自己，我也很能幹喔～",
  str_voice_1501351_10 = "呃……你的視線在看哪裡！",
  str_voice_1501351_11 = "要怎麼收穫，先那麼栽。不過加班費要另外算。",
  str_voice_1501351_12 = "唔……好難抉擇！到底該選葡萄口味的牙膏，還是草莓口味……",
  str_voice_1501351_13 = "工作還沒完成，必須隨時保持責任感！話雖如此，還是先找個地方吃烤肉吧。",
  str_voice_1501351_14 = "咦，你在看什麼？啊啊啊啊……我頭上的角又冒出來了！",
  str_voice_1501351_15 = "好、好大的生日蛋糕，今天是你的生日嗎？",
  str_voice_1501351_16 = "肚子咕嚕咕嚕地叫……胃得不到滿足時，壓力就會很大……",
  str_voice_1501351_17 = "有好好吃早餐嗎？如果慢吞吞地，食物會冷掉喔。",
  str_voice_1501351_18 = "啊！已經晚上了，得早點睡，明天還要上班呢。",
  str_voice_1501351_19 = "這個時間還不睡嗎？看來你也有很多工作還沒處理完啊……",
  str_voice_1501351_20 = "調和一方注重秩序，不能干涉或破壞其他世界原有的規則。",
  str_voice_1501351_21 = "那些自詡混沌的傢伙渴望破壞與毀滅……還是不要太接近他們比較好。",
  str_voice_1501351_22 = "征服……不對，守護新世界！",
  str_voice_1501351_23 = "暗鬼嗎……如同混沌一般殘忍而邪惡的存在。",
  str_voice_1501351_24 = "朵露那個傢伙，隨心所欲、喜歡亂來、毫無節制。但……這也是我羨慕她的地方。",
  str_voice_1501351_25 = "能出來戰鬥，是因為瀧谷幫忙做了兩倍的工作，他也太拚命了……",
  str_voice_1501351_26 = "第一次嚐到奶油麵包我就被征服了！生巧克力也令人無法抗拒！",
  str_voice_1501351_27 = "到處都是混亂！這樣不行，我必須儘快把這裡調和好，不然我會全身不對勁！！",
  str_voice_1501351_28 = "不知道巨像上有沒有可以製作食物的地方？",
  str_voice_1501351_29 = "上、上井艾爾瑪，目前任職於地獄巡商事北千住事務所，請多指教！不知道這樣自我介紹有沒有符合這個世界的禮儀……",
  str_voice_1501351_30 = "甜點之力！",
  str_voice_1501351_31 = "魔素補充完畢～",
  str_voice_1501351_32 = "向我祈禱吧！",
  str_voice_1501351_33 = "主宰水源的力量！",
  str_voice_1501351_34 = "在！",
  str_voice_1501351_35 = "準備萬全。",
  str_voice_1501351_36 = "做好覺悟吧。",
  str_voice_1501351_37 = "祛除不潔之物！",
  str_voice_1501351_38 = "正本清源！",
  str_voice_1501351_39 = "退散！",
  str_voice_1501351_40 = "邪魔歪道！",
  str_voice_1501351_41 = "與我調解紛爭吧～",
  str_voice_1501351_42 = "不是很簡單嗎？",
  str_voice_1501351_43 = "要好好反省……",
  str_voice_1501351_44 = "我……可以免費住在這裡嗎？！",
  str_voice_1501351_45 = "薪水按月發放了。",
  str_voice_1501351_46 = "這、這是加班的報酬嗎！",
  str_voice_1501351_47 = "謝謝你的好意。",
  str_voice_1501351_48 = "這是我做的護身符，送給你！",
  str_voice_1501351_49 = "我雖然是代表秩序的龍，但我剛到小林家時就把她的房子毀了一半，還把一座山夷為平地。啊……我到底做了什麼……",
  str_voice_1501351_50 = "我誕生於水中，卻無法成為水。唯有不斷深化自己的意義，才能維持自我……",
  str_voice_1501351_51 = "我羨慕、憧憬那些能自由自在飛翔的傢伙，因為自由本身就是一件狡猾的事。",
  str_voice_1501351_52 = "白夜極光。",
  str_voice_1501351_53 = "PlayerName，在嗎？",
  str_voice_1501351_54 = "早安。",
  str_voice_1501351_55 = "午安，感覺如何？",
  str_voice_1501351_56 = "已經晚上了啊。",
  str_voice_1501351_57 = "新年快樂！今天可是一年中餐桌最豐盛的日子呢。",
  str_voice_1501361_1 = "我的本名太拗口了，叫我露可亞就好。怎麼了？這樣叫會讓你害羞嗎？",
  str_voice_1501361_2 = "我不是惡魔喔。不如說剛好相反，原本是神明。好了，別再問了。",
  str_voice_1501361_3 = "上一任主人總說我是惡魔，搞不懂是什麼意思。你覺得呢？",
  str_voice_1501361_4 = "我不喜歡嚴肅。因為，沒有那個必要。",
  str_voice_1501361_5 = "我的職責是維繫世界平衡。現在看來，假期要結束了啊……",
  str_voice_1501361_6 = "不好的記憶就消除掉，不好的時光就倒回去。這是我的生活方式，我的「特權」。",
  str_voice_1501361_7 = "既然簽訂了契約，我會暫時聽你的話。不過先說好，隨時會反悔喔～",
  str_voice_1501361_8 = "對神明來說，玩弄凡人是輕而易舉的事情。啊啦，抱歉，我說錯話了。",
  str_voice_1501361_9 = "你不喜歡擁抱嗎？呵呵，我會注意的。",
  str_voice_1501361_10 = "喂～聽得見嗎？有人在家嗎？",
  str_voice_1501361_11 = "呵呵，收到～這段期間我會乖乖聽話唷～",
  str_voice_1501361_12 = "傷腦筋啊……總是找不到合身的衣服……",
  str_voice_1501361_13 = "那些孩子也來了嗎？真好啊，就像郊遊一樣～",
  str_voice_1501361_14 = "欸？！我喝醉對女孩子……真是的，朵露又在亂說！",
  str_voice_1501361_15 = "生日快樂～想要什麼禮物呢？我什麼都可以給你喔～",
  str_voice_1501361_16 = "貴安。昨天晚上有打擾到你休息嗎？",
  str_voice_1501361_17 = "呼……呼……再睡一會……唔……",
  str_voice_1501361_18 = "太陽下山了，又是悠哉的一天，真好啊～",
  str_voice_1501361_19 = "還不想睡嗎？嗯～我可以講床邊故事哄你睡喔～",
  str_voice_1501361_20 = "大家都是好孩子喔～雖然每個人都多～少有一些缺點。",
  str_voice_1501361_21 = "這個世界有自己運作的規則，或許我還是不要插手比較好。",
  str_voice_1501361_22 = "征服新世界～",
  str_voice_1501361_23 = "某種意義上來說，那些孩子也是為維繫平衡而生。我們是同類呢。",
  str_voice_1501361_24 = "自從遇到了小林，朵露老實很多呢。",
  str_voice_1501361_25 = "康娜在這邊還習慣嗎？那孩子好奇心旺盛，要常常陪她玩喔～",
  str_voice_1501361_26 = "說到放鬆，果然還是要翔太啊！",
  str_voice_1501361_27 = "酒精的味道！……不不不，不行。出於某些原因，我現在盡量滴酒不沾……",
  str_voice_1501361_28 = "要駕馭這種東西，一定很辛苦吧……",
  str_voice_1501361_29 = "以後你就是我的主人了喔。當然，只是暫時的。",
  str_voice_1501361_30 = "愈來愈有趣了。",
  str_voice_1501361_31 = "想多瞭解我一點嗎？",
  str_voice_1501361_32 = "過來，我跟你說個「祕密」。",
  str_voice_1501361_33 = "準備好，覲見神明。",
  str_voice_1501361_34 = "來了喔～",
  str_voice_1501361_35 = "一定要這樣嗎？",
  str_voice_1501361_36 = "我不擅長打鬥。",
  str_voice_1501361_37 = "會有點痛喔～",
  str_voice_1501361_38 = "汝之所見皆為神諭。",
  str_voice_1501361_39 = "天地運行之法。",
  str_voice_1501361_40 = "森羅萬象之力。",
  str_voice_1501361_41 = "大家看我這邊！",
  str_voice_1501361_42 = "沒有稱讚嗎？",
  str_voice_1501361_43 = "啊啦，大意了。",
  str_voice_1501361_44 = "這個環境……令人昏昏欲睡呢，你說是吧？",
  str_voice_1501361_45 = "謝謝～我會好好珍惜！",
  str_voice_1501361_46 = "呵呵，你偷偷研究過我的喜好嗎？",
  str_voice_1501361_47 = "這份禮物有什麼含義呢？",
  str_voice_1501361_48 = "這只能算是我第二想要的東西喔～",
  str_voice_1501361_49 = "為什麼出現在這裡？喔，我發現朵露開錯世界門，就好奇跟過來了。",
  str_voice_1501361_50 = "一路上總是有人盯著我看……我有那麼引人注目嗎？",
  str_voice_1501361_51 = "我聽到有人在召喚什麼，就自告奮勇地現身了。不過當時你真正想召喚的，究竟是什麼？",
  str_voice_1501361_52 = "白夜極光。",
  str_voice_1501361_53 = "貴安。",
  str_voice_1501361_54 = "早安～",
  str_voice_1501361_55 = "我可以睡午覺了嗎？",
  str_voice_1501361_56 = "晚上了唷～",
  str_voice_1501361_57 = "新年快樂～這個節日跟以前比起來，變化好大啊。",
  str_voice_1401371_1 = "執事？呿，你在侮辱我嗎？我不會臣服於任何人。",
  str_voice_1401371_2 = "我在玩遊戲，待會再說。",
  str_voice_1401371_3 = "勇敢是種美德嗎？我殺過幾百個那樣的傢伙了。",
  str_voice_1401371_4 = "貪婪是人的本性，他們追尋寶藏，卻不在乎「寶藏」本身是什麼。",
  str_voice_1401371_5 = "無法逃離，無法抗拒，必定會走向悲慘的命運——那即是詛咒。",
  str_voice_1401371_6 = "沐浴於我血中的生靈將獲得不朽的身軀。可惜，沒人能承受這份恩澤。",
  str_voice_1401371_7 = "那是我寫的書，你有興趣就拿去讀吧。哼，看來你很有眼光。",
  str_voice_1401371_8 = "這個世界的遊戲還不壞。喂，活動要開始了，抓緊囉。",
  str_voice_1401371_9 = "人也有分能相處及不能相處，不能相處的人一眼就看得出來，能相處的人卻要花時間慢慢瞭解。",
  str_voice_1401371_10 = "喂，要讓我等到什麼時候？",
  str_voice_1401371_11 = "不要指使我。",
  str_voice_1401371_12 = "我當然不喜歡現在的打扮，因為我最討厭被你們視為同類！",
  str_voice_1401371_13 = "這是為下一次漫畫展準備的同人誌。呵呵呵，一定會大賣。",
  str_voice_1401371_14 = "有死亡的遊戲才有趣。畢竟，現實中沒人能殺掉我。",
  str_voice_1401371_15 = "出生的日子也要慶祝，無聊的生物。",
  str_voice_1401371_16 = "嗯。新的一天，繼續為自己的生命倒數吧。",
  str_voice_1401371_17 = "你們很重視時間，但對我來說，早上晚上沒有差別。",
  str_voice_1401371_18 = "晚餐？我對那種東西沒興趣。等一下，那是甜咖哩？",
  str_voice_1401371_19 = "我不用睡覺。你想睡就睡。",
  str_voice_1401371_20 = "都是些靠不住的傢伙，別惹麻煩。",
  str_voice_1401371_21 = "別打擾我就好。",
  str_voice_1401371_22 = "毀滅這個世界。",
  str_voice_1401371_23 = "我看不出那些傢伙和你們的區別。不過垃圾的話要分類。",
  str_voice_1401371_24 = "嗯，我跟朵露認識很久了。在行事風格上，我們是同類。",
  str_voice_1401371_25 = "露可亞真正的實力很強，我能認可。",
  str_voice_1401371_26 = "你們的本性雖然卑劣，但不得不承認，發明出來的遊戲很有趣。",
  str_voice_1401371_27 = "隨意踏入別人的居所，意圖奪走寶藏的傢伙，都要殺掉！",
  str_voice_1401371_28 = "可悲的傢伙。虛假的意志嵌在虛假的軀殼裡，徒有形式的傀儡。",
  str_voice_1401371_29 = "我是法夫納。哼，無聊的新世界，我准許你們存在，但千萬不要惹惱我。",
  str_voice_1401371_30 = "升級了。",
  str_voice_1401371_31 = "我現在很煩躁。",
  str_voice_1401371_32 = "殺掉。殺掉。殺掉。",
  str_voice_1401371_33 = "我可聽不見求饒聲。",
  str_voice_1401371_34 = "讓開。",
  str_voice_1401371_35 = "時間到。",
  str_voice_1401371_36 = "儀式開始。",
  str_voice_1401371_37 = "你的命運已經寫好。",
  str_voice_1401371_38 = "如芒刺在背，如附骨之疽！",
  str_voice_1401371_39 = "儘管掙扎吧。",
  str_voice_1401371_40 = "沒有倖存者。",
  str_voice_1401371_41 = "所有人，聽我命令。",
  str_voice_1401371_42 = "哼。",
  str_voice_1401371_43 = "那些傢伙……",
  str_voice_1401371_44 = "把你們的遊戲都拿過來。",
  str_voice_1401371_45 = "這算什麼？貢品？",
  str_voice_1401371_46 = "哼，就這種程度。",
  str_voice_1401371_47 = "好，我會收下。",
  str_voice_1401371_48 = "呵呵呵，就是這個。",
  str_voice_1401371_49 = "有個傢伙亂開世界之門，把我牽扯進來。沒猜錯的話是朵露吧。",
  str_voice_1401371_50 = "剛才遇到幾個沒禮貌的傢伙，不過無所謂，他們已經不在了。",
  str_voice_1401371_51 = "我會被一個叫齊格飛的屠龍者殺死？哼，可笑。",
  str_voice_1401371_52 = "白夜極光。",
  str_voice_1401371_53 = "嗯。",
  str_voice_1401371_54 = "早。",
  str_voice_1401371_55 = "好刺眼。",
  str_voice_1401371_56 = "喔，晚上了啊。",
  str_voice_1401371_57 = "新年啊。需不需要我的詛咒？",
  str_voice_1601381_1 = "如果挖到了什麼古代遺物，建議你直接交給啟光研究院，只有那裡能讓它們重新煥發生機。當然，交給我最好喔。",
  str_voice_1601381_2 = "我相信科學，但有時候科學也無法解釋一切。比如究竟哪裡可以找到有價值的遺跡……這可能就要靠運氣啦。",
  str_voice_1601381_3 = "古代遺物會說話。哈哈哈，它們不是真的會開口說話，而是藉由自身留下的痕跡，向我們傳遞訊息。",
  str_voice_1601381_4 = "不用那麼害怕，我的小蜘蛛很可愛哦～考察古代遺跡的時候，牠們幫過我不少忙呢。",
  str_voice_1601381_5 = "那些創造了如此輝煌的古代文明之人，後來為什麼會消失呢……我，想找到這個答案。",
  str_voice_1601381_6 = "工作就是解決問題，而在解決問題的過程中最忌諱感情用事。不過要是下了班，就另當別論了。",
  str_voice_1601381_7 = "「三」，奇數、正整數，一個和諧穩固的數字，代表了首尾呼應、完整無缺。「三」，是我的幸運數字哦～",
  str_voice_1601381_8 = "你問我為什麼喜歡把思考的過程說出來？哈哈，被你發現了呢～這是我小時候養成的壞習慣。嗯？不算壞嗎？",
  str_voice_1601381_9 = "也不是任何時候都會戴口罩啦。咦，很好奇嗎？咳咳，這可不是工作時應有的態度哦。等下班後再說啦……",
  str_voice_1601381_10 = "我說，如果大家都很閒的話，不如就提前下班去喝幾杯吧。嗯，再來幾份麻辣串燒……完美！",
  str_voice_1601381_11 = "謝謝你邀請我來研究……嗯？不是研究嗎？哦～這種輕鬆的工作可不多呢。",
  str_voice_1601381_12 = "我想挖掘的東西，既不是金銀也不是珠寶，卻比金銀珠寶更有價值。",
  str_voice_1601381_13 = "「希諾普千杯不倒」即使是謠傳，也有點太誇張了哦～",
  str_voice_1601381_14 = "有蜘蛛？啊，那是我養的小蜘蛛。",
  str_voice_1601381_15 = "今天是你的生日嗎？我下班後一定去為你慶祝，記得幫我留一杯哦～",
  str_voice_1601381_16 = "工作上遇到什麼問題了嗎？儘管告訴我，沒有我解決不了的麻煩。",
  str_voice_1601381_17 = "早安！現在是開始工作的好時機呢。",
  str_voice_1601381_18 = "唔嗯……這就下班。怎麼樣，待會兒要不要出去喝一杯？",
  str_voice_1601381_19 = "熬夜係指到深夜還不睡的行為，分為主動熬夜與被動熬夜兩種。你是哪一種？",
  str_voice_1601381_20 = "啟光不僅教會我如何研究，更提供我充分的研究自由。",
  str_voice_1601381_21 = "唉，搞不懂白夜城的人在想什麼。就算不喜歡遺跡，也用不著破壞啊。",
  str_voice_1601381_22 = "為了啟明之光～",
  str_voice_1601381_23 = "暗鬼會神出鬼沒地破壞古代遺跡，我不會放過牠們。",
  str_voice_1601381_24 = "無論是研究，還是管理，貢露長官一直都是我的榜樣。",
  str_voice_1601381_25 = "撇開研究成果不提，彌加德的所作所為總是令我無法理解。",
  str_voice_1601381_26 = "我喜歡喝大人的發酵飲料，可不是小孩子可以消化的哦～",
  str_voice_1601381_27 = "遊、遊戲……？咳咳，我想起我還有工作，你們玩就好。",
  str_voice_1601381_28 = "流暢的線條、熠熠生輝的肌理……這個巨大的飛行器來頭不小呢。",
  str_voice_1601381_29 = "身材、面相、毛髮、身體結構、服飾風格……沒錯，你就是貨真價實的空裔！我是希諾普，很高興研究你～",
  str_voice_1601381_30 = "工作效率又提高了呢。",
  str_voice_1601381_31 = "跨越了時間……",
  str_voice_1601381_32 = "穿越了空間……",
  str_voice_1601381_33 = "看盡了人世間……",
  str_voice_1601381_34 = "任務，收到！",
  str_voice_1601381_35 = "反應要快。",
  str_voice_1601381_36 = "隨時可以開始。",
  str_voice_1601381_37 = "時間到，撒網吧！",
  str_voice_1601381_38 = "蛛網恢恢！",
  str_voice_1601381_39 = "炸裂吧！",
  str_voice_1601381_40 = "蜘蛛之吻！",
  str_voice_1601381_41 = "好，我知道了。",
  str_voice_1601381_42 = "多虧有出色的指揮。",
  str_voice_1601381_43 = "戰敗原因，分析完畢。",
  str_voice_1601381_44 = "你說那件事嗎？讓我來解釋給你聽吧。",
  str_voice_1601381_45 = "這是你上繳的古代遺物嗎？",
  str_voice_1601381_46 = "難道你感應到我的心聲了……",
  str_voice_1601381_47 = "這東西來頭不小……嗯？送給我的？",
  str_voice_1601381_48 = "空裔真懂女人心啊。",
  str_voice_1601381_49 = "還記得……在那陰冷潮濕的坑道盡頭，古代遺跡第一次出現在我眼前，流露神祕與誘惑的氣息。",
  str_voice_1601381_50 = "印象深刻的生日嗎……那一年，有許多我不認識的大人捧著鮮花來找我，然而他們為我準備的並不是生日禮物……",
  str_voice_1601381_51 = "我想像父親一樣勇敢，像母親一樣專注。為了心愛的事業，即使有一天倒下，我也無怨無悔。",
  str_voice_1601381_52 = "白夜極光。",
  str_voice_1601381_53 = "你好哦～",
  str_voice_1601381_54 = "該上班了。",
  str_voice_1601381_55 = "稍微休息一下吧。",
  str_voice_1601381_56 = "下班了嗎？",
  str_voice_1601381_57 = "新年快樂～嗯，也該放個長假了呢。",
  str_voice_1501391_1 = "我能聽見異界的低語。那不屬於世間的聲音，不斷誘惑我為其開啟通往現世的大門……",
  str_voice_1501391_2 = "真羨慕你，對這世界的祕密渾然不知，對自己的處境毫無覺察，臉上每天都掛著無憂無慮的傻笑。",
  str_voice_1501391_3 = "艦長，起航吧。……你好像對我的稱呼感到非常費解？遠古人都是這麼稱呼駕駛飛行器的導航員。",
  str_voice_1501391_4 = "我佩的劍以特殊工藝打造，能夠注入不同屬性的光能來增強威力，你也可以試試。",
  str_voice_1501391_5 = "白夜城的居民瘋狂崇拜那不可言說的存在，一定是受到控制了……我一定要喚醒他們。",
  str_voice_1501391_6 = "現在的我已經與這片大地融為一體，更能夠感知到入侵這世界的邪祟存在了。",
  str_voice_1501391_7 = "你想要知道世界的真相嗎？那麼就跟我一起踏上這條充滿未知與驚奇的道路吧。",
  str_voice_1501391_8 = "想瞭解更多關於「異界」和「次元」知識的話，我可以借你我珍藏的古籍。不過你不能隨便嘗試上面記載的儀式……",
  str_voice_1501391_9 = "這個世界是虛假的，但與你共度的時光，一定都是真實的。",
  str_voice_1501391_10 = "呼……呼……跨越時空的狗，快把我的點心還給我——！唔……是夢啊。還好空裔不在，不然我身為覺醒者的顏面何存……",
  str_voice_1501391_11 = "又要站崗嗎……你一定沒有體會過上一秒還在溫暖的被窩，下一秒就被迫接受寒風洗禮的強烈落差感……嗯？你說待在這裡做什麼都行？還有這種好事？",
  str_voice_1501391_12 = "糖分能促進大腦分泌天然的興奮物質，有助於思考，所以我會隨身攜帶糖果。",
  str_voice_1501391_13 = "這杯拿鐵表面自然呈現的螺旋狀紋路……一定是未知生命發送給我們的警告訊號。",
  str_voice_1501391_14 = "氣壓正以每秒0.155個單位的速度下降。巨像起飛了嗎？",
  str_voice_1501391_15 = "生日快樂。盡情享受這虛偽世界中難得殘存的片刻安寧吧。",
  str_voice_1501391_16 = "你來了。潛伏在暗影中的未知存在尚未察覺到你，放心工作吧。",
  str_voice_1501391_17 = "下次不要這麼早來……我還想……再多睡一會……",
  str_voice_1501391_18 = "不詳的力量正凝聚在空氣中。時間，要到了嗎……",
  str_voice_1501391_19 = "夜晚是虛空氣息變得濃烈的時刻。為了保護柔弱的空裔，我還不能睡覺。",
  str_voice_1501391_20 = "白夜城存在著太多未知……在那裡一定要注意保持虔誠，否則會被凝視……",
  str_voice_1501391_21 = "啟光的學生都很博學。他們研究了那麼多古文明的產物，說不定知道不少祕密……",
  str_voice_1501391_22 = "白夜至上——嗯。",
  str_voice_1501391_23 = "暗鬼，是未知存在創造的產物，是神祕力量正虎視眈眈的信號。",
  str_voice_1501391_24 = "芙洛琳會長是我在黎明學院交到的第一個朋友，也是唯一一個。",
  str_voice_1501391_25 = "烏列爾大人認為世界是虛假的，終有一日會毀滅。她一定也是覺醒之人。",
  str_voice_1501391_26 = "你不覺得隔絕一切紛擾閉門不出，享受一個人的世界是件非常美好的事情嗎？",
  str_voice_1501391_27 = "你在看什麼？《白夜城歷史概述》……呃，字好多，我要昏倒了……",
  str_voice_1501391_28 = "能夠建造巨像，空裔一族到底擁有多麼超凡的技術……難道是「未知存在」傳授的？",
  str_voice_1501391_29 = "我是艾莉法，你好。擁有古老血脈的空裔啊……你和我的相遇，是早已編寫好的程式，還是命運的安排？",
  str_voice_1501391_30 = "力量源源不絕。",
  str_voice_1501391_31 = "與虛空的共鳴增強了……",
  str_voice_1501391_32 = "我聽見了星球的意志。",
  str_voice_1501391_33 = "異界的入侵者無所遁形。",
  str_voice_1501391_34 = "我想回去睡覺。",
  str_voice_1501391_35 = "也可以再等等……",
  str_voice_1501391_36 = "唉，好吧。",
  str_voice_1501391_37 = "轟鳴吧，雷電！",
  str_voice_1501391_38 = "雷光閃擊！",
  str_voice_1501391_39 = "聚集吧——",
  str_voice_1501391_40 = "電光迴轉！",
  str_voice_1501391_41 = "不要交給我麻煩事啊。",
  str_voice_1501391_42 = "快回去睡覺了。",
  str_voice_1501391_43 = "還未完全覺醒嗎……",
  str_voice_1501391_44 = "這就是巨像嗎……趕快趁他不在奪取控制權……\n啊，艦長，你回來了。",
  str_voice_1501391_45 = "這是特產嗎？",
  str_voice_1501391_46 = "下次可以多一點。",
  str_voice_1501391_47 = "堪比古文明典籍的禮物。",
  str_voice_1501391_48 = "這是我收過最棒的禮物。",
  str_voice_1501391_49 = "我成為騎士的動機並不像其他人那麼複雜、那麼偉大。只是因為……祖父將原本對父親的要求強加在我身上。",
  str_voice_1501391_50 = "我父親曾經送我一本「禁書」，它改變了我的人生。因為它，我對神祕現象產生興趣，並貿然召喚了那不屬於現世的詭祕存在……",
  str_voice_1501391_51 = "這個世界危機重重。不知道有多少未知存在正在窺視我們，圖謀侵略。我身為覺醒者，唯有調查古文明、找到解決的關鍵，才能拯救大家。",
  str_voice_1501391_52 = "白夜極光。",
  str_voice_1501391_53 = "艦長。",
  str_voice_1501391_54 = "要不再睡一下吧。",
  str_voice_1501391_55 = "該午睡了。",
  str_voice_1501391_56 = "活動時間到了。",
  str_voice_1501391_57 = "留給光靈的時間，又少了一年……",
  str_voice_1601401_1 = "這把劍很奇怪嗎……這是我父母湊了很多錢為我特別訂製的蜿蜒之劍。這樣橫過來看，是不是很像一條小蛇？",
  str_voice_1601401_2 = "你喊「小白蛇」牠是不會理你的，你要喊牠的名字「阿爾芭」才行。但至於會不會真的理你，還要看阿爾芭的心情。",
  str_voice_1601401_3 = "接到任務然後完成，這就是我的生活。欸？這次的任務是「請給自己放一天假」……嗎？",
  str_voice_1601401_4 = "我最看不慣強者依仗力量欺負弱者……所以，只要我還能握緊手中的劍，就不會對那些事情視而不見。",
  str_voice_1601401_5 = "如果當時我接受了自己的命運，恐怕就不會與你們相遇了……不，那本就不是屬於我的命運。光之神一定可以為我作證。",
  str_voice_1601401_6 = "抱歉，阿爾芭受到驚嚇的時候，咳咳，就會放出這種……這種臭氣。聞多了會暈倒的，我去通風。",
  str_voice_1601401_7 = "我的父母……他們還在等著我做出非凡的成就。所以我不會停下來，我要出色地完成所有我應該完成的任務。",
  str_voice_1601401_8 = "覺得脖頸光溜溜、涼絲絲的？啊，是阿爾芭？牠平時明明不會這麼親人的……阿爾芭，快出來……",
  str_voice_1601401_9 = "出門時記得提前查好路線，帶好隨身物品，別忘了帶上水和食物……欸，為什麼這樣看著我？是我有些嘮叨嗎……",
  str_voice_1601401_10 = "如果沒什麼事，我想在這裡練一下劍，可以嗎？這樣好的時光，我不想白白浪費。",
  str_voice_1601401_11 = "這裡也有調查任務？欸，是不一樣的工作嗎……沒關係，既然由我來做這件事，就不會讓任何人失望。",
  str_voice_1601401_12 = "你也喜歡看書？最好不是些低俗下流的言情小說。",
  str_voice_1601401_13 = "看你的樣子，嘴唇皸裂，皮膚乾燥，是不是又忘了喝水？",
  str_voice_1601401_14 = "一名真正的騎士，是不會輕言放棄的。我從小就這樣要求自己。",
  str_voice_1601401_15 = "生日快樂。為什麼會記得你的生日？偶然聽說就記住了而已……",
  str_voice_1601401_16 = "我們鍛鍊身體、休養生息，不就是為了在這時候好好工作嗎？",
  str_voice_1601401_17 = "早晨醒來之後，最好先喝一杯溫水。注意不要太涼，那樣容易拉肚子。",
  str_voice_1601401_18 = "都這個時間了，就不要做劇烈的運動了，也別吃太多東西喝太多水。",
  str_voice_1601401_19 = "首先你要躺在床上，其次放下娛樂設備。這樣還睡不著，才叫失眠。",
  str_voice_1601401_20 = "唯一仍在繼承光之神意志的地方……我會拼盡全力守護白夜城！",
  str_voice_1601401_21 = "啟光一直充滿野心，我只希望他們沒有忘記自己的初心。",
  str_voice_1601401_22 = "白夜至上！",
  str_voice_1601401_23 = "暗鬼是所有光靈共同的敵人，連光之神也同意我們消滅掉暗鬼。",
  str_voice_1601401_24 = "希望艾莉法能早點拋開那些不切實際的想法，讓我不用再這樣擔心。",
  str_voice_1601401_25 = "海蒂前輩既有才智又有能力，是我學習的榜樣。",
  str_voice_1601401_26 = "我喜歡為正義而戰、守護弱小的人，就這樣。",
  str_voice_1601401_27 = "我討厭的東西不少，其中最不喜歡的就是破壞信仰的人。這麼說會不會太嚴肅了？",
  str_voice_1601401_28 = "誰能告訴我，巨像究竟是不是遠古時代的科技？但我希望……它不是。",
  str_voice_1601401_29 = "白夜至上！我是芙洛琳。關於你的傳聞我聽說過許多，但請原諒，我需要親眼確認後才能得出結論。",
  str_voice_1601401_30 = "努力一定會有回報。",
  str_voice_1601401_31 = "蜿蜒之劍更加鋒利了。",
  str_voice_1601401_32 = "可以……更快地完成任務了！",
  str_voice_1601401_33 = "我一直在等待這一刻！",
  str_voice_1601401_34 = "保證完成任務！",
  str_voice_1601401_35 = "準備完畢。",
  str_voice_1601401_36 = "等待時機。",
  str_voice_1601401_37 = "一個都不許逃！",
  str_voice_1601401_38 = "等待審判吧！",
  str_voice_1601401_39 = "雷蛇，覺醒！",
  str_voice_1601401_40 = "雷蛇之怒！",
  str_voice_1601401_41 = "多謝你的信任！",
  str_voice_1601401_42 = "這是我的職責所在。",
  str_voice_1601401_43 = "請放心，我不會放棄……",
  str_voice_1601401_44 = "你居然是這個東西的主人嗎……看不出來你還挺能幹的。",
  str_voice_1601401_45 = "你不必這樣破費……",
  str_voice_1601401_46 = "嗯……那我就不客氣了。",
  str_voice_1601401_47 = "謝謝你，總是如此費心。",
  str_voice_1601401_48 = "我很喜歡，一定會回禮的！",
  str_voice_1601401_49 = "為了照顧經常犯迷糊的母親，我從小就會做一手好菜。你可以隨便說出一種家務活，一定難不倒我。",
  str_voice_1601401_50 = "我知道自己的家境算不上太好，所以我過去從來都沒有奢求過能夠走進黎明學院的殿堂。但父母還是想方設法為我湊足了學費……",
  str_voice_1601401_51 = "沒有耀眼的資質也沒關係，因為努力絕對不會說謊。我通過了神殿的考核，正式成為異端調查組的一員，就是這句話的最好證明。",
  str_voice_1601401_52 = "白夜極光。",
  str_voice_1601401_53 = "日安。",
  str_voice_1601401_54 = "早起對身體好。",
  str_voice_1601401_55 = "記得要多喝水。",
  str_voice_1601401_56 = "不要太晚睡覺。",
  str_voice_1601401_57 = "要說點什麼嗎……呃，新年快樂。",
  str_voice_1601411_1 = "走吧！去哪裡？當然是去未知的地方探險啦！別告訴我你真的一點興趣都沒有吧？",
  str_voice_1601411_2 = "來來來，為你介紹一下，這是彭太和嚨太哦。啊，分不清嗎？你看哦，這隻瘦一點的是彭太，那隻胖一點的是嚨太。",
  str_voice_1601411_3 = "奇怪，我的球棒放在哪裡了……剛才還在的，怎麼一轉眼就不見了？你說什麼？就在我……啊，還真在這裡，哈哈！",
  str_voice_1601411_4 = "不要小看我的探險裝備包哦，這裡面有工具、藥品、口糧、水……啊，這是彭太和嚨太……算是我的「特殊裝備」吧，嘿嘿……",
  str_voice_1601411_5 = "我有一個驚天地泣鬼神的絕妙想法！可以把我的汽車綁在你的巨像外面嗎？這樣我的汽車就能飛了！",
  str_voice_1601411_6 = "哈哈哈，快停下來……啊，不好意思，剛剛彭太和嚨太又在給我撓癢了。喂，你們兩個，快從我衣服裡出來！",
  str_voice_1601411_7 = "聽老媽說，我是在紅油扳手的篷車裡出生的。大家都覺得這很酷，你也這麼覺得吧？",
  str_voice_1601411_8 = "害我找了半天，原來彭太和嚨太藏到你身上了？不過牠們很少會對除我之外的人這麼親近呢……",
  str_voice_1601411_9 = "「啦啦啦～嘟比嘟比噠～」欸，你聽過這首歌嗎？原來你也是芭芭拉的粉絲啊，來，耳機分你一個！",
  str_voice_1601411_10 = "呃嗯……你，快跟我說說話吧……再這樣下去，我就和埋在地底下的古董沒什麼兩樣了……",
  str_voice_1601411_11 = "嗨～我可以在這裡探險嗎？等等……我好像忘記帶自己的探險裝備了！欸，用不到那些嗎？",
  str_voice_1601411_12 = "巨像裡的螢盞，可以當球打嗎？忽然好手癢啊……",
  str_voice_1601411_13 = "用不了幾年，這片大陸上每個人，都會知道一個叫露比的偉大探險家！",
  str_voice_1601411_14 = "探險確實花銷很大，這沒什麼。隨便接點賞金任務就行了唄。",
  str_voice_1601411_15 = "原來今天是你生日啊！哈哈，有什麼願望嗎？我幫你實現一個囉。",
  str_voice_1601411_16 = "嗯～氣溫尚可、濕度尚可、風速尚可……是適合探險的絕佳天氣！",
  str_voice_1601411_17 = "嗨～我昨晚夢見實現了自己的夢想欸！你呢？晚上有沒有做什麼美夢？",
  str_voice_1601411_18 = "嗨～我在寫今天的探險日記呢！欸？我的字有點醜？這不重要啦～",
  str_voice_1601411_19 = "熬夜不睡覺，是會變醜的吧……你不睡，我可不等你了哦。",
  str_voice_1601411_20 = "有自由、有快樂、還有我的親人……紅油扳手是我永遠的家。",
  str_voice_1601411_21 = "啟光竟然佔有那麼多古代遺跡？！可他們的生活聽起來就很沒勁啊。",
  str_voice_1601411_22 = "及時行樂，路在四方！",
  str_voice_1601411_23 = "暗鬼是阻礙我探險的壞傢伙，絕對不能放過牠們！",
  str_voice_1601411_24 = "其實……我很希望花芸能擁有自己的夢想，而不是一直跟在我身邊。",
  str_voice_1601411_25 = "歐緹是我的師父，這很奇怪嗎？雖然她年齡比我小，但她懂得多嘛。",
  str_voice_1601411_26 = "我喜歡的東西可太多了，只能說一個嗎？那肯定是——探險！",
  str_voice_1601411_27 = "只要別讓我待在屋子裡閒著，什麼都好說！",
  str_voice_1601411_28 = "能飛確實很酷，但在天上就沒辦法踏遍大陸的每個角落了……",
  str_voice_1601411_29 = "嗨～我叫露比，我的夢想是踏遍地圖上的每個角落！你也經常探險嗎？那我們會很聊得來喔～",
  str_voice_1601411_30 = "血液在沸騰！",
  str_voice_1601411_31 = "從未有過的感覺！",
  str_voice_1601411_32 = "我寫的字有變好看嗎？",
  str_voice_1601411_33 = "夢想……觸手可及！",
  str_voice_1601411_34 = "有什麼好玩的嗎？",
  str_voice_1601411_35 = "喂～我準備好啦！",
  str_voice_1601411_36 = "你不會把我給忘了吧？",
  str_voice_1601411_37 = "漂亮一揮！",
  str_voice_1601411_38 = "棒棒的棒棒閃擊！",
  str_voice_1601411_39 = "絕對好球！",
  str_voice_1601411_40 = "必殺！直球！",
  str_voice_1601411_41 = "嗯～小菜一碟！",
  str_voice_1601411_42 = "歡呼聲在哪裡？",
  str_voice_1601411_43 = "還有機會……再來一局！",
  str_voice_1601411_44 = "要出發去冒險嗎？！我馬上……欸，不去嗎？",
  str_voice_1601411_45 = "不會吧，你送給我啦？",
  str_voice_1601411_46 = "哈哈哈，你很懂我喔～",
  str_voice_1601411_47 = "喂，這東西很貴吧？",
  str_voice_1601411_48 = "我真的好喜歡這個！",
  str_voice_1601411_49 = "從記事起，我就和紅油扳手的大哥哥大姐姐們混在一起，打架、兜風、打獵……大口吃肉，大聲唱歌。",
  str_voice_1601411_50 = "光憑一腔熱血可沒法去探險，還需要各式各樣的知識和實踐經驗才行。要知道，我可是在這上面吃過苦頭的。",
  str_voice_1601411_51 = "老實說，在我告別母親、啟動汽車的瞬間，眼淚差點要翻湧出來。但我忽然發現，車裡還藏著一個人。",
  str_voice_1601411_52 = "白夜極光～！",
  str_voice_1601411_53 = "嗨～",
  str_voice_1601411_54 = "嗨，早哇～",
  str_voice_1601411_55 = "嗨，肚子餓了嗎？",
  str_voice_1601411_56 = "嗨，晚上好！",
  str_voice_1601411_57 = "新年快樂！新的一年，讓我們去更遠的地方探險吧？",
  str_voice_1501421_1 = "喂，下次出擊的時候幫我蒐集這份清單上的材料吧。唔……別那麼看著我，我會把做好的樣品送給你一份的。",
  str_voice_1501421_2 = "巨像上的伙食還滿不錯的。每天都有一葷一素，偶爾還有自助……你應該多吃肉，多鍛鍊，爭取做到一拳放倒暗鬼。",
  str_voice_1501421_3 = "你不會是在偷懶吧？該做的事情都做完了嗎？別移開視線……喂！",
  str_voice_1501421_4 = "「熾紅重刃」最初到我手中的時候，只是一把體型稍大的普通鉗子。我花了兩年的時間，才改進成了現在的樣子——是不是很威風？",
  str_voice_1501421_5 = "遠古人類的機器真是種類繁多又新奇啊。要是我有一天也能夠發明出空前絕後的機器，大家就一定會承認我是大發明家了。",
  str_voice_1501421_6 = "有了這份力量，我就能更好地保護露比姐了。但是，還不夠，我要成為最強的，強到足以讓她依賴……",
  str_voice_1501421_7 = "我只是看你可憐才過來幫忙，加上這裡也有不少新奇的技術……絕對不是想要和你搞好關係！",
  str_voice_1501421_8 = "怎麼忽然靠得這麼近？這樣的距離在朋友間很正常？我、我還沒承認呢！",
  str_voice_1501421_9 = "累嗎？偶爾也放鬆一下吧，不用那麼拚命的。你那眼神什麼意思，看到我關心你覺得很驚訝嗎？我在你心裡是什麼形象啊……",
  str_voice_1501421_10 = "唔？睡著了嗎……喂喂、醒醒啦，好歹披件衣服再睡啦，不然會著涼啊……",
  str_voice_1501421_11 = "讓我在這裡陪著你？……你難道在撒嬌嗎？……那可真沒辦法，我就勉為其難答應你吧。",
  str_voice_1501421_12 = "你從剛才起就在直勾勾地盯著我吧。下次要收費了哦。",
  str_voice_1501421_13 = "你看到露比姐了嗎？唔，她那麼喜歡冒險，我很擔心她遇上了什麼麻煩。",
  str_voice_1501421_14 = "肉～♪肉～♪香噴噴的烤肉……嗚哇！你、你是什麼時候來的！",
  str_voice_1501421_15 = "給，這是點上火就能唱歌的蠟燭。只……只是順手做的！",
  str_voice_1501421_16 = "來了？讓我等了好久。才不是想你了！只是缺個人給我打下手！",
  str_voice_1501421_17 = "嗨，難得見你早起啊。有什麼需要修理的設備嗎？閒著也是閒著。",
  str_voice_1501421_18 = "吃過飯後就是娛樂時間囉。勞逸結合才能更有效率。",
  str_voice_1501421_19 = "早睡早起才能有好身體……只是隨便提醒你一句，不是特別關心。",
  str_voice_1501421_20 = "紅油扳手無條件地包容和接納了我。對我而言，那裡是家一樣的地方。",
  str_voice_1501421_21 = "白夜城那幫傢伙，總是把我們和其他的強盜綁匪混為一談，真是討厭。",
  str_voice_1501421_22 = "為了露比姐！",
  str_voice_1501421_23 = "人有時比暗鬼還要可怕。人心的險惡，難以揣測。",
  str_voice_1501421_24 = "從很小的時候起，露比姐就陪在我的身邊。如果沒有她，就沒有現在的我……",
  str_voice_1501421_25 = "約娜姐是我的救命恩人，現在也很照顧我。有時候還會請我吃飯呢。",
  str_voice_1501421_26 = "喜歡的東西？忽然問這個做什麼，打算討好我嗎？",
  str_voice_1501421_27 = "哇啊！！不要突然從我背後出現！！魂都要嚇飛了！！",
  str_voice_1501421_28 = "如果把巨像送給露比姐的話，她肯定很開心……多少錢能買下來？",
  str_voice_1501421_29 = "我是花芸，紅油扳手的一號發明家。給我辦歡迎會的時候，記得擺上最好的肉。……咳咳、說起來，露比姐在你這裡嗎？",
  str_voice_1501421_30 = "身體變得輕盈……",
  str_voice_1501421_31 = "擁有了更強的力量！",
  str_voice_1501421_32 = "血液沸騰了！",
  str_voice_1501421_33 = "我能感受到火焰在燃燒……",
  str_voice_1501421_34 = "好好看著吧。",
  str_voice_1501421_35 = "目標鎖定！",
  str_voice_1501421_36 = "裝填完畢！",
  str_voice_1501421_37 = "鉗刃——猛攻模式！",
  str_voice_1501421_38 = "開火射擊！百發百中——",
  str_voice_1501421_39 = "飛舞吧！",
  str_voice_1501421_40 = "熾紅重刃！",
  str_voice_1501421_41 = "我是最好的。",
  str_voice_1501421_42 = "理所應當～",
  str_voice_1501421_43 = "我太沒用了……",
  str_voice_1501421_44 = "不要亂摸我的「熾紅重刃」！它可是很精密的。",
  str_voice_1501421_45 = "給我的禮物？為什麼？",
  str_voice_1501421_46 = "我……我才不會中了你的圈套。",
  str_voice_1501421_47 = "看著還行，我收下了。",
  str_voice_1501421_48 = "……謝謝……不，你聽錯了。",
  str_voice_1501421_49 = "父母？我不需要他們。若不是有血緣關係，誰會承認那兩個傢伙是我的父母？我支離破碎的童年，都是拜他們所賜。",
  str_voice_1501421_50 = "我無需信仰神明，因為我早就找到了自己的救世主。露比姐將我從那灰暗的死地中救出，給予了我光明。為了她，我可以付出一切……",
  str_voice_1501421_51 = "紅油扳手的傢伙們都非常隨性灑脫，對吧？哪怕像我這樣的人，都能融入他們。只不過，他們總調侃我是露比姐的跟屁蟲……",
  str_voice_1501421_52 = "白夜極光。",
  str_voice_1501421_53 = "喂。",
  str_voice_1501421_54 = "起得挺早啊。",
  str_voice_1501421_55 = "中午了。",
  str_voice_1501421_56 = "晚上了。",
  str_voice_1501421_57 = "是新年啊。新年就該吃火鍋！放很——多肉的那種！",
  str_voice_1601431_1 = "有我在，這裡就不會遭受入侵。",
  str_voice_1601431_2 = "除了巫女的職責以外，我對演奏樂器和文書工作也很擅長哦。",
  str_voice_1601431_3 = "我的神樂鈴……有一顆鈴鐺不見了。能請您幫忙找找看嗎？",
  str_voice_1601431_4 = "靈力修行，誠心祈福，打掃居所……巫女的日常生活，其實很單調呢。",
  str_voice_1601431_5 = "在我們的信仰裡，山、川、石、木……世間萬物當中都寄宿著神明，而這些神明也時時刻刻庇佑著我們。",
  str_voice_1601431_6 = "巫女的結界，保護的並不只有巫女自身，也包括巫女在乎的一切。",
  str_voice_1601431_7 = "我的淨化之力，能否治癒您的傷痛呢？",
  str_voice_1601431_8 = "我的結界能抵禦污穢，卻並不能無限延伸，所以還請您不要亂跑。",
  str_voice_1601431_9 = "在您身邊的時候，似乎能夠比平時更加順利地使用靈力呢。這是空裔的特殊能力嗎？又或者，這是心意相通產生的加護呢？",
  str_voice_1601431_10 = "哎呀，導航員大人走神了？懶散也是污穢的一種，需要我幫您祛除嗎？",
  str_voice_1601431_11 = "哎呀，在這裡的工作和巫女修行區別很大呢。",
  str_voice_1601431_12 = "導航員大人，要休息一下嗎？",
  str_voice_1601431_13 = "巫女修行正要開始，您想和我一起嗎？",
  str_voice_1601431_14 = "想知道我的心中供奉著怎樣的神明？這可是不能探究的祕·密·哦。",
  str_voice_1601431_15 = "生日快樂，導航員大人。願您今後的旅行中也有良緣相隨。",
  str_voice_1601431_16 = "不論何時何地，巫女都會展現出完美的姿態。",
  str_voice_1601431_17 = "早上好，導航員大人。今天我也會協助您的工作。",
  str_voice_1601431_18 = "晚上好，導航員大人。今天的工作還順利嗎？",
  str_voice_1601431_19 = "夜晚是污穢最為活躍的時候，導航員大人，要與我一同祛除污穢嗎？",
  str_voice_1601431_20 = "那雲端之城，依舊令我懷念……",
  str_voice_1601431_21 = "白夜城的信仰中似乎只有一位神明，和我的信仰有些不同呢……",
  str_voice_1601431_22 = "像現在這樣自由地生活，也不失為一種享受。",
  str_voice_1601431_23 = "用注連繩在巨像中佈滿結界，那些東西應該就無法攻入了吧？",
  str_voice_1601431_24 = "柏乃是個好孩子，但她似乎沒有意識到，跟蹤是一種不禮貌的行為……",
  str_voice_1601431_25 = "瑤單純又可愛，像一隻小狗狗。",
  str_voice_1601431_26 = "那些亮晶晶的東西……是叫螢盞嗎？真可愛……",
  str_voice_1601431_27 = "污穢可不該存在於這個世界上，還是用淨化之力燒掉吧。",
  str_voice_1601431_28 = "巨像裡充滿了光，而且沒有一絲污穢，我非常喜歡。",
  str_voice_1601431_29 = "雲島的巫女，凜音，應您的召集前來相助。請讓我追隨您的腳步，為您的旅程獻上微薄之力。",
  str_voice_1601431_30 = "感謝您的信任。",
  str_voice_1601431_31 = "戰鬥更輕鬆了呢。",
  str_voice_1601431_32 = "我感受到前所未有的靈力。",
  str_voice_1601431_33 = "這份淨化之力，我會好好使用。",
  str_voice_1601431_34 = "請交給我吧。",
  str_voice_1601431_35 = "我在此祈願……",
  str_voice_1601431_36 = "淨化之力啊……",
  str_voice_1601431_37 = "結界，於此展開！",
  str_voice_1601431_38 = "籠罩的陰霾，我命令你們消散！",
  str_voice_1601431_39 = "真是不堪入目。",
  str_voice_1601431_40 = "邪魔退散！",
  str_voice_1601431_41 = "各位，請跟緊我。",
  str_voice_1601431_42 = "污穢，盡數祛除。",
  str_voice_1601431_43 = "這些污穢，竟然……",
  str_voice_1601431_44 = "哎呀，需要巫女為您做什麼嗎？請不必客氣，儘管告訴我吧？",
  str_voice_1601431_45 = "送給我的禮物？勞您費心了。",
  str_voice_1601431_46 = "哎呀，您怎麼知道我喜歡這個？",
  str_voice_1601431_47 = "您的心意，已經傳達給我了。",
  str_voice_1601431_48 = "我會把這份禮物放進寶匣裡珍藏的。",
  str_voice_1601431_49 = "巫女的生活十分單調。如果沒有與您相遇，或許我至今仍會過著一成不變的生活吧。",
  str_voice_1601431_50 = "人們對於他人的不信任，是引發嫌隙與紛爭的開端。而巫女的責任之一，便是消除這份猜忌。",
  str_voice_1601431_51 = "與您踏上旅途後，每天都能擁有新奇的經歷。這種生活或許不如雲島那樣平靜與安全，但……我不討厭。",
  str_voice_1601431_52 = "白夜極光。",
  str_voice_1601431_53 = "貴安。",
  str_voice_1601431_54 = "晨安。",
  str_voice_1601431_55 = "午安，導航員大人。",
  str_voice_1601431_56 = "請原諒我的叨擾。",
  str_voice_1601431_57 = "恭祝您新年快樂，導航員大人。請讓我用這神樂鈴為您祛除污穢，祈求平安。",
  str_voice_1501441_1 = "那個，請不要盯著我看，我會很緊張……",
  str_voice_1501441_2 = "如果沒有巫女大人的話，我說不定會就此死去了，我很感激她。",
  str_voice_1501441_3 = "遊蕩在塵世間，無家可歸的怨念啊；環繞於我周身，孤苦無依的幽魂啊……呵呵……等等，剛才的話，不是我說的……嗚……",
  str_voice_1501441_4 = "在我眼中，「那些東西」就像縹緲的霧氣。然而，不論我如何解釋，也沒有人願意相信。",
  str_voice_1501441_5 = "有時候，我可能會說出一些奇怪的話。那不是我的本意，而是「那些東西」讓我替它們說的。請您……相信我。",
  str_voice_1501441_6 = "我有時也會思考，自己未來究竟應該去向何方。不過現在看來，我想留在這裡。",
  str_voice_1501441_7 = "這里和故鄉很不同呢，有一種令人放鬆的感覺，如果人再少一點的話，就更好了……",
  str_voice_1501441_8 = "如果您不嫌棄，可以讓我為您畫一幅畫嗎？我過去曾經偷學過一些繪畫的技巧，會努力畫好的。",
  str_voice_1501441_9 = "真奇妙……除了小孩子們以外，您大概是我的第一位朋友了。我和「那些東西」並不像這裡的其他人那樣強大，但是……如果您有需要，我會傾力而為。",
  str_voice_1501441_10 = "導航員大人不在嗎？那我稍微偷一下懶，應該也沒關係吧？",
  str_voice_1501441_11 = "要我在這里工作嗎？希望來這裡的人不多……",
  str_voice_1501441_12 = "導航員的黑眼圈，看起來更重了。請您好好休息……",
  str_voice_1501441_13 = "導航員要出發了嗎，那我去休息室……欸？我，我也要去嗎？",
  str_voice_1501441_14 = "那些東西……請不要撕下來，與儀式有關……唔！請不要扯，會痛……",
  str_voice_1501441_15 = "生日快樂。我為您準備了特殊的禮物……不，不是的，真的不是「那些東西」！",
  str_voice_1501441_16 = "導航員的工作，不分時段嗎？真辛苦……",
  str_voice_1501441_17 = "唔……早，早上好，我還想，再睡一下……呼……",
  str_voice_1501441_18 = "晚上好。那個……有好好吃晚飯嗎？",
  str_voice_1501441_19 = "唔……呼……鯛魚燒……好吃的……唔？！導航員大人？您還沒有休息嗎？",
  str_voice_1501441_20 = "江富城，傲居雲端數載，統魔御鬼，難逃宿命輪迴……呵呵呵……",
  str_voice_1501441_21 = "那些紅油扳手的人，都那麼外向嗎？真可怕呢……",
  str_voice_1501441_22 = "故鄉……已經沒有我的容身之地了。",
  str_voice_1501441_23 = "世界上到處都是這些可怕的傢伙，真不想與它們戰鬥……",
  str_voice_1501441_24 = "阿桃和阿杏，一直都在照顧我。",
  str_voice_1501441_25 = "凜音大人這麼高貴，我這樣的小人物，是不敢攀附她的……",
  str_voice_1501441_26 = "如果我能一個人呆著，「那些東西」就沒辦法傷害別人了。",
  str_voice_1501441_27 = "江富城，夜夜笙歌，粉飾太平。可笑，可悲……呵呵……",
  str_voice_1501441_28 = "巨像裡有很多房間呢……應該也有人少的地方吧？",
  str_voice_1501441_29 = "您好……我是柏乃。請不要害怕，我……我會努力控制「那些東西」，不會給您造成困擾的。",
  str_voice_1501441_30 = "怨念，更深重了。",
  str_voice_1501441_31 = "稍微……變強一點了呢。",
  str_voice_1501441_32 = "一點也不想戰鬥……嗚……",
  str_voice_1501441_33 = "您究竟在期待什麼呢……",
  str_voice_1501441_34 = "要，要我上場嗎？",
  str_voice_1501441_35 = "「那些東西」……要失控了！",
  str_voice_1501441_36 = "難以……控制……嗚！",
  str_voice_1501441_37 = "請躲開！",
  str_voice_1501441_38 = "怨念，如此深重。呵呵……",
  str_voice_1501441_39 = "是打這裡嗎？",
  str_voice_1501441_40 = "請不要跑……",
  str_voice_1501441_41 = "嗚，我不擅長社交啊……",
  str_voice_1501441_42 = "總算是，活下來了……",
  str_voice_1501441_43 = "對不起，是我太弱了……",
  str_voice_1501441_44 = "感謝您……特意來看我，我很高興。",
  str_voice_1501441_45 = "這個是給我的嗎？真的？",
  str_voice_1501441_46 = "我不知道該如何報答您……",
  str_voice_1501441_47 = "能被您關心，我非常幸福……",
  str_voice_1501441_48 = "謝謝您，我……我真的……嗚……",
  str_voice_1501441_49 = "我的童年……只是一些無聊瑣碎的事情，不值得您去瞭解。",
  str_voice_1501441_50 = "我的過去，已經全部告訴您了，還請您……不要討厭我。",
  str_voice_1501441_51 = "我的生命，曾經被許多人拯救，而如今，也包括您。還請您允許我，留在這裡……",
  str_voice_1501441_52 = "那個……白夜極光……？",
  str_voice_1501441_53 = "請稍等……",
  str_voice_1501441_54 = "早上好，您醒了嗎？",
  str_voice_1501441_55 = "唔……肚子餓了……",
  str_voice_1501441_56 = "導航員大人，您睡了嗎？",
  str_voice_1501441_57 = "不知不覺間，一年又過去了……",
  str_voice_1600064_10 = "還在盯著我看？小心會被凍成冰塊……",
  str_voice_1600064_11 = "這裡的風景真的很不錯，風吹在身上的感覺很清爽……這讓我想起了北境。那裡雖然冷，但與白夜城不同，會令人放鬆。",
  str_voice_1600064_16 = "工作時也要偶爾休息一下，比如坐下來喝個咖啡，和夥伴聊聊天。",
  str_voice_1600064_17 = "你起得很早呢……請保持這種生活規律，我很願意看到。",
  str_voice_1600064_18 = "巨像上的夜景也很不錯，如果有機會，我帶你去看一看白夜城的夜景。",
  str_voice_1600064_19 = "還沒有休息？你是在思考什麼嗎？如果願意，我可以做你的傾聽者。",
  str_voice_1600064_35 = "霧氣，已凝結。",
  str_voice_1600064_36 = "期待釋放。",
  str_voice_1600064_37 = "讓戰鬥落幕吧！",
  str_voice_1600064_38 = "凍結靈魂之凜冽！",
  str_voice_1600064_39 = "霜華之風。",
  str_voice_1600064_40 = "冰雪之宴。",
  str_voice_1600064_44 = "請......請不要那樣一直盯著我。",
  str_voice_1600064_58 = "好的夥伴並不是每天都和和氣氣的，反而經常會拌嘴，據說戀人之間也是如此，真的嗎？",
  str_voice_1600064_59 = "偶爾也需要放鬆……總是緊繃繃的，頭腦遲早會變得有問題。",
  str_voice_1600064_60 = "有時候也要從一些固化的思維走出來，多嘗試嘗試新鮮事物，這樣可以從其他角度看待事情。",
  str_voice_1600064_61 = "不知道其他地方的女孩子，會是什麼樣的打扮呢？",
  str_voice_1600064_62 = "聽說影鎮的風氣很開放，然而不加約束的話，過度的開放就會逐漸演化成墮落。",
  str_voice_1600064_63 = "巡邏時需要一定的威嚴，但是更多的其實是親和力。要讓民眾感覺到安全，這才是最重要的。",
  str_voice_1600064_64 = "今天早上巨像裡有點熱。",
  str_voice_1600064_65 = "早上好，你起來啦。",
  str_voice_1600064_66 = "你今天起得很早。",
  str_voice_1600064_67 = "今天似乎有不少工作？",
  str_voice_1600064_68 = "啊……早上好。",
  str_voice_1600064_69 = "今天早上你有沒有聽到什麼聲音？",
  str_voice_1600064_70 = "中午了。",
  str_voice_1600064_71 = "今天的午飯如何？",
  str_voice_1600064_72 = "午飯，已經吃好了嗎？",
  str_voice_1600064_73 = "中午的太陽真好！",
  str_voice_1600064_74 = "似乎該睡覺了。",
  str_voice_1600064_75 = "如果你睡不著的話，會做些什麼？",
  str_voice_1600064_76 = "今天的夜空很漂亮啊。",
  str_voice_1600064_77 = "你休息得怎麼樣？",
  str_voice_1601451_1 = "我身後的忍法帖，記載著千奇百怪的忍術與修煉之法。怎麼，你想看看嗎？別怪我沒提醒你，修煉不當是會走火入魔的。",
  str_voice_1601451_2 = "你說你想知道在下身上到底藏了多少種武器？恕我直言，千萬不要再問別的忍者這種傻問題，否則下場會很難看。",
  str_voice_1601451_3 = "苦無，苦無。不覺得這個名字很有趣嗎？明明是可以傷人的東西，卻叫「苦無」，好像用了它就可以沒有痛苦。",
  str_voice_1601451_4 = "你會覺得在下無趣嗎？呵，我不會介意。這世上所有的笑容背後，都有一個無趣的靈魂在守候，你不這麼覺得嗎？",
  str_voice_1601451_5 = "臨、兵、鬥、者、皆、陣、列、在、前。九字真言，當記於心！",
  str_voice_1601451_6 = "忍術禁忌有三，一曰恐懼之心，二曰侮辱之心，三曰思慮之心。若拋棄這三者，即可達行若閃電之境。",
  str_voice_1601451_7 = "大人聽過風吹稻田的聲音嗎？沙沙、沙沙……年幼時，我總是聽著這樣的聲音進入夢鄉。不過，無憂無慮的日子總是那樣短暫，對嗎？",
  str_voice_1601451_8 = "沒想到大人你竟然獨自在地下隱忍了整整十七年。這個……足以寫在我身後的忍法帖上了！",
  str_voice_1601451_9 = "如果有一天，雲島之人都獲得了真正的幸福寧靜，在下依然會守在這裡吧。又或許……可以跟著大人遊走四方？",
  str_voice_1601451_10 = "寂寞與等待，我早已習慣。所以請大人放心，這裡如有任何風吹草動，我都會及時稟報。",
  str_voice_1601451_11 = "大人的意思是……讓我在此處監視敵情吧。不需要嗎？你是讓我「做喜歡的事就好」？真是令在下為難的要求。",
  str_voice_1601451_12 = "請不要誤會……隱於黑暗，是因為嚮往光明。",
  str_voice_1601451_13 = "我相信天意，天意令我踏上忍者之道，我便不會再回頭。",
  str_voice_1601451_14 = "在下的斗笠裡確實藏著安眠的藥物，但那可不是給失眠患者準備的。",
  str_voice_1601451_15 = "今天是你的出生之日？值得慶祝。",
  str_voice_1601451_16 = "我練習忍術之時，最好不要偷看。除非，你也要加入我的師門？",
  str_voice_1601451_17 = "醒了？大人睡得可真香。我怎麼知道？你莫不是忘記了在下的職業？",
  str_voice_1601451_18 = "若是尋常百姓，正是一家人圍坐一團，吃飯閒聊的時候吧。",
  str_voice_1601451_19 = "這個時間還醒著？如果不是在提防在下……就是也想踏上忍者之道。",
  str_voice_1601451_20 = "行於忍之道者，不求於青史留名。",
  str_voice_1601451_21 = "聽說海的那邊有一處叫做影鎮的地方，聽起來很像忍者的聚集地。",
  str_voice_1601451_22 = "守瓶緘口，隱忍於世。",
  str_voice_1601451_23 = "只希望那些東西的靈魂可有歸處。",
  str_voice_1601451_24 = "師父給了在下第二次生命，在下願意為師父做任何事。",
  str_voice_1601451_25 = "生於這亂世之中，為何瑤那傢伙還能有這樣爽朗純真的笑容……",
  str_voice_1601451_26 = "喜歡沐浴，我們這種人身上必須沒有任何異味，香味也不行。",
  str_voice_1601451_27 = "戰爭會帶來欺騙、背叛和生離死別。但為了驅趕戰爭，只能拿起刀來。",
  str_voice_1601451_28 = "在街頭藝人的講談中曾出現過的巨型飛天神獸，莫非就是這東西。",
  str_voice_1601451_29 = "隨風入夜，化影而遁，徬徨於雲山深處，露宿於星野之下。在下雨森，請多指教。",
  str_voice_1601451_30 = "忍法帖之上，再添新墨。",
  str_voice_1601451_31 = "投擲得更加精準了。",
  str_voice_1601451_32 = "獲得了……忍術的祕法！",
  str_voice_1601451_33 = "光明之處，在下亦可遁入。",
  str_voice_1601451_34 = "在下早已隱入隊列之中。",
  str_voice_1601451_35 = "隨時可以行動。",
  str_voice_1601451_36 = "在下已靜候多時。",
  str_voice_1601451_37 = "忍法！飛簷走壁！",
  str_voice_1601451_38 = "奧義！墨影尋蹤！",
  str_voice_1601451_39 = "忍術無息！",
  str_voice_1601451_40 = "鋼刃無情！",
  str_voice_1601451_41 = "在下領命。",
  str_voice_1601451_42 = "區區一次勝利，不足為人稱道。",
  str_voice_1601451_43 = "逃遁並不可恥，保留生機是為了再戰。",
  str_voice_1601451_44 = "告訴在下，密道在哪裡？",
  str_voice_1601451_45 = "莫非是下次任務的定金？",
  str_voice_1601451_46 = "這東西頗合在下的胃口。",
  str_voice_1601451_47 = "謝過，好意心領了。",
  str_voice_1601451_48 = "除了師父，還沒有人送過在下這般貴重的禮物。",
  str_voice_1601451_49 = "在下出生於雲島的戰火之中，本不過是農家之女，毫無練武之心。心頭所念，不過是收成幾何而已。",
  str_voice_1601451_50 = "士兵們的火把點燃整個村落，火焰的顏色在我眼中化作滿地粘稠的猩紅。善良之人會招致死神……這就是命運嗎。",
  str_voice_1601451_51 = "她身上所佩戴的刀，反射出寒冷的白光，明晃晃地劃過我的雙瞳。我知道，跟著她是我唯一的希望。",
  str_voice_1601451_52 = "白夜極光。",
  str_voice_1601451_53 = "嗯。",
  str_voice_1601451_54 = "早。",
  str_voice_1601451_55 = "好。",
  str_voice_1601451_56 = "安。",
  str_voice_1601451_57 = "願新年都有好收成。",
  str_voice_1601461_1 = "我才不是腦中空無一物的傻丫頭！上次這麼說我的人，已經被我的拳頭制服了，想試試嗎？",
  str_voice_1601461_2 = "咕嚕嚕……小籠包、餃子、燒賣、烤鴨……我好想念大家啊！但我還要去遠方行俠仗義，只能忍忍了…",
  str_voice_1601461_3 = "有什麼擺不平的事情直接喊我！不過若讓我發現你才是作惡的那一個，哼，那你可要吃不了兜著走！",
  str_voice_1601461_4 = "小心，我頭上的簪子可不是個徒有其表的裝飾。若非必要，我也不想讓它和壞傢伙們有什麼身體接觸。懂嗎？",
  str_voice_1601461_5 = "我之所以習武，就是為了在看到不公之事時，能站出來制止。如果連這一點都做不到，還算什麼習武之人？",
  str_voice_1601461_6 = "啊，快幫我看看，最近我的肌肉是不是又更壯了？我的衣服不知為何忽然變緊了……",
  str_voice_1601461_7 = "你幹嘛一直看著我，難道你也想學氣術？哈哈哈，氣術可沒你想的那麼簡單，體能、柔韌、技巧，缺一不可！",
  str_voice_1601461_8 = "你喜歡吃麻婆豆腐嗎？唉，看樣子你沒吃過什麼正宗的啊！有機會我做給你吃啊，保證你吃過後七竅噴火！",
  str_voice_1601461_9 = "一人行天下才是大俠該有的風範！不過如果強強聯手同行天下……好像也不錯？你覺得呢？",
  str_voice_1601461_10 = "閒著也是閒著，你要不要和我一起練功？先來一百個伏地挺身，再做五百次踢腿……",
  str_voice_1601461_11 = "你這是想僱我來這裡當護衛嗎？這個我熟，安啦！欸，我想做什麼就做什麼嗎？那就更沒問題啦。",
  str_voice_1601461_12 = "我正在練習踢腿，膽子大的就過來找我比試比試吧！",
  str_voice_1601461_13 = "你不覺得比起暗鬼，險惡的人心更令人害怕嗎？",
  str_voice_1601461_14 = "我的衣服好看嗎？喜歡的話，我可以找人給你也訂製一套啊！",
  str_voice_1601461_15 = "哇，今天你是大壽星啊？咳咳，祝你長命百歲、福星高照！",
  str_voice_1601461_16 = "看來今天沒什麼不平之事，我甚是清閒欸。唔哈～",
  str_voice_1601461_17 = "哇，有沒有搞錯！我都晨跑回來了，你怎麼還沒從睡夢中清醒過來啊？",
  str_voice_1601461_18 = "喂，你怎麼還在忙？我都等累了……快站起來活動活動筋骨吧！",
  str_voice_1601461_19 = "日出而作，日落而息。順應天法，益壽延年。反正我要睡了。",
  str_voice_1601461_20 = "我天生就是無根之人，無法歸於任何勢力……哈，這才是大俠風範！",
  str_voice_1601461_21 = "紅油扳手倒是也有幾分俠義之氣，但聽說那裡面怪人很多，真的嗎？",
  str_voice_1601461_22 = "道義大於青天！",
  str_voice_1601461_23 = "沒有精氣神的怪物們，咿……光想想就噁心！但我可以一拳打一個！",
  str_voice_1601461_24 = "讓雨森笑一笑好像是要她的命一樣，明明她的笑容那麼可愛……",
  str_voice_1601461_25 = "在影鎮有誰會不知道影主大人呢，我覺得他也稱得上大俠啦。",
  str_voice_1601461_26 = "全身上下我最寶貝的就是這只簪子。誰讓我只有這一個武器嘛。",
  str_voice_1601461_27 = "有些地方的飯菜淡得像沒放鹽！沒辦法，只能隨身帶幾瓶七味辣椒粉。",
  str_voice_1601461_28 = "渡海之時的最佳交通工具……比船好太多了！",
  str_voice_1601461_29 = "久仰大名，今日終得一見。我單名一個瑤字，日後行走於江湖之上，還請你多加擔待啦～",
  str_voice_1601461_30 = "氣息，貫通全身……",
  str_voice_1601461_31 = "指尖的力量在燃燒！",
  str_voice_1601461_32 = "大腿的肌肉在顫抖！",
  str_voice_1601461_33 = "哇，我打通了全身的經脈？",
  str_voice_1601461_34 = "這忙，我幫定了！",
  str_voice_1601461_35 = "深呼吸……",
  str_voice_1601461_36 = "蓄力中……",
  str_voice_1601461_37 = "噓……心靜，拳法才准。哈！",
  str_voice_1601461_38 = "天人合一，勢如破竹！",
  str_voice_1601461_39 = "起勢，雨落松林！",
  str_voice_1601461_40 = "起勢，石鎚沉海！",
  str_voice_1601461_41 = "這才是大俠該做的嘛。",
  str_voice_1601461_42 = "雕蟲小技，何足掛齒。",
  str_voice_1601461_43 = "哼，此仇不報非君子！",
  str_voice_1601461_44 = "哇，這裡好適合練功啊！",
  str_voice_1601461_45 = "哇，給我的？",
  str_voice_1601461_46 = "這怎麼好意思……那我就收下了？",
  str_voice_1601461_47 = "哎呀，都說不用這麼客氣啦！",
  str_voice_1601461_48 = "多謝，我好喜歡這個啊！",
  str_voice_1601461_49 = "記憶開始的味道是鹹的，是一片汪洋海水的鹹腥。海水咕咚咕咚地灌入我的口腔、我的鼻腔、我的耳朵……",
  str_voice_1601461_50 = "我的養父母說，我失憶了。失憶之前我是什麼樣子，做過什麼，去過哪裡……全都成為無法再捕捉到的幻影。",
  str_voice_1601461_51 = "很快，我聽從大家的建議開始練習氣術。沒辦法，畢竟我不能埋沒一個即將橫空出世的大俠。沒錯，大俠就是我呀！",
  str_voice_1601461_52 = "白夜極光！",
  str_voice_1601461_53 = "嗚哇～",
  str_voice_1601461_54 = "早起練功囉～",
  str_voice_1601461_55 = "咕，餓了……",
  str_voice_1601461_56 = "養精蓄銳！",
  str_voice_1601461_57 = "新的一年，當然也要——快快樂樂！",
  str_voice_1501471_1 = "-我是阿桃，負責煮麵。\n-我是阿杏，負責記帳。\n-可別因為我們是雙胞胎就把我們弄混了喔！",
  str_voice_1501471_2 = "-誰是姐姐？當然是我！\n-明明是我才對！\n-是我啦！",
  str_voice_1501471_3 = "-阿杏，斤斤計較，真小氣！\n-阿桃，上躥下跳，像個小猴子！",
  str_voice_1501471_4 = "-鏘鏘鏘！新品出爐！\n-蟹家肉包，絕讚好評售賣中！",
  str_voice_1501471_5 = "-阿杏，那些暗鬼在浪費食物！\n-阿桃，用特製肉包讓牠們長長記性！",
  str_voice_1501471_6 = "-今天的包子是什麼餡？\n-是五仁餡哦！",
  str_voice_1501471_7 = "-我們的貴客最近經常來呢！\n-已經是常客啦！",
  str_voice_1501471_8 = "-貴客最近好像很辛苦。\n-我們做一些點心送給他吧？\n-我這就去準備！",
  str_voice_1501471_9 = "-我們的貴客來啦。阿桃，準備最高級的料理！\n-收到！看我的吧！",
  str_voice_1501471_10 = "-阿杏阿杏，貴客睡著了耶！\n-好機會，阿桃！我們在他的面裡加點芥末吧！",
  str_voice_1501471_11 = "-蟹家拉麵——\n-臨空者號分店——\n-盛大開業啦！",
  str_voice_1501471_12 = "-雖然我們也會吵架。\n-但是永遠不會分開！",
  str_voice_1501471_13 = "-臨空者號上很熱鬧呢！\n-總是有很多人！",
  str_voice_1501471_14 = "-來舉辦節日吧，就叫蟹家拉麵節！\n-要讓更多人品嚐美味的拉麵！",
  str_voice_1501471_15 = "-我們的貴客，祝您生日快樂！\n-我們為您準備了長壽麵哦！",
  str_voice_1501471_16 = "-還沒到吃飯時間嗎？\n-還沒到嗎？\n-等不及啦～",
  str_voice_1501471_17 = "-今天的早餐是豚骨拉麵哦！\n-濃濃的骨湯最美味啦！",
  str_voice_1501471_18 = "-晚餐是辛拉麵，配豬肉煎餃！\n-吃飽了睡覺才踏實！",
  str_voice_1501471_19 = "-已經是深夜了！\n-貴客要來一點宵夜嗎？",
  str_voice_1501471_20 = "-雖然我和阿杏也經常吵架。\n-但蟹家拉麵是最棒的！",
  str_voice_1501471_21 = "-啟光聯邦，我知道，是住在地下城的傢伙！\n-他們會喜歡拉麵嗎？",
  str_voice_1501471_22 = "-蟹家拉麵——\n-天下第一！",
  str_voice_1501471_23 = "-暗鬼？能吃嗎？好吃嗎？怎麼吃？\n-不知道！下次來試試吧！",
  str_voice_1501471_24 = "-打工的經常跑出去呢。\n-跟蹤巫女，鬼鬼祟祟！",
  str_voice_1501471_25 = "-那個穿旗袍的客人，很好相處。\n-還會幫忙趕走鬧事的客人。",
  str_voice_1501471_26 = "-喜歡的東西？\n-當然是蟹家拉麵啦！",
  str_voice_1501471_27 = "-不好吃的東西，不喜歡……\n-浪費食物的傢伙，更討厭！",
  str_voice_1501471_28 = "-臨空者號今天的食譜是？\n-拉麵，拉麵，還是拉麵！",
  str_voice_1501471_29 = "-拉麵一碗！\n-謝謝惠顧！",
  str_voice_1501471_30 = "-好吃的拉麵——\n-再來一份！",
  str_voice_1501471_31 = "-雙倍濃湯！\n-麵條加量！",
  str_voice_1501471_32 = "-店面升級！\n-好欸！",
  str_voice_1501471_33 = "-火力全開！\n-小心燒糊啊！",
  str_voice_1501471_34 = "-準備營業！",
  str_voice_1501471_35 = "-您的麵好了！",
  str_voice_1501471_36 = "-請趁熱享用！",
  str_voice_1501471_37 = "-上菜了上菜了！",
  str_voice_1501471_38 = "-豪華——\n-加量——\n-蟹家拉麵！",
  str_voice_1501471_39 = "-猛火攻擊！",
  str_voice_1501471_40 = "-吃我一鍋！",
  str_voice_1501471_41 = "-拉麵時間！",
  str_voice_1501471_42 = "-感謝惠顧！\n-記得推薦給朋友！",
  str_voice_1501471_43 = "-麵湯……\n-灑光了……",
  str_voice_1501471_44 = "-報告！發現廚房！\n-哼哼哼～貴客今後的伙食，就由我們包攬啦！",
  str_voice_1501471_45 = "-是禮物！\n-感謝您！",
  str_voice_1501471_46 = "-這個好貴的！\n-我們能收下嗎？",
  str_voice_1501471_47 = "-這個放在哪裡呢？\n-放在店裡吧！",
  str_voice_1501471_48 = "-請收下這張免單劵！\n-這是我們的回禮！",
  str_voice_1501471_49 = "-我們不止賣拉麵哦，還會賣很多別的東西。\n-比如包子、餃子之類的。全都是在旅行中學到的美味祕方！",
  str_voice_1501471_50 = "-我的葫蘆裡裝著讓湯美味的祕訣！\n-不就是山泉水嗎？\n-阿杏！不可以就這樣把祕密講出去唷！",
  str_voice_1501471_51 = "-料理好吃的關鍵，不僅是用心烹飪。\n-還有傾注愛意！\n-以及堅不可摧的友誼！",
  str_voice_1501471_52 = "-白夜——  \n-極光！",
  str_voice_1501471_53 = "-開張啦開張啦！",
  str_voice_1501471_54 = "-起床吃早飯啦！",
  str_voice_1501471_55 = "-我們的貴客吃午飯了嗎？",
  str_voice_1501471_56 = "-晚飯想吃什麼？",
  str_voice_1501471_57 = "-新年快樂！\n-新年的第一碗麵，我們已經準備好啦！\n-是海鮮拉麵喔！",
  str_voice_1201631_1 = "腦筋急轉彎……「會到處去看畫展的狗是」？答案是「Tourdog」。都是我的呀，唔喔喔……",
  str_voice_1201631_2 = "這麼大的船還能在天上飛，叫它風船多好，為何叫巨像呢……",
  str_voice_1201631_3 = "我不介意在作品中反應現實，不過最好是半真半假，而且一定要有夢想。沒有夢想的作品，就很容易淪為流水線產品般的平庸之物……",
  str_voice_1201631_4 = "讓我重畫？怎麼可能……好吧，能加錢嗎？",
  str_voice_1201631_5 = "應該讓繪師們自由發揮，按照他們理想中的樣子去畫。",
  str_voice_1201631_6 = "要我畫「七彩絢爛的黑」……我試試。",
  str_voice_1201631_7 = "《白XX光》的劇情，最好既憂傷又熱血，既有俠義精神又不乏宏大敘事……",
  str_voice_1201631_8 = "跟你講喔，我能這麼專注做遊戲和約稿，全靠有人資助，看來白夜城……啊不，影鎮也並不都是瞎子。",
  str_voice_1201631_9 = "北境雖然清冷，然而那裡的極光真的很好看，我也就是在極光中看到《白XX光》的種子……",
  str_voice_1201631_10 = "《白XX光》的動畫電影，首先要把畫稿準備好，不對……應該要先寫劇情大綱。",
  str_voice_1201631_11 = "看家？好吧，我確實做過這種兼職，正好可以研究一下這裡的設備……",
  str_voice_1201631_12 = "前幾天約了太多稿子了，手頭有點緊……都快沒衣服穿了，風船大大，能不能借我幾件衣服穿啊。",
  str_voice_1201631_13 = "某些畫作真的很好，但是不太適合整體基調。對於它們，只能說能用上最好，但是也不要強行使用。",
  str_voice_1201631_14 = "之前有人問我哪裡有好的投資人……我怎麼知道啊……或許問一下那個叫「涉」的女老闆比較好？",
  str_voice_1201631_15 = "生日快樂。我沒蛋糕送你了，給你畫一個……",
  str_voice_1201631_16 = "一天的工作就要開始了，辛苦。",
  str_voice_1201631_17 = "這麼早就開工了嗎？你也很努力……看來維護好這艘船就是你的夢想？",
  str_voice_1201631_18 = "還在工作？記得要吃飯，身體可是事業的本錢。",
  str_voice_1201631_19 = "風船大大完全不休息的嗎？我可撐不住了……啊……",
  str_voice_1201631_20 = "影鎮，不少人的審美意外地還可以，不過浮誇的傢伙還是佔大多數。",
  str_voice_1201631_21 = "別看白夜城的那些老傢伙們很古板，某些人確實懂些審美，看來賺錢還是很重要。",
  str_voice_1201631_22 = "成功，永遠屬於馬上行動的人。",
  str_voice_1201631_23 = "長得還有些藝術感……",
  str_voice_1201631_24 = "瀧這傢伙，看似眼裡只有錢，其實很用心，審美能力進步很快。",
  str_voice_1201631_25 = "蜂與銀城？他們就是賣畫的黑心販子，不過有時確實能找到好作品……",
  str_voice_1201631_26 = "有繪師？快帶我去找他……",
  str_voice_1201631_27 = "我討厭……對待創作不真誠的傢伙。",
  str_voice_1201631_28 = "唔喔喔，這裡的設備真多，或許可以用它們來做一下《白XX光》……",
  str_voice_1201631_29 = "你會不會畫畫？或者說認識會畫畫的人？我是巡迴犬，為了《白XX光》，我在尋找這樣的人……",
  str_voice_1201631_30 = "來了、來了！",
  str_voice_1201631_31 = "什麼要求都能滿足。",
  str_voice_1201631_32 = "三秒出畫。",
  str_voice_1201631_33 = "突破……瓶頸了。",
  str_voice_1201631_34 = "開工……",
  str_voice_1201631_35 = "素材已足夠。",
  str_voice_1201631_36 = "隨時都可以開始。",
  str_voice_1201631_37 = "動起來！",
  str_voice_1201631_38 = "集中注意力！",
  str_voice_1201631_39 = "唔喔喔，可愛！",
  str_voice_1201631_40 = "加油！",
  str_voice_1201631_41 = "按照大家的方式來。",
  str_voice_1201631_42 = "距離目標更近了。",
  str_voice_1201631_43 = "剩下的安撫工作你來做吧……",
  str_voice_1201631_44 = "來玩《白XX光》。",
  str_voice_1201631_45 = "如果是厲害的畫就好了……",
  str_voice_1201631_46 = "我會把它放到《白XX光》裡。",
  str_voice_1201631_47 = "等一下給你《白XX光》內測帳號。",
  str_voice_1201631_48 = "唔喔喔，它給我靈感了。",
  str_voice_1201631_49 = "我之前參加過一次遺跡探索，真是幸運，我找到了「那個裝置」，才得以開始製作《白XX光》。",
  str_voice_1201631_50 = "製作遊戲的前幾年特別困難，自己一個人的力量還是太有限了……幸虧後來有了夥伴，還帶來了資助……",
  str_voice_1201631_51 = "或許是因為我出生在北境，極光給了我靈感，不過更多的是那本遊戲手冊，是它指引我來到影鎮闖蕩。",
  str_voice_1201631_52 = "白夜極光。",
  str_voice_1201631_53 = "好啊。",
  str_voice_1201631_54 = "開始一天的作畫。",
  str_voice_1201631_55 = "午休？別想。",
  str_voice_1201631_56 = "晚上加個班。",
  str_voice_1201631_57 = "巡迴犬祝你新年好。",
  str_voice_1601481_1 = "會開車嗎？如果你有興趣，我可以手把手地慢慢教你。姐姐我的駕駛經驗很豐富，飆車的話，我不會輸給任何人。",
  str_voice_1601481_2 = "唷，你跟啟光和白夜城的可愛小姑娘關係都不錯嘛。哼～還真不能小看啊。悠著點，萬人迷，可別玩得太過分了。",
  str_voice_1601481_3 = "我喜歡一個人行動。沒有束縛，也沒有辜負......孤獨？一點也不。有漫天的星星為我閃爍，荒野的風為我歌唱。",
  str_voice_1601481_4 = "我駕駛過各式各樣的載具，但能飛的巨像還是第一次見。真想知道駕駛巨像是什麼感覺......哦？降落是難點？",
  str_voice_1601481_5 = "可以給姐姐展示下你的那個「感應能力」麼，試試看我現在在想什麼......這就怕了？真沒意思。",
  str_voice_1601481_6 = "大家都叫你「導航員」呢......下次的熾焰拉力賽，來做我的導航員怎麼樣？專屬於我一個人的。哦呀，臉紅了？",
  str_voice_1601481_7 = "和那些只敢偷偷盯著我看的無聊傢伙不一樣，你倒是完全不怕接近我呢。給你一點獎勵也不錯......來，到這邊來。",
  str_voice_1601481_8 = "我是說過喜歡一個人行動，不過你想找地方散散心的時候，這副駕駛的座位空著也是空著......",
  str_voice_1601481_9 = "已經很久沒有人呼喚過我的真名「薩菲婭」了......可以請你重複一遍這個名字麼？呵，你就當我是醉了吧。",
  str_voice_1601481_10 = "你真的準備把我晾在一邊？呵......給你三秒鐘，重新考慮一下你到底該怎麼表現。",
  str_voice_1601481_11 = "要我一直待在這裡？多無聊啊，不如......一起做點有趣的事情怎麼樣？",
  str_voice_1601481_12 = "紅油扳手的那些吵鬧的小鬼，作為解悶的玩具很是有趣呢。你也一樣。",
  str_voice_1601481_13 = "有什麼新鮮事嗎，說來聽聽。這世上啊，沒有毫無價值的情報喔。",
  str_voice_1601481_14 = "總是找我做什麼？糾纏不休可不會受歡迎。但你比較可愛，原諒一次。",
  str_voice_1601481_15 = "生日快樂，但我忘了準備禮物......要不就把我當作禮物？開玩笑的。",
  str_voice_1601481_16 = "想跟我一起出去蒐集情報嗎？腳踏實地的調查可是探索的第一步。",
  str_voice_1601481_17 = "哦唷，不需要打屁股就起床了？乖孩子。",
  str_voice_1601481_18 = "嗯～差不多該找個地方消遣一下了。有興趣嗎？再磨蹭可不等你了。",
  str_voice_1601481_19 = "哎呀，還以為能看到你可愛的睡顏......既然醒著，夜晚才剛開始喔？",
  str_voice_1601481_20 = "紅油扳手是我的家。雖然不常回去，但這份牽絆，讓我能走得更遠。",
  str_voice_1601481_21 = "和那些傢伙的恩怨，可不是一兩句話就能說清的......",
  str_voice_1601481_22 = "及時行樂？也許吧。",
  str_voice_1601481_23 = "暗鬼嗎......如果這些渣滓，從來都沒存在過就好了。",
  str_voice_1601481_24 = "整個紅油扳手，也就約娜能陪我喝個盡興。羅伊？那傢伙酒品太差。",
  str_voice_1601481_25 = "沒想到當年的那個羅伊會變得這麼嘮叨......你可千萬別學他。",
  str_voice_1601481_26 = "喜歡的東西？當然是可愛的男孩子。別怕，又不會吃了你......暫時不會。",
  str_voice_1601481_27 = "聽說白夜城和啟光都有很多條條框框，光是想想就覺得窒息。",
  str_voice_1601481_28 = "這麼大的巨像，保養得卻很不錯。看得出來，牠是你重要的夥伴。",
  str_voice_1601481_29 = "啊哈，你就是大名鼎鼎的空裔？名字呆呆的，臉長得倒是滿可愛的嘛。來，再湊近一點......",
  str_voice_1601481_30 = "......還想要......更多！",
  str_voice_1601481_31 = "真令人興奮呢。",
  str_voice_1601481_32 = "彷彿飲下千杯佳釀......",
  str_voice_1601481_33 = "還是第一次有這種感覺......",
  str_voice_1601481_34 = "現在才想起我？",
  str_voice_1601481_35 = "別讓姐姐等太久喔。",
  str_voice_1601481_36 = "山貓，永不入眠。",
  str_voice_1601481_37 = "幽藍蜃影，投射！",
  str_voice_1601481_38 = "冰點爆破！",
  str_voice_1601481_39 = "唉，不覺得熱嗎？",
  str_voice_1601481_40 = "涼快一下吧！",
  str_voice_1601481_41 = "也行，先想好怎麼報答我吧。",
  str_voice_1601481_42 = "所以你準備怎麼報答我呢？",
  str_voice_1601481_43 = "......再來一次，不要停！",
  str_voice_1601481_44 = "用你的巨像，一起去兜風怎麼樣？",
  str_voice_1601481_45 = "我知道的，你也給別的漂亮姐姐送了很多吧？",
  str_voice_1601481_46 = "對我的喜好很瞭解嘛，在打什麼壞主意？",
  str_voice_1601481_47 = "真乖，謝謝你啦。來，臉湊過來。啾～",
  str_voice_1601481_48 = "這麼用心，我會當真的。不要戲弄大人喔。",
  str_voice_1601481_49 = "我可是打從娘胎裡就開始學開槍了。可惜，已經沒有人能幫我證明了......",
  str_voice_1601481_50 = "你能想像獨自行走於茫茫沙漠之上時的絕望嗎？找不回容身之處，也找不回曾經的自己......",
  str_voice_1601481_51 = "我不想重蹈覆轍，不想讓過去的悲劇重演......現在，紅油扳手就是我的家，我會用我的方式守護它。",
  str_voice_1601481_52 = "白、夜、極、光～",
  str_voice_1601481_53 = "唷。",
  str_voice_1601481_54 = "早呀。",
  str_voice_1601481_55 = "陪姐姐喝一杯嗎？",
  str_voice_1601481_56 = "哈～啊，晚安囉。",
  str_voice_1601481_57 = "新年快樂。呵，今年會不會稍微成長一點呢......我很期待喔？",
  str_voice_1501491_1 = "後勤工作的祕訣？哪有那種方便的東西，一定要說的話，嗯......熬夜加班？呃，不像是紅油扳手的祕訣？哈哈哈，確實啊。",
  str_voice_1501491_2 = "這幾隻「小甜甜」是用撿來的零件改裝的，不過我搞不清原理，能動完全是歪打正著......名字太可愛了？是澤塔起的啦。",
  str_voice_1501491_3 = "影鎮的商隊也學精了，這樣一來不改變下策略可不行。哦？你也對因地制宜佈置埋伏有興趣？來看看地形圖嗎？我教你。",
  str_voice_1501491_4 = "雖然想給你做個布偶當禮物，但巨像實在是有點難為我了。西瓜蟲暗鬼怎麼樣？",
  str_voice_1501491_5 = "近身格鬥的技巧？你要是想練，就聽我的——抓起沙子糊住對方的眼睛，然後偷襲，百試百靈！卑鄙？嗯～能贏才是最重要的吧？",
  str_voice_1501491_6 = "如果戰爭年代有你們一族的人在，也許一切都會變得不一樣......聽不懂我在說什麼？這就是年輕人說的「代溝」嗎？",
  str_voice_1501491_7 = "年輕人，你真的不考慮加入紅油扳手，成為我們家的一員嗎？那真是可惜，不過隨時歡迎你來玩喔。",
  str_voice_1501491_8 = "我是被過去束縛的人，拯救世界的英雄故事就由你們去寫吧。大叔我啊，光是抓住眼前的東西就已經竭盡全力了。",
  str_voice_1501491_9 = "唉，年紀大了就是這樣嗎，總是會回憶過去的悔恨......要我忘記是不可能的，但和你一起創造一些新的回憶，倒也不錯。",
  str_voice_1501491_10 = "那個…要不要聊聊天？想聽聽暗鬼小百科還是沙漠生存指南？不要留我一個人在這裡啊，怪寂寞的......",
  str_voice_1501491_11 = "讓我這樣的大叔站在這裡？現在的年輕人真是奇怪......算啦，我會好好照看你的，有什麼事交給我來擺平。",
  str_voice_1501491_12 = "打架？還算擅長吧，但最近開始腰痛了，歲月不饒人啊......",
  str_voice_1501491_13 = "想吃糖嗎？我口袋裡有好多，個人推薦紅蠍子味！",
  str_voice_1501491_14 = "呼啊......嗯？哈哈，沒什麼，昨晚又做噩夢了而已，常有的事。",
  str_voice_1501491_15 = "今天是你的生日？那可馬虎不得，來辦個熱鬧的派對吧！",
  str_voice_1501491_16 = "今天好像也會是忙碌的一天......好想偷懶。你也別太勉強自己喔。",
  str_voice_1501491_17 = "哦唷，起這麼早的年輕人可不多見。至少在我們家不多見......呼啊......",
  str_voice_1501491_18 = "這一天過得怎麼樣？有不順心的事情也要好好吃飯好好睡覺啊。",
  str_voice_1501491_19 = "已經是好孩子該睡覺的時間了。失眠了？要給你讀點睡前故事嗎？",
  str_voice_1501491_20 = "如果是為了紅油扳手，我什麼都會做。",
  str_voice_1501491_21 = "啟光......不太熟。補給品的運輸路線我倒是密切關注著呢。",
  str_voice_1501491_22 = "及時行樂。",
  str_voice_1501491_23 = "為什麼我會對暗鬼這麼瞭解？因為......不，沒什麼。",
  str_voice_1501491_24 = "是，青瞳能照顧好自己，但除了傳遞情報，偶爾也該寫點信回來嘛。",
  str_voice_1501491_25 = "醒山那小子，是個很不錯的首領吧？勇往直前，永遠不回頭。",
  str_voice_1501491_26 = "製作布偶的過程很治癒心靈，真的！雖然跟人說起有點難為情......",
  str_voice_1501491_27 = "討厭的東西？到了大叔我這個年紀啊，已經沒什麼討厭的東西了。",
  str_voice_1501491_28 = "哦哦，你這巨像的後勤整備做得很好嘛。",
  str_voice_1501491_29 = "唷，我是紅油扳手的羅伊。我家的那些小鬼已經給你添了不少麻煩了吧？啊哈哈，請多指教。",
  str_voice_1501491_30 = "哎呀呀，感覺不錯～",
  str_voice_1501491_31 = "不要對大叔我有這麼高的期待比較好......",
  str_voice_1501491_32 = "嗯，好像找回了一點當年的感覺。",
  str_voice_1501491_33 = "這是又多了一份責任嗎......",
  str_voice_1501491_34 = "那就稍微努力一下。",
  str_voice_1501491_35 = "什麼時候喊我都行。",
  str_voice_1501491_36 = "唷吼～需要點什麼？",
  str_voice_1501491_37 = "嗯......讓我看看......",
  str_voice_1501491_38 = "來補充點糖分吧。",
  str_voice_1501491_39 = "看招！",
  str_voice_1501491_40 = "怕了怕了......才怪！",
  str_voice_1501491_41 = "要我上？真拿你沒辦法啊。",
  str_voice_1501491_42 = "大叔我也算是盡力囉。",
  str_voice_1501491_43 = "喂，沒受傷吧？",
  str_voice_1501491_44 = "讓我來改造改造你的巨像，增加一點新功能怎麼樣？",
  str_voice_1501491_45 = "好啦好啦，以後不用這麼客氣。",
  str_voice_1501491_46 = "喔？這個可是好東西。確定要給我......？",
  str_voice_1501491_47 = "你啊，這種東西應該送給真心在意的對象才對吧......",
  str_voice_1501491_48 = "這得好好給你回禮才行，想要什麼？任性一點也可以喔。",
  str_voice_1501491_49 = "這幫孩子雖然各有各的脾氣，也闖過不少禍，但大家心眼都不壞。過度保護？我？呃......可能有那麼一點吧，就一點。",
  str_voice_1501491_50 = "哎呀呀，醒山那小子也成了能獨當一面的領袖了......對了，想讀下他小時候寫的詩集嗎？很可愛唷。",
  str_voice_1501491_51 = "加入紅油扳手的契機？因為有個傢伙說想跟我「一起組建個熱鬧的大家庭」......像個傻瓜吧？答應了的我也是個傻瓜就是了。",
  str_voice_1501491_52 = "白夜極光。",
  str_voice_1501491_53 = "最近怎麼樣？",
  str_voice_1501491_54 = "早上好啊，年輕人！",
  str_voice_1501491_55 = "中午飯記得要吃好。",
  str_voice_1501491_56 = "好好休息才能長得高喔。",
  str_voice_1501491_57 = "新年快樂，空裔。",
  str_voice_1601501_1 = "蓮，很聽話。但現在，不是所有人的話，都聽。這樣......算是叛逆嗎？",
  str_voice_1601501_2 = "水滴從眼睛裡，掉出來，好神奇。蓮喜歡流淚，可是大家說，難過才會流淚......難過是一種，不好的情緒嗎？",
  str_voice_1601501_3 = "原來世界上，有這麼多母親......蓮的母親，是獨一無二的嗎？",
  str_voice_1601501_4 = "蓮的肚子，發出了奇怪的聲音。這就是......飢餓麼？這種感覺，好奇妙。像是身體裡住著一個人，在和蓮說話。",
  str_voice_1601501_5 = "如果蓮還是曾經的模樣，導航員會覺得害怕嗎？蓮知道「害怕」是什麼感覺......不想讓別人因為蓮感到害怕。",
  str_voice_1601501_6 = "蓮是誰，蓮從哪裡來到世上的，蓮以後要去哪裡......導航員思考這些問題的時候，也會像蓮一樣頭疼嗎？",
  str_voice_1601501_7 = "導航員總是說，蓮不用必須完成誰的任務。可導航員是蓮認定的人，蓮想要聽從導航員的命令。",
  str_voice_1601501_8 = "導航員看向蓮的時候，蓮總會下意識地摸耳朵，好奇怪，像被施了故事書裡的魔咒。嗯？這是......「害羞」嗎？",
  str_voice_1601501_9 = "蓮從導航員身上，感覺到了那種蓮一直想瞭解的感情。導航員，蓮想知道，這就是「母愛」嗎？",
  str_voice_1601501_10 = "待在這裡，一動不動。這樣的任務，蓮很擅長。以前蓮就是這樣，守著母親和梅的家。",
  str_voice_1601501_11 = "明白了。只要是導航員下達的命令，蓮一定會完成。",
  str_voice_1601501_12 = "有時候蓮會想起梅，蓮猜......梅正在給白色的貓梳理毛髮，梅受不了打結的毛髮。",
  str_voice_1601501_13 = "......最重要的器官，是心臟，還是大腦？",
  str_voice_1601501_14 = "蓮，要做些什麼呢？沒有別人的命令，蓮，不知道自己要做什麼。",
  str_voice_1601501_15 = "生日，是很好的日子，祝導航員今天也開心。",
  str_voice_1601501_16 = "蓮在練習，呼吸。涼涼的空氣吸進來，熱熱的空氣吐出去。",
  str_voice_1601501_17 = "天亮了，世界活過來了，蓮也活過來了。怎麼，蓮又說錯什麼了嗎？",
  str_voice_1601501_18 = "睡前記得刷牙洗臉。啊，抱歉。蓮總是......在這個時間，說這句話。",
  str_voice_1601501_19 = "還不習慣在夜晚，閉上眼睛......睡覺。導航員也和蓮一樣嗎？",
  str_voice_1601501_20 = "蓮是真理結社的，一員。蓮每天都為，真理祈禱。",
  str_voice_1601501_21 = "蓮聽說過，北境。在故事書裡，小孩子愛讀的，那種書。",
  str_voice_1601501_22 = "願真理......祝福你。",
  str_voice_1601501_23 = "許多人，都讓蓮幫著打那些......東西。大家說那些東西，叫做暗鬼。",
  str_voice_1601501_24 = "梅是蓮的妹妹......妹妹是不需要母親的命令，也必須照顧的......存在嗎？",
  str_voice_1601501_25 = "維多利亞大人，讓蓮加入真理結社。她說的話，蓮願意聽。",
  str_voice_1601501_26 = "「喜歡」......是什麼感覺？會讓蓮感到開心的事物嗎？",
  str_voice_1601501_27 = "「討厭」，蓮知道這種感覺。無法完成任務的時候，會有這種感覺。",
  str_voice_1601501_28 = "既是大房子，又是交通工具。",
  str_voice_1601501_29 = "終於來了，蓮一直在等導航員......的命令。導航員不會命令蓮嗎？......也沒有任務給蓮？",
  str_voice_1601501_30 = "蓮覺得很......開心。",
  str_voice_1601501_31 = "擰緊發條的，感覺。",
  str_voice_1601501_32 = "好像......換了許多零件。",
  str_voice_1601501_33 = "這種感覺，很好，很喜歡。",
  str_voice_1601501_34 = "好的，明白了。",
  str_voice_1601501_35 = "蓮準備好了。",
  str_voice_1601501_36 = "蓮在等指揮。",
  str_voice_1601501_37 = "血海，翻騰吧。",
  str_voice_1601501_38 = "這是，蓮的領域。",
  str_voice_1601501_39 = "血鐮很鋒利。",
  str_voice_1601501_40 = "不會失手。",
  str_voice_1601501_41 = "蓮當隊長，明白了。",
  str_voice_1601501_42 = "報告，蓮完成任務了。",
  str_voice_1601501_43 = "蓮不會放棄，蓮會繼續。",
  str_voice_1601501_44 = "牠會有情緒嗎？",
  str_voice_1601501_45 = "蓮收到了一般的禮物。謝謝。",
  str_voice_1601501_46 = "蓮收到了好的禮物。謝謝。",
  str_voice_1601501_47 = "明白了......蓮不能隨便評價禮物。",
  str_voice_1601501_48 = "喜歡，蓮很喜歡。謝謝，導航員。",
  str_voice_1601501_49 = "母親命令蓮......照顧一個叫梅的小孩。小孩，沒有人照顧......就會哭。可是，蓮想不起來，有沒有人照顧過蓮。",
  str_voice_1601501_50 = "在那之前，蓮一直以為......「母親」只是一個名字。在那之後，蓮才明白......母親就是，母親。",
  str_voice_1601501_51 = "母親不在家，梅也不在家。蓮完成了所有的任務，還是沒有人回家。蓮就把身上的零件換了五百零二遍。",
  str_voice_1601501_52 = "白夜……極光。",
  str_voice_1601501_53 = "你好。",
  str_voice_1601501_54 = "早上了，蓮祝導航員，早上好。",
  str_voice_1601501_55 = "中午了，導航員餓嗎？",
  str_voice_1601501_56 = "晚上了，晚上好。",
  str_voice_1601501_57 = "新年，會和過去的每一年都不一樣嗎？",
  str_voice_1601511_1 = "「黑黑的羊羔叫以撒，燙手的絨毛真可怕......」喂，你有好好聽嗎？這可是我為了警告倒楣蛋們才編的新童謠。",
  str_voice_1601511_2 = "你知道白夜城的那幫小孩嗎？叫什麼來著？母雞？不，咯咯！還是不對......總之別讓我碰到他們，否則......我一定請他們唱唱我編的童謠！",
  str_voice_1601511_3 = "為什麼烏鴉像寫字台......你也不知道謎底嗎？啊，究竟是為什麼為什麼為什麼，我的頭咚咚咚地、咚咚咚地好疼啊！！！",
  str_voice_1601511_4 = "哈～欠，最近總是好想睡覺啊，我一定是在長身體......嗯，會比導航員長得更高的......",
  str_voice_1601511_5 = "羊角已經無法抑制它那蓄勢待發的力量，透過紅色的眼眸，我已經看穿了這世上所有的謊言！",
  str_voice_1601511_6 = "鋒利的羊角撕扯開夜晚的帷幕，滾燙的岩漿流淌在殘破的大地之上。我的腦海深處，有一顆真理的種子！",
  str_voice_1601511_7 = "看來你很喜歡以撒？但是不好意思，以撒是我的救命恩人，我是不會放手的！嗯？你不是這個意思？",
  str_voice_1601511_8 = "「一加一等於二，我加你大於二」，這首謎語童謠的答案有很多，你......起碼要給出一個回答吧？",
  str_voice_1601511_9 = "我沒事，只是忽然多了很多靈感！一首童謠的靈感！靈感？靈感！靈感都來自你，我親愛的導航員。",
  str_voice_1601511_10 = "「嘀噠噠的時間，逃跑了。嘩啦啦地撞碎，大螢幕。螢幕的盡頭是，導航員。導航員的身後，站著誰？」",
  str_voice_1601511_11 = "嗯？這裡有肉吃嗎？喔，綿羊肉以外的肉......嘁，什麼都沒有嗎？",
  str_voice_1601511_12 = "除了童謠我一無所有。有了童謠......我最富有！啊哈哈哈哈哈！",
  str_voice_1601511_13 = "咩咩咩～為什麼這樣看著我？這是以撒的語言，為了表示對以撒的尊重，你也一起來啊。咩咩咩～",
  str_voice_1601511_14 = "「我不是怪胎——」呼哧呼哧......喔，又做夢了啊。沒嚇到你就好。哈～欠，我繼續睡了。",
  str_voice_1601511_15 = "生日快樂，讓我用岩漿為你製造一場慶生的煙火秀吧！",
  str_voice_1601511_16 = "你天天都在忙些什麼亂七八糟的啊，嗯，無聊。哈～欠......還是聽我唱童謠吧！",
  str_voice_1601511_17 = "哈～欠......嗯，睡覺好舒服啊......反正沒什麼事，再睡一覺好了。",
  str_voice_1601511_18 = "當當當當！期待已久的——晚餐時間！今晚我們是吃肉呢？還是吃肉呢？",
  str_voice_1601511_19 = "這麼好的時間，竟然有人不睡覺。哈～欠......算了，就當我沒看見。",
  str_voice_1601511_20 = "真理結社裡還是有一些人能聽懂我的童謠的，比別的地方強多了。",
  str_voice_1601511_21 = "白夜城......白夜城？！冷......關愛！漠視......我想去！不......我不會再回去！不會！",
  str_voice_1601511_22 = "願真理祝福你。",
  str_voice_1601511_23 = "我們和暗鬼就像相互吸引的磁鐵......我們被安排找到並消滅彼此，哈哈哈哈！",
  str_voice_1601511_24 = "維多利亞姐姐最懂我了，啊對啊對啊......我要為她寫一首新的童謠！",
  str_voice_1601511_25 = "浮士德總是笑嘻嘻的，但我覺得他根本就听不懂我的童謠。",
  str_voice_1601511_26 = "啊？這麼明顯都看不出來嗎？我喜歡童謠啊，如果還有別的......那就是睡覺囉。",
  str_voice_1601511_27 = "不肯聽我唱童謠的人最討厭了......喂，你不會是那種人吧？",
  str_voice_1601511_28 = "哈～欠......巨像？移動的床鋪，在裡面睡覺會更香嗎？哈～欠......",
  str_voice_1601511_29 = "什麼嘛，原來是導航員啊，哈～欠......喔！！！你特意找我來，是因為你想听童謠了！對吧對吧對吧？",
  str_voice_1601511_30 = "快來看啊哈哈哈！",
  str_voice_1601511_31 = "喔......又想出一首新童謠！",
  str_voice_1601511_32 = "神奇的感覺！",
  str_voice_1601511_33 = "抑制不住......這份力量！",
  str_voice_1601511_34 = "欸——？很快就能結束吧......？",
  str_voice_1601511_35 = "記得叫醒我喔？",
  str_voice_1601511_36 = "已經睡過一覺了。",
  str_voice_1601511_37 = "以撒，我們走～！",
  str_voice_1601511_38 = "讓你們開開眼！",
  str_voice_1601511_39 = "岩漿暴擊！",
  str_voice_1601511_40 = "去吞噬吧，熔岩！",
  str_voice_1601511_41 = "隊長？哈哈哈，大家都聽我的吧！",
  str_voice_1601511_42 = "可以回去睡覺了吧？",
  str_voice_1601511_43 = "沒意思......沒意思沒意思沒意思！",
  str_voice_1601511_44 = "我對他笑了，他卻沒有對我笑，這玻璃的反光真有趣。",
  str_voice_1601511_45 = "哈～欠......喔，我收下了。",
  str_voice_1601511_46 = "嗚呼～！謝啦！",
  str_voice_1601511_47 = "嗯？好～我收下了。",
  str_voice_1601511_48 = "這東西太太太太太棒了吧！",
  str_voice_1601511_49 = "在我看來，那些找不到人生意義的傢伙們真的是奇怪呢。人生意義這種事，不應該一生下來就知道嗎？",
  str_voice_1601511_50 = "那個人，說要帶我去探險，那是我第一次出遠門......啊啊啊啊......他推了一把我的後背，墜落？墜落！墜落......",
  str_voice_1601511_51 = "流浪的生活沒什麼不好。但是維多利亞姐姐為我準備了一張睡起來很舒服的床啊！",
  str_voice_1601511_52 = "白夜極光……",
  str_voice_1601511_53 = "哈～欠～",
  str_voice_1601511_54 = "早啊，我的羊羔。",
  str_voice_1601511_55 = "吃好吃的去囉——！",
  str_voice_1601511_56 = "終於能睡覺囉......",
  str_voice_1601511_57 = "新年好，新年妙，新年要唱新童謠，唷呼——！",
  str_voice_1501521_1 = "盯著我看什麼？再看，我就讓藤曼戳你！欸，你竟然沒有覺得害怕？看來，下次我要對你使用另一種唬人的方法了......",
  str_voice_1501521_2 = "我身上的縫痕？啊哈哈，每一道縫痕的針腳都不一樣喔。好看嗎？下次可以給你試試。",
  str_voice_1501521_3 = "寶寶乖乖......啊，你不要誤會，我是在跟我的寶寶說話。欸，這麼毛茸茸的一大團，你都沒有看見嗎？",
  str_voice_1501521_4 = "寶寶脫落的絨毛，可是好東西。用那些絨毛可以做成最堅韌的紡線。要不然，你以為我縫東西的線都是從哪裡來的？",
  str_voice_1501521_5 = "你覺得，我的能力在真理結社裡面能排第幾名？等一下！我還沒有做好心理準備......還是過幾天再問你吧。",
  str_voice_1501521_6 = "明白嗎？好孩子都是誇出來的。咳咳，現在輪到你發言了。你問我「要說什麼」？嗯......看來你還是沒有明白。",
  str_voice_1501521_7 = "導航員，你已經有六十八秒沒有理我了。我就在你旁邊，你卻不跟我說話......果然，你是不是討厭我？",
  str_voice_1501521_8 = "嗯......我沒事，只是在思考一個嚴肅的問題——我的寶寶應該叫你叔叔呢，還是叫你爺爺呢？",
  str_voice_1501521_9 = "噓，有個祕密，我只告訴你一個人喔。我的這個包包裡，蒐集了好多貓咪的鬍鬚。蒐集鬍鬚，就是累積好運！",
  str_voice_1501521_10 = "就算是空閒的時間，我也不會偷懶的。只要導航員答應我，不會忘記我還在這裡。",
  str_voice_1501521_11 = "這是給我的新任務？如果能完成這個任務，大家......就會喜歡我嗎？",
  str_voice_1501521_12 = "剛才那個路過的人為什麼瞥了我一眼......一定是對我有意見......",
  str_voice_1501521_13 = "寶寶，別跑——真是的，這孩子就愛亂跑，真是不讓我省心呢。",
  str_voice_1501521_14 = "對面的小姐姐好像在對我微笑......怎麼辦，該怎麼回應才好？",
  str_voice_1501521_15 = "有這麼多人祝你生日快樂呀？好羨慕......",
  str_voice_1501521_16 = "我家寶寶喜歡在白天睡覺，你家的呢？喔，你還沒有孩子嗎？真可惜。",
  str_voice_1501521_17 = "寶寶醒得很早，媽媽也要早起才行。不說了，我還要給寶寶準備早餐呢。",
  str_voice_1501521_18 = "睡前記得刷牙、洗臉。是誰教我的？那不重要。",
  str_voice_1501521_19 = "你怎麼和我家寶寶一樣，喜歡在夜裡到處逛？",
  str_voice_1501521_20 = "真理結社是我的家，也是寶寶的家。真理，給予我們永恆的家。",
  str_voice_1501521_21 = "聽說白夜城是最不接受真理的地方，真是奇怪呢。",
  str_voice_1501521_22 = "願真理祝福你，啊哈哈。",
  str_voice_1501521_23 = "暗鬼見到我就打，一定是討厭我吧......還好，是我先討厭牠們的。",
  str_voice_1501521_24 = "蓮......不過是一隻沒有感情的玩偶，最好不要在她身上浪費感情喔。",
  str_voice_1501521_25 = "好想像吉納維芙小姐那樣、那樣受歡迎......咳，你什麼都沒聽見！",
  str_voice_1501521_26 = "你有喜歡的人嗎？我可以幫忙把你們縫在一起哦。啊哈哈。",
  str_voice_1501521_27 = "啊......啊！寶寶的毛又打結了，都是媽媽不好，都是媽媽不對！",
  str_voice_1501521_28 = "巨像喜歡我嗎？牠喜歡我，我才會喜歡牠。",
  str_voice_1501521_29 = "啊哈哈。還以為導航員有多厲害呢，照樣逃不出我的手掌心。欸？什麼......是你主動過來找我的？",
  str_voice_1501521_30 = "好開心喔。",
  str_voice_1501521_31 = "愈來愈近了......愈來愈近了！",
  str_voice_1501521_32 = "這種感覺......是真理嗎？",
  str_voice_1501521_33 = "藤曼開花了呢。",
  str_voice_1501521_34 = "咳，也不是不可以。",
  str_voice_1501521_35 = "藤曼已經復甦。",
  str_voice_1501521_36 = "纏繞，還是抽打？",
  str_voice_1501521_37 = "壞孩子，受罰吧！",
  str_voice_1501521_38 = "送你一朵，大花花。",
  str_voice_1501521_39 = "太討厭了！",
  str_voice_1501521_40 = "一路走好。",
  str_voice_1501521_41 = "我......我才不會怕呢。",
  str_voice_1501521_42 = "剛剛，我是不是表現得很好？",
  str_voice_1501521_43 = "不，這不是我的錯......",
  str_voice_1501521_44 = "啊......這裡看起來會有很多有趣的東西。",
  str_voice_1501521_45 = "這是什麼任務嗎？",
  str_voice_1501521_46 = "是給我的禮物？！",
  str_voice_1501521_47 = "謝......蟹！裡面是螃蟹嗎？",
  str_voice_1501521_48 = "我......我會把它縫進我的口袋。",
  str_voice_1501521_49 = "寶寶的媽媽就是小梅我呀。欸，你問小梅的媽媽？我的媽媽長什麼樣來著，有點忘了。",
  str_voice_1501521_50 = "看著那隻楚楚可憐的小生命，我明白了......也許我從來都不是誰的「寶寶」，但我可以擁有自己的「寶寶」！",
  str_voice_1501521_51 = "我不再需要媽媽的肯定。真理結社給予我的肯定，才是真實的、神聖的、不容杜撰的、我一生渴求的。",
  str_voice_1501521_52 = "白夜極光。",
  str_voice_1501521_53 = "啊，哈，哈。",
  str_voice_1501521_54 = "嗯，天亮了。",
  str_voice_1501521_55 = "一天的一半，是半天。",
  str_voice_1501521_56 = "啊，天黑了。",
  str_voice_1501521_57 = "縫縫補補又一年......新年快樂。",
  str_voice_1601531_1 = "開始一場戰爭很容易，而想要結束一場戰爭卻難得多。PlayerName，告訴我，你做好覺悟了嗎？",
  str_voice_1601531_2 = "戰爭結束之前，沒有人能保證自己一定能贏。我們唯一能保證的是堅持懷有必勝的決心！",
  str_voice_1601531_3 = "記住，永遠不要被眼前的煙霧彈迷住雙眼。真相往往藏在漆黑的帷幕之後。",
  str_voice_1601531_4 = "如果你對我有任何疑問，儘管當面質疑我。我會給你一個滿意的回答。這不是你的特權，在啟光，所有人都擁有這樣的權力。",
  str_voice_1601531_5 = "不斷拓展自己的能力邊界，有鬥志和骨氣的人，才能獲得人們的尊重和喜愛。",
  str_voice_1601531_6 = "不要害怕這些傷疤，PlayerName，這是我作為一名戰士的榮耀。你一定明白，有時候身體上的傷害，遠沒有精神上的傷害來得痛苦。",
  str_voice_1601531_7 = "如果能接受啟光的軍事化訓練，相信你的能力可以提升得更快。嗯，不過有時候，「太快」也不是件好事。",
  str_voice_1601531_8 = "喔？你在看戰略方面的書籍？我看看......嗯，這本書裡面的分析是很到位，但是方法早就落伍了。哈哈，我不多說了，你看完後可以找我討論。",
  str_voice_1601531_9 = "身為軍人，要學會信任你的隊友。身為領導者，要學會分辨周圍人的謊言......呵，等你做到這兩點，大概就能體會到我的感受。",
  str_voice_1601531_10 = "作為一個有理想的年輕人，拖拖拉拉、消磨時間可不是你該有的狀態。",
  str_voice_1601531_11 = "嗯，難得我有空閒。就讓我來看看你最近都在忙些什麼吧。",
  str_voice_1601531_12 = "沒有能力不足的士兵，只有不善用兵的將軍。你一定知道我在說什麼。",
  str_voice_1601531_13 = "情緒低落的時候，就痛快地吃些東西吧！胃是我們的第二個大腦，可不能虧待它。",
  str_voice_1601531_14 = "逃兵在啟光會受到嚴格的審判，你問為什麼？呵，逃避只能解決一時，無法解決一世。遇到問題沒能解決不可恥，可恥的是不能面對問題。你說對嗎？",
  str_voice_1601531_15 = "生日快樂！長大一歲了，體能訓練也要記得跟上。",
  str_voice_1601531_16 = "肚子餓了？看來你還在長身體啊？要想長得強壯，還是得多吃大鍋燴飯啊，哈哈。",
  str_voice_1601531_17 = "早！嚇到你了？醒來後的第一句話，要用力喊出來。讓我聽見你的回答！",
  str_voice_1601531_18 = "天要黑了，但可以工作的時間還沒有結束。",
  str_voice_1601531_19 = "在正確的時間做正確的事，「用功」不需要占用這一點休息的時間。",
  str_voice_1601531_20 = "不論身世、不問過往。只要心向啟光，任何人都能在這裡實現自己的價值。",
  str_voice_1601531_21 = "白夜城對待民眾的態度，我不敢苟同。但白夜城也並非一無是處。",
  str_voice_1601531_22 = "為了同胞、為了家園、為了啟明之光！",
  str_voice_1601531_23 = "暗鬼是我們的天敵。但我也不妨告訴你，一切都沒有看起來那麼簡單。",
  str_voice_1601531_24 = "薇薇安的「計畫至上」雖然在戰場上行不通，但很適合用在後勤工作上。",
  str_voice_1601531_25 = "雷霆的野心並不會威脅到我，相反，她時刻提醒著我要保持前行。",
  str_voice_1601531_26 = "我不覺得精緻的料理有多好吃。要想填飽肚子和心靈，還是得靠大鍋燴飯。",
  str_voice_1601531_27 = "躺在原地怨天尤人的逃兵，世界並不欠你們任何東西。",
  str_voice_1601531_28 = "嗯，臨空者號皮糙肉厚、容量也大，很適合當作軍事運輸工具。",
  str_voice_1601531_29 = "PlayerName，你的出現，為整個艾斯特拉大陸帶來了一個巨大的驚喜。讓我看看吧，你還會為我們帶來多少驚喜。",
  str_voice_1601531_30 = "還不止如此！",
  str_voice_1601531_31 = "這份力量，不止屬於我一人。",
  str_voice_1601531_32 = "對，就是這樣！強大，和更加強大！",
  str_voice_1601531_33 = "我的愛槍，亦為我而燃燒！",
  str_voice_1601531_34 = "喔？命令將軍的士兵？",
  str_voice_1601531_35 = "時不我待！",
  str_voice_1601531_36 = "給我看看你的指揮能力。",
  str_voice_1601531_37 = "看看吧，什麼是真正的力量！",
  str_voice_1601531_38 = "就讓一切在這裡終結。",
  str_voice_1601531_39 = "刺穿一切！",
  str_voice_1601531_40 = "走吧，我的愛槍！",
  str_voice_1601531_41 = "讓我領隊？偷懶但有效的決定。",
  str_voice_1601531_42 = "我們終將取得一切勝利！",
  str_voice_1601531_43 = "繼續戰鬥，繼續前進！",
  str_voice_1601531_44 = "這裡很適合當做基地啊！",
  str_voice_1601531_45 = "我對物質並無執念，不過還是謝了。",
  str_voice_1601531_46 = "喔？有心了。",
  str_voice_1601531_47 = "多謝，我必會物盡其用。",
  str_voice_1601531_48 = "哈哈，別把機靈勁都用在這上面。",
  str_voice_1601531_49 = "我與其他啟光人並無二致，戰鬥就是我的使命。自從我真正踏上戰場之後，便再也沒有什麼能擋住我刺向敵人的利刃。",
  str_voice_1601531_50 = "雷霆確實是我在校園時代的同桌，但我並非任人唯親之徒。她的實力，所有人都看在眼裡。這個答案，你滿意嗎？",
  str_voice_1601531_51 = "希羅娜和緋是我提拔上來的，呵呵，她們能成為軍團長靠的是她們的真本事。我從不吝嗇提供機會，但真正能抓住機遇的人，比你想像中要少得多。",
  str_voice_1601531_52 = "白夜極光！",
  str_voice_1601531_53 = "打起精神來！",
  str_voice_1601531_54 = "嗯，早安！",
  str_voice_1601531_55 = "嗯，你好！",
  str_voice_1601531_56 = "嗯，晚安！",
  str_voice_1601531_57 = "新年的願望需靠自己的拼搏來實現。",
  str_voice_1601541_1 = "呼呼......啊，沒什麼啦。只是忽然想起我們第一次見面的時候，我還以為你是什麼奇怪的「幽靈」呢。啊～沒想到，已經過去這麼久了呢。",
  str_voice_1601541_2 = "你還是會覺得我......奇怪嗎？其實我照鏡子的時候也會被嚇一跳呢。但我能感覺到自己身上充滿了力量。對我們來說這是件好事吧。嗯，我們！",
  str_voice_1601541_3 = "艾斯特拉大陸的寧靜並沒有持續太久......現在我們好像逐漸被捲入了歷史的漩渦之中。PlayerName，不要害怕，我會陪你一起走下去！",
  str_voice_1601541_4 = "有時候覺得自己知道得愈多，反而懂得愈少......真是的，我在說什麼胡話，是不是變得愈來愈像你了？",
  str_voice_1601541_5 = "既然我的能力變強了，那豈不是......烹飪料理的水平也會提高？！嘿嘿，PlayerName，你想吃什麼？儘管告訴我喔～",
  str_voice_1601541_6 = "與暗鬼不同，我們追求力量並不是為了恃強凌弱，而是為了保護弱小。所以我相信我身上的這份力量，也請你一如既往地相信我吧！",
  str_voice_1601541_7 = "沒想到我還滿適合暗色系的......啊，我是說衣服的顏色啦！你覺得呢，我穿黑色好看，還是白色好看？",
  str_voice_1601541_8 = "最近我有在好好練琴喔，還能是什麼琴？當然是鋼琴啦！怎麼樣，要不要再來個四手聯彈？",
  str_voice_1601541_9 = "也許，我真的變了，變得太過貪心。因為我心中想要守護的人變多了，其中也包括......你。所以，我並不想要改掉這份貪心呢。",
  str_voice_1601541_10 = "好啦好啦，我在這裡休息夠了啦。知道你是為我好，不過我們還是要快點工作呢，好不好呀？",
  str_voice_1601541_11 = "幫忙？當然可以啦。我看看，這裡沒什麼需要維修的地方呀？你是說......想讓我在這裡休息一下嗎？",
  str_voice_1601541_12 = "只要有詳細的計畫加上認真訓練就會有相應的成果！所以下個月的計畫書，你準備什麼時候能給我呀？",
  str_voice_1601541_13 = "想去休假旅遊？咳咳，也不是不可以......其實我也很期待出去玩呢。不過想要玩得盡興，還要再完成一些委託任務才行。我這就去算下帳！",
  str_voice_1601541_14 = "計畫書完成了嗎？欸？巨像的計畫書確實早就做好了，可是空谷的建設計畫還沒有做呀。PlayerName，不要忘記你身上的責任唷。",
  str_voice_1601541_15 = "生日快樂！新的一歲也要加油喔，我會好好見證的，嘿嘿。",
  str_voice_1601541_16 = "工作不要太辛苦啦，偶爾也要放鬆一下嘛！勞逸結合最重要喔。",
  str_voice_1601541_17 = "早上好！這是今天的待辦事項，請我們的PlayerName大人確認一下吧。",
  str_voice_1601541_18 = "呼～終於忙完啦！欸，你還沒有處理完工作嗎？有什麼我可以幫你的嗎？",
  str_voice_1601541_19 = "你還沒睡嗎？一定是遇到什麼棘手的問題了吧？沒關係喔，我來陪你一起解決吧。",
  str_voice_1601541_20 = "啟光似乎也有什麼我不知道的祕密......但那絕對不是陰謀，啟光不會允許那種事存在！",
  str_voice_1601541_21 = "以前我也以為紅油扳手是群亡命之徒，但接觸了之後才發現，他們其實還滿不錯。",
  str_voice_1601541_22 = "為了啟明之光！",
  str_voice_1601541_23 = "殺戮並不是我所喜歡的方式，但是面對兇殘的暗鬼，我們似乎沒有別的辦法。",
  str_voice_1601541_24 = "他呀，雖然武力值不高，但是很聰明、很勇敢、很努力......欸？我只是在介紹......我的好朋友呀。",
  str_voice_1601541_25 = "卡蓮一直都是那麼聰明、冷靜、成熟。直到最近我才發現，她只是故意把孩子氣的一面給藏起來了。",
  str_voice_1601541_26 = "白的黎花、粉的櫻花、海邊的刨冰、雪天的蜂蜜蛋糕......喜歡的東西，變多了哩。",
  str_voice_1601541_27 = "以前無法接受的東西，現在會覺得也沒那麼糟糕......欸，這算是成長了嗎？",
  str_voice_1601541_28 = "臨空者號，漸漸有了家一樣的感覺。咳咳，不止我一個人這麼想吧？",
  str_voice_1601541_29 = "欸，為什麼這樣看著我......我的樣子，真的變化很大嗎？放心啦，我還是從前的那個薇絲！如假包換喔～",
  str_voice_1601541_30 = "更加、更加冰冷的能量！",
  str_voice_1601541_31 = "只要努力，就能走得更遠！",
  str_voice_1601541_32 = "未來會回饋我們的選擇！",
  str_voice_1601541_33 = "封印的力量，終於被釋放！",
  str_voice_1601541_34 = "會加倍努力的！",
  str_voice_1601541_35 = "讓我去吧！",
  str_voice_1601541_36 = "事不宜遲！",
  str_voice_1601541_37 = "就是現在，看招！",
  str_voice_1601541_38 = "馬上就能結束一切！",
  str_voice_1601541_39 = "一擊必中！",
  str_voice_1601541_40 = "冰箭，出擊！",
  str_voice_1601541_41 = "老樣子，你來指揮！",
  str_voice_1601541_42 = "可以放進教科書裡的完美戰鬥！",
  str_voice_1601541_43 = "沒關係，我們還有機會！",
  str_voice_1601541_44 = "唔，讓我看看待辦事項清單......巨像養護、食材採購、每日計畫，今天也要繼續加油啊！",
  str_voice_1601541_45 = "哈～原來是老搭檔送來的禮物呀。",
  str_voice_1601541_46 = "欸，你從哪裡找來的？謝謝啦！",
  str_voice_1601541_47 = "還跟我客氣什麼呀？",
  str_voice_1601541_48 = "啊！我一直都好想要這個......多謝啦！",
  str_voice_1601541_49 = "如果當時我沒有把你從地下救出來，也許我已經不在這個世界上了吧......所以我們是最好的搭檔，對嗎？",
  str_voice_1601541_50 = "那些記憶原本早已消散在腦海深處......但現在，它們卻猛然現出原形、變得清晰起來。大腦空白、耳邊嗡嗡......原來，我也曾經有過那樣的日子呢。",
  str_voice_1601541_51 = "和你一起在艾斯特拉大陸上探險的日子......真的是太危險了！但我一直相信，相信我們可以克服任何艱難險阻。所以，我還想和你一起去見識更多的風景！可以嗎？",
  str_voice_1601541_52 = "白夜極光！",
  str_voice_1601541_53 = "PlayerName，還好嗎？",
  str_voice_1601541_54 = "早上好呀，睡醒了嗎？",
  str_voice_1601541_55 = "吃午飯了嗎？",
  str_voice_1601541_56 = "晚上好，今天累壞了吧？",
  str_voice_1601541_57 = "又是新的一年啦，接下來也要一起加油喔！",
  str_voice_1601551_1 = "你這傢伙，不會是被我這副樣子嚇到了吧？怎麼回事，那些頂著鯊魚頭的、搖著狗尾巴的不是天天都在巨像裡晃蕩嗎？怎麼看見我反而覺得稀奇了？",
  str_voice_1601551_2 = "這屆新兵是我帶過最差的一屆！生在和平假象裡的孩子果然都沒什麼憂患意識啊！",
  str_voice_1601551_3 = "怎麼你們一個個的，都跟縮頭烏龜一樣？呵，戰場之上可沒什麼龜殼讓你躲！趁早認清現實吧！",
  str_voice_1601551_4 = "這些年，什麼樣的兵器我都用過一圈，沒想到用起來最順手的居然是這兩把可以合二為一的劍。",
  str_voice_1601551_5 = "偷襲這招好用是好用，但最近我已經不用了。因為我現在正面出擊也可以輕輕鬆鬆把對方打趴下了。怎麼，要試試看嗎？",
  str_voice_1601551_6 = "我算是明白了，我們體內的力量其實並不歸我們管，只有戰勝自己，才能真的駕馭這股力量啊。還好我已經戰勝自己了，啊哈哈哈哈。",
  str_voice_1601551_7 = "我記得你還認識我手下的幾個小兵？哈哈哈，挺好。對了，你別看白矮星那小子平時啥屁也不放，要是打起仗來，可真不給我丟臉。",
  str_voice_1601551_8 = "能有資格跟我切磋兵棋推演的人，除了我自己，也就只有你了吧，哈哈哈。",
  str_voice_1601551_9 = "你確實有點帶兵領隊的能耐啊。別以為我在誇你，有天賦沒什麼好炫耀的，最好讓我看見你的毅力和鬥志！",
  str_voice_1601551_10 = "喂，我已經在腦海裡搞了三場兵棋推演了，你還來不來啊？",
  str_voice_1601551_11 = "哈哈！已經開始主動找我要求訓練了嗎？你這傢伙的成長也不容小覷啊。",
  str_voice_1601551_12 = "你在寫什麼作文嗎？寫這玩意能打勝仗嗎？聽我的，不如出去練下長跑。要是遇到強敵，起碼能溜之大吉。哈哈哈。",
  str_voice_1601551_13 = "別以為你每個地方都有朋友，就能一路暢通了。認識的人愈多，衝突也就愈多。做好心理準備吧，別怪我沒告訴你。",
  str_voice_1601551_14 = "你問我「為什麼可以忍受無聊了嗎」？哈哈哈，你看我哪裡像是能受得了無聊的人？只是最近讓我覺得無聊的時間變少了而已！",
  str_voice_1601551_15 = "今天是你生日？走吧，帶你去前線找點刺激！",
  str_voice_1601551_16 = "嗯......啊啊啊！為什麼當個軍團長還要審批這些亂七八糟的文書資料啊？",
  str_voice_1601551_17 = "起這麼早，是想跟我一起去訓練嗎？你這傢伙，直接跟我說不就得了！",
  str_voice_1601551_18 = "嘁，好不容易熬到可以自由活動的時間了，睡前再去練下劍法吧。想學嗎？一起來啊！",
  str_voice_1601551_19 = "還沒睡？那也別對著空氣發呆啊，過來跟我比劃比劃！",
  str_voice_1601551_20 = "我不懂上面的人到底在打什麼算盤，但只要我還在啟光，就別想攔著我打勝仗。",
  str_voice_1601551_21 = "紅油扳手的人就知道吃喝拉撒，一身本事都用在歪門邪道上了，還不如給我。",
  str_voice_1601551_22 = "為了啟明之光！",
  str_voice_1601551_23 = "暗鬼就是一群沒腦子的垃圾，嘶......可牠們怎麼敢站在我們的對立面？",
  str_voice_1601551_24 = "其他幾個軍團長裡，也就緋能入我眼。喂，你別想歪囉！我說的是戰鬥的實力！",
  str_voice_1601551_25 = "雷霆總愛說什麼「堂堂正正地決鬥」，戰場上哪有這種時間啊？傻不傻？",
  str_voice_1601551_26 = "瞧見了嗎？我就是為疆場而生的戰士！只有戰鬥才能給我活著的感覺！",
  str_voice_1601551_27 = "整天端著茶杯讀報紙有啥意思？別想把我按在那種位置上，我可沒那種「福氣」。",
  str_voice_1601551_28 = "你這巨像怎麼沒什麼變化啊？連個子彈洞之類的「裝飾」都沒有......讓我幫你劃一刀，開個好頭吧！",
  str_voice_1601551_29 = "幾天沒見你就不認識我了？下次還是讓我們在戰場上見吧，也好讓你瞧瞧我最真實的樣子。怎麼？怕了嗎？哈哈哈！",
  str_voice_1601551_30 = "還能變得更強，還能！",
  str_voice_1601551_31 = "要的就是這種勁頭！",
  str_voice_1601551_32 = "可以再戰一百年！哈哈哈哈。",
  str_voice_1601551_33 = "還有誰？！",
  str_voice_1601551_34 = "戰場在哪裡？",
  str_voice_1601551_35 = "喂，小心別被我打到了！",
  str_voice_1601551_36 = "該去掃蕩了！",
  str_voice_1601551_37 = "靠近點，嚐嚐這招！",
  str_voice_1601551_38 = "吼——！",
  str_voice_1601551_39 = "豹——擊——！",
  str_voice_1601551_40 = "放馬過來！",
  str_voice_1601551_41 = "走！都給我麻利點！",
  str_voice_1601551_42 = "趁熱打鐵，繼續衝！",
  str_voice_1601551_43 = "還沒到喪氣的時候！",
  str_voice_1601551_44 = "怎麼，是不是身子生鏽了，來陪我練兩手吧？",
  str_voice_1601551_45 = "有夠大方啊你。",
  str_voice_1601551_46 = "正需要這個，謝囉！",
  str_voice_1601551_47 = "那我就不跟你客氣了，哈哈。",
  str_voice_1601551_48 = "喔！這東西好，夠勁！",
  str_voice_1601551_49 = "士兵還需要長官訓練嗎？難道不是應該自己高標準要求自己嗎？自從我戴上軍帽以來，從來都是自己訓練自己！",
  str_voice_1601551_50 = "我認識萊因哈特的時候，估計你小子還沒學會走路吧？你別說，還真有點懷念那時候，萊因哈特還沒被委員會那幫傢伙給帶壞的時候。",
  str_voice_1601551_51 = "我早就說過，士兵不能退縮，哪裡有敵人我們就去哪裡！要不是堅持這個信念，我也不會有今天。",
  str_voice_1601551_52 = "白夜極光！",
  str_voice_1601551_53 = "嘿，說話呀？",
  str_voice_1601551_54 = "早啊！",
  str_voice_1601551_55 = "這麼快就中午了？",
  str_voice_1601551_56 = "晚安啊。",
  str_voice_1601551_57 = "新年來了，許個願！今年一定要消滅掉那群該死的暗鬼！",
  str_voice_1601561_1 = "見到淑女主動問好才是作為一名紳士的修養......我說，你有沒有在聽呀？仔細聆聽淑女的建議，也是紳士該做到的事情喔。",
  str_voice_1601561_2 = "今天的下午茶我想喝茉莉紅茶，點心就來無糖司康餅吧。欸，要我自己準備？要，要怎麼準備......算了，本小姐忽然沒有喝下午茶的興致了。",
  str_voice_1601561_3 = "本小姐手裡拿著的是「陽傘」，不是「雨傘」！你問我有什麼區別？真是敗給你了......唉，看來原諒庶民的無知也是本小姐的功課之一呢。",
  str_voice_1601561_4 = "欸？你也覺得我的戰鬥能力提升了？呵呵，那是當然啦。給我好好看著吧，本小姐馬上就能稱霸影鎮了！",
  str_voice_1601561_5 = "嗚啊哈哈哈，設計武器的靈感愈來愈多了！早就告訴過你嘛，本小姐是這方面的天才！",
  str_voice_1601561_6 = "在服裝設計、寶石鑑賞和武器製作方面的造詣已經爐火純青的本小姐，要開始征服下一個領域了！選什麼比較好呢......啊，有了，對空裔的研究！",
  str_voice_1601561_7 = "你也知道，本小姐呢，也算是比較著名的服裝設計師了。要我為你設計一身衣服也不是不可以喔。友情提示，這種時候回答「我的榮幸」才是正確答案！",
  str_voice_1601561_8 = "我們現在這樣算是......好朋友嗎？別誤會，我只是不想把感情浪費在不懂別人心意的傻瓜身上而已......",
  str_voice_1601561_9 = "PlayerName，你會想念你的父母嗎？沒什麼，只是忽然好想媽媽啊。如果媽媽還在，我應該會......把你介紹給她吧。",
  str_voice_1601561_10 = "把我帶過來，又無視我的存在......你到底有沒有禮貌啊？欸，難道是我哪裡做錯了......我不管！你不說清楚，我是不會道歉的！",
  str_voice_1601561_11 = "搞什麼嘛，把本小姐帶到這種窮酸的地方......欸，我不是討厭這裡的意思啦，笨蛋！既然把我帶過來，你......你可要好好注視著我才行！",
  str_voice_1601561_12 = "「少年被埋地下17年竟復活......」這也算是恐怖故事？現在庶民的品味就是這樣的嗎？",
  str_voice_1601561_13 = "咦——黑乎乎的一塊......這就是紅油燒烤？本小姐養的寵物狗都不會吃的好嗎？！不要硬塞給我啦......啊啊啊嗚啊嗚......欸，竟然，有點好吃？",
  str_voice_1601561_14 = "伊斯塔萬叔叔總是勸爸爸重出江湖......什麼嘛，爸爸不過是個天天宅在家裡的大叔，真有他說得那麼厲害嗎？",
  str_voice_1601561_15 = "這是本小姐做慈善的時候剩下的東西，才不是給你準備的生日禮物！啊......生，生日快樂。",
  str_voice_1601561_16 = "在忙什麼呢？欸，本小姐不是在關心你啦！這只是......只是......算了，不和你說了。",
  str_voice_1601561_17 = "不會還在睡覺吧？本小姐可不會屈尊親自叫你起床......嗯？怎麼還沒動靜，快醒醒啦！",
  str_voice_1601561_18 = "這麼晚了，你還在......工作嗎？沒什麼啦，本小姐也很忙的，才不會覺得寂寞呢。",
  str_voice_1601561_19 = "啊——！是你？笨蛋，大半夜的嚇死我了啦！還以為是鬼呢......",
  str_voice_1601561_20 = "影鎮就是本小姐的天下，欸？才......才不是因為我爸爸一直在幫我呢......",
  str_voice_1601561_21 = "白夜城？那地方......有什麼好去的？要是你真想去，我可以把我們家祖宅借你住兩天。",
  str_voice_1601561_22 = "本小姐在注視著你～",
  str_voice_1601561_23 = "管它是不是暗鬼，跟我對著幹的傢伙不會有好下場的！",
  str_voice_1601561_24 = "咳咳......不得不承認，貝菲爾和本小姐一樣優秀。唔......遲早有一天我會比她厲害一萬倍的！",
  str_voice_1601561_25 = "早苗慌張的樣子好可愛呼呼呼......嗯？我，我才沒有欺負過她呢！應該沒有吧......",
  str_voice_1601561_26 = "本小姐喜歡的東西可多著呢，有的也許你連聽都沒聽說過喔。",
  str_voice_1601561_27 = "我怕鬼？笑話，本小姐這麼愛看恐怖故事的人，怎麼會......啊嗚嗚剛才那是什麼，不會是鬼吧？",
  str_voice_1601561_28 = "巨像......好厲害！咳咳，給我點時間，我也要造一座！",
  str_voice_1601561_29 = "你就是PlayerName？哼，到處都有人在討論你，還以為你長得有多不一樣呢。我是妮娜·安德森，認識本小姐是你的榮幸。",
  str_voice_1601561_30 = "你們都給我看好了！",
  str_voice_1601561_31 = "靈感......湧現！",
  str_voice_1601561_32 = "上好的武器，又添了一件。",
  str_voice_1601561_33 = "我可以......只依靠自己的力量！",
  str_voice_1601561_34 = "看來你也不傻嘛。",
  str_voice_1601561_35 = "準備就緒～",
  str_voice_1601561_36 = "還要讓本小姐等多久啊？",
  str_voice_1601561_37 = "不自量力的傢伙！",
  str_voice_1601561_38 = "就給你們看看本小姐的收藏吧。",
  str_voice_1601561_39 = "好吵啊！",
  str_voice_1601561_40 = "你們這群......超級白痴！",
  str_voice_1601561_41 = "大家，要聽本小姐指揮喔！",
  str_voice_1601561_42 = "有本小姐坐鎮，勝利是理所應當的。",
  str_voice_1601561_43 = "本小姐才不會被打敗呢！",
  str_voice_1601561_44 = "可別告訴我這裡沒有喝下午茶的地方啊？",
  str_voice_1601561_45 = "呃，不會是什麼庶民品味的東西吧？",
  str_voice_1601561_46 = "既然是這個......那就沒辦法了呢。",
  str_voice_1601561_47 = "別太得意，我可沒說喜歡！",
  str_voice_1601561_48 = "原來你真的知道我的喜好......謝，謝謝。",
  str_voice_1601561_49 = "不要太小看我喔，本小姐好歹也是白夜城爵位的繼承者。為什麼不住在白夜城？這個......說來話長。",
  str_voice_1601561_50 = "真不明白，為什麼所有人都夸貝菲爾是影鎮的接班人......本小姐明明也在黎明學院名列前茅啊！",
  str_voice_1601561_51 = "爸爸這個傻瓜，我一直以為他是世界上最懂我的人，沒想到他根本不知道我想要的是什麼......沒關係，我會靠自己的力量爭取到想要的東西的！",
  str_voice_1601561_52 = "白夜極光！",
  str_voice_1601561_53 = "PlayerName！",
  str_voice_1601561_54 = "早安。",
  str_voice_1601561_55 = "不打算問候我午安嗎？",
  str_voice_1601561_56 = "你好。",
  str_voice_1601561_57 = "新年快樂，新年一定要願望成真唷。我的願望是......不告訴你！",
  str_voice_1501571_1 = "那個......呃......如您所見，我是一名女僕。我會......洗衣服，還會煮飯，還有還有......如果您需要的話，我還可以為您講一些遠東的睡前故事。",
  str_voice_1501571_2 = "-這個叫PlayerName的傢伙真的靠譜嗎？\n-我覺得......嗚啊啊啊！PlayerName先生？您什麼時候站在這裡的？那個，旁邊的這位是我的姐姐真枝......",
  str_voice_1501571_3 = "真枝姐姐很關心我，總是會站出來保護我......都怪我，是我太沒用了......啊，但是我會努力工作的！請您不要解僱我！",
  str_voice_1501571_4 = "-來艾斯特拉大陸打工之前......我從來都不知道在這邊生活還要擔心暗鬼。\n-精神損失費，誰來結算一下？",
  str_voice_1501571_5 = "-是錯覺嗎......最近摔倒的次數好像變少了很多......\n-嗯～嗯～小早苗長大了呢。",
  str_voice_1501571_6 = "-自從認識你以來，小早苗成長得非常迅速。也許有一天，她就不需要我了。\n-真枝姐姐......請不要這樣說......",
  str_voice_1501571_7 = "啊嗚啊嗚，烤鵝肝真的好好吃喔......唔啊啊啊，您來了？！那個我......我不是在偷偷吃東西......只是隨便想像一下，嘿嘿嘿。",
  str_voice_1501571_8 = "PlayerName先生，我想......謝謝您！因為，因為......我還從來沒有這麼長時間都沒被解僱呢。",
  str_voice_1501571_9 = "啊，PlayerName先生......難道就是傳說中會騎著白色的巨龍，踩著七彩的祥雲來接我回家的王子殿下嗎......",
  str_voice_1501571_10 = "-喂，說你呢！沒長耳朵嗎？你打算讓早苗在這裡等你等到什麼時候啊？\n-唔啊......姐姐，不可以這樣跟PlayerName先生說話的。那個......對，對不起！我等多久都沒關係的......真的。",
  str_voice_1501571_11 = "-欸......？我......我很樂意為您服務！\n-咳，先把酬勞談好再說。",
  str_voice_1501571_12 = "那個......巨像裡那種會飛的鳥......是叫螢盞嗎？不知道吃起來是什麼味道......欸，不可以吃嗎？唔......對不起！我不會擅自吃PlayerName先生的食物的。",
  str_voice_1501571_13 = "其......其實女僕不是我的第一份工作，我去賣過報紙、刷過油漆，還在碼頭搬過箱子......雖然很快就被解僱了。",
  str_voice_1501571_14 = "-呼......什麼時候才能還完債呢......\n-PlayerName，是不是該漲點工錢了？",
  str_voice_1501571_15 = "-那個......今天是您的生日嗎？祝您生日快樂！\n-生日禮物要等發了工錢才能送你了。",
  str_voice_1501571_16 = "唔啊啊......日安。您......為什麼這樣看著我？啊呃呃呃......是我工作得不夠認真嗎？",
  str_voice_1501571_17 = "呃呃......那個......尊敬的PlayerName先生，該......該起床了，早餐已經......為您準備好了。",
  str_voice_1501571_18 = "工作了一天......您，您辛苦了！我去幫您拿一杯熱牛奶吧？",
  str_voice_1501571_19 = "-啊......PlayerName先生，有什麼我可以為您服務的嗎？\n-怎麼又來了？現在已經是下班時間了！",
  str_voice_1501571_20 = "-雲島......是個很漂亮的地方喔。\n-除此之外的方面就很難評價了。",
  str_voice_1501571_21 = "-感謝影鎮接納了這樣的我......\n-哼，這裡也不全是好人。",
  str_voice_1501571_22 = "-打工......掙錢......還債......\n-吃頓好的。",
  str_voice_1501571_23 = "-暗鬼......凶凶的，還會吃人......好可怕！\n-有我在，不怕！",
  str_voice_1501571_24 = "貝菲爾小姐......真的是個很善良的人！她一直在幫我找工作呢。",
  str_voice_1501571_25 = "真枝姐姐總是在我身邊守護我，在我遇到困難的時候幫助我......如果不是她，我也......堅持不到今天。",
  str_voice_1501571_26 = "欸......喜歡的東西？啊，那個......我喜歡......喜歡......吃東西。這個算嗎？",
  str_voice_1501571_27 = "-騙子、人渣，都給我滾開點！\n-......噓，PlayerName先生不是那種人啦......大概。",
  str_voice_1501571_28 = "-巨像......是不是很快就能飛到雲島？\n-現在還不是回去的時候。",
  str_voice_1501571_29 = "唔啊！好痛......欸？對......對不起，我不是故意撞翻您的！那個......我是早苗，需要我背您去診所嗎？",
  str_voice_1501571_30 = "這次......一定能行......",
  str_voice_1501571_31 = "像米飯一樣香噴噴的......力量。",
  str_voice_1501571_32 = "再也不用餓肚子了......",
  str_voice_1501571_33 = "姐妹同心！",
  str_voice_1501571_34 = "啊嗚嗚......我，我嗎？",
  str_voice_1501571_35 = "嗚嗚嗚啊，這樣應該沒問題吧......",
  str_voice_1501571_36 = "啊，那個，我......",
  str_voice_1501571_37 = "真枝姐姐，拜託了！",
  str_voice_1501571_38 = "喂，你們擋著我的路了！",
  str_voice_1501571_39 = "咿——呀！",
  str_voice_1501571_40 = "想逃？沒門！",
  str_voice_1501571_41 = "我......我該怎麼做才好？",
  str_voice_1501571_42 = "呼～總算是......勝利了呢。",
  str_voice_1501571_43 = "糟了......會被扣工錢的......",
  str_voice_1501571_44 = "-唔......這裡有什麼我可以做的工作嗎？\n-給工錢的那種。",
  str_voice_1501571_45 = "-欸，是......給我的嗎？\n-小心有詐。",
  str_voice_1501571_46 = "-謝謝您......\n-你還滿大方嘛。",
  str_voice_1501571_47 = "-您對我......實在是太好了......\n-別有多餘的心思。",
  str_voice_1501571_48 = "-喜歡，最喜歡了！\n-別瞎想，她說的是這份禮物。",
  str_voice_1501571_49 = "走投無路的時候......我遇到了一個粉色頭髮的女孩。沒有她，我永遠都沒辦法坐上開往艾斯特拉大陸的船隻......",
  str_voice_1501571_50 = "-爸爸媽媽不在的時候......是半助叔叔收留了我。\n-那人真是個混蛋！關進監獄是他罪有應得。",
  str_voice_1501571_51 = "-真枝是我的雙胞胎姐姐......欸？我們看起來長得不像嗎？\n-你這人，眼睛長在後腦勺上了？",
  str_voice_1501571_52 = "白夜極光～",
  str_voice_1501571_53 = "唔啊啊啊......",
  str_voice_1501571_54 = "早......早安。",
  str_voice_1501571_55 = "欸......午安！",
  str_voice_1501571_56 = "祝您......晚安喔。",
  str_voice_1501571_57 = "新年快樂......欸？還要再說點什麼嗎？唔啊啊......",
  str_voice_1601581_1 = "這地方還真是不可思議......",
  str_voice_1601581_2 = "好了，準備出去走走吧。",
  str_voice_1601581_3 = "要開作戰會議了？",
  str_voice_1601581_4 = "嗯……",
  str_voice_1601581_5 = "如果你有什麼麻煩的話，可以告訴我。",
  str_voice_1601581_6 = "下一步要做什麼呢......",
  str_voice_1601581_7 = "很高興見到妳。",
  str_voice_1601581_8 = "這個世界......很有趣啊。",
  str_voice_1601581_9 = "有點懷念咖啡的味道......",
  str_voice_1601581_10 = "好了，開始吧。",
  str_voice_1601581_11 = "知道了，交給我吧。",
  str_voice_1601581_12 = "對我來說，住在哪裡都一樣，並沒太大區別......嗯，算是入鄉隨俗。",
  str_voice_1601581_13 = "準備好了嗎？",
  str_voice_1601581_14 = "判斷，就交給你了。",
  str_voice_1601581_15 = "生日快樂。",
  str_voice_1601581_16 = "沒問題，我準備好了。",
  str_voice_1601581_17 = "早安。",
  str_voice_1601581_18 = "得再認真一點啊。",
  str_voice_1601581_19 = "今天就先睡覺吧。",
  str_voice_1601581_20 = "這個……",
  str_voice_1601581_21 = "怎麼說呢......",
  str_voice_1601581_22 = "Showtime!",
  str_voice_1601581_23 = "暗鬼......\n就是我們現在應該打倒的敵人......",
  str_voice_1601581_24 = "很好......",
  str_voice_1601581_25 = "太棒了。",
  str_voice_1601581_26 = "喜歡的東西？\n如果一定要說的話，應該是「所有的東西」吧......",
  str_voice_1601581_27 = "討厭的東西？\n我可以回答「看情況」嗎？",
  str_voice_1601581_28 = "巨像......真是個奇怪的地方。",
  str_voice_1601581_29 = "代號「JOKER」。我來取走你的心了。",
  str_voice_1601581_30 = "還不錯。",
  str_voice_1601581_31 = "可以啊。",
  str_voice_1601581_32 = "好像變強了。",
  str_voice_1601581_33 = "來吧！亞森！",
  str_voice_1601581_34 = "我們走！",
  str_voice_1601581_35 = "就這麼辦！",
  str_voice_1601581_36 = "我拿走了！",
  str_voice_1601581_37 = "接招吧！",
  str_voice_1601581_38 = "到此為止！",
  str_voice_1601581_39 = "放棄吧！",
  str_voice_1601581_40 = "將軍！",
  str_voice_1601581_41 = "交給我吧。",
  str_voice_1601581_42 = "一切按計畫進行。",
  str_voice_1601581_43 = "在這裡失敗......",
  str_voice_1601581_44 = "怎麼了？",
  str_voice_1601581_45 = "我會收好的。",
  str_voice_1601581_46 = "那麼......我就收下了。",
  str_voice_1601581_47 = "謝謝。",
  str_voice_1601581_48 = "謝謝......不，也許應該說，我很榮幸。",
  str_voice_1601581_49 = "當你到了一個陌生的地方後，就會忍不住開始想起「那一天」......",
  str_voice_1601581_50 = "只有夥伴們的意見全體一致的時候，我們才會行動。",
  str_voice_1601581_51 = "真名是有的，但是......因為你看見的是這幅樣子的我，所以，現在還是用「代號」來稱呼我吧。",
  str_voice_1601581_52 = "白夜極光！",
  str_voice_1601581_57 = "新年快樂。",
  str_voice_1601581_58 = "結束了！",
  str_voice_1601591_1 = "想要瞭解這個世界的事......果然還是要從當地人那裡蒐集情報比較好吧？",
  str_voice_1601591_2 = "可能因為我的裝束，所以在這個世界裡，總是更容易被別人認為是「武鬥派」啦......",
  str_voice_1601591_3 = "這裡的人們過著怎樣的生活呢？我很好奇。",
  str_voice_1601591_4 = "必須要先觀察狀況，然後再冷靜地行動。",
  str_voice_1601591_5 = "一旦有了目標，就要在達成目標的路上不斷開拓！嗯......這種事，確實要自己好好把握。",
  str_voice_1601591_6 = "儘管目標不同......但我們那份「想要達成的心情」卻是一樣的。",
  str_voice_1601591_7 = "夥伴們！要振作起來喔。",
  str_voice_1601591_8 = "假如遇到了不明白的事......就在明白後，把所得和所學轉化為自己的知識！",
  str_voice_1601591_9 = "我對這個世界更加好奇了......比如說......嗯，是否會有學校之類的地方呢？",
  str_voice_1601591_10 = "啊，不好意思，我在想事情。",
  str_voice_1601591_11 = "明白，交給我吧！",
  str_voice_1601591_12 = "這座「巨像」裡......真的是什麼都有呢。",
  str_voice_1601591_13 = "姐姐......有好好吃飯嗎？",
  str_voice_1601591_14 = "這裡這麼寬敞，打掃起來應該很辛苦吧？",
  str_voice_1601591_15 = "生日快樂！雖然到了另一個世界，但是......能夠送上「生日快樂」這種祝福，還是讓我很開心！",
  str_voice_1601591_16 = "無論在戰鬥中，還是在生活裡，情報都很重要！",
  str_voice_1601591_17 = "早安，新的一天開始了喔。",
  str_voice_1601591_18 = "雖然這個時候容易犯睏......但請不要懈怠。喝杯咖啡怎麼樣？",
  str_voice_1601591_19 = "都這個時候了......差不多該睡了吧。",
  str_voice_1601591_20 = "稍微休息一下吧！要和我一起吃點甜的東西嗎？",
  str_voice_1601591_21 = "這個世界......與我們的世界有許多相似之處呢。",
  str_voice_1601591_22 = "好！開始工作吧！",
  str_voice_1601591_23 = "暗鬼......總覺得在夢裡見過這樣的東西呢。",
  str_voice_1601591_24 = "JOKER是值得依賴的首領！是的，對我們來說是不可或缺的存在。",
  str_voice_1601591_25 = "對我們來說，怪盜團是重要的容身之處......",
  str_voice_1601591_26 = "想去那種很遠的地方旅行！......哎，但要忍到考試之後才行。",
  str_voice_1601591_27 = "討厭的東西？嗯......與其說用「討厭」來逃避，我更傾向於去思考它們身上的優點。我這種想法還滿積極的吧？",
  str_voice_1601591_28 = "巨像究竟是用什麼技術建成的呢......？我很好奇......",
  str_voice_1601591_29 = "我是QUEEN，請多關照。要是能幫上什麼忙就好了。",
  str_voice_1601591_30 = "好像變強了一點？",
  str_voice_1601591_31 = "我們很合得來呢！",
  str_voice_1601591_32 = "嗯，很順利！",
  str_voice_1601591_33 = "瓊安！我們上！",
  str_voice_1601591_34 = "我將回應你的期待！",
  str_voice_1601591_35 = "隨時準備著！",
  str_voice_1601591_36 = "全力翱翔！",
  str_voice_1601591_37 = "覺悟吧！",
  str_voice_1601591_38 = "鐵・拳・制・裁！",
  str_voice_1601591_39 = "就是現在！",
  str_voice_1601591_40 = "我會解決的！",
  str_voice_1601591_41 = "到我出場了嗎？",
  str_voice_1601591_42 = "那麼，繼續前進吧！",
  str_voice_1601591_43 = "不能在這裡結束啊......",
  str_voice_1601591_44 = "「巨像」真是太有趣了，無論從史學，還是從構造學來講。",
  str_voice_1601591_45 = "不錯呢......",
  str_voice_1601591_46 = "是給我的嗎？",
  str_voice_1601591_47 = "謝謝......！我......很高興。",
  str_voice_1601591_48 = "我......可以收下嗎？......謝謝，我真的很開心！",
  str_voice_1601591_49 = "果然，教科書上沒有記載的事......的確讓人很興奮啊！",
  str_voice_1601591_50 = "「空之末裔嗎」......？不知道怎麼回事，我突然想起了「銀行」......",
  str_voice_1601591_51 = "巨像啊......像是遊戲世界才會出現的東西呢。唔......「遊戲」......「賭場」......姐姐......",
  str_voice_1601591_52 = "白夜極光！",
  str_voice_1601591_57 = "新年快樂！朝著目標努力前行吧！",
  str_voice_1601591_58 = "決不饒恕！",
  str_voice_1501601_1 = "......嗯？什麼啊，你也來散步啊。",
  str_voice_1501601_2 = "這就是巨像嗎。\n能從空中俯瞰大地，真是難得的體驗......",
  str_voice_1501601_3 = "在這個世界不用擔心交通的開銷啊......真不錯。",
  str_voice_1501601_4 = "這個世界的水真好喝啊，\n跟我們世界的自來水不分伯仲。",
  str_voice_1501601_5 = "還是海帶茶和甜品最搭啊。",
  str_voice_1501601_6 = "我裝束上的這根尾巴，坐下的時候\n好像有些礙事......",
  str_voice_1501601_7 = "你說自己是空之末裔的話，那我應該就是日本畫的明日之星......差不多這種感覺吧。",
  str_voice_1501601_8 = "巨像裡真是寬敞啊，甚至想向你借一處地方當做畫室了。",
  str_voice_1501601_9 = "這個世界有如此多我沒見過的東西，讓我的靈感不斷涌現。",
  str_voice_1501601_10 = "這裡的室內裝潢......是根據你的喜好來的嗎？",
  str_voice_1501601_11 = "讓我來，儘管交給我吧！",
  str_voice_1501601_12 = "我很中意這個世界，希望能夠在畫布上描繪出這些事物。",
  str_voice_1501601_13 = "巨像裡真是什麼都有啊。\n待會可以給我介紹一下嗎？",
  str_voice_1501601_14 = "有免費的食物提供嗎！實在太棒了！",
  str_voice_1501601_15 = "生日快樂。\n祝你在接下來的一年裡，\n生活能夠繽紛多彩。",
  str_voice_1501601_16 = "在這裡的經驗，會成為我繪畫的養分。",
  str_voice_1501601_17 = "早安。快到早餐的時間了吧？\n我想先品嚐一下這裡的飯食。",
  str_voice_1501601_18 = "是晚間散步嗎？真不錯。\n我也可以參加嗎？",
  str_voice_1501601_19 = "還沒睡嗎？真是個怪人。\n雖然我也是一樣。",
  str_voice_1501601_20 = "我也想要一同探索這個世界的奧祕，出發吧！",
  str_voice_1501601_21 = "尾巴、貓耳、龍角......\n這個世界的造物主\n真是很有品味啊。",
  str_voice_1501601_22 = "來，就由我為你展示最富有美感的行動。",
  str_voice_1501601_23 = "暗鬼......牠們的身姿裡，\n可沒有任何值得描繪的美感啊。",
  str_voice_1501601_24 = "JOKER是個值得信賴的領導者。",
  str_voice_1501601_25 = "有夥伴感覺也不壞。",
  str_voice_1501601_26 = "散步可真不錯，就連交通費都可以節省不少。",
  str_voice_1501601_27 = "我討厭的事物......對了，\n我不想和不懂審美的人扯上關係。",
  str_voice_1501601_28 = "從這「巨像」的外形之中，我能感受到「美」。",
  str_voice_1501601_29 = "心之怪盜團，FOX參上。\n你需要我的力量吧？",
  str_voice_1501601_30 = "刀與筆在使用方法上，存在著些許異曲同工之處。",
  str_voice_1501601_31 = "似乎變強了些。",
  str_voice_1501601_32 = "很順利，繼續吧。",
  str_voice_1501601_33 = "擊退牠們，五右衛門！",
  str_voice_1501601_34 = "看來該我出場了啊。",
  str_voice_1501601_35 = "這裡請交給我吧。",
  str_voice_1501601_36 = "你逃不掉了。",
  str_voice_1501601_37 = "是時候該覺悟了！",
  str_voice_1501601_38 = "他就是另一個我！",
  str_voice_1501601_39 = "有破綻！",
  str_voice_1501601_40 = "斬斷吧！",
  str_voice_1501601_41 = "斬成碎片！",
  str_voice_1501601_42 = "很好，讓我們邁向下一場勝利吧。",
  str_voice_1501601_43 = "這副不像話的模樣......抱歉。",
  str_voice_1501601_44 = "我在做什麼？正在「光靈觀察」是也。",
  str_voice_1501601_45 = "這是給我的嗎？先收下了。",
  str_voice_1501601_46 = "送給我禮物嗎？喔喔......！這是何等的美麗......！",
  str_voice_1501601_47 = "要把這麼好的東西送我......？那麼，我就領受了。",
  str_voice_1501601_48 = "太棒了，真是棒極了！\n看來你很懂我的喜好啊。",
  str_voice_1501601_49 = "不管是在哪裡，只要能畫畫就可以。",
  str_voice_1501601_50 = "最近我有些沉迷獻血。\n呵呵......這是我的新愛好。",
  str_voice_1501601_51 = "啊，今天好像是附近超市的特價日啊......喔，我現在正在異世界呢。",
  str_voice_1501601_52 = "白夜極光！",
  str_voice_1501601_57 = "新年快樂。\n在異世界迎來新的一年也不錯嘛。",
  str_voice_1501601_58 = "即將落幕！",
  str_voice_1501611_1 = "今天也加油吧！",
  str_voice_1501611_2 = "薇絲會給我們做一些奇怪的食物呢。雖然很在意它們的味道......不過，比起味道，好像更在意是否能吃飽......",
  str_voice_1501611_3 = "請問，你知道藝術體操嗎？",
  str_voice_1501611_4 = "關於這個世界的各種事......希望您能教給我更多呢。",
  str_voice_1501611_5 = "在這裡的各位，也都有自己應該去做的事情吧。",
  str_voice_1501611_6 = "戰鬥前請做好伸展運動喔。需要我來教你嗎？",
  str_voice_1501611_7 = "很高興能備受他人的期待，但也稍微會感覺到有些壓力呢。",
  str_voice_1501611_8 = "原來這裡叫做「巨像」啊......裡面居然有這麼多東西，真讓人感到驚訝。",
  str_voice_1501611_9 = "是問我......在做什麼嗎？\n硬要說的話，是在發呆呢！",
  str_voice_1501611_10 = "活動身體的時候，頭腦也會變得清醒。\n要一起做伸展運動嗎？",
  str_voice_1501611_11 = "為了能成為你的力量，我會加油的！",
  str_voice_1501611_12 = "吃甜食和吃主食的胃「不是同一個」喔！\n即使世界變了，這個道理也不會變呢！",
  str_voice_1501611_13 = "在這裡的經驗見聞，可以作為表演的參考也說不定。",
  str_voice_1501611_14 = "鍛鍊的時候，可千萬別忘了補充水分喔。",
  str_voice_1501611_15 = "生日快樂！",
  str_voice_1501611_16 = "喝杯茶，休息一下吧。",
  str_voice_1501611_17 = "早安！一起來晨練嗎？",
  str_voice_1501611_18 = "今天辛苦了，請好好休息吧。",
  str_voice_1501611_19 = "熬夜對身體不好喔！\n我也是，得趕緊睡覺了。",
  str_voice_1501611_20 = "辛苦了！",
  str_voice_1501611_21 = "在戰鬥的時候，我可是會非常認真，並且竭盡全力喔！",
  str_voice_1501611_22 = "加油！加油！",
  str_voice_1501611_23 = "暗鬼......\n看起來非常狂暴呢......",
  str_voice_1501611_24 = "我也要努力......成為大家的力量！",
  str_voice_1501611_25 = "MONA前輩可以變成汽車喔！......難道說在這個世界其實是很普通的事嗎？",
  str_voice_1501611_26 = "我喜歡的東西......嗎？\n當然是美味的料理之類的東西！不過如果是在大賽前，就必須要忍耐了......",
  str_voice_1501611_27 = "討厭的東西......嗎？\n應該是，不想陷入低谷吧。",
  str_voice_1501611_28 = "你竟然可以和「巨像」溝通嗎？\n稍微感覺有點不可思議。",
  str_voice_1501611_29 = "我的代號是VIOLET。\n為了能幫到大家，我會加油的。",
  str_voice_1501611_30 = "感覺變得更強了！",
  str_voice_1501611_31 = "由我來回應你的期待！",
  str_voice_1501611_32 = "全力以赴！",
  str_voice_1501611_33 = "舞動吧！辛德瑞拉！",
  str_voice_1501611_34 = "加油吧！",
  str_voice_1501611_35 = "交給我吧！",
  str_voice_1501611_36 = "像蝴蝶一樣！",
  str_voice_1501611_37 = "把勝利握在手中！",
  str_voice_1501611_38 = "起舞吧！PERSONA！",
  str_voice_1501611_39 = "集中！",
  str_voice_1501611_40 = "請反省吧！",
  str_voice_1501611_41 = "準備就緒！",
  str_voice_1501611_42 = "華麗落幕！",
  str_voice_1501611_43 = "不能輸......",
  str_voice_1501611_44 = "「巨像」裡也可以舉行慶典嗎？",
  str_voice_1501611_45 = "我收下了！",
  str_voice_1501611_46 = "給我的禮物......嗎？好高興！",
  str_voice_1501611_47 = "謝謝妳！",
  str_voice_1501611_48 = "咦！這麼棒的禮物，我真的能收下嗎？",
  str_voice_1501611_49 = "為了實現那個夢想......付出再多的努力我也願意......！",
  str_voice_1501611_50 = "能夠做出決定的......是「我自己」！",
  str_voice_1501611_51 = "和辛德瑞拉一起前進......我們，一起！",
  str_voice_1501611_52 = "白夜極光。",
  str_voice_1501611_57 = "新年快樂！\n今年也要打起精神振作起來喔！",
  str_voice_1501611_58 = "滿分的結果！",
  str_voice_1501621_1 = "吾輩不是貓！是人！！",
  str_voice_1501621_2 = "這地方感覺好不可思議啊。",
  str_voice_1501621_3 = "我還不怎麼瞭解這個世界，所以導航（navi）的工作就交給你啦。",
  str_voice_1501621_4 = "「身分不明」可是怪盜的美學喔。",
  str_voice_1501621_5 = "那就......請多多指教了！",
  str_voice_1501621_6 = "好～那就，出門吧！",
  str_voice_1501621_7 = "作為怪盜，需要時刻在心間銘記「幫助弱小，不阿諛強者」的不屈精神。",
  str_voice_1501621_8 = "如果你想像吾輩一樣厲害，那還需要加把勁訓練！",
  str_voice_1501621_9 = "喵嗚呼呼～閃閃發光的寶藏！\n......什麼嘛，原來是夢啊。",
  str_voice_1501621_10 = "不理人的話，吾輩可就去睡覺了喔？",
  str_voice_1501621_11 = "喔，輪到吾輩出場了嗎？",
  str_voice_1501621_12 = "吾輩保證這次表現非常得出色，所以準備好獎勵吧，\n就準備「大肥金槍魚刺身」好了。",
  str_voice_1501621_13 = "一想到現在正飛翔在空中，就感覺很不可思議......",
  str_voice_1501621_14 = "接觸不同文化也不錯。見識變廣了，吾輩也更有魅力了。",
  str_voice_1501621_15 = "生日快樂！以後也請多多關照喔！！",
  str_voice_1501621_16 = "喵嗚——！今天的吾輩，狀態依然不錯！",
  str_voice_1501621_17 = "睡得好嗎？那麼，今天也繼續努力吧！",
  str_voice_1501621_18 = "一天真是過得飛快啊，還有什麼沒做完的事嗎？",
  str_voice_1501621_19 = "今天就先睡覺吧！",
  str_voice_1501621_20 = "怪盜總能很優雅華麗地完成工作，無論何時。",
  str_voice_1501621_21 = "嗯，正中下懷！",
  str_voice_1501621_22 = "作戰開始！",
  str_voice_1501621_23 = "暗鬼......有必要仔細調查一番了。",
  str_voice_1501621_24 = "怪盜團可是吾輩親自訓練的。沒有什麼事是做不到的！",
  str_voice_1501621_25 = "怪盜團很酷？那是當然。\n他們可是吾輩看中的人。",
  str_voice_1501621_26 = "喜歡的東西......？\n如果是喜歡的人，怎麼說呢......也不是沒有......",
  str_voice_1501621_27 = "討厭的東西？嘲笑他人努力的傢伙......之類的？",
  str_voice_1501621_28 = "這個巨像如此巨大，它是怎麼在空中飛行的？",
  str_voice_1501621_29 = "哼哼哼，與吾輩MONA相遇，你要感到榮幸喔！",
  str_voice_1501621_30 = "哼，吾輩的魅力又增加了！",
  str_voice_1501621_31 = "這就是吾輩的力量！",
  str_voice_1501621_32 = "交給吾輩吧！",
  str_voice_1501621_33 = "衝吧！佐羅！",
  str_voice_1501621_34 = "該吾輩上場了！",
  str_voice_1501621_35 = "做好準備了！",
  str_voice_1501621_36 = "後悔也來不及了！",
  str_voice_1501621_37 = "出來吧！吾輩的半身！",
  str_voice_1501621_38 = "看著吾等決心的證明吧！",
  str_voice_1501621_39 = "覺悟吧！",
  str_voice_1501621_40 = "永別了！",
  str_voice_1501621_41 = "由吾輩發出指示！",
  str_voice_1501621_42 = "大家幹得不錯！",
  str_voice_1501621_43 = "到此為止了嗎......",
  str_voice_1501621_44 = "喂，巨像也能像吾輩一樣會變身嗎？",
  str_voice_1501621_45 = "喔，謝謝啦。",
  str_voice_1501621_46 = "要給吾輩的？謝謝啦！",
  str_voice_1501621_47 = "可以嗎？謝謝喔，好開心！",
  str_voice_1501621_48 = "真的可以收下嗎？！太棒了！",
  str_voice_1501621_49 = "等這些事情都告一段落了，想和大家一起去開「慶功宴」呢。",
  str_voice_1501621_50 = "雖然記憶模糊，但吾輩會使用行動做出成果！這就是吾輩成為「王牌」的原因。",
  str_voice_1501621_51 = "不知何時開始，自己變得常常被人所包圍。這是獨自一人時完全無法想像的情況呢......",
  str_voice_1501621_52 = "白夜極光！",
  str_voice_1501621_57 = "新年快樂！新的一年吾輩會繼續好好鍛鍊你的，要有覺悟喔！",
  str_voice_1501621_58 = "清掃完畢！",
  str_voice_1601641_1 = "我很慶幸自己選擇去白夜城外面看看，如果我滿足於城主之女的身分，只在白夜城裡巡邏，恐怕我永遠無法得知自己的這一面。",
  str_voice_1601641_2 = "所謂「劍」的善惡，都是空談。因為決定一把劍是否會危害他人的，並非是劍本身，而是握持武器的那隻手。",
  str_voice_1601641_3 = "艾斯特拉大陸應為所有文明種族共同所有、共同管理、共同建設，包括光靈，自然也包括空裔。",
  str_voice_1601641_4 = "勿以責任之小而毫無作為，勿以事情之小而逾界為之。",
  str_voice_1601641_5 = "某些時刻強大的意志力足以控制自身的力量，也足以改變現實。這便是「心勝於物」之理。",
  str_voice_1601641_6 = "路漫漫且有荊棘兮，吾輩不可退縮。道隱隱且有雲霧兮，吾輩自當明目。",
  str_voice_1601641_7 = "光可以作為護盾，如同白夜城擁有的那面。或許未來的某一天，我擁有的光將成為盾牌來保護大家，也保護你......",
  str_voice_1601641_8 = "如果血脈真的能夠帶來力量，那麼就能以此來決定高低尊卑？以此來號令他人？我覺得不妥......",
  str_voice_1601641_9 = "我有時候在想，如果我們能夠早一點相遇，並且你是一名光靈，或許現在就不一樣了。",
  str_voice_1601641_10 = "好悠閒......在長途跋涉的空檔，也有偶爾休息，發發呆，回想在白夜城四處巡邏抓人的日子......",
  str_voice_1601641_11 = "我會像守護白夜城一樣守護此地，因為巨像是你的家，而我是與你並肩前行的同路人。",
  str_voice_1601641_12 = "名為「腐朽」的黴菌已經污染了白夜城，如果不找到它們的源頭，是無法將之驅逐的。",
  str_voice_1601641_13 = "白夜城的未來，就是所有光靈的未來。文明、繁榮、富足與傳承，它們屹立萬年永不倒。",
  str_voice_1601641_14 = "英雄的血脈固然重要，但面對危機時自身的選擇才更為關鍵。英雄後代不免屈膝，無名之輩亦有勇士。",
  str_voice_1601641_15 = "希望在明年的今天，我們依舊能夠像現在這樣慶祝你的誕生之日。",
  str_voice_1601641_16 = "想要處理好政務，就要從紛繁複雜的事情中抽出一根線頭，一路細細順去，定會迎刃而解。",
  str_voice_1601641_17 = "清晨醒來時，若有一縷陽光照在床頭，那麼一整天的心情都會很好。",
  str_voice_1601641_18 = "處理了一天的事務想必很累吧，可以適當休息一下，比如聽一首古典樂？",
  str_voice_1601641_19 = "深夜的工作，搭配草莓椰奶糕的宵夜，別有情調。",
  str_voice_1601641_20 = "白夜城古老、穩定，而這長治久安帶來的另一面便是在光明之下悄然滋長的陰影。",
  str_voice_1601641_21 = "如果太過理性，則會失去感情，如果啟光在這條路上走得太遠，恐怕他們會變成機械。",
  str_voice_1601641_22 = "白夜至上，請照亮前方。",
  str_voice_1601641_23 = "光與暗無法相容，只能此消彼長。",
  str_voice_1601641_24 = "作為一城之主，舒瓦茲的責任之大、牽扯之多，恐怕也是他有時候不得不妥協的原因吧......",
  str_voice_1601641_25 = "作為同窗，我之前沒有太留意薇絲，然而當年不起眼的留學生，將來的名氣說不定要比我大。",
  str_voice_1601641_26 = "若無公序良俗，文明便會崩塌，隨之而來的便是各種比洪水猛獸更加可怕的事情。",
  str_voice_1601641_27 = "強大的能力並不可怕，可怕的是沒有相應的責任心與原則。兩者缺一不可，否則必將釀成災禍。",
  str_voice_1601641_28 = "或許有一天，巨像會與白夜城一同成為光靈的象征。",
  str_voice_1601641_29 = "卡蓮·德·舒瓦茲在此。無需為我擔心，並非是寒霜遠離了我，而是當下的我選擇了焰熔。",
  str_voice_1601641_30 = "更加......耀眼！",
  str_voice_1601641_31 = "長槍！燃起！",
  str_voice_1601641_32 = "輝煌屬於我們。",
  str_voice_1601641_33 = "光明與靈魂同在。",
  str_voice_1601641_34 = "我的長槍屬於你。",
  str_voice_1601641_35 = "磨礪以須。",
  str_voice_1601641_36 = "攻必克。",
  str_voice_1601641_37 = "光芒！暉映！",
  str_voice_1601641_38 = "長槍之下，焉有陰影！",
  str_voice_1601641_39 = "令敵人消失。",
  str_voice_1601641_40 = "無需仁慈。",
  str_voice_1601641_41 = "你的選擇很明智。",
  str_voice_1601641_42 = "帶領大家獲勝，是統帥的責任。",
  str_voice_1601641_43 = "知其不勝，故而不行。",
  str_voice_1601641_44 = "巨像的飛行能力確實優秀，如果用來巡視領地......",
  str_voice_1601641_45 = "感謝你的慷慨。",
  str_voice_1601641_46 = "還是你懂我......",
  str_voice_1601641_47 = "你的好意，我已十分瞭解。",
  str_voice_1601641_48 = "白夜至上，我不會忘記你的餽贈。",
  str_voice_1601641_49 = "光能真是奇妙，原本以為自己只能掌握寒冰的花朵，沒料到現在也能用熾烈的長槍來戰鬥。",
  str_voice_1601641_50 = "血脈本無高低，以此決定尊卑實在可笑。上位者需有能力，眾人方可信服。",
  str_voice_1601641_51 = "我偶爾夢到一片黑暗中，人們眼中的光芒消散，而我......舉著火炬前行。",
  str_voice_1601641_52 = "白夜極光。",
  str_voice_1601641_53 = "同行之人。",
  str_voice_1601641_54 = "新的一天開始了。",
  str_voice_1601641_55 = "到了一天的中間點了。",
  str_voice_1601641_56 = "白晝，已落幕。",
  str_voice_1601641_57 = "與你同行，我很榮幸，希望在新的一年中也能並肩進取。",
  str_voice_1501651_1 = "動力裝甲的根本是驅動裝置，需要考慮到能源材料、轉換率、結構性、傳動裝置，哎呀，實在是太複雜了。",
  str_voice_1501651_2 = "不知道空裔中有沒有科學家，否則怎麼維護這麼厲害的巨像。琪個......我是不是說錯話了......",
  str_voice_1501651_3 = "空裔的很多物品都太過神祕，上次嘗試畫螢盞的正視圖，結果一天一夜也沒搞出來......",
  str_voice_1501651_4 = "製圖當然也是繪畫！薇絲這麼說是對的！而且製圖比繪畫要好的一點是，勝負標準很清楚，只要看誰畫得最準確就行。",
  str_voice_1501651_5 = "動力裝甲不僅能夠用於戰鬥，在探索、挖掘、建設這些工作中也能很好地發揮，是未來啟光聯邦必需的裝備之一。",
  str_voice_1501651_6 = "導航員！我對設計圖有了新的理解！之前的計算有誤，這次看起來沒問題了，那件完美的動力裝甲很快就可以......",
  str_voice_1501651_7 = "你要作圖嗎？我這裡有一副祖傳的圓規和直尺，它們特別好用，之前薇絲跟我借，我都沒有答應。",
  str_voice_1501651_8 = "導航員，巨像不需要大修嗎？或者加裝些其他裝置？別擔心，在工程學上，我會給你很多幫助的。",
  str_voice_1501651_9 = "琪個......這件動力裝甲可能也到年限了，你有什麼特別的空裔科技幫我維修一下嗎？",
  str_voice_1501651_10 = "要不要坐進動力裝甲裡睡一下呢......反正也沒其他人。啊......琪個、琪個，我沒有在偷懶啦！",
  str_voice_1501651_11 = "工程學上的問題就交給我吧，至於其他方面，我就只能當個記錄員了，連建議都給不出，這樣真的沒問題？",
  str_voice_1501651_12 = "聽說你去過很多地方，有沒有見識到什麼新奇的材料？比如北境的綠礦石、紅油沙漠的沙蟲血......",
  str_voice_1501651_13 = "科學家是最重要的人才，就像動力裝甲的發動機一樣，是一個組織的靈魂！",
  str_voice_1501651_14 = "是誰發明的長跑與游泳......它們就和設計圖中的錯誤一樣，是不應該出現的！",
  str_voice_1501651_15 = "似乎過生日要送禮物呀？要送你什麼呢？動力裝甲模型如何？",
  str_voice_1501651_16 = "今天導航員有沒有列計畫表？否則工作可能會變成一團亂麻的。",
  str_voice_1501651_17 = "起得很早呀，要調試一下巨像嗎？",
  str_voice_1501651_18 = "偶爾也要休息一下，比如到吊床上躺一會......",
  str_voice_1501651_19 = "深夜很適合計算和製圖呢！當然，要是有靈感的話就更好了。",
  str_voice_1501651_20 = "啟光雲集了大陸上所有的頂尖科學家，能夠得到他們的指導，是我的幸運。",
  str_voice_1501651_21 = "紅油扳手有些技工的操作真是玄妙，明明沒有科學理論，卻靠經驗就能胡亂修好......",
  str_voice_1501651_22 = "為了啟明之光！我一定要完成那件動力裝甲！",
  str_voice_1501651_23 = "那些暗鬼的身體構造很像某些精密的機械，牠們到底是誰製造出來的呢......",
  str_voice_1501651_24 = "要是沒有貢露科研長，我可能還在設計圖上打轉，連動力裝甲的螺絲也搞不出來呢。",
  str_voice_1501651_25 = "在火車駕駛與操控上，卡戎長官簡直就是天才，只不過平時就......咳咳，習慣就好啦。",
  str_voice_1501651_26 = "就算給我十倍智商，我也發明不出吊床這麼舒服的東西！如果不是為了製作動力裝甲，我真想每天都在上面躺二十個小時......",
  str_voice_1501651_27 = "在公開場合取笑別人的傢伙，是不是應該都送到精煉爐中......",
  str_voice_1501651_28 = "結構、系統設計、材料都遠超現在的技術，這到底是哪些天才設計的呢......",
  str_voice_1501651_29 = "別看我是負責開鑿隧道的，實際上我是名工程師！這件動力裝甲就是我的作品，它還是未完成的型號，不要隨便亂碰喔！對了，我叫琪爾。",
  str_voice_1501651_30 = "技術力變強了。",
  str_voice_1501651_31 = "系統已換代。",
  str_voice_1501651_32 = "結構性......更上一檔。",
  str_voice_1501651_33 = "動力強大，充滿幹勁。",
  str_voice_1501651_34 = "要幫忙挖隧道嗎？",
  str_voice_1501651_35 = "斯提克斯，準備好了。",
  str_voice_1501651_36 = "太陽箭，已就緒。",
  str_voice_1501651_37 = "太陽箭，釋放！",
  str_voice_1501651_38 = "太陽箭，全域籠罩！",
  str_voice_1501651_39 = "無死角！發射！",
  str_voice_1501651_40 = "滿載！發射！",
  str_voice_1501651_41 = "讓我來擔任團隊的發動機！",
  str_voice_1501651_42 = "就像擰螺絲一樣容易！",
  str_voice_1501651_43 = "逃跑的隧道我已經挖好了......",
  str_voice_1501651_44 = "這座巨像的結構太特別了，需要仔細測量研究一下。",
  str_voice_1501651_45 = "我會把它放進房間裡的。",
  str_voice_1501651_46 = "哇！是它！我收下了！",
  str_voice_1501651_47 = "謝謝！要怎麼給你回禮？",
  str_voice_1501651_48 = "太好了！給你也造一套動力裝甲，怎麼樣？",
  str_voice_1501651_49 = "雙腿上的動力裝甲與現在這套並不搭配，它其實是一件失敗作品的產物。",
  str_voice_1501651_50 = "雖然父母只是普通工人，然而他們卻鼓勵我成為一名工程師，事實表明這個選擇是正確的。",
  str_voice_1501651_51 = "如果不是因為自己的玩心，或許那件完美的動力裝甲早就造出來了。",
  str_voice_1501651_52 = "白夜極光。",
  str_voice_1501651_53 = "你在吧！",
  str_voice_1501651_54 = "早上就要擰緊發條啊！",
  str_voice_1501651_55 = "即便是機器也要午休的。",
  str_voice_1501651_56 = "工作可以告一段落啦。",
  str_voice_1501651_57 = "又是新的一年......看來動力裝甲的設計進度要加快了。",
  str_voice_1601661_1 = "哼，等著吧，等哪天我和凱羅變強了，就去找那些看不起我的傢伙報仇！",
  str_voice_1601661_2 = "嗯？想知道流浪貓半夜聚在一起是在聊什麼？還是不知道比較好吧，畢竟是和統治艾斯特拉大陸有關的話題......",
  str_voice_1601661_3 = "「毒可可肉菇——長得像蘑菇的神奇動物。牠們吃了巧克力之後，會陷入舒適的幻覺狀態，繼而成群結隊地入侵城市中的甜品店。」——這應該是師父瞎編的吧。",
  str_voice_1601661_4 = "菲雅的皮膚變得比之前更光滑啦～軟軟彈彈。但是PlayerName不用羡慕，菲雅會無私地把護膚品分享給你，這可是用凱羅的分泌物製成的！",
  str_voice_1601661_5 = "警戒！全員警戒！菲雅的觸角察覺到了危險訊號！周圍有神奇動物正在接近，就在菲雅背後——啊，原來是PlayerName啊。",
  str_voice_1601661_6 = "凱羅在情緒平穩的情況下是藍白色，受到刺激會變成黑紅色。但我也確實看到過牠變成霓虹燈一樣閃爍的彩虹色。那到底代表著什麼？還是說我在做夢？",
  str_voice_1601661_7 = "凱羅扭了扭屁股，又蹦了兩下，牠到底想說什麼？難道是在罵我？",
  str_voice_1601661_8 = "啊啊啊——草率了，企鵝和北極熊原來是光靈嗎？！還有那只鱷魚......菲雅收服神奇動物之路果然才剛剛開始......",
  str_voice_1601661_9 = "PlayerName孤身一人，真是太可憐了。不如......菲雅收養你好了！菲雅可是有責任心的主人，把衣食住行全交給菲雅安排也沒有問題。",
  str_voice_1601661_10 = "啊啊啊——笨蛋凱羅，還有笨蛋PlayerName，不要盯著我看啦！！",
  str_voice_1601661_11 = "讓可愛的女孩子做傭人的工作，每天起早貪黑站在這裡，還要露出八顆牙齒做營業性微笑。殘忍的大人可真是精明，你必須，必須多給菲雅點零花錢。",
  str_voice_1601661_12 = "討厭那些看不起我的傢伙，更討厭看不起臭師父的人！",
  str_voice_1601661_13 = "嗚哇？！幹，幹嘛突然嚇唬我？",
  str_voice_1601661_14 = "菲雅知道自己很可愛了，所以可以不要摸我的頭了嗎？",
  str_voice_1601661_15 = "祝你......你的生日是這個日子嗎！得記到《神奇動物大冒險》裡。",
  str_voice_1601661_16 = "早安、午安、晚安，招呼都打了一遍了喔！",
  str_voice_1601661_17 = "這個時間也太早了，必須睡個回籠覺，不然長不高。",
  str_voice_1601661_18 = "晚飯時間！你喜歡吃海藻嗎？菲雅可以分你一點。",
  str_voice_1601661_19 = "哈——哈——啾，想打哈欠結果變成打噴嚏了，唔......",
  str_voice_1601661_20 = "我們是專業的、職業的、內行的、靠譜的神奇動物研究保護團隊。",
  str_voice_1601661_21 = "抱歉喔，菲雅只喜歡神奇動物，對光靈沒什麼興趣。",
  str_voice_1601661_22 = "抓捕，進化，放生！",
  str_voice_1601661_23 = "暗鬼到底是怎麼繁殖的呢？牠們的數量不會衰減，難道是無性生殖？",
  str_voice_1601661_24 = "無所事事的中年男人根本沒有說服力，臭師父他是個大騙子啊！",
  str_voice_1601661_25 = "師姐她，雖然是條奇怪的章魚，但也是個好女人呢，嗯。",
  str_voice_1601661_26 = "菲雅喜歡亮閃閃的玻璃、糖果、寶石，但最喜歡的還是神奇動物。",
  str_voice_1601661_27 = "喂！PlayerName，說你呢，不許無視我！",
  str_voice_1601661_28 = "菲雅想在巨像裡增設神奇動物孵化室、培育室、訓練室和墓地——",
  str_voice_1601661_29 = "沒錯，我就是傳說中的神奇動物訓練師，牠是我的搭檔凱羅。哼，怎麼樣，害怕了嗎？",
  str_voice_1601661_30 = "菲雅變強了！但凱羅沒什麼變化。",
  str_voice_1601661_31 = "渾身上下滑溜溜溜～～滑溜溜～",
  str_voice_1601661_32 = "唔咪！觸角豎起來了！",
  str_voice_1601661_33 = "徹底地蛻變與新生！進化吧，菲雅！",
  str_voice_1601661_34 = "欸，不應該是六人小隊嗎？",
  str_voice_1601661_35 = "準備準備準備！",
  str_voice_1601661_36 = "上鉤囉～",
  str_voice_1601661_37 = "上吧，凱羅，Plan A！",
  str_voice_1601661_38 = "凱羅，改變計畫，Plan B！",
  str_voice_1601661_39 = "快來幫忙！",
  str_voice_1601661_40 = "夥伴的力量！",
  str_voice_1601661_41 = "哼哼，隊長當然是我啦～",
  str_voice_1601661_42 = "作戰計畫大成功～",
  str_voice_1601661_43 = "好，好討厭的感覺！！",
  str_voice_1601661_44 = "這個觸感......總覺得，凱羅是不是長胖了？",
  str_voice_1601661_45 = "真的可以收下嗎？",
  str_voice_1601661_46 = "欸欸欸，難道說PlayerName喜歡......",
  str_voice_1601661_47 = "哇！是禮物！",
  str_voice_1601661_48 = "嗚啊啊啊～～你對菲雅也太好了吧！",
  str_voice_1601661_49 = "菲雅到現在都記得，《千奇百怪的小動物》的扉頁上寫著：「致所有寂寞的、孤獨的、無助的人：別被自己的負面想法困住，睜開眼睛看看外面的世界吧，那裡有無數與你相同而又不同的生靈。」",
  str_voice_1601661_50 = "哈啊——師父真是我遇到過的最不靠譜的男人了，師姐也是奇奇怪怪的女人。是正常人都不願意成為神奇動物專家嗎？我是不是選錯發展方向了......",
  str_voice_1601661_51 = "「尊重神奇動物的習性與願望，不要把自己的想法強加給牠們。」只有明白了這一點，才能和神奇動物和睦相處呀，菲雅也是最近才領悟到的。",
  str_voice_1601661_52 = "白夜極光",
  str_voice_1601661_53 = "是菲雅喔！",
  str_voice_1601661_54 = "早呀。",
  str_voice_1601661_55 = "午安午安！",
  str_voice_1601661_56 = "晚，哈欠——安。",
  str_voice_1601661_57 = "是新年喔！是新年喔！新年快樂！！",
  str_voice_1601671_1 = "優秀的視覺可以把人們拉進情緒超載的深淵。最令人狂喜又恐懼的是，視覺可以提供一種讓我們將已知的萬物聯繫起來的能力......",
  str_voice_1601671_2 = "來自深海的氣泡破碎著捲過船邊的聲音。船體縫隙中嗚咽著穿過的狡詐之風的聲音。以及那些將在這裡被獻出的奇蹟湧動著逼迫我令它們展露出來的聲音。",
  str_voice_1601671_3 = "我熟悉那些走投無路的人身上散發出來的氣息，因為我也曾是其中一員。",
  str_voice_1601671_4 = "挑剔的卡牌正在浩瀚的思緒中挑選理智，庸俗的蠢材將無法承受這張牌面的謎底。",
  str_voice_1601671_5 = "事態開始變得灼熱，這次開牌的結果將會令敵人膽寒。",
  str_voice_1601671_6 = "怒火奏響此刻的樂章，卡牌的光澤在此刻交相輝映。呵呵，黃金對我來說臭得令人發昏。",
  str_voice_1601671_7 = "魔術，這種奇蹟代表著人與物之間精妙的博弈，要強迫你的肌肉牢記這種玄妙的技巧......我的襪子穿反了。",
  str_voice_1601671_8 = "這種奇妙的感覺是？控制表情的手段不再生效，汗液卻源源不斷地侵蝕我的後背......我知道了，附近一定有不少敵人。",
  str_voice_1601671_9 = "抱歉，我在出汗。可僅僅是「站在這裡注視著您」，就已經是我的底牌了。",
  str_voice_1601671_10 = "我不喜歡發呆的時刻。這種時候會有很多我無法控制的思緒胡亂地遊走，它們會自顧自地回溯到那些被我努力忽視的時間線上。",
  str_voice_1601671_11 = "棲身之處是如此安靜，令人不安。也許該把頭摘下來......頭不能被摘下來。",
  str_voice_1601671_12 = "我並不在意除了魔術之外的那些搖搖欲墜的東西，它們嘲弄我，因此我也嘲弄它們。",
  str_voice_1601671_13 = "魔術演出是一種華麗的暗示，技術的地基和視覺的亂舞，二者缺一不可。語言？過於重視語言會把人導入晦澀的暗巷。",
  str_voice_1601671_14 = "時間的流逝會讓您惱怒於自身的無力，而真理，只有真理能提供您所渴求的一切意義......這樣宣傳就能完成維多利亞女士的任務了吧。",
  str_voice_1601671_15 = "生日快樂。您今天想看什麼樣的表演？",
  str_voice_1601671_16 = "今天，我將會把自己完全而真切地投射到那充斥著神祕色彩的閃光與怪誕無序的狂想的魔術世界中。",
  str_voice_1601671_17 = "黑咖啡果然是最不錯的，如果我端穩了杯子的話。",
  str_voice_1601671_18 = "飛舞著卻無法抓住的靈感們......會在此刻終於肯俯下身，願意鑽進我的腦子裡嗎？",
  str_voice_1601671_19 = "又一個被魔術拯救因此才不得不到來的深夜啊。睡吧？",
  str_voice_1601671_20 = "起源之牌與聲名鵲起都是那位女士送給我的禮物。",
  str_voice_1601671_21 = "您知道這個世界上何處的餐飲文化最發達嗎？也許我會想去那裡看看。",
  str_voice_1601671_22 = "願真理祝福您。",
  str_voice_1601671_23 = "我憎恨一切不精巧的生物......也許牠們連生物都算不上。",
  str_voice_1601671_24 = "虹霞承擔了那些我無法忍受的事情。",
  str_voice_1601671_25 = "曾經和他是可以將眼淚和傻乎乎的大笑託付給彼此的關係，直到責任把我們裹得愈來愈緊。",
  str_voice_1601671_26 = "我並不吝嗇於為孩子們來一場演出，他們總會讓人覺得更自在。",
  str_voice_1601671_27 = "對於我來說，肥胖會降低表演的靈活程度，所有的道具也需要調整尺寸。",
  str_voice_1601671_28 = "雖然可以飛翔，但是卻無緣於蕩漾。",
  str_voice_1601671_29 = "尊敬的觀眾，您好。我是綠榴石號馬戲航船的團長，魔術師傑諾。敬請期待吧，這次會面只是演出的序章。",
  str_voice_1601671_30 = "是個好戲法。",
  str_voice_1601671_31 = "新花樣。",
  str_voice_1601671_32 = "被眷顧的起源之牌。",
  str_voice_1601671_33 = "到頂點了嗎？",
  str_voice_1601671_34 = "我知道了。",
  str_voice_1601671_35 = "道具就緒。",
  str_voice_1601671_36 = "想看個戲法嗎？",
  str_voice_1601671_37 = "好好看著！",
  str_voice_1601671_38 = "一齣好戲！",
  str_voice_1601671_39 = "為我尖叫！",
  str_voice_1601671_40 = "感受轟鳴！",
  str_voice_1601671_41 = "我將收下您的期待。",
  str_voice_1601671_42 = "正常的。",
  str_voice_1601671_43 = "是長胖了嗎......",
  str_voice_1601671_44 = "雖然這座巨像也算是個奇蹟，但有離你更近的奇蹟。",
  str_voice_1601671_45 = "這是打賞？謝謝。",
  str_voice_1601671_46 = "您這豐盈的餽贈......",
  str_voice_1601671_47 = "我在緊張。",
  str_voice_1601671_48 = "我，可以為您獻上什麼呢......",
  str_voice_1601671_49 = "趕海、看日出、把一直待在家裡的我揪出去認識新的朋友......曾經這些事都是和艾維斯一起做的，曾經。",
  str_voice_1601671_50 = "為了躲避暗潮危機，父母帶著我來到了綠榴石號上生活，但它當時還不屬於我。",
  str_voice_1601671_51 = "那時候，我瞞著父母和教會我魔術的那個人一起離開了綠榴石號，去了大陸上歷練，因此才認識了那位女士。",
  str_voice_1601671_52 = "白夜極光。",
  str_voice_1601671_53 = "尊敬的觀眾。",
  str_voice_1601671_54 = "是時候從夢境中醒來了。",
  str_voice_1601671_55 = "午安，我該準備下午的演出了。",
  str_voice_1601671_56 = "萬籟俱寂，休息吧。",
  str_voice_1601671_57 = "新年快樂。希望我能找到頂點，又突破頂點。",
  str_voice_1501681_1 = "各位觀眾，大家好啊～讓我聽見你們的歡呼～～～哦？怎麼沒有聲音呀？是不是有人想涼快一下？我手裡的碧海之槍可以幫你們喔～",
  str_voice_1501681_2 = "呀呀，你是不是在皺眉頭呀？不開心的話，和虹霞一起玩水吧！快來，想像一下......這裡是遼闊的大海，隨著波濤一起漂浮......",
  str_voice_1501681_3 = "虹霞有做過發聲練習喔！就是那種能讓聲音更加甜美清澈的訓練啦。嘿嘿，這是為了讓所有來看演出的客人都能聽清並且喜歡我說的話～",
  str_voice_1501681_4 = "虹霞快要控制不住了！想給這個世界更多水花～更多更多的涼爽和輕快！",
  str_voice_1501681_5 = "哇呀哇呀！感覺自己造出了很多艘艦船呢！不僅有綠榴石號這樣的巨艦，還有鐵甲船、捕魚船、遠洋船......咳咳，雖然都還只是模型而已。",
  str_voice_1501681_6 = "綠榴石號的第一護衛虹霞，隨時準備出擊！潛水、偵查魚群、綠榴石號的日常維護，全都沒有問題！請下達指令！",
  str_voice_1501681_7 = "親愛的觀眾，現在是中場報幕時間～～請把目光再次放回到虹霞身上喔？很好很好！虹霞看到你期待的眼神和輕快的笑容啦～",
  str_voice_1501681_8 = "你想要免票的話，當......當然沒問題啦！！先讓我算一算我這個月的工錢，如果要付你這份的話......唔！你，你什麼都沒聽到！！",
  str_voice_1501681_9 = "現在我們的狀況，是我想像的那樣嗎？你......你對其他人，不會也說過一樣的話吧？",
  str_voice_1501681_10 = "沒有掌聲嗎？這樣的話，就連虹霞也會覺得有點寂寞呢～",
  str_voice_1501681_11 = "不再是暖場表演和中場報幕了嗎？這，這次虹霞終於可以來一次正式又完整的表演了嗎？！哇嗚嗚......客人您對虹霞真是太好啦！！",
  str_voice_1501681_12 = "下雨的時候馬戲團總是手忙腳亂的，要先把各種道具給收起來，然後要去處理那些被淋壞的擴音器......說起修這個啊，我可在行啦！",
  str_voice_1501681_13 = "欸欸，人氣高這種說法只不過是大家在哄虹霞而已啦！我才不會單飛呢，我還要留在團裡向輪機師學更多機械知識～",
  str_voice_1501681_14 = "我修補了水桶，怎麼樣？好看嗎？嘿嘿，我也覺得很好看！不過有很多地方還在漏水呢......",
  str_voice_1501681_15 = "生日快樂！！今天無論你想做什麼虹霞都會陪你的喔？",
  str_voice_1501681_16 = "嗨嗨～今天要不要和虹霞一起抓魚呢？欸——用網子？不行不行，當然是和我一起徒手抓魚才好玩呀！",
  str_voice_1501681_17 = "早！剛剛好像看到了一艘很帥氣的遠洋船！啊？那是個飛過的小信使嗎？",
  str_voice_1501681_18 = "今天沒有演出，做些什麼好呢？規劃夜晚的時間嗎？沒那個必要啦，隨緣不就好啦～",
  str_voice_1501681_19 = "你怎麼還醒著呢？難道是故意等著虹霞來催你睡覺嗎？好啦，那就快睡吧！",
  str_voice_1501681_20 = "綠榴石號最棒啦，虹霞將來會做出來的船其次！哦哦，忘記了還有臨空者號呀......",
  str_voice_1501681_21 = "那些來自啟光的客人總是有很多新鮮的裝備，真想去那裡看看呀！",
  str_voice_1501681_22 = "虹霞會隨時守護你的安全喔～～",
  str_voice_1501681_23 = "還要打敗多少這樣的敵人才行呢？",
  str_voice_1501681_24 = "傑諾團長啊，雖然他看起來冷冰冰的，但只要和他多說幾句話......嘿嘿嘿。",
  str_voice_1501681_25 = "總有一天，我也會成為和師父一樣厲害的輪機師......吧？",
  str_voice_1501681_26 = "我真的很喜歡現在的生活！虹霞喜歡水，喜歡馬戲團，喜歡現在這個對一切都充滿好奇的自己！",
  str_voice_1501681_27 = "一定要說的話，應該是討厭乾燥吧？除此以外還有點不喜歡那種沒意思的人呢。",
  str_voice_1501681_28 = "飛，飛天巨艦臨空者號！！嗚嗚，為什麼我不是空裔，不可以和牠說話呢......",
  str_voice_1501681_29 = "嘿！你好嗎？我是虹霞——綠榴石號的唯一指定護衛！馬戲團的新任成員？那只是我的兼職而已啦！",
  str_voice_1501681_30 = "嘩啦啦！",
  str_voice_1501681_31 = "水壓強化——",
  str_voice_1501681_32 = "噴泉噴泉！",
  str_voice_1501681_33 = "超大浪花！",
  str_voice_1501681_34 = "加入艦艇編隊啦！",
  str_voice_1501681_35 = "時刻準備著！",
  str_voice_1501681_36 = "放我出去！",
  str_voice_1501681_37 = "虹霞來啦！",
  str_voice_1501681_38 = "炸開，水花！",
  str_voice_1501681_39 = "增壓！",
  str_voice_1501681_40 = "高壓發射！",
  str_voice_1501681_41 = "啊啊！知道啦！",
  str_voice_1501681_42 = "運氣真不錯呀～",
  str_voice_1501681_43 = "我絕不會投降......",
  str_voice_1501681_44 = "感覺巨像上有點乾燥呀，我幫你灑點水吧？",
  str_voice_1501681_45 = "我收下啦！",
  str_voice_1501681_46 = "嘿嘿，馬上放進貼身口袋。",
  str_voice_1501681_47 = "你......這是在向虹霞示好嗎？",
  str_voice_1501681_48 = "我，我可以收下這份心意嗎？",
  str_voice_1501681_49 = "我啊，應該算是個在水裡長大的孩子吧？從小就經常跟著爸爸媽媽出海捕魚，還老是拿著爸爸給我做的水槍跑來跑去的，哈哈哈。",
  str_voice_1501681_50 = "木板一號和魚竿二號，它們都是我在海上獨自生活那段時間的好夥伴。如果沒有它們，我也不知道自己該怎麼度過那段失去爸爸之後又失去了媽媽的日子......",
  str_voice_1501681_51 = "比爾馬戲團的老團長是我的救命恩人！哎，可惜我真的沒辦法靜下心來鑽研那種魔術技巧，就連他也拿我沒辦法。",
  str_voice_1501681_52 = "白夜極光！！",
  str_voice_1501681_53 = "嗨！小觀眾？",
  str_voice_1501681_54 = "早呀，早上最適合抓魚啦！",
  str_voice_1501681_55 = "午安午安！好熱喔！",
  str_voice_1501681_56 = "我今晚有表演呢～",
  str_voice_1501681_57 = "新年快樂！今年也邊演出邊朝著「成為輪機師」這個目標而努力吧！",
  str_voice_1600384_10 = "你在幹什麼呢？再這樣下去我可就要開始覺得無聊了。PlayerName，看過來呀！",
  str_voice_1600384_11 = "嗯？莫非這是某種「水族館體驗」之類的遊戲嗎？我在扮演水族館裡面的小魚，而你是玻璃之外的遊客......嘻嘻，聽起來還滿有趣！",
  str_voice_1600384_16 = "正是研究攻略的好時間呢～嘿嘿，你來找我一定是想跟我一起打遊戲吧？",
  str_voice_1600384_17 = "可惡，打了一整夜，還差一點點就要過關了！！\n可現在必須要先去科研室分享昨天下午的研究結果......",
  str_voice_1600384_18 = "我之前試著按照烹飪遊戲裡曾提到的菜譜來煮飯。咳，至於結果嘛......還是讓那些東西留在遊戲世界裡吧。",
  str_voice_1600384_19 = "你也在線上？哇哇，現在可是在排行榜上更進一步的最佳時刻呀！",
  str_voice_1600384_35 = "貢露，新版本！",
  str_voice_1600384_36 = "我在這裡——！",
  str_voice_1600384_37 = "這是大招按鈕！",
  str_voice_1600384_38 = "最——高——等——級！",
  str_voice_1600384_39 = "你要輸了！",
  str_voice_1600384_40 = "你輸了！",
  str_voice_1600384_44 = "很喜歡我的新造型嗎？嘿嘿，多謝你啦。",
  str_voice_1600384_58 = "魚兒們會追隨你的行動呢，就好像遊戲裡那些時刻都會陪伴在主角身邊的夥伴似的。嗯？這次，PlayerName是夥伴，而我是主角嗎？",
  str_voice_1600384_59 = "可以更靠近一點嗎？更近一點，再近一點......哎呀，小心！距離到這裡就可以了。再靠近的話，我們也許會交換位置喔？還是說，你也想試試待在這裡面的感覺呢？",
  str_voice_1600384_60 = "無論一款遊戲有多難，只要多試幾次，總能過關。要是有人願意付出多些時間的話，更是可以很輕鬆就拿到那種「完美獎勵」......你覺得不輕鬆嗎？和真實世界比起來，總歸是要輕鬆很多的吧！",
  str_voice_1600384_61 = "雖然這套裝束的露出面積比較多，但是如果我穿著它去科研室的話，最先臉紅的人應該不是我，而是尤尼梅特吧。",
  str_voice_1600384_62 = "對我來說做研究和玩遊戲一樣簡單呀，起碼這兩件事都有個固定的「標準答案」。沒錯，有答案的問卷做起來總是比較簡單嘛～",
  str_voice_1600384_63 = "偶爾也會重溫一下那些早就過關了的遊戲呢......大概是無法捨棄當時自己為了過關而付出的努力，和投射到遊戲世界中的那些情感吧。",
  str_voice_1600384_64 = "早呀......",
  str_voice_1600384_65 = "早安！你喜歡大海嗎？",
  str_voice_1600384_66 = "早！今天我要和希諾普一起去試驗場喔！",
  str_voice_1600384_67 = "早喔，我已經開始工作了。",
  str_voice_1600384_68 = "有事請留言～沒有回覆的話就是在工作喔～",
  str_voice_1600384_69 = "猜猜我中午吃什麼？",
  str_voice_1600384_70 = "嘿！午安！今天我嘗試了新題材的遊戲呢！",
  str_voice_1600384_71 = "今天中午得好好休息才行呢。",
  str_voice_1600384_72 = "今天午休的時候幹點什麼好呢？",
  str_voice_1600384_73 = "又到這個時候了啊～",
  str_voice_1600384_74 = "嘿嘿，吃了好吃的宵夜！",
  str_voice_1600384_75 = "可惡可惡可惡可惡！剛剛居然輸掉了！",
  str_voice_1600384_76 = "嗚嗚......今天過關的遊戲，裡面的故事好感人......",
  str_voice_1600384_77 = "每晚睡前你會想些什麼呢？",
  str_voice_1501301_1 = "某個案子裡的原告在陳詞時打了個嗝，惹惱了審判官，結果被判全家流放，死在外地，然後那個審判官也被查了。唉，多少生命因為一個嗝而逝去。",
  str_voice_1501301_2 = "牢房不夠的話，會影響到審判官的判決，導致重罪輕罰或輕罪重罰。雖然妨礙程式正義，但結果通常會有一方滿意。",
  str_voice_1501301_3 = "空裔會用那種「感應能力」來進行判決嗎？或在腦子裡進行辯護？不過，在腦子裡的話，就不能使用話術了。",
  str_voice_1501301_4 = "如果螢盞是有智慧的生物，那麼你算不算對牠們進行了奴役？這可是違法的，開庭、開庭！",
  str_voice_1501301_5 = "不熟悉法律條文？沒關係，我可以給你背出來，不過至於有用沒用，那就要靠你自己判斷了。",
  str_voice_1501301_6 = "什麼？你說某些法律變成了空中樓閣？那不是一件很正常的事情嗎？畢竟在白夜城，那些傢伙只負責寫不負責執行。",
  str_voice_1501301_7 = "若要在巨像上開庭，我可以身兼多職——審判官、檢察官和律師，然後判處對方敗訴。若要執行判決結果的話，那就得請你來了！",
  str_voice_1501301_8 = "名字愈好聽就愈不對勁，比如：慈善的貴族、正義的騎士、忠誠的侍從，以及文明的白夜城。",
  str_voice_1501301_9 = "在看過很多案件內幕後，我感覺白夜城還不如墜落在地，砸個稀爛。",
  str_voice_1501301_10 = "巨像是要涉及《繼承法》還是《契約法》？螢盞要不要單獨立法來加以保護？好煩啊，要不乾脆罰你一筆錢吧。",
  str_voice_1501301_11 = "要本審判官在這種地方開庭？完全不行！哦......只是讓我呆著，那好吧。正好可以考慮如何訂立巨像上的法律。",
  str_voice_1501301_12 = "如果要在巨像上訂立法律，首先要討論巨像是一處領地還是一個生物，這兩者可大相徑庭。",
  str_voice_1501301_13 = "我最滿意的一次判決，是讓一對在衝動之下訴訟離婚的夫妻達成了和解，但由於浪費了我的時間，所以對每人都罰了大一筆錢。",
  str_voice_1501301_14 = "法條不能包括所有情況，所以可以根據判例或自己的想法來進行創新，並進行判決。所以說，白夜城也有與時俱進之處。",
  str_voice_1501301_15 = "由於你的年紀沒有記錄在白夜城官方機構中，所以就「永葆青春」了。不過，還是祝你生日快樂。",
  str_voice_1501301_16 = "不用管天氣好壞，今天很適合開庭！因為我想到了——啊不，是記起了新的法條，正好試驗一下。",
  str_voice_1501301_17 = "這麼早就想打官司？材料準備齊全了？準備好就先回去吧，今天休息。",
  str_voice_1501301_18 = "程式正義、結果正義，都比不上傍晚的一杯不加糖的溫咖啡正義。",
  str_voice_1501301_19 = "好累。我都開始思考法律是如何帶來公平正義這種問題了，看來真是不休息不行了。",
  str_voice_1501301_20 = "大眾們為了白夜城而努力奮鬥，大人們則在白夜城裡盡情享受。",
  str_voice_1501301_21 = "沒有秩序的地方，那裡的人簡直就是牲畜，不過雜誌真不錯，嘿嘿。",
  str_voice_1501301_22 = "白夜至上。白夜城好，眾貴族好，你好我好大家好。",
  str_voice_1501301_23 = "聽不懂法律的生物真可憐，只能永遠站在被告席上了。",
  str_voice_1501301_24 = "儘管我的一生已如灰燼，但至少可以相信伊倫汀審判長，因為她是特別的。",
  str_voice_1501301_25 = "看到基汀就想到過去的我。要不要和他們組成「基汀審判」組合？我來當隊長，一定很犀利的。",
  str_voice_1501301_26 = "落錘的響就是正義的化身，當然降臨在其他人頭上是最爽的。",
  str_voice_1501301_27 = "對於那些懂得法律卻又喜歡把它掛在嘴邊的傢伙，我會宣布判決：「請結束你的人生」。",
  str_voice_1501301_28 = "牠違反了本審判官最新訂立的《白夜城天空法》第一條，故判決將其沒收。",
  str_voice_1501301_29 = "維護法律正義是有代價的，如果要付出代價，那麼最好從別人開始。所以本審判官來了，避免你出現這種情況。",
  str_voice_1501301_30 = "法條又增加了！",
  str_voice_1501301_31 = "判決沒有失誤。",
  str_voice_1501301_32 = "一秒判決。",
  str_voice_1501301_33 = "我，即法典。",
  str_voice_1501301_34 = "我會見證的。",
  str_voice_1501301_35 = "準備開庭。",
  str_voice_1501301_36 = "可陳詞。",
  str_voice_1501301_37 = "眾人入席。",
  str_voice_1501301_38 = "眾人入庭。",
  str_voice_1501301_39 = "開——庭！",
  str_voice_1501301_40 = "肅靜！",
  str_voice_1501301_41 = "我來負責主審。",
  str_voice_1501301_42 = "勝訴。",
  str_voice_1501301_43 = "隔日重審吧。",
  str_voice_1501301_44 = "請安靜，我要在這裡開庭了。",
  str_voice_1501301_45 = "這點東西就想賄賂我？",
  str_voice_1501301_46 = "我會為你辯護的。",
  str_voice_1501301_47 = "賄賂是有罪的，下次不許了。",
  str_voice_1501301_48 = "哦！判決將對你有利！",
  str_voice_1501301_49 = "我五歲的時候就能背誦一整套法典，所以獲得了提前入學的機會。",
  str_voice_1501301_50 = "那時，我被稱為「百年難得一見的奇才，操控法律的死神」。",
  str_voice_1501301_51 = "我曾是個明白大是大非的人，但在那之後，我選擇閉上雙眼，無視一切，不視、不聽、不言。",
  str_voice_1501301_52 = "白夜極光。",
  str_voice_1501301_53 = "發言吧。",
  str_voice_1501301_54 = "早安，現未開庭。",
  str_voice_1501301_55 = "午安，休庭。",
  str_voice_1501301_56 = "晚安，閉庭。",
  str_voice_1501301_57 = "新的一年，我將給予你新的公正。",
  str_voice_1601701_1 = "你笑起來的樣子，真像那個孩子啊......可以的話多笑笑吧，這是我打算用盡一生去守護的。",
  str_voice_1601701_2 = "充滿硝煙的戰場終有一天會開滿鮮花，破敗的教堂也會重新迎來白鴿。",
  str_voice_1601701_3 = "人們總是把希望寄存於未來，但若是我們沒有「未來」呢？",
  str_voice_1601701_4 = "以鬥爭追求和平，則和平長存。以妥協來求取的和平，那便不是和平。",
  str_voice_1601701_5 = "只有真實地身處戰爭的陰影下，才能切身體會到戰爭的沉重與殘忍。",
  str_voice_1601701_6 = "我是如此討厭那些蠅營狗苟、心中毫無信仰的人，但我深知自己也和他們一樣。",
  str_voice_1601701_7 = "PlayerName，也許你的存在，就是為了給我們光靈帶來一束希望。",
  str_voice_1601701_8 = "如果事與願違，就相信未來一定另有安排。如果萬事順遂，就一定不要忘記那些在黑暗中前進的時光。",
  str_voice_1601701_9 = "好好珍惜現在和平的時光吧，去享受、去品味、去感悟......和我們一起。",
  str_voice_1601701_10 = "身為一名雇傭兵，鬆懈下來可不是好事啊......需要我在你腦袋上開一槍嗎？",
  str_voice_1601701_11 = "讓我來做這種事嗎？呵呵呵......你就和那群離不開我的孩子們一樣呢。",
  str_voice_1601701_12 = "唔......你是有話要同我說嗎？沒關係，我一直在，會仔細聽你說的。",
  str_voice_1601701_13 = "雖然我們曾經都失去了家人，但漫漫餘生......也許我們還有機會去選擇新的「家人」。",
  str_voice_1601701_14 = "你和巨像是什麼關係呢？是家人？還是摯友？摯友這個身分可是很危險呢......",
  str_voice_1601701_15 = "PlayerName，生日快樂。「希望我們可以永遠在一起！」——那群孩子讓我轉達給你的。",
  str_voice_1601701_16 = "等候你多時了，可不要被那幫傢伙小看了啊！",
  str_voice_1601701_17 = "你是剛醒？還是未曾離開......",
  str_voice_1601701_18 = "今天辛苦你了，我猜你需要來一杯熱牛奶放鬆一下？",
  str_voice_1601701_19 = "早點休息吧？我們有的是時間。",
  str_voice_1601701_20 = "弱肉強食是大人世界裡的法則，孩子們只要以孩子的方式生活就好。",
  str_voice_1601701_21 = "影鎮嗎？有機會的話，我倒是很想把那裡的時裝店都逛個遍呢。",
  str_voice_1601701_22 = "招惹烏鴉血前，請三思而後行。",
  str_voice_1601701_23 = "暗鬼這種毫無信仰的存在，就該泯滅於世間。",
  str_voice_1601701_24 = "卡斯特是個好孩子，如果可以的話，我希望她不要再背負那麼多......",
  str_voice_1601701_25 = "安塔蕾斯，我們還會再相見的，不論相隔多遠，一定。",
  str_voice_1601701_26 = "聽說你手裡有一批來自影鎮的新款時裝？應該都很適合我吧......",
  str_voice_1601701_27 = "讓它們離我遠一點，這不該是你現在該接觸的東西。",
  str_voice_1601701_28 = "你把巨像養育到這麼大，一定也很辛苦吧......什麼？竟是牠在養育你嗎？",
  str_voice_1601701_29 = "人們無需崇拜光，當你為自己追求的「正義」而全力以赴時，你也可成為光。",
  str_voice_1601701_30 = "這感覺真不賴～",
  str_voice_1601701_31 = "呼～讓人渾身一輕。",
  str_voice_1601701_32 = "有什麼變得不一樣了，不是嗎？",
  str_voice_1601701_33 = "戰場將被我引爆！",
  str_voice_1601701_34 = "不錯的選擇！",
  str_voice_1601701_35 = "還在猶豫什麼？",
  str_voice_1601701_36 = "一網打盡！",
  str_voice_1601701_37 = "你們甚至不配讓我開槍。",
  str_voice_1601701_38 = "遇上我，是你們的不幸。",
  str_voice_1601701_39 = "雷嗔電怒！",
  str_voice_1601701_40 = "萬夫莫敵！",
  str_voice_1601701_41 = "讓我帶領你們再一次走向勝利！",
  str_voice_1601701_42 = "呵，還沒一群孩子耐打！",
  str_voice_1601701_43 = "唔......是我心軟了嗎？",
  str_voice_1601701_44 = "呵，你看我那麼認真，是不是有話想對我說啊～",
  str_voice_1601701_45 = "這是送給我的嗎？呃......我是說......謝謝。",
  str_voice_1601701_46 = "有趣，我會銘記這份心意的。",
  str_voice_1601701_47 = "準備這個一定費了你不少精力吧？",
  str_voice_1601701_48 = "真想拿回去給那群孩子們看看啊～",
  str_voice_1601701_49 = "尤佛里亞早已沒有什麼道德可談，但我希望教堂裡至少能是正常世界的樣子。",
  str_voice_1601701_50 = "我總是橫加干涉那群孩子的選擇，又何嘗不是希望他們不要活成下一個我呢？",
  str_voice_1601701_51 = "安塔蕾斯，我的心靈之友。人生能得一摯友何其幸運？但要親手埋葬摯友，又是何其可哀？",
  str_voice_1601701_52 = "白夜極光。",
  str_voice_1601701_53 = "又見面了～",
  str_voice_1601701_54 = "你今天看起來心情不錯？",
  str_voice_1601701_55 = "你一天到晚總是這麼渾身充滿能量嗎？",
  str_voice_1601701_56 = "天色不早了，晚睡的孩子長不高。",
  str_voice_1601701_57 = "新年快樂，PlayerName。願明年的今日，我們仍能在一起度過這個節日。",
  str_voice_1501711_1 = "在尤佛里亞的生活其實讓我感到很自在，除了生存之外的事情都不需要關心。",
  str_voice_1501711_2 = "啊，你不用那麼謹慎，我只會對貓屋敷開那種玩笑，況且我槍法很準。",
  str_voice_1501711_3 = "戰鬥是為了不把自己珍視的地方讓給其他人。",
  str_voice_1501711_4 = "拔槍速度變慢，無異於把生命交到敵人手裡。請放心，我絕不會讓那樣的事發生。",
  str_voice_1501711_5 = "這份工作讓我作為傭兵的能力成長了許多，謝謝你，看來幸運女神沒有放棄我呢。",
  str_voice_1501711_6 = "無論以後過上怎樣的生活，我都不會忘記戰鬥的感覺，戰鬥的感覺就是活著的感覺。",
  str_voice_1501711_7 = "我很相信自己的「幸運」，因為我總能遇見貴人。",
  str_voice_1501711_8 = "你......感受到了，我對你的信賴？太好了。",
  str_voice_1501711_9 = "巧克力棒？給我的？啊！原來你還記得我戒掉了那個，謝謝。",
  str_voice_1501711_10 = "這樣的悠閒也許會令人變得怠惰，緊繃的弦一旦鬆懈便無法恢復如初。請放心，我絕不會變成那樣。",
  str_voice_1501711_11 = "只要保護你的安全就可以了嗎？這個我擅長。嗯？是我誤會了什麼嗎？",
  str_voice_1501711_12 = "失去右腿對我來說也不全是壞事，這讓我每一步都深思熟慮。",
  str_voice_1501711_13 = "珀拉珂？她不需要時刻在我的視線裡，我們的心是連著的，這一點我們比任何人都清楚。",
  str_voice_1501711_14 = "和你在一起的時候會讓我有種無所不能的錯覺，這就是被信賴的感覺嗎？",
  str_voice_1501711_15 = "生日快樂，姑且準備了禮物。啊，你不要抱太大期待。",
  str_voice_1501711_16 = "吃飯了嗎？戰鬥前我會補充些糖分，低血糖很麻煩。",
  str_voice_1501711_17 = "已經習慣了陰雲連綿的日子，我也有機會看見太陽嗎？",
  str_voice_1501711_18 = "吵到你了嗎？新的義肢還在適應中，抱歉。",
  str_voice_1501711_19 = "我在這裡，別擔心。直到天亮之前我都會呆在你看得到的地方。",
  str_voice_1501711_20 = "在尤佛里亞佔據一席之地的烏鴉血只有兩個人，很厲害吧。",
  str_voice_1501711_21 = "從影鎮來的渡，我認為他是個可靠的人。或許那裡是個值得一去的地方。",
  str_voice_1501711_22 = "招惹烏鴉血之前，請三思而後行。",
  str_voice_1501711_23 = "遊樂園的射擊攤位上作為射擊目標的擺設，差不多是那種東西吧。",
  str_voice_1501711_24 = "我和她早已不是語言可以表達的關係，總之，我會站在她身邊，永遠。",
  str_voice_1501711_25 = "雖然他嘴上不說，但我清楚他為我們做了很多。你不要告訴他！",
  str_voice_1501711_26 = "說你信賴我的話，我......可以不要報酬。",
  str_voice_1501711_27 = "太繁瑣的事。不是做不來，只是不想做。",
  str_voice_1501711_28 = "如此龐大的巨像，飛行起來卻毫無阻礙，真讓人羡慕。",
  str_voice_1501711_29 = "雖然我不是職業的，但我的實力不會讓你失望。話說在前面，你可要準備好與我實力相襯的報酬。",
  str_voice_1501711_30 = "嗯，感覺不錯。",
  str_voice_1501711_31 = "早說過了，我很厲害的。",
  str_voice_1501711_32 = "更認真的話要加錢。",
  str_voice_1501711_33 = "勝局已定。",
  str_voice_1501711_34 = "你是說......團隊合作？",
  str_voice_1501711_35 = "已到達最佳位置。",
  str_voice_1501711_36 = "等你下令。",
  str_voice_1501711_37 = "這把刀可不是裝飾。",
  str_voice_1501711_38 = "好討厭會動的靶盤啊。",
  str_voice_1501711_39 = "滿分射擊。",
  str_voice_1501711_40 = "一個不落。",
  str_voice_1501711_41 = "靈活作戰吧。",
  str_voice_1501711_42 = "理所應當。",
  str_voice_1501711_43 = "幸運女神下班了？",
  str_voice_1501711_44 = "幸運女神今天也在眷顧著我呢。",
  str_voice_1501711_45 = "額外的報酬？謝謝。",
  str_voice_1501711_46 = "孩子們也會喜歡這個的，謝謝。",
  str_voice_1501711_47 = "總是猜中我的喜好，幸運女神也在幫你嗎？",
  str_voice_1501711_48 = "我現在對你下次會送我什麼很是期待。啊，不要感到負擔。",
  str_voice_1501711_49 = "對於我來說，珀拉珂早已超出了友人、家人的範疇。我從來沒想去做什麼英雄，只要是為了保護她，成為反派也沒關係。",
  str_voice_1501711_50 = "關於我很幸運這件事，其實我一開始並沒有注意到。但也許不發現更好，一旦依賴上這不真實的能力，很快就會發現幸運總伴隨著與之等價的不幸。",
  str_voice_1501711_51 = "不是有那種說法嗎，其實人會對苦味上癮。我也一樣，這樣的人生對我來說剛剛好。啊，不過那根可以被點燃的東西，我和珀拉珂已經戒掉了。",
  str_voice_1501711_52 = "白夜極光。",
  str_voice_1501711_53 = "在？",
  str_voice_1501711_54 = "記得吃早飯。",
  str_voice_1501711_55 = "正午的陽光真刺眼啊。",
  str_voice_1501711_56 = "又是平和的一天，晚安。",
  str_voice_1501711_57 = "新年快樂，又平安地度過了一年呢。",
  str_voice_1601721_1 = "身為演員，形象管理可是重要的必修課之一呢，所以沒錢的時候少吃兩頓飯不算什麼啦，可以順便減肥，多好呀。",
  str_voice_1601721_2 = "好想去海濱城市生活一段時間呀，聽說那裡的海鮮價格都很便宜，幾十白夜幣就能隨便吃海蟹......吸溜。",
  str_voice_1601721_3 = "要出門嗎？等一下、等一下，我要找找我的墨鏡和帽子，如果被狗仔發現我和空裔一起走在街上，又要被當作花邊新聞爆料了。",
  str_voice_1601721_4 = "哇，不愧是我，這段影像拍得如此有意境，構圖也很完美，肯定會大賣的，我要在這盒錄影帶上面簽上我的名字！",
  str_voice_1601721_5 = "我們來合影吧～來看鏡頭——等一下，你的表情太呆滯了，和未來家喻戶曉的大明星一起合影的機會可是很難得的喔，笑得燦爛一點嘛！",
  str_voice_1601721_6 = "畢竟我這行也是要靠臉吃飯嘛，自我投資是很重要的，我在包裝自己這件事上可不會節省，聰明的人要把錢花在刀刃上！",
  str_voice_1601721_7 = "我怎麼覺得除了演戲，我還有導演的天賦呢？乾脆試試自導自演好了！",
  str_voice_1601721_8 = "要不要一起看電影，恐怖片怎麼樣？放心，這些電影的套路我都摸清楚了，到嚇人的地方我會提前告訴你的～",
  str_voice_1601721_9 = "其實仔細看看，你長得真的滿帥的呢。要不要跟我合作拍部電影呀？憑你的資質和我的才華，電影一定會火的！",
  str_voice_1601721_10 = "你好像很忙的樣子，那我邊背台詞邊陪你吧。唔？這個劇本是不是寫錯了，明明我是女八號，為什麼我只有一句台詞？",
  str_voice_1601721_11 = "這裡環境真好，先記下來，之後有機會的話可以來這裡取景～",
  str_voice_1601721_12 = "要不要一起去逛街買東西？殺價就交給我吧，當初買下「塞洛洛」我可是只花了兩百白夜幣。",
  str_voice_1601721_13 = "爆米花真的很好吃，也很充飢。我剛到影鎮的時候沒什麼錢，有時候餓得不行了，會去影院門口撿走別人吃剩下的爆米花桶。",
  str_voice_1601721_14 = "出演路人甲又怎麼了？哪怕只露一面，或者只有一句台詞，不也算是參演了嘛～我都會認真準備的。",
  str_voice_1601721_15 = "我可是花重金拍了一支影片給你作為生日禮物喔，快關燈一起欣賞！",
  str_voice_1601721_16 = "哈欠——是你呀，要不要一起去喝杯咖啡？昨天我又熬夜看劇本了。",
  str_voice_1601721_17 = "你起得好早喔，我要繼續去睡回籠覺了......",
  str_voice_1601721_18 = "我要出門啦，這個時間點狗仔記者會少一點。",
  str_voice_1601721_19 = "哇，你也睡得這麼晚？正好，你陪我對一下台詞吧。",
  str_voice_1601721_20 = "影鎮的「好夢塢」可是很多演員和導演的事業起點唷！",
  str_voice_1601721_21 = "我很喜歡紅油沙漠狂野的美感，很想給紅油扳手的人拍一支紀錄片！",
  str_voice_1601721_22 = "透過鏡頭，我在注視著你。",
  str_voice_1601721_23 = "暗鬼的型態也很多種多樣呢，說不定拍電影的時候可以用得上牠們。",
  str_voice_1601721_24 = "克萊肯先生經常幫我聯繫工作，雖然薪酬很少，不過還是很感謝他！",
  str_voice_1601721_25 = "烈雀是第一個認出我是「影鎮之戰」電影裡被炸飛的那個臨演的人！",
  str_voice_1601721_26 = "透過鏡頭去看這個世界，整個世界都會變得非常不一樣喔。",
  str_voice_1601721_27 = "狗仔真的很討厭，上次我被緋聞對象的粉絲丟了十幾顆雞蛋。",
  str_voice_1601721_28 = "嗚哇！這......這麼豪華的地方，真的可以讓我住進來嗎？",
  str_voice_1601721_29 = "我是影鎮知名導演兼演員，莉莉卡，代表作還正在籌備中，不過可以先給你一份我的簽名喔。",
  str_voice_1601721_30 = "好像忽然有很多靈感。",
  str_voice_1601721_31 = "投資我是正確的選擇。",
  str_voice_1601721_32 = "看著吧，我絕對會出名的。",
  str_voice_1601721_33 = "優雅是演員的必修課！",
  str_voice_1601721_34 = "唔，陽光好曬。",
  str_voice_1601721_35 = "攝影機準備就緒。",
  str_voice_1601721_36 = "姿勢擺好了嗎？",
  str_voice_1601721_37 = "哎呀，曝光過度了！",
  str_voice_1601721_38 = "開機！",
  str_voice_1601721_39 = "上吧，塞洛洛！",
  str_voice_1601721_40 = "卡，這條重拍！",
  str_voice_1601721_41 = "該我出場了！",
  str_voice_1601721_42 = "慶祝一下，今天不吃蒸馬鈴薯了～",
  str_voice_1601721_43 = "別灰心，貧窮比失敗更可怕。",
  str_voice_1601721_44 = "我在透過鏡頭觀察巨像，好像有很多場景都很適合拍攝呢。",
  str_voice_1601721_45 = "我無以為報，給你簽個名吧！",
  str_voice_1601721_46 = "你怎麼知道我在攢錢買這個？！",
  str_voice_1601721_47 = "你還滿會討女孩子歡心～",
  str_voice_1601721_48 = "等我富貴起來，一定不會忘了你。",
  str_voice_1601721_49 = "因為海鮮太貴了，小時候都是只有我過生日的時候爸爸媽媽才會買一些回家。等我收到了這次的片酬，一定要接他們來影鎮吃一次海鮮大餐！",
  str_voice_1601721_50 = "這是我小時候爸爸媽媽送我的攝影機，雖然款式很老，但是拍出來的畫面很有質感。我經常用它拍各種我喜歡的東西，不過就是膠捲的價格有點貴。",
  str_voice_1601721_51 = "我做過臨演、蹲在路邊吃盒飯、穿厚厚的戲服中過暑，還被炸飛過，但是拍電影對我來講充滿了樂趣，所以一點都不覺得辛苦呢。",
  str_voice_1601721_52 = "白夜極光。",
  str_voice_1601721_53 = "在做什麼呢？",
  str_voice_1601721_54 = "哈欠——我好睏喔。",
  str_voice_1601721_55 = "睡醒了好餓，吃點什麼呢？",
  str_voice_1601721_56 = "新的一天才剛剛開始！",
  str_voice_1601721_57 = "我們叫上大家一起來拍攝新年短片吧！",
  str_voice_1601731_1 = "冒昧打擾了，請問您對花的種類有什麼偏好嗎？我曾向雲島來的商人們請教過插花的技藝，如果您同意，我可以用鮮花來裝點一下我們的餐桌。",
  str_voice_1601731_2 = "雖然我個人對您有著良好的評價，但距離獲得老爺的認可，您需要學習的還有很多。不過別擔心，我會幫助您的。",
  str_voice_1601731_3 = "我並不會讀心術。預測主人和客人的期望後，提前做好安排並嚴格地去執行，這只是身為安德森家管家的基本要求。",
  str_voice_1601731_4 = "剛剛我把徘徊在附近的暗鬼清除了一遍，暫且可以清靜一段時間了。如果您願意的話，我很樂意陪您在附近散散步。",
  str_voice_1601731_5 = "嚴格按照時間表的計畫行事才能確保每日工作順利完成，畢竟時不再來，因此我起床後第一件事就是校準我的懷錶。",
  str_voice_1601731_6 = "對於時局的把控依賴於經驗的累積，無論是商場還是戰場都是如此。不過您在這方面有很高的天賦，我可以跟您分享一些我的心得。",
  str_voice_1601731_7 = "稍等，您的衣服......這裡好像被劃破了。凡事必作於細，不能放過任何細微的問題。您可以將它換下來交給我，我會將它縫補好。",
  str_voice_1601731_8 = "我只是恰好有空，才隨手做了這些菜，不知道合不合您口味？啊，您的嘴角沾上了奶油，我幫您擦掉吧。",
  str_voice_1601731_9 = "跳舞是必備的社交手段，您身為妮娜大小姐的朋友，還請務必掌握這項技能。嗯？還在等什麼，請把您的手放在我的腰側。",
  str_voice_1601731_10 = "在這種地方睡覺會著涼的，如果您不介意，我可以帶您回房間休息，床褥和香薰都已經準備好了。",
  str_voice_1601731_11 = "感謝您邀請我來做客，不過我剛剛用手帕擦拭扶手時發現了一些灰塵，請允許我將這裡打掃一下。",
  str_voice_1601731_12 = "您真的很容易受傷，請坐下，我幫您清理一下傷口。",
  str_voice_1601731_13 = "嗯？不好意思，您剛剛說什麼？哦，我並不是太累了，我只是會利用一切機會休息，養精蓄銳而已，勞您費心了。",
  str_voice_1601731_14 = "作為安德森家的管家，只做到這些是不夠的，我必須向著「完美」不斷修行。",
  str_voice_1601731_15 = "生日快樂，我擅自做主為您準備了一場晚宴，還喊了您親近的友人們來一同慶祝。如果您不介意的話，請允許我帶您去更衣準備。",
  str_voice_1601731_16 = "我知道您很忙，但還是請您記得按時吃飯，照顧好自己的身體。",
  str_voice_1601731_17 = "稍後的早茶您想吃藍莓覆盆子芝士蛋糕，還是雪頂舒芙蕾呢？",
  str_voice_1601731_18 = "看您的臉色很疲憊，想泡個澡嗎？熱水已經放好了。",
  str_voice_1601731_19 = "良好的作息會讓白天事半功倍，要照顧好自己的身體。",
  str_voice_1601731_20 = "我所做的一切都不足以回報老爺對我的恩情。",
  str_voice_1601731_21 = "無論是白夜城還是影鎮，我不會允許任何人傷害到老爺和小姐。",
  str_voice_1601731_22 = "任何對安德森家族圖謀不軌的人，都會在我的注視之下被消滅。",
  str_voice_1601731_23 = "我無法允許世界上存在暗鬼這樣不堪入目的造物。",
  str_voice_1601731_24 = "妮娜大小姐的內心是非常善良單純的，我會用我的生命守護她。",
  str_voice_1601731_25 = "早苗雖然肢體協調能力有些令人擔憂，但妮娜大小姐很喜歡她。",
  str_voice_1601731_26 = "一切都井井有條、乾乾淨淨的，是一件令人心情愉悅的事情。",
  str_voice_1601731_27 = "我不太能理解，為什麼有些人可以忍受自己的房間如此淩亂？",
  str_voice_1601731_28 = "巨像的裝潢非常具有美感，只是每天來往的人這麼多，一定要常打掃。",
  str_voice_1601731_29 = "我是安德森家的管家，米洛斯，很榮幸能夠見到您。雖然不能成為您的專屬管家，但我會盡可能幫上忙。",
  str_voice_1601731_30 = "凡事多做幾次就會有經驗。",
  str_voice_1601731_31 = "我還不夠「完美」。",
  str_voice_1601731_32 = "這種感覺，很新奇。",
  str_voice_1601731_33 = "我會努力回饋您的信任。",
  str_voice_1601731_34 = "我明白了。",
  str_voice_1601731_35 = "等候您的指令。",
  str_voice_1601731_36 = "是否要收網呢？",
  str_voice_1601731_37 = "速戰速決吧。",
  str_voice_1601731_38 = "別擔心，我會提供最溫柔的入睡服務。",
  str_voice_1601731_39 = "請消失吧。",
  str_voice_1601731_40 = "骯髒。",
  str_voice_1601731_41 = "請放心交給我。",
  str_voice_1601731_42 = "還好沒有弄髒衣服。",
  str_voice_1601731_43 = "很抱歉，是我的失誤。",
  str_voice_1601731_44 = "我已經把吧台的杯子都擦拭一遍了，請放心使用吧。",
  str_voice_1601731_45 = "讓您費心了。",
  str_voice_1601731_46 = "竟然是......我會好好珍藏的。",
  str_voice_1601731_47 = "您還是一如既往地慷慨。",
  str_voice_1601731_48 = "我的喜好，已經被您看透了。",
  str_voice_1601731_49 = "我頭上的角當然不是天生就斷掉的，是被我的師父......算了，都過去了。您想來杯薄荷檸檬茶提提神嗎？",
  str_voice_1601731_50 = "注意自己的儀容非常重要，我曾經因為沒有將身上的血漬處理乾淨，嚇到了妮娜大小姐，她很長一段時間都不敢靠近我，讓我非常傷心。",
  str_voice_1601731_51 = "管家的工作很簡單，除了熨燙衣物、擦拭銀器、準備早中晚餐和接待客人之外，就只需要清除暗鬼、防範殺手、打探情報，以及必要的時候去威脅一下居心叵測之徒而已。",
  str_voice_1601731_52 = "白夜極光。",
  str_voice_1601731_53 = "有什麼事嗎？",
  str_voice_1601731_54 = "早茶已經準備好了。",
  str_voice_1601731_55 = "中午想吃什麼呢？",
  str_voice_1601731_56 = "已經到該休息的時間了。",
  str_voice_1601731_57 = "新年快樂，得要儘快為新年晚宴做準備了。",
  str_voice_1401691_1 = "歡迎大人光臨！大人，歡迎光臨！\n不不不，感覺還是歡迎光臨，大人，這樣更好些......\n嗯？我在認真練習接到委託時的說辭呢。",
  str_voice_1401691_2 = "嗯、哼、嘿、唷！我的目光穿過黑夜，這是只有塞提才能到達的境界！接下委託並不只靠著一張嘴，其他人會的塞提全都學不會！糟糕......唱錯了。",
  str_voice_1401691_3 = "俠盜就是最帥的職業。當城主很霸氣、當影主很威風、當女王很夢幻、當公主很累......你問我他們都是誰？我不曉得啊。反正俠盜就是最帥的。",
  str_voice_1401691_4 = "是距離俠盜的夢想更進一步了嗎？啊......這麼說來是你把我變強的啊？噢耶！塞提距離俠盜的夢想更進一步了。",
  str_voice_1401691_5 = "問我怎麼去總商會？直線距離很近的。直走，看到那面牆了嗎？翻過去。翻不過去？想要轉彎？不，不行。找幾個箱子墊在腳下就能翻過去了。",
  str_voice_1401691_6 = "被月光映照著的古舊都市里，俠盜早已不知所蹤......可街上卻漸漸傳出了獲救居民們的讚歎之聲。嗯，我也能做到嗎？啊，我們已經一起做到了嗎？",
  str_voice_1401691_7 = "你在盯著哪裡看？難道是我發尾的顏色掉色了嗎？糟糕，買的染髮劑果然品質太差了吧！唔，發尾還是黑色的，沒有掉色啊......那你盯著我看幹嘛？",
  str_voice_1401691_8 = "帥氣的大姐姐太多了。塞提要好好向她們學習才行。嗯，孤身出來闖蕩打拼的空裔也很帥氣。",
  str_voice_1401691_9 = "幫你鍛鍊肌肉、借你俠盜漫畫、糾正你的潮流認知......你想選哪個？什麼都不選也沒關係，反正塞提會保護你的。那個，如果能給交點保護費就更好了。",
  str_voice_1401691_10 = "我的一天很忙。早上先翹課看漫畫，下午再翹課去看看有沒有委託能接，晚上還要和超帥大姐姐一起特訓。所以，我也很佩服自己現在居然能這麼老實地站在這裡。",
  str_voice_1401691_11 = "站崗這種委託就算對我來說也是很簡單的工作。難道是要我站在這裡觀察你的意思嗎？好吧，就讓我來看看你和俠盜們的相似之處......",
  str_voice_1401691_12 = "我壓低了帽檐，意思是我在行動邊緣！你可要注意周圍情況，說不定下一秒我就會出現在你身旁。",
  str_voice_1401691_13 = "我之前只能在碼頭找到工作，只有那些工人不嫌棄我力氣太大。不過現在塞提已經可以很輕鬆地拿起那些又輕又小的盤子和咖啡杯了。",
  str_voice_1401691_14 = "塞提接不到委託？你聽誰在胡說？噓！這......這是暫時出錯！我也接到過很多次「幫忙銷毀過期物品」、「把三十箱啤酒一次搬到烈雀幫」這樣的委託！",
  str_voice_1401691_15 = "生日快樂，塞提·六六六為你送上祝福。",
  str_voice_1401691_16 = "好好好，問好結束了。快過來，然後小聲點，別被人發現我們在翹課。",
  str_voice_1401691_17 = "你早。我要像個大人一樣早起，然後像個大人一樣晚睡。",
  str_voice_1401691_18 = "記得吃飯，大姐姐說多吃蔬菜可以更好地控制自己的力氣。救命，討厭蔬菜。",
  str_voice_1401691_19 = "俠盜會指責你這樣的作息。俠盜派我來命令你早點休息。呃......好吧，我瞎編的。",
  str_voice_1401691_20 = "很好，俠盜通常會在這裡出沒。",
  str_voice_1401691_21 = "白夜城？還好吧，發行的俠盜漫畫數量太少了。",
  str_voice_1401691_22 = "俠盜的影子在注視著你！",
  str_voice_1401691_23 = "要是俠盜漫畫的數量和暗鬼一樣多就好了。當然，漫畫是好東西，暗鬼是壞東西。",
  str_voice_1401691_24 = "艾爾戈絲，教會了我很多道理的帥氣大姐姐。我很羡慕她。",
  str_voice_1401691_25 = "艾蕾雅，把球棒「酷酷」交給我，還陪我特訓的帥氣大姐姐。我也很羡慕她。",
  str_voice_1401691_26 = "俠盜漫畫、時尚、丁零當啷的飾品、大姐姐們。大姐姐不算東西？你說了可不算。",
  str_voice_1401691_27 = "被別人說笨笨的。雖然塞提覺得自己確實有一點。還有粉色、蔬菜和下雨天。",
  str_voice_1401691_28 = "如果能被用來當做俠盜的武器和代步工具的話，俠盜一定會變得更酷吧？",
  str_voice_1401691_29 = "本人就是未來的影鎮排名第一的俠盜——「塞提·六六六」！為什麼是未來的？咳，這個就以後慢慢說吧。",
  str_voice_1401691_30 = "力氣變得可以掌控了！",
  str_voice_1401691_31 = "酷酷，更靈活了！",
  str_voice_1401691_32 = "我變帥了吧？",
  str_voice_1401691_33 = "要成為俠盜了！！",
  str_voice_1401691_34 = "必須要合作？也行。",
  str_voice_1401691_35 = "酷酷迫不及待！",
  str_voice_1401691_36 = "現在？是現在嗎？",
  str_voice_1401691_37 = "塞提·六六六，出擊！",
  str_voice_1401691_38 = "六六六·塞提，激情燃燒！",
  str_voice_1401691_39 = "水平式——",
  str_voice_1401691_40 = "——揮棒！",
  str_voice_1401691_41 = "塞提會像她們一樣棒！",
  str_voice_1401691_42 = "能誇誇我嗎？",
  str_voice_1401691_43 = "這是，不愛讀書的代價......？",
  str_voice_1401691_44 = "會飛的大鳥載著塞提到處跑，導航員看起來像個小寶寶。",
  str_voice_1401691_45 = "謝了。",
  str_voice_1401691_46 = "哇！你居然......",
  str_voice_1401691_47 = "喜歡，真的！",
  str_voice_1401691_48 = "你......你想和我一起當俠盜？",
  str_voice_1401691_49 = "爸爸媽媽在白夜城工作，他們好像滿喜歡那裡。其實我也談不上喜不喜歡，因為我已經不怎麼記得小時候住在那裡的事了。",
  str_voice_1401691_50 = "想要成為俠盜的初心嗎......這就要從翹課那天，艾爾戈絲姐姐在街上對我的質問說起了。嗯，行為不端的人是無法成為俠盜的。",
  str_voice_1401691_51 = "學會控制力量，和自己的傢伙建立信任，這才是成為俠盜的第一步——這些東西都是艾蕾雅姐姐教會我的。她好帥。",
  str_voice_1401691_52 = "白夜極光。",
  str_voice_1401691_53 = "嗨。",
  str_voice_1401691_54 = "醒了嗎？我都溜出來了。",
  str_voice_1401691_55 = "中午不是俠盜行動的好時候。",
  str_voice_1401691_56 = "好想看漫畫，但是，又有點睏了......",
  str_voice_1401691_57 = "新年快樂，今年塞提成為俠盜的機率一定會大增吧？",
  str_voice_1600254_10 = "嗯？怎麼沒有聲音了？是被在下的演技所折服，而忘記歡呼鼓掌了嗎？",
  str_voice_1600254_11 = "想讓我演一齣專屬於你的戲劇嗎？那就把燈光都熄滅。不......還是要留下兩束光。一束朝向我，至於另一束，當然要朝向我的獨家觀眾。",
  str_voice_1600254_16 = "美德與罪惡，都是藝術的素材。你，更喜歡哪一種？",
  str_voice_1600254_17 = "服裝完美、妝容完美、狀態完美！燈光？晨曦就是最華美的燈光師！",
  str_voice_1600254_18 = "晚安，我的朋友。悄悄提醒一句，攝影機的鏡頭還在錄製。",
  str_voice_1600254_19 = "來吧！把自己浸泡在寂靜濃稠的夜裡，會得到一杯口感香醇的靈感。",
  str_voice_1600254_35 = "可以開拍了。",
  str_voice_1600254_36 = "焦點，在我身上！",
  str_voice_1600254_37 = "嘶吼吧，讓這演出更加生動！",
  str_voice_1600254_38 = "來吧，演出的高潮！",
  str_voice_1600254_39 = "演技，收放自如。",
  str_voice_1600254_40 = "這才是你的劇本！",
  str_voice_1600254_44 = "嗯？你一定是想要我的簽名海報吧？",
  str_voice_1600254_58 = "只有當我以演員的身分出席隆重場合時，才會穿上這身私人定制的華貴禮服。當然也有例外，比如現在。",
  str_voice_1600254_59 = "今天要重溫我的哪一部作品呢？選擇是一件難事，那麼——所有的螢幕，一起閃爍吧！",
  str_voice_1600254_60 = "多麼充滿戲劇張力的身世......PlayerName，有朝一日把你的故事編成戲劇吧！我會乘著彼岸號在全世界巡演！",
  str_voice_1600254_61 = "「被人議論並不可怕，可怕的是沒有人議論。」哦......但，藝術家的食糧，是遠離人群的孤獨。",
  str_voice_1600254_62 = "任何平庸的劇本都能被偉大的藝術家演繹出別樣的精彩。不相信嗎？沒關係，我可以親自為你展示。",
  str_voice_1600254_63 = "PlayerName，我最心靈相通的觀眾，來得正好！和我一起重溫冥河列車·天才表演藝術家·卡戎的影視作品吧。",
  str_voice_1600254_64 = "早安，我的朋友，我心靈相通的觀眾！",
  str_voice_1600254_65 = "清晨的回籠覺，總會帶來最離奇的夢境。",
  str_voice_1600254_66 = "工作日的早晨，也一樣華麗！",
  str_voice_1600254_67 = "第一幕！",
  str_voice_1600254_68 = "晚安，我的朋友。",
  str_voice_1600254_69 = "喜歡在晚上重溫我的作品。",
  str_voice_1600254_70 = "靈感，為何還不肯降臨......",
  str_voice_1600254_71 = "「晚安，親愛的少年。」",
  str_voice_1600254_72 = "哦！別對我說晚安，吼——！",
  str_voice_1600254_73 = "最上鏡的角度，是三百六十度。",
  str_voice_1600254_74 = "完美的我，和差一點就完美的你。",
  str_voice_1600254_75 = "也許太有魅力，也是一種殺傷力。",
  str_voice_1600254_76 = "如果可以，我不想在你的人生中謝幕。",
  str_voice_1600254_77 = "天才的世界，不需要庸才瞭解。",
  str_voice_1601751_1 = "PlayerName正在盯著阿克希亞。不痛的，義體和繃帶並不是戰鬥帶來的損傷，它們只是一個「戰鬥機器」應有的裝備而已。",
  str_voice_1601751_2 = "跳跳糖在舌尖跳動的感覺很刺激，阿克希亞推測，這種感覺就是PlayerName所說的情感。",
  str_voice_1601751_3 = "阿克希亞唯一無法對抗的東西，就是強大的睡意……「盡情戰鬥、盡興休息」，這是鶯歌說的……呼……",
  str_voice_1601751_4 = "阿克希亞的腿關節雖然會嘎吱嘎吱地響，但它在融合了阿克希亞的光能術之後，就能像彈簧一樣咻地邁出去很遠。",
  str_voice_1601751_5 = "三次方對阿克希亞來說，就像螢盞對PlayerName來說一樣重要。PlayerName，理解了嗎？",
  str_voice_1601751_6 = "背後有發條的是「01」，長著翅膀的是「10」，頭上有光圈的是「11」，三次方其實很容易辨認。",
  str_voice_1601751_7 = "阿克希亞瞭解訓練的殘酷，淘汰與死亡是戰敗時的必然結果，但在阿克希亞參與的戰鬥裡，這種事情一般不會發生。",
  str_voice_1601751_8 = "你好，PlayerName……看來PlayerName沒聽到。那麼，即使這樣也，聽——不——到——嗎——",
  str_voice_1601751_9 = "PlayerName，請幫阿克希亞低頭看一下，阿克希亞的繃帶和腿關節，彼此纏在一起了……",
  str_voice_1601751_10 = "呼……呼……阿克希亞明白，現在的任務是補充體能。",
  str_voice_1601751_11 = "請享受手上的工作吧，PlayerName，把特訓和執勤這種緊張的任務全交給阿克希亞就好。",
  str_voice_1601751_12 = "監測到PlayerName此時空閒。請和阿克希亞一起進入模擬器訓練，然後和阿克希亞一起在戰鬥中活下來。",
  str_voice_1601751_13 = "PlayerName說，想要教給三次方一些音樂。但阿克希亞認為，啟光內部沒有合適的設備……原來如此，是用巨像的鋼琴教學，明白了。",
  str_voice_1601751_14 = "阿克希亞很容易疲憊，但只要讓阿克希亞進入短時間睡眠流程，即可恢復。請再給阿克希亞一些時間。",
  str_voice_1601751_15 = "生日快樂，PlayerName。",
  str_voice_1601751_16 = "真好，PlayerName還健康地活著……這樣說嚇到你了？",
  str_voice_1601751_17 = "空氣聞起來像下過雨，螢盞飛過了七隻……阿克希亞的意思是，早安。",
  str_voice_1601751_18 = "阿克希亞的皮膚很特別，天色暗下來後，全身就會一直微微發亮。",
  str_voice_1601751_19 = "睡不著？請試試阿克希亞的休眠艙……結論是，裝不下。",
  str_voice_1601751_20 = "阿克希亞是整個啟光的孩子，阿克希亞為啟光獻身是天經地義的。",
  str_voice_1601751_21 = "浮在空中的城市？跟西恩在終端裡說得不太相符，請帶阿克希亞確認。",
  str_voice_1601751_22 = "為了啟明之光。",
  str_voice_1601751_23 = "與暗鬼戰鬥是一件只有過程的事情，因為結果永遠是相同的。",
  str_voice_1601751_24 = "鶯歌的性格像父親的翻版。但阿克希亞知道，鶯歌是情感豐富的人。",
  str_voice_1601751_25 = "西恩和阿克希亞不同，或許戰區的職位更能讓西恩發揮實力。",
  str_voice_1601751_26 = "請將更多的跳跳糖作為阿克希亞的勝利獎勵。",
  str_voice_1601751_27 = "抱歉，下雨的時候，阿克希亞難以提起精神，阿克希亞的雙腿很重。",
  str_voice_1601751_28 = "原來PlayerName曾在這裡睡了十七年。明白了，這也是個巨大休眠艙。",
  str_voice_1601751_29 = "「戰鬥機器」阿克希亞報到，如果戰鬥已經是不得已的選擇，請讓阿克希亞成為最有力的武器。",
  str_voice_1601751_30 = "完全理解了。",
  str_voice_1601751_31 = "簡單的訓練。",
  str_voice_1601751_32 = "練習強度提升。",
  str_voice_1601751_33 = "請用實戰檢驗我。",
  str_voice_1601751_34 = "收到指令。",
  str_voice_1601751_35 = "阿克希亞，就緒。",
  str_voice_1601751_36 = "三、二、一……",
  str_voice_1601751_37 = "久等了。",
  str_voice_1601751_38 = "交給阿克希亞吧。",
  str_voice_1601751_39 = "要保護大家。",
  str_voice_1601751_40 = "還沒有結束。",
  str_voice_1601751_41 = "就像每次訓練那樣。",
  str_voice_1601751_42 = "勝利是唯一的結果。",
  str_voice_1601751_43 = "咳，從未有過的經驗……",
  str_voice_1601751_44 = "開始巡視任務。已確認，附近沒有危險。",
  str_voice_1601751_45 = "請放在旁邊吧。",
  str_voice_1601751_46 = "這是拉近關係的方式？",
  str_voice_1601751_47 = "三次方，收起來。",
  str_voice_1601751_48 = "阿克希亞會認真保管。",
  str_voice_1601751_49 = "是「啟明星計畫」帶著阿克希亞認識了這個世界。至於阿克希亞「真實的父母」……抱歉，阿克希亞偵測不到這樣的記憶。",
  str_voice_1601751_50 = "阿克希亞在皮膚崩裂時，曾經真實地感受了死亡。阿克希亞認為，賦予阿克希亞生命的人，就是父母，不管這是第幾次的生命。",
  str_voice_1601751_51 = "三次方是阿爾戈爾送給阿克希亞的朋友。阿克希亞需要三次方來輔助生活，也可以配合三次方來進行作戰。",
  str_voice_1601751_52 = "白夜極光。",
  str_voice_1601751_53 = "哈欠~",
  str_voice_1601751_54 = "早安。",
  str_voice_1601751_55 = "午安。",
  str_voice_1601751_56 = "安心睡吧。",
  str_voice_1601751_57 = "哈欠……新年快樂。",
  str_voice_1501761_1 = "如果能像約翰先生那樣組建一支醫療隊、前往艾斯特拉各地巡迴診療就好了。這世界上還有許多人需要醫療援助。",
  str_voice_1501761_2 = "每次幫拉斐爾大人梳頭髮都要花好長時間……幹嘛用那種眼神看著我？我可沒有覺得厭煩！",
  str_voice_1501761_3 = "不論治癒的希望有多渺茫，我都不會放棄任何一個病人，就像當初那些醫生沒有放棄我一樣。",
  str_voice_1501761_4 = "我想幫助每位患者擺脫病痛的困擾，但是想要實現這個目標，就需要不斷努力。",
  str_voice_1501761_5 = "體力與光能術的鍛鍊很重要，精神方面的鍛鍊也不能放鬆。",
  str_voice_1501761_6 = "我努力至今，就是為了等待一個展現實力的機會。謝謝你這麼信任我，我一定不會辜負你的期待！",
  str_voice_1501761_7 = "既然成為了朋友，那我也會負起責任，讓你健健康康的。要是哪裡不舒服，就告訴我吧。",
  str_voice_1501761_8 = "勞逸結合嗎……？雖然我總是這樣提醒別人，但真正想要做到的時候卻很難呢。感謝你的提醒，我會注意休息的。",
  str_voice_1501761_9 = "我按照你的建議進行了充分的休息，工作效率確實得到了提升，這樣做果然比一味地熬夜學習效果更好。謝謝你的建議！",
  str_voice_1501761_10 = "你要去休息？好吧，那我去看一下醫學書。我的時間非常寶貴，每分每秒都不能浪費。",
  str_voice_1501761_11 = "這裡有人需要救治嗎？什麼？只是站在這裡就可以了？嗯……這樣做能夠提升我的醫術嗎？",
  str_voice_1501761_12 = "一定要記得按時體檢。如果能夠儘早發現問題，許多疾病其實是非常容易治好的。",
  str_voice_1501761_13 = "拉斐爾大人為什麼會認為聖水導彈能夠修復破損的螢盞呢……抱歉，我馬上就去把它們擦乾淨。",
  str_voice_1501761_14 = "下一次戰鬥一定會比這一次更順利，因為我在不斷進步！",
  str_voice_1501761_15 = "生日快樂！請收下這個醫療箱。有了它，以後就能及時處理傷口了！",
  str_voice_1501761_16 = "記得隨時注意自己的身體情況，千萬不要鬆懈。",
  str_voice_1501761_17 = "早。如果要外出執行任務或者完成委託，就帶上我吧。我一定能幫上忙。",
  str_voice_1501761_18 = "晚上好，你今天也忙了一整天吧？我也是，一直都在鑽研醫術。",
  str_voice_1501761_19 = "已經很晚了，早點休息吧。我？我不累，還能再多練習一下光能術。",
  str_voice_1501761_20 = "白夜城是我的家鄉，也是教我知識、讓我能夠朝著夢想不斷努力的地方。",
  str_voice_1501761_21 = "影鎮那些傢伙真是麻煩，每次去那裡都能看到因為打架受傷的人。",
  str_voice_1501761_22 = "白夜至上！",
  str_voice_1501761_23 = "對付暗鬼，最好的治療手段就是拳頭。",
  str_voice_1501761_24 = "拉斐爾大人雖然有時冒冒失失的，但她確實是一位優秀的醫生！",
  str_voice_1501761_25 = "卡蓮大人那麼強大，一定經歷了我想像不到的辛苦、付出了無數努力吧？",
  str_voice_1501761_26 = "養花養鳥、打掃房間……這些都是拉斐爾大人建議我培養的愛好。",
  str_voice_1501761_27 = "我討厭一成不變的生活，它會消磨人們的上進心，讓人失去進步的動力。",
  str_voice_1501761_28 = "巨像看起來像是有生命一樣……在它受傷或生病的時候，又該如何治療呢？",
  str_voice_1501761_29 = "戰鬥醫師貝爾塔，奉命前來支援。你就是這艘巨像的管理者吧？有人受傷嗎？我會立刻展開救治。",
  str_voice_1501761_30 = "有所進步真是太好了！",
  str_voice_1501761_31 = "好，更有幹勁了！",
  str_voice_1501761_32 = "任務什麼的，儘管交給我吧！",
  str_voice_1501761_33 = "這份信任，我一定會回應的。",
  str_voice_1501761_34 = "我會努力的！",
  str_voice_1501761_35 = "準備完畢！",
  str_voice_1501761_36 = "隨時可以開始治療！",
  str_voice_1501761_37 = "閃耀吧，北銀河之羽！",
  str_voice_1501761_38 = "努力至今，就是為了這一刻！",
  str_voice_1501761_39 = "別動，就一針！",
  str_voice_1501761_40 = "這是必要的治療！",
  str_voice_1501761_41 = "好，交給我吧！",
  str_voice_1501761_42 = "取得勝利！真是太好了！",
  str_voice_1501761_43 = "我不畏懼失敗，只是覺得……不甘心。",
  str_voice_1501761_44 = "希望我的醫術和戰鬥力能得到進步，每一天、每一秒都是如此！",
  str_voice_1501761_45 = "這些能用來提升醫術嗎……？",
  str_voice_1501761_46 = "謝謝你，我很喜歡這個！",
  str_voice_1501761_47 = "我會好好使用它們的！",
  str_voice_1501761_48 = "導航員真瞭解我的喜好啊，謝謝！",
  str_voice_1501761_49 = "所謂的戰鬥醫師，就是要一邊防備戰鬥中的各種危險情況，一邊為他人提供支援。為了能夠勝任這項工作，我必須不斷努力。",
  str_voice_1501761_50 = "我曾經身患重病，但被約翰先生帶領的醫療隊拯救，所以我額頭上的十字形傷痕不僅是手術留下的痕跡，也是那些醫生們的勳章。",
  str_voice_1501761_51 = "雖然常常要幫忙善後，但我是自願選擇照顧拉斐爾大人的。她是一位非常有天賦的醫生，跟在她身邊，我能學到許多事。",
  str_voice_1501761_52 = "白夜極光。",
  str_voice_1501761_53 = "你好啊。",
  str_voice_1501761_54 = "新的一天從早起晨練開始。",
  str_voice_1501761_55 = "午安。好好吃午飯了嗎？",
  str_voice_1501761_56 = "還沒休息嗎？",
  str_voice_1501761_57 = "新年快樂！為了慶祝新年，我申請了半天的休假。你問為什麼是半天？因為另外半天要加倍努力，把休息佔用的訓練時間都補回來。",
  str_voice_1601771_1 = "啊~你在盯著我看嗎？哈哈，那就讓我來好好為你展示一番什麼叫做真正的偶像風采吧——咳！稍等，讓我先喝一下用來保護嗓子的藥劑哦。",
  str_voice_1601771_2 = "猜猜我每天打扮成這樣需要多久？……半個小時？才不止呢！半個小時只是我用來做髮型的時間而已！",
  str_voice_1601771_3 = "我們的眼光果然很相似呢~我也覺得我的專屬麥克風很獨特！你要試試嗎？啊，但是它是純金的，PlayerName拿得動嗎？",
  str_voice_1601771_4 = "啊~啊~啊！哦哦！怎麼回事？感覺自己在PlayerName的幫助下，音域都變寬了呢！",
  str_voice_1601771_5 = "腳步變得更加輕盈，與舞曲融為一體。所有感覺都是那麼美妙和諧~PlayerName，要和我一起跳一支舞嗎？",
  str_voice_1601771_6 = "這種感覺——嗯！謝謝你，PlayerName！我覺得「夜間的工作」會更加順利了！",
  str_voice_1601771_7 = "跟你講哦！被人用槍指著的時候，只要心裡默默地數數，並且跳過所有的7，子彈就永遠不會擊中你！是真的！",
  str_voice_1601771_8 = "鞋子後跟有蝴蝶結，胸口裝飾有蝴蝶結，裙邊設計也有蝴蝶結……我、我確實很喜歡蝴蝶結！PlayerName呢，你也喜歡嗎？",
  str_voice_1601771_9 = "如果你願意的話……哦不！那個，我的意思是！如果你有空的話，可以看一看我頭頂頭髮的形狀——是愛心哦！",
  str_voice_1601771_10 = "原來如此，「冷清」是這種感覺啊。我可是很少會出現在這種地方的哦？不過，認真感受一下寂靜也還挺有意思的嘛~",
  str_voice_1601771_11 = "就算讓我一個人站在這裡……就算讓我一個人站在這裡，我也要大聲地說——我喜歡這個世界！我喜歡大家！我……我喜歡能為所有人帶來開心和快樂的我自己！",
  str_voice_1601771_12 = "你也注意到我的子彈頭髮飾了嗎？雖然造型有點特殊，但是它可幫了我不少忙呢。每次我把它拋出去的時候，它都會正向落地~說明我們也要正面地面對生活呀。",
  str_voice_1601771_13 = "在舞台上的感覺是很美妙的，因為台下有那麼多人都在注視著我！他們會給我勇氣和力量，就像……就好像我最愛的那個小傢伙一樣！",
  str_voice_1601771_14 = "棉花糖~棉花糖！咦？我不是想吃棉花糖啦。棉花糖是我身邊這隻小白狗的名字哦！嘿嘿，它簡直和我小時候很喜歡的那隻廣告狗狗長得一模一樣~",
  str_voice_1601771_15 = "生日快樂！但我更希望你每天都快樂！",
  str_voice_1601771_16 = "嗨嗨！今晚你會來看我的演出嗎？嗯~確實是在專門邀請你呀。",
  str_voice_1601771_17 = "早上好！我已經開始練聲啦~我希望能用美妙的聲音為大家帶去幸福~",
  str_voice_1601771_18 = "現在，有點累了……可是大家一直在喊「安可」！所以，我還可以繼續！",
  str_voice_1601771_19 = "悄悄告訴你。我之所以要堅持夜間出門，是因為我……想要成為孩子們的英雄！",
  str_voice_1601771_20 = "因為我的活動範圍基本都在影鎮，所以啊~我偶爾也會想去其它地方，讓更多的人在現場聽到我的歌聲呢。",
  str_voice_1601771_21 = "白夜城？那些「音樂人」和「偶像」是完全不同的兩個概念啦！完全！",
  str_voice_1601771_22 = "閃耀的歌聲和色彩在注視著你~",
  str_voice_1601771_23 = "不懂得欣賞美好、只會破壞的傢伙們會被我一網打盡。",
  str_voice_1601771_24 = "珀蘭蒂是個很敬業、也很有職業操守的女孩子呢！",
  str_voice_1601771_25 = "涉女士真的很聰明！總覺得能從她的思維模式中學到很多不一樣的東西。",
  str_voice_1601771_26 = "嗯？你問我我身上的徽章？嘿嘿，它們其實代表著我獲得過的獎項哦。",
  str_voice_1601771_27 = "吃了整整一週苦瓜，站在體重秤上一看……啊！還是那個數字呀！",
  str_voice_1601771_28 = "嗯嗯，我知道啦。臨空者號，它就是你的棉花糖狗狗，對吧？",
  str_voice_1601771_29 = "嘿！我是歌爾蒂，你就是PlayerName對嗎？很高興在這個閃閃發光、華麗又溫柔的世界上和你相遇！",
  str_voice_1601771_30 = "哇！好神奇！",
  str_voice_1601771_31 = "感覺要飛起來啦~",
  str_voice_1601771_32 = "啦~啦~啦~！",
  str_voice_1601771_33 = "變得更加耀眼了！",
  str_voice_1601771_34 = "明白你的意思！",
  str_voice_1601771_35 = "準備完畢！",
  str_voice_1601771_36 = "現在就可以！",
  str_voice_1601771_37 = "我的聲音充滿能量！",
  str_voice_1601771_38 = "最高音域！",
  str_voice_1601771_39 = "綻放吧！",
  str_voice_1601771_40 = "閃耀吧！",
  str_voice_1601771_41 = "動作要有張力哦！",
  str_voice_1601771_42 = "我很開心！",
  str_voice_1601771_43 = "不……不會氣餒！",
  str_voice_1601771_44 = "無論在哪裡，我都可以創造夢想哦！",
  str_voice_1601771_45 = "怎麼辦……我好高興！",
  str_voice_1601771_46 = "我會用更好的舞台來回報你！",
  str_voice_1601771_47 = "感激的心情，快要溢出來了……",
  str_voice_1601771_48 = "你的禮物，我會一生珍藏！",
  str_voice_1601771_49 = "我出生在一個非常普通的家庭哦！小時候我以為我在電視上看到的明星都在另一個世界呢。還有廣告裡的那隻棉花糖狗狗。",
  str_voice_1601771_50 = "我被劫匪當做人質的那一天？也許不能被稱為「不幸」。雖然我在那之後患上了幽閉恐懼症，但同時我也獲得了奇妙的能力呀。",
  str_voice_1601771_51 = "嘿嘿嘿！你很喜歡舞台上的我嗎？多謝你啦。除了「這個」自己，我也很喜歡舞台結束之後的「那個」自己呢。",
  str_voice_1601771_52 = "白夜極光～",
  str_voice_1601771_53 = "嗨嗨！",
  str_voice_1601771_54 = "早上好！你在做什麼？",
  str_voice_1601771_55 = "中午了，記得要補充水分哦~",
  str_voice_1601771_56 = "為了保護喉嚨，我們應該早點休息。",
  str_voice_1601771_57 = "新年快樂！新的一年裡可以學到更多舞步的，對吧？",
  str_voice_1601781_1 = "哈欠——菲雅呢？我可愛的小徒弟呢？快來幫你尊敬的師父捏一下肩膀，趴著睡覺果然對肩頸不太好……啊痛痛痛。",
  str_voice_1601781_2 = "不好意思啊PlayerName，神奇動物也是會經常掉毛的，你應該不會過敏吧？至於清潔的任務就叫菲雅來做吧……你來？那多不好意思，那就先從那盆沙子裡鏟出排泄物開始吧～",
  str_voice_1601781_3 = "打聽年齡這種事啊，不論對男人還是女人來講都是很不禮貌的，你只要記住我是永遠的十八歲就好。或者可以問問我其他問題，比如什麼神奇動物分泌的黏液護膚效果最好？",
  str_voice_1601781_4 = "這是我特地根據神奇動物的習性，專門用泥尊鷹脫落的羽毛製成的玩具，小毛球牠們可喜歡了，菲雅這個逆徒怎麼能污蔑我為了省錢而摳門呢？",
  str_voice_1601781_5 = "我可以理解每個人對神奇動物會抱有不同的看法和態度，但還是希望我寫的書能讓更多人理解、喜愛上這些神奇的小生靈。",
  str_voice_1601781_6 = "我的旅程還沒結束，這個世界上一定還存在著我從未見過的神奇動物，我想親眼看看牠們。",
  str_voice_1601781_7 = "我看你對神奇動物也很有興趣，怎麼樣，要不要拜我為師？這樣我就又多了一個打雜……寶貝徒弟了呢。",
  str_voice_1601781_8 = "如果你也喜歡神奇動物，下次要不要和我一起遊歷阿斯特拉？我會在書籍助手那一欄裡寫上你的名字……當然我絕對不是為了免費的勞動力和代步工具。",
  str_voice_1601781_9 = "曾經有一位你們族裔的少女，她幫助我學會了如何和神奇動物溝通，有時候你會讓我想起她……哎呀，或許她是你的親戚也說不定~",
  str_voice_1601781_10 = "睏了嗎？來來，跟我一起躺在小毛球身上吧，牠不會介意的。",
  str_voice_1601781_11 = "就是坐在這裡看著就行了吧？那我順便給小動物們梳一遍毛。",
  str_voice_1601781_12 = "哈嚏！哎呀，最近總是打噴嚏呢，不知道又是哪家的小姐在思念我呢？",
  str_voice_1601781_13 = "憑我這張臉，如果再會唱歌跳舞拍戲的話，豈不是搶了所有偶像藝人的飯碗？他們都應該感謝我選擇了隱居。",
  str_voice_1601781_14 = "骨氣？哎呀，那是你們年輕人講究的東西，對我這種老胳膊老腿而言，認清現實才是生存之道。",
  str_voice_1601781_15 = "不喜歡我替你準備的禮物嗎？這可是佩可兔脫落的乳牙，很珍貴的！",
  str_voice_1601781_16 = "是你呀，你看到我的手稿了嗎？不會又被哪隻小傢伙吃掉了吧……",
  str_voice_1601781_17 = "醒這麼早？年輕人精力真好。",
  str_voice_1601781_18 = "好餓……看到菲雅了嗎？我的小徒弟怎麼還不幫我送餐過來？",
  str_voice_1601781_19 = "走嗎？帶你去看看那些晝伏夜出的神奇動物。",
  str_voice_1601781_20 = "神奇動物專家專家都是些古怪的傢伙，不過大家愛動物的心是一樣的。",
  str_voice_1601781_21 = "聰明的領導者，會意識到環境和生態對發展的重要性 。",
  str_voice_1601781_22 = "尋找神奇動物，研究牠們的祕密，這是我身上肩負的使命。",
  str_voice_1601781_23 = "暗鬼無聊又醜陋，我對它們沒興趣。",
  str_voice_1601781_24 = "被自己心愛的小徒弟誤解，天天被喊騙子，真是令人難過呢，嗚嗚~",
  str_voice_1601781_25 = "詩燁啊……她是個堅強的孩子，神奇動物的保護大業就全靠她了！",
  str_voice_1601781_26 = "酒是文學和藝術靈感的來源，小酌兩杯有助於創作！",
  str_voice_1601781_27 = "啊啊啊！是誰動了我的書？順序全都亂了！",
  str_voice_1601781_28 = "可以借我一間溫室嗎？有些神奇動物需要生活在更溫暖的環境。",
  str_voice_1601781_29 = "瞭解神奇動物，也是瞭解這個世界的一種方式。想要一起看看嗎——那些你從未見過的生靈帶來的奇妙光景？",
  str_voice_1601781_30 = "小動物們更喜歡你了呢。",
  str_voice_1601781_31 = "麻煩的事情可別找我！",
  str_voice_1601781_32 = "人情債難還啊。",
  str_voice_1601781_33 = "心意相通才能發揮實力。",
  str_voice_1601781_34 = "我可幫不上什麼忙。",
  str_voice_1601781_35 = "該你們上場了。",
  str_voice_1601781_36 = "小毛球救我！",
  str_voice_1601781_37 = "小毛球，使出「爪擊」。",
  str_voice_1601781_38 = "哈欠——交給你們了。",
  str_voice_1601781_39 = "好累啊。",
  str_voice_1601781_40 = "還沒結束嗎？",
  str_voice_1601781_41 = "饒了我吧。",
  str_voice_1601781_42 = "實力不減當年~",
  str_voice_1601781_43 = "投降，我投降。",
  str_voice_1601781_44 = "需要泥尊鷹的美夢入睡服務嗎？長期失眠可以辦個套餐。",
  str_voice_1601781_45 = "下次來我家做客～",
  str_voice_1601781_46 = "哎呀，真是個不錯的年輕人。",
  str_voice_1601781_47 = "那我就收下了～",
  str_voice_1601781_48 = "嗚嗚，感動得我老淚縱橫。",
  str_voice_1601781_49 = "我確實從很小的時候就喜歡神奇動物，但以前也因為家裡的生意，做過傷害牠們的事情……我現在只剩下一邊的翅膀，和身上的那道疤痕，都是應該承受的代價。",
  str_voice_1601781_50 = "神奇動物很單純，沒有光靈那麼多的心思。當年我只是救了小毛球一命，牠從此就跟著我走遍了阿斯特拉大陸南北，一路護我周全。哪像我那兩個逆徒，天天辱駡我還欺負我，嗚嗚～",
  str_voice_1601781_51 = "不是我信不過你，是我自己都不太清楚關於我血脈的事情。我只在古籍中翻到了有關「銜尾龍」的事，但具體和我有什麼關係，我也還在調查。如果你真對我那麼感興趣，要不要陪我一起找線索？",
  str_voice_1601781_52 = "白夜極光。",
  str_voice_1601781_53 = "喂～",
  str_voice_1601781_54 = "起得很早呢。",
  str_voice_1601781_55 = "要一起睡午覺嗎？",
  str_voice_1601781_56 = "保持年輕的祕訣是早睡。",
  str_voice_1601781_57 = "新年快樂，我給你和我的兩個寶貝徒弟織了手套，用的是小毛球的毛。",
  str_voice_1601781_58 = "菲雅，為師先去前方等你～",
  str_voice_1601781_59 = "不愧是我，教得真好呢。",
  str_voice_1501801_1 = "情報收集是很重要的工作。戴禮帽的麻雀「阿白」負責白夜城，灰鴿子「阿灰」負責下城區，老鼠「阿黑」負責影鎮。",
  str_voice_1501801_2 = "我身邊的裝備們看起來很重？啊，謝謝，我自己拿就可以了。要是想成為一名獨當一面的記者的話，它們可都是必不可少的好夥計。",
  str_voice_1501801_3 = "我知道你剛剛說了些什麼。你不喜歡這裡，是吧？你有很多還沒實現的想法，對嗎？哦？你在否認？真的？我不信。",
  str_voice_1501801_4 = "哇，仿佛登山包都變輕了！行動一定會更便捷的。多謝你，PlayerName。",
  str_voice_1501801_5 = "阿白找到了人物動機，阿灰找到了作案工具，阿黑找到了目擊證人……嗯！珀蘭蒂已經知道兇手是誰了！獨家報導馬上就出爐！",
  str_voice_1501801_6 = "很好，寫作的速度變得飛快！我要馬上把這件事告訴編輯老師。嘿嘿，感覺很快就能轉正了呢！",
  str_voice_1501801_7 = "我還是第一次聽到別人對我說這種話。你、你該不會是在賄賂我吧？就算是這樣我也不會停止報導那些發生在你身上的真實新聞的！",
  str_voice_1501801_8 = "我想為你寫一篇獨家報導。呃，咳。沒錯，這是編輯老師的要求，我也是剛剛才知道這個需求。",
  str_voice_1501801_9 = "你……那個，其實我……呼，深呼吸。其實我只是想問，我們這樣真的沒關係嗎？記者和受訪對象？",
  str_voice_1501801_10 = "我會把你在我面前所做的事一一記錄下來。害怕了嗎？噗哈哈……不，不。我沒有笑。",
  str_voice_1501801_11 = "好耶，這是難得的機會！沒有其他人打擾，編輯老師也不會來催稿……剛好可以利用現在的時間完成上一週的工作！",
  str_voice_1501801_12 = "一流的記者，哪怕身後發生爆炸，也不會動搖分毫。",
  str_voice_1501801_13 = "你對我的登山包很好奇？那裡面裝著的都是各種各樣的寶貴線索和素材，是記者引以為傲的珍寶。什麼？你只是對外型感到好奇？",
  str_voice_1501801_14 = "聽著，當你追蹤新聞線索快要暴露身分時，只需要像我一樣做就可以隱藏自己的身分。壓低帽檐、戴上墨鏡、扣好風衣……",
  str_voice_1501801_15 = "生日快樂！你今天一定很開心吧？都收到了來自誰的什麼禮物？",
  str_voice_1501801_16 = "採訪對象到底有沒有說真話？交叉驗證的流程我做對了嗎？啊！嗨，我正在認真工作呢。",
  str_voice_1501801_17 = "清晨，小鳥在吃街頭的麵包渣。牠們為什麼會選擇這條路線？引人深思。",
  str_voice_1501801_18 = "晚上好。我正在為了明天的拍攝做準備。膠捲、鏡頭蓋、閃光燈檢查……",
  str_voice_1501801_19 = "我想你並沒有「無法通過試用期」這種困擾對吧？那你就應該早點休息才對。",
  str_voice_1501801_20 = "無論是社會議題還是民生議題，影鎮總是可以滿足你的胃口。",
  str_voice_1501801_21 = "白夜城……我不知道在這那裡有沒有記者這種職業。",
  str_voice_1501801_22 = "阿白阿灰阿黑在注視著你！",
  str_voice_1501801_23 = "從它們身上我看不到任何新聞價值。",
  str_voice_1501801_24 = "維克，他真的是我很想採訪的一個人物……嗯，總有一天會採訪到的！",
  str_voice_1501801_25 = "莉莉卡和我一樣！我們都在努力地追求夢想。",
  str_voice_1501801_26 = "聽說薇絲和卡蓮做同學的時候擅長的方向不太一樣，這是真的嗎？呃，好吧，我不問了。",
  str_voice_1501801_27 = "真不知道那些大人們說的話有什麼意義……不僅不切實際，他們甚至還會哄騙青少年！",
  str_voice_1501801_28 = "臨空者號只能和你溝通嗎？哦！能不能幫我個忙——沒錯，就是把他受訪的發言翻譯給我。你怎麼知道？",
  str_voice_1501801_29 = "我是來自「十字街祕聞快訊」的實習記者珀蘭蒂。你就是PlayerName？很好，終於見到你了——阿斯特拉的素材寶庫！",
  str_voice_1501801_30 = "寫得好快！",
  str_voice_1501801_31 = "頭腦變得清晰了！",
  str_voice_1501801_32 = "一切都瞭若指掌！",
  str_voice_1501801_33 = "我、我轉正了嗎？",
  str_voice_1501801_34 = "統統記錄下來。",
  str_voice_1501801_35 = "靈感裝載完成！",
  str_voice_1501801_36 = "要施放了嗎？",
  str_voice_1501801_37 = "戰鬥的感覺！",
  str_voice_1501801_38 = "真實自有萬鈞之力！",
  str_voice_1501801_39 = "鏡頭準備！",
  str_voice_1501801_40 = "開拍！",
  str_voice_1501801_41 = "一定沒問題。",
  str_voice_1501801_42 = "哈哈，我就說嘛！",
  str_voice_1501801_43 = "抱歉……",
  str_voice_1501801_44 = "哈！讓我來看看這裡有什麼採訪素材……",
  str_voice_1501801_45 = "謝謝，我很喜歡！",
  str_voice_1501801_46 = "哇！我會把它放到我的登山包裡！",
  str_voice_1501801_47 = "等等，我有點害羞……",
  str_voice_1501801_48 = "嗚嗚……PlayerName……",
  str_voice_1501801_49 = "我和報刊的第一次接觸要從小時候說起了。雖然我那時候只對一些八卦題材感興趣，但我卻從那些題材的新聞中學會了讀書寫字。",
  str_voice_1501801_50 = "戰亂的日子讓我明白原來生活中不僅只有八卦新聞。甚至我開始不明白什麼叫做新聞……每一天都在重複發生的悲劇，還能夠被稱之為「新聞」嗎？",
  str_voice_1501801_51 = "爸爸媽媽希望我學會一門手藝，可我覺得採訪和寫作將會變成我一生為之追求的技藝。嗯……要是現在的工作能轉正的話就更好了。",
  str_voice_1501801_52 = "白夜極光！",
  str_voice_1501801_53 = "你好，我是珀蘭蒂。",
  str_voice_1501801_54 = "早，我已經到辦公桌前了。",
  str_voice_1501801_55 = "午安，抓緊時間吃飯！",
  str_voice_1501801_56 = "啊啊，今天的稿子還沒寫完。",
  str_voice_1501801_57 = "新年快樂，PlayerName。雖然去年發生了很多不好的新聞，但只要我真實地把它們記錄下來並且有人在關注的話……那麼我就願意去相信明年能夠變得更好。",
  str_voice_1600773_1 = "發現了嗎，音樂流淌之處，即使是再稀鬆平常的光景，也會開始變得如同暖陽下的鑽石一般熠熠生輝。",
  str_voice_1600773_2 = "怎樣才算是一首好歌？旋律動聽，抑或是歌詞華麗？空裔啊，我想「用心」才是這個問題的關鍵。",
  str_voice_1600773_3 = "每個人的人生，都像是一首獨一無二的歌。嗯？你問我……我的人生是一首什麼樣的歌？也許你可以告訴我這個答案。",
  str_voice_1600773_10 = "不要把時間浪費在發呆上。來，坐在這架鋼琴面前，讓我們用音樂進行一場關於未來的對談。",
  str_voice_1600773_11 = "女歌手的一天會是怎樣的？換上這身裝扮，也許就會有所了解。嗯？你把這叫作……角色扮演？就算這樣，你也是我的粉絲吧？",
  str_voice_1600773_12 = "吉他斷了弦、鋼琴走了音、鼓皮破了洞……就算這種事情真的發生，也請相信，動人心弦的音樂永不消亡。",
  str_voice_1600773_13 = "只有你彈奏的音樂，可以喚醒那沉睡的巨像。不……不只是巨像……嗯，現在說，還為時過早嗎？",
  str_voice_1600773_14 = "我唱的歌會讓你覺得憂傷？都說歌曲會傳遞一個人的情緒，原來是真的……噓，請替我保守這個祕密。",
  str_voice_1600773_16 = "空曠的雪原之上，亦有調皮的歌手在吟唱。側耳傾聽吧，這連雪也能融化的歌聲。",
  str_voice_1600773_17 = "嗯，你醒了？果然，舒緩的音樂更容易將人從夢境中喚醒。",
  str_voice_1600773_18 = "夜晚再次降臨北境，家家戶戶都唱起同一首歌謠……♪～",
  str_voice_1600773_19 = "還不去休息嗎？好吧，如果你執意做我的深夜聽眾。",
  str_voice_1600773_35 = "北境的樂隊已就位。",
  str_voice_1600773_36 = "是時候登台演唱了。",
  str_voice_1600773_37 = "這首歌，獻給所有光靈。",
  str_voice_1600773_38 = "把這首旋律刻在心裡吧。",
  str_voice_1600773_39 = "極寒掃弦！",
  str_voice_1600773_40 = "冰蝕泛音！",
  str_voice_1600773_44 = "一起用歌聲傳遞希望吧，我的獨家聽眾。",
  str_voice_1600773_58 = "早安，我所期許之人。",
  str_voice_1600773_59 = "一杯紅茶，開啟寧靜的一天。",
  str_voice_1600773_60 = "今晨，可曾聽到那啁啾的鳥鳴？",
  str_voice_1600773_61 = "昨夜，你可曾陷入夢境的泥沼？",
  str_voice_1600773_62 = "清晨的時光轉瞬即逝，切要好好把握。",
  str_voice_1600773_63 = "「晨曦中，冰晶閃爍……」",
  str_voice_1600773_64 = "新的一天，要體驗誰的人生呢？",
  str_voice_1600773_65 = "中午好，我的聽眾。",
  str_voice_1600773_66 = "一日過半，感覺如何？",
  str_voice_1600773_67 = "記住，可把北境視作你的故鄉。",
  str_voice_1600773_68 = "待命運降臨之時，你終會知曉一切。",
  str_voice_1600773_69 = "支離破碎的未來之中，有無數關於你的蜃景。",
  str_voice_1600773_70 = "復仇無法成為戰鬥的理由。",
  str_voice_1600773_71 = "如果決心踏上戰場，你要先找到自己想守護的東西。",
  str_voice_1601781_99 = "為了用好鈴鼓，我練習了很久，希望不會讓大家失望~",
  str_voice_1601031_99 = "演出的歌曲哪裡有審訊室裡的尖叫聲好聽呢？",
  str_voice_1601481_99 = "演出完以後，要怎麼報答姐姐呢？",
  str_voice_1601161_99 = "演出結束後，我可以帶走幾個漂浮巨像的零件作為紀念嗎？",
  str_voice_1600021_99 = "參加演出對我來說也是一種修行，可以磨練心性。",
  str_voice_1601771_99 = "希望我們的歌聲能帶給大家感動和力量~",
  str_voice_1601811_1 = "我曾隨林家家主數次出海，海上風景甚美，不妨放下旁念，用心欣賞。",
  str_voice_1601811_2 = "這三隻小貓已與我相伴多年，正如我的左膀右臂，已然密不可分了。",
  str_voice_1601811_3 = "如果你喜歡的話，我很樂意為小友多多講述龍洲歷史、風物人情。",
  str_voice_1601811_4 = "人生逆旅，能交到小友這樣的知己，真是不虛此行。",
  str_voice_1601811_5 = "前半生恣意英雄氣，後半生漂泊如浮萍，但又如何？無人能決定我身在何處，更無人能動搖我心中執念。",
  str_voice_1601811_6 = "好啊，好啊！功名不過塵與土，此身未老，我仍能手握赤焰，斬邪除惡！",
  str_voice_1601811_7 = "小友正是風華正茂之年，不禁讓我想起往事。與我出去走走，暢談一番，如何？",
  str_voice_1601811_8 = "與小友相逢，仲某受益良多。看來世間廣闊，遠不止龍洲的一隅天空。",
  str_voice_1601811_9 = "我年少時曾如你一般，願小友今後也能一往無前，追逐星辰。",
  str_voice_1601811_10 = "經年遊歷的這些時光，在外漂泊已久，我也不禁開始想念故土人情了啊……",
  str_voice_1601811_11 = "能得到小友的信賴，是仲某之榮幸。",
  str_voice_1601811_12 = "起風了，起風的時候，總會想起故鄉之秋。",
  str_voice_1601811_13 = "你可以隨時和我的小貓們玩耍，牠們分別叫一心、一夢、一諾。放心，牠們深知你是我的好友，不會傷你。",
  str_voice_1601811_14 = "我的輪椅似乎最近有點響動，也可能是錯覺吧？實話說來，我好像還沒有那麼習慣。",
  str_voice_1601811_15 = "良辰吉日，祝小友身體康健，心想事皆成。",
  str_voice_1601811_16 = "為事物感到心煩意亂之時，只需閉眼冥想片刻。",
  str_voice_1601811_17 = "沐浴在晨曦之下，令人心安。",
  str_voice_1601811_18 = "工作一日後，學會適當放鬆，也是提升效益的辦法。",
  str_voice_1601811_19 = "萬籟俱寂之時，反而能令頭腦清醒。",
  str_voice_1601811_20 = "無論經歷幾何，我始終熱愛著龍洲這片土地。",
  str_voice_1601811_21 = "艾斯特拉大陸，還有許多我未曾見識的景物，是個神奇的地方。",
  str_voice_1601811_22 = "但行萬里之遙，護我龍洲河山！",
  str_voice_1601811_23 = "有光的地方，自然會有黑暗。",
  str_voice_1601811_24 = "別看林家家主如今穩重的模樣，他年輕時可因為輕率吃了不少苦頭。",
  str_voice_1601811_25 = "厘青小貓，戲弄他甚是有趣。嗯，我是不是不該這樣說我的大夫？",
  str_voice_1601811_26 = "龍洲生產的瓷器甚是精美，是我喜愛的物件。",
  str_voice_1601811_27 = "可能是由於海上的經歷吧，看到魚讓我想起了不愉快的回憶。",
  str_voice_1601811_28 = "真是……令人震撼的存在。",
  str_voice_1601811_29 = "我曾乃龍洲大陸兆國的大將軍仲胥，如今不過一逍遙浪客。前塵往事休再提，惟願今起，伴君同行。",
  str_voice_1601811_30 = "胸中之火，赫赫炎炎。",
  str_voice_1601811_31 = "氣力有所恢復。",
  str_voice_1601811_32 = "妙哉，樂哉！",
  str_voice_1601811_33 = "英姿如也！",
  str_voice_1601811_34 = "久等了。",
  str_voice_1601811_35 = "蓄勢待發。",
  str_voice_1601811_36 = "感覺狀態不錯。",
  str_voice_1601811_37 = "須臾，斷滅！",
  str_voice_1601811_38 = "炎火焚盡，斷滅諸惡！",
  str_voice_1601811_39 = "一心，出陣！",
  str_voice_1601811_40 = "戰場無情。",
  str_voice_1601811_41 = "定當不負期望。",
  str_voice_1601811_42 = "勝局在握，不過如此。",
  str_voice_1601811_43 = "留得青山，再接再厲。",
  str_voice_1601811_44 = "不必顧慮我，這裡甚好。",
  str_voice_1601811_45 = "小友的心意，我領受於心。",
  str_voice_1601811_46 = "小友體貼入微，我感念於心。",
  str_voice_1601811_47 = "實乃厚禮，小友破費。",
  str_voice_1601811_48 = "如此佳贈，我心甚喜。",
  str_voice_1601811_49 = "我曾揮劍持槍，為振興國家、平復災亂攜軍四處征伐，那時候，真是少年意氣風發啊……",
  str_voice_1601811_50 = "在濟國道上，我救下了被劫的林家商隊，由是與林家家主相識。如此說來，我倆已經相識十多載了。",
  str_voice_1601811_51 = "離開央京之時，我並未帶過多身外之物，唯獨帶了這三隻小狸貓。只要家國此情長留心中，天地再大，也不會是偏安一隅了。",
  str_voice_1601811_52 = "白夜極光。",
  str_voice_1601811_53 = "小友安好。",
  str_voice_1601811_54 = "天光曦微。",
  str_voice_1601811_55 = "此為天光正盛之時。",
  str_voice_1601811_56 = "小友，夜已深了。",
  str_voice_1601811_57 = "新禧已至，願君安康。",
  str_voice_1601821_1 = "若問前方是什麼？是暗流，是險礁，是吞沒一切的海嘯，但這條路是我自己選的，無論如何也要走完。",
  str_voice_1601821_2 = "打造艦船並非易事，需要船廠、港口、林場的系統協作。你指揮眾人作戰，想來也是多方協調籌謀，更是不易。",
  str_voice_1601821_3 = "不必說些無聊的寒暄，我不關心。我來找你，是想和你交朋友。",
  str_voice_1601821_4 = "給船槳上油，船便能划得更快；給掌舵者以海圖，船方能行對航路。",
  str_voice_1601821_5 = "看不出來你體格竟然不錯，方才出海那麼大的風浪，你都沒有暈船嘔吐，很是難得。明日再帶你參加「帆船競速比賽」，那個更刺激。嗯？怎麼跑了？",
  str_voice_1601821_6 = "受傷了啊，嗯，你好可憐。我太冷漠？那你把衣服除去，我剛在日頭下忙完，手掌熱呼呼的，幫你上藥可夠熱了。",
  str_voice_1601821_7 = "等有空了，帶你出海去狩獵瓊角鯤。現在就想去？不可，需得提前一日派小船過去勘探情勢，等我安排妥當，定會叫你。",
  str_voice_1601821_8 = "你把我的寵物魚放生了？那麼你來代替牠，成為我的寵物。",
  str_voice_1601821_9 = "我臉色不好？大概是因為剛剛訓斥了幾個部下，一群蠢貨。別走。你又不是我的部下，不需要看我臉色，在我旁邊……待著便好。",
  str_voice_1601821_10 = "上了我的船，要一切聽從我的指揮，否則就……下船。",
  str_voice_1601821_11 = "他們說想感謝別人就要報以笑容，謝謝你請我來，呵呵。",
  str_voice_1601821_12 = "人人都說大海洶湧無情，可面對大海比面對人容易多了。",
  str_voice_1601821_13 = "雖然有更快捷的方法……算了，想釣大魚，就要有耐心。",
  str_voice_1601821_14 = "最近有點不開心，想要我安慰？喔，別不開心。我當然把你當朋友，但我不想說那些無聊的寒暄。",
  str_voice_1601821_15 = "祝你像萬年海怪一樣長壽。",
  str_voice_1601821_16 = "你覺得無聊？喔，我不覺得。",
  str_voice_1601821_17 = "想看看早上的海嗎？",
  str_voice_1601821_18 = "世間美景，莫若海上夕陽。",
  str_voice_1601821_19 = "夜深別隨便出門，萬一遇到暗鬼，會死。",
  str_voice_1601821_20 = "濟國擁有得天獨厚的海運條件，才能造就發達的貿易業。",
  str_voice_1601821_21 = "艾斯特拉大陸物產豐富，多多交流貿易定能為雙邊發展助力。",
  str_voice_1601821_22 = "往來各國，交流有無，是我們商會的主旨。",
  str_voice_1601821_23 = "就像水下的暗礁一樣令人厭惡。",
  str_voice_1601821_24 = "我是被林家長老收養的，他不僅是我撫養我的親人，更是我的老師。這份知遇之恩，定當報答。",
  str_voice_1601821_25 = "我的家人？母親死了，父親跑了，還想知道什麼？我沒有生氣。真的沒有。真的。",
  str_voice_1601821_26 = "螺粉，好吃。",
  str_voice_1601821_27 = "甜膩膩的東西和乾巴巴的東西，我吃不慣。",
  str_voice_1601821_28 = "你說這巨像能入海嗎？",
  str_voice_1601821_29 = "我是木月白，「蜃風號」遠航船船長。沒事的話，別來找我。",
  str_voice_1601821_30 = "如魚得水。",
  str_voice_1601821_31 = "航向正確。",
  str_voice_1601821_32 = "百尺竿頭。",
  str_voice_1601821_33 = "願乘長風，破萬里浪。",
  str_voice_1601821_34 = "來了。",
  str_voice_1601821_35 = "潮起。",
  str_voice_1601821_36 = "潮平。",
  str_voice_1601821_37 = "洪流，席捲而至！",
  str_voice_1601821_38 = "大海無邊，容納萬物。",
  str_voice_1601821_39 = "不要偏航。",
  str_voice_1601821_40 = "洗淨世間。",
  str_voice_1601821_41 = "定不負使命。",
  str_voice_1601821_42 = "月亮，從海上升起來了。",
  str_voice_1601821_43 = "不知該如何安慰你。",
  str_voice_1601821_44 = "這巨像的構造與船體相仿，我想好好研究一下。",
  str_voice_1601821_45 = "為什麼送禮？還送得這麼普通。",
  str_voice_1601821_46 = "挺好，謝了。",
  str_voice_1601821_47 = "哦，一般般吧。",
  str_voice_1601821_48 = "多謝，這個很合我心意。",
  str_voice_1601821_49 = "我生來就長著螭龍魚尾，別人見了多半都會害怕。哦？你不覺得害怕，只是好奇？",
  str_voice_1601821_50 = "這把「冰骨刃」是林家長老送我的，而且送了我兩次，一次是我出生的時候，一次是我爹離開的時候。",
  str_voice_1601821_51 = "我本姓林，後來才改姓木，個中緣由……還是帶你參觀「蜃風號」吧，最近我又改良了動力系統。",
  str_voice_1601821_52 = "白夜極光。",
  str_voice_1601821_53 = "天氣不錯，適宜出海。",
  str_voice_1601821_54 = "你來了，我吃早飯去了。再見。",
  str_voice_1601821_55 = "午間炎熱，我洗澡去了。再見。",
  str_voice_1601821_56 = "天色不早了，我睡覺去了。再見。",
  str_voice_1601821_57 = "新年快樂。",
  str_voice_1501831_1 = "別摸我頭！你怎麼對長輩這麼不禮貌！我幾歲？十二歲……但也是你的長輩！",
  str_voice_1501831_2 = "你正是長身體的年紀，每天吃一副這個，補充補充營養。錢？我對這種東西可不感興趣，再提錢我可要生氣了！",
  str_voice_1501831_3 = "這隻小貓？小尾巴才不是小貓，是我哥哥。他又懶又饞，所以才遲遲沒修煉成人形……痛痛痛！知道啦，不叫你乳名啦！",
  str_voice_1501831_4 = "總覺得身體變輕了！好嘞，這下我總能跳上櫃頂了。讓我看看這裡都放著什麼……",
  str_voice_1501831_5 = "今天看了五本新書，所有知識我都記住了。我很聰明對吧！嗯……不過也有你的功勞。",
  str_voice_1501831_6 = "呼……嗯！耳聰目明，感覺現在可以一口氣嚐遍百草，寫出無數個新方子！等一下你得幫我試藥喔！",
  str_voice_1501831_7 = "前幾天我找到一種非常好吃的果子，你也嚐嚐……啊，小尾巴！你怎麼都給吃掉了！！",
  str_voice_1501831_8 = "想摸摸我的尾巴？嗯、嗯……也不是不行……就破例讓你摸一把，只為你破例喔！",
  str_voice_1501831_9 = "其實很多人都不喜歡我們「祟靈」，覺得我們很野蠻，低人一等。但是，PlayerName，和你在一起的時候……不不不！算了！！",
  str_voice_1501831_10 = "嗯～～～一直關在屋子裡太無聊了！快帶我去外面尋找新的藥材吧！",
  str_voice_1501831_11 = "來啦來啦，怎麼了，哪裡不舒服？……沒有生病？本醫可是很——忙的！別隨便叫……替我準備了零食？那、那我就勉為其難……",
  str_voice_1501831_12 = "你怎麼又在吃零食這麼沒營養的東西，沒收！……還挺好吃的。我、我是大人，吃兩口沒事！",
  str_voice_1501831_13 = "我很博學對吧？我的藥很管用對吧？你還挺有眼光的嘛！咳咳，功名利祿乃身外之事……不過你再多誇幾句也無妨。",
  str_voice_1501831_14 = "對我的秤感興趣？不可以亂摸哦！這可是用來配藥的重要道具，必須隨時保持精準和乾淨。",
  str_voice_1501831_15 = "生日快樂！今天你可以吸小尾巴的肚皮，我替他答應你了。",
  str_voice_1501831_16 = "哈～下午陽光真好，曬得我好睏……",
  str_voice_1501831_17 = "好忙好忙……你來啦！趕緊幫我搬一下那邊的草藥，可不許偷懶哦！",
  str_voice_1501831_18 = "這麼晚還來工作，你也挺勤奮的嘛。不過可別睡太晚哦。",
  str_voice_1501831_19 = "哇！你怎麼還在熬夜！我來幫你把工作做完，你給我趕緊睡覺！",
  str_voice_1501831_20 = "卜子曰：醫非仁愛不可托，非廉潔不可信。",
  str_voice_1501831_21 = "白夜城的人穿著打扮可真奇怪，怎麼全是白白金金的。",
  str_voice_1501831_22 = "救死扶傷，懸壺濟世！",
  str_voice_1501831_23 = "水裡的暗鬼比地上的還要可怕！當時嚇得我都要有心理陰影了……",
  str_voice_1501831_24 = "仲胥呀，就是個老古板嘛。不過別看他這樣，其實面冷心熱哦。",
  str_voice_1501831_25 = "雖然師父不讓我四處招搖……但我可是卜存子弟子！師父是世上最棒的醫生！",
  str_voice_1501831_26 = "好像聞到飯的香味了……唔……讓我去看看！",
  str_voice_1501831_27 = "小孩子才挑食呢。什、什麼……？你為什麼端出來一盤青椒？！！",
  str_voice_1501831_28 = "怎樣才能治好臨空者號？機械……系統……嗯——完全不明白！",
  str_voice_1501831_29 = "哼哼～能找到我這個名醫，你也有點本事嘛。我是厘青，有我在保你藥到病除！",
  str_voice_1501831_30 = "身高有沒有增長呢……",
  str_voice_1501831_31 = "嗯？嗅覺變得更好了。",
  str_voice_1501831_32 = "味覺也變得更敏銳了！",
  str_voice_1501831_33 = "身高好像變高了……！",
  str_voice_1501831_34 = "交給我吧！",
  str_voice_1501831_35 = "配比完美！",
  str_voice_1501831_36 = "藥效強勁！",
  str_voice_1501831_37 = "良藥苦口！",
  str_voice_1501831_38 = "集天地草木精華！",
  str_voice_1501831_39 = "瞄準——",
  str_voice_1501831_40 = "接藥！",
  str_voice_1501831_41 = "大家跟上！",
  str_voice_1501831_42 = "哼哼～必然的結果！",
  str_voice_1501831_43 = "痛痛痛……",
  str_voice_1501831_44 = "哇！嚇我一跳！",
  str_voice_1501831_45 = "是好吃的嗎？",
  str_voice_1501831_46 = "你還滿有品味嘛！",
  str_voice_1501831_47 = "又是送我的？怪、怪不好意思的……",
  str_voice_1501831_48 = "你怎麼知道我喜歡這個……",
  str_voice_1501831_49 = "和普通的「祟靈」不同，我誤食了卜存子的丹藥，誤打誤撞才化為人形。要不是我足夠幸運，說不定當時就一命嗚呼了！",
  str_voice_1501831_50 = "為了償還藥債，我成為了師父的弟子。但漸漸地，我也開始理解身為醫者的快樂和責任。",
  str_voice_1501831_51 = "但是好景不長，我偷偷下山的事情很快就暴露了。師父訓人的時候可兇了！但我也有不容妥協的夢想。",
  str_voice_1501831_52 = "白夜極光！",
  str_voice_1501831_53 = "喂～",
  str_voice_1501831_54 = "一日之計在於晨哦！",
  str_voice_1501831_55 = "吃飽了才有力氣工作！",
  str_voice_1501831_56 = "呼啊～該睡了……",
  str_voice_1501831_57 = "新年快樂～你也要繼續成長，早點變得像我一樣成熟可靠哦！",
  str_voice_1601841_1 = "又有部下要找我？幫我轉告他們，叫他們自己看著辦吧。沒關係，我相信他們有能力辦好，全都是小問題、小問題啦～",
  str_voice_1601841_2 = "……嗯？你說什麼？剛剛沒聽到，注意力都在書上。說吧，我邊看書邊聽你講。嗯、嗯……我有在聽。",
  str_voice_1601841_3 = "所以這裡所有人的資源都是你義務準備的？空裔小哥還真是個老好人……不，還是該說這裡的人都太愛佔人便宜？",
  str_voice_1601841_4 = "我喜歡新鮮的事物。比方說旅行、讀書、探索未知、思考哲理等等，新鮮的刺激感能帶給我活著的真實感。反之，無聊則有如動態的死亡。",
  str_voice_1601841_5 = "在你重建之前，我去過空之山谷。混亂、荒蕪、死寂……還有破滅。你覺得，人們前進究竟有什麼意義呢？",
  str_voice_1601841_6 = "幽青巨蟒最近經常傳給我一種奇妙的感覺。怎麼解釋好呢……嗯，嚴肅一點來說，就是「我們來到這裡，不虛此行」。",
  str_voice_1601841_7 = "我很欣賞你的中立態度，或者說不輕易偏向任何勢力的做法。無序、階級、鐵律、保守……沒必要急著染上某種顏色。",
  str_voice_1601841_8 = "別總是積極投身於麻煩，偶爾也和我一起享受觀劇的樂趣吧。看戲很有趣喔？你一定會喜歡上這種感覺。",
  str_voice_1601841_9 = "來，告訴我你近日的所見所聞。最近閒閒無事，很無聊？別這麼說嘛，我很喜歡你分享的小趣事呢。",
  str_voice_1601841_10 = "嗯……書也看膩了，帶我去做點有意思的事吧。",
  str_voice_1601841_11 = "要我待在這裡？可以啊。那我就繼續看書吧……工作？嗯、嗯，工作的部分，我會去做。",
  str_voice_1601841_12 = "我不像出生在紅油扳手的人？我也這麼覺得。而且我好像也不適合任何勢力。但我喜歡這種感覺。",
  str_voice_1601841_13 = "我說話有時很尖銳？嗯……誰知道呢～尖銳也好、隨和也罷，聲音只會在碰到壁面時反射。正所謂「聽者有心」，不是嗎？",
  str_voice_1601841_14 = "人際關係……我不在意啊。不過看到無處可去、只能作廢的信件，心裡難免會有一點失落感。",
  str_voice_1601841_15 = "今天是你的生日嗎……那就祝你能一直不迷惘地走下去吧。",
  str_voice_1601841_16 = "你很勤奮呢，我來觀察一下你工作的樣子吧。",
  str_voice_1601841_17 = "早啊，正巧鶴鷹剛回來，如果有有什麼有趣的消息，我再跟你分享。",
  str_voice_1601841_18 = "晚安，轉眼之間一天又快過去了，光陰似箭呢。",
  str_voice_1601841_19 = "……嗯？空裔小哥居然還在？那正好，趁大家都睡了，和我單獨聊聊吧。",
  str_voice_1601841_20 = "相對於其他勢力，信使公會真是個舒服的好地方。",
  str_voice_1601841_21 = "有時我真的很希望紅油扳手的人行動前可以多思考一下。",
  str_voice_1601841_22 = "信使公會，使命……應該能送達。",
  str_voice_1601841_23 = "暗鬼……他們究竟如何出現，又抱著何等目的而行動呢？",
  str_voice_1601841_24 = "我很喜歡像凱雅這樣單純可愛的孩子喔～而且她的確很擅長工作。",
  str_voice_1601841_25 = "別擔心，天塌下來有納努塞爾頂著，有她在總會有辦法。",
  str_voice_1601841_26 = "能一邊看書一邊吃肝臟製成的零食，是非常棒的享受呢。",
  str_voice_1601841_27 = "別總是做無聊的工作。成天做那些事會讓你變得平庸無趣。",
  str_voice_1601841_28 = "這座巨像和紅油扳手的那座不太一樣，空裔文化真是深奧。",
  str_voice_1601841_29 = "我是耶利亞，與我隨意相處就可以了。很在意我的朋友們嗎？別怕，他們和我一樣，比起暴力更喜歡新鮮事物。",
  str_voice_1601841_30 = "嗯，感覺還不賴。",
  str_voice_1601841_31 = "體能似乎變強了。",
  str_voice_1601841_32 = "內心感到平靜。",
  str_voice_1601841_33 = "知識流進了腦海。",
  str_voice_1601841_34 = "好吧……",
  str_voice_1601841_35 = "魔典——",
  str_voice_1601841_36 = "隨時都行。",
  str_voice_1601841_37 = "言靈們！",
  str_voice_1601841_38 = "幻惑之光！",
  str_voice_1601841_39 = "鶴鷹！",
  str_voice_1601841_40 = "巨蟒！",
  str_voice_1601841_41 = "要我當隊長？",
  str_voice_1601841_42 = "蠻無聊的。",
  str_voice_1601841_43 = "這下有意思了……",
  str_voice_1601841_44 = "嗯……有什麼趣事嗎？",
  str_voice_1601841_45 = "謝謝你。",
  str_voice_1601841_46 = "這還真不錯。",
  str_voice_1601841_47 = "快讓我看看。",
  str_voice_1601841_48 = "真是新奇……你想要什麼回禮？",
  str_voice_1601841_49 = "我出生於紅油扳手，父母都是……相當自由奔放的人。即使我的個性與周遭格格不入，我很感謝他們依舊包容我。",
  str_voice_1601841_50 = "我在某次意外中展現了光能術的天賦。父母開始意識到我不該被束縛在這裡。所以後來時機成熟時，我就踏上了旅途。",
  str_voice_1601841_51 = "起初我熱衷於旅行。然而隨著見識增長，我反而陷入了迷惘。人生的盡頭，究竟會是什麼呢？",
  str_voice_1601841_52 = "白夜極光。",
  str_voice_1601841_53 = "你好。",
  str_voice_1601841_54 = "這時間很適合讀書。",
  str_voice_1601841_55 = "休息一下。",
  str_voice_1601841_56 = "月亮出來了。",
  str_voice_1601841_57 = "知識並不會隨著歲月自然累積，切記旅途的路出自你的腳下。",
  str_voice_1501851_1 = "你手裡拿著什麼？好像很特別……咳哼，對於行走天涯的信使而言，這還稱不上新奇。",
  str_voice_1501851_2 = "那條路確實比較近，可是公會地圖上沒有紀錄，所以不能走。唔……繞了好遠，也許剛才應該聽你的。",
  str_voice_1501851_3 = "這裡正在舉辦一年一度的市集？好想去看看啊……不行！我還有信要送！絕對不能耽誤！",
  str_voice_1501851_4 = "身為信使公會的信使即代表我能獨當一面，就算跌倒也……哎呀！好痛！不用扶我，我能自己爬起來。",
  str_voice_1501851_5 = "從歷史的角度來看，向我們傳遞古老文明和文化的遺跡也是一種信使。別小看我，我讀了很多相關書籍。",
  str_voice_1501851_6 = "聽說在信使公會成立以前，光靈們都是靠騎馬甚至跑步傳遞信息，真辛苦啊……",
  str_voice_1501851_7 = "紅油辣醬炒鹽漬魚罐頭……？這、這真的能吃嗎？！我才不吃呢！你強烈推薦？唔……那我就試試看吧……",
  str_voice_1501851_8 = "如果遇到開心的事，可以寫信跟你分享嗎？我希望笑容能從我臉上傳遞到你的臉上，嘻嘻。",
  str_voice_1501851_9 = "寫信是一種很浪漫的交流方式呢，我想說……你能寫封信給我嗎？任何內容都可以。",
  str_voice_1501851_10 = "真希望我擁有過目不忘的能力，這樣就不會弄錯了……我、我才沒有送錯地址，已經飛快地拿回信件了！",
  str_voice_1501851_11 = "有什麼訊息需要我傳遞嗎？使命必達、絕對準時！",
  str_voice_1501851_12 = "把信件交給我就可以放心了，絕對不會弄丟。不過至於你的信件……不，我不會偷看啦。真的，嗯……",
  str_voice_1501851_13 = "本月送信排行榜的倒數第一又是我……PlayerName，你想不想寄信？郵資我出，只求交給我寄！",
  str_voice_1501851_14 = "公會地圖表示要直走，但前方是一堵牆，反倒是左邊還有條路，該怎麼辦呢？還是……翻牆過去好了。",
  str_voice_1501851_15 = "生日快樂～今天的祝福和禮物，我會全數為你送到！",
  str_voice_1501851_16 = "為你帶來遠山和清風的問候。",
  str_voice_1501851_17 = "要不要和我一起去送信？",
  str_voice_1501851_18 = "收到久未謀面的朋友來信，會感到開心吧？",
  str_voice_1501851_19 = "請允許我將星星送進你的夢裡。",
  str_voice_1501851_20 = "信使公會是一個了不起的組織，是我們與他人聯繫的橋樑和管道。",
  str_voice_1501851_21 = "每個地方都有自己的特點，我希望自己的足跡能遍布整個大陸。",
  str_voice_1501851_22 = "信使公會，安全、及時、保密。",
  str_voice_1501851_23 = "暗鬼嗎？就算牠們想寄信，我也不會幫牠們送。",
  str_voice_1501851_24 = "真想不通多孚那樣的人怎能進入信使公會？每次看到她都是在偷懶，一點也沒有信使該有的緊張感。",
  str_voice_1501851_25 = "納努塞爾是位值得尊敬的前輩和上司，我會以她為榜樣！",
  str_voice_1501851_26 = "守時才是最大的美德。",
  str_voice_1501851_27 = "唔……又被放鴿子了。可不可以不要這樣……",
  str_voice_1501851_28 = "要送信到這裡還真不容易呢！",
  str_voice_1501851_29 = "您好，信使凱雅在此，為您帶來最新的訊息，請留意查收。",
  str_voice_1501851_30 = "收到信件了。",
  str_voice_1501851_31 = "跑得更快了。",
  str_voice_1501851_32 = "耳聰目明。",
  str_voice_1501851_33 = "遞送成功。",
  str_voice_1501851_34 = "我來啦。",
  str_voice_1501851_35 = "準備好了。",
  str_voice_1501851_36 = "靜候指示。",
  str_voice_1501851_37 = "隔空投遞！",
  str_voice_1501851_38 = "郵件來了！",
  str_voice_1501851_39 = "請簽收！",
  str_voice_1501851_40 = "攻擊送達！",
  str_voice_1501851_41 = "我會認真管理！",
  str_voice_1501851_42 = "想把這份喜悅寄送給大家～",
  str_voice_1501851_43 = "唔……把失敗偷偷藏起來。",
  str_voice_1501851_44 = "我正在看地圖，努力記住每個地區的街道。",
  str_voice_1501851_45 = "呃……謝謝。",
  str_voice_1501851_46 = "我可以收下嗎？好喜歡！",
  str_voice_1501851_47 = "已經簽收啦。",
  str_voice_1501851_48 = "超級棒的禮物！非常感謝！",
  str_voice_1501851_49 = "我的家鄉叫法爾村，地處偏遠，人跡罕至。在我的幼年記憶中，世界也彷彿只有法爾村那麼大。",
  str_voice_1501851_50 = "愛梅洛是我的老师，也是帶領我加入信使公會，讓我成為信使的人。",
  str_voice_1501851_51 = "印象深刻的經歷？就是有次送信的時候，遇見一群被暗鬼圍攻的小孩子！",
  str_voice_1501851_52 = "白夜極光。",
  str_voice_1501851_53 = "叮咚！",
  str_voice_1501851_54 = "晨光多麼明媚。",
  str_voice_1501851_55 = "中午休息一下吧。",
  str_voice_1501851_56 = "睡前記錄一下今天的生活。",
  str_voice_1501851_57 = "新年是我最忙碌的時節，不過能送祝福給大家，我也很開心。",
  str_voice_1601861_1 = "真是不錯的一天啊～出去散散步吧，然後回來好好睡一覺。有點捨不得離開我的躺椅，嗯，還是省略「散步」的步驟直接入睡吧。",
  str_voice_1601861_2 = "要在清醒的時間裡，高效率地完成工作才行。",
  str_voice_1601861_3 = "偷偷告訴你，其實我是左撇子，可是因為害怕誤傷到別人，所以簡單的事情我會選擇用右手處理。",
  str_voice_1601861_4 = "我覺得現在充滿了活力，是不是因為我成長了？",
  str_voice_1601861_5 = "審判庭的工作雖然繁雜，不過最近我的效率提高了不少。畢竟不能因為我的關係，給同事們添太多麻煩。",
  str_voice_1601861_6 = "「神之手」的力量變得更強大了，看來我以後使用左手得更加小心才行。",
  str_voice_1601861_7 = "PlayerName果然是個暖心的人，以後有什麼需要，也可以找我幫忙喔～",
  str_voice_1601861_8 = "嗯，你想試坐一下我的躺椅嗎？是家族的人特地為我訂做的，非常柔軟舒適喔。",
  str_voice_1601861_9 = "能夠認識PlayerName真是……太好了，你是我值得信賴的朋友，坎貝爾家族也將是你的後盾。",
  str_voice_1601861_10 = "閒來無事的話，可以用睡覺來打發時間。",
  str_voice_1601861_11 = "咦，不怕我突然睡著嗎？",
  str_voice_1601861_12 = "甜食雖然很美味，但是我吃了會失眠。嗯，你也要注意糖分的攝取量喔，超標了會變成大號的空裔～",
  str_voice_1601861_13 = "咦？我的筆記本在哪裡？我習慣每天記錄我清醒的時間，這樣可以幫我解決許多煩惱。",
  str_voice_1601861_14 = "我的夢境通常十分短暫，不過我醒來後會記得夢到了什麼。如果有趣的話，我會寫進筆記本裡。",
  str_voice_1601861_15 = "生日快樂喔，PlayerName。",
  str_voice_1601861_16 = "很高興見到妳。",
  str_voice_1601861_17 = "一覺醒來就能看見你，覺得很開心。",
  str_voice_1601861_18 = "我很喜歡日落之後的時間，可以獨自享受靜謐的時刻。",
  str_voice_1601861_19 = "這麼晚了啊……這個時間我通常已經昏睡了，你一般在做什麼呢？",
  str_voice_1601861_20 = "我相信白夜城的禮儀與優良傳統會一直傳承下去。",
  str_voice_1601861_21 = "紅油扳手的成員們，他們的生活是不是和冒險小說一樣精彩呢？",
  str_voice_1601861_22 = "白夜至上。",
  str_voice_1601861_23 = "我見過一隻可愛無害的小暗鬼，牠似乎是暗鬼中特別的存在。",
  str_voice_1601861_24 = "零恩……我很感激他，別人都嫌棄我的特殊體質，但他幫了我許多。",
  str_voice_1601861_25 = "馬太先生似乎覺得我給同事們添了麻煩，我會繼續努力的。",
  str_voice_1601861_26 = "要說我有什麼興趣……我很喜歡閱讀小說，尤其是懸疑類的喔！",
  str_voice_1601861_27 = "我很討厭睡覺時被人吵醒，因為這樣我就不得不另外找時間補眠了。",
  str_voice_1601861_28 = "好大的巨像……原來這不是只有在夢裡才會出現的啊。",
  str_voice_1601861_29 = "我很高興我們能成為朋友，不過你介意我一天只有四個小時清醒著嗎？",
  str_voice_1601861_30 = "「神之手」散發出耀眼的光輝。",
  str_voice_1601861_31 = "力量正在我的身體裡湧動。",
  str_voice_1601861_32 = "更能克制睡意了。",
  str_voice_1601861_33 = "「神之手」已擁有前所未有的威力。",
  str_voice_1601861_34 = "我不會突然睡著的。",
  str_voice_1601861_35 = "聖光滿盈。",
  str_voice_1601861_36 = "聖光將消滅所有邪惡。",
  str_voice_1601861_37 = "神聖光輝！",
  str_voice_1601861_38 = "聖光之下，無處躲藏！",
  str_voice_1601861_39 = "聖光灑落！",
  str_voice_1601861_40 = "聖光輝映！",
  str_voice_1601861_41 = "感謝你的信賴。",
  str_voice_1601861_42 = "「神之手」會掃除一切障礙。",
  str_voice_1601861_43 = "是我掌握「神之手」的能力還不足。",
  str_voice_1601861_44 = "唔？找我有什麼事嗎？別看我這樣，其實我現在很清醒喔。",
  str_voice_1601861_45 = "謝謝你，PlayerName～",
  str_voice_1601861_46 = "這份禮物十分貼心。",
  str_voice_1601861_47 = "你的好意，我已經感受到了喔～",
  str_voice_1601861_48 = "你記得我喜歡這個？啊，好感動。",
  str_voice_1601861_49 = "身為家族繼承人，我繼承了「神之手」和爵位。幼時的我還沒有患上「強睡症」，家族中的大家也不認為我和其他孩子有什麼不同。",
  str_voice_1601861_50 = "醫生並沒有幫我找到治癒「強睡症」的辦法。不過就算一天只清醒四個小時，只要我在這四個小時內做完所有事情就好了，所以我並沒有為此感到特別煩惱喔～",
  str_voice_1601861_51 = "要是能飼養那隻我碰見的小暗鬼當寵物，該有多好啊……不過，在白夜城應該是不可能的吧。嗯……其實我也只是想想而已啦。",
  str_voice_1601861_52 = "白夜極光",
  str_voice_1601861_53 = "你好啊～",
  str_voice_1601861_54 = "早安～",
  str_voice_1601861_55 = "啊，已經中午了。",
  str_voice_1601861_56 = "晚安喔。",
  str_voice_1601861_57 = "PlayerName，新年快樂唷！",
  str_voice_1601891_1 = "一提到正義，不少人都會嗤之以鼻。但正義不該是個可笑的詞。至少在白夜城審判官眼裡，它是唯一的尺度。",
  str_voice_1601891_2 = "比起外表，我更注重內在，或者說實用性。人們總用一種奇怪的語氣，說我的武器和打扮比較像啟光人。您覺得呢？",
  str_voice_1601891_3 = "世上大多的不幸，都源於不公。我深知自己無法顛覆現實，但目之所及的不公，我都會全力剷除。",
  str_voice_1601891_4 = "可以的話，請不要讓我和其他人搭檔工作。不，我對您的朋友沒有任何意見，只是我單獨工作比較有效率。",
  str_voice_1601891_5 = "若要嚴於律人，必須嚴於律己。所以踐行正義，一定要建立在自我鞭撻的基礎上。也請您隨時指正我。",
  str_voice_1601891_6 = "抱歉，我欺騙了您。我不願意與人合作，只是因為我個人的軟弱。而現在，我終於有勇氣承認這點了。",
  str_voice_1601891_7 = "如果累了的話，我可以為您泡一壺花茶，準備一些點心。花和水果都是我親自種的……抱歉說了這些，我有點失態了。",
  str_voice_1601891_8 = "人們都說，對待朋友應該用更隨意的語氣。咳咳，你、你早啊，兄弟，今天心情如何……還是算了吧，請忘記剛剛的一切。",
  str_voice_1601891_9 = "我，零恩，在此起誓。在您身邊時，我將僅作為您的騎士。只要不與正義相違，我會向您獻上所有忠……太沉重了？抱、抱歉，我只會這種的……",
  str_voice_1601891_10 = "……是不是睡著了？毛毯、毛毯……有了。啊，抱歉，吵醒您了。您感到疲累的話，可以休息一下，沒關係的。",
  str_voice_1601891_11 = "零恩前來報到。如有任何需求，請您隨時開口。只是想和我說說話？好吧，如果這是您期望的。",
  str_voice_1601891_12 = "為了增加閱歷，我不只會讀卷宗，還會看推理小說。不得不說，現在的推理小說越來越離譜了……但確實很有趣。",
  str_voice_1601891_13 = "萬分抱歉，因為與我同行，引起了多餘的矚目。有些人說我很討異性喜歡，但我不喜歡這樣，更不想給您添麻煩。",
  str_voice_1601891_14 = "恕我僭越，我有一些意見想傳達給您。請放心，此事與我審判官的身分無關。只是身為您的騎士，希望您飯前少吃零食。",
  str_voice_1601891_15 = "生日快樂。請問，您喜歡餅乾嗎？如果不喜歡，我可以換成別的……",
  str_voice_1601891_16 = "您好，歡迎回來。事不宜遲，請安排工作給我吧。",
  str_voice_1601891_17 = "早安，人在早晨的狀態最好，您可以將繁雜的工作安排在上午進行。",
  str_voice_1601891_18 = "時間不早了，請準備休息吧。任何做不完的工作，都可以交給我。",
  str_voice_1601891_19 = "您居然還醒著……是有什麼急事嗎？需要的話，零恩任您差遣。",
  str_voice_1601891_20 = "身為審判官，我沒有資格評判白夜城。因為造就它，即是我們的工作。",
  str_voice_1601891_21 = "我很看好啟光的務實，但比起正義更注重紀律這點，我無法苟同。",
  str_voice_1601891_22 = "白夜至上！",
  str_voice_1601891_23 = "暗鬼，這種彷彿以侵害光靈為生存意義的生物，必然是我的敵人。",
  str_voice_1601891_24 = "蒂娜很嗜睡，但她對工作盡心盡力。對我來說，這就足夠了。",
  str_voice_1601891_25 = "黑潮……我其實很感激他，但也真的不想再見到他了。",
  str_voice_1601891_26 = "閒暇時，澆澆花、修修老鐘、做頓美食……這種時光真不錯啊。",
  str_voice_1601891_27 = "我無法容忍不公……以及藏在菜葉下的辣椒。",
  str_voice_1601891_28 = "巨像，真是神奇的建築……不，對您來說，它更是您的家人吧。",
  str_voice_1601891_29 = "您好，我是白夜城的審判官，零恩。即使身處此地，我也會踐行我的正義。如有冒犯，還請您多多海涵。",
  str_voice_1601891_30 = "一步一步。",
  str_voice_1601891_31 = "這是日積月累的成果。",
  str_voice_1601891_32 = "抓住了，層層突破的訣竅！",
  str_voice_1601891_33 = "這正是，我的決心。",
  str_voice_1601891_34 = "收到。",
  str_voice_1601891_35 = "零恩，隨時準備。",
  str_voice_1601891_36 = "為您，為了正義。",
  str_voice_1601891_37 = "最大輸出，接招！",
  str_voice_1601891_38 = "撕裂黑暗！",
  str_voice_1601891_39 = "休想逃走！",
  str_voice_1601891_40 = "接受制裁吧！",
  str_voice_1601891_41 = "請交給我。",
  str_voice_1601891_42 = "贏了！戰果請您過目。",
  str_voice_1601891_43 = "請盡快撤離，我負責殿後……！",
  str_voice_1601891_44 = "我在，請問有何吩咐？",
  str_voice_1601891_45 = "您不必如此……",
  str_voice_1601891_46 = "好、好吧，感謝您……",
  str_voice_1601891_47 = "又是禮物？您可真是……",
  str_voice_1601891_48 = "謝謝……謝謝你。",
  str_voice_1601891_49 = "我的童年……並不怎麼開心，至今我都不知該如何面對父母。所以我逃跑了，逃到軍隊裡。說到底，我也只是個膽小鬼罷了。",
  str_voice_1601891_50 = "我熱愛軍隊的生活，但不喜歡那些複雜的人際利益。但那時的我，缺乏改變一切的決心。或許，與黑潮相遇也是件好事。",
  str_voice_1601891_51 = "總之，在黑潮的刺激下，我改變了自己的想法，試著主動去做些什麼。努力成為審判官，和蒂娜搭檔，當然，也包括伴您左右。",
  str_voice_1601891_52 = "白夜極光！",
  str_voice_1601891_53 = "您好。",
  str_voice_1601891_54 = "早安。",
  str_voice_1601891_55 = "午安。",
  str_voice_1601891_56 = "你好。",
  str_voice_1601891_57 = "新年快樂，今年也麻煩您繼續關照了。沒想到，我也能有說出這句話的一天。",
  str_voice_1501901_1 = "你穿的那是什麼亂七八糟的東西？算了，不能對你要求太高，品味這種東西得靠天賦和環境，而你顯然都沒有。",
  str_voice_1501901_2 = "把工作推給彼亞塔曼那傢伙，可不是為了偷懶，那種簡單乏味的工作我可看不上，時間應該用來學習和思考。",
  str_voice_1501901_3 = "我當然不討厭庶民，呵呵……但我也不能喜歡所有人嘛～如果是那樣，就說明我誰都不喜歡。",
  str_voice_1501901_4 = "如果沒有能力，就算是王室也得不到我的認可，我只欣賞真正有實力的人。噢，庶民不算在內。",
  str_voice_1501901_5 = "我喜歡美麗的事物，雖然都說和才能相比，美麗是虛無的，不過還好我二者皆備～",
  str_voice_1501901_6 = "刻苦努力後獲得成功是很偉大的事情，我發自內心這麼認為，可惜我不用努力就能成功。",
  str_voice_1501901_7 = "我居然會覺得你的品味還不錯，我肯定是生病了，果然生病會降低智商。",
  str_voice_1501901_8 = "事情太多忙不完？沒關係，我來教你：捫心自問，這件事可以丟給誰去做。",
  str_voice_1501901_9 = "你聽誰說我小時候穿女裝的事？！不，不准再說了！你真的想知道？其實就是小時候我媽媽……你懂的……",
  str_voice_1501901_10 = "又見到你了，真高興。什麼？我笑得很假？這麼明顯嗎……",
  str_voice_1501901_11 = "就這麼想一直看見我嗎？嘖，好吧，讓本貴族來淨化你的眼睛。",
  str_voice_1501901_12 = "錢能不能買到快樂我不知道，反正我既有錢，又很快樂～",
  str_voice_1501901_13 = "成功之路很難走，必須靠自己一步步走下去……我是說你，我先坐車去啦～",
  str_voice_1501901_14 = "喂，我在跟你說話，這是你的榮幸，現在、立刻、回應我。",
  str_voice_1501901_15 = "原來空裔也要過生日啊？真稀奇……那就將我的祝福賜予你吧。",
  str_voice_1501901_16 = "天氣好熱啊，貴族身上怎麼能有汗味呢？我去洗澡了。",
  str_voice_1501901_17 = "聞著早晨的露水清香，智商會提高，不過你大概體會不到吧。",
  str_voice_1501901_18 = "真正的寶石在黑夜裡也會閃爍，怪不得天黑時我看不見你。",
  str_voice_1501901_19 = "你這傢伙居然也和本貴族一樣睡不著？不對，我們才不一樣！",
  str_voice_1501901_20 = "貴族就是正義，白夜城是世界的主宰。",
  str_voice_1501901_21 = "什麼？世界上還有除了貴族以外的組織？",
  str_voice_1501901_22 = "白夜至上！",
  str_voice_1501901_23 = "就算一天洗八百次澡，也洗不掉暗鬼身上的汙穢。",
  str_voice_1501901_24 = "伊倫汀大人算不上是我的好友，不過卻是少數我看得上的人。",
  str_voice_1501901_25 = "彼亞塔曼嘛，很熱心，很有正義感，很能為我所用～",
  str_voice_1501901_26 = "哪怕是最普通的物品，只要用綠寶石裝飾，也會變得好看很多～",
  str_voice_1501901_27 = "嘖，好髒啊，快去洗乾淨！",
  str_voice_1501901_28 = "這個地方確實不錯，我宣布，為了保護這裡的環境，庶民禁止入內。",
  str_voice_1501901_29 = "本貴族是史上最年輕的審判官馬太，擁有絕佳品味和無盡才華，你可以崇拜我，但我大概不會和你當朋友。",
  str_voice_1501901_30 = "厲害如我。",
  str_voice_1501901_31 = "寶石閃耀。",
  str_voice_1501901_32 = "更華麗了～",
  str_voice_1501901_33 = "我就是光～",
  str_voice_1501901_34 = "可以歡呼了。",
  str_voice_1501901_35 = "光已降臨。",
  str_voice_1501901_36 = "家族榮耀。",
  str_voice_1501901_37 = "聖物閃光。",
  str_voice_1501901_38 = "長鞭之怒！",
  str_voice_1501901_39 = "判你有罪！",
  str_voice_1501901_40 = "乖乖伏法～",
  str_voice_1501901_41 = "還得靠我～",
  str_voice_1501901_42 = "習慣了。",
  str_voice_1501901_43 = "這不可能……",
  str_voice_1501901_44 = "巨像真不錯，如果只有貴族居住就更好了。",
  str_voice_1501901_45 = "這種東西能送人？",
  str_voice_1501901_46 = "小看你了。",
  str_voice_1501901_47 = "品味堪憂。",
  str_voice_1501901_48 = "那我就收下吧。",
  str_voice_1501901_49 = "我的家族是做服裝奢侈品生意的，所謂人靠衣裝，越普通的人越需要衣飾的加持，比如你。",
  str_voice_1501901_50 = "沒錯，我就是黎明學院傳聞中的神童～十歲就當上老師的助教，十五歲成為最年輕的審判官～可以掌聲加尖叫了。",
  str_voice_1501901_51 = "工作嘛，對我來說沒什麼難度，比較麻煩的其實是我那個討厭的搭檔……",
  str_voice_1501901_52 = "白夜極光。",
  str_voice_1501901_53 = "喂～",
  str_voice_1501901_54 = "今天適合休假。",
  str_voice_1501901_55 = "今天沒出汗～",
  str_voice_1501901_56 = "洗澡最棒了～",
  str_voice_1501901_57 = "想不到新年的氣氛讓你也染上了些許光彩呢。",
  str_voice_1601484_10 = "哈～有點睏了，我去睡一覺，有委託人來的話記得叫我。如果偷懶被我抓到……你懂吧？",
  str_voice_1601484_11 = "我父母曾說過：「好的獵人，最擅長偽裝和等待。」所以穿成這樣坐在這裡，也是很有必要的。就是無聊了點。",
  str_voice_1601484_16 = "委託人差不多要來了。打起精神，不然被子彈擦到臉頰我可不管喔？",
  str_voice_1601484_17 = "遲到的話，該怎麼罰你呢？嗯……就罰你當我的椅子吧？",
  str_voice_1601484_18 = "好了，該下班了。這麼急著走，是和哪個小可愛有約了嗎？",
  str_voice_1601484_19 = "哎呀，你怎麼這個時間來了？難道是來見我的？",
  str_voice_1601484_35 = "知道該怎麼做吧？",
  str_voice_1601484_36 = "精準地、確實地。",
  str_voice_1601484_37 = "封鎖完畢！",
  str_voice_1601484_38 = "無路可逃！",
  str_voice_1601484_39 = "乖乖別動。",
  str_voice_1601484_40 = "不會痛的。",
  str_voice_1601484_44 = "一起去完成下一項委託吧。",
  str_voice_1601484_1 = "我不喜歡一直待在一個地方。所以經營事務所這種事，玩玩就夠了。",
  str_voice_1601484_2 = "我喝得越多，就射得越準。要不要試試？對，就站在那邊，把空罐頂在頭上。",
  str_voice_1601484_3 = "這把槍雖然不及「山貓之眼」，但還不錯。乾脆幹完這票之後，送你玩好了。不想要嗎？",
  str_voice_1601484_12 = "這件上衣有點緊，所以我把扣子全解開了。不行？為什麼不行？來，清清楚楚地告訴我，不然我不明白呢。",
  str_voice_1601484_13 = "交換情報的時候，要準備好底牌。當然，槍口也算其中一種。",
  str_voice_1601484_14 = "哼～你還挺會討我歡心。作為助手，勉強還算及格。如果能再加把勁，我就給你獎勵。",
  str_voice_1601484_58 = "太陽曬屁股了，快起來。",
  str_voice_1601484_59 = "想去兜風嗎？",
  str_voice_1601484_60 = "事務所的工作，居然還挺有趣。",
  str_voice_1601484_61 = "中午吃什麼好呢？",
  str_voice_1601484_62 = "下午好熱。",
  str_voice_1601484_63 = "好無聊，有什麼趣事嗎？",
  str_voice_1601484_64 = "不來喝一杯嗎？",
  str_voice_1601484_65 = "還醒著嗎，小空裔？",
  str_voice_1601484_66 = "晚安，在想什麼呢？",
  str_voice_1601484_67 = "哪怕是工作，我也會以我的風格完成，這樣才有趣。",
  str_voice_1601484_68 = "小酌幾口，狀態才會更好。",
  str_voice_1601484_69 = "呵呵呵，就這麼討厭被壞姐姐欺負嗎？",
  str_voice_1601484_70 = "我的目的只有一個，那就是保護我現在的「家」。",
  str_voice_1601484_71 = "哎呀，我都要迷上你了。",
  str_voice_1601911_1 = "有時腦中會閃過轉瞬即逝的記憶片段，停留短短幾秒鐘，掌握不住，更無法留存。宛如煙火綻放而迅速凋零，不留一絲痕跡。",
  str_voice_1601911_2 = "我不是野狗！我不是怪物！我……唔……抱歉，剛才又做了噩夢。",
  str_voice_1601911_3 = "我剛才在聚會上故意躲在角落，原因當然是懶得社交，太麻煩了。不過我看得出來有人對你有意思，你還沒發現？那不說了，讓你自己慢慢去體會吧。",
  str_voice_1601911_4 = "在我的看法，得有強大的精神力才能適當駕馭火焰。你能指揮大家一起作戰，這肯定代表你的精神力無比強大吧？",
  str_voice_1601911_5 = "這個世界承載了太多的惡意。我見過，也經歷過許多不可思議的事，讓我明白到世界上並非只有光明。",
  str_voice_1601911_6 = "有些記憶令人痛苦，但無論如何也不願輕易遺忘。將碎片拼湊起來，在混亂中尋找規律，總有一天能得到答案吧。",
  str_voice_1601911_7 = "就算外表和普通人不太一樣，但我的內心並不因此有何不同。相信你能理解我，因為你和我散發著一樣的氣味。",
  str_voice_1601911_8 = "送給你，這是我製作的長明燈，裡面有一顆小小的火種，期望它在黑暗中為你帶來些許光明和溫暖。",
  str_voice_1601911_9 = "別擔心，我的耳朵早就痊癒了，你可以摸摸看……沒關係，你摸的感覺還挺舒服的。",
  str_voice_1601911_10 = "今天有點無聊，不如我們來玩捉迷藏吧。你會玩嗎？我可以教你。哦，你會啊，真厲害，我也是昨天才學會。",
  str_voice_1601911_11 = "你儘管放心去做事，我會在這裡守護你，無論何時，我都會守在這裡，你忠誠的哈提。",
  str_voice_1601911_12 = "我習慣獨自行動，但認識你之後發現有個夥伴好像也不賴，畢竟你能幫上忙，而且也不算太煩人。",
  str_voice_1601911_13 = "迷路的孩子，為尋找記憶點燃火焰，卻不曾想微弱的火苗也可能引發大火，焚毀一切。",
  str_voice_1601911_14 = "比起社會規則，我更相信自己的直覺。社會規則經常把事情搞得很複雜，我相信直覺反而能讓我們更快找到答案。",
  str_voice_1601911_15 = "生日快樂，我們一起去吃烤肉吧！",
  str_voice_1601911_16 = "有什麼想做的事就直接去做，不要拖拖拉拉。",
  str_voice_1601911_17 = "早晨起來就抽空曬曬陽光吧，全身暖洋洋的會很舒服。",
  str_voice_1601911_18 = "晚餐有吃燉肉嗎？多吃肉才有力氣生活嘛。",
  str_voice_1601911_19 = "在篝火的陪伴下，度過寧靜的夜晚。",
  str_voice_1601911_20 = "影鎮是個很複雜的地方，好像充滿了陰暗的角落，但也存在偶爾的光明。",
  str_voice_1601911_21 = "白夜城是世界上最黑暗的地方，我討厭那裡。",
  str_voice_1601911_22 = "影子在注視著你。",
  str_voice_1601911_23 = "暗鬼和白夜城的貴族一樣討厭。",
  str_voice_1601911_24 = "格林那傢伙就愛尬聊，但人不壞，跟誰都有辦法聊個兩句。",
  str_voice_1601911_25 = "伊斯塔萬算是我的恩人吧，若非有他在，大概也沒有現在的我了。",
  str_voice_1601911_26 = "還有新的報紙嗎？這期上面的字謎都被我猜完了。",
  str_voice_1601911_27 = "可以不吃蔬菜嗎？尤其是紫甘藍，真的好難吃啊……",
  str_voice_1601911_28 = "原來世界上真的有這樣的地方，充滿了光明和溫暖。",
  str_voice_1601911_29 = "別被我的外表嚇到，也別因為外表就排斥我，我只是一名普通的光靈，名為哈提，可以的話請和我做朋友。",
  str_voice_1601911_30 = "火焰燃燒。",
  str_voice_1601911_31 = "我變得更厲害了！",
  str_voice_1601911_32 = "焚燒萬物",
  str_voice_1601911_33 = "藍色火焰乃是永恆。",
  str_voice_1601911_34 = "你可以信賴我。",
  str_voice_1601911_35 = "藍火幽幽。",
  str_voice_1601911_36 = "想被撕碎嗎？",
  str_voice_1601911_37 = "火——蔓延！",
  str_voice_1601911_38 = "要上囉！",
  str_voice_1601911_39 = "藍火之魂！",
  str_voice_1601911_40 = "爆裂燃燒！",
  str_voice_1601911_41 = "包在我身上！",
  str_voice_1601911_42 = "痛快的勝利！",
  str_voice_1601911_43 = "這……真沒意思。",
  str_voice_1601911_44 = "總覺得待在這裡都不會遇上壞事，盡是好事。",
  str_voice_1601911_45 = "哦，就放著吧。",
  str_voice_1601911_46 = "禮物很好。",
  str_voice_1601911_47 = "應該說……謝謝。",
  str_voice_1601911_48 = "很棒的禮物，感謝你。",
  str_voice_1601911_49 = "我沒見過父親，他在我出生前就離世了，留下的這個掛墜盒是他唯一的信物……",
  str_voice_1601911_50 = "記憶中的母親總是很緊繃、很忙碌，那時的我總想博取她更多的關注。現在回想起來，那樣孩子氣的我，想必很不討大人的喜歡吧……",
  str_voice_1601911_51 = "我沒什麼朋友，也許因為我外表特殊的緣故吧。我不會主動傷害任何人，但厄運好像從不願離我而去。",
  str_voice_1601911_52 = "白夜極光。",
  str_voice_1601911_53 = "你也在啊。",
  str_voice_1601911_54 = "撓撓，趕快起床。",
  str_voice_1601911_55 = "午餐有燉肉嗎？",
  str_voice_1601911_56 = "晚餐有吃飽了嗎？",
  str_voice_1601911_57 = "新的一年，期待發生值得紀念的事情。",
  str_voice_1501931_1 = "哼～哼哼～果然自由的旋律才是最為優美靈動，那些被寫在樂譜上的旋律，不管唱多少次都是一樣的。",
  str_voice_1501931_2 = "因為有這把長槍存在，我才能不受動搖地懲處罪犯。",
  str_voice_1501931_3 = "我的家族在世界各處購置了莊園，您要與我一同去度假嗎？啊……不過得等到我的見習期結束後～",
  str_voice_1501931_4 = "長槍需要細心呵護，這樣它才能隨時維持自身的鋒芒。",
  str_voice_1501931_5 = "流水能奏出最美的音樂，在清脆的水流聲中，所有迷惘都將煙消雲散。",
  str_voice_1501931_6 = "在波濤中高歌吧，澎湃的力量將指引每一個自由的信徒——前往新浪潮的彼岸！",
  str_voice_1501931_7 = "我會彈奏多種樂器，只不過……還談不上熱愛。嗯，您覺得音樂家和審判官，哪個身分比較適合我呢？",
  str_voice_1501931_8 = "我很欣賞您的生活型態，自由且無拘束。或許有一天，我也能如您一樣去到世界的更多角落。",
  str_voice_1501931_9 = "我十分敬愛我的父母，但這不代表我願意接受他們安排的生活。至少截至目前，我不曾為我的選擇感到後悔。",
  str_voice_1501931_10 = "呼，突然就閒下來了，總覺得……有點無所適從呢。",
  str_voice_1501931_11 = "有新的工作嗎？啊，我只需要待在這裡嗎？呵呵，對我來說，守候在您身邊也是重要的工作哦～",
  str_voice_1501931_12 = "我按照書本所寫的教程來處理經手的案件，仍無法解決所有問題。果然我還有很多可以學習的啊～",
  str_voice_1501931_13 = "說起來，我已經很久沒去觀看歌劇演出了，不曉得最近有沒有新的流行劇目呢……",
  str_voice_1501931_14 = "為什麼盯著我看？難道我的衣著凌亂了……嗯，沒有問題呀，大概是我過度敏感了吧，請別介意。",
  str_voice_1501931_15 = "生～日～快～樂～這是我自創的曲調哦，好聽嗎？",
  str_voice_1501931_16 = "需要我幫忙嗎？不過得先等我整理完這個案件，請稍候哦～",
  str_voice_1501931_17 = "振作起來，太陽都曬屁股啦！您再不醒來，小鳥都要在您頭上築巢了！",
  str_voice_1501931_18 = "嗯，現在是一天當中最該放鬆的時候啦～我來為您播放音樂吧？",
  str_voice_1501931_19 = "很晚囉，找我有什麼急事嗎？咦？難道……您只是餓了？",
  str_voice_1501931_20 = "白夜城中有些貴族認為不該接近平民，但我認為這個想法很傲慢。",
  str_voice_1501931_21 = "影鎮是和白夜城完全不一樣的存在，不過我想我喜歡這裡。",
  str_voice_1501931_22 = "白夜至上。",
  str_voice_1501931_23 = "暗鬼簡直就是混亂的象徵，牠們或多或少都犯過幾條罪行。",
  str_voice_1501931_24 = "澤納斯曾經教授我武藝，作為一個老師，他很值得欽佩。",
  str_voice_1501931_25 = "馬太先生有時會莫名盯著我看，難道是我的小調影響了他嗎？",
  str_voice_1501931_26 = "我喜歡形狀方正的物體，因為可以擺放得整整齊齊，這個時刻十分療癒！",
  str_voice_1501931_27 = "罪犯是世上最令人厭惡的存在，正因如此，我必當秉持正義而行動。",
  str_voice_1501931_28 = "巨像真的十分壯觀，不過一個人待在這裡不會感到寂寞嗎？",
  str_voice_1501931_29 = "我是克莉絲汀，身為一名見習審判官，我正在學習更有效的工作方法。若有突發案件，您當然也可以向我求助哦？",
  str_voice_1501931_30 = "您期待我變得更強大嗎？",
  str_voice_1501931_31 = "湍流正在暗湧。",
  str_voice_1501931_32 = "黎明終將到來——",
  str_voice_1501931_33 = "湍流將會席捲一切！",
  str_voice_1501931_34 = "已準備就緒！",
  str_voice_1501931_35 = "長槍已擦亮。",
  str_voice_1501931_36 = "想體驗長槍的威力嗎？",
  str_voice_1501931_37 = "逆流而上！",
  str_voice_1501931_38 = "湍流嘯空！",
  str_voice_1501931_39 = "流水之舞！",
  str_voice_1501931_40 = "洶湧吧！",
  str_voice_1501931_41 = "水流會掃除所有障礙。",
  str_voice_1501931_42 = "正義必勝！",
  str_voice_1501931_43 = "最近有點怠惰呢……",
  str_voice_1501931_44 = "請跟我分享幾樁與巨像有關的趣事吧～我會認真聆聽！",
  str_voice_1501931_45 = "謝謝，挺不錯的禮物。",
  str_voice_1501931_46 = "是我喜歡的，謝謝您。",
  str_voice_1501931_47 = "這是份用心的禮物，我會珍藏起來。",
  str_voice_1501931_48 = "我很喜歡，要怎麼感謝您才好呢？",
  str_voice_1501931_49 = "聲樂老師認為我天生有著好嗓音，勢將成為著名的歌唱家。但我不喜歡嚴格教育，也不喜歡那些重複的曲調。",
  str_voice_1501931_50 = "就讀於學院時，我時常替同學們調解紛爭。漸漸地，我成為大家眼中「公證人」一般的存在。",
  str_voice_1501931_51 = "畢業後，我如願以償成為了一名見習審判官。工作比預想得還要苛刻，但我會繼續努力！",
  str_voice_1501931_52 = "白夜極光～",
  str_voice_1501931_53 = "您好！",
  str_voice_1501931_54 = "早安！有睡好嗎？",
  str_voice_1501931_55 = "午安，多麼美妙的一天。",
  str_voice_1501931_56 = "今天的工作結束了。",
  str_voice_1501931_57 = "新年快樂！希望我們在新的一年都有更多收穫。",
  str_voice_1601921_1 = "用劍來開疆拓土，用手來撫慰民心。可惜啊，總有人把它弄反了。",
  str_voice_1601921_2 = "我習慣把軍旗披在身上，只要團員們還能在戰場上看到我，他們就知道這一戰能贏。",
  str_voice_1601921_3 = "巨像如此宏偉，或許應該為它設立一面旗幟，展現它的力量和榮耀。",
  str_voice_1601921_4 = "如果你對戰場有什麼想瞭解的，可以隨時來找我。別害怕接受指導，要成長總是需要一個導師。",
  str_voice_1601921_5 = "提醒你一下，要時常檢查巨像的物資，如果不及時補充，有可能會發生不必要的麻煩。",
  str_voice_1601921_6 = "我的目標一直很明確，我想成為一個能夠保護人民的勇士，為和平而戰。",
  str_voice_1601921_7 = "昨晚落枕了？我來幫你，好了。這沒什麼，我還幫團員吸過傷口的毒素。",
  str_voice_1601921_8 = "你這一臉天真的樣子很像我的團員，讓我忍不住想保護你。不過我不會這麼做，因為你需要獨立成長。小心！看路。",
  str_voice_1601921_9 = "如果我有什麼地方做得不對，請直接告訴我。朋友之間不能有隔閡，只有相互坦誠交流，才能讓友誼更加牢固。",
  str_voice_1601921_10 = "遇到難題時別猶豫，就交給我來解決吧，我有足夠的智慧和勇氣。",
  str_voice_1601921_11 = "想讓我在這裡駐守？沒問題，絕對不會出差錯。",
  str_voice_1601921_12 = "遇到什麼難題了？我會盡力幫你解決。哦，是衣服破了，交給我吧，我經常幫團員縫衣服。",
  str_voice_1601921_13 = "學習新技能是一件很好的事情，不要害怕失敗。只要你堅定自己的信念，持之以恆地努力，一定會成功的。",
  str_voice_1601921_14 = "想要取得勝利並不難，抓住對手的弱點，並利用它們就可以了。",
  str_voice_1601921_15 = "又成長了一些，願你的未來充滿了創造力與奇蹟。",
  str_voice_1601921_16 = "今天的工作進度如何？需要我的幫忙嗎？",
  str_voice_1601921_17 = "今天的計畫安排好了嗎？希望一切都在你的掌握之中。",
  str_voice_1601921_18 = "今天的事情都忙完了嗎？",
  str_voice_1601921_19 = "夜深了，好好休息，別讓疲憊的身體影響你的效率。",
  str_voice_1601921_20 = "白夜城，到了應該改變的時候了。",
  str_voice_1601921_21 = "啟光有一些戰士很不錯，適合加入我的鐵棘騎士團。",
  str_voice_1601921_22 = "鐵棘騎士團！",
  str_voice_1601921_23 = "哪怕只剩最後一口氣，也要將暗鬼盡數消滅。",
  str_voice_1601921_24 = "若瑟總是充滿悲憫和寬容，是白夜要塞和平民之間重要的黏合劑。",
  str_voice_1601921_25 = "卡蓮殿下和腐朽的貴族不一樣，她也許會成為一道照耀白夜城的光。",
  str_voice_1601921_26 = "擁有一把好用的武器將對戰鬥大有裨益。",
  str_voice_1601921_27 = "好色之徒的目光往往只看到表面，缺乏對內心真正的關懷與欣賞。",
  str_voice_1601921_28 = "雄偉且精巧，這是奇蹟之作。",
  str_voice_1601921_29 = "鐵棘騎士團團長李奧，接受你的指揮。在戰鬥中，冷靜和果斷是勝利的關鍵，希望你不會讓我失望。",
  str_voice_1601921_30 = "發揮潛力。",
  str_voice_1601921_31 = "決不放棄。",
  str_voice_1601921_32 = "不會猶豫。",
  str_voice_1601921_33 = "堅不可摧。",
  str_voice_1601921_34 = "出擊。",
  str_voice_1601921_35 = "準備就緒。",
  str_voice_1601921_36 = "隨時待命。",
  str_voice_1601921_37 = "致命一擊。",
  str_voice_1601921_38 = "劍如閃電。",
  str_voice_1601921_39 = "全軍衝鋒！",
  str_voice_1601921_40 = "統御八方！",
  str_voice_1601921_41 = "聽我指揮。",
  str_voice_1601921_42 = "痛快的戰鬥。",
  str_voice_1601921_43 = "保持冷靜。",
  str_voice_1601921_44 = "我想要守護這裡。",
  str_voice_1601921_45 = "謝謝。",
  str_voice_1601921_46 = "你很有眼光。",
  str_voice_1601921_47 = "感謝你的禮物。",
  str_voice_1601921_48 = "你很瞭解我。",
  str_voice_1601921_49 = "雖然我曾經是白夜城貴族的一員，但實際上我從來就不是真正的貴族，在我被流放之前就不是。",
  str_voice_1601921_50 = "家道中落後，我被流放到了黃昏鎮，成了邊陲小鎮裡一個寂寂無名的平民。",
  str_voice_1601921_51 = "我組建了鐵棘騎士團，吸納了黃昏鎮大部分遠征騎士。數次擊敗暗鬼了之後，鐵棘騎士團的威名傳遍了整個黃昏鎮。",
  str_voice_1601921_52 = "白夜極光。",
  str_voice_1601921_53 = "你好。",
  str_voice_1601921_54 = "有失遠迎。",
  str_voice_1601921_55 = "進展還順利嗎？",
  str_voice_1601921_56 = "早點休息。",
  str_voice_1601921_57 = "新年快樂！讓我們一起迎接全新的未來，勇往直前，充滿自信。",
  str_voice_1601991_1 = "我大部分的時間都待在戰備室中，這是因為工作需要。不過在沉悶狹窄的環境中待久了，不由得會嚮往那片純粹的藍色天空。",
  str_voice_1601991_2 = "在獨自思考時，我會想像與對手博弈的場景，對方可以是陌生人，也可以是我自己。",
  str_voice_1601991_3 = "藍波是一隻仙鶲，牠會像這樣乖乖地飛到我的指尖，十分通人心意。這些年，牠一直陪伴在我的身邊。",
  str_voice_1601991_4 = "我不會輕易架起狙擊槍，但只要用它瞄準了敵人，唯一的結果將會是「正中目標」。",
  str_voice_1601991_5 = "計畫就如同一場棋局，每一次落子都會影響下一步計畫的實施，因此好的計畫總是有著高容錯率。",
  str_voice_1601991_6 = "射擊時需要全身貫注，注意，不能喘氣，呼吸會影響射擊的結果。學會了這點，你也能成為一名好狙擊手。",
  str_voice_1601991_7 = "你問我委員會的工作是不是機械又枯燥？在許多人眼中或許是如此，然而對我而言，「計畫」是一件有趣的事情。",
  str_voice_1601991_8 = "有時候我會覺得藍波就像我一樣。順從或脆弱只是表象，在那小小的心臟中跳動著的，還有一點勇敢與倔強。",
  str_voice_1601991_9 = "我們的過去十分相似，既是孤獨的個體，又有著未盡的職責，所以我能夠理解你的感受。假如可以的話，我願意成為你的聆聽者。",
  str_voice_1601991_10 = "累了嗎？偶爾放空一下有助於轉換思路。但假如感到疲倦的話，就該好好休息一下了。",
  str_voice_1601991_11 = "與你一起分享同樣的景色，這種感覺也不錯。",
  str_voice_1601991_12 = "危機不過是讓我們有重整旗鼓的機會，冷靜下來才能找到問題的源頭。",
  str_voice_1601991_13 = "每個人都有著自己堅守的原則，而我的原則是「整體優先」。當出現多個需要權衡的變數時，這時候需要注重的便是對整體的影響。",
  str_voice_1601991_14 = "敵人的反擊或是防守都會傳達出關於他們自身的資訊，因此，每一次進攻都是有意義的。",
  str_voice_1601991_15 = "千萬不要把生日願望說出來喔。總之，生日快樂！",
  str_voice_1601991_16 = "找我有什麼事嗎？或者應該說……很高興見到你。",
  str_voice_1601991_17 = "早安，我剛整理好著裝，今天的我看起來怎麼樣？",
  str_voice_1601991_18 = "傍晚可以看到淡粉色的晚霞，要不要一起去散步？",
  str_voice_1601991_19 = "時間不早了，但碰巧，我還醒著。",
  str_voice_1601991_20 = "啟光研究的所有新科技，都是為了保護民眾而存在的。",
  str_voice_1601991_21 = "紅油扳手的紀律實在是過於散漫，他們應該更重視組織性一點。",
  str_voice_1601991_22 = "為了啟明之光。",
  str_voice_1601991_23 = "只要想到許多民眾還在忍受暗鬼的騷擾，我就想更努力地工作。",
  str_voice_1601991_24 = "阿克希亞是個缺乏關愛的孩子，這也讓她並不能理解真正的情感。",
  str_voice_1601991_25 = "單純並不是一件壞事，至少對西恩來講，這顯得格外可愛。",
  str_voice_1601991_26 = "我喜歡香甜的乳酪，還有新鮮的牛奶，嗯……是不是太普通了？",
  str_voice_1601991_27 = "我討厭碳酸飲料對喉嚨的刺激，有時會無法控制地打嗝。",
  str_voice_1601991_28 = "巨像的存在證明了科技的可能性，不覺得這背後有思考的空間嗎？",
  str_voice_1601991_29 = "我是鶯歌，作為啟光的科學首席議會情報官，我可以為你提供在戰場上對敵的策略，前提是——你將我視作值得信賴的同伴。",
  str_voice_1601991_30 = "這也是計畫的一部分。",
  str_voice_1601991_31 = "嗯……要小心走火。",
  str_voice_1601991_32 = "這就是改良後的子彈嗎？",
  str_voice_1601991_33 = "無需再猶豫了。",
  str_voice_1601991_34 = "我就在這裡。",
  str_voice_1601991_35 = "子彈已上膛。",
  str_voice_1601991_36 = "目標已鎖定。",
  str_voice_1601991_37 = "清脆的一擊！",
  str_voice_1601991_38 = "完美的一擊！",
  str_voice_1601991_39 = "連續發射！",
  str_voice_1601991_40 = "精準操控！",
  str_voice_1601991_41 = "我很擅長「指揮」這件事。",
  str_voice_1601991_42 = "一切都在「計畫」之中。",
  str_voice_1601991_43 = "看來需要重新擬定計畫了……",
  str_voice_1601991_44 = "我會讓藍波飛行時小心一點，以免弄亂你的巨像。",
  str_voice_1601991_45 = "送我的嗎？謝謝。",
  str_voice_1601991_46 = "你費心了，我很喜歡。",
  str_voice_1601991_47 = "我會把它視作你對我的認可。",
  str_voice_1601991_48 = "我會把它與戰利品共同珍藏起來。",
  str_voice_1601991_49 = "我的父母在上戰場前，將四歲的我託付給了尤利西斯教授。不久後噩耗傳來，他們已為啟光奉獻出了生命。",
  str_voice_1601991_50 = "我曾聽到過無數褒獎，但那些溢美之詞並不只是代表簡單的認同，而是代表著他們的期待——希望我能夠肩負起啟光的未來。",
  str_voice_1601991_51 = "作為通過考核的獎勵，教授送給了我一隻仙鶲，我將牠取名為藍波。我知道，這並非是純粹的獎勵，還有著提醒的意思……",
  str_voice_1601991_52 = "白夜極光。",
  str_voice_1601991_53 = "你好。",
  str_voice_1601991_54 = "早安，睡得好嗎？",
  str_voice_1601991_55 = "PlayerName，午安。",
  str_voice_1601991_56 = "嗯，不知不覺又到這個時候了。",
  str_voice_1601991_57 = "新年快樂，希望明年的此刻，我也能夠見到你。",
  str_voice_1502001_1 = "生物是資訊的集合體。只要擁有足夠的情報，就可以分析出一個生物的行為模式和動機，甚至做出一定程度的預測。",
  str_voice_1502001_2 = "嗯……嗯？你叫我嗎？不，我沒有睡著，只是在觀察你和這座巨像上的其他人。",
  str_voice_1502001_3 = "空裔有著光靈所不具備的感應能力，這種能力不僅能為戰鬥提供幫助，在收集情報的方面，似乎也能提供不小的幫助。",
  str_voice_1502001_4 = "別被現有的情報迷惑了。作為情報官，我很少參與戰鬥，但並不代表我不擅長戰鬥。",
  str_voice_1502001_5 = "對於情報官而言，不必要的戰鬥應該盡量避免。但這如果是你的委託，那我也不會推辭。",
  str_voice_1502001_6 = "想必你也知道了我的能力與極限……那麼，就請作為指揮者的你盡情地對我發號施令吧，我會為你帶回通向勝利的情報。",
  str_voice_1502001_7 = "道聼塗説的消息不能作為情報，需要經過驗證……我也是在真正與你相遇後，才逐漸開始瞭解你是個怎樣的人。",
  str_voice_1502001_8 = "在戰場上，有種東西比情報和裝備更為重要，那就是信任。過去的我作為偵察兵獨來獨往，並不理解信任的含義，但現在不同了。",
  str_voice_1502001_9 = "你想看我的筆記本？嗯……只能看不涉及啟光機密的部分，不能對外人透露筆記的內容，塗鴉也不行。",
  str_voice_1502001_10 = "PlayerName去休息了嗎？那我就用這段閒置時間整理剛剛收集到的情報吧。",
  str_voice_1502001_11 = "助手嗎……我並沒有任何經驗，但如果您能詳細告訴我關於這份工作的情報，我一定會盡力而為。",
  str_voice_1502001_12 = "這是我養的魚，牠叫「泡泡」，是在靠近暗面的沼澤裡撿到的。你可以摸摸牠，放心，牠只是普通的生物，並不危險。",
  str_voice_1502001_13 = "請不要亂動我的筆記本，它不僅是記錄情報的工具，也是我的武器。",
  str_voice_1502001_14 = "「凡是走過，必留痕跡」。不管怎樣掩蓋，情報都不會憑空消失，只是需要更仔細地觀察才能發現而已。",
  str_voice_1502001_15 = "根據情報，今天是您的生日。祝您生日快樂。其他知道這個情報的人，一定也滿懷祝福地等待著您吧。",
  str_voice_1502001_16 = "歡迎回來。情報已經整理完畢，工作行程也都安排好了，請過目。",
  str_voice_1502001_17 = "早安。看起來你是個熱愛工作的人。",
  str_voice_1502001_18 = "晚安。快到休息時間了，不必強迫自己工作，放鬆一下也未嘗不可。",
  str_voice_1502001_19 = "這麼晚了……你還沒休息嗎？",
  str_voice_1502001_20 = "啟光聯邦是一個為了讓所有人幸福而存在的地方，至少我是這麼想的。",
  str_voice_1502001_21 = "北境同樣靠近暗面，但那裡有群山和燈塔庇護，和平又安逸，令人羡慕。",
  str_voice_1502001_22 = "為了啟明之光。",
  str_voice_1502001_23 = "不論在哪裡，暗鬼都是帶來麻煩與危險的生物，請務必小心。",
  str_voice_1502001_24 = "大元帥是一個可靠的領導者，這是我觀察後得出的結論。",
  str_voice_1502001_25 = "我偶爾也想向巴頓軍團長抱怨兩句，希望他能再冷靜一點。",
  str_voice_1502001_26 = "我喜歡養魚很出乎你意料嗎？嗯，這就是資訊不對等。",
  str_voice_1502001_27 = "盲目的信仰並非好事，它會影響指揮者的決斷。",
  str_voice_1502001_28 = "關於巨像的情報在啟光並不多見……能允許我四處看看嗎？",
  str_voice_1502001_29 = "空裔一族，駕駛能夠飛行的巨像……看來就是你沒錯了。啟光聯邦情報官阿納托利，樂意為你效勞。請下達命令吧。",
  str_voice_1502001_30 = "累積作戰經驗也是收集情報的一種方式。",
  str_voice_1502001_31 = "情報準確度提升。",
  str_voice_1502001_32 = "新的作戰方案擬定完畢。",
  str_voice_1502001_33 = "隨時可以執行作戰計畫。",
  str_voice_1502001_34 = "瞭解。",
  str_voice_1502001_35 = "新戰術，規劃完畢。",
  str_voice_1502001_36 = "隨時待命。",
  str_voice_1502001_37 = "打亂敵人的陣型。",
  str_voice_1502001_38 = "微光，潛於暗影。",
  str_voice_1502001_39 = "弱點是這裡。",
  str_voice_1502001_40 = "現在就是機會。",
  str_voice_1502001_41 = "遵命。",
  str_voice_1502001_42 = "意料之中的勝利。",
  str_voice_1502001_43 = "情報有誤，暫時撤退。",
  str_voice_1502001_44 = "不用在意我，我只是在觀察其他人，收集情報。",
  str_voice_1502001_45 = "謝謝你的禮物。",
  str_voice_1502001_46 = "你……特地研究過我的喜好嗎？",
  str_voice_1502001_47 = "在你選擇給別人的禮物時，這些物品也會反映出你自己的品味與喜好。",
  str_voice_1502001_48 = "謝謝，這份禮物我很喜歡。",
  str_voice_1502001_49 = "沒有人是天生的情報官，我也是從偵察兵開始一點點累積經驗、磨練自己，最終才成為這樣的。",
  str_voice_1502001_50 = "養魚是一件很花時間的事，需要定時餵食、清理魚缸裡的綠藻，並且要隨時注意魚的健康狀態……不過泡泡的生命力一直很頑強，或許是因為牠曾經在永夜生活過吧。",
  str_voice_1502001_51 = "不管是普通的士兵還是情報官，信任某個人都代表著他們願意將背後甚至生命託付給對方。",
  str_voice_1502001_52 = "白夜極光。",
  str_voice_1502001_53 = "你好，PlayerName。",
  str_voice_1502001_54 = "早安。",
  str_voice_1502001_55 = "午安。",
  str_voice_1502001_56 = "天黑了啊……",
  str_voice_1502001_57 = "新年快樂，PlayerName。新的一年裡，也請允許我在巨像上收集情報、為你提供幫助吧。",
  str_voice_1602011_1 = "我已經……很久沒穿過這種顏色的裙子了，看起來適合我嗎？嘿嘿，總覺得有點害羞呢。",
  str_voice_1602011_2 = "戰鬥……不一定要奪取敵人的性命，對吧？嗯，我明白。強大的戰士，才能選擇善良和寬容，我還遠遠不夠……",
  str_voice_1602011_3 = "哇，街上有好多人啊，大家在幹什麼呢……我會優先完成工作的！希望工作完成後，太陽還沒下山……",
  str_voice_1602011_4 = "小時候不論我怎麼努力，都只會感到失落、無力……現在，我只為了自己的目標而奮鬥，心裡輕鬆了不少呢。",
  str_voice_1602011_5 = "「頭銜」真是個奇妙的東西啊。既能給人沉重枷鎖，也能給人無限力量。可千萬不要迷失其中喔……",
  str_voice_1602011_6 = "如果以前的我，能像現在一樣勇敢……不，這樣的想法毫無意義。重要的是，守護眼前的珍視之物，對吧？",
  str_voice_1602011_7 = "我和以前已經不一樣了，既不會盲目自卑，也不會無法控制自己……真的喔！所以……可以更信賴我一點嗎？",
  str_voice_1602011_8 = "請、請不要總是幫我解圍。不，你沒給我添麻煩。只是，我想……應該由我來保護你才對……",
  str_voice_1602011_9 = "告訴你一個祕密，其實戰鬥的時候，我的手有時還是會顫抖呢。可以借一點勇氣給我嗎？……你的手，真溫暖啊。",
  str_voice_1602011_10 = "摘一束玫瑰～♪送給親愛的爸爸媽媽～♪……啊啊啊抱歉！太安靜了，我下意識就……嗚，果然我還是一個人……",
  str_voice_1602011_11 = "不著急，慢慢深呼吸，吸……呼……咳咳，沒問題，我能勝任這份工作的。請交給我吧……！",
  str_voice_1602011_12 = "不論誰說什麼，我都是卡蓮的姐姐。也是……約書亞的女兒。家人之間的紐帶，才不會被無聊的榮譽斬斷。",
  str_voice_1602011_13 = "我有一個……朋友，叫做芭芭雅嘎。她以前有點粗暴，但現在不會了。如果你有機會見到她，請不要害怕她，好嗎？",
  str_voice_1602011_14 = "練習的時候擦破膝蓋了，好痛啊……嗯？不、不，這點小傷不算什麼！我的眼角有淚光？嗚……才沒有……",
  str_voice_1602011_15 = "生日快樂。能夠慢慢長大，是一件很幸福的事情喔。",
  str_voice_1602011_16 = "有空就多出去走走吧，白天的街道真的很美。",
  str_voice_1602011_17 = "早安，真是個美好的早晨。要來杯早茶嗎？",
  str_voice_1602011_18 = "天漸漸變黑了呢……沒關係，我很習慣這種黑暗。",
  str_voice_1602011_19 = "哎呀，這麼晚了怎麼還在忙？……或許身負重任的人都是這樣吧。",
  str_voice_1602011_20 = "即使……今生只能仰望那個遙不可及的家，我也會盡全力守護它。",
  str_voice_1602011_21 = "影鎮是個好地方，真希望白夜城的人也能多看看這裡。",
  str_voice_1602011_22 = "白夜至上……哈哈，好令人懷念啊。",
  str_voice_1602011_23 = "……你討厭暗鬼嗎？那，向暗鬼轉變的光靈呢？",
  str_voice_1602011_24 = "卡蓮、媽媽……真希望我們可以永遠……不，算了。",
  str_voice_1602011_25 = "舒瓦茲這個姓氏並不重要。我，不會再活在他的陰影之下了。",
  str_voice_1602011_26 = "在午後街邊的小店裡，獨自捧著一杯騎士紅茶眺望街景……真美好。",
  str_voice_1602011_27 = "沒事，我可以自己處理所有事情，不會給任何人添麻煩的……",
  str_voice_1602011_28 = "這裡有好多人啊……既有我想見的人，也有我不想見的人呢。",
  str_voice_1602011_29 = "你好。讓我想想，該如何向你自我介紹呢……薇羅妮卡？不，果然還是叫我「蜜雅」吧。蜜雅，這就足夠了。",
  str_voice_1602011_30 = "不斷地練習……",
  str_voice_1602011_31 = "好像，抓住竅門了！",
  str_voice_1602011_32 = "我是騎士……我不柔弱！",
  str_voice_1602011_33 = "如果我能早點擁有這份力量……",
  str_voice_1602011_34 = "我會加油的……！",
  str_voice_1602011_35 = "我、我準備好了！",
  str_voice_1602011_36 = "請不要害怕……",
  str_voice_1602011_37 = "這就是我的力量！",
  str_voice_1602011_38 = "這就是真正的我！！",
  str_voice_1602011_39 = "命中吧！",
  str_voice_1602011_40 = "絕不手軟！",
  str_voice_1602011_41 = "大家……跟上我！",
  str_voice_1602011_42 = "贏、贏了……我們贏了！",
  str_voice_1602011_43 = "唔，還是不夠嗎……",
  str_voice_1602011_44 = "貴安，您近來如何？嘿嘿，好久沒這麼說過了。",
  str_voice_1602011_45 = "謝謝你。",
  str_voice_1602011_46 = "哎呀，這是……",
  str_voice_1602011_47 = "這次是什麼呢？",
  str_voice_1602011_48 = "只有你如此瞭解我……",
  str_voice_1602011_49 = "「薇羅妮卡」，白夜城主的長女……舒瓦茲家族的污點。這就是，這身裙裝所代表的過去。",
  str_voice_1602011_50 = "「芭芭雅嘎」……幽靈般的黑蜘蛛。她並沒有死去，而是與「蜜雅」融為一體，變成了現在的我。",
  str_voice_1602011_51 = "現在的我，依舊是「蜜雅」……也只能是「蜜雅」。但，這不是他人冠以的虛名，而是我自己選擇的道路。",
  str_voice_1602011_52 = "白夜極光。",
  str_voice_1602011_53 = "請問……",
  str_voice_1602011_54 = "紅茶真香啊……",
  str_voice_1602011_55 = "午安，我沒打擾到你吧……？",
  str_voice_1602011_56 = "那個，晚安……",
  str_voice_1602011_57 = "新年快樂。今年要珍惜，與重要之人相處的時光啊。",
  str_voice_1602021_1 = "下雨了，我的大女兒很喜歡雨天，喜歡在細雨中顫動的紫羅蘭花……我總是不懂她。",
  str_voice_1602021_2 = "遠瞰這偌大的白夜城，自問我能否對得起民眾的俯首？我需繼續勉勵自己，更好地治理這片象徵光明的土地。",
  str_voice_1602021_3 = "我還算是一個健談的人，不過能與我有交流機會的人並不多，而你算其中一個。",
  str_voice_1602021_4 = "暗鬼帶來了黑暗，但黎明就在不遠處——我會擊垮它們，直到一個不留。",
  str_voice_1602021_5 = "戰爭正在白熱化階段，越靠近勝利，越不能懈怠。",
  str_voice_1602021_6 = "強大是領袖必備的素質之一。我將會運用這份力量，帶領所有人走向戰爭的勝利。",
  str_voice_1602021_7 = "作為一個統治者，在紛亂的事務中梳理出思緒，是必要的習慣。",
  str_voice_1602021_8 = "我偏愛讀一些歷史書籍，若有一些古典文學的名作，我願意花費為數不多的閒暇時間去閱讀。",
  str_voice_1602021_9 = "有人認為我對孩子們過於嚴苛，但未來的路道阻且長，若希望他們能避免犯錯，也只有此舉能有一二用處。",
  str_voice_1602021_10 = "如此清閒的作風，難成大事。若我的責任感與你一樣，白夜城的諸多事務早就亂成一團了。",
  str_voice_1602021_11 = "管理此處這件小事，還需要我來分神嗎？",
  str_voice_1602021_12 = "卡蓮尚且幼小，已展現出了遠超年齡的聰明才智，雖然她或許不能理解，但作為父親，我是為她驕傲的。",
  str_voice_1602021_13 = "「進攻」當然大於「防守」，強烈的攻勢可以掃退所有膽怯的敵人，並且能讓你發現對方更多的弱點。",
  str_voice_1602021_14 = "十分遺憾，那些覬覦王座者，無一例外都走向了毀滅，或即將走向毀滅，而舒瓦茲家族的榮耀將永遠延續下去。",
  str_voice_1602021_15 = "生日快樂，這是我的祝福，也是白夜城的祝福。",
  str_voice_1602021_16 = "你來了？記得多巡視你的領地。",
  str_voice_1602021_17 = "來得還算早，和我共飲一杯茶吧。",
  str_voice_1602021_18 = "活動筋骨，放鬆一下思緒，對提升效率更有益。",
  str_voice_1602021_19 = "這個時候，我需要檢查一下明日的事務安排。",
  str_voice_1602021_20 = "在我的領導之下，白夜城將會走向更加繁榮與光明的未來。",
  str_voice_1602021_21 = "毫無異議，影鎮的安定與繁榮對白夜城會帶來好處。",
  str_voice_1602021_22 = "白夜，至上。",
  str_voice_1602021_23 = "暗鬼開始集結大軍進攻各方，這背後一定有藏於黑暗的謀劃者。",
  str_voice_1602021_24 = "是約書亞成就了我，而並非是我選擇了約書亞。",
  str_voice_1602021_25 = "只要將薇羅妮卡往正確的道路引導，她也能有所作為。",
  str_voice_1602021_26 = "每個光靈都應該嚮往熾熱的陽光，這也是我喜歡晴天的原因。",
  str_voice_1602021_27 = "在戰場上對敵人施以無謂的同情，何嘗不是對自己的殘忍？",
  str_voice_1602021_28 = "讓我在巨像上擺放一些歷史書籍，以助你瞭解白夜城的歷史。",
  str_voice_1602021_29 = "舒瓦茲家族會尊敬每個有智慧與謀略之人，你既然有不凡的本領，也就獲得了與我對話的資格。",
  str_voice_1602021_30 = "強大是權利的附庸。",
  str_voice_1602021_31 = "且待黎明之後。",
  str_voice_1602021_32 = "天色已然破曉。",
  str_voice_1602021_33 = "光明將引導白夜——",
  str_voice_1602021_34 = "正確的選擇。",
  str_voice_1602021_35 = "已蓄勢待發！",
  str_voice_1602021_36 = "還在等待什麼？",
  str_voice_1602021_37 = "暗夜破滅，長日無盡！",
  str_voice_1602021_38 = "光之所至，萬物皆明！",
  str_voice_1602021_39 = "白夜之光！",
  str_voice_1602021_40 = "主宰一切！",
  str_voice_1602021_41 = "我將率兵出征！",
  str_voice_1602021_42 = "勝利，理所應當。",
  str_voice_1602021_43 = "這次就饒過他們。",
  str_voice_1602021_44 = "不要小看這狹窄的一地，長明之光與未來，將從此處展開。",
  str_voice_1602021_45 = "嗯……那我便收下了。",
  str_voice_1602021_46 = "你想要什麼回禮？",
  str_voice_1602021_47 = "我會珍藏。",
  str_voice_1602021_48 = "我已擁有無數財富，但這份禮物是特別的。",
  str_voice_1602021_49 = "約書亞出身平民，舒瓦茲家族不允許我與她結合，但我認定了她，我願意為此付諸一切努力。",
  str_voice_1602021_50 = "成為人父這件事，甚至比我日後即位為執政官時帶給我的震撼更大，是我開始深刻地瞭解「責任」一詞意義之始。",
  str_voice_1602021_51 = "暗鬼的威脅破滅了曾經的和平，為了白夜城，為了手無縛雞之力的民眾們，為了我的家庭……我，必須要出征。",
  str_voice_1602021_52 = "白夜極光！",
  str_voice_1602021_53 = "可好？",
  str_voice_1602021_54 = "晨曦將洗禮一切。",
  str_voice_1602021_55 = "午時至，稍作休息。",
  str_voice_1602021_56 = "天色已晚。",
  str_voice_1602021_57 = "新的一年，記得來白夜城作客。",
  str_voice_1502031_1 = "根據你對這幾個占卜問題的回答……我確定你是一個開心時會大笑、饑餓時會肚子叫、疲憊時會很想睡覺的人！嗯？你說所有人都是這樣？",
  str_voice_1502031_2 = "巨像的顏色有點單調呢，不如我們來幫巨像畫上明亮豔麗的花紋吧～咦？為什麼不要啊？我不是在亂塗亂畫啦！",
  str_voice_1502031_3 = "嗨！你在幹嘛？咦咦？被我大聲的招呼嚇到了？為什麼呢？在做什麼見不得人的事情？哈哈我不會說出去喔～",
  str_voice_1502031_4 = "你沒休息好嗎？看起來有點睏睏呢，不然我跟你講個故事吧～《神祕洞穴吞噬活人》這種故事應該比較提神吧？",
  str_voice_1502031_5 = "像耶利亞一樣從容、像伯利恆一樣強大、像母親一樣聰明，這又不是什麼難以做到的事！",
  str_voice_1502031_6 = "你在玩什麼遊戲？很難嗎？我也來試試，我們一起的話肯定沒問題！",
  str_voice_1502031_7 = "聽說這個週末的市集會很熱鬧，有很多東西，真想去啊～等你有空的時候我們一起去吧～",
  str_voice_1502031_8 = "昨天有人邀請我參加一個聚會，不過你不在我就沒去了。雖然我很喜歡大家一起聚會，不過你不在的話好像就沒什麼意思了。",
  str_voice_1502031_9 = "我最近很忙喔，在做捕夢網，據說可以捕捉美麗的夢。用了好多種不同顏色的絲線製作呢～等做好了就送給你吧～",
  str_voice_1502031_10 = "上次沒能幫你占卜成功，我決定再免費幫你占卜一次。咦咦？為什麼不要啊？這次一定會成功的啦！",
  str_voice_1502031_11 = "嗨～我來陪你啦～如果不開心的話，我就為你講故事～",
  str_voice_1502031_12 = "我剛才在餐廳吃了超好吃的水果沙拉喔，紅色的草莓、橙色的橘子和黃色的鳳梨，簡直像調色盤一樣～",
  str_voice_1502031_13 = "你丟了一支筆？我來占卜一下，唔……應該就在東南方的櫃子裡喔！咦咦？沒找到嗎？",
  str_voice_1502031_14 = "上次我們在市集看到的那種五顏六色的東西是叫什麼來著？哦，對了，是氣球，真好看呢。",
  str_voice_1502031_15 = "哇～是你生日欸～讓我們辦一個超級熱鬧的派對吧～",
  str_voice_1502031_16 = "今天遇到了什麼好玩的事情嗎？一定要告訴我喔！",
  str_voice_1502031_17 = "早安！今天的任務很重要嗎？先讓我為你占卜一下吧～",
  str_voice_1502031_18 = "哎呀，天已經黑了，那就出去看看夜景吧。",
  str_voice_1502031_19 = "占卜書上說晚上的靈氣更盛，我決定通宵不睡啦！",
  str_voice_1502031_20 = "北境雖然有點冷，但也像童話世界一樣晶瑩夢幻呢。",
  str_voice_1502031_21 = "白夜城很漂亮，不過感覺好嚴肅喔，有種硬邦邦的感覺。",
  str_voice_1502031_22 = "暮冬而生。",
  str_voice_1502031_23 = "哎呀，要透過占卜完全避開暗鬼才行呐。",
  str_voice_1502031_24 = "耶利亞老師超級酷，又從容又強大，怎麼做才能變成她那樣呢？",
  str_voice_1502031_25 = "伯利恆女王好有氣勢，好美喔，每次看見她我都移不開眼睛。",
  str_voice_1502031_26 = "我最近又編了幾個很精彩的故事喔，你想聽嗎？",
  str_voice_1502031_27 = "怎麼會有人失約呢？真討厭呀。我就不會失約，頂多是……記錯時間吧，嘿嘿。",
  str_voice_1502031_28 = "巨像如果再大一點就好了，把所有人都裝進來，這樣就更熱鬧啦～",
  str_voice_1502031_29 = "卟呤卟呤——水晶球發光，神祕莫測的占卜師加晴登場，會展開怎樣的故事呢？敬請期待吧～",
  str_voice_1502031_30 = "呦呼～",
  str_voice_1502031_31 = "我很好～",
  str_voice_1502031_32 = "我真棒～",
  str_voice_1502031_33 = "我太厲害啦～",
  str_voice_1502031_34 = "大家好～",
  str_voice_1502031_35 = "準備占卜。",
  str_voice_1502031_36 = "占卜一下。",
  str_voice_1502031_37 = "水晶球球！",
  str_voice_1502031_38 = "罩起來啦～",
  str_voice_1502031_39 = "預言勝利。",
  str_voice_1502031_40 = "感知未來。",
  str_voice_1502031_41 = "看我的吧～",
  str_voice_1502031_42 = "占卜成功～",
  str_voice_1502031_43 = "占卜失敗……",
  str_voice_1502031_44 = "距離天空越近，占卜就會越準吧？",
  str_voice_1502031_45 = "嗯！謝謝！",
  str_voice_1502031_46 = "哇！這個禮物真棒！",
  str_voice_1502031_47 = "嘻嘻，又收到禮物了。",
  str_voice_1502031_48 = "天哪！我好喜歡喔！",
  str_voice_1502031_49 = "我的媽媽也是個占卜師喔，她超級厲害的呢！這本……占卜書？就是她留給我的啦。",
  str_voice_1502031_50 = "耶利亞是我的老師喔，你看我的小蛇幽呼是不是跟耶利亞老師的幽青巨蟒很像？唔……不像嗎？",
  str_voice_1502031_51 = "我最喜歡去的地方啊？以前是鏡湖、綠松之地、世界之脊……雖然人不多，但是大概也許可以探索光能術的奧祕呢。",
  str_voice_1502031_52 = "白夜極光。",
  str_voice_1502031_53 = "嗨～",
  str_voice_1502031_54 = "早安呀～",
  str_voice_1502031_55 = "中午最熱鬧了。",
  str_voice_1502031_56 = "呼嚕呼嚕快睡吧。",
  str_voice_1502031_57 = "又到了一年中最熱鬧、最快樂的時間，讓我們一起跳舞吧～歡笑吧～",
  str_voice_1602041_1 = "雖然有點捨不得白夜城的紅茶，但離開這裡之後，是不是也能在別的地方找到同樣香醇的紅茶呢？我已經開始期待了。",
  str_voice_1602041_2 = "天氣潮濕，感覺什麼都黏糊糊的。果然，我還是比較喜歡晴朗的天氣，一切都變得俐落起來～",
  str_voice_1602041_3 = "那孩子……你喚作「蜜雅」的那個孩子，似乎不擅長表露自己的心意。唯獨在你面前，她才會敞開心扉呢。",
  str_voice_1602041_4 = "這把劍很漂亮吧？要知道，這把劍可不是虛有其表。我會緊握著它，守護更多、更多的人。",
  str_voice_1602041_5 = "你覺得我的劍術更精進了？哈哈，我只不過是找回曾經的感覺罷了。畢竟以前即使是「那個人」跟我也難分高下呢。",
  str_voice_1602041_6 = "從以前到現在，我的心願一直都是「守護大家」。不只是我的家人、不只是那些故鄉的朋友……",
  str_voice_1602041_7 = "一些舒緩的輕音樂，可以讓氣氛輕盈起來。下次與客人會談的時候，不如播放幾首試試看吧？",
  str_voice_1602041_8 = "我啊，最喜歡大家的笑容了。PlayerName也要多笑一笑喲，愛笑的孩子會更加幸運的～",
  str_voice_1602041_9 = "外面的世界果然與白夜城迥然不同。下一次又要去哪裡旅行呢？PlayerName有什麼推薦的地方嗎？",
  str_voice_1602041_10 = "來一杯蜂蜜水吧！有助於緩解疲勞。不可以不喝唷，乖孩子應該要聽「大人」的話。",
  str_voice_1602041_11 = "雖然我擅長打理，不過管理巨像……還沒有什麼經驗。不過既然是你的請求，我身為長輩一定會好好學習的。",
  str_voice_1602041_12 = "即使這個世界看起來如此殘破不堪，但總有人在努力讓它變得美好，我相信，你也是其中一個。",
  str_voice_1602041_13 = "作母親唯一的希望，不過是看著年幼的孩子們可以從自己的掌心，飛向更廣闊的天空。你已經做到了，我替你的母親感到驕傲。",
  str_voice_1602041_14 = "過去的一切就像是場特別的旅程，我曾在旅途中停靠過一些車站，不過看完風景後，就該重新出發了。",
  str_voice_1602041_15 = "PlayerName一定能成為更加帥氣的孩子，生日快樂唷～",
  str_voice_1602041_16 = "鼓足幹勁，好好工作吧！",
  str_voice_1602041_17 = "早安，吃過早餐了嗎？",
  str_voice_1602041_18 = "晚上不要喝紅茶唷，會失眠的。",
  str_voice_1602041_19 = "夜深了，別累壞了，好好照顧自己。",
  str_voice_1602041_20 = "我深愛著白夜城的大家，所以我……才決定暫時先離開這裡。",
  str_voice_1602041_21 = "紅油扳手，聽起來像個很有意思的地方呢～",
  str_voice_1602041_22 = "白夜至上。",
  str_voice_1602041_23 = "與其說厭惡暗鬼，不如說我是痛恨那些肆意妄為的邪惡行徑。",
  str_voice_1602041_24 = "「那個人」這些年也變了不少呢。歲月在他身上留下了深刻的印記……",
  str_voice_1602041_25 = "卡蓮已經可以獨當一面了。那孩子比我想像中堅強，我感到很欣慰。",
  str_voice_1602041_26 = "我喜歡整理房間，潔淨的環境可以療癒心靈。",
  str_voice_1602041_27 = "我討厭的東西……要說的話，應該是香菜，聞起來怪怪的呢。",
  str_voice_1602041_28 = "巨像雖然壯觀，不過要是能多增添一些溫馨的裝飾，會更有生活氣息。",
  str_voice_1602041_29 = "噓，千萬別再叫我「城主夫人」了。我們不是說好要保密嗎？從現在起，叫我「約書亞」就好，記住了嗎？",
  str_voice_1602041_30 = "變得更強了～",
  str_voice_1602041_31 = "嗯，好像回想起了什麼。",
  str_voice_1602041_32 = "體內的力量正在湧動……",
  str_voice_1602041_33 = "劍，是為了保護大家而存在的！",
  str_voice_1602041_34 = "一起加油。",
  str_voice_1602041_35 = "劍光已至。",
  str_voice_1602041_36 = "聖裁之光！",
  str_voice_1602041_37 = "聖理將給予我們指引。",
  str_voice_1602041_38 = "聖理之光，榮膺之斬！",
  str_voice_1602041_39 = "劍花繚亂！",
  str_voice_1602041_40 = "淩光劍舞！",
  str_voice_1602041_41 = "那就由我帶領大家。",
  str_voice_1602041_42 = "付出總會得到回報。",
  str_voice_1602041_43 = "再努力一次吧。",
  str_voice_1602041_44 = "偶爾像這樣舒展一下身體，可以放鬆身心唷～",
  str_voice_1602041_45 = "那我……就收下了。",
  str_voice_1602041_46 = "這份禮物很用心唷。",
  str_voice_1602041_47 = "是份可愛的禮物呢。",
  str_voice_1602041_48 = "這份禮物……真令人驚喜～",
  str_voice_1602041_49 = "偉大的理想，讓我可以有攀登、靠近天空的勇氣。懦弱者總是會原地踏步，而我，不願沉迷於自我懷疑之中。",
  str_voice_1602041_50 = "大貴族與平民的愛情本不受任何人看好，而我不希望他日後的治國之路會因此受到更多阻力。",
  str_voice_1602041_51 = "有機會的話，我希望可以去看看她的墳墓。畢竟我們之間似乎有一條無形的線——沒錯，是緣分將我們聯繫在一起。",
  str_voice_1602041_52 = "白夜極光。",
  str_voice_1602041_53 = "你好～",
  str_voice_1602041_54 = "早安～",
  str_voice_1602041_55 = "午安。",
  str_voice_1602041_56 = "不早了唷～",
  str_voice_1602041_57 = "新年快樂！新的一年，你也要好好加油唷～",
  str_voice_1502051_1 = "在紅油沙漠曬黑了？皮膚可是要精心呵護的呢，就讓我帶您去做全身美白水療吧～",
  str_voice_1502051_2 = "為了成為全天候提供服務的引路人，我已經把睡眠也給進化掉了。無論什麼時候都可以為您服務。",
  str_voice_1502051_3 = "陪伴的意思就是——只要您需要我，我會第一時間出現在您面前。",
  str_voice_1502051_4 = "想參加舞會嗎？與您共舞應該很有意思，不過在此之前，我要先去準備一條新裙子。",
  str_voice_1502051_5 = "情緒波動會影響我的守護任務，而紅茶可以幫我穩定心緒。來，我幫您也泡好了一杯。",
  str_voice_1502051_6 = "晚上的城市總是危機四伏，但您不用擔心，我的任務就是守護您的安全。",
  str_voice_1502051_7 = "白夜城時時刻刻都有獨特的美景，請讓我陪伴您暢遊白夜城吧。",
  str_voice_1502051_8 = "完美執行任務是我的信條。這表示我無論何時都必須保持冷靜，就算和您在一起的時候也一樣。",
  str_voice_1502051_9 = "如果只能穿一件衣服入睡，那麼我會選擇香水。您為什麼露出驚訝的表情？對這個答案很意外？還是您不喜歡我今天的香味？",
  str_voice_1502051_10 = "年輕的男孩子也應當有自己的時髦單品，我可以幫您選出完美的搭配唷。",
  str_voice_1502051_11 = "守護您的旅途是我的責任與榮耀，我會全心全意為您服務。",
  str_voice_1502051_12 = "想聽最新的傳聞嗎？我可是掌握著獨家的情報來源喲。",
  str_voice_1502051_13 = "身為引路人，我會一直在您身邊，確保您安全抵達目的地。",
  str_voice_1502051_14 = "每當換上新衣服，彷彿整個人都煥然一新，過往的事情就可以都拋諸腦後了吧。",
  str_voice_1502051_15 = "年輕真好，還喜歡慶祝生日。那就祝您永遠年輕吧。",
  str_voice_1502051_16 = "今天不需要我陪同嗎？有點擔心呢，看您的樣子總覺得會迷路。",
  str_voice_1502051_17 = "新的一天開始了呢，今天有什麼安排嗎？我已經為您列好了觀光計畫表。",
  str_voice_1502051_18 = "我不打算睡覺，這個時間點對我來說還早，天還沒亮呢。",
  str_voice_1502051_19 = "晚上是個美妙的時刻，您是否也和我一樣喜歡在夜晚執行任務呢？",
  str_voice_1502051_20 = "有人說白夜城是金玉其外、敗絮其中，但無論如何，我都必須守護白夜城。",
  str_voice_1502051_21 = "影鎮是個有趣的地方，看似一片混亂，實際上暗藏著屬於那裡獨特的秩序和規則。",
  str_voice_1502051_22 = "白夜至上。",
  str_voice_1502051_23 = "曾經讓我「死」過一次的暗鬼，這次我不會讓牠們活著離開。",
  str_voice_1502051_24 = "如果問我有什麼心願，除了守護白夜城，就只有找到她了。",
  str_voice_1502051_25 = "娜汀是個好學的孩子，工作時那認真的模樣，還真是有點像我呢。",
  str_voice_1502051_26 = "在夜晚的街道上漫步，聞著香氣四溢的咖啡和紅茶，是我最喜歡的放鬆方式。",
  str_voice_1502051_27 = "不遵守秩序的傢伙，會對我們的遊覽體驗帶來很多麻煩呢。",
  str_voice_1502051_28 = "這麼大的傢伙，想要引導牠的方向可不容易呢。",
  str_voice_1502051_29 = "您好，我是引路人白蘭，您也可以叫我白夜城的守護者。我會完美執行任務，務必滿足您所有的需求。",
  str_voice_1502051_30 = "漂亮。",
  str_voice_1502051_31 = "噴灑香水。",
  str_voice_1502051_32 = "換上裙子。",
  str_voice_1502051_33 = "參加舞會。",
  str_voice_1502051_34 = "都到齊了嗎？",
  str_voice_1502051_35 = "任務完成。",
  str_voice_1502051_36 = "暗夜守護。",
  str_voice_1502051_37 = "送您個見面禮。",
  str_voice_1502051_38 = "竭誠為您服務。",
  str_voice_1502051_39 = "最佳組合。",
  str_voice_1502051_40 = "強強聯手。",
  str_voice_1502051_41 = "請大家跟我來。",
  str_voice_1502051_42 = "輕鬆的行程。",
  str_voice_1502051_43 = "有點累了呢……",
  str_voice_1502051_44 = "我可以坐在這裡欣賞一整晚的美景。",
  str_voice_1502051_45 = "感謝您的認可。",
  str_voice_1502051_46 = "我正好想要這個。",
  str_voice_1502051_47 = "心意無價。",
  str_voice_1502051_48 = "眼光不錯，很適合我。",
  str_voice_1502051_49 = "年紀大了以後，最有面子的並不是擁有很多新衣服，而是還能穿上十幾年前的舊衣，這意味著身材保持如初。",
  str_voice_1502051_50 = "您問我為什麼自稱「白夜城的守護者」？這可不是我自封的，這叫命中注定。",
  str_voice_1502051_51 = "我沒有遇到什麼困難，只是在確認自己的妝容罷了，是的，從暗鬼的瞳孔裡確認。",
  str_voice_1502051_52 = "白夜極光。",
  str_voice_1502051_53 = "您好。",
  str_voice_1502051_54 = "咖啡還是紅茶？",
  str_voice_1502051_55 = "今天想去哪裡？",
  str_voice_1502051_56 = "如果睡不著可以找我。",
  str_voice_1502051_57 = "恭喜您踏入新的一年，希望今年也能順利完成所有任務。",
  str_voice_1602061_1 = "嗨～我帶了一份水果給你，據說是新研發的品種，不確定好不好吃，嚐鮮看看吧～",
  str_voice_1602061_2 = "別放棄追夢！每個人都有自己的夢想，但是只有有勇氣實現夢想的人，才能獲得成功。",
  str_voice_1602061_3 = "啊，這裡的咖啡真的好棒啊！我喜歡嘗試不同地方的風味，這讓我覺得生活總是充滿新鮮和刺激。",
  str_voice_1602061_4 = "我覺得創業真的很有意思，雖然有時會遇到困難和挫折，但那種成就感和自由感是無與倫比的。",
  str_voice_1602061_5 = "呼，感覺有點累了，來杯果汁吧，這個口味還沒喝過，我喜歡這種嚐鮮的感覺～",
  str_voice_1602061_6 = "你問我怎麼經營那麼大的企業？我的經營理念很簡單：要不做到最好，要不不做。凡事都不應半途而廢。",
  str_voice_1602061_7 = "嗨，我看你最近情緒有點低落，怎麼了？被別人否定了嗎？別太在意那些眼光，做自己就好了。",
  str_voice_1602061_8 = "今天天氣真好！不如我們出去逛逛，發現些新事物怎麼樣？我、我只是剛好看到你才約你的……",
  str_voice_1602061_9 = "唔，我剛才睡著了？因為昨晚在看報表……啊！我身上披的是你的衣服？你、你幫我披上的？嗯……不是，我才沒有臉紅。",
  str_voice_1602061_10 = "說到資本，我覺得它就像一把雙面刃，要懂得運用，才能取得最大的效益。",
  str_voice_1602061_11 = "想要我待在這裡嗎？可以呀！不常來這裡，很新鮮，空氣也很清新，更有助於我做商業決策吧。",
  str_voice_1602061_12 = "資本是一切生意的基礎，只有足夠的資本才能爭取到更多機會。",
  str_voice_1602061_13 = "嘗試新事物、體驗各地的風土民情，可以幫助我們瞭解這個世界。",
  str_voice_1602061_14 = "告訴我你今天遇到什麼有趣的事情吧？我很想知道你眼中的世界，或許能帶給我一些商業啟發。",
  str_voice_1602061_15 = "嗨，生日快樂，我的朋友。你打算許什麼願望呢？",
  str_voice_1602061_16 = "今天要不要來一份創意料理當正餐，給你的味蕾一次冒險？",
  str_voice_1602061_17 = "早安，又是新的一天，讓我們一起去探索新的機會和可能性吧！",
  str_voice_1602061_18 = "累了一天，辛苦了。要好好休息，放鬆一下喔。",
  str_voice_1602061_19 = "太晚了，我要去休息啦，不然明天可沒精力應付一整天的工作。",
  str_voice_1602061_20 = "影鎮是個充滿機會和挑戰的地方，可惜我的母親在那裡……",
  str_voice_1602061_21 = "啟光真是太棒了，有各種科技和創新，正適合我這種創業家。",
  str_voice_1602061_22 = "影子在注視著你。",
  str_voice_1602061_23 = "破壞我生意的暗鬼絕對不可饒恕！",
  str_voice_1602061_24 = "醒山是個優秀的合作夥伴，或許我該考慮在紅油沙漠再投資一些專案……",
  str_voice_1602061_25 = "叭噗是個可靠的助手，我很意外紅油沙漠有她這種認真又老實的光靈。",
  str_voice_1602061_26 = "我喜歡商業交易，充滿了變數和挑戰，只有在變數中才能找到商機。",
  str_voice_1602061_27 = "我很討厭那些總是活在規矩和框架裡的人，太無聊了。",
  str_voice_1602061_28 = "這就是你最重要的資產吧。咦？你說巨像是家人？真是奇怪的想法。",
  str_voice_1602061_29 = "你好，我是萊蕾，一個始終在尋找商業機會的企業家，非常期待與你合作。",
  str_voice_1602061_30 = "感謝投資。",
  str_voice_1602061_31 = "博弈開始。",
  str_voice_1602061_32 = "保持競爭力。",
  str_voice_1602061_33 = "火光乍現！",
  str_voice_1602061_34 = "合作愉快。",
  str_voice_1602061_35 = "尋找機遇。",
  str_voice_1602061_36 = "風險投資。",
  str_voice_1602061_37 = "開始營業了！",
  str_voice_1602061_38 = "資本賦能！",
  str_voice_1602061_39 = "市場之手！",
  str_voice_1602061_40 = "變現吧！",
  str_voice_1602061_41 = "跟著我有股份喔～",
  str_voice_1602061_42 = "不錯的投報率。",
  str_voice_1602061_43 = "市場的風向變了……",
  str_voice_1602061_44 = "我可以在這裡看公司的財報嗎？",
  str_voice_1602061_45 = "想和我套關係？",
  str_voice_1602061_46 = "你很會投人所好唷。",
  str_voice_1602061_47 = "謝謝你總想到我。",
  str_voice_1602061_48 = "謝謝，我非常喜歡～",
  str_voice_1602061_49 = "誠信是合作的基石，我很樂意與你分享我的成長經歷和家族背景，這有助於我們建立穩定互信的夥伴關係。",
  str_voice_1602061_50 = "對於你的遭遇我深感抱歉，不過我有時也很羡慕你獨自一人、無拘無束呢。",
  str_voice_1602061_51 = "與其說我是創業家，不如換個我更喜歡的稱呼——追夢人。我想透過自己的努力來影響這個世界，達成夢想。",
  str_voice_1602061_52 = "白夜極光。",
  str_voice_1602061_53 = "你好呀。",
  str_voice_1602061_54 = "早安，今天有什麼安排？",
  str_voice_1602061_55 = "工作還順利嗎？",
  str_voice_1602061_56 = "還沒睡嗎？",
  str_voice_1602061_57 = "新的一年，希望你能嘗試更多你有興趣的新事物，自由享受生活吧～",
  str_voice_1602071_1 = "來吧老弟，我看你太緊繃了，人生苦短，沒有什麼值得煩惱。活力、激情和漂亮姐姐才是活著的意義！",
  str_voice_1602071_2 = "高級餐廳除了美味的料理，有時還能偶遇一些別具魅力的女性，光這兩點就值得我流連忘返了。",
  str_voice_1602071_3 = "真傷腦筋，我的馬丁尼昨天就放在這裡，怎麼不見了？到底發生了什麼事……難不成是我晚上宿醉忘記了……",
  str_voice_1602071_4 = "每個人當然都有過去，至於我的……或許「贖罪」二字更能代表過去的經歷對我的意義。",
  str_voice_1602071_5 = "男人總是需要一個成長的轉捩點，可以是一次刻骨銘心的事件，也可以……是一場無疾而終的愛情。",
  str_voice_1602071_6 = "哪怕小小的蜉蝣，也可以嚮往天空與太陽。遇到你之後，我覺得我的心也有點躁動了起來。別誤會，我對你可沒興趣。",
  str_voice_1602071_7 = "即便比我大上二十歲，也不乏有魅力十足的成熟女性值得約會。好奇了吧？別客氣，跟我一起去和大姐姐們玩遊戲……",
  str_voice_1602071_8 = "嗯……你身上散發出毛頭小子的稚嫩味道，這瓶香水你就儘管拿去試試吧，不用謝我。",
  str_voice_1602071_9 = "我沒有資格被愛……也沒有能力真正去愛一個人。許多人認為我輕浮，當然，我也不否認。",
  str_voice_1602071_10 = "在這裡發什麼呆，難道沒有人找你約會嗎？嘖，真是可惜。時間管理這方面，你應該多向我學習。",
  str_voice_1602071_11 = "時薪算你10000白夜幣就好，這可是友情價。嗯……看來你的財務狀況不太好，那就先賣你一個人情吧。",
  str_voice_1602071_12 = "欸，叫我大叔也太沒禮貌了吧？應該叫希南哥哥——你說有點噁心？這樣我會傷心的，還是叫我希南吧。",
  str_voice_1602071_13 = "度假村裡許多設施都是我精心設計的，確保客人能擁有絕無僅有、難以忘懷的美妙體驗……",
  str_voice_1602071_14 = "嚇我一跳，下次走路能不能發出一點聲音？我剛才正在思考——如何把這單調的房間改造一番。",
  str_voice_1602071_15 = "生日快樂，祝你新的一年成長為有擔當的男子漢。",
  str_voice_1602071_16 = "怎麼盯著我，難不成是我的髮型太亂？看來得去找美髮師做一下造型了。",
  str_voice_1602071_17 = "我推薦你吃班尼迪克蛋當早餐，營養全面又不失風味。",
  str_voice_1602071_18 = "越夜越美麗，我要抓緊時間去約會了！",
  str_voice_1602071_19 = "年輕人的作息就該這樣，讓我們一起徹夜狂歡吧！",
  str_voice_1602071_20 = "我走遍大陸後還是決定回到家鄉，然後遇到了他們——紅油扳手。",
  str_voice_1602071_21 = "我在白夜城度過了一段很長的時間，也在那裡受到不少好心人的照顧。",
  str_voice_1602071_22 = "活在當下。",
  str_voice_1602071_23 = "那群暗鬼雖然沒有智慧，卻十分強大。",
  str_voice_1602071_24 = "醒山那傢伙雖然不算細膩，但和我很合得來。",
  str_voice_1602071_25 = "要說叭噗和我是什麼關係，她比較像我沒血緣的女兒吧？呵呵。",
  str_voice_1602071_26 = "我喜歡嘗試新香水，雖然有時會踩雷，不過那也挺有趣的。",
  str_voice_1602071_27 = "那些不修邊幅的傢伙實在令人厭惡。",
  str_voice_1602071_28 = "「臨空者號」和我是同類呢，可以飛行的生物。",
  str_voice_1602071_29 = "歡迎來到我的度假村，身為這裡的主管，我有義務讓你度過快活的一天。差點忘了介紹，你可以叫我希南。",
  str_voice_1602071_30 = "需要透透氣。",
  str_voice_1602071_31 = "回想起故鄉的溪流……",
  str_voice_1602071_32 = "枯竭之河，再次流淌。",
  str_voice_1602071_33 = "銀色山澗中，蜉蝣在飛舞——",
  str_voice_1602071_34 = "相信我。",
  str_voice_1602071_35 = "它們與我同在。",
  str_voice_1602071_36 = "無人可擋。",
  str_voice_1602071_37 = "蜉蝣夢醒，泛起漣漪！",
  str_voice_1602071_38 = "蜉蝣群舞，煩惱不再！",
  str_voice_1602071_39 = "苦中作樂！",
  str_voice_1602071_40 = "彈無虛發！",
  str_voice_1602071_41 = "有點迫不及待了。",
  str_voice_1602071_42 = "小試身手而已。",
  str_voice_1602071_43 = "果然，昨晚喝太多了……",
  str_voice_1602071_44 = "即便在室內，也要隨時注意形象，才是優雅的紳士。",
  str_voice_1602071_45 = "謝謝，費心了。",
  str_voice_1602071_46 = "你倒是瞭解我的喜好。",
  str_voice_1602071_47 = "有什麼想讓我幫忙的事嗎？",
  str_voice_1602071_48 = "我送你約會技巧指南當回禮吧？",
  str_voice_1602071_49 = "我出生在德諾奧峽谷的一個村子裡，現在又回到這裡當度假村的負責人……或許，人生就是如此千迴百轉吧。",
  str_voice_1602071_50 = "我在白夜城住了許多年，漸漸受到那裡的文化與禮節的薰陶。或許正因如此，才會讓你覺得我看起來和紅油扳手的人略有不同。",
  str_voice_1602071_51 = "你問我為什麼要回到這裡？大概是我幾乎遊遍了整個艾斯特拉大陸，已經對隨波逐流的旅程感到無趣了吧。",
  str_voice_1602071_52 = "白夜極光。",
  str_voice_1602071_53 = "嗨。",
  str_voice_1602071_54 = "早安。",
  str_voice_1602071_55 = "午安。",
  str_voice_1602071_56 = "晚上沒有約會嗎？",
  str_voice_1602071_57 = "新年快樂！這麼好的日子，不打算和我一起去找點樂子嗎？",
  str_voice_1502081_1 = "要不我看這樣吧，大家按照計畫行事，我們就別那麼衝動，好不好？有人聽到我說話嗎？喂……",
  str_voice_1502081_2 = "大家盯著我的尾巴說要做蜥蜴料理，還說「蜥蜴斷尾可以重生」……我嚇得落荒而逃，結果他們卻狂笑，太過分啦！",
  str_voice_1502081_3 = "你有看見伊芙送我的花嗎？就是之前擺在窗台那盆。哈啾！抱歉，最近好像得了花粉症……",
  str_voice_1502081_4 = "大蜥蜴是我最好的夥伴，他很聽我的話。你的大老鷹不聽話嗎？要是大老鷹不舒服的話，得好好幫他檢查一下……",
  str_voice_1502081_5 = "你要小心沙漠中的流沙區域，雖然有我在的話可以救你，但是一個人的時候可是非常危險的！",
  str_voice_1502081_6 = "「守護機關」可是很厲害的，除了用來收拾邪惡的暗鬼，還可以對付不禮貌的傢伙……",
  str_voice_1502081_7 = "PlayerName每次都會默默聽我說完所有話……所以，你已經是叭噗的好朋友了。",
  str_voice_1502081_8 = "我也是會生氣的喔，比如偷吃我的點心、惡作劇、把紅油扳手弄得一團亂，還有，無視我的存在……",
  str_voice_1502081_9 = "並不是我走得太慢……你看，我的尾巴可是很笨重的，不小心一點會撞倒東西的。",
  str_voice_1502081_10 = "打起精神來，你該不會是……睡著了吧？唔……我好像也有點想睡了，一起……休息吧……",
  str_voice_1502081_11 = "PlayerName是想要隨時看到我，才讓我待在這裡的嗎？好開心……",
  str_voice_1502081_12 = "不用試圖用蜥蜴口味的泡芙誘惑我喔……那樣我一定會忍不住投降的。",
  str_voice_1502081_13 = "我得加快寫計畫的速度了，總有一天大家會按照我的計畫完美執行，這樣就不會帶來那麼多麻煩啦！",
  str_voice_1502081_14 = "老、老大，哪裡失火了？！滅火器在這裡……呃！原來是夢啊……我沒有嚇到你吧？",
  str_voice_1502081_15 = "生日快樂，這是我為你做的蜥蜴口味蛋糕，要記得吃喔……",
  str_voice_1502081_16 = "啊，你剛剛……有看到什麼嗎？我真的沒有偷吃泡芙喔！",
  str_voice_1502081_17 = "早安～我正在幫你安排行程表，再等一下，馬上就好……",
  str_voice_1502081_18 = "晚安，你問我在做什麼？我在寫日記……不、不准偷看！",
  str_voice_1502081_19 = "唔……怎麼還不睡？既然你不想睡，我就陪你一下吧。",
  str_voice_1502081_20 = "在我心裡，紅油扳手就是我的家。",
  str_voice_1502081_21 = "聽說北境很冷很冷，不知道我有沒有機會去看看呢？",
  str_voice_1502081_22 = "及時行樂，但要適度……",
  str_voice_1502081_23 = "暗鬼是世界上最可惡的傢伙，要把牠們都……都踩碎！",
  str_voice_1502081_24 = "萊蕾小姐是很好的老闆！我很感激她在遊樂園對我的照顧……",
  str_voice_1502081_25 = "醒山是世界上最勇敢、最有義氣的老大，他、他是我的偶像！",
  str_voice_1502081_26 = "紅油炸蚯蚓是世界上最美味的食物，我永遠都吃不膩……",
  str_voice_1502081_27 = "我討厭被無視，可是大家下一次還是會忽略我……",
  str_voice_1502081_28 = "嗯……看起來和大蜥蜴很不一樣，但很壯觀！",
  str_voice_1502081_29 = "我是現任紅油扳手「軍師」——叭噗，雖然大家常常不聽我的話……聽說你會駕駛大老鷹，就是那個很大的傢伙……",
  str_voice_1502081_30 = "還要更謹慎一點。",
  str_voice_1502081_31 = "流沙，變成金色了……",
  str_voice_1502081_32 = "「守護機關」已重組。",
  str_voice_1502081_33 = "前進吧，大蜥蜴！",
  str_voice_1502081_34 = "我……我會努力的！",
  str_voice_1502081_35 = "我就在這裡。",
  str_voice_1502081_36 = "沙漠的風啊……",
  str_voice_1502081_37 = "起舞吧，凝沙之流！",
  str_voice_1502081_38 = "凝沙……掀起風暴吧！",
  str_voice_1502081_39 = "流沙耀金！",
  str_voice_1502081_40 = "沙之讚頌！",
  str_voice_1502081_41 = "大家，要記得看向我喔……",
  str_voice_1502081_42 = "這是守護的力量。",
  str_voice_1502081_43 = "下次要好好計畫。",
  str_voice_1502081_44 = "大老鷹的胃好大啊……可以裝下好多房間。",
  str_voice_1502081_45 = "謝謝……你的禮物。",
  str_voice_1502081_46 = "嗚嗚，你……記得我的喜好？",
  str_voice_1502081_47 = "我需要思考要送什麼回禮……",
  str_voice_1502081_48 = "PlayerName果然……最好了！",
  str_voice_1502081_49 = "我不記得父母的模樣，也不知道自己的來歷，但沒關係，紅油扳手的大家就是我最珍視的家人！",
  str_voice_1502081_50 = "眼罩下的右眼……你很好奇嗎？啊，小時候紅油扳手遭到暗鬼入侵，我因為那次事件受傷了。",
  str_voice_1502081_51 = "我才不是什麼「吉祥物」，你別聽他們胡說，我是堂堂正正的「軍師」！雖然大家常常不按照我的計畫行動……",
  str_voice_1502081_52 = "白夜極光。",
  str_voice_1502081_53 = "你好～",
  str_voice_1502081_54 = "早安……",
  str_voice_1502081_55 = "午安呀。",
  str_voice_1502081_56 = "PlayerName，晚安囉。",
  str_voice_1502081_57 = "新年……快樂，一定會遇到好事情的！",
  str_voice_1601214_10 = "坦誠是種美德，但有時候會被誤解成冒犯。我寧願坦誠得罪人，也不願虛偽取悅人。",
  str_voice_1601214_11 = "有些人滿嘴道德卻比惡魔還壞，對吧？我喜歡看到他們被揭穿的那一刻。",
  str_voice_1601214_16 = "荊棘的刺雖然鋒利，但它的花卻異常美麗。這正是人生的真諦，痛苦與美好並存。",
  str_voice_1601214_17 = "那些人沉浸在對光之神的虛假信仰中，就像在黑暗中尋找不存在的光明。",
  str_voice_1601214_18 = "想把我困在這裡？我可不是你輕易能留住的人。不過這裡景色不錯，我就姑且看看吧。",
  str_voice_1601214_19 = "我發現你很喜歡幫助朋友，這是好的特質，但有時也要看看對方值不值得幫助。",
  str_voice_1601214_35 = "如果你無法忍受虛偽的事物，總是擔心自己會格格不入，只是因為你的內心太過純粹了。",
  str_voice_1601214_36 = "言行不一的人最可怕，因為他們既不誠實，又不可信。",
  str_voice_1601214_37 = "今天有什麼計畫？還是像往常一樣讓時間白白溜走？",
  str_voice_1601214_38 = "今天會是艱難的一天，因為荊棘花都開滿了，這意味著命運的折磨來臨了。",
  str_voice_1601214_39 = "吃過晚餐了嗎？餓著肚子苦修也不會讓信仰立刻實現。",
  str_voice_1601214_40 = "不想睡覺，是因為虛假的信念和意識型態擾亂了你的心神嗎？",
  str_voice_1601214_44 = "審判來臨。",
  str_voice_1601214_58 = "回歸本質。",
  str_voice_1601214_59 = "揭穿虛偽！",
  str_voice_1601214_60 = "信仰不會磨滅。",
  str_voice_1601214_61 = "荊棘盛放。",
  str_voice_1601214_62 = "愚弄一下～",
  str_voice_1601214_63 = "難道沒人信仰巨像嗎？",
  str_voice_1601214_64 = "早安，導航員。",
  str_voice_1601214_65 = "清晨的空氣總是讓人感覺自由。",
  str_voice_1601214_66 = "我會賠償的，導航員。",
  str_voice_1601214_67 = "早啊，今天有什麼計畫嗎？",
  str_voice_1601214_68 = "聽說你最近在晨練？",
  str_voice_1601214_69 = "要麻煩你了，導航員。",
  str_voice_1601214_70 = "今天的早餐有種白夜城的味道。",
  str_voice_1601214_71 = "你會在夜晚陷入低潮嗎？",
  str_voice_1601214_72 = "黑暗和寂靜籠罩著大地。",
  str_voice_1601214_73 = "你看過荊棘花盛開的樣子嗎？",
  str_voice_1601214_74 = "真知是黑夜和沉默的產物。",
  str_voice_1601214_75 = "想做什麼，想加入哪裡，這都是我的自由。",
  str_voice_1601214_76 = "黑暗的天空，猩紅的日冕。",
  str_voice_1601214_77 = "如果你想要指教的話，倒是可以問問我手中的荊棘。",
  str_voice_1601054_10 = "今天有什麼計畫嗎？外面天氣好像很好，要一起出去玩嗎？",
  str_voice_1601054_11 = "紅油扳手的大家給我的感覺就像是家人一樣……嘿嘿，導航員給我的感覺也一樣。",
  str_voice_1601054_16 = "世界這麼大，可不能把時間浪費在發呆上！接下來要去哪裡？我一直都很想去北境呢。",
  str_voice_1601054_17 = "不知道哥哥和紅油扳手的大家都在做什麼呀……嗯……！我也要打起精神，努力幫上導航員。",
  str_voice_1601054_18 = "嗯？在找我嗎？已經收拾好野餐會用到的東西了，什麼時候出發？",
  str_voice_1601054_19 = "「故事的最後，公主從噩夢中醒來，王子和她重要的家人都陪伴在身邊……」嗯！我很喜歡這個結局！",
  str_voice_1601054_35 = "不管怎麼說我也是女孩子，當然會對各式各樣漂亮的衣服有興趣了！導航員有什麼提議嗎？",
  str_voice_1601054_36 = "原來草是如此清香，太陽是如此溫暖……呼……感覺就快睡著了呢。",
  str_voice_1601054_37 = "等導航員好久啦！今天要去哪裡玩？",
  str_voice_1601054_38 = "哈……欠，感覺時間還很早呢……哥哥說不乖乖睡覺的話會長不高呀……",
  str_voice_1601054_39 = "晚安～今天也辛苦了，我特地泡了杯茶給導航員，請喝～",
  str_voice_1601054_40 = "呼……哈，不知道導航員失眠的時候會數羊嗎？還是數螢盞呢……一個螢盞……兩個螢盞……三個螢盞……四個……",
  str_voice_1601054_44 = "隨時行動。",
  str_voice_1601054_58 = "我們上吧！",
  str_voice_1601054_59 = "必須保護大家！",
  str_voice_1601054_60 = "掃除危險！",
  str_voice_1601054_61 = "可能會很痛喔！",
  str_voice_1601054_62 = "可沒邀請你喔！",
  str_voice_1601054_63 = "我正好帶了一些漂亮的花回來，可以放在這裡裝飾巨像。",
  str_voice_1601054_64 = "出來玩嗎？",
  str_voice_1601054_65 = "要不要再考慮一下加入紅油扳手！",
  str_voice_1601054_66 = "我現在非常幸福喔，因為有哥哥、你和大家一直在我身邊。",
  str_voice_1601054_67 = "可不能再浪費時間了！我還有很多地方想和導航員一起去呢！",
  str_voice_1601054_68 = "今天也要拜託導航員啦！",
  str_voice_1601054_69 = "那個……其實我最近在學習怎麼做飯，有機會的話你想試吃看看嗎？",
  str_voice_1601054_70 = "最近我的力量沒有失控了，這都多虧了導航員呢！",
  str_voice_1601054_71 = "能和導航員一起去野餐好開心啊！",
  str_voice_1601054_72 = "哥哥常說要及時行樂，所以工作的事先暫停一下，我們出去玩吧！",
  str_voice_1601054_73 = "導航員比較喜歡咖啡還是茶？我會在下次野餐前提前準備好的。",
  str_voice_1601054_74 = "嗯？導航員？你看起來好像沒什麼精神呢……要我講故事給你聽嗎？是之前從哥哥那裡聽來的。",
  str_voice_1602091_1 = "啟光聯邦的大元帥，這……本來就是屬於我的位置。",
  str_voice_1602091_2 = "壓低帽沿不代表被馴服。只有我能夠馴服我自己。",
  str_voice_1602091_3 = "要想加入我的軍團，先說說你對戰局的理解吧。",
  str_voice_1602091_4 = "全新的我，不僅僅是換身裝束這麼簡單。而是要把過去的自己，從身體裡連根拔除。",
  str_voice_1602091_5 = "紅男爵的變化不是意外，而是在提醒那些不懷好意的傢伙，正義與型態無關。",
  str_voice_1602091_6 = "力量如雷鳴般刺穿身體。你呢？準備好與我一起掀起狂瀾了嗎？",
  str_voice_1602091_7 = "我似乎能理解萊因哈特了，你確實是個有潛力的人。讓我看看你還有什麼是我不知道的，咳、我是說實力。",
  str_voice_1602091_8 = "不用離我那麼遠。紅男爵只會指向敵人，而你，是夥伴。",
  str_voice_1602091_9 = "謝謝你願意替我治療，不過這件事情不要讓我部下知道，就當做你我之間的祕密，好嗎？",
  str_voice_1602091_10 = "想不通的事情很多，但既然坐在這個位置上，煩惱和危機就常伴左右，我已經習慣了。",
  str_voice_1602091_11 = "哦？想找我聊聊？站在你面前的可不再是過去那個軍團長雷霆了，建議你想好再說。",
  str_voice_1602091_12 = "不用擔心我，這種程度的任務，只能說他們還不瞭解我真正的能耐。",
  str_voice_1602091_13 = "我帶領的軍團，不過是啟光戰力的冰山一角。不自量力的傢伙，我定會讓你輸得心服口服。",
  str_voice_1602091_14 = "我不覺得表情嚴肅有什麼問題。倘若你也統帥千軍，想必你的臉只會更難看。",
  str_voice_1602091_15 = "新的一歲，有沒有為了身邊的人，變得更成熟一些呢……",
  str_voice_1602091_16 = "不用那麼見外，直呼我的名字就行了。",
  str_voice_1602091_17 = "哦……都已經這個時間了。一思索眼前的局勢，不知不覺就天亮了。",
  str_voice_1602091_18 = "今天在訓練場上怎麼沒看到你？想追上我，你還得加緊練習。",
  str_voice_1602091_19 = "休息？抱歉，現在不是休息的時候。",
  str_voice_1602091_20 = "我早該想到高位之人有多貪戀權力，和那日益膨脹的野心。",
  str_voice_1602091_21 = "那座浮空城不過是作風保守之人養尊處優的地方，我從不在乎。",
  str_voice_1602091_22 = "為了啟明之光！",
  str_voice_1602091_23 = "一群渾渾噩噩、聽命於人的爬蟲。我一定會將牠們趕盡殺絕。",
  str_voice_1602091_24 = "要想戰勝萊因哈特，就必須將擋在面前的困難一一攻破。",
  str_voice_1602091_25 = "「這件事只有緋做得到」，凡是與她共事過的人都會這麼說。",
  str_voice_1602091_26 = "南征北討不是為了有一天能高枕無憂，而是為了在過程中磨礪自己。",
  str_voice_1602091_27 = "背刺我的人，我絕對會在死前將他捏得粉碎。",
  str_voice_1602091_28 = "第四軍團缺一支空中部隊，你這位朋友願意擔任指揮官嗎？",
  str_voice_1602091_29 = "我，雷霆，是啟光聯邦的新任大元帥。雖然不知道能在這位置坐多久，自我介紹的時候還是該正式一點。",
  str_voice_1602091_30 = "力量源源不斷！",
  str_voice_1602091_31 = "這就是我，勢不可擋！",
  str_voice_1602091_32 = "無需考慮，繼續強化！",
  str_voice_1602091_33 = "我的實力，何止如此！",
  str_voice_1602091_34 = "算你有眼光。",
  str_voice_1602091_35 = "雷鳴之勢就緒！",
  str_voice_1602091_36 = "別猶豫，就是現在！",
  str_voice_1602091_37 = "雷槍穿刺！",
  str_voice_1602091_38 = "感受雷鳴之勢！",
  str_voice_1602091_39 = "打不倒我！",
  str_voice_1602091_40 = "衝擊敵陣！",
  str_voice_1602091_41 = "最強軍團，聽我號令！",
  str_voice_1602091_42 = "不過是日常訓練的強度而已。",
  str_voice_1602091_43 = "集中精力，再戰一場。",
  str_voice_1602091_44 = "介意我在這裡訓練部下嗎？這麼大的空間，不利用一下很可惜。",
  str_voice_1602091_45 = "謝謝，我的屬下會需要這個。",
  str_voice_1602091_46 = "這個……告訴我，你是怎麼想到的？",
  str_voice_1602091_47 = "你果然是個心思細膩的傢伙，謝了。",
  str_voice_1602091_48 = "感謝！沒想到你這麼貼心。",
  str_voice_1602091_49 = "我承認，我沒想過用這種手段坐上大元帥之位。但單論實力，我雷霆絕對夠格！",
  str_voice_1602091_50 = "我看不慣萊因哈特那種息事寧人的作風。但是如今的局勢讓我相信，個人野心在啟光的未來面前一點也不重要。",
  str_voice_1602091_51 = "即使把我逼到這步田地，我也絕不會容忍傷害啟光同胞的行為。所有光靈都有活下去的權利。",
  str_voice_1602091_52 = "白夜極光。",
  str_voice_1602091_53 = "收到回話。",
  str_voice_1602091_54 = "醒了沒？準備晨練。",
  str_voice_1602091_55 = "老是盯著終端怎麼行。",
  str_voice_1602091_56 = "明早的訓練別忘了。",
  str_voice_1602091_57 = "新年快樂。",
  str_voice_1502101_1 = "白夜至上，祝你有平靜順遂的一天。",
  str_voice_1502101_2 = "我不是「聖女」，只是個普普通通的百姓。有空還請來趟市集光顧我的攤子和縫紉生意。",
  str_voice_1502101_3 = "身為光之神的子民，我的職責是保護光靈同胞不受暗鬼傷害。空裔的職責是什麼呢？",
  str_voice_1502101_4 = "感謝無上的光之神，賜予我斬斷黑暗的力量。",
  str_voice_1502101_5 = "為了拯救更多光靈同胞，我必須變得更強大。",
  str_voice_1502101_6 = "我將站在光靈隊伍的最前方，竭力為戰士指引方向。",
  str_voice_1502101_7 = "我在你的身上看到光靈種族的希望，不，是全體生靈的希望。",
  str_voice_1502101_8 = "要和我一起禱告嗎？雖然這只是我的個人習慣。日升日落之時，我期待與你分享我的信仰。",
  str_voice_1502101_9 = "嗯……還請原諒我不合時宜的說辭。與你在戰場上的默契，讓我相信你就是神賜的禮物。",
  str_voice_1502101_10 = "抱歉……讓你久等了。剛才我在為幾個孩子講故事，再說一次好嗎？",
  str_voice_1502101_11 = "我也是一名戰士，我必將為這片曾經守護過我的土地奉獻生命。",
  str_voice_1502101_12 = "從暗鬼進犯黃昏鎮的那一刻起，我們便只能走上戰場，永不回頭。",
  str_voice_1502101_13 = "光靈擁有活下去的權利。在光之神的教義裡，任何逆其意志的死亡都是不允許的。",
  str_voice_1502101_14 = "即使降生在神棄之地，神仍然能聽到我們的禱告。因為我始終相信，光之神與我同在。",
  str_voice_1502101_15 = "生日快樂，願光之神賜福於你。",
  str_voice_1502101_16 = "很高興見到你，精進劍術和祈求禱告，今天先做哪一個好呢？",
  str_voice_1502101_17 = "清晨，神之光灑遍艾斯特拉大陸。不妨陪我去市集走走吧？",
  str_voice_1502101_18 = "如此虔誠的你，一定會在日常的勞碌中聽見神的聲音。",
  str_voice_1502101_19 = "還沒休息嗎？那請試試在夜深人靜的時候祈禱吧，說不定可以更清晰地聽到神諭。",
  str_voice_1502101_20 = "說起來我也是個白夜人，但黃昏鎮的人從不在乎彼此的勢力背景。",
  str_voice_1502101_21 = "來自啟光的戰士和我們的目標一樣，那便是活著，與暗鬼抗爭到底。",
  str_voice_1502101_22 = "白夜至上。",
  str_voice_1502101_23 = "踐踏光靈者，必將受到光之神的審判。",
  str_voice_1502101_24 = "彼時心高氣傲的李奧，成為騎士團長後，一心只想守護黃昏鎮。",
  str_voice_1502101_25 = "若瑟是虔誠之人，關於教會的問題，我要向他請教的還有很多。",
  str_voice_1502101_26 = "出生在黃昏鎮的人能夠安居樂業，那便是我最大的心願。",
  str_voice_1502101_27 = "光是一切的源頭。玷污光之神的罪靈，會在光明重降之日悉數湮滅。",
  str_voice_1502101_28 = "我有個不情之請，巨像上是否有空閒房間，借我用於晨禱？",
  str_voice_1502101_29 = "光之神斬斷黑暗，光之民灼爍永恆。我是引導光明的教女，喬瑟琳。",
  str_voice_1502101_30 = "光之神永恆！",
  str_voice_1502101_31 = "我無所畏懼。",
  str_voice_1502101_32 = "我將劃破黑暗。",
  str_voice_1502101_33 = "致力於神聖使命！",
  str_voice_1502101_34 = "我定視死如歸。",
  str_voice_1502101_35 = "向著黑暗！",
  str_voice_1502101_36 = "願光之神庇佑！",
  str_voice_1502101_37 = "光之神啊，請指引我戰鬥！",
  str_voice_1502101_38 = "我將引導光明降臨！",
  str_voice_1502101_39 = "竭力斬殺！",
  str_voice_1502101_40 = "絕不手軟！",
  str_voice_1502101_41 = "嗯，我習慣站在隊伍的最前方！",
  str_voice_1502101_42 = "神之光照耀我們。",
  str_voice_1502101_43 = "一時的失敗，不會阻止我們前進。",
  str_voice_1502101_44 = "孤兒院的孩子們，一定會喜歡這裡的。放心，他們都是聽話的孩子。",
  str_voice_1502101_45 = "謝謝，神恩與你同在。",
  str_voice_1502101_46 = "能收到這樣的禮物，真是意外啊。",
  str_voice_1502101_47 = "承蒙厚愛，我能為你做些什麼嗎？",
  str_voice_1502101_48 = "謝謝，這是我收過最好的禮物！",
  str_voice_1502101_49 = "出身自艾斯特拉大陸邊陲，我明白拯救光靈的意義所在。即便環境險惡、暗鬼侵襲，光之神的子民也永不退縮。",
  str_voice_1502101_50 = "那些在黃昏鎮出生的孩子，曾經與我一樣，以為那就是整個世界。為了保護他們的一方天地，我會挺身而出。",
  str_voice_1502101_51 = "啟光、白夜城……許多人只因出生在不同陣營，便染上了敵對的顏色。但除了暗鬼，我們沒有別的敵人。",
  str_voice_1502101_52 = "白夜極光。",
  str_voice_1502101_53 = "你好。",
  str_voice_1502101_54 = "早安，我已為你祈禱。",
  str_voice_1502101_55 = "午安，願你今日也充滿勇氣。",
  str_voice_1502101_56 = "晚安，神之光永不離棄。",
  str_voice_1502101_57 = "新年快樂，願光之神與你同在。",
  str_voice_1600894_10 = "還在回憶事情的經過嗎？沒關係，請慢慢來，我會在這裡等候，不會離開。",
  str_voice_1600894_11 = "PlayerName，請勿慌張。告訴我，這裡發生了何事？我定為你尋回正義。",
  str_voice_1600894_16 = "工作時間，請保持專心……抱歉，我不應把對自己的要求強加於你。",
  str_voice_1600894_17 = "晨安，清冷的旭光使人安心。可以開始一天的工作了。",
  str_voice_1600894_18 = "要休息嗎？除了工作之外，我不知還可做些什麼？PlayerName，你有何建議？",
  str_voice_1600894_19 = "此時仍然頭腦清醒的，不是機關算盡的罪犯，便是我們這些追蹤罪犯之人。你……只是失眠嗎？",
  str_voice_1600894_35 = "搜查完畢。",
  str_voice_1600894_36 = "即刻出發！",
  str_voice_1600894_37 = "抗拒從嚴！",
  str_voice_1600894_38 = "這是最後的警告！",
  str_voice_1600894_39 = "伏法吧！",
  str_voice_1600894_40 = "你已無路可退！",
  str_voice_1600894_44 = "請將法典放於顯眼之處，我不想這裡成為「法外之地」。",
  str_voice_1600894_1 = "嗯？你也覺得這把劍過於鋒利了？請放心，我只會為了守護弱小、追尋正義而拔劍。啊，我不是在說PlayerName很弱小……",
  str_voice_1600894_2 = "這身衣服提醒著我，要時刻以匡扶正義、幫助他人為榮。PlayerName，你願意和我一起嗎？",
  str_voice_1600894_3 = "抱歉，我腿上的傷疤嚇到你了嗎？你說它們代表著正義與信念？咳……未免有些誇張了。",
  str_voice_1600894_12 = "任何人都不能打敗我，除了我自己……PlayerName，這可是你教會我的道理。",
  str_voice_1600894_13 = "若不是你，PlayerName，我可能仍困於那虛實難辨的夢魘之中。謝謝你，讓我找回真正的自己。",
  str_voice_1600894_14 = "想去的地方嗎？嗯……聽聞那些沒有律法約束之地，都有一套當地的「叢林法則」。我倒是很想去那些地方研究一番。",
  str_voice_1600894_58 = "審判庭並非爭論輸贏的地方。",
  str_voice_1600894_59 = "修正錯誤，無需瞻前顧後。",
  str_voice_1600894_60 = "審判他……便是審判我自己。",
  str_voice_1600894_61 = "你很善於表露自己的情感……我的意思是，我很羡慕這一點。",
  str_voice_1600894_62 = "我很好奇，空裔有怎樣的法律？",
  str_voice_1600894_63 = "我知道，我想要反抗的並不是他……我的父親。",
  str_voice_1600894_64 = "「只有獲勝者才配書寫正義」？不、不應該是這樣……",
  str_voice_1600894_65 = "曾經，我總以為「快樂」是一種罪。",
  str_voice_1600894_66 = "是時候培養一些愛好了吧。",
  str_voice_1600894_67 = "保護你的，也會約束著你。",
  str_voice_1600894_68 = "好，出去走走。不過你打算帶我去哪裡？",
  str_voice_1602111_1 = "你在找我嗎？放心，我哪裡也沒去，沒有生病也沒有被暗鬼吃掉。我、我很好，謝謝關心……",
  str_voice_1602111_2 = "今天艦橋上只有你一個人？在忙巨像的事……？啊，沒什麼，你在忙我就不打擾了，我看看你就好。",
  str_voice_1602111_3 = "你說得沒錯，外面的世界超乎我想像得廣闊。光是站在這裡，就能感受到了。",
  str_voice_1602111_4 = "我的冰在你的感應中，也像北境的暴風雪一樣冷酷、善變、暴虐嗎？",
  str_voice_1602111_5 = "我想要能守護他人的力量，能治癒和溫暖我所愛之人的力量。但是極光啊，為什麼偏偏是冰呢……",
  str_voice_1602111_6 = "如果那一晚我沒有衝動行事，也許就不會獲得這種力量，不會與姐姐錯過......但也不會遇見你們。",
  str_voice_1602111_7 = "我不是忘恩負義的人，當然不會在這裡白吃白住。打掃、護衛、幫廚我都幫得上忙……吧？",
  str_voice_1602111_8 = "冷飲我都準備好了，隨時可以通知大家來拿……你這吃驚的表情是怎麼回事？我也不是什麼事都會搞砸的好不好。",
  str_voice_1602111_9 = "不知不覺和你同行了這麼久，我已經不太甘心空手回到北境了，總是期待和你的下一次冒險。真是的，我什麼時候也成了這種人？",
  str_voice_1602111_10 = "欸？你真的睡著了？稍微戳一下看看會不會醒……嗚哇！不要突然醒過來啊！",
  str_voice_1602111_11 = "你想要我來這裡陪你？不、不是，我才沒露出什麼期待的表情！",
  str_voice_1602111_12 = "我沒有你想像得那麼怕寂寞，所以你也不用找這種理由來看我，我一個人也很好。",
  str_voice_1602111_13 = "要去炎熱的地方嗎？我也許可以提前準備一些冰塊，萬一你中暑可就糟糕了。",
  str_voice_1602111_14 = "我大概是這巨像上最不怕冷的人吧，所以給我添衣服就不必了……不、不准再說那個冰棒笑話！",
  str_voice_1602111_15 = "搞不懂彩偶的做法，只好送你北境的禮物了……生日快樂。",
  str_voice_1602111_16 = "看你一直跑上跑下，跟光靈溝通，巨像導航員也很辛苦呢。",
  str_voice_1602111_17 = "早安，你沒熬夜吧？今天應該還有不少事情要忙，打起精神來唷。",
  str_voice_1602111_18 = "本來想邀請你一起用餐，看你忙成這樣子，我也來幫忙算了！",
  str_voice_1602111_19 = "你還沒睡啊……我已經……快睜不開眼睛了……晚安……呼。",
  str_voice_1602111_20 = "出身北境，就像在離世界中心最遠的地方。安寧、夢幻，但也很寂寞。",
  str_voice_1602111_21 = "我小時候也嚮往過白夜城，嚮往成為備受寵愛的公主。",
  str_voice_1602111_22 = "咳……暮冬而生。",
  str_voice_1602111_23 = "可以的話，當然也想離暗鬼遠一點。但想也知道不可能，我得擔起責任來才行。",
  str_voice_1602111_24 = "我知道三十三號她絕不是姐姐的替身，但我還是想當她的妹妹……",
  str_voice_1602111_25 = "朋友？唔……安頓先生很可靠。我知道我在這個時代幾乎沒有朋友，不用你提醒。",
  str_voice_1602111_26 = "我想，等有一天我成為姐姐那樣溫暖又有力量的人時，再說「喜歡」。",
  str_voice_1602111_27 = "暗鬼啊、毛蟲啊、打結的頭髮啊，都很討厭……最討厭的還是獨自一個人。",
  str_voice_1602111_28 = "這座巨像有意識？還是你的家人？我需不需要向他打個招呼？",
  str_voice_1602111_29 = "謝謝你，把我從北境的霜雪裡帶出來……重新向你自我介紹，我是札莉雅，願極光繼續指引我們的道路！",
  str_voice_1602111_30 = "頭髮……又發出光來了。",
  str_voice_1602111_31 = "我要把握好身體裡的光。",
  str_voice_1602111_32 = "我要凝結住手中的冰。",
  str_voice_1602111_33 = "我要成為姐姐那樣的戰士！",
  str_voice_1602111_34 = "我能幫得上什麼忙嗎？",
  str_voice_1602111_35 = "怎麼樣，可以發動了嗎？",
  str_voice_1602111_36 = "願極光指引——",
  str_voice_1602111_37 = "讓冰棱覆蓋！",
  str_voice_1602111_38 = "染上冰的顏色！",
  str_voice_1602111_39 = "雪光，綻放！",
  str_voice_1602111_40 = "我絕不後退！",
  str_voice_1602111_41 = "讓我來？嗯，我不會輸的。",
  str_voice_1602111_42 = "呼，太好了，我沒有丟臉吧！",
  str_voice_1602111_43 = "我、我還沒輸！",
  str_voice_1602111_44 = "感覺乘客變多了，PlayerName也會更加忙碌吧。",
  str_voice_1602111_45 = "外面的人都喜歡這種東西嗎？",
  str_voice_1602111_46 = "給我的？原來你還記得這種事……",
  str_voice_1602111_47 = "真是的，明明隨便陪我聊聊天就行了。",
  str_voice_1602111_48 = "我、我才沒有……非常感動呢！",
  str_voice_1602111_49 = "對母親早逝，又被父親嫌棄的我來說，姐姐是非常重要的人，所以為了找到她，我什麼都可以不顧。",
  str_voice_1602111_50 = "小時候我就不擅長控制自己的力量……在北境，沒有孩子不想像故事裡的光靈一樣操縱魔法，但卻沒有誰像我一樣整天讓魔法失控。",
  str_voice_1602111_51 = "我……在冰裡睡了足足一百年。如果沒有你和安頓先生，我大概會永遠沉睡在那個地方吧。",
  str_voice_1602111_52 = "白夜極光。",
  str_voice_1602111_53 = "你在哪裡？",
  str_voice_1602111_54 = "早安，這裡的早晨很暖和……",
  str_voice_1602111_55 = "不覺得有點熱嗎？",
  str_voice_1602111_56 = "晚安，願你受光的庇護。",
  str_voice_1602111_57 = "也許是因為累積太久，我有很多新年願望。你呢？把你藏在心裡的那些期待都告訴我，好不好？",
  str_voice_1602121_1 = "真的非常感謝你！沒想到有一天，我也能住進這種遠古文明的智慧造物！",
  str_voice_1602121_2 = "巨像記錄工程編號三百一十二，今天的觀察對象是了不起的螢盞……嗯？你什麼時候到我背後的？完全沒發現。",
  str_voice_1602121_3 = "沒關係，以你的熱情和執著，一定能繼承空裔一族的知識，實現他們對這個世界的期待。",
  str_voice_1602121_4 = "光靈的力量來源是光，這究竟代表著什麼呢……表示我們是太陽的子民嗎？還是這暗示著，除此之外的道路皆為黑暗……",
  str_voice_1602121_5 = "無論是各地的資料典籍，還是泥土裡挖出的遺物，都可以看出這個世界發生了很多大變動……",
  str_voice_1602121_6 = "土地或許經歷了許多變化，但天空不會改變。所以我認為，相對於其他所有知識，天文學是最獨特的！",
  str_voice_1602121_7 = "啊，請問我可以佔用你一點時間嗎？關於資料室裡展示的空裔歷史，我有非常想問的問題……",
  str_voice_1602121_8 = "位置……角度……潮汐力……新的公式……啊不好意思，一下子提到太多東西了，你之前問什麼來著？",
  str_voice_1602121_9 = "好明朗的天空，謝謝你，帶我來到巨像的頂端，還特意開到這麼遠的位置。",
  str_voice_1602121_10 = "自轉的角度，星系的旋臂……啊，對不起！我不是故意把水灑出來的！",
  str_voice_1602121_11 = "現在開始記錄。天氣晴朗、風向西南，適宜出航。我會努力輔助你的。",
  str_voice_1602121_12 = "書是很重要的歷史資產。哪怕是為兒童創作的歌謠，也可能藏有歷史的線索。",
  str_voice_1602121_13 = "對不起，這個我也沒有聽過，果然還是應該去正規學院進修呢。",
  str_voice_1602121_14 = "不知道是第幾次沒注意到你來了，我真是不合格的朋友啊……得想辦法把這個習慣改掉……",
  str_voice_1602121_15 = "對不起，差點忘了今天是你生日！啊，我拿什麼補償你比較好？你說吧，什麼都可以！",
  str_voice_1602121_16 = "吃飯時間都過了？對不起！我常常忘記吃，下次不用等我了！",
  str_voice_1602121_17 = "早安……呃，抱歉，昨晚一直在想問題，沒有睡好。",
  str_voice_1602121_18 = "終於天黑了，我準備記錄今晚的天象，有發現什麼有趣的就告訴你。",
  str_voice_1602121_19 = "那顆星星似乎有變化……是雲層的干擾嗎？咦，你也還沒睡？",
  str_voice_1602121_20 = "也許沒有啟光和白夜城那麼引人注目，但我相信世界的真相就在北境！",
  str_voice_1602121_21 = "真理結社談論的話題我都很感興趣，但我完全聽不懂他們在說什麼……",
  str_voice_1602121_22 = "暮冬而生！",
  str_voice_1602121_23 = "暗鬼到底是從什麼時候開始出現的？是自然誕生的生物嗎？還是……",
  str_voice_1602121_24 = "札莉雅小姐說話也許有些任性，但我知道她待人很真誠。",
  str_voice_1602121_25 = "如果三十三號不想談論自己的過去，即使再好奇，我也會尊重她的意願。",
  str_voice_1602121_26 = "所有能拓展視野的知識都很棒，不過最棒的果然還是天文學吧。",
  str_voice_1602121_27 = "其實我也說不上憎恨那些毀壞書籍的人，只是覺得很可悲而已。",
  str_voice_1602121_28 = "這座巨像的存在本身，就是一座龐大的知識寶庫了！活生生的歷史！",
  str_voice_1602121_29 = "你是說，就算只是個不成熟的民間學者，我也可以留在巨像上進行觀測記錄工作嗎……太好了！",
  str_voice_1602121_30 = "又多學到了一點。",
  str_voice_1602121_31 = "地理學是基礎。",
  str_voice_1602121_32 = "植物學也非常管用。",
  str_voice_1602121_33 = "天文學隱藏著祕密。",
  str_voice_1602121_34 = "今天要探索哪裡？",
  str_voice_1602121_35 = "樹木指引了方向。",
  str_voice_1602121_36 = "遵循能量的公式。",
  str_voice_1602121_37 = "應急術式啟動……應該，沒問題吧！",
  str_voice_1602121_38 = "應急術式啟動，嗯，沒問題！",
  str_voice_1602121_39 = "環境衝擊！",
  str_voice_1602121_40 = "能量代謝！",
  str_voice_1602121_41 = "可以嗎？那，請大家跟緊我！",
  str_voice_1602121_42 = "還好還好，有驚無險。",
  str_voice_1602121_43 = "沒事，這點傷我扛得住。",
  str_voice_1602121_44 = "讓我再仔細看看牆上這份肌材……",
  str_voice_1602121_45 = "……嗯？你剛才說什麼？禮物？",
  str_voice_1602121_46 = "謝謝！這個對我很有幫助！",
  str_voice_1602121_47 = "一直讓你這麼照顧，真是不好意思。",
  str_voice_1602121_48 = "非常感謝！我一直想拆一個來看看～",
  str_voice_1602121_49 = "如果可以的話，我確實很想去正規的學院進修。不過，前幾次努力都失敗了。",
  str_voice_1602121_50 = "離開北境四處流浪的那段時間裡，我也接觸到一些想法類似的人，可惜大家抱負不同，最終還是分道揚鑣了。",
  str_voice_1602121_51 = "白夜城的演說也好，真理結社的傳道也罷，兩邊的觀點我都不反對。我認為兩者所說的，都是世界真相的一部分。",
  str_voice_1602121_52 = "白夜極光。",
  str_voice_1602121_53 = "唔，訊號測試。",
  str_voice_1602121_54 = "啊，現在是該說早安的時間了！",
  str_voice_1602121_55 = "有空嗎？想給你看看我的新發現。",
  str_voice_1602121_56 = "希望今晚的觀測一切順利。",
  str_voice_1602121_57 = "又到了新的一年，也許就在今年，就在今天，人們對這個世界的見解會產生翻天覆地的變化。",
  str_voice_1502131_1 = "您已在巨像內度過了半個太陽週期，建議適度進行室外活動，接觸自然光，放鬆肩部肌肉和眼部神經。",
  str_voice_1502131_2 = "確定要拒絕我為您量身打造的健康監測系統嗎？我明白了，我會將結果轉告薇絲小姐。",
  str_voice_1502131_3 = "請不要介意剛才的碰撞，我的表皮能夠抵抗大部分污漬，包括您剛剛灑出的咖啡。",
  str_voice_1502131_4 = "很抱歉，我的外接記憶裝置裡並沒有誕生時的資料，我無法記起自己是如何出生，又是如何接受改造的。",
  str_voice_1502131_5 = "我確實記得接受改造的理由。要執行我的使命，我必須有一具光能傳輸與轉化效率皆更佳化的身體。",
  str_voice_1502131_6 = "我的使命所涉時間跨度遠超一般光靈的認知，服務於使命的這具身體也跨越了無數光靈的壽限，未來……也將如此。",
  str_voice_1502131_7 = "您似乎對我的外觀很感興趣。其實此型態只是制式塗裝，我還有應對其他環境的塗裝可供選擇。",
  str_voice_1502131_8 = "決定和您一起登上巨像時，我也曾感到猶豫，不知我的型態能否被外界光靈所接納。",
  str_voice_1502131_9 = "感謝您協助我清潔表層塗裝，也請允許我為您清洗表皮作為回報……不可以嗎？",
  str_voice_1502131_10 = "待機中……希望您也能享受您的待機時間。",
  str_voice_1502131_11 = "瞭解，我將以專業的手段協助您度過完美的一天。接下來請在薇絲小姐的計畫書、影鎮委託欄、巨像維護和白夜城人際往來中選擇您想完成的項目。",
  str_voice_1502131_12 = "我的身分、我的使命、我所隱瞞的祕密，都必須保密。但我相信您的選擇，您不會讓我暴露於風險。",
  str_voice_1502131_13 = "即使是我，也無法承受永無止盡的漫長工作所帶來的無力感……請您一定要注意休息。",
  str_voice_1502131_14 = "即使世界上還有構造、使命與我類似的光靈，我也很難理解他們的變化，這就是孤獨嗎……",
  str_voice_1502131_15 = "生日快樂。我的記憶裝置沒有記錄這句話，但我學起來了。",
  str_voice_1502131_16 = "請您盡情享受美妙的用餐時間。我並不需要攝取一般光靈的食物。",
  str_voice_1502131_17 = "請您按時起床，我將為您規劃一天的行程。",
  str_voice_1502131_18 = "請您準時返回巨像，我會協助您處理今日未盡的事項。",
  str_voice_1502131_19 = "請您按時入寢，調養精神。我並不需要一般光靈的睡眠。",
  str_voice_1502131_20 = "將我變作這一姿態的人沒有留下名字，但比起追溯起源，我更想探知未來。",
  str_voice_1502131_21 = "我曾接到提醒，需小心來自啟光的窺視……",
  str_voice_1502131_22 = "新的使命，在前方等待。",
  str_voice_1502131_23 = "我的記憶裝置中已有暗鬼的記錄，牠們存在的歷史毋庸置疑。",
  str_voice_1502131_24 = "諾維亞大人是我的上級，換算成光靈的說法，即是家長。咦，這說法不對嗎？",
  str_voice_1502131_25 = "札莉雅發生的事我也有責任，但我不知道該如何對其情緒做出反應。",
  str_voice_1502131_26 = "過去，我沒有喜歡的事物，只有唯一的使命。現在，我不知道……",
  str_voice_1502131_27 = "我討厭沒有盡頭的工作，無法改變的混沌趨勢。",
  str_voice_1502131_28 = "我的記憶裝置中曾有巨像的記錄，可惜後來因資料維護而刪除。",
  str_voice_1502131_29 = "古老遺跡的維護者，三十三號，遵守約定，在此回應您的呼喚。",
  str_voice_1502131_30 = "資料庫升級。",
  str_voice_1502131_31 = "對敵資料已更新。",
  str_voice_1502131_32 = "武裝版本已成功更新。",
  str_voice_1502131_33 = "外接記憶裝置已全面增強。",
  str_voice_1502131_34 = "三十三號，加入戰鬥。",
  str_voice_1502131_35 = "偵測到敵意。",
  str_voice_1502131_36 = "準備改造——",
  str_voice_1502131_37 = "改造開始，請抓緊時間。",
  str_voice_1502131_38 = "最佳方案，全面執行！",
  str_voice_1502131_39 = "武器發射。",
  str_voice_1502131_40 = "指令，摧毀。",
  str_voice_1502131_41 = "我將全面接管。",
  str_voice_1502131_42 = "已確認完成使命。",
  str_voice_1502131_43 = "請求損傷評估。",
  str_voice_1502131_44 = "室溫適宜，光照適宜，空氣流通適宜，評估為最適合PlayerName打瞌睡的場所。",
  str_voice_1502131_45 = "感謝您的物資支持。",
  str_voice_1502131_46 = "非常感謝，我將仔細紀錄其特徵。",
  str_voice_1502131_47 = "我似乎可以向您學習和光靈的交流技巧。",
  str_voice_1502131_48 = "您何以能夠得知我的傾向？",
  str_voice_1502131_49 = "是的，即使外表和內在都已大不相同，我依然是光靈。這是 DNA 變異所賦予我的身分。",
  str_voice_1502131_50 = "北境的地底設施對北境的安全，乃至整個光靈種族的安危都有特殊的意義。我即為此而生，為此而受改造的維護者。",
  str_voice_1502131_51 = "我曾預估，我可以堅持使命，直到我和設施中的一切都因超過使用年限而報廢。但錯誤還是出現了，出現於我的精神，而非身體。",
  str_voice_1502131_52 = "白夜極光。",
  str_voice_1502131_53 = "您好。",
  str_voice_1502131_54 = "早安，是否需要報時？",
  str_voice_1502131_55 = "午安，我更新了一份食譜。",
  str_voice_1502131_56 = "晚安，準備播放助眠曲。",
  str_voice_1502131_57 = "資料庫中的紀年早已失效，但我願意重新接受新的年曆，和您一起重新認識這個世界。",
  str_voice_1601881_1 = "「灼華郡主是質子」，這事並不是什麼機密。只是「質子」這二字，聽著有些逆耳。本郡主更喜歡稱呼自己是「留、學、生」。",
  str_voice_1601881_2 = "為何如此這般看我……難不成今日我的胭脂比往日塗得厚了些？",
  str_voice_1601881_3 = "兆國攜八大諸侯國雄踞龍洲大陸，看似君臣一心，實則暗流洶湧……若我還待在鄴國，許是永遠都沒法知道這些。",
  str_voice_1601881_4 = "不瞞你說，我很是羡慕那些雲遊四海的有志之士。若有一天我完成了肩負的使命，也許也能像他們一般逍遙吧。",
  str_voice_1601881_5 = "離開鄴國的時候，阿妹還不到兩歲。聽阿玖說，如今她已經開始修習舞蹈……真想看看她現在的模樣啊。",
  str_voice_1601881_6 = "治國之道講究的是因地制宜，在一國好用的法子不一定就適用於別國。別誤會，我學這些不為別的，只盼日後有機會輔佐叔父……或是阿姐。",
  str_voice_1601881_7 = "「濟國世子有意與鄴國的灼華郡主成婚」？怎麼連你也聽說了？唉，我也不願做那狠心之人，只可惜……",
  str_voice_1601881_8 = "你這裡的螢盞可真有趣，讓我想起幼時最愛的鄴國玩具——機關鳥。待我找些上好的紫檀木，改日親手做一個送你。",
  str_voice_1601881_9 = "聽我說了這麼多鄴國的事，你會不會覺得煩膩？嗯？不會嗎……也許有朝一日，我可攜你一同回歸故里。",
  str_voice_1601881_10 = "PlayerName公子大可以安心處理公務。我就在此處賞花，不會私自闖去別處。",
  str_voice_1601881_11 = "多謝PlayerName公子相邀，實不相瞞，我早就想前來拜訪，正在想著要如何開口呢。啊，忘記把我的胭脂奩帶來了……",
  str_voice_1601881_12 = "世人皆說命數由天，可我偏偏不信。",
  str_voice_1601881_13 = "你可曾聽說過「卜存子」？他白髮白鬚，是一位醫術高明的仙人。沒有嗎？沒事的，我早已習慣了這個回答。",
  str_voice_1601881_14 = "昨夜的月亮似銀盤一般皎白，可到底不如在家鄉時看到的那般漂亮……PlayerName公子，你說，我何時才能歸家？",
  str_voice_1601881_15 = "送你一碗百花羹，願你花開百歲庚。PlayerName公子，生辰安康。",
  str_voice_1601881_16 = "空……啊，抱歉，你在忙嗎？我不是有意叨擾。咦，沒關係嗎？",
  str_voice_1601881_17 = "早早起床，在艾斯特拉大陸不算是一種美德嗎？",
  str_voice_1601881_18 = "夜風微涼，此時出門散步，想必是絕佳的。嗯？你們管這叫……約會？",
  str_voice_1601881_19 = "雖說苦夜悠長，但PlayerName公子再不歇息，怕是晨雞都要來報曉了。",
  str_voice_1601881_20 = "鄴國有許多能工巧匠，只要是你能想到的物件，他們都能造出來。",
  str_voice_1601881_21 = "我在書中看過，影鎮包容開放，兼收並蓄……倒有幾分我們鄴國的風采呢。",
  str_voice_1601881_22 = "「兼愛」乃吾鄴國立國之根本。",
  str_voice_1601881_23 = "世上為何會有暗鬼這種……生來就帶著惡意的生物呢？",
  str_voice_1601881_24 = "別看阿玖總是悶頭不語，她可是個深藏不露的人呢。",
  str_voice_1601881_25 = "叔父待我不薄，可我總覺得……現在的他不再是我幼時相識的那個叔父了。",
  str_voice_1601881_26 = "世間花萬朵，我獨愛海棠一支。",
  str_voice_1601881_27 = "人的命數是由自己決定的，為何要交由那些江湖騙子推算？",
  str_voice_1601881_28 = "你這巨像是用了什麼法子造的？真想讓我們鄴國的工匠們也造一個出來。",
  str_voice_1601881_29 = "你就是PlayerName公子？我知道你，這有何稀奇？不過是稍加翻閱艾斯特拉大陸的書刊就會知道的事。我是灼華郡主……罷了，叫我丹棠就好。",
  str_voice_1601881_30 = "我命，由我！",
  str_voice_1601881_31 = "暗香，幽動。",
  str_voice_1601881_32 = "猶聞仙樂。",
  str_voice_1601881_33 = "讓我變厲害的人，是你？",
  str_voice_1601881_34 = "聽君差遣。",
  str_voice_1601881_35 = "花期將至。",
  str_voice_1601881_36 = "賞花有時。",
  str_voice_1601881_37 = "花落無聲。",
  str_voice_1601881_38 = "海棠有情。",
  str_voice_1601881_39 = "風起，落英。",
  str_voice_1601881_40 = "花事，不休！",
  str_voice_1601881_41 = "既是如此，我便不推讓了。",
  str_voice_1601881_42 = "稍等，待我補個妝。",
  str_voice_1601881_43 = "花謝為誰憐……",
  str_voice_1601881_44 = "不曾想……這巨像之內竟也別有洞天。",
  str_voice_1601881_45 = "PlayerName公子這是作何……",
  str_voice_1601881_46 = "本郡主很是歡喜。",
  str_voice_1601881_47 = "PlayerName公子有心了。",
  str_voice_1601881_48 = "今日投我以桃，他日必將報之以李。",
  str_voice_1601881_49 = "我自幼便不得父王寵愛，只因那算命先生說我生辰不吉，是命數乖蹇之人。",
  str_voice_1601881_50 = "衛家上下全部染病、長臥不起，唯有我僅過三日就痊癒如初。人人都說……丹棠是天煞孤星，會孤克六親。",
  str_voice_1601881_51 = "叔父即位後，我肩負使命，遠走濟國。鄴國國運比父王在位時好轉了許多……難道我果真是剋星？",
  str_voice_1601881_52 = "白夜極光。",
  str_voice_1601881_53 = "PlayerName公子，可在？",
  str_voice_1601881_54 = "PlayerName公子，晨安。",
  str_voice_1601881_55 = "日安。",
  str_voice_1601881_56 = "公子用過晚膳了嗎？",
  str_voice_1601881_57 = "祝PlayerName公子新年吉祥。離百花爛漫之時，又近了些許呢。",
  str_voice_1502151_1 = "麗蓓——原來是你啊，有什麼事嗎？如果是討債的話我可以幫忙……呃，不是嗎？那你到底想幹嘛啦？",
  str_voice_1502151_2 = "首先，我不是極端的金錢至上主義者；其次，如果要委託我做事，請先支付訂金——你的話可以打八折。",
  str_voice_1502151_3 = "找到麗蓓卡之前的經歷？我不想回憶起那些，話說你還真是八卦欸！",
  str_voice_1502151_4 = "我不討厭工作，工作意味著報酬。我私下偷接工作的事，你可千萬別跟麗蓓卡說！拜託啦！",
  str_voice_1502151_5 = "如果有搞不定的事儘管找我幫忙，雖然我也不一定能搞定，但至少可以聽你抱怨。",
  str_voice_1502151_6 = "只要有我在，就沒人敢欺負麗蓓卡！她現在需要好好靜養才行，如果你有事要找她，就先過我這關吧～",
  str_voice_1502151_7 = "你想知道麗蓓卡小時候的事嗎？那我可不能告訴你！不過……你如果也知道一些她的祕密，不如我們交換一下情報？",
  str_voice_1502151_8 = "我想要成為一個稱職的姐姐——不是為了彌補什麼，而是願望。\n我希望能聽到麗蓓卡再次發自內心叫我「姐姐」。",
  str_voice_1502151_9 = "總之！如果你「不小心」拍到了麗蓓卡的照片，我會出高價買下的！你懂我意思嗎？還有這件事不要讓麗蓓卡知道！",
  str_voice_1502151_10 = "又被躲開了……到底是哪裡沒做好，難道是我還不夠熱情嗎？\n還是說，得趁她不注意的時候……",
  str_voice_1502151_11 = "很好，讓我看看是哪個倒楣鬼欠你錢。\n什麼？沒有那種人？這種事應該早點告訴我！",
  str_voice_1502151_12 = "手癢，想揍人。\n啊，是你，來得正是時候。\n別怕，只是陪我演練一下討債而已，不會出人命——啊，別跑！",
  str_voice_1502151_13 = "為什麼不放棄討債的工作？\n問得好，當然是因為我想讓麗蓓卡過上好日子啊！她經歷了那麼多……這是身為姐姐必須做的。",
  str_voice_1502151_14 = "當你的保鏢或祕書有報酬嗎？我可不想讓你占便宜。不要用那種眼神看我，我還得養活麗蓓卡啊！多少給一點也行啊……我很划算的！",
  str_voice_1502151_15 = "……我早忘記生日這天該做些什麼了，你要是有想做的事就告訴我吧！",
  str_voice_1502151_16 = "呀吼～工作進展得怎麼樣？我這邊可是非常順利呢，不愧是我！",
  str_voice_1502151_17 = "起得很早嘛！既然遇到了，就跟我去找麗蓓卡吧！",
  str_voice_1502151_18 = "嗚哇，你不會還沒吃晚餐吧？我分你一些好了。",
  str_voice_1502151_19 = "哼哼～有些工作就是要在這種時間完成的，我懂我懂！",
  str_voice_1502151_20 = "就是要亂一點，我這樣的人才有工作——怎麼搞得好像壞人一樣？",
  str_voice_1502151_21 = "據說白夜城是世界上最安全的地方，我有考慮過要帶麗蓓卡去那裡定居。",
  str_voice_1502151_22 = "麗蓓卡天下第一！不接受反駁！",
  str_voice_1502151_23 = "如果說欠債還錢是天經地義，那麼消滅暗鬼也是如此。",
  str_voice_1502151_24 = "雖然涉總是一副什麼都知道的樣子，但我卻覺得她有一天會吃大虧。",
  str_voice_1502151_25 = "麗蓓卡似乎還有點放不開，啊～真是的！明明不用這麼害羞也～可～以～的～！",
  str_voice_1502151_26 = "麗蓓卡、麗蓓卡、麗蓓卡麗蓓卡麗蓓卡，嘿嘿嘿嘿嘿……",
  str_voice_1502151_27 = "被麗蓓卡討厭——唯獨這個是我無論如何都不能接受的。",
  str_voice_1502151_28 = "我能跟你借用一下嗎？開著這個大傢伙去討債一定超簡單！",
  str_voice_1502151_29 = "嗨！我是伊莎，職業討債集團兼麗蓓卡的醫療助手，不管什麼樣的債務都能幫你輕鬆搞定——不過你得是債主才行。",
  str_voice_1502151_30 = "喔，感覺不錯！",
  str_voice_1502151_31 = "能接更多工作了。",
  str_voice_1502151_32 = "富有的生活，啊～",
  str_voice_1502151_33 = "這下終於不會再被誤認成妹妹了！",
  str_voice_1502151_34 = "工作時間。",
  str_voice_1502151_35 = "準備好接受調教了嗎？",
  str_voice_1502151_36 = "從哪裡開始呢？",
  str_voice_1502151_37 = "就從這裡開始吧！",
  str_voice_1502151_38 = "想要試試這個？",
  str_voice_1502151_39 = "回答呢？",
  str_voice_1502151_40 = "乖乖聽話！",
  str_voice_1502151_41 = "你好，請還錢。",
  str_voice_1502151_42 = "欠款回收完畢～",
  str_voice_1502151_43 = "唔！忘記算利息了！",
  str_voice_1502151_44 = "休息時間～這時候就用麗蓓卡的照片來療癒一下疲憊的身心吧！\n……唔啊啊——！！",
  str_voice_1502151_45 = "說吧，誰欠你錢了？",
  str_voice_1502151_46 = "給我的？謝啦！",
  str_voice_1502151_47 = "唔……這下不得不收啦！",
  str_voice_1502151_48 = "喔喔！你這傢伙！你很懂嘛！",
  str_voice_1502151_49 = "環境對人的影響真的很大，看看我跟麗蓓卡就明白了。即便如此，我想，有些刻在靈魂最深處的東西是始終不變的。\n你覺得呢？",
  str_voice_1502151_50 = "身為姐姐，我一定是不合格的吧——這種事我當然知道，我只是不想、不願意承認。\n無法接受！我怎麼能輸給那個人！",
  str_voice_1502151_51 = "多虧你，我才沒有重蹈覆轍。謝謝你，謝謝你直到最後都沒有放棄，願意拯救麗蓓卡。\n……謝謝。",
  str_voice_1502151_52 = "白夜極光。",
  str_voice_1502151_53 = "哈囉～",
  str_voice_1502151_54 = "醒了嗎？該起床了！",
  str_voice_1502151_55 = "稍微偷懶一下怎麼樣？",
  str_voice_1502151_56 = "我還不累啊～你睡了嗎？",
  str_voice_1502151_57 = "新年快樂呀！今天就拋開工作，悠悠哉哉地度過吧！我準備了年糕和茶，跟我一起去麗蓓卡那裡玩吧！",
  str_voice_1602141_1 = "我的毒液會影響到您嗎……請放心，暫時還很安全……暫時而已。",
  str_voice_1602141_2 = "漫天的毒霧遮蔽了天空，就連呼吸都成了奢望……而我那時卻無能為力……",
  str_voice_1602141_3 = "從家族逃離後，她也一定經歷過很多背叛與傷痛。別擔心，我會保護好她的……一定。",
  str_voice_1602141_4 = "治癒病人是醫生的天職，但對我而言也有「喜歡」的成分在其中。\n話雖如此，還是不要生病最好，呵呵。",
  str_voice_1602141_5 = "我所擁有的能力，究竟是詛咒，還是上天賜予的禮物？\n我不清楚，不過，我希望能用在正確的事情上。",
  str_voice_1602141_6 = "呃……不用擔心，我沒有重蹈覆轍，只是這股疼痛是無法避免的。或許需要幾年、十幾年的時間，我的身體才能恢復……",
  str_voice_1602141_7 = "我以前會時不時地夢到家族被襲擊時的情形，不過現在已經不會再做那樣的夢了。",
  str_voice_1602141_8 = "您對我來說，也是家人般的存在——我這麼說的話，會讓您感到困擾嗎？\n不用回答我也沒關係的……",
  str_voice_1602141_9 = "正因為經歷過悲傷、痛苦與離別，才顯得平淡的生活彌足珍貴……我很珍惜現在的一切。",
  str_voice_1602141_10 = "謝謝你一直陪在我身邊……放心，我現在過得很好。\n還有，我很想你。",
  str_voice_1602141_11 = "您願意再次握緊我的手嗎？謝謝……",
  str_voice_1602141_12 = "多餘的毒液還殘留著……別擔心，它只會傷害我……",
  str_voice_1602141_13 = "我在影鎮附近新開了一家診所……是的，還是原來的名字。您要來看看嗎？",
  str_voice_1602141_14 = "利益究竟為影鎮帶來了什麼？人命變成簡單的數字、家人成了耀武揚威的工具……我不懂，我真的不懂……",
  str_voice_1602141_15 = "今天是您的生日？對不起，我什麼都沒準備……現在還來得及嗎？",
  str_voice_1602141_16 = "我一直在等您……",
  str_voice_1602141_17 = "朝陽……原來，這麼溫暖……",
  str_voice_1602141_18 = "出診結束了……現在是私人問診的時間。",
  str_voice_1602141_19 = "夜深了……但這次「光芒」不會再消散了。",
  str_voice_1602141_20 = "重要的不是住在哪裡，而是跟誰一起生活，不是嗎？",
  str_voice_1602141_21 = "影鎮……我始終無法理解這裡的生存法則……我也不想去理解。",
  str_voice_1602141_22 = "哪怕再混沌、黑暗的陰影之中，也總會有一絲微光存在。",
  str_voice_1602141_23 = "那些「單細胞生物」的可怕，遠不及人心……",
  str_voice_1602141_24 = "她是位特別的商人，我看不透她。另外，我……不太喜歡她看我的眼神。",
  str_voice_1602141_25 = "作為妹妹，我希望身為姐姐的伊莎能夠再穩重一點。",
  str_voice_1602141_26 = "與家人一起安穩生活的時光——對我來說，沒有比這更寶貴的東西。",
  str_voice_1602141_27 = "討厭的東西？有很多呢……\n不像？或許是因為您把我想得太好了吧？",
  str_voice_1602141_28 = "看得出來，您很珍惜這位家人。真好啊……",
  str_voice_1602141_29 = "終於又見到您了……這次，我們來立一個新約定吧，雙方都不能打破的那種。",
  str_voice_1602141_30 = "似乎沒有副作用。",
  str_voice_1602141_31 = "不會再痛了……",
  str_voice_1602141_32 = "會痊癒的，我保證。",
  str_voice_1602141_33 = "既然無法拒絕，那就接受吧。",
  str_voice_1602141_34 = "是出診嗎？",
  str_voice_1602141_35 = "還不撤退嗎……",
  str_voice_1602141_36 = "不許傷害他們……",
  str_voice_1602141_37 = "蔓延吧……",
  str_voice_1602141_38 = "我想這發作起來應該會很快。",
  str_voice_1602141_39 = "別反抗……",
  str_voice_1602141_40 = "很快就不痛了……",
  str_voice_1602141_41 = "如果是為了守護家人……",
  str_voice_1602141_42 = "呼～應該沒人受傷吧？",
  str_voice_1602141_43 = "快走吧……不用管我……",
  str_voice_1602141_44 = "這裡有地方可以存放多餘的毒液樣本嗎？最好是不太會有人去的倉庫之類的。",
  str_voice_1602141_45 = "很久沒收到過禮物了，謝謝您。",
  str_voice_1602141_46 = "這是……給我的？真的可以收下嗎？",
  str_voice_1602141_47 = "總覺得有點開始習慣您的好意了……",
  str_voice_1602141_48 = "謝謝，我會……好好珍惜的。",
  str_voice_1602141_49 = "您知道，我的家族已經不復存在——有時我會想像，如果沒有發生那種事，我現在會在哪裡，又在做些什麼呢？",
  str_voice_1602141_50 = "家人對您來說曾是虛無飄渺的概念，但現在，我想，您的身邊應該也有可以稱為「家人」的存在吧。",
  str_voice_1602141_51 = "我差點犯下大錯。\n即便如此，您跟姐姐也沒有放棄我。我實在不知該如何表達這份感情，請別嫌我囉嗦：\n謝謝您。",
  str_voice_1602141_52 = "白夜……極光？",
  str_voice_1602141_53 = "您好。",
  str_voice_1602141_54 = "早安，願您今天一切順利。",
  str_voice_1602141_55 = "稍微休息一下如何？",
  str_voice_1602141_56 = "差不多該睡了，您也早點休息吧。",
  str_voice_1602141_57 = "新年快樂，時間過得真快，不知不覺已經是新的一年了。\n新年願望？我的話，當然是希望能夠維持現在這樣平淡的生活。",
  str_voice_1600234_1 = "呼……你好，還記得我嗎？我是克娜莉，很高興再見到你……我說出來了！",
  str_voice_1600234_2 = "我真的適合這身衣服嗎……咦？你說……很好看？！唔，謝、謝謝……",
  str_voice_1600234_3 = "安東說茶會已經準備萬全了……但大家會不會來呢？PlayerName會不會來呢……",
  str_voice_1600234_4 = "哼哼哼哼，哼哼哼哼哼……",
  str_voice_1600234_5 = "感、感謝你的到來，如、如果不嫌棄的話，這裡……有我準備的茶點和咖啡……",
  str_voice_1600234_6 = "從夢裡醒來後……腦海中出現了新的曲調，等我練熟了，可以吹給你聽嗎？",
  str_voice_1600234_7 = "我好像夢到，安東曾經是更強大的存在……但現在這樣我也很滿足，它們的陪伴就夠珍貴了。",
  str_voice_1600234_8 = "我和安東在聊什麼？呃……聊到我跟你……嗚，是不能對你說的話題……",
  str_voice_1600234_9 = "抱歉，我想練習一下新的曲子，會打擾到你工作嗎？咦咦咦咦？！不、不用特地抽時間來聽啦！",
  str_voice_1600234_10 = "早上好，需要咖啡嗎？紅茶也可以喔。",
  str_voice_1600234_11 = "雖然時間過了，但需要的話，我也很樂意為你準備茶點……",
  str_voice_1600234_12 = "深藍色的夜空……就像海底一樣。如果沒有你……我一個人想必沒辦法面對……",
  str_voice_1600234_13 = "不好意思……我要開始吹奏囉。",
  str_voice_1600234_14 = "安東，準備好了嗎？",
  str_voice_1600234_15 = "希望不會吵到大家。",
  str_voice_1600234_16 = "謝謝大家聽我演奏。",
  str_voice_1600234_17 = "海洋之聲——",
  str_voice_1600234_18 = "水形之音——",
  str_voice_1600234_19 = "等等！安東你們跑太快了……我的鞋子！？",
  str_voice_1600234_20 = "大海會演奏，也會傾聽。",
  str_voice_1600234_21 = "安東還有其他同伴嗎？在海裡，還是別處？",
  str_voice_1600234_22 = "音樂居然能夠溝通不同的次元，真不可思議。",
  str_voice_1600234_23 = "魚兒們聽得很認真，但我偶爾也想要別的聽眾……",
  str_voice_1600234_24 = "我的單簧管！太好了，我沒有失去它。",
  str_voice_1600234_25 = "咳，請、請允許我帶來這場獨奏。",
  str_voice_1600234_26 = "你說……這身衣服很適合跳舞？我、我跳得來嗎……",
  str_voice_1600234_27 = "不行了，當茶會淑女比當咖啡店員還累……",
  str_voice_1600234_28 = "想逃跑……但穿著這身衣服連躲藏都很不方便啊！",
  str_voice_1600234_29 = "就算只是夢，在裡面得到的東西，也不全是泡影吧。",
  str_voice_1600234_30 = "謝謝你來參加我和安東準備的茶會。",
  str_voice_1600234_31 = "嗚咿咿咿……為什麼會是我呢？",
  str_voice_1600234_32 = "要我當女王什麼的……也太亂來了！",
  str_voice_1600234_33 = "躲起來，躲進熟悉的黑暗裡……",
  str_voice_1600234_34 = "音樂擁有力量……我，要讓他們……聽見我的憤怒！",
  str_voice_1600234_35 = "沒有人注意到我……沒有人注意到我……",
  str_voice_1600234_36 = "呼……呼……",
  str_voice_1600234_37 = "欸？",
  str_voice_1602161_1 = "「兼愛非攻」是我鄴國的機巧師所循之道，教人相愛相利而不互害。怎樣，很容易吧？就算只有兩個人也能做到。",
  str_voice_1602161_2 = "今天你想看點什麼好東西？噴火的銅牛、鑽地的蠍子還是自由起落的風箏？",
  str_voice_1602161_3 = "想問我機關鳥的製作方法？哈哈，在你這般舉世無雙的人物面前，只擺弄小孩子玩具太浪費了。",
  str_voice_1602161_4 = "你也對我的「奇掣巧行傘」有興趣？真有眼光！它攻防一體，收放自如，是我的得意之作唷！",
  str_voice_1602161_5 = "我確實對機關術全心全意，但也並非對活物不感興趣，不如說，大千世界芸芸眾生，便是我的造物曲尺。",
  str_voice_1602161_6 = "世人常謂我奇，擅奇巧之術，行怪奇之舉，獻出奇之策，與人群格格不入…PlayerName閣下，你又作何感想？",
  str_voice_1602161_7 = "要跟我出去逛逛嗎？有傘在手，無論下雨下雪下暗鬼都不必掛懷。",
  str_voice_1602161_8 = "我聽聞空裔所信奉之理和我的宗族有類似之處，怎麼樣，願意來我鄴國宗門交流一番嗎？",
  str_voice_1602161_9 = "只要你還在龍洲一天，還樂意來找我共飲，我傘下的一隅就永遠為你敞開，風雨不侵，霜雪不入。",
  str_voice_1602161_10 = "……所以說，自行梳洗機關的設計我已經有……嗯？你睡著了？",
  str_voice_1602161_11 = "這個銅人是我精心研製的僕役機關人，可以站崗放哨、端水打雜、聊天取樂……哈，當然不能代替我本人啦。",
  str_voice_1602161_12 = "若是可行，我十分想將機關術普及至鄴國上下，吃飯喝水都用得上的程度。",
  str_voice_1602161_13 = "其他諸侯國的來客常說鄴國人執迷於外物，但我覺得鑽研新事物總好過在迂腐的權術中彼此內耗。",
  str_voice_1602161_14 = "法寶、古遺、仙器……在龍洲大陸，那些古代遺物有很多種叫法，大型機關的啟動少不了它們。",
  str_voice_1602161_15 = "你猜我要送什麼，鳴禽舞雀還是車馬樓船？ 嘿，都錯了，是護心鏡。",
  str_voice_1602161_16 = "還在忙？好，我就在附近，有事叫我……或叫我的機關鳥。",
  str_voice_1602161_17 = "這個嘛……與其造個叫你起床的機關，不如直接造個替你工作的出來。",
  str_voice_1602161_18 = "嗯──好像也工作挺久了，要跟我一起出去蹓躂放鬆一下嗎？",
  str_voice_1602161_19 = "走走停停，吃吃逛逛，還沒盡興就又到了入睡時間，真是遺憾。",
  str_voice_1602161_20 = "鄴國以兼愛主張與工巧之術立國，是龍洲巧匠的福地，也是令我自豪的故鄉。",
  str_voice_1602161_21 = "嗯……能不能用你的人脈，跟我介紹一兩個啟光的頂尖研究員？",
  str_voice_1602161_22 = "哼哼，工巧中自有乾坤。",
  str_voice_1602161_23 = "我對艾斯特拉的對暗鬼技術很有興趣。縱有巧工，還需兼收並蓄方能應付。",
  str_voice_1602161_24 = "不了不了，我可不教丹棠郡主機關術，省得被人念叨教唆王室，大罪一樁。",
  str_voice_1602161_25 = "玖姑娘克服身世之苦，練就一身本領，著實令人欽佩，只望她莫要再捲入任何陰謀。",
  str_voice_1602161_26 = "哈哈，都說我「無機不歡」，其實沒那麼過分的。詩情劍意，花生瓜子，我都挺喜歡。",
  str_voice_1602161_27 = "再神妙的機關也是物，物不會暴起傷人。傷人的只能是惡念之人。",
  str_voice_1602161_28 = "古雲有鯕鵬，天人注靈韻……啊，沒事，我只是突然想起一些舊籍殘卷中的說法。",
  str_voice_1602161_29 = "喔！這裡就是你的巨像？客氣什麼，直呼我的名字「璇極」就是了！那我在這裡鼓搗些小玩意，你應該不會介意吧？",
  str_voice_1602161_30 = "神機需有妙用！",
  str_voice_1602161_31 = "強弩羽箭皆備！",
  str_voice_1602161_32 = "機栝連珠有方！",
  str_voice_1602161_33 = "傘下當定乾坤！",
  str_voice_1602161_34 = "有什麼妙招，說來聽聽～",
  str_voice_1602161_35 = "指在弦上。",
  str_voice_1602161_36 = "風雷盡在傘下。",
  str_voice_1602161_37 = "銅蜻蜓，發射！",
  str_voice_1602161_38 = "雷光奇掣，機關巧行！",
  str_voice_1602161_39 = "連珠掃！",
  str_voice_1602161_40 = "千機齊發！",
  str_voice_1602161_41 = "利器當配能人，還望各位相助！",
  str_voice_1602161_42 = "巧手亦需匠心，了不起的指揮！",
  str_voice_1602161_43 = "莫慌，只是一些小故障。",
  str_voice_1602161_44 = "讓我領略來自神話時代的機巧奧妙吧。",
  str_voice_1602161_45 = "什麼都可以，我不挑的。",
  str_voice_1602161_46 = "看你心這麼誠，交個朋友吧？",
  str_voice_1602161_47 = "有人掛念的感覺真不錯。",
  str_voice_1602161_48 = "看來下次的回禮，我得拿出壓箱本事了……",
  str_voice_1602161_49 = "我所屬的機巧師流派叫「乾雲」，與其相對的乃是「地坤」。二者一擅動一擅靜，但我以為乾坤合一、兼收並蓄才是進步之法。",
  str_voice_1602161_50 = "我想製造一個由機關打造的大千世界，一切勞務和苦役皆可由無生命的機關來完成，眾生即可兼愛無礙。",
  str_voice_1602161_51 = "看似平靜的鄴國實有異常在醞釀，其源頭並非鄴國，而在更加要害之地。為此，我推辭了謀士的工作，想要尋找那動亂的核心。",
  str_voice_1602161_52 = "白夜極光。",
  str_voice_1602161_53 = "喔，你好！",
  str_voice_1602161_54 = "早——",
  str_voice_1602161_55 = "今日又有什麼趣事？",
  str_voice_1602161_56 = "不胡鬧了，你也早點睡吧。",
  str_voice_1602161_57 = "我試做了一座紀念鐘，上面記錄著過往一年的點點滴滴……你說不想忘，那就讓機關替你記著吧，我們期待來日。",
  str_voice_1501871_1 = "在下算卦的法子乃是自創，名為「萬類天鬥」。十二陰、十二陽、一即陰且陽，將這二十五支簽放入籤筒中，擲簽卜卦。",
  str_voice_1501871_2 = "-要「棗」生貴子。\n-要「瓜」熟蒂落。\n-喲，我說多言多語，你們還學會旁敲側擊了？別要了，沒錢了，餓了外面吃草去。",
  str_voice_1501871_3 = "您想聽點奇聞異事？咳咳，龍五子「狻猊」，雖說喜靜不喜動，但曾在朝堂上當眾和大臣對峙，甚至動了手。",
  str_voice_1501871_4 = "當個合格的看客也沒那麼容易。若只是看，隔靴搔癢；若身處其中，難免進退無措。譬如走獨木橋，一線之間罷了。",
  str_voice_1501871_5 = "「天下第三富」？「三兩針」？「要命不要錢」？這些人在下知道是知道，但不認識啊～",
  str_voice_1501871_6 = "在下算的從來都不是天命，而是人事。天命大小不過生死，但人事卻是實實在在的柴米油鹽。",
  str_voice_1501871_7 = "在下真是窮得身上沒有半個子了！衣服破了洞，鞋子磨壞了跟，帽子被這幾隻鳥咬得開了線，還得求您多多接濟。",
  str_voice_1501871_8 = "嘶，您的卦象還真是離奇，竟然是即陰且陽的「貓卦」。所謂「困於陰陽之間，不在名錄之上」，前路如霧中迷途……咳，想聽後面的得加錢。",
  str_voice_1501871_9 = "龍生九子，子子不同，哪有什麼真龍假龍。剩到最後，假的也成了真的，真的亦有可能變成假的。",
  str_voice_1501871_10 = "手藝人看卦，講究「把簧兒」。看準了來人的「喜怒憂思悲恐驚」，卦也就算對一半了。",
  str_voice_1501871_11 = "您要算卦？您拜託的事，在下自然不會推脫，只是得勞煩您給我預備把椅子，因為坐著算更準。",
  str_voice_1501871_12 = "居廟堂之高，則自暇自逸；處江湖之遠，則為所欲為。",
  str_voice_1501871_13 = "老話常說，路未踏足不知遠，事未經歷不知難。",
  str_voice_1501871_14 = "你問客從何處來？「雲中瓊閣雲中跡，飄渺平明飄渺行。」",
  str_voice_1501871_15 = "喜事！喜事！祝您時運亨通、心想事成。",
  str_voice_1501871_16 = "嘶。先不跟您打招呼了，在下正牙疼，都是用糖水漱口惹的禍啊。",
  str_voice_1501871_17 = "「起床啦！」\n別吵、別吵！這也太早了，還沒睡醒呢……",
  str_voice_1501871_18 = "天乾物燥，小心火燭；關門關窗，防風防寒。",
  str_voice_1501871_19 = "白日不做虧心事，半夜不怕災傍身。",
  str_voice_1501871_20 = "大廈將傾之時，與其奮力抵擋，不如趁早溜之大吉。",
  str_voice_1501871_21 = "天地之大，無所不有。",
  str_voice_1501871_22 = "天地方略、鄰里奇聞、算卦算卦～",
  str_voice_1501871_23 = "暗鬼？呸，什麼醃臢玩意兒。",
  str_voice_1501871_24 = "在下有一朋友，身形如鶴，著蓑衣斗笠，喜獨釣寒江。",
  str_voice_1501871_25 = "上簽陽鼠、下簽陰鼠，鼠鼠類聚。在下看似在算卦，實則在罵人。",
  str_voice_1501871_26 = "家父捏的糖人當真極品，糖皮晶透，物形靈動。",
  str_voice_1501871_27 = "嘖……八哥不能不會說話，也不能太會說話，煩。",
  str_voice_1501871_28 = "這巨像可是稀罕之物，指不定能賣出一座金山。",
  str_voice_1501871_29 = "在下李天閑，上可談天說地、指點方略，下可粗談相法、淺看八字，朝堂祕聞、鄰里瑣事亦是無所不知。",
  str_voice_1501871_30 = "如不靈驗，分文不取。",
  str_voice_1501871_31 = "虛一而靜，坐觀成敗。",
  str_voice_1501871_32 = "眾生百態，光怪陸離。",
  str_voice_1501871_33 = "天命難違，人事可改。",
  str_voice_1501871_34 = "各位都是同行？",
  str_voice_1501871_35 = "起卦。",
  str_voice_1501871_36 = "打卦。",
  str_voice_1501871_37 = "乾坤百年，玄之又玄。",
  str_voice_1501871_38 = "推背敲爻，以占天命。",
  str_voice_1501871_39 = "合陰陽之數。",
  str_voice_1501871_40 = "具萬類之形。",
  str_voice_1501871_41 = "在下頭前帶路。",
  str_voice_1501871_42 = "趨吉避兇啊～",
  str_voice_1501871_43 = "福禍相依。",
  str_voice_1501871_44 = "嘰嘰喳喳、嘰嘰喳喳，真是粗鄙鳥語不絕於耳。",
  str_voice_1501871_45 = "吃人嘴軟，拿人手短啊……",
  str_voice_1501871_46 = "哎呦，感謝您的接濟。",
  str_voice_1501871_47 = "這多不好意思啊～",
  str_voice_1501871_48 = "喲！這玩意可金貴！",
  str_voice_1501871_49 = "在下曾遇雲中客，得《演天通神卷》。是天降祥瑞？是妖言惑眾？還是一卷廁紙呢？",
  str_voice_1501871_50 = "都說八哥能言善辯、好勇鬥狠。您可不要小瞧了在下身邊這些鳥，牠們知的、見的不比人少。",
  str_voice_1501871_51 = "-「他是個騙子，他扮過白鬢老頭。」\n-「他扮過黃花姑娘。」\n-呸，瞎說什麼鳥話，別在那造謠，我可是行不更名、坐不改姓。",
  str_voice_1501871_52 = "白夜極光。",
  str_voice_1501871_53 = "喲，是您！",
  str_voice_1501871_54 = "您早～",
  str_voice_1501871_55 = "您吃了嗎？",
  str_voice_1501871_56 = "晚安啊。",
  str_voice_1501871_57 = "年年有今日，歲歲有今朝。",
  str_voice_1602181_1 = "我特地為您準備了折扣清單，要看一下嗎？啊，背面的是給優質客人您的一點小、禮、物。",
  str_voice_1602181_2 = "手裡這枚白夜幣？客人真是目光敏銳，它對我意義非凡。不過也無妨，既然您如此好奇，就送給您吧。",
  str_voice_1602181_3 = "我一生中大多時間都在挑選商品和議價中度過。而客人您更需要——用寶貴的時間去開闢未來。",
  str_voice_1602181_4 = "我平常很少親自接待客人，不過您身上的確有著特別的魅力……尤其是結帳的瞬間呢～",
  str_voice_1602181_5 = "不同的選擇，不同的回報。生意和人生都是如此，這句話今天就免費送給客人您吧。",
  str_voice_1602181_6 = "窸窸窣窣，摸來摸去的樣子……就像隻可愛的小老鼠一樣。啊，客人您……養過寵物蛇嗎？",
  str_voice_1602181_7 = "躊躇又迷茫的客人呀……我會教您如何把錢變成喜歡的樣子，永遠留在身邊喔……",
  str_voice_1602181_8 = "如何？客人您挑到喜歡的商品了嗎？……我？呵呵……真是讓人困擾呀，我可是非賣品喔……",
  str_voice_1602181_9 = "生意夥伴？呵呵，您對我來說，可不只如此喔。",
  str_voice_1602181_10 = "客人您在發呆嗎？物價會漲，商機也會溜走喔。",
  str_voice_1602181_11 = "要我當您的祕書？可以喔，親愛的。我會一整——天一直教您賺錢技巧的。",
  str_voice_1602181_12 = "不買東西也沒關係，我很喜歡與客人談天說地——商機也許會在我們思想碰撞之間閃現喔。",
  str_voice_1602181_13 = "客人您太老實了，生意人的思路要更靈活一些才行呢。",
  str_voice_1602181_14 = "有人稱呼我為「貪婪之蛇」……我能理解他們為什麼會有這樣的看法，呵呵。那您呢？您眼中的我是什麼樣的？",
  str_voice_1602181_15 = "生日快樂，這是特地為您準備的禮物和優惠券……消費陷阱？呵呵，親愛的，您想太多了。",
  str_voice_1602181_16 = "歡迎光臨，親愛的。浮空商會永遠歡迎您這樣高貴又有品味的客人。",
  str_voice_1602181_17 = "稍等一下喔，還沒到營業時間。呵呵，您還真是心急。",
  str_voice_1602181_18 = "工作餐？不不不，我替您準備了更好的選擇……",
  str_voice_1602181_19 = "要體驗一下浮空商會特製的羽絨床墊嗎？來這邊，親愛的。",
  str_voice_1602181_20 = "影鎮是適合商業發展的沃土，也是適合罪惡孳生的溫床。",
  str_voice_1602181_21 = "他們未免有些太過大驚小怪。浮空商會區區幾艘飛空艇，怎麼會對那座「不落之城」造成威脅？您說呢？",
  str_voice_1602181_22 = "影子在注視著你。",
  str_voice_1602181_23 = "如果能轉變成利益的話，即使是暗鬼……哈哈，您怎麼又當真了呢？",
  str_voice_1602181_24 = "您對影主伊斯塔萬感興趣？呵呵，想知道情報的話，需要付出一點點代價。",
  str_voice_1602181_25 = "信使公會其實非常值得投資。至於盈利原理……未來有有機會再告訴您。",
  str_voice_1602181_26 = "賺錢是我的樂趣，但我最喜歡以花錢為樂趣的客人唷。",
  str_voice_1602181_27 = "我怎麼會討厭做買賣呢？不過，說起來……的確有一種買賣我不太喜歡：賠本買賣。",
  str_voice_1602181_28 = "有朝一日，想把巨像這樣的商品擺在浮空商會的櫃檯呢。",
  str_voice_1602181_29 = "我是浮空商會會長——涉。憑我們的關係，就不用再說更多了吧，親愛的？",
  str_voice_1602181_30 = "明智的投資。",
  str_voice_1602181_31 = "我們的合作還能更深入。",
  str_voice_1602181_32 = "商會的大門向您敞開。",
  str_voice_1602181_33 = "您是我的股東了。",
  str_voice_1602181_34 = "準備開張。",
  str_voice_1602181_35 = "聽到錢的聲音了～",
  str_voice_1602181_36 = "戰略佈局——",
  str_voice_1602181_37 = "出手要準。",
  str_voice_1602181_38 = "這裡，是我的了～",
  str_voice_1602181_39 = "抓住商機！",
  str_voice_1602181_40 = "出奇制勝！",
  str_voice_1602181_41 = "一起大賺一筆吧。",
  str_voice_1602181_42 = "謝謝惠顧～",
  str_voice_1602181_43 = "是事前調查失誤嗎……",
  str_voice_1602181_44 = "浮空商會還有不少好看的家具，正適合放在這裡呢。",
  str_voice_1602181_45 = "送給我？謝謝您。",
  str_voice_1602181_46 = "您把錢花對地方了～",
  str_voice_1602181_47 = "您是不是有求於我？",
  str_voice_1602181_48 = "我不會白收您的禮物。",
  str_voice_1602181_49 = "別的不敢說，但從無到有建立起大型商會的人……在整個影鎮裡，我應該也排得上前幾名呢。",
  str_voice_1602181_50 = "何必提及那些無法挽回的往事呢？此刻在我面前的客人您才是最重要的，不是嗎？",
  str_voice_1602181_51 = "親愛的，金錢的流動就如同血液，要活絡運轉才能帶來活力。換句話說，浮空商會就是推動社會繁榮的引擎！",
  str_voice_1602181_52 = "白夜極光。",
  str_voice_1602181_53 = "您好，客人。",
  str_voice_1602181_54 = "早安，親愛的。",
  str_voice_1602181_55 = "要來浮空商會坐坐嗎？",
  str_voice_1602181_56 = "睡了嗎？親愛的。",
  str_voice_1602181_57 = "新年快樂。浮空商會的歷史又增長了一年，我們的友誼也是如此，親愛的。",
  str_voice_1602191_1 = "我下棋的風格變了？直率、冒險、激進……這一直是我的風格，只不過被埋在影子之下而已。",
  str_voice_1602191_2 = "將滿腔熱血揮灑殆盡，往往是年輕人容易誤觸的陷阱。隱藏真正的實力，才是必要的計謀。",
  str_voice_1602191_3 = "我不願將傷疤視為勳章，而新的傷疤又層層疊在舊傷疤之上……它們早已化作我貼身的鎧甲，成為「我」的一部分。",
  str_voice_1602191_4 = "機關重重的「低語迴廊」，連影子本身進入也須小心提防。這是影子的惡作劇，無趣，但勝在刺激。",
  str_voice_1602191_5 = "「令人恐懼」是一股強大的力量，我不否認我擅長利用自己天生的優勢。",
  str_voice_1602191_6 = "傷痕披露在陽光下，力量也從那段被正視的往事中點滴浮現。影子……不該對自己也隱藏真意。",
  str_voice_1602191_7 = "你喜歡我衣櫃裡的西裝革履？那些光鮮的行頭，其實是我最好的隱身衣，讓我成為真正的影子……",
  str_voice_1602191_8 = "我窖藏了許多與你同歲的佳釀，等你能夠品味歲月之日，便是我開瓶替你祝賀之時。不，還不是現在，要學會等待。",
  str_voice_1602191_9 = "你下棋的風格很像我的一個老朋友。曾經，我沒能留住他……現在，我不會讓同樣的事在你身上重演。",
  str_voice_1602191_10 = "哈哈，思考是個好習慣，但發呆可不是喔。",
  str_voice_1602191_11 = "每道傷痕都是我的眼睛。我會和它們一起，幫你監管這方天地。",
  str_voice_1602191_12 = "沒有「底線」不需要爭取，沒有「改變」不需要戰鬥。你應該早就明白，遠離暗鬼的世界同樣適用這個規則。",
  str_voice_1602191_13 = "能力出眾卻有著失控風險的孩子們……我不想讓他們經歷我曾經歷的。你若小上幾歲，我也很樂意收養你。當然，現在也不晚。",
  str_voice_1602191_14 = "規則的守護者無須知道太多建立規則的骯髒祕聞……你們只管前進。影子，會目送你們遠行。",
  str_voice_1602191_15 = "許個願吧，我會幫你實現。",
  str_voice_1602191_16 = "行動之前別忘記思考，以及……不要輕易被人發現你在思考什麼。",
  str_voice_1602191_17 = "年輕人，在該沐浴朝陽的時候就去沐浴——這便是我化身為影的目的。",
  str_voice_1602191_18 = "不去休息嗎？怎麼，你想瞭解更多我過去的混沌故事？",
  str_voice_1602191_19 = "呃......你還醒著？讓你見笑了。這些傷痕，總是在這時候強調它們的存在感。",
  str_voice_1602191_20 = "我會讓影鎮擁有更穩固的秩序……無論還要付出多少代價。",
  str_voice_1602191_21 = "北境之所以能成為所有人心中的避難所，也許都該歸功於那位繼承並維護著純白秩序的女王。",
  str_voice_1602191_22 = "影子，仍會注視著你。",
  str_voice_1602191_23 = "對付暗鬼往往不需要動腦，相信我，這未嘗不是一種紓壓方式。",
  str_voice_1602191_24 = "貝菲爾......她並不像我，所以她才能站在陰影之上。這是件好事。",
  str_voice_1602191_25 = "哈哈，莉奧娜倒是有幾分像年輕時的我。她心中的執念甚至比我更深。",
  str_voice_1602191_26 = "沒有人不喜歡贏，我也是——無論是棋局還是人生。",
  str_voice_1602191_27 = "當你真正成為影子的一部分，你就會發現自己變得比以往都還要寬容。",
  str_voice_1602191_28 = "你要學會在巨像上留一個誰都不知道的隱蔽角落給自己。對，連我也不要說。",
  str_voice_1602191_29 = "嗯，是該向你道賀。現在你知道了，影子誕生於混沌。於混沌之中，沒有人能全身而退。",
  str_voice_1602191_30 = "還遠不到影子的極限。",
  str_voice_1602191_31 = "這，是付出代價的回報。",
  str_voice_1602191_32 = "影子更深了。",
  str_voice_1602191_33 = "影子的承諾，一如既往。",
  str_voice_1602191_34 = "是該活動一下筋骨了。",
  str_voice_1602191_35 = "傷痕已經滾燙。",
  str_voice_1602191_36 = "那就讓他們見識一下。",
  str_voice_1602191_37 = "直視我——！",
  str_voice_1602191_38 = "毀滅，才能新生！",
  str_voice_1602191_39 = "喝啊——！",
  str_voice_1602191_40 = "把頭抬起來！",
  str_voice_1602191_41 = "跟我走吧。",
  str_voice_1602191_42 = "他們早該明白自己的下場。",
  str_voice_1602191_43 = "不過是添道新的傷痕。",
  str_voice_1602191_44 = "嗯？每次來巨像，都能看到新的變化。",
  str_voice_1602191_45 = "你的品味……嗯，比當年的我更好。",
  str_voice_1602191_46 = "看來你已經學會了「投其所好」。",
  str_voice_1602191_47 = "要為這些禮物做個單獨的收藏櫃了。",
  str_voice_1602191_48 = "你比我身邊的人更懂我的喜好。",
  str_voice_1602191_49 = "舊的秩序尚未被打破之時，擁有惡魔長相的孩子，就算於陰影之中也無法討到善待。",
  str_voice_1602191_50 = "任何人都有不同的一面。你所看到的我，也只是我想讓你看到的樣子。",
  str_voice_1602191_51 = "想要改變混亂的秩序？那麼，你得先成為混亂的一部分。",
  str_voice_1602191_52 = "白夜極光。",
  str_voice_1602191_53 = "我的朋友。",
  str_voice_1602191_54 = "早。",
  str_voice_1602191_55 = "你需要休息。",
  str_voice_1602191_56 = "隱於夜色。",
  str_voice_1602191_57 = "舉杯吧，哪怕是影子也要慶祝新年。",
  str_voice_1502201_1 = "嗚啊！你、你怎麼突然就出現了？我專心工作的時候，請、請你從二十公尺外就開始咳嗽、吹口哨、用力踏步！",
  str_voice_1502201_2 = "哥哥，這塊蛋糕我可以先吃一口嗎，一口就好……哇，這盤子的花紋，是我只有在書裡看過的空裔樣式！放大鏡、我的放大鏡呢？",
  str_voice_1502201_3 = "「鑑定古董是高強度的腦力工作，你必須比製造贗品的人吃得更多！」出自《鑑定師入門手冊》。咦，你怎麼知道這本書的作者是我？",
  str_voice_1502201_4 = "嗚哇，我操縱光能的力量是不是變強了？好險好險，幸好沒傷到珍貴的古畫。",
  str_voice_1502201_5 = "力量……力量在不斷湧現！我現在走進坐滿人的房間也沒問題！呃……錯覺，一定是錯覺。",
  str_voice_1502201_6 = "PlayerName哥哥也覺得我變強了？果然攝取糖分不會背叛我們！這堆點心，分你三……四分之一吧！你、你不會嫌棄吧……",
  str_voice_1502201_7 = "糖松木、活動榫卯、古迦南外框……完美。嗚哇！沒、沒事，我只是想替你的肖像畫配一個上好畫框！咦，你沒有肖像畫？我、我可以幫你介紹畫家喔！",
  str_voice_1502201_8 = "PlayerName哥哥常常來找我玩呢……什麼？我、我怎麼會嫌你煩？我很高興，以後也請你常來……呃，這不是在要求你喔！沒空來也沒關係……",
  str_voice_1502201_9 = "我一直以為陌生人只會害我恐慌，直到認識你……PlayerName哥哥，我常常覺得，如果我有一個哥哥，應該會像你一樣吧……",
  str_voice_1502201_10 = "哥哥，你該不會睡著了吧？不是昨天才剛睡過覺嗎？",
  str_voice_1502201_11 = "這裡太亮了，我要融化了……咦，你需要我幫你看門？好、好吧。裝成好人接近你的「假貨」，我會全部揪出來的……盡量。",
  str_voice_1502201_12 = "哇，你說什麼？我被列入藝術法庭的《鑑定師名冊》，必須出庭提供專家意見？不不不，我不要去！除非你陪我……嗚，我是不是太煩人了？",
  str_voice_1502201_13 = "你要幫我搬古董？謝謝你！……啊，果然還是太重了？沒關係，我自己來。哥哥，你……你得多攝取一些糖分呀。",
  str_voice_1502201_14 = "嗚……今天只吃了三十七頓點心，餓得頭昏眼花，有點撐不住了……",
  str_voice_1502201_15 = "生日快樂！生、生日派對什麼的就不用找我了，但是蛋糕可以送到我房間喔……可以嗎？",
  str_voice_1502201_16 = "哥哥好！人來人往的時段總是讓我有點煩躁，但你都很有精神，有什麼祕訣嗎？",
  str_voice_1502201_17 = "晚安……咦，已經早上了？欸嘿嘿嘿，在你身邊工作很安心，時間總是過得特別快。",
  str_voice_1502201_18 = "天黑了嗎？不要緊，我還可以繼續工作……哥哥也要和我一起嗎？",
  str_voice_1502201_19 = "哥哥快去睡吧，我還不想睡。啊，你說什麼？不睡覺會長不高？嗚啊，原來我是因為這樣才……",
  str_voice_1502201_20 = "影鎮的歷史複雜，故事一層疊著一層，如同埋藏文物的地層……很、很合我胃口。",
  str_voice_1502201_21 = "在白夜城流通的贗品一定很多！因為……那裡的鑑定師沒什麼眼光，顧客也只會附庸風雅。",
  str_voice_1502201_22 = "影子在注視著你……鑑定師也在注視著你！",
  str_voice_1502201_23 = "暗鬼不是「真貨」，而是某種仿製品，他們……嗚哇，沒、沒有什麼確切證據啦，只是直、直覺……",
  str_voice_1502201_24 = "哥哥，這是我從龍州來的朋友「阿龍」，你看它寶石般的漆面……咦，你說這只是一把檀木椅子？對呀，有什麼問題嗎？",
  str_voice_1502201_25 = "艾爾戈絲姐姐是影鎮最厲害的收藏家，眼力、品味無懈可擊。她相中的東西絕不會有錯。",
  str_voice_1502201_26 = "博物館展出了新的藏品？！太好了！我們什麼時候出發？明天？還是……今天就去吧！",
  str_voice_1502201_27 = "我、我今天跟三個人說過話，社交能量已經見底了！",
  str_voice_1502201_28 = "巨像是空裔文明的心血結晶！它的形象、色彩、花紋……不行不行，我要住下來研究個夠！",
  str_voice_1502201_29 = "初、初次見面，我叫維吉爾，喜歡古董。你好、再見……等等，你的服裝是空谷的樣式……你是那個剛出土的空裔！",
  str_voice_1502201_30 = "洞察一切真偽！",
  str_voice_1502201_31 = "我看得更清楚了。",
  str_voice_1502201_32 = "遠古的智慧與我同在。",
  str_voice_1502201_33 = "萬千虛假，無所遁形！",
  str_voice_1502201_34 = "嗚哇，人好多！",
  str_voice_1502201_35 = "糖分補充完畢！",
  str_voice_1502201_36 = "讓、讓我再靠近一點觀察嘛。",
  str_voice_1502201_37 = "瑕疵品……別想蒙混過關！",
  str_voice_1502201_38 = "至少還有七處破綻。",
  str_voice_1502201_39 = "統統現出原形！",
  str_voice_1502201_40 = "逃不過我的眼睛。",
  str_voice_1502201_41 = "要我指揮這麼多人，真的沒問題嗎？",
  str_voice_1502201_42 = "鑑定完畢，全部都是瑕疵品。",
  str_voice_1502201_43 = "難道……我的力量不是「真貨」？",
  str_voice_1502201_44 = "這座巨像……隨便我觀察？！這、這種好事是真的嗎？！",
  str_voice_1502201_45 = "禮物？不是要委託我鑑定啊……",
  str_voice_1502201_46 = "這個東西……！得和我最珍貴的藏品擺在一起！",
  str_voice_1502201_47 = "謝謝你的禮物，讓我見識到古董之外的魅力。",
  str_voice_1502201_48 = "哇啊！鑑定完畢，哥哥對我的瞭解，貨真價實！",
  str_voice_1502201_49 = "我、我才不是什麼「天才鑑定師」，只不過是在還沒懂事前，就整天和古董、名畫待在一起，久而久之自然就知道怎麼識真辨偽啦。",
  str_voice_1502201_50 = "為什麼小小年紀就出來工作？唔，其實是我捨不得古董店裡的那些「朋友」……",
  str_voice_1502201_51 = "有些贋畫師，比真正的名畫家還要有才華。那美妙的混色，慧黠的情思，大膽的概括，全都——啊，對、對不起，我又自顧自講起來了。",
  str_voice_1502201_52 = "白、白夜極光……！",
  str_voice_1502201_53 = "PlayerName哥哥！",
  str_voice_1502201_54 = "嗚哇，天又亮了……",
  str_voice_1502201_55 = "午安……！問、問候完畢。",
  str_voice_1502201_56 = "哥哥，晚安！",
  str_voice_1502201_57 = "咦，新年到了？新年快樂！新年晚會……人很多吧？不過，只要哥哥在，我、我可以忍耐！我們走吧……！",
  str_voice_1602211_1 = "我提出這麼多問題，是為了確保我能按照你的類型系統執行指令，使我的回答符合你的預期，藉此提高彼此的溝通效率。",
  str_voice_1602211_2 = "科學家必須瞭解自身的智力侷限，透過環境啟迪喚醒內在智慧。唯有如此，我們才能跟上世界惡化的速度。",
  str_voice_1602211_3 = "和布林相識不是命運使然，純屬巧合。正是大家的思維慣性讓我顯得更加怪異。不過……怪就怪吧，我喜歡自己的怪異！",
  str_voice_1602211_4 = "啊？研究本身就是我身為科學家最高、最極致的追求！成本、價值、用途什麼的……不是我關心的事。",
  str_voice_1602211_5 = "布林竟然能在視覺中聽見音樂，在聲音中看見色彩流轉！這就是所謂光靈才有的「聯覺」天賦啊，厲害！真厲害！",
  str_voice_1602211_6 = "從前我難以理解他人，他人也難以理解我……所以我住到這個「與世隔絕的地方」。互不接觸後，反而能夠相互理解了……",
  str_voice_1602211_7 = "堅持研究遠古人工智慧的原因嗎……大概是對遠古人類感到困惑，也好奇光靈的未來吧。輪到你說了。",
  str_voice_1602211_8 = "喔，有空再去醫療中心做個腸胃檢查吧。畢竟你常常在天上飛來飛去，腸道健康和消化問題一定很多……",
  str_voice_1602211_9 = "在危難時刻，內心深處的信念往往會在腦海中清晰浮現。所以你那句「守護擁有的一切」……咳，倒是沒有讓我太驚訝喔。",
  str_voice_1602211_10 = "如果根據情緒的三種表達方式來分類，即開心、難過、無所謂……這種分類能夠解釋日蝕語和程式語言之間的關聯嗎？",
  str_voice_1602211_11 = "一聽到你需要幫手，布林就躁動不已。喔，我不擅長多人合作，你去和布林交流吧，它會全力配合的！欸？睡著了……？",
  str_voice_1602211_12 = "試想如果那是一個科技至上的時代，記憶或許能與記錄劃上等號。因為資訊就是力量，知道的越多，也就越強大。",
  str_voice_1602211_13 = "歷史不是事實，文化也不是由枯燥的資料組成。就算它記錄下世上所有資料，達到所謂的「全知」，也不代表我們要走相同的道路。",
  str_voice_1602211_14 = "在戰鬥中，與其過分強調光能術的觸發儀式，不如研究光能的本質。在我的程式中，觸發儀式不過是幾行不起眼的程式碼而已。",
  str_voice_1602211_15 = "生日？不急的話，明天過也沒關係吧？",
  str_voice_1602211_16 = "一邊工作一邊健身很難嗎？你不試試看怎麼知道！",
  str_voice_1602211_17 = "這個咖啡杯會根據我的精神狀況變色。果然，昨晚睡得很好！",
  str_voice_1602211_18 = "如此精美的程式碼，真希望你也能懂一點啊！",
  str_voice_1602211_19 = "時間是內在尺規。所以我說「現在還早」，你能理解嗎？",
  str_voice_1602211_20 = "一部機器和圍它而建的數座地下城……啟光能有今天，屬實是奇蹟。",
  str_voice_1602211_21 = "只是宿敵或許還簡單……能造出這種東西的存在，光靈於他何益呢？",
  str_voice_1602211_22 = "喔，「為了啟明之光」。原來到現在還在喊這種口號啊……",
  str_voice_1602211_23 = "畢竟面對暗鬼，光靈還沒真正贏過呢……哈哈，哈哈哈哈哈……",
  str_voice_1602211_24 = "嗯……那就布林吧。除了沒辦法完全弄懂它之外，沒什麼缺點。",
  str_voice_1602211_25 = "喬伊斯勉強算吧……不過我們大半年才會聯繫一次。你想問什麼？",
  str_voice_1602211_26 = "噪音？不覺得「嗡嗡嗡」的機器聲很助眠嗎？",
  str_voice_1602211_27 = "真是受不了！科學家就一定是沉悶無聊、不愛洗澡的禿頭瘋子嗎？",
  str_voice_1602211_28 = "據說巨像的骨架參考自遠古巨龍，這內部紋理多少也參考了一些吧？",
  str_voice_1602211_29 = "更新了五天五夜……就這樣？！啊？找阿爾戈爾？沒看到我正……喔！運動時間到了。說吧，找我什麼事？",
  str_voice_1602211_30 = "哇……提升很快嘛！",
  str_voice_1602211_31 = "新系統的表現不錯吧！",
  str_voice_1602211_32 = "再快一點……再快一點！",
  str_voice_1602211_33 = "布林也認可你的智慧！",
  str_voice_1602211_34 = "布林也等不及啦！",
  str_voice_1602211_35 = "準備執行程式！",
  str_voice_1602211_36 = "新建行程！",
  str_voice_1602211_37 = "執行程式！",
  str_voice_1602211_38 = "高速運轉！",
  str_voice_1602211_39 = "發送指令！",
  str_voice_1602211_40 = "覆寫資料！",
  str_voice_1602211_41 = "哈哈哈……交給我們吧！",
  str_voice_1602211_42 = "資料已建檔。",
  str_voice_1602211_43 = "正在尋找遺失檔案。",
  str_voice_1602211_44 = "嗯……嗯？喔，布林向你問好。",
  str_voice_1602211_45 = "我這……也沒什麼好送你的。",
  str_voice_1602211_46 = "這……！你真是聰明無比！",
  str_voice_1602211_47 = "嗯，塞我抽屜裡吧。",
  str_voice_1602211_48 = "奇怪奇怪……我竟然有種汗毛直豎的感覺！",
  str_voice_1602211_49 = "我曾完全依賴理性來分析和計算，於是有了「機器人」這個外號。但過度依賴大腦後，想要停下來並不像我想像中那樣容易。",
  str_voice_1602211_50 = "家人……當然是擔心我年紀太小會陷入所謂「資訊漩渦」。但我的天性就是這樣，我知道這是只有我才能完成的事情。",
  str_voice_1602211_51 = "起初，布林的行為捉摸不透，這種程度的「按摩」已經算好了。但相處久了，我漸漸能理解它透過「按摩」交流的智慧。",
  str_voice_1602211_52 = "喔，白夜極光。",
  str_voice_1602211_53 = "對了……",
  str_voice_1602211_54 = "通宵之後，神清氣爽！",
  str_voice_1602211_55 = "你在午休？",
  str_voice_1602211_56 = "夜晚是智慧的溫床！",
  str_voice_1602211_57 = "新年……嗯，新年快樂。",
  str_voice_1600024_1 = "離開雲山時，奶奶把這身櫻華一族的華服托付予我，希望族人的思念可以常伴左右……",
  str_voice_1600024_2 = "若有朝一日，我終將揭開封印，希望你也能像這般伴我身旁，為我見證。",
  str_voice_1600024_3 = "你都看到了……？別怕，這些繃帶下的傷痕和代表的往事都已經過去了。",
  str_voice_1600024_10 = "打擾？當然沒有。是我選擇和你一起，靜靜待在這裡，聽風的聲音……呼……",
  str_voice_1600024_11 = "當我立於你身側，理應守護你不受任何邪惡之物的侵害……以櫻華與榮角之名起誓。",
  str_voice_1600024_12 = "我很高興，在擁有足以回到雲島的力量之前，還有其他地方能成為我的歸宿，比如啟光，比如你的所在。",
  str_voice_1600024_13 = "你是勇義之士，是值得信賴之人。和你相處這段時間，我已用身心確認無誤。",
  str_voice_1600024_14 = "櫻華與榮角的最後一人，空裔的最後一人……當我們並肩而行，應該就不算「一人」了吧？",
  str_voice_1600024_16 = "我就在這裡，你隨時都看得見的地方。",
  str_voice_1600024_17 = "早，我晨起的聲音吵醒你了……？沒有就好。",
  str_voice_1600024_18 = "晚餐我吃配給的乾糧就……呃，不是在拒絕你，既然你有安排，那我也沒理由辜負這份好意。",
  str_voice_1600024_19 = "你的手有些涼……夜深了，注意保暖。",
  str_voice_1600024_35 = "榮角刀在顫動。",
  str_voice_1600024_36 = "櫻龍，借我力量——",
  str_voice_1600024_37 = "無懼無畏——！",
  str_voice_1600024_38 = "散華寂滅——！",
  str_voice_1600024_39 = "喝！",
  str_voice_1600024_40 = "消散吧！",
  str_voice_1600024_44 = "不必顧慮我，我已經習慣這裡的生活了。",
  str_voice_1600024_58 = "早安。",
  str_voice_1600024_59 = "早，你應該不是被我吵醒的吧？",
  str_voice_1600024_60 = "要來參加晨練嗎？",
  str_voice_1600024_61 = "清晨的靜思，也是修行的一環。",
  str_voice_1600024_62 = "晚安，休息了嗎？",
  str_voice_1600024_63 = "你明天有計畫嗎？",
  str_voice_1600024_64 = "請問，你那裡有茶葉嗎？",
  str_voice_1600024_65 = "整日伏案工作，肩頸的負擔太大……",
  str_voice_1600024_66 = "晚安，希望櫻花的香氣能讓你安穩入睡。",
  str_voice_1600024_67 = "感謝你為我準備的刀具保養套組。",
  str_voice_1600024_68 = "可以介紹一下空裔的「溫德嵐節」嗎？",
  str_voice_1600024_69 = "往事盡沉故紙，初櫻方綻新春。",
  str_voice_1600024_70 = "不知道奶奶和獠過得怎麼樣了。",
  str_voice_1600024_71 = "我曾經也有很重的雲山口音呢。",
  str_voice_1500994_1 = "導航員，您……啊，穿這身裝束的時候，應該叫您……「公子」？",
  str_voice_1500994_2 = "龍洲的髮簪，明明也是鋒利的尖刺，佩戴在頭上卻是美麗的飾物……",
  str_voice_1500994_3 = "劍是武器，由使用者決定用途。我的魔劍將為守護城鎮，守護您而揮舞。",
  str_voice_1500994_10 = "袖子……沒有沾上污漬，下擺……也沒有破損，太好了。",
  str_voice_1500994_11 = "傭兵艾蕾雅，委託範圍已拓展至雙榭城。現在這身打扮……應該能與您並肩了。",
  str_voice_1500994_12 = "一直聽說絲綢會呼吸，現在穿在身上我才真的體會出來。",
  str_voice_1500994_13 = "魔劍在保護我，這一點我一直都曉得。但沒想到，我們之間還有那樣的關聯。",
  str_voice_1500994_14 = "現在有了更方便的衣服，也更加瞭解魔劍，我也更有資格協助您戰鬥了。今後也請您多多擔待囉。",
  str_voice_1500994_16 = "……我今天的工作？就是守在您身邊。您有什麼事需要我幫忙嗎？",
  str_voice_1500994_17 = "早安，能像您一樣自然地用肌膚迎接晨光，簡直像做夢一樣。",
  str_voice_1500994_18 = "工作結束了？那麼接下來您要去哪裡休息？我會為您值夜。",
  str_voice_1500994_19 = "雙榭城販售的禦寒披風，又輕又保暖，我一直想存錢買一件給您……",
  str_voice_1500994_35 = "魔劍在顫動。",
  str_voice_1500994_36 = "劍為君舞。",
  str_voice_1500994_37 = "魔劍，聚氣於身！",
  str_voice_1500994_38 = "魔劍，助我破陣！",
  str_voice_1500994_39 = "出劍！",
  str_voice_1500994_40 = "天荊地棘！",
  str_voice_1500994_44 = "我在雙榭城練習過口才，不知道聊天能力有沒有比較好……",
  str_voice_1500994_58 = "魔劍庇佑著我，我也會用魔劍保護更多人。",
  str_voice_1500994_59 = "沒想到荊棘開出的花，也會像紫藤一般美麗。",
  str_voice_1500994_60 = "龍洲人常說重劍無鋒，魔劍卻有鋒又有刺。",
  str_voice_1500994_61 = "那位少年醫師的藥很有用，雖然沒有解開詛咒，我還是很感謝他。",
  str_voice_1500994_62 = "先祖鑄劍時留下的心意，我不會忘記……",
  str_voice_1500994_63 = "穿著這身衣服，可以鑽窗、翻牆、揮劍，方便……也很美麗。",
  str_voice_1500994_64 = "我是不是該學學裁縫，好做一套合身的衣服給您呢。",
  str_voice_1500994_65 = "呃，在大家眼裡，我是個狂熱的披風愛好者嗎？",
  str_voice_1500994_66 = "不要緊，就算無法解開詛咒……我也會努力活下去！",
  str_voice_1500994_67 = "我有很多想報答的人，像是璇極小姐、丹棠小姐，還有您……",
  str_voice_1500994_68 = "嗯，從今以後，我是魔劍劍使，也是您的艾蕾雅。",
  str_voice_1500994_69 = "來到新的任務地點了，需要確認目標。",
  str_voice_1500994_70 = "魔劍啊，你要告訴我什麼？",
  str_voice_1500994_71 = "我，不會辜負這把劍上的思念！",
  str_voice_1500994_72 = "要帶什麼特產去給影鎮和巨像上認識的大家呢？",
  str_voice_1500994_73 = "這身衣服好輕透，想多活動一下。",
  str_voice_1500994_74 = "魔劍，你也感覺到了嗎？有惡意的氣息……",
  str_voice_1500994_75 = "嘿……哈……",
  str_voice_1500994_76 = "有東西！",
  str_voice_1602231_1 = "阿霓明白呀，你是這位巨靈的侍者，你能聽到很多聲音，但他的聲音最重要。",
  str_voice_1602231_2 = "阿霓平常住在海底。海淵裡，有上古時天人修建的洞府，裡面很涼快呢，就是有點破舊。",
  str_voice_1602231_3 = "海裡的東西有時會讓船失靈，開著開著就沉了……人好脆弱，要把他們每個都撈起來，阿霓也費了不少勁呢。",
  str_voice_1602231_4 = "阿霓這一身看起來很貴氣吧？因為換新銀票不方便，身上多掛點金銀首飾，就能隨時拿去典當啦。",
  str_voice_1602231_5 = "阿霓醒來發現好多東西都變了，雖然一覺醒來世界就變了好像不稀罕，但這次變得格外多……你能幫阿霓看看嗎？",
  str_voice_1602231_6 = "小PlayerName，今日別來無恙？呼……那便在這蒲團上坐下，與吾說說這異邦之事吧。",
  str_voice_1602231_7 = "阿霓的鱗片才不礙人，若是不信，你可以摸摸！",
  str_voice_1602231_8 = "你要看阿霓跳舞嗎？可以看，但是不要嫌棄喔。阿霓跳的舞太老了，都有幾千歲啦。",
  str_voice_1602231_9 = "吾乃護持之人，西海之主，布施龍佑之女，觀海之善女龍王。吾可護汝行船無阻，逢兇化吉……嗯，此言作數。",
  str_voice_1602231_10 = "天命龍女，降而生兆。萬里海闊，煙波浩渺。天佑龍女，百祿多福。如月之恆，如日之升……",
  str_voice_1602231_11 = "行啊，阿霓這就來！你是想叫我陪你玩……還是有要事想求善女龍王大人？",
  str_voice_1602231_12 = "好多西洋人，戲台上也開始有西洋戲了！連機巧物也變多了……什麼時候能重現始祖夢裡的高台廣廈呢。",
  str_voice_1602231_13 = "龍女鎮海舞？這個阿霓見過！請來好看的姑娘，在大台子上跳模仿阿霓的舞……！其實阿霓跳得根本不如她們。",
  str_voice_1602231_14 = "兆國的皇帝我不稀罕。阿霓看他也挺可憐的，還有什麼天天操心的大臣，被呼來喚去的侍衛……人活著麻煩事真多。",
  str_voice_1602231_15 = "往日常見信眾為吾祝誕，今日終有機緣，以吾意願為他人祝誕，妙哉！",
  str_voice_1602231_16 = "妳在寫什麼？快給阿霓看看……嗯～完全看不懂！",
  str_voice_1602231_17 = "唔，你起得好早……阿霓還想再睡一下……放心，不會睡到幾百年後的……",
  str_voice_1602231_18 = "辛苦你啦，小PlayerName！這是阿霓的貢品，也分你一份吃吃看？",
  str_voice_1602231_19 = "夜已深，你卻還要出門嗎？唉……可憐世人，所行不易。",
  str_voice_1602231_20 = "吾是否與你提起過龍洲得名的原因……？說過便好、便好……",
  str_voice_1602231_21 = "空谷之事，汝心甚哀，但吾以為生機尚存，莫要過分耽溺往事。",
  str_voice_1602231_22 = "天佑——龍洲——",
  str_voice_1602231_23 = "妖魔外道，豈堪一擊？邪王孽物，鬥之可降。",
  str_voice_1602231_24 = "不知你是否有遇見其他大祟靈？若是現在沒有，以後也定能遇到。",
  str_voice_1602231_25 = "龍是我的遠親，螭龍魚是龍的遠親，小月白是螭龍魚的遠親……就是我遠親的遠親的遠親？",
  str_voice_1602231_26 = "阿霓數數，有睡覺、戳氣泡、數小船、吃貢品……還能加好多新鮮東西。",
  str_voice_1602231_27 = "信眾所求，也有吾所不能成之事。生老病死為其一，名利糾葛為其二。",
  str_voice_1602231_28 = "吾聞遠古之音……巨靈巨靈，汝欲謂何？昔時之征，亦或今時之友？",
  str_voice_1602231_29 = "汝見阿霓，為何不拜？唉呀，這是暗語，不是叫你真的拜！就算久離塵俗，看熟人這樣也怪不好意思的……",
  str_voice_1602231_30 = "又來上供給阿霓啦？",
  str_voice_1602231_31 = "坐蓮台～",
  str_voice_1602231_32 = "塑金身～",
  str_voice_1602231_33 = "龍女臨世——",
  str_voice_1602231_34 = "汝求何事？",
  str_voice_1602231_35 = "龍女敕令——",
  str_voice_1602231_36 = "引眾生——",
  str_voice_1602231_37 = "如意神通——巧變。",
  str_voice_1602231_38 = "遊龍觀世——驚霆。",
  str_voice_1602231_39 = "鎮海之舞。",
  str_voice_1602231_40 = "金鱗伏浪。",
  str_voice_1602231_41 = "承龍之佑——",
  str_voice_1602231_42 = "都上岸了吧，阿霓就知道沒問題～",
  str_voice_1602231_43 = "日有短長，月有死生，無妨。",
  str_voice_1602231_44 = "還是人的樣子好，不然阿霓就進不來這樣的房間了。",
  str_voice_1602231_45 = "哇——這個，可以吃嗎？",
  str_voice_1602231_46 = "小PlayerName真乖！阿霓喜歡這個！",
  str_voice_1602231_47 = "所供之物頗為新奇，還請多多益善。",
  str_voice_1602231_48 = "此物令吾心甚悅，定要納入珍藏。",
  str_voice_1602231_49 = "龍洲萬物，均與始祖相襲。而吾乃始祖近親，在吾眼中，光靈祟靈、飛禽走獸，無甚高低之別。",
  str_voice_1602231_50 = "人子與祟靈亦有過從甚密之時。早年人曾依附於祟靈之側，供為圖騰，始能在荒蕪之地繁衍生息，初有國邦。",
  str_voice_1602231_51 = "吾常眠海淵，救助落水之人是偶爾為之。然沿海之民建我祠廟，呼我名諱，吾唯有守望相助，方不負鎮海之名。",
  str_voice_1602231_52 = "白夜極光。",
  str_voice_1602231_53 = "小PlayerName！",
  str_voice_1602231_54 = "呵——真早……",
  str_voice_1602231_55 = "岸上有什麼好玩的？",
  str_voice_1602231_56 = "夜已深，可需賜福？",
  str_voice_1602231_57 = "阿霓已經度過數不清個新年了，但和小PlayerName是第一次！你要什麼樣的祝福？阿霓的祝福可是龍佑喔。",
  str_voice_1502241_1 = "你在龍洲各地行走，要是碰到麻煩的祟靈就跟我說一聲，我來替你擺平。",
  str_voice_1502241_2 = "也得注意防騙，比如那些天天把天命、陰陽、祥瑞掛在嘴邊卻不做事的人……針對誰？不，沒有針對誰啊。",
  str_voice_1502241_3 = "龍洲鄉村常流行一些很離譜的祟靈上身故事。要我看，那大部分都是假的，祟靈才不會那麼閒去幹這種事。",
  str_voice_1502241_4 = "這是阿丁，就是平常被我扔出去戰鬥的傢伙……當然要扔出去啊，否則牠什麼時候才能練成牠想要的「鐵頭術」？",
  str_voice_1502241_5 = "教練？異邦大陸有這種說法啊。蠻好的，我喜歡當祟靈教練，比教人輕鬆。",
  str_voice_1502241_6 = "阿丁這樣的祟靈，還要修行很久才能獲得人形。你問多久？嗯，至少還要好幾百年吧。",
  str_voice_1502241_7 = "不要灰心，雖然你沒有能術天賦，但身體康健，手足靈敏，若是好好鍛鍊，定能有所成就！",
  str_voice_1502241_8 = "我的法術單論天賦也不怎樣，然而配上我這些年練出來的拳腳就有勁多了！",
  str_voice_1502241_9 = "如何，你也想和阿丁牠們練練吧？哈，不用對打，能把牠們順利舉起來、扔出去就行了！",
  str_voice_1502241_10 = "抱歉，阿丁牠們是不是吵到你了？我馬上叫那群小東西安靜。",
  str_voice_1502241_11 = "有什麼事需要我幫忙嗎？嗯，只是想摸摸小祟靈？可以是可以，牠們不會咬人，就是有點燙。",
  str_voice_1502241_12 = "原來異邦大陸沒有像「祟靈」這樣的生物，只有會用能術的異獸，和不太會用能術的獸頭人……有機會必要見識一下。",
  str_voice_1502241_13 = "話本小說裡常講祟靈修煉要「渡劫」的故事。這事半真半假，所謂的「渡劫」就是學會控制自己的能術，莫被反噬。",
  str_voice_1502241_14 = "書上說有教無類，師傅也說眾生平等，這理我認，所以我不管什麼大官還是小妖，賞善罰惡都是應當。",
  str_voice_1502241_15 = "送你，這是我準備的生辰賀禮！旁邊那些是阿丁牠們準備的，記得別生吃。",
  str_voice_1502241_16 = "天光正好，日頭高照，若是有祟靈想搗亂，八成不會選這時候。",
  str_voice_1502241_17 = "早～你這是在搬運輜重嗎？我來幫你，阿丁牠們也可以運一點。",
  str_voice_1502241_18 = "黃昏至人定，妖魔鬼怪出現的頻率就比白天高多了。",
  str_voice_1502241_19 = "尚未化人形的祟靈常依本性而動，深夜是不少祟靈的活動時間。",
  str_voice_1502241_20 = "龍洲天高海闊，有名頭的祟靈數不勝數。",
  str_voice_1502241_21 = "聽說在異邦大陸，狀似祟靈血統的身形很常見？",
  str_voice_1502241_22 = "降妖伏魔，本領所在。",
  str_voice_1502241_23 = "祟靈對妖魔的氣味比人還要敏感，不然一不小心就會被吃掉。",
  str_voice_1502241_24 = "等阿丁的鐵頭術練好了，我得幫牠想想下一步該練什麼。",
  str_voice_1502241_25 = "像厘青醫生那樣的祟靈，一看就知道很有教養，定有高人指導。",
  str_voice_1502241_26 = "要不要吃點菱角？",
  str_voice_1502241_27 = "有財主堅持要我助他的貓渡劫，我說那不是祟靈，只是貓，他還不聽。",
  str_voice_1502241_28 = "就算我走南闖北見識過不少稀奇事物，這我是真的從來沒見過。",
  str_voice_1502241_29 = "道士羅松，正下山遊歷，以降妖伏魔為業。這是祟靈阿丁和牠的夥伴們。",
  str_voice_1502241_30 = "強筋健骨是第一要務。",
  str_voice_1502241_31 = "法衣合身就好。",
  str_voice_1502241_32 = "護命符有備無患。",
  str_voice_1502241_33 = "天罡令多多益善。",
  str_voice_1502241_34 = "什麼東西在惹麻煩？",
  str_voice_1502241_35 = "有破綻！",
  str_voice_1502241_36 = "阿丁，機會來了。",
  str_voice_1502241_37 = "急急如律，百發百中！",
  str_voice_1502241_38 = "鐵頭術預備！",
  str_voice_1502241_39 = "炎之頭槌！",
  str_voice_1502241_40 = "阿丁出擊——",
  str_voice_1502241_41 = "噓，先觀察觀察。",
  str_voice_1502241_42 = "滿順利，還有空吃個茶。",
  str_voice_1502241_43 = "你先跑，牠們追不上來。",
  str_voice_1502241_44 = "阿丁，在別人家裡應該有素質一點，莫亂逛。",
  str_voice_1502241_45 = "多謝，說不定有用。",
  str_voice_1502241_46 = "這個好用，阿丁也喜歡。",
  str_voice_1502241_47 = "我收下了，改天也尋些好物給你。",
  str_voice_1502241_48 = "哎唷，這寶貝在哪找的？介紹一下呀。",
  str_voice_1502241_49 = "我在道觀長大。小時候爹媽覺得我被祟靈上身了才體質不好，其實沒這回事。",
  str_voice_1502241_50 = "師兄師姐傳下來的東西不多，在紙糊的符咒戲法和實在的功夫把式之間，我當然是選擇把式了。",
  str_voice_1502241_51 = "下山之後，我以替人降服祟靈為生，就是在這個過程中遇見了阿丁，開始教牠別踩莊稼，以及其他生存之道。",
  str_voice_1502241_52 = "白夜極光。",
  str_voice_1502241_53 = "我來也——",
  str_voice_1502241_54 = "早啊，吃過飯沒？",
  str_voice_1502241_55 = "阿丁麻煩你啦。",
  str_voice_1502241_56 = "再會，有空過來玩啊。",
  str_voice_1502241_57 = "新年快樂！不管是從哪裡來，不管是不是人，大家聚在一起還是很有氣氛，對吧？",
  str_voice_1701073_1 = "奇怪，最近總是做夢，真實又殘酷的夢。嗯？你是說……或許那並不是夢，而是我遺失的回憶？",
  str_voice_1701073_2 = "「艾德拉斯」，這就是我的名字啊……是你幫我找回來的？該說什麼好呢……多謝。",
  str_voice_1701073_3 = "一位獵兵勇往直前的鬥志永遠不會被削弱，無論發生任何事都不會。",
  str_voice_1701073_10 = "嗯？沒力氣說話了？是肚子餓了吧？有沒有小麥粉，我記得該如何烘烤麵包，味道不比你這裡的差，要吃吃看嗎？",
  str_voice_1701073_11 = "隨時為你效勞。",
  str_voice_1701073_12 = "這個世界最大的威脅依舊沒有改變嗎……不，我說的並不是暗鬼。",
  str_voice_1701073_13 = "守護民眾是我與生俱來的使命，即使曾經發生過那樣的事……我也不會放棄。",
  str_voice_1701073_14 = "你知道麥子熟透是什麼味道嗎？淡淡的香甜，隨著熱浪一滾一滾襲入鼻腔……那才是我再也無法企及的……美夢。",
  str_voice_1701073_16 = "沒有暗鬼的時候也不能鬆懈。現在我唯一的任務就是守護你，PlayerName。",
  str_voice_1701073_17 = "早！來吧，一起用飽滿的氣勢面對嶄新的一天！",
  str_voice_1701073_18 = "夜晚降臨的時候更要小心……不過這種事交給我就行了，你最重要的任務就是好好休息。",
  str_voice_1701073_19 = "睡吧，有我在，噩夢也別想靠近。",
  str_voice_1701073_35 = "放馬過來吧！！！",
  str_voice_1701073_36 = "別攔著我！！！",
  str_voice_1701073_37 = "想跑？！喝啊——！！！",
  str_voice_1701073_38 = "投降？太遲了——！",
  str_voice_1701073_39 = "來啊！！！",
  str_voice_1701073_40 = "衝啊——！！！",
  str_voice_1701073_44 = "可以在這裡種麥子嗎？",
  str_voice_1701073_58 = "暗鬼不過是群大腦簡單的生物罷了。",
  str_voice_1701073_59 = "永遠……不要留下被人利用的把柄。",
  str_voice_1701073_60 = "人生沒有後悔可言。",
  str_voice_1701073_61 = "善待你的摯愛，不要留下遺憾。",
  str_voice_1701073_62 = "「永生」是對我的懲罰。",
  str_voice_1701073_63 = "陷入瘋狂……也許是我曾經的遮羞布。",
  str_voice_1701073_64 = "或許我無法獨自守護所有民眾，但現在我還有你。",
  str_voice_1701073_65 = "這片大地上，已經沒有我故鄉的痕跡……",
  str_voice_1701073_66 = "歲月洗去曾經的恩怨，現在的我只是艾德拉斯。",
  str_voice_1701073_67 = "我曾在神殿前，許下永生永世的誓言。",
  str_voice_1701073_68 = "不能遲到……最重要的日子絕對不能遲到！",
  str_voice_1701073_69 = "瑪塞拉……不要嚇我，我親愛的瑪塞拉……",
  str_voice_1701073_70 = "大家看我的眼神為什麼……是我的錯覺嗎？",
  str_voice_1701073_71 = "我已經不再被大家需要了嗎……",
  str_voice_1701073_72 = "有瑪塞拉在身邊足矣。",
  str_voice_1701073_73 = "怎麼會這樣，不、不……",
  str_voice_1701073_74 = "別過來！！！放我走……放我離開！",
  str_voice_1701073_75 = "接下來該去哪裡？我的行程規劃呢？",
  str_voice_1701073_76 = "一、二、三——四！",
  str_voice_1701073_77 = "嗯？",
  str_voice_1701073_78 = "有狀況？別擔心，我去解決！",
  str_voice_1600264_1 = "等魔藥的時效結束，這身衣服也會化作火焰……你會循著最後一縷火光來追尋我嗎？",
  str_voice_1600264_2 = "你也想喝下這瓶魔藥嗎？不給……我只想要現在的你。",
  str_voice_1600264_3 = "你、你願意和我一起陷入淨界？那……拉起我的手，一起燃燒希望吧！",
  str_voice_1600264_10 = "不要走……！不然你再回來時，可能就只剩灰燼了……",
  str_voice_1600264_11 = "存在本無意義，但你讓我存在於此，這便有了意義……嗝！",
  str_voice_1600264_12 = "你比較喜歡令人憐惜的火苗，還是吞噬一切的烈焰？……不准回答！要是答錯了，魔藥會失效的！",
  str_voice_1600264_13 = "什麼末日啊！那種事我不想管了……既然一切最終都會迎來消亡，此刻就該更加放肆才對。",
  str_voice_1600264_14 = "這炙烈的火牢、燃燒的心臟，如果你能承受的話，送給你也沒關係……我，才沒有魔藥喝多……",
  str_voice_1600264_16 = "歡迎來到新一天的虛無～我們來一起創造意義吧。",
  str_voice_1600264_17 = "這個時間……你還要再睡一會嗎？還是說……要我為你燃燒夢鄉？",
  str_voice_1600264_18 = "晚餐？比起盤子裡的食物，我對面前端著盤子的人比較有興趣。",
  str_voice_1600264_19 = "可惡，明明喝了魔藥，人格都變化了，胸口怎麼還在痛？嗚嗚……救救我……",
  str_voice_1600264_35 = "淨界的獄門已經打開！",
  str_voice_1600264_36 = "抓緊我的手——",
  str_voice_1600264_37 = "一起走吧，去地獄的盡頭。",
  str_voice_1600264_38 = "一起去顛覆世界的末日吧。",
  str_voice_1600264_39 = "業火啊——",
  str_voice_1600264_40 = "淨界燒卻！",
  str_voice_1600264_44 = "我可以在這裡，和你一起等待時間的終結嗎？",
  str_voice_1600264_58 = "早安……！我很努力打起精神了。",
  str_voice_1600264_59 = "看到今天的日出了嗎？",
  str_voice_1600264_60 = "可以來我這裡嗎？",
  str_voice_1600264_61 = "呵——唔嗯……",
  str_voice_1600264_62 = "晚安……",
  str_voice_1600264_63 = "這麼早就要睡了嗎？",
  str_voice_1600264_64 = "又是一天結束了……",
  str_voice_1600264_65 = "「期待明天」？那你教我啊……",
  str_voice_1600264_66 = "胸口又開始痛痛了……",
  str_voice_1600264_67 = "我給阿姨買了禮物賠罪……",
  str_voice_1600264_68 = "你還記得父母的樣子嗎？",
  str_voice_1600264_69 = "你的巨像……好像比防爆桶舒適一點……",
  str_voice_1600264_70 = "有推薦的魔法書嗎？",
  str_voice_1600264_71 = "新的魔藥好像快要完成了……！",
  str_voice_1602251_1 = "儘管在這遼闊的北境，還沒有人能對女王陛下構成威脅。但是身為女王陛下的護衛，我會竭盡全力保護她。",
  str_voice_1602251_2 = "隨時隱匿行蹤，是我在雪林生活的本能。但在夜幕降臨之後，我也會爬到高高的樹梢，任自己暴露在北境的廣袤之中。",
  str_voice_1602251_3 = "有時候，我會偷偷觀察陌生人在雪地裡跌倒的樣子。他們總是慌亂掙扎，而我會在暗中偷笑。你能理解這其中的樂趣嗎？",
  str_voice_1602251_4 = "我身上流著北境的血液，所以每當我赤足踏在雪地上時，不會感覺到冷，反而能更深刻地感受到北境的力量。",
  str_voice_1602251_5 = "你應該看得出來，我是個不錯的獵手。無論是追逐還是潛伏，我都能抓住最佳時機，給予獵物致命一擊！",
  str_voice_1602251_6 = "你見過燈塔對嗎？長老說，北境的燈塔和生長在北境的三棵古樹有關。但我每次問她，她只是沉默地看向遠方。",
  str_voice_1602251_7 = "哈哈，你跑得這麼慢，看來我得背著你跑才行！別擔心，身為女王大人的護衛，照顧她的朋友也是我的職責！",
  str_voice_1602251_8 = "對著天空嗥叫，是我們表達喜悅和悲傷的方式。欸？你聽得出來差別？那……你可以試著叫兩聲給我聽嗎？",
  str_voice_1602251_9 = "比起冬宮，我更喜歡在部落附近欣賞極光。邊境處的極光總有一種獨屬於我的絢爛，你想和我一起去瞧瞧嗎？",
  str_voice_1602251_10 = "有一次，我怎麼也追不上一隻兔子，那兔子還頻頻回頭，彷彿在嘲笑我！後來我才知道，那兔子是諾維亞大人的……",
  str_voice_1602251_11 = "你這是打算雇我來這裡當護衛嗎？我勸你還是趁早打消這個念頭吧！喔，來做客？那沒問題……先警告你，我可不會見外唷。",
  str_voice_1602251_12 = "嘿，林中的朋友們，準備好一起玩了嗎？欸……我只是想嚇唬你們，看看你們的反應而已！怎麼都跑了……",
  str_voice_1602251_13 = "噓！看到石頭後面那個狡猾的傢伙了嗎？我數到三，我們一起抓牠個措手不及！一、二……喂！你怎麼不聽我的指令啊？！",
  str_voice_1602251_14 = "因為北境信仰萬物有靈，自然會流傳著許多美麗的傳說。關於北境的起源……你聽過「三棵松樹」的傳說嗎？",
  str_voice_1602251_15 = "生日快樂！按照部落的風俗，我還要恭喜你長出新的皺紋。",
  str_voice_1602251_16 = "女王陛下今天出門去了，特別讓我放了一天假。咱們要做些什麼好呢？",
  str_voice_1602251_17 = "呼！我現在才發現身上結了一層冰。去見女王陛下之前，我得好好整理一下！",
  str_voice_1602251_18 = "我、我正在追、追北境跑得最快的光靈！無論如何，我一定要追上他！",
  str_voice_1602251_19 = "我相信，那些總說自己太忙太累的人，一定會錯過許多美麗的風景。",
  str_voice_1602251_20 = "北境之外的世界或許絢爛多彩，但我更喜歡這裡的簡單自在。",
  str_voice_1602251_21 = "笨蛋！叫你那些身上帶著奇怪東西的朋友別靠近長老！",
  str_voice_1602251_22 = "暮冬而生。",
  str_voice_1602251_23 = "牠們奪走了我寶貴的東西，所以我理解你。我會和你一起奪回來！",
  str_voice_1602251_24 = "女王陛下是如此強大。成為她的護衛，是我最自豪的身分……",
  str_voice_1602251_25 = "有時候，我忍不住想稱呼長老為「太奶奶」，因為她倆給我一種相似的感覺。",
  str_voice_1602251_26 = "爬樹、狩獵，還有在雪地裡奔跑……你身邊有喜歡這些的朋友嗎？",
  str_voice_1602251_27 = "對於隨意闖入我們部落的陌生人，僅僅是教訓一頓也太便宜他們了！",
  str_voice_1602251_28 = "這裡雖然裝飾得溫馨舒適，但總覺得缺少了一些大自然的野性呢……",
  str_voice_1602251_29 = "我是提亞拉，北境女王的護衛，也是雪狐部落的首領。在此提醒你，北境不是遊樂場，部落更不是你能隨意進入的地方！",
  str_voice_1602251_30 = "這就是自然之力嗎？",
  str_voice_1602251_31 = "血液沸騰的感覺！",
  str_voice_1602251_32 = "我是女王陛下的護衛！",
  str_voice_1602251_33 = "我是北境的護衛！",
  str_voice_1602251_34 = "提亞拉，奉命前來！",
  str_voice_1602251_35 = "聚力冰尖之上！",
  str_voice_1602251_36 = "跟上我的速度！",
  str_voice_1602251_37 = "為了北境的安寧！",
  str_voice_1602251_38 = "自然之力，發動！",
  str_voice_1602251_39 = "往哪裡跑！",
  str_voice_1602251_40 = "區區暗鬼！",
  str_voice_1602251_41 = "現在，由我來保護你！",
  str_voice_1602251_42 = "女王陛下一定會高興的！",
  str_voice_1602251_43 = "暫時……不要告訴女王陛下。",
  str_voice_1602251_44 = "不是我！唔……我是說，我沒聽到任何奇怪的聲音。",
  str_voice_1602251_45 = "這是用來做什麼的？",
  str_voice_1602251_46 = "喜歡！",
  str_voice_1602251_47 = "你的小玩意還真多！",
  str_voice_1602251_48 = "我好喜歡！",
  str_voice_1602251_49 = "我出生在邊境的一個部落裡，從小便與太奶奶、雪狐住在一起。至於我的父母，我只知道他們是了不起的北境護衛。",
  str_voice_1602251_50 = "我曾經在山林中遭遇雪崩，是女王陛下救了我的命，還修好我的長矛。從那時起，我就決定要永遠效忠女王陛下。",
  str_voice_1602251_51 = "我還記得那個夜晚，長老和我在洞穴中聽著雪狐的呼嘯聲沉默不語。那時，我還無法理解「守護」的意義。",
  str_voice_1602251_52 = "白夜極光。",
  str_voice_1602251_53 = "怎麼辦……",
  str_voice_1602251_54 = "早安。",
  str_voice_1602251_55 = "午安。",
  str_voice_1602251_56 = "晚安。",
  str_voice_1602251_57 = "新年快樂。北境和女王陛下會繼續庇佑你的。",
  str_voice_1202261_1 = "呱呱呱呱！",
  str_voice_1202261_2 = "呱呱呱呱！",
  str_voice_1202261_3 = "呱呱呱呱！",
  str_voice_1202261_4 = "呱呱呱呱！",
  str_voice_1202261_5 = "呱呱呱呱！",
  str_voice_1202261_6 = "呱呱呱呱！",
  str_voice_1202261_7 = "呱呱呱呱！",
  str_voice_1202261_8 = "呱呱呱呱！",
