  str_voice_1202261_21 = "呱呱呱呱！",
  str_voice_1202261_22 = "呱呱呱呱！",
  str_voice_1202261_23 = "呱呱呱呱！",
  str_voice_1202261_24 = "呱呱呱呱！",
  str_voice_1202261_25 = "呱呱呱呱！",
  str_voice_1202261_26 = "呱呱呱呱！",
  str_voice_1202261_27 = "呱呱呱呱！",
  str_voice_1202261_28 = "呱呱呱呱！",
  str_voice_1202261_29 = "呱呱呱呱！",
  str_voice_1202261_30 = "呱呱呱呱！",
  str_voice_1202261_31 = "呱呱呱呱！",
  str_voice_1202261_32 = "呱呱呱呱！",
  str_voice_1202261_33 = "呱呱呱呱！",
  str_voice_1202261_34 = "呱呱呱呱！",
  str_voice_1202261_35 = "呱呱呱呱！",
  str_voice_1202261_36 = "呱呱呱呱！",
  str_voice_1202261_37 = "呱呱呱呱！",
  str_voice_1202261_38 = "呱呱呱呱！",
  str_voice_1202261_39 = "呱呱呱呱！",
  str_voice_1202261_40 = "呱呱呱呱！",
  str_voice_1202261_41 = "呱呱呱呱！",
  str_voice_1202261_42 = "呱呱呱呱！",
  str_voice_1202261_43 = "呱呱呱呱！",
  str_voice_1202261_44 = "呱呱呱呱！",
  str_voice_1202261_45 = "呱呱呱呱！",
  str_voice_1202261_46 = "呱呱呱呱！",
  str_voice_1202261_47 = "呱呱呱呱！",
  str_voice_1202261_48 = "呱呱呱呱！",
  str_voice_1202261_49 = "呱呱呱呱！",
  str_voice_1202261_50 = "呱呱呱呱！",
  str_voice_1202261_51 = "呱呱呱呱！",
  str_voice_1202261_52 = "呱呱呱呱！",
  str_voice_1202261_53 = "呱呱呱呱！",
  str_voice_1202261_54 = "呱呱呱呱！",
  str_voice_1202261_55 = "呱呱呱呱！",
  str_voice_1202261_56 = "呱呱呱呱！",
  str_voice_1202261_57 = "呱呱呱呱！",
  str_voice_1601774_1 = "呵呵呵……沒什麼，只是看見你在我身邊，覺得很開心～",
  str_voice_1601774_2 = "經紀人、經紀人、經紀人——你得快點習慣這個稱呼唷～",
  str_voice_1601774_3 = "你知道嗎？我有時候真的很怕黑，但只要有你在，我就什麼都不怕了。",
  str_voice_1601774_10 = "一閃一閃亮晶晶～你是最耀眼的星～",
  str_voice_1601774_11 = "歌爾蒂，降臨——想我了嗎？經、紀、人～",
  str_voice_1601774_12 = "要來玩扮家家酒嗎？我是媽媽，你是爸爸，再加上棉花糖，鏘鏘——我們是三口之家～",
  str_voice_1601774_13 = "等等，不要動……嗯，這個身高、尺寸……我可以把你的樣子做成等身抱枕嗎？這樣就能一直感覺到這份溫暖了～",
  str_voice_1601774_14 = "穿久了演出用的服裝，偶爾穿這種軟綿綿的睡衣也不錯——尤其是還有你和我一起穿，嘿嘿～",
  str_voice_1601774_16 = "準備好開始今天的工作了嗎，PlayerName？喔，今天應該叫你「經紀人」～",
  str_voice_1601774_17 = "呼啊～早，不想跟我再多睡一會嗎？",
  str_voice_1601774_18 = "工作這麼久辛苦啦。來，我要給你一點獎勵～",
  str_voice_1601774_19 = "一天就要結束了嗎……？那，我們一起做個美夢吧。",
  str_voice_1601774_35 = "夢境演唱會，開始囉～",
  str_voice_1601774_36 = "夢中的朋友，你們好嗎——",
  str_voice_1601774_37 = "讓我看到你們的雙手！",
  str_voice_1601774_38 = "和我一起唱！",
  str_voice_1601774_39 = "噢——耶！",
  str_voice_1601774_40 = "代表夢境消滅你！",
  str_voice_1601774_44 = "我想在這裡舉行睡衣演唱會，可以嗎，經紀人？",
  str_voice_1601774_58 = "Do—Re—Mi—Fa—So—La—Ti—Do——",
  str_voice_1601774_59 = "早安，經紀人！",
  str_voice_1601774_60 = "經紀人，再不起床就趕不上今天的行程了！",
  str_voice_1601774_61 = "早安！每一天的你，都是全新的自己！",
  str_voice_1601774_62 = "要我唱搖籃曲給你聽嗎？",
  str_voice_1601774_63 = "今天舞台上的我，是不是閃閃發光？",
  str_voice_1601774_64 = "棉花糖好像想跟你一起睡。",
  str_voice_1601774_65 = "晚安，經紀人～",
  str_voice_1601774_66 = "穿著睡衣，不知不覺就想睡了……",
  str_voice_1601774_67 = "哈～哈～剛才的舞，跳得怎麼樣？",
  str_voice_1601774_68 = "即使在家穿著睡衣，練習也不能鬆懈呀！",
  str_voice_1601774_69 = "棉花糖——你在哪？",
  str_voice_1601774_70 = "咳咳，經紀人，我的喉嚨……",
  str_voice_1601774_71 = "關於新歌，你有什麼想法嗎？",
  str_voice_1602233_1 = "為君繫彩縷，五色續千春。",
  str_voice_1602233_2 = "如果是小PlayerName的話，向阿霓許個稍微任性點的願望也不是不行喔。",
  str_voice_1602233_3 = "點心很好吃，遊戲很有趣。世間廣大，樂事無窮，何苦非去做話本子裡那種餐風沐雨的神仙？",
  str_voice_1602233_10 = "避水、禦寒、防暑……衣服上還能施加什麼庇護呢？難得收到的禮物，要好好保管才行～",
  str_voice_1602233_11 = "嗯！這裡風好，光好，有你在，超好！是個值得記住的好日子～",
  str_voice_1602233_12 = "只在這裡偷偷說喔。小PlayerName，你一定要活久一點，和阿霓一起去做更多有趣的事。",
  str_voice_1602233_13 = "向吾祈願者心中多懷嗔癡貪念，如你這般純粹的心意，實屬難得。",
  str_voice_1602233_14 = "光靈、祟靈，不論壽命長短，在無垠宇宙間，皆如滄海一粟，無甚差別。我們都只享有世界的一刹罷了。",
  str_voice_1602233_16 = "向阿霓許願的人有很多，但為阿霓許願的，你還是第一個。",
  str_voice_1602233_17 = "今天天氣如何？不喜歡的話，阿霓幫你換一個！",
  str_voice_1602233_18 = "龍洲的星宿啊……其中有一顆星子，名叫「辰」喔。",
  str_voice_1602233_19 = "這麼晚還不好好休息可不行。沒辦法，阿霓來保佑你身體健康吧～",
  str_voice_1602233_35 = "五色俱備。",
  str_voice_1602233_36 = "成汝所願。",
  str_voice_1602233_37 = "龍行——萬潮湧。",
  str_voice_1602233_38 = "一念——蓮華生。",
  str_voice_1602233_39 = "悠然遊世～",
  str_voice_1602233_40 = "樂聞音。",
  str_voice_1602233_44 = "小PlayerName不是信眾，而是朋友，對吧？",
  str_voice_1602233_58 = "天亮了！又是人間清和天。",
  str_voice_1602233_59 = "要不要出來玩～",
  str_voice_1602233_60 = "小PlayerName，醒了嗎？",
  str_voice_1602233_61 = "還沒睡飽，明年再叫阿霓起來吧……",
  str_voice_1602233_62 = "夜晚，適合聽海浪聲。",
  str_voice_1602233_63 = "不好好睡覺會長不高哦。",
  str_voice_1602233_64 = "摸摸頭，願小PlayerName永無夢魘。",
  str_voice_1602233_65 = "今天過得開心嗎？",
  str_voice_1602233_66 = "日出而作，日落而息，是好習慣。",
  str_voice_1602233_67 = "送你的五色絲，要好好戴著喔。",
  str_voice_1602233_68 = "龍洲有很多節日，下次再一起過吧。",
  str_voice_1602233_69 = "小PlayerName用的文字，教教阿霓！",
  str_voice_1602233_70 = "阿霓收到了沒吃過的供品，一起吃吃看吧？",
  str_voice_1602233_71 = "你喜歡什麼供品……不對，是禮物！",
  str_voice_1502281_1 = "「空之末裔」這個稱呼真的好帥氣！唔唔唔，如果這是澤塔想出來的就好了……",
  str_voice_1502281_2 = "「克勞狄烏斯」、「艾瑟爾烈德」、「彼得克利爾」……嗯，澤塔果然很有取名的品味啊。嗯？替炸彈取名很奇怪嗎？",
  str_voice_1502281_3 = "「人生就是速度與甜味。所以，一邊飆車一邊吃糖就是人生應有的模樣——澤塔如是說」。嗯嗯……感覺說出了很帥氣的台詞呢。",
  str_voice_1502281_4 = "嘿嘿～我可是要拯救艾斯特拉的勇者主角！解開右手的「永夜慟哭之封印」還會變得更強喔！",
  str_voice_1502281_5 = "所謂的勇者，簡單來說就是友情、努力、勝利，當然還有最重要的——糖分。無論哪一項，澤塔都是百分百符合呢。",
  str_voice_1502281_6 = "「此刻，我的右手正在熊熊燃燒，它在嘶吼著，呼喚著我去……」後面是啥來著？糟糕，這麼帥氣的台詞居然想不起來。",
  str_voice_1502281_7 = "你也不賴嘛，再加把勁，澤塔就考慮讓你加入我的勇者小隊！",
  str_voice_1502281_8 = "我認可你了，空之末裔。從今天起，你就是我勇者小隊的成員了！現在，你得與澤塔一起分享這支棒棒糖，這是入隊儀式的一環喔。",
  str_voice_1502281_9 = "等一切都結束之後，你有考慮過要做什麼嗎？如果沒打算的話，要不要和澤塔一起……糟糕糟糕，差點就要立FLAG了！",
  str_voice_1502281_10 = "真是無聊啊，好想出去飆車……不，難道這也是命運對勇者主角的試煉嗎？澤塔，不可以逃避呀。",
  str_voice_1502281_11 = "欸——叫澤塔乖乖待在這裡？不要不要，我想出去飆車！一定要……？真愛撒嬌，那就稍微陪你一下下，就一下下喔？",
  str_voice_1502281_12 = "唔唔，牛皮糖蓋飯的開發失敗了，果然這樣的組合還是太離譜了呢……下次試試用水果糖吧。",
  str_voice_1502281_13 = "嗯，讓我看看，來顆太妃糖吧？不、不，還是來顆牛奶糖吧。",
  str_voice_1502281_14 = "你問我「吃這麼多糖，牙齒沒問題嗎」？哈哈哈，那當然啦，我可是紅油扳手的甜蜜死神，才不會忘記保持口腔健康咧。",
  str_voice_1502281_15 = "生日快樂！所以蛋糕呢？蛋糕在哪裡？加了很多奶油和草莓的那種蛋糕！",
  str_voice_1502281_16 = "勇者澤塔，今天也要為了世界的命運而奔走！",
  str_voice_1502281_17 = "早安，呵……好想睡。澤塔是小孩子，多睡一點也沒關係吧。",
  str_voice_1502281_18 = "太陽……下山了。這樣一來，那些傢伙也該開始行動了。哎？那些傢伙是誰？這個嘛……這是我的戰鬥，你不要插手！",
  str_voice_1502281_19 = "晚安！咦，你問我為什麼不睡覺？因為澤塔已經是大人了，不用那麼早睡也沒關係。",
  str_voice_1502281_20 = "我從小就在紅油扳手長大，跟大家都很合得來啦。除了那個女人……哼，也對，身為主角不能沒有勁敵呢。",
  str_voice_1502281_21 = "白夜城？啊……我當然知道！澤塔曾在那裡打敗邪龍，拯救了一位美麗的公主殿下喔。",
  str_voice_1502281_22 = "及時行樂！該吃糖囉！",
  str_voice_1502281_23 = "放心吧，澤塔會保護大家！畢竟澤塔九歲就能幹掉三隻暗鬼了。",
  str_voice_1502281_24 = "青瞳……那傢伙明明是邪惡魔王的手下，澤塔早晚會揭開她的真面目！",
  str_voice_1502281_25 = "紅油扳手的孩子們都是我的手下。",
  str_voice_1502281_26 = "守護世間的糖果，就是澤塔的使命！啊，順帶一提，不包括零卡糖和甘草糖喔。",
  str_voice_1502281_27 = "討厭的東西啊……大概是「失敗」吧？但這也是命運對主角的試煉！",
  str_voice_1502281_28 = "真是令人羡慕啊，空之末裔的超古代兵器。",
  str_voice_1502281_29 = "啊啊，在命運之手的指引下，終於與傳說中的救世主——澤塔相會了呢。做得不錯，PlayerName。喏，給你一顆糖吧！",
  str_voice_1502281_30 = "嗯，這感覺真不賴。",
  str_voice_1502281_31 = "右手的封印要……",
  str_voice_1502281_32 = "「永夜慟哭之封印」，將汝之力借予吾……",
  str_voice_1502281_33 = "「永夜慟哭之源」——蒞臨！",
  str_voice_1502281_34 = "需要澤塔出馬了呀？",
  str_voice_1502281_35 = "糖果罐要滿囉～",
  str_voice_1502281_36 = "送他們一點禮物吧？",
  str_voice_1502281_37 = "甜蜜的～",
  str_voice_1502281_38 = "甘美的～",
  str_voice_1502281_39 = "招蜂！",
  str_voice_1502281_40 = "引蝶！",
  str_voice_1502281_41 = "救世勇者小隊，出戰！",
  str_voice_1502281_42 = "你們敗給我的命運，會讓我敗給更強者。",
  str_voice_1502281_43 = "不過……是命運的試煉罷了……",
  str_voice_1502281_44 = "接下來，勇者的故事將如何發展呢？",
  str_voice_1502281_45 = "謝啦，要吃糖嗎？",
  str_voice_1502281_46 = "居然知道澤塔正需要這個嗎？",
  str_voice_1502281_47 = "都是勇者小隊的同伴了，不用這麼客氣啦。",
  str_voice_1502281_48 = "空之末裔，你果然也受到了命運的指引呀。",
  str_voice_1502281_49 = "從我懂事起，就是羅伊在照顧我。對我來說，他就像是村長對勇者一樣的存在！",
  str_voice_1502281_50 = "哼，不是我要自誇，澤塔可是很有駕駛天賦的喔。當年澤塔第一次開車上路，就撞飛了三隻暗鬼！",
  str_voice_1502281_51 = "那些傢伙老是說那個魔女……青瞳，賽車技巧很厲害。可是，澤塔明明也得過比賽的冠軍啊？",
  str_voice_1502281_52 = "白夜～極光！",
  str_voice_1502281_53 = "喂！",
  str_voice_1502281_54 = "早安，呼～",
  str_voice_1502281_55 = "這麼快就中午了？",
  str_voice_1502281_56 = "呼，想睡了。",
  str_voice_1502281_57 = "新年快樂！有什麼新年願望嗎？澤塔會如實替你轉告給命運的主宰者！",
  str_voice_1500924_1 = "我知道我這套衣服很好看，但你也不用這樣直勾勾地盯著我吧。欸，也不用背對著我呀？你、你還是轉過去吧……",
  str_voice_1500924_2 = "為什麼要打扮「獵石」？這還用問嗎，「獵石」可是我獨一無二的時尚單品。",
  str_voice_1500924_3 = "咳咳。「哦呵呵，這單生意我很感興趣。貴商會一定不想錯過我的投資——」欸？你、你什麼時候來的？！我剛剛什麼都沒說，一定是你聽錯了！",
  str_voice_1500924_10 = "怎麼一直不理我？說吧，是不是做了虧心事才躲著我？欸，你只是在忙工作？那……也不至於一點時間都沒有吧？",
  str_voice_1500924_11 = "哼哼，既然你都誠意邀請我了，我也不是不能幫你。說說看，有什麼棘手的任務需要我幫你擺平？",
  str_voice_1500924_12 = "你問我還想不想甩開「獵石」？……我說「獵石」這麼固執的傢伙，這世界上也只有我能忍受得了吧。",
  str_voice_1500924_13 = "「想跟人做生意，首要把自己收拾得體面一點」，這當然也算是一種「條律」。沒聽過？現在你聽過了。",
  str_voice_1500924_14 = "別以為你藏得很好，我早就發現是你……是你幫我走出那場夢。但你也不要太得意忘形……呃，稍微得意一下我也管不著啦！",
  str_voice_1500924_16 = "準備好了就快點出發吧，咦？還沒有嗎，不會吧……好了，會等你啦。",
  str_voice_1500924_17 = "早安，我想確認一下，今天的早餐裡應該沒有放胡蘿蔔吧？",
  str_voice_1500924_18 = "這麼多晚宴邀請你，你怎麼不去？怎麼……要我帶你去嗎？",
  str_voice_1500924_19 = "偶爾打破條律，世界好像也不會因此毀滅。但……真的該休息了，PlayerName……",
  str_voice_1500924_35 = "還沒開始嗎？",
  str_voice_1500924_36 = "你覺得呢？",
  str_voice_1500924_37 = "嚐嚐這華麗的荊棘吧！",
  str_voice_1500924_38 = "掙扎只會更痛喔。",
  str_voice_1500924_39 = "傾瀉一切！",
  str_voice_1500924_40 = "逃不掉的！",
  str_voice_1500924_44 = "最近很喜歡你這裡……是「獵石」喜歡不是我！",
  str_voice_1500924_58 = "今後，我會和「獵石」一起好好活下去。",
  str_voice_1500924_59 = "有空可以再陪我去一趟影鎮嗎？",
  str_voice_1500924_60 = "有什麼想要我幫你做的嗎？我可不想欠這麼大的人情。",
  str_voice_1500924_61 = "我會試著聽取你的意見，但吃胡蘿蔔這件事情沒得商量。",
  str_voice_1500924_62 = "這套衣服完全符合父親對我的期望，但現在我是為自己而穿。",
  str_voice_1500924_63 = "以前竟然沒人發現這座小鎮嗎？真是的，果然還是要我出馬才行。",
  str_voice_1500924_64 = "趁沒人發現，也……不是不能嚐一顆地上的石子吧？",
  str_voice_1500924_65 = "一言不合就動手，真是莫名其妙，可惜了我新買的裙子……",
  str_voice_1500924_66 = "如果沒有這股奇怪的味道，這座森林一定很好吃吧……",
  str_voice_1500924_67 = "「獵石」，這一次……換我來尋找你的蹤跡！",
  str_voice_1500924_68 = "嗯？需要我教你如何遵循條律嗎？",
  str_voice_1500924_69 = "現在可不是休息的時候！",
  str_voice_1500924_70 = "怎麼還沒到？",
  str_voice_1500924_71 = "發現寶藏！",
  str_voice_1602271_1 = "別緊張，附近的暗鬼不會來打擾我們。你看，「獵鷹一號」和「獵鷹二號」在高空干擾著訊號，「獵鷹三號」也在持續巡邏。",
  str_voice_1602271_2 = "「空裔一號」，啊……抱歉，我好像還沒習慣直呼你的名字，PlayerName……",
  str_voice_1602271_3 = "你叫我「不要隨時都這麼神經緊繃」？這是我的職業習慣，你不喜歡的話，我可以隱藏自己的氣息。嗯……不是這個意思嗎？",
  str_voice_1602271_4 = "如果不能更進一步，那就是訓練得還太少。和你不同，PlayerName，我並不是生來就擁有這身力量的天才。",
  str_voice_1602271_5 = "好，打鐵趁熱！我還想繼續改良「獵鷹」系列的演算法，讓它們可以為我的隊員提供更強大的安全防護……",
  str_voice_1602271_6 = "PlayerName，我做到了！對，我想馬上告訴父母，還有姑姑。不是為了恢復「英雄世家」的榮譽，只是因為……想把快樂第一時間分享給最親的人。",
  str_voice_1602271_7 = "啟光軍事博物館最近有個新展覽，我會找時間去參觀……嗯，要去嗎？我不介意多帶一個人。",
  str_voice_1602271_8 = "我這有一枚多餘的「默契好友勳章」，可以送你。嗯，這種勳章需要兩個拼在一起才能完整。你問另一枚在哪裡……？我收起來了。",
  str_voice_1602271_9 = "嗯，我答應你……至少在你身邊的時候，我不會再繃緊自己的神經了。",
  str_voice_1602271_10 = "不用我在這裡站崗，也不放我回去休息……你找我來，是有什麼話想告訴我嗎？",
  str_voice_1602271_11 = "既然是你的請求，倒也無妨。",
  str_voice_1602271_12 = "你當然沒辦法在啟光的任何角落找到和「獵鷹」一樣的無人機，因為這些是我自己改裝的。很奇怪嗎？但我在軍校時學的正是機械工程。",
  str_voice_1602271_13 = "有時候，你會讓我想起我的妹妹。嗯？我沒有別的意思……妹妹雖然比我小八歲，但已經展現出很強的天賦了。",
  str_voice_1602271_14 = "你問我，「如果沒有戰爭，想做什麼」……？這種問題對我來說太奢侈了，PlayerName。我只希望當下的這一刻，我們都可以安全無虞。",
  str_voice_1602271_15 = "我拿到一塊配給的蛋糕，但我不太餓……給你吃吧。",
  str_voice_1602271_16 = "你……似乎也很忙？這樣看來，你好像也沒有立場勸我多休息。",
  str_voice_1602271_17 = "你醒了？希望不是我晨練的聲音把你吵醒的……沒關係，你還可以再多睡一會。",
  str_voice_1602271_18 = "晚餐時間？多謝，留一口吃的給我就好了，我不在乎口味。",
  str_voice_1602271_19 = "沒事，在前線偵察時我也常會通宵，習慣了。倒是你……不用勉強自己，早點休息吧。",
  str_voice_1602271_20 = "哪裡需要我們，我們就到哪裡。我相信啟光聯邦所肩負的使命，除了我們沒有其他人可以做出這番事業。",
  str_voice_1602271_21 = "北境嗎……我妹妹很喜歡北境的傳說和童話。如果有機會，真想帶她去那裡看看。",
  str_voice_1602271_22 = "為了啟明之光。",
  str_voice_1602271_23 = "總有一天……總有一天會把那群黑漆漆的傢伙趕盡殺絕……",
  str_voice_1602271_24 = "有人說我和緋長官有一點像，但我知道那是恭維話罷了。只希望……我不會辜負緋長官的期待。",
  str_voice_1602271_25 = "噓！小聲點……你怎麼知道我想摸摸看菲莉詩長官的尾巴？",
  str_voice_1602271_26 = "……你是誰家的小貓咪？可以……讓我摸摸你軟軟的小肚子嗎？",
  str_voice_1602271_27 = "雖然只是模擬戰鬥，我也不希望被扣除哪怕一分。所以不用阻止我了，我還可以繼續。",
  str_voice_1602271_28 = "百聞不如一見，但巨像……果然，不太適合配合隱匿的偵察任務呢。",
  str_voice_1602271_29 = "「鷹眼小隊」隊長「獵鷹零號」前來報到！嗯？是你……「空裔一號」？",
  str_voice_1602271_30 = "勤能補拙。",
  str_voice_1602271_31 = "目光銳如鷹眼……",
  str_voice_1602271_32 = "攻擊凜如利爪……",
  str_voice_1602271_33 = "行動迅如振翅……",
  str_voice_1602271_34 = "鷹眼小隊，集合！",
  str_voice_1602271_35 = "偵察完畢！",
  str_voice_1602271_36 = "時刻等待命令。",
  str_voice_1602271_37 = "鷹域展開！",
  str_voice_1602271_38 = "鷹爪出擊！",
  str_voice_1602271_39 = "噓，安靜。",
  str_voice_1602271_40 = "逃不掉了。",
  str_voice_1602271_41 = "任務收到。",
  str_voice_1602271_42 = "嗯，這是我職責所在。",
  str_voice_1602271_43 = "……調整狀態，再來一次！",
  str_voice_1602271_44 = "我的「獵鷹」應該不會嚇壞這裡的螢盞吧？",
  str_voice_1602271_45 = "給我的？",
  str_voice_1602271_46 = "嗯……謝謝。",
  str_voice_1602271_47 = "你不用這樣費心。",
  str_voice_1602271_48 = "沒有不喜歡……我會好好珍藏的。",
  str_voice_1602271_49 = "在迦南城，出生在一個「英雄世家」雖然能讓你備受矚目，但並不會帶來實質性的優待。",
  str_voice_1602271_50 = "身邊那些天賦出眾的孩子，很早就被各大軍校、甚至是委員會挑走了。而我……我不能只是躲在角落默默地不甘心。",
  str_voice_1602271_51 = "比起在後方的實驗室被同胞們保護，我更希望能在前線搏殺。這就是我進入第三軍團的理由，有什麼問題嗎？",
  str_voice_1602271_52 = "白夜極光。",
  str_voice_1602271_53 = "報告。",
  str_voice_1602271_54 = "早安。",
  str_voice_1602271_55 = "午安。",
  str_voice_1602271_56 = "晚安。",
  str_voice_1602271_57 = "新年快樂。我？我沒有別的願望，只希望妹妹可以無憂無慮。還有你，希望你新的一年健康、快樂。",
  str_voice_1602291_1 = "我……喜歡遊戲。每個新手都能得到平等的指導，萬一失敗也可以重新來過。",
  str_voice_1602291_2 = "就算你說「不要用腳撿掉在地上的東西」……但我的手忙著打遊戲啊。",
  str_voice_1602291_3 = "腰痠背痛了……有點後悔沒收下貢露前輩的按摩背包。咦，你要幫我按摩……？躺下就不必了吧。",
  str_voice_1602291_4 = "策略、格鬥、射擊、角色扮演……你，喜歡哪一種？我是經典派來著。",
  str_voice_1602291_5 = "舊時代的人創造的遊戲百花齊放，那個時代他們一定過著充實的生活吧……哪怕是地獄式的充實。",
  str_voice_1602291_6 = "「虛擬實境」遊戲我聽前輩提過。不過，遊戲達到那種程度，一定會被用於遊戲之外的事……吧？",
  str_voice_1602291_7 = "要我教你玩這款遊戲嗎？嗯……直接講很難說明，還是手把手教你吧。",
  str_voice_1602291_8 = "呼呵——我在努力適應你的作息……這樣我們醒著的時間比較能重疊吧？",
  str_voice_1602291_9 = "用你當枕頭的話，即使晚上也能睡得很香吧？",
  str_voice_1602291_10 = "喂——我的雙手已經離開遊戲機了喔——要打敗我就趁現在……",
  str_voice_1602291_11 = "這裡……是不是太亮了？啊，好……為了保護眼睛，就不關燈了。",
  str_voice_1602291_12 = "經營店鋪很難……好在，艾斯特拉的遊戲玩家也不多……應該可以早點退休。",
  str_voice_1602291_13 = "打遊戲……可以。參加比賽……勉、勉強。站在聚光燈下領獎……絕對不行！",
  str_voice_1602291_14 = "有些遊戲，組隊一起玩更有趣，這也是我守在遊戲廳的一大原因。",
  str_voice_1602291_15 = "果然，你是那種會在遊戲裡填寫真實生日的類型……生日快樂。",
  str_voice_1602291_16 = "呵啊——是你啊……呃，沒事，等你走了我再睡。",
  str_voice_1602291_17 = "嗯？對我這麼早就起床感到很驚訝……？其實也有可能，我根本是還沒睡。",
  str_voice_1602291_18 = "早餐還沒好嗎？我都起床一陣子了。",
  str_voice_1602291_19 = "……喔好，你去休息吧。明天需要我叫你起床嗎？",
  str_voice_1602291_20 = "對不喜歡大太陽的我來說，影鎮很好，被白夜城遮得嚴嚴實實。",
  str_voice_1602291_21 = "啟光好像還有不少遊戲被當作古代遺物收藏起來……要怎麼樣才能玩到呢。",
  str_voice_1602291_22 = "影子在注視著你。",
  str_voice_1602291_23 = "要是暗鬼也能像《塔塔開方塊》那樣，聚成一排會自動消失就好了。",
  str_voice_1602291_24 = "我不是那塊料啦，只有遊戲方面能和貢露前輩有得聊。",
  str_voice_1602291_25 = "我想向歐緹學習一些技術。要是能自己挖掘、修理遠古的遊戲機就好了。",
  str_voice_1602291_26 = "我光靠打遊戲就能一直活下去。只能選一款的話……我選《塔塔開方塊》。",
  str_voice_1602291_27 = "太陽下人來人往的大街……不行，會暈倒。",
  str_voice_1602291_28 = "好想一直待在娛樂室玩遊戲，不過那裡人也太多了……",
  str_voice_1602291_29 = "觸發驚嘆號！任務讀取中……你好，我是巴緹牙，影鎮遊戲廳「祕密獠牙」的領主，歡迎來到遊戲的世界。",
  str_voice_1602291_30 = "升級成功。",
  str_voice_1602291_31 = "覺醒成功。",
  str_voice_1602291_32 = "照理說應該變強了，找個關卡試試威力吧。",
  str_voice_1602291_33 = "好，這樣就能陪你闖更多關了。",
  str_voice_1602291_34 = "我打暗鬼？啊……真的假的？",
  str_voice_1602291_35 = "BUFF疊得差不多了……",
  str_voice_1602291_36 = "怎麼旋轉都沒問題。",
  str_voice_1602291_37 = "進洞成功。",
  str_voice_1602291_38 = "消滅所有空洞。",
  str_voice_1602291_39 = "吃到火力了！",
  str_voice_1602291_40 = "吃到彈藥了！",
  str_voice_1602291_41 = "Game start！",
  str_voice_1602291_42 = "呼，總算是過了。",
  str_voice_1602291_43 = "我要重來到打贏為止。",
  str_voice_1602291_44 = "娛樂室有新遊戲……？唔，我晚上去玩。",
  str_voice_1602291_45 = "要找對好感度禮物唷。",
  str_voice_1602291_46 = "選對了，好感度上升！",
  str_voice_1602291_47 = "看到FLAG了……",
  str_voice_1602291_48 = "好像……快被你攻略了。",
  str_voice_1602291_49 = "我有蝙蝠亞人血統，不適應陽光，手腳也短短的，不方便幹活……天生的廢人，大概就是這樣吧？",
  str_voice_1602291_50 = "因為遊戲而認識了貢露前輩。前輩說我反應敏捷，直覺一流，讓我很震驚……真的不是神經衰弱，喜歡亂想嗎？",
  str_voice_1602291_51 = "在前輩和其他幾位玩家的支持下，我告別了尼特生活，戰戰兢兢地接手了這家店，然後……嗯，顧客人都還挺好的嘛。",
  str_voice_1602291_52 = "歡迎來到白夜極光。",
  str_voice_1602291_53 = "喂？",
  str_voice_1602291_54 = "晚安，呵啊——",
  str_voice_1602291_55 = "寶箱在哪……",
  str_voice_1602291_56 = "醒了，周圍好安靜啊。",
  str_voice_1602291_57 = "新年快樂。你可不要學我喔，跨年還在打遊戲……還不是因為你現在才來，我邊打遊戲邊等你好久了。",
  str_voice_1601533_1 = "在迦南城想看見陽光並不容易。努力推動綠化，提倡健康生活，讓大家期待朝陽，我只為一個道理……別忘了我們真正的起點。",
  str_voice_1601533_2 = "練習舞蹈的時候到了……怎麼了？這也是社交禮儀，我當然也會學。不過練起來真難，連雷霆也跟不太上我。",
  str_voice_1601533_3 = "嗯？我穿成這樣當然不太適合打架，但是嘛……哼哼，萊因哈特可不會被任何東西束縛。",
  str_voice_1601533_10 = "久等了，今天的事務終於處理完了。嗯？你……睡著了嗎？呵，好好享受這寧靜吧。",
  str_voice_1601533_11 = "好，換手吧，讓我主宰！",
  str_voice_1601533_12 = "感到不安嗎？你可以向我傾訴。哈，我在啟光聽的牢騷，可比你想像得要多。而且朋友嘛，就該適時分享情緒。",
  str_voice_1601533_13 = "放輕鬆，想對得起所有期待是不可能的。你可以保留歉意，並在明天更進一步。慢慢來，「明天」有很多。",
  str_voice_1601533_14 = "時代在變化，啟光這艘大船也在經歷浪潮。沒關係，我會和所有夥伴一起渡過風暴。",
  str_voice_1601533_16 = "白天也要注意休息，聽過「只工作，不玩耍，聰明孩子也變傻」嗎？",
  str_voice_1601533_17 = "早呀。對了，這裡的桌子不舒服，不適合長時間工作，建議你換一張。",
  str_voice_1601533_18 = "你想去參加迦南城的宴會嗎？別後退啊，都是正經美食。",
  str_voice_1601533_19 = "這裡的風景很好，讓我能夠守望長夜，盼著黎明破曉。",
  str_voice_1601533_35 = "讓他們面對我！",
  str_voice_1601533_36 = "粉碎一切枷鎖！",
  str_voice_1601533_37 = "迎向你的毀滅吧！",
  str_voice_1601533_38 = "我就是啟明之光！",
  str_voice_1601533_39 = "破曉！",
  str_voice_1601533_40 = "貫穿長夜！",
  str_voice_1601533_44 = "多好的基地，就在這伴著漫天光輝休息一會吧。",
  str_voice_1601533_58 = "這麼早？真不錯，不考慮一下加入啟光的特殊隊伍嗎？",
  str_voice_1601533_59 = "早啊！你看窗外了嗎？陽光明媚，別躲在屋子裡。",
  str_voice_1601533_60 = "起床了嗎？想參加晚宴，就得從早上開始準備囉。",
  str_voice_1601533_61 = "有好好吃飯嗎？美食可是來之不易。",
  str_voice_1601533_62 = "現在正是陽光最烈的時候呢，真希望迦南城也能曬曬。 ",
  str_voice_1601533_63 = "外頭的人好像很不喜歡這時候談事情，但我倒無所謂。",
  str_voice_1601533_64 = "眺望群星，總會感慨世界如此美麗。",
  str_voice_1601533_65 = "多多休息，別讓關心你的人操心。",
  str_voice_1601533_66 = "宴會落幕的時間到了，和這夜告別吧。",
  str_voice_1601533_67 = "你相信「黎明終將破曉」嗎？",
  str_voice_1601533_68 = "我們應該追逐群星，而不是被困在原地。",
  str_voice_1601533_69 = "想大步前進，就得先掙脫束縛。",
  str_voice_1601533_70 = "通常來說，我用槍尖書寫自己的傳奇。",
  str_voice_1601533_71 = "啟光也需要朋友，需要很多朋友。",
  str_voice_1500424_1 = "你想知道我的過往嗎？坐下來吧，我有許多時間可以慢慢告訴你。我年輕的時候……連我都覺得自己混蛋。",
  str_voice_1500424_2 = "暗鬼來了！暗鬼來了！你別阻止我，總得有人警告他們，不時吹響軍號，否則他們很快就會溺亡在安逸之中！",
  str_voice_1500424_3 = "你聽過「削尖彈頭」嗎？要拼命打磨到極限，又要確保能用。這樣的彈頭，我們只留在最危險的時刻使用……",
  str_voice_1500424_10 = "你累了？沒關係，背著你我也一樣跑得動。怎麼樣，動起來吧！",
  str_voice_1500424_11 = "沒人管你不行嗎？哈，正好！我監督人很厲害！",
  str_voice_1500424_12 = "我一直相信「槍比刀強」。嗯？你問我為什麼還用刀？說來話長……總之，潘戈長官花了很大功夫逼我學。",
  str_voice_1500424_13 = "這話可能輪不到我說，但是你要好好珍惜身邊的人，別讓那些幫助你的人走遠了。要好好守護他們不放，這才是戰友。",
  str_voice_1500424_14 = "問我為什麼對你特別？我的眼光一向不差，你是那種能成為主角的人。如果覺得太難前行，我不介意替你披荊斬棘。",
  str_voice_1500424_16 = "你信不信我會駕駛巨像？不信？那還不速速駛向暗鬼，還要我等多久！",
  str_voice_1500424_17 = "懶散的傢伙，馬上給我出列！",
  str_voice_1500424_18 = "以前這時間，我們都會衝向食堂。像你這樣慢吞吞的傢伙，絕對吃不了一頓飯。",
  str_voice_1500424_19 = "睡眠充足才能確保士兵身體健康。睡吧，我會為你守夜。",
  str_voice_1500424_35 = "利刃出鞘！",
  str_voice_1500424_36 = "絕不妥協！",
  str_voice_1500424_37 = "鋼芯淬火彈！",
  str_voice_1500424_38 = "全金屬削尖彈！",
  str_voice_1500424_39 = "衝垮他們！",
  str_voice_1500424_40 = "全彈發射！",
  str_voice_1500424_44 = "累了嗎？想不想一起找點樂子？",
  str_voice_1500424_58 = "第二軍團，永不後退！",
  str_voice_1500424_59 = "服從長官是天職，可惜我比較叛逆。",
  str_voice_1500424_60 = "繼續衝！在殲滅所有暗鬼前不能停下來！",
  str_voice_1500424_61 = "來一盤兵棋推演吧。",
  str_voice_1500424_62 = "十幾歲的小女孩啊……都是怪物。",
  str_voice_1500424_63 = "證明給他們看！",
  str_voice_1500424_64 = "不小心打了個盹，幸好長官沒看見。",
  str_voice_1500424_65 = "我還能再快點，巴頓，你還能再快點！",
  str_voice_1500424_66 = "哇！有意思。",
  str_voice_1500424_67 = "沒想到那糟老頭子還挺上相的。",
  str_voice_1500424_68 = "跟我上，讓那些傢伙見識我們啟光人的骨氣！",
  str_voice_1500424_69 = "可惡，多格……讓你狠狠耍了一次帥啊。",
  str_voice_1500424_70 = "萊因哈特變了，他們都變了……事情怎麼複雜得我看不懂了？",
  str_voice_1500424_71 = "削尖彈頭還沒打出去，這算什麼？我不同意……",
  str_voice_1601553_1 = "你想知道我的過往嗎？坐下來吧，我有許多時間可以慢慢告訴你。我年輕的時候……連我都覺得自己混蛋。",
  str_voice_1601553_2 = "暗鬼來了！暗鬼來了！你別阻止我，總得有人警告他們，不時吹響軍號，否則他們很快就會溺亡在安逸之中！",
  str_voice_1601553_3 = "你聽過「削尖彈頭」嗎？要拼命打磨到極限，又要確保能用。這樣的彈頭，我們只留在最危險的時刻使用……",
  str_voice_1601553_10 = "你累了？沒關係，背著你我也一樣跑得動。怎麼樣，動起來吧！",
  str_voice_1601553_11 = "沒人管你不行嗎？哈，正好！我監督人很厲害！",
  str_voice_1601553_12 = "我一直相信「槍比刀強」。嗯？你問我為什麼還用刀？說來話長……總之，潘戈長官花了很大功夫逼我學。",
  str_voice_1601553_13 = "這話可能輪不到我說，但是你要好好珍惜身邊的人，別讓那些幫助你的人走遠了。要好好守護他們不放，這才是戰友。",
  str_voice_1601553_14 = "問我為什麼對你特別？我的眼光一向不差，你是那種能成為主角的人。如果覺得太難前行，我不介意替你披荊斬棘。",
  str_voice_1601553_16 = "你信不信我會駕駛巨像？不信？那還不速速駛向暗鬼，還要我等多久！",
  str_voice_1601553_17 = "懶散的傢伙，馬上給我出列！",
  str_voice_1601553_18 = "以前這時間，我們都會衝向食堂。像你這樣慢吞吞的傢伙，絕對吃不了一頓飯。",
  str_voice_1601553_19 = "睡眠充足才能確保士兵身體健康。睡吧，我會為你守夜。",
  str_voice_1601553_35 = "利刃出鞘！",
  str_voice_1601553_36 = "絕不妥協！",
  str_voice_1601553_37 = "鋼芯淬火彈！",
  str_voice_1601553_38 = "全金屬削尖彈！",
  str_voice_1601553_39 = "衝垮他們！",
  str_voice_1601553_40 = "全彈發射！",
  str_voice_1601553_44 = "累了嗎？想不想一起找點樂子？",
  str_voice_1601553_58 = "第二軍團，永不後退！",
  str_voice_1601553_59 = "服從長官是天職，可惜我比較叛逆。",
  str_voice_1601553_60 = "繼續衝！在殲滅所有暗鬼前不能停下來！",
  str_voice_1601553_61 = "來一盤兵棋推演吧。",
  str_voice_1601553_62 = "十幾歲的小女孩啊……都是怪物。",
  str_voice_1601553_63 = "證明給他們看！",
  str_voice_1601553_64 = "不小心打了個盹，幸好長官沒看見。",
  str_voice_1601553_65 = "我還能再快點，巴頓，你還能再快點！",
  str_voice_1601553_66 = "哇！有意思。",
  str_voice_1601553_67 = "沒想到那糟老頭子還挺上相的。",
  str_voice_1601553_68 = "跟我上，讓那些傢伙見識我們啟光人的骨氣！",
  str_voice_1601553_69 = "可惡，多格……讓你狠狠耍了一次帥啊。",
  str_voice_1601553_70 = "萊因哈特變了，他們都變了……事情怎麼複雜得我看不懂了？",
  str_voice_1601553_71 = "削尖彈頭還沒打出去，這算什麼？我不同意……",
  str_voice_1602301_1 = "生之甘露是生命糧食的補充，不僅能賜給飲用者一夜好眠，還能讓受苦之人不再自憐。您想嚐嚐看嗎？",
  str_voice_1602301_2 = "站在暗處看光靈與暗鬼廝殺不是一件樂事，但有時候，真理的訓戒就是如此。怎麼，讓您掛念了？",
  str_voice_1602301_3 = "不瞭解我的人，常常說我言語晦澀，甚至胡吹神侃。他們避開我，卻偷偷窺探我。呵呵，這種心情您應該理解吧。",
  str_voice_1602301_4 = "聽過這樣一句話嗎？「物質是光靈與生俱來的牢籠。」呵呵……看您皺眉的樣子，我就知道，您不是傻瓜。",
  str_voice_1602301_5 = "確實有人信奉「超越自我，去獲得那高於世界的力量」。但「自我」並不能被超越，拋棄「自我」這個概念並非真理的教義。",
  str_voice_1602301_6 = "仇恨與戰爭，不過是那些攫取到力量的螻蟻，對於自身的極致探索。真理之主存在於何處，他們並不知道。",
  str_voice_1602301_7 = "心情不好的時候，您會抱怨一切的遭遇都是命運的安排嗎？不妨換個方向想，相信這就是命運的安排，然後愉悅地去揭開命運的真相。",
  str_voice_1602301_8 = "我常常和他們說，建構感官，而非理解世界。因為真理存在於多個維度，透過理解世界獲得的真理，並非真理。",
  str_voice_1602301_9 = "至高的真理隱藏在至深的感受裡。那些與您建立情感連結的光靈，早已向您昭示了他們的真理。我，越來越期待與您的旅程了。",
  str_voice_1602301_10 = "怎麼一直盯著我看？不習慣我這身裝束嗎？呵呵，就算您用後腦勺對著我，剛才那些眼神我也全數收下了。",
  str_voice_1602301_11 = "即便真理的國度曾經坍塌，祂還是祂。祂散落於萬物之上，啟示萬物。儘管祂曾找到降臨之地，但在您誕生之時，祂改變了主意。",
  str_voice_1602301_12 = "接近真理的途徑唯有獲取知識。個體必須將接受的資訊與先天範疇聯結起來，產生判斷。所以個體不同，獲取的知識不同，真理的型態也就變化萬千。",
  str_voice_1602301_13 = "每個光靈身上都承載著一個世界，此時大家都在自己的世界裡，而真理之主站在光靈之中，縱覽所有世界。",
  str_voice_1602301_14 = "永恆沉睡的並非亡者。在真理的國度，即使死亡本身亦會消逝。長久站在高地，才會對個人的生命無感吧。",
  str_voice_1602301_15 = "年歲是最無用的量尺。但若您希望，我便會真心祝福您，生日快樂。",
  str_voice_1602301_16 = "需要我的協助嗎？只需付出小小的代價……您的表情還是一如既往地有趣啊。",
  str_voice_1602301_17 = "撐傘？呵呵，不用擔心，我的頭髮和肌膚在陽光下只會更加閃耀。",
  str_voice_1602301_18 = "今晚月色不錯，但是比起瓦拉吉鎮上的血月還是差了點。",
  str_voice_1602301_19 = "典籍預言了您的到來，但沒想到您來得這麼早。",
  str_voice_1602301_20 = "真理之主特為證明真理而降臨，凡屬真理之人，定會見證「神蹟」。",
  str_voice_1602301_21 = "禁錮信仰者，又要從信仰者的腦中挖出「真理是什麼」的答案，真是對真理莫大的諷刺啊。",
  str_voice_1602301_22 = "願真理，祝福您。",
  str_voice_1602301_23 = "暗鬼並非純粹的惡，光靈也非完全的善。迷失之人只因沒有真理之主的指引。",
  str_voice_1602301_24 = "聆聽、承受，對世界同時產生愛與恨，然後揉碎過往，重塑自我。他就是這樣一步步接近真理的吧。",
  str_voice_1602301_25 = "目睹了聖釘的力量，我便知道他有成為聖徒的潛質。如今，他的時刻也來臨了。",
  str_voice_1602301_26 = "我的興趣嗎？用您的能力，與我產生更深的連結吧。",
  str_voice_1602301_27 = "禁錮、永生、囈語……如您所見，質疑和厭惡這些的，並不是如今的我。",
  str_voice_1602301_28 = "祂是否存在於巨像的軀體裡……如果是過去，我的答案是否定的。",
  str_voice_1602301_29 = "既然您主動找上門來，那就搭上真理的列車吧。去往哪裡，就由我說了算了……畢竟時常探尋真理的您，多少也對我充滿好奇吧。",
  str_voice_1602301_30 = "隱祕而顯耀的力量啊。",
  str_voice_1602301_31 = "我將超越生死！",
  str_voice_1602301_32 = "我將跨越時空！",
  str_voice_1602301_33 = "永恆已至！",
  str_voice_1602301_34 = "要看點不一樣的？",
  str_voice_1602301_35 = "與我誦念契語。",
  str_voice_1602301_36 = "此為我血液中的締造。",
  str_voice_1602301_37 = "災典，具現！",
  str_voice_1602301_38 = "祭血之靈，起身！",
  str_voice_1602301_39 = "聆聽真理！",
  str_voice_1602301_40 = "我即真理！",
  str_voice_1602301_41 = "靜候神的降臨。",
  str_voice_1602301_42 = "剛才嚇到您了嗎？",
  str_voice_1602301_43 = "用身體刻印真理吧。",
  str_voice_1602301_44 = "嗯，就在這裡舉辦真理結社的集會吧。",
  str_voice_1602301_45 = "想同我一起聆聽真理嗎？",
  str_voice_1602301_46 = "祂的信仰者很多，空裔倒是獨一無二。",
  str_voice_1602301_47 = "別動……就在這裡面，聽見了嗎？",
  str_voice_1602301_48 = "與來源不明的古籍相比，我更喜歡您的饋贈。",
  str_voice_1602301_49 = "我能理解家主對瓦拉吉血脈的覬覦，也能理解我的父母對終結壽命的渴望。所以我才在血脈覺醒之年，對周圍的一切漠然不應。",
  str_voice_1602301_50 = "噗……不錯，我是從那個血月籠罩的小鎮出走，不過不是我獲得在白晝行進的能力，而是我想體驗一些不同的氣息。",
  str_voice_1602301_51 = "很久以前，我在祖先的墓穴中聽到真理之主的啟示，而大量祖先的囈語也隨之灌入我的腦袋。疼痛是偶然，但接近真理是必然。",
  str_voice_1602301_52 = "白夜極光。",
  str_voice_1602301_53 = "沒錯……",
  str_voice_1602301_54 = "不知不覺天就亮了呢……",
  str_voice_1602301_55 = "閱讀時間到了。",
  str_voice_1602301_56 = "要休息了嗎？",
  str_voice_1602301_57 = "新的一年，真理結社靜候您的光臨。",
  str_voice_1502321_1 = "導師曾問我，這些年來都在懺悔什麼？我回答「一切。出生、存在、談吐、心思……」這是第一次有人聽我說了許久卻沒走開。",
  str_voice_1502321_2 = "我不敢妄想獲得救贖。但是當「稀血」凝聚成形，信徒讚頌我的聖潔之時，我短暫產生了「獲救」的想法。",
  str_voice_1502321_3 = "「在彼失去，在此得到。在彼贖罪，在此獲膏澤。」也就是說，我做的不是噁心無聊的事，我也不是受世界遺棄的怪物。",
  str_voice_1502321_4 = "皮肉的痛楚都不是真的，因為當傷口復原，我還在那種失落的情緒之中。但不用擔心我，現在我偶爾也會感到幸福。",
  str_voice_1502321_5 = "您說「虔誠的聖釘」嗎？嗯，確實不一樣了，更鋒利，也更優雅。我可以在更多場合懺悔了。不如就……嗯？你要一起嗎？",
  str_voice_1502321_6 = "在我的血即將流乾之際，我經歷了短暫的失溫。我告訴自己，我終於迎來了渴望的沉睡，但導師卻用他的聖潔籠罩我。",
  str_voice_1502321_7 = "那裡的信徒都說，真理之主是播撒黑夜的神，會讓一切疼痛在白晝時消失。我也試著這樣想，應該算是一種懺悔吧？",
  str_voice_1502321_8 = "加入真理結社後，我很快為自己找了一個受傷有罪的理由。但是，懺悔的根源是厭惡，而厭惡的根源……請不要再問了。",
  str_voice_1502321_9 = "「稀血」冰涼而刺痛，「聖血」卻是熾熱的重生之火，它燃燒我，指引我，讓我救贖自己時也當救贖他人。",
  str_voice_1502321_10 = "啊，光顧著欣賞這套衣服，竟忘了您也在這裡，讓您見笑了。那麼，請開始您的懺悔吧，我會仔細聆聽。",
  str_voice_1502321_11 = "我知道這一天終會來臨，我將向您講述我那罪孽的過往。嗯，我會看著您的眼睛。我準備好了。",
  str_voice_1502321_12 = "喔，這是善良的信徒替我包紮的傷口。他們沒有嫌棄我，而是感念我的功績。嗯，我會懷著感激之情努力適應的。",
  str_voice_1502321_13 = "在真理面前，我是無罪之人！啊，儘管我努力這麼想，但您依然能聽到我自責的心聲吧？",
  str_voice_1502321_14 = "該懺悔什麼？您虛度的時光、您浪費的錢財、您——抱歉，我不該多嘴。",
  str_voice_1502321_15 = "祝福您，我願在每年的今天——不，每天！與您一同懺悔。",
  str_voice_1502321_16 = "可以幫我看看後背的傷口癒合了沒嗎？上次不小心刺得太深了。",
  str_voice_1502321_17 = "啊，那麼早就來了？您是比我還虔誠的真理信徒呢。",
  str_voice_1502321_18 = "這個時間嗎？當然可以。向尋求真理之人展現傷口，是聖徒的本分。",
  str_voice_1502321_19 = "您也因心中的罪惡而睡不著覺嗎？正好，我有很多懺悔的心得與您分享。",
  str_voice_1502321_20 = "他們不曾可憐我、嫌棄我，反而期待在我身上看到真理之主的降臨。",
  str_voice_1502321_21 = "反正我已不屬於那裡，不是聖徒該有的行為。這是我最後一次評論他們。",
  str_voice_1502321_22 = "願真理祝福您！",
  str_voice_1502321_23 = "暗鬼也會時常感到痛苦加身嗎？",
  str_voice_1502321_24 = "維多利亞大人接納我、指引我，我才有資格成為主的聖徒。",
  str_voice_1502321_25 = "他品讀我，在我的懺悔之詞中尋找罪孽的根源。我的真理導師，我一生的導師！",
  str_voice_1502321_26 = "我在彌留之際聽見了主的聲音。就算那是幻象，我也會再次覓得。",
  str_voice_1502321_27 = "最近我才明白，我厭惡的是自己。啊，謝謝您，總有一天，我也會接納自己。",
  str_voice_1502321_28 = "冒昧問一下，懺悔室還沒建好嗎？",
  str_voice_1502321_29 = "許多人都發現我變了，但您是第一個問我經歷了什麼的人。這身聖潔的衣服，是真理之主擁抱過我的證明。",
  str_voice_1502321_30 = "真主再次赦免我。",
  str_voice_1502321_31 = "我還有所缺失……",
  str_voice_1502321_32 = "我會時常感激。",
  str_voice_1502321_33 = "真主說，我是無辜的！",
  str_voice_1502321_34 = "千萬不能弄髒衣服。",
  str_voice_1502321_35 = "「聖血」就要凝聚成形。",
  str_voice_1502321_36 = "這不是我的力量。",
  str_voice_1502321_37 = "由我替罪惡之人回答！",
  str_voice_1502321_38 = "我將傾聽受難者的懺悔！",
  str_voice_1502321_39 = "不痛！",
  str_voice_1502321_40 = "還有很多！",
  str_voice_1502321_41 = "我願替您受苦……",
  str_voice_1502321_42 = "主再次洗淨了我的罪孽。",
  str_voice_1502321_43 = "我還不配聖徒之名。",
  str_voice_1502321_44 = "我再也不是污穢之物了，對吧？",
  str_voice_1502321_45 = "我會代主收下。",
  str_voice_1502321_46 = "真的能據為己有嗎？",
  str_voice_1502321_47 = "您比我更值得擁有它。",
  str_voice_1502321_48 = "我應當給予自己肯定。",
  str_voice_1502321_49 = "那段經歷讓我頓悟，僅只關心自己的痛苦過於淺薄。骯髒的血液不會因為我的懺悔而消失，反而必須利用來做點什麼。",
  str_voice_1502321_50 = "現在，我偶爾也會為自己的存在感到高興，但就只是偶爾。一想起我弟弟面無表情地手握繼承人佩劍時的樣子，我就……",
  str_voice_1502321_51 = "過去我只認為，真理結社是怪人的容身所，但我後來發現，正是這些怪異之人，才讓外面的世界變得合理。",
  str_voice_1502321_52 = "白夜極光。",
  str_voice_1502321_53 = "如果可以……",
  str_voice_1502321_54 = "新一天的懺悔開始了。",
  str_voice_1502321_55 = "我還有一些話要說。",
  str_voice_1502321_56 = "厭煩我了嗎？",
  str_voice_1502321_57 = "過去一年來，感謝您沒有厭棄我。",
  str_voice_1602311_1 = "PlayerName，把你的瓠仔腦袋牢牢縮好，別想冒充真理之主蹦進我腦子裡……哼，現在你可騙不了我。",
  str_voice_1602311_2 = "你是維多利亞的朋友？呵，既然如此，我不介意你也喊我一聲「叔父」。",
  str_voice_1602311_3 = "你確定要這樣……嗯，未經深思熟慮就把話說出口嗎。抱歉，這樣的行為在我看來就像是……未著衣衫的野蠻人。",
  str_voice_1602311_4 = "PlayerName，通往真理的路途沒有你想像中複雜，你只需要永遠相信「相信」的力量。",
  str_voice_1602311_5 = "所有在這片土地上掙扎的個體，都深深受真理祝福著。唯有向真理之主奉上信仰的力量，我們才有機會逃離這永恆掙扎的命運。",
  str_voice_1602311_6 = "總有一天，你也會躺進那條河。那時，所有真理將如同黑夜裡最灼熱的星芒，穿透你、撕裂你、燃燒你、重塑你……直到你不再是你，你又成為了你。",
  str_voice_1602311_7 = "早就告訴過聖釘，不要再四處宣揚我是他的「導師」。你看，搞得現在連你也想來拜師了……你不是這個意思？怎麼，是我不夠資格嗎？",
  str_voice_1602311_8 = "每個人都擁有屬於自己的修行方式，我向來不會干涉。只是我不願看到你走太多彎路。聰慧如你，應該懂我的意思。",
  str_voice_1602311_9 = "身為瓦拉吉家族的一員，我早已完成自己的使命。用你的瓠仔腦袋使勁想一想，接下來，我可以替哪個小可憐分擔一二？",
  str_voice_1602311_10 = "你果真如同一隻噤聲的兔子嗎？倒讓我開始有些好奇了……關於真理、隱修和世界的真相，你就沒有半句話想問我的嗎？",
  str_voice_1602311_11 = "很好，看樣子你替我準備了一間空空如也的房間。嗯嗯，別擔心，我不會嫌棄這地方太過狹窄。",
  str_voice_1602311_12 = "與你不同，我的城堡並不歡迎太多客人。但若你獨自前來……好吧，我會體貼地為你備上一口適合的棺木。",
  str_voice_1602311_13 = "真理無處不在。下過雨的泥土、泛黃的書頁、你我的身體之中……都有真理的痕跡。",
  str_voice_1602311_14 = "吞噬一切、謀殺眾生，卻無人能將其逮捕。你認識這位「逃犯」嗎？呵呵，沒幾個人猜得到答案，不過……也許你會是例外？",
  str_voice_1602311_15 = "今天似乎是某人的生日？請幫我轉告他——生日快樂。",
  str_voice_1602311_16 = "我有理由相信，即使是真理之主也會感到疑惑。你這樣忙碌，究竟是在做些什麼？",
  str_voice_1602311_17 = "哦？似乎有人沒見過豐盛的早餐？怎麼還愣著？還是你喜歡冷一點的濃湯？",
  str_voice_1602311_18 = "你終於肯現身了？嗯，倒也還不算太晚。真正的一天，才剛剛開始。",
  str_voice_1602311_19 = "怎麼了？深呼吸，你雜亂的氣息都快讓我的頭髮打結了。很好，現在你想告訴我，是誰在夢裡捉弄你了嗎？",
  str_voice_1602311_20 = "如今的真理結社，已確切地走在受真理祝福的正途之上。",
  str_voice_1602311_21 = "若不是佔據著那座浮空島，信奉偽神的羔羊們，將擁有比現在更令人唏噓的命運。",
  str_voice_1602311_22 = "願真理，祝福你。",
  str_voice_1602311_23 = "真理的敵人，怎會是我的朋友？",
  str_voice_1602311_24 = "不知維多利亞是否還像過去那樣討厭我？不，PlayerName，別做多餘的事。",
  str_voice_1602311_25 = "卡戎和他父親關係不好？呵呵，這不算什麼新聞了。",
  str_voice_1602311_26 = "抱歉，我比較喜歡獨處。但……如果你能像隻兔子一樣安靜，我也不介意與你共處一室。",
  str_voice_1602311_27 = "嘈雜的地方，注定充滿欺騙、背叛、較量、爭鬥。答應我，別去湊熱鬧。",
  str_voice_1602311_28 = "你很幸運，擁有一座會移動的城堡。在佈置城堡這方面，你顯然相當用心。",
  str_voice_1602311_29 = "除了教你如何在漫長的時光中抵禦無聊的誘惑和邪惡的低語，我什麼都幫不了你。即使如此，你也願意靠近我嗎？",
  str_voice_1602311_30 = "哦，我的主啊……",
  str_voice_1602311_31 = "領悟從未停滯。",
  str_voice_1602311_32 = "指引愈加清晰。",
  str_voice_1602311_33 = "彷彿回到了那條河……",
  str_voice_1602311_34 = "讓我看看。",
  str_voice_1602311_35 = "劍刃已成。",
  str_voice_1602311_36 = "你喜歡等嗎？",
  str_voice_1602311_37 = "血月的光芒啊！",
  str_voice_1602311_38 = "薔薇綻放的時刻！",
  str_voice_1602311_39 = "流淌吧……",
  str_voice_1602311_40 = "睡去吧……",
  str_voice_1602311_41 = "不會有事。",
  str_voice_1602311_42 = "我說過，不會有事的。",
  str_voice_1602311_43 = "站到我身後，快！",
  str_voice_1602311_44 = "你就是在這裡隱修了十七年嗎？",
  str_voice_1602311_45 = "怪不得大家都想成為你的客人。",
  str_voice_1602311_46 = "這是特殊的，對嗎？",
  str_voice_1602311_47 = "你很擅長討人歡心。",
  str_voice_1602311_48 = "盡情期待你會收到什麼回禮吧。",
  str_voice_1602311_49 = "瓦拉吉家族的歷史比你想像中的更久遠。有興趣的話，我可以將每一位祖先的生平都講給你聽……前提是，你真的有興趣。",
  str_voice_1602311_50 = "那時的我以為自己是在踐行真理，但在人們眼中，我只是背叛了我的兄弟。",
  str_voice_1602311_51 = "我將自己封鎖在懸崖上的古堡裡，卻意外獲得了內心的充盈與寧靜。",
  str_voice_1602311_52 = "白夜極光。",
  str_voice_1602311_53 = "有人在找我？",
  str_voice_1602311_54 = "開始聒噪起來了。",
  str_voice_1602311_55 = "昏昏欲睡的午後……",
  str_voice_1602311_56 = "看看是誰已經就寢了？",
  str_voice_1602311_57 = "所有人都能抵達新的一年，如同所有人都能抵達真理的河流。",
  str_voice_1602331_1 = "謝謝你邀請我來到這座巨像！我還是第一次見到這種冒險感十足的飛行船耶！",
  str_voice_1602331_2 = "有什麼需要我幫忙的嗎？我的鍊金術最擅長把看似普通的材料變成好東西喔！",
  str_voice_1602331_3 = "發生什麼事了？看起來好熱鬧的樣子！有什麼奇妙的委託嗎？",
  str_voice_1602331_4 = "螢盞們好可愛！要是我的鍊金術也能做出這樣可愛的小幫手就好了。",
  str_voice_1602331_5 = "艾斯特拉的材料也很豐富啊！我想全都採集起來，好好研究一番！",
  str_voice_1602331_6 = "薇絲說，「鍊金術」在這個世界是很古老的用語，用來形容非常不得了的技術。真希望我也能學到更多鍊金術的知識呢。",
  str_voice_1602331_7 = "導航員會釣魚嗎？真的嗎，你也喜歡釣魚？太棒了，等我一下，我做幾支釣竿！",
  str_voice_1602331_8 = "再說一點嘛，你的冒險故事！我已經迫不及待想聽下一個了！",
  str_voice_1602331_9 = "謝謝你，導航員，在島上和巨像上的這段時間麻煩你了。託你的福，大家度過了一個非——常難忘的夏天！",
  str_voice_1602331_10 = "桶子！",
  str_voice_1602331_11 = "歡迎來到我自豪的鍊金工房！雖然只是臨時的，嘿嘿。這些都是我做的，快來看看能不能派上用場！",
  str_voice_1602331_12 = "剛才紅油扳手的大家來跟我交換材料，各式各樣的蜥蜴跟仙人掌，真是叫人大開眼界！",
  str_voice_1602331_13 = "想去的地方？有機會的話，我想看看白夜城……啊，北境也不錯！好難決定呀。",
  str_voice_1602331_14 = "這個世界也有很多人擅長探索遺跡呢。薇絲跟我說了很多遺跡探險的故事，感覺可以開一場故事大會了。",
  str_voice_1602331_15 = "生日快樂！我和科洛蒂婭她們一起準備了這個，厲害吧！材料都是我用鍊金術製作的喲！",
  str_voice_1602331_16 = "嗯嗯，讓我研究一下這份材料，該去哪裡弄來呢？",
  str_voice_1602331_17 = "早安！我的狀態絕佳，隨時可以出發喔！",
  str_voice_1602331_18 = "今天的晚餐也很好吃，還有很多有趣的冒險故事，收穫滿滿！",
  str_voice_1602331_19 = "呼啊——感謝導航員陪我採集材料，辛苦啦。晚安。",
  str_voice_1602331_20 = "平凡無奇的生活，終於迎來了全新的夏日冒險！",
  str_voice_1602331_21 = "決定了，果然還是想去北境看看極光啊！",
  str_voice_1602331_22 = "鍊金術的基礎，就是採集與調合！",
  str_voice_1602331_23 = "就算魔物很危險，也不能停下冒險和採集的步伐！",
  str_voice_1602331_24 = "科洛蒂婭演奏的聲音真美，有機會我們再幫她籌辦一場音樂會吧！",
  str_voice_1602331_25 = "派蒂有沒有融入新地方呢？想帶她再多認識幾個朋友。",
  str_voice_1602331_26 = "真希望能學到更多鍊金術的知識或技術～",
  str_voice_1602331_27 = "受人欺負就要反擊，遇到魔物攔路就要戰鬥！絕不輕易退縮！",
  str_voice_1602331_28 = "搭乘超大的飛行船，在空中四處旅行，簡直就像作夢一樣！",
  str_voice_1602331_29 = "我是旅行中的鍊金術士，萊莎琳·斯托特，叫我萊莎就好！異世界、巨像、遺跡、夏天的冒險，正是我期待的事！",
  str_voice_1602331_30 = "我還能變得更強喔！",
  str_voice_1602331_31 = "都採集到了！",
  str_voice_1602331_32 = "調合很成功！",
  str_voice_1602331_33 = "好耶，成功了！",
  str_voice_1602331_34 = "加油吧，邁出第一步！",
  str_voice_1602331_35 = "我要改變戰況了喔！",
  str_voice_1602331_36 = "那，要開始了唷！",
  str_voice_1602331_37 = "這是我最強的絕招！",
  str_voice_1602331_38 = "一發定勝負！北斗七星！",
  str_voice_1602331_39 = "衝呀——",
  str_voice_1602331_40 = "這就是鍊金術的力量！",
  str_voice_1602331_41 = "好，讓我們玩個痛快吧！",
  str_voice_1602331_42 = "太棒了，都搞定了！",
  str_voice_1602331_43 = "我還是需要繼續修行啊……",
  str_voice_1602331_44 = "這裡的裝潢，可以用鍊金術做出來嗎？",
  str_voice_1602331_45 = "謝謝！我正想要這個素材！",
  str_voice_1602331_46 = "哇，迫不及待想要拿去調和了～",
  str_voice_1602331_47 = "這是什麼？有點心動……",
  str_voice_1602331_48 = "沒想到能在這裡收到這麼棒的禮物～",
  str_voice_1602331_49 = "三年前的我只是個平凡的農家少女，根本不懂鍊金術，每天都在尋找有什麼有趣好玩的事物。",
  str_voice_1602331_50 = "我以前也曾穿越到另一個世界過，所以我異世界的事情沒有那麼吃驚，嘿嘿。",
  str_voice_1602331_51 = "絕對別忘記你的冒險精神，還有旅途中認識的朋友！",
  str_voice_1602331_52 = "白夜極光！",
  str_voice_1602331_53 = "妳好啊！",
  str_voice_1602331_54 = "早安！",
  str_voice_1602331_55 = "咦，已經中午了？！",
  str_voice_1602331_56 = "好好睡一覺吧。",
  str_voice_1602331_57 = "新年快樂！大家來一起期待，明年會有怎樣的冒險吧！",
  str_voice_1602341_1 = "啊，不好意思，打擾到你了嗎？我沒什麼，只是一時沉浸在這座巨像所展現的風景中了。",
  str_voice_1602341_2 = "太好了，和萊莎她們一起冒險的回憶又增加了。這都是多虧有你的支持。",
  str_voice_1602341_3 = "這座巨像上也常有美妙的音樂聲傳來。唔，我也可以加入？真的嗎？",
  str_voice_1602341_4 = "克娜莉小姐好像有話想跟我說，正巧我也想欣賞一下她的樂器。嗯，該怎麼開口才好呢？",
  str_voice_1602341_5 = "想跟我學習商人的思路，好對付薇絲小姐的需求和狡木先生的推銷？呵呵，很高興你這麼信任我。",
  str_voice_1602341_6 = "如果需要的話，請將掩護和輔助的任務交給我吧。或許沒有萊莎她們那麼活躍，但我一定會盡力的。",
  str_voice_1602341_7 = "請問需要在這裡休息一下嗎？我有茶和點心。你看起來風塵僕僕的。",
  str_voice_1602341_8 = "你在為理財問題而苦惱？其實，我在資金管理方面恰好有一些經驗。讓我來幫你看看吧。",
  str_voice_1602341_9 = "今天在巨像上跟大家學到很多艾斯特拉飲食的做法，有機會可以在你面前露一手了！",
  str_voice_1602341_10 = "進貨量、出貨量、訂單數……啊，抱歉！現在明明是休假中，不應該想這些事情的。",
  str_voice_1602341_11 = "多謝你的信任。在這段時間裡，我會替你管理每一份委託的資金流向。",
  str_voice_1602341_12 = "我和白蘭女士交流了出行規劃與安全保障等議題，受益匪淺呢。這就是光靈的人生經驗嗎？",
  str_voice_1602341_13 = "你認為我可以成為影鎮大商會的會長助理？承蒙抬舉，不過我初來乍到，還有很多事情要學呢。",
  str_voice_1602341_14 = "導航員，辛苦了！這段日子你一直在照顧我們，為我們帶來珍貴的體驗，希望我們也能為你留下一段美好的回憶！",
  str_voice_1602341_15 = "生日快樂，導航員！這個禮物的企劃是由我提出，由萊莎她們準備的，但願我的構想符合你的喜好。",
  str_voice_1602341_16 = "你今天似乎有不少安排呢，需要我幫忙嗎？",
  str_voice_1602341_17 = "導航員，早安！來，這是我泡的茶。",
  str_voice_1602341_18 = "歡迎回來，今天的冒險如何？有沒有趣事要跟我分享呢？",
  str_voice_1602341_19 = "也到說晚安的時間了，今天就到這裡，明天再來繼續聽那些故事吧。",
  str_voice_1602341_20 = "我們那邊世界的王都非常繁榮興盛，但我還是比較嚮往和萊莎在野外冒險的日子。",
  str_voice_1602341_21 = "好幾位光靈都推薦我去影鎮謀職，我真的有辦法勝任嗎？",
  str_voice_1602341_22 = "巴蘭茨商會為您服務！嗯嗯，是這種感覺嗎？",
  str_voice_1602341_23 = "即使面對那麼嚇人的魔物，這個世界的居民也堅強地生活著，令人欽佩。",
  str_voice_1602341_24 = "萊莎常說自己不夠瞭解鍊金術之外的事，但對我來說，只要她在這裡，我就很滿足了。",
  str_voice_1602341_25 = "派蒂總是會擔心自己在禮儀方面不夠到位。怎麼會呢？她是很優秀的淑女呢。",
  str_voice_1602341_26 = "和萊莎跟大家一同經歷的冒險，就是我心中最棒的寶物。",
  str_voice_1602341_27 = "我也想為大家出一份力。現在的我，應該比以前成長了不少。所以，請讓我承擔更多責任吧！",
  str_voice_1602341_28 = "有種仙境般的美感，非常舒適，令人嚮往。",
  str_voice_1602341_29 = "打擾了，我是科洛蒂婭·巴蘭茨。初次來到艾斯特拉大陸，還有很多不太懂的地方，有勞導航員照顧、引薦了！",
  str_voice_1602341_30 = "好像成長了一點？",
  str_voice_1602341_31 = "我還能戰鬥！",
  str_voice_1602341_32 = "鍛鍊自己的能力。",
  str_voice_1602341_33 = "我來守護。",
  str_voice_1602341_34 = "我會，全力以赴！",
  str_voice_1602341_35 = "精靈們，拜託了！！",
  str_voice_1602341_36 = "風啊，請借我力量。",
  str_voice_1602341_37 = "別想躲開風之矢喔！",
  str_voice_1602341_38 = "結束了！純白鎮魂歌！",
  str_voice_1602341_39 = "命中！",
  str_voice_1602341_40 = "疾風纏繞！",
  str_voice_1602341_41 = "好！請交給我吧！",
  str_voice_1602341_42 = "這是大家的功勞，都辛苦了！",
  str_voice_1602341_43 = "冷靜，現在最優先的是治療……",
  str_voice_1602341_44 = "多謝招待，我也準備了一些親手做的點心，希望大家會喜歡。",
  str_voice_1602341_45 = "謝謝你，我也會準備回禮的。",
  str_voice_1602341_46 = "哎呀，有勞您費心了。",
  str_voice_1602341_47 = "那個，我恰好也有東西想送你。",
  str_voice_1602341_48 = "可、可以收下嗎？太好了！",
  str_voice_1602341_49 = "我出生於商賈之家，常常跟父親在外旅行，很少有機會結交同輩的朋友。",
  str_voice_1602341_50 = "萊莎和她的夥伴們在森林中救了我，我和她因而成為朋友，一起踏上了許多冒險。",
  str_voice_1602341_51 = "現在的我依舊走在從商之路上，但我相信，和萊莎在一起的日子讓我變得不一樣了。",
  str_voice_1602341_52 = "白夜極光。",
  str_voice_1602341_53 = "打擾了——",
  str_voice_1602341_54 = "早安。",
  str_voice_1602341_55 = "要用茶嗎？",
  str_voice_1602341_56 = "請好好休息吧。",
  str_voice_1602341_57 = "又是新的一年，願您在未來的日子裡也能繼續這場精彩的冒險，留下無數值得珍藏的美好瞬間。",
  str_voice_1502351_1 = "這就是巨像啊？無論是外形還是內部結構都好令人震撼。我不會在裡面迷路吧？",
  str_voice_1502351_2 = "決定了，我要向白夜城的騎士學習儀態，向啟光聯邦的軍官學習管理。",
  str_voice_1502351_3 = "我不太瞭解光靈的孩子們喜歡玩怎樣的遊戲，貿然加入會不會打擾她們……啊，不會嗎？",
  str_voice_1502351_4 = "我的父親曾經是很優秀的騎士，我也得為此不斷鍛鍊才行。",
  str_voice_1502351_5 = "啊，您也發現我在偷偷觀察卡蓮小姐了？因為她凜然的風姿很接近我心目中理想的樣子，讓我崇拜不已呢。",
  str_voice_1502351_6 = "來到這邊的世界後，我又經歷了很多不同凡響的戰鬥。希望我的劍能為您效力，也為巨像效力。",
  str_voice_1502351_7 = "啊，不好意思，讓您看到我失態的樣子了。且讓我重整姿勢，再來一次。",
  str_voice_1502351_8 = "您認為我的戰術大有進步？謝謝！看來這陣子的訓練沒有白費。",
  str_voice_1502351_9 = "真不愧是導航員，每次我找不到目標的時候，您就會來幫助我。下一次，就換我來守護您吧！",
  str_voice_1502351_10 = "您怎麼不說話了？果然，您也覺得我很無聊吧。嗯，不是嗎？呃，喔。",
  str_voice_1502351_11 = "嗯，我知道了。這段時間我會擔任您的騎士，好好行使保護您的職責。",
  str_voice_1502351_12 = "以前都覺得藍噗尼這樣的魔物很煩人，見識到這世界的魔物之後，才發現藍噗尼可愛多了。",
  str_voice_1502351_13 = "剛才有位光靈來向我推薦似乎是讀書會的結社入會資格，對方看起來很友善，知書達理，可惜我聽不懂。",
  str_voice_1502351_14 = "還好有科洛蒂婭在，不然我大概很難判斷這個世界的貨物流通價值，鬧出很多笑話。",
  str_voice_1502351_15 = "生日快樂，您覺得這份禮物如何？道具是萊莎做的，想法由科洛蒂婭提供，希望我參與的部分沒有拖後腿。",
  str_voice_1502351_16 = "感謝您邀請我一同用餐，艾斯特拉的菜色種類很豐富，我很滿足。",
  str_voice_1502351_17 = "早安，看來您也是很守時的人啊。",
  str_voice_1502351_18 = "時候不早了，該結束工作回到巨像了。還是您需要去夜間巡邏？",
  str_voice_1502351_19 = "呵……啊，是導航員！辛苦了，這麼晚才回來，我來幫您處理這些物資吧。",
  str_voice_1502351_20 = "如果能用我的方式，為大家貢獻力量，那就再好不過了。",
  str_voice_1502351_21 = "白夜城華美的建築令人印象深刻，但卡蓮小姐說得對，看待城市和領地，也需要深入核心才行。",
  str_voice_1502351_22 = "對於妨礙我的人，我可不會手下留情！",
  str_voice_1502351_23 = "很詭異的魔物，萊莎會不會想把牠們身上的一部分拿去當鍊金素材？",
  str_voice_1502351_24 = "這裡有這麼多全新的素材，萊莎又能製作出很多不得了的炸彈吧？",
  str_voice_1502351_25 = "其實，科洛蒂婭和那位拿著長樂器的光靈姐姐默默互看的樣子，還挺有趣的。",
  str_voice_1502351_26 = "過去的我，大概會說是讓父親和家族感到榮耀，但現在我想仔細思考，給出別的答案。",
  str_voice_1502351_27 = "呃，我不喜歡蟲子。就算知道牠們不會傷害我，但一聽到翅膀嗡嗡的聲音，我還是會忍不住緊張起來。",
  str_voice_1502351_28 = "很偉大的造物，兼具美感與實用價值。",
  str_voice_1502351_29 = "初次見面，我是派翠夏·阿貝爾海姆，叫我派蒂就好。雖然是么女，但也是貴族之裔，略懂劍術，願為您提供幫助。",
  str_voice_1502351_30 = "嗯，變強了。",
  str_voice_1502351_31 = "我會變得更加強大。",
  str_voice_1502351_32 = "逐漸適應冒險的節奏。",
  str_voice_1502351_33 = "在實踐中累積的經驗，我會更加珍惜。",
  str_voice_1502351_34 = "我會好好累積經驗的。",
  str_voice_1502351_35 = "交給我吧。",
  str_voice_1502351_36 = "別想逃走！",
  str_voice_1502351_37 = "帶著遺憾消失吧！",
  str_voice_1502351_38 = "接招吧！完美願望！",
  str_voice_1502351_39 = "接招！",
  str_voice_1502351_40 = "休想阻止我！",
  str_voice_1502351_41 = "那麼，請多指教了！",
  str_voice_1502351_42 = "贏了！但我也不會就此懈怠。",
  str_voice_1502351_43 = "……情況危急，請盡速撤退。",
  str_voice_1502351_44 = "這裡的裝潢和我故鄉非常不同，但我能理解這種獨特的美感呢。",
  str_voice_1502351_45 = "謝謝，我會惦記著您的好意。",
  str_voice_1502351_46 = "哇，這是什麼？",
  str_voice_1502351_47 = "我也想再多為您做些什麼。",
  str_voice_1502351_48 = "我會一直記得這一刻的！",
  str_voice_1502351_49 = "我是貴族之裔，雖然只是么女，但我很理解身為貴族，尤其是領主子嗣的立場。",
  str_voice_1502351_50 = "我需要為父親分憂，按照貴族的方式行事，哪怕它讓我感到難過、孤獨。",
  str_voice_1502351_51 = "但萊莎讓我見識到遠離貴族社會的人是如何生活的，讓我開始領會冒險的意義。",
  str_voice_1502351_52 = "白夜極光。",
  str_voice_1502351_53 = "請問……？",
  str_voice_1502351_54 = "真早啊。",
  str_voice_1502351_55 = "辛苦了！",
  str_voice_1502351_56 = "居然這麼晚了。",
  str_voice_1502351_57 = "願您新的一年也能找到新的目標，實現新的夢想，嗯！",
  str_voice_1602333_1 = "雖然從小就在四面環湖的地方長大，但真正的大海怎麼看都看不膩呢～",
  str_voice_1602333_2 = "導航員，這件泳裝的布料，手感是不是很像天界布？啊對喔，你不知道天界布的觸感，抱歉。",
  str_voice_1602333_3 = "艾斯特拉的海裡也有很多有趣的事物呢，像是海膽居然都在海裡！",
  str_voice_1602333_10 = "從海的那邊飄過來的是……桶子啊！",
  str_voice_1602333_11 = "「布料越少，防禦越高」？咦，這是艾斯特拉大陸的邏輯嗎？！",
  str_voice_1602333_12 = "呼，呼……大鬧一通過後感覺好熱啊。導航員，可以幫我拿點降溫的東西嗎？",
  str_voice_1602333_13 = "嗯！有朋友陪伴的夏天，果然最棒了～！",
  str_voice_1602333_14 = "噗哈哈哈哈，導航員身上也濕透了呢，還好我們倆都穿的是泳裝。呀？！居然偷襲，太狡猾了！",
  str_voice_1602333_16 = "大海在呼喚我們，趕快開始新的冒險吧！",
  str_voice_1602333_17 = "早，睡得好嗎？巨像上總是吹著清涼的風，即使是夏夜也完全不覺得悶熱呢。",
  str_voice_1602333_18 = "要來點雞尾酒點心嗎？雖然改用了這邊當地的食材，但我覺得味道也很不錯喔~來，啊~",
  str_voice_1602333_19 = "哈啾！夜裡真的有點冷呢。這毯子是給我的？嘿嘿，謝謝啦。",
  str_voice_1602333_35 = "冒險的衝動，按捺不住了！",
  str_voice_1602333_36 = "來，一起去大海吧！",
  str_voice_1602333_37 = "消失在大海的彼岸吧！",
  str_voice_1602333_38 = "夏天的我，不會輸給任何人！",
  str_voice_1602333_39 = "這招如何！",
  str_voice_1602333_40 = "轟飛吧！",
  str_voice_1602333_44 = "向著夏日的大冒險，出發！",
  str_voice_1602371_1 = "你會彈鋼琴？太好了！摩耶會吹螺號，我們可以一起演奏。",
  str_voice_1602371_2 = "唔，剛剛說到哪了？對了，你會樂器嗎？要不要摩耶教你怎麼吹螺號？",
  str_voice_1602371_3 = "要一起讀書嗎？不過我認識的字不多，你願意讀給我聽嗎？太好了！謝謝你！",
  str_voice_1602371_4 = "摩耶的力量就是你的力量。需要幫忙的話，隨時都能跟我說。",
  str_voice_1602371_5 = "螺號的旋律，會帶摩耶進入先祖大人的夢。那些泡泡其實是祂的笑聲，先祖大人幫了摩耶很多忙。",
  str_voice_1602371_6 = "PlayerName，我能從你身上聞到來自夢的味道。別怕，要是被夢纏上，我會為你吹響螺號唷。",
  str_voice_1602371_7 = "你對摩耶很友善。真的，摩耶感覺得出來喔！",
  str_voice_1602371_8 = "摩耶喜歡你！咦？你怎麼臉紅了？",
  str_voice_1602371_9 = "摩耶喜歡你！咦？你怎麼轉過身去了？唔，雖然總覺得忘了什麼——不管了，摩耶喜歡你！",
  str_voice_1602371_10 = "要休息了？你想做個美夢嗎？摩耶可以幫你製造一個美夢。",
  str_voice_1602371_11 = "好的，我要是忘記了什麼，你就提醒我！",
  str_voice_1602371_12 = "PlayerName，摩耶學會一個魔術喔。你在這裡別走開，摩耶準備一下就表演給你看。",
  str_voice_1602371_13 = "爸爸媽媽睡著了，摩耶生活在他們的夢裡。等摩耶也睡著了，爸爸媽媽和先祖大人才會來找摩耶玩。",
  str_voice_1602371_14 = "PlayerName，我今天又幫了好多人。你看，他們在我的備忘錄上蓋了好多小紅花。咦？你說……這是昨天的？",
  str_voice_1602371_15 = "生日快樂！謝謝你能出生，摩耶很喜歡你。",
  str_voice_1602371_16 = "你來啦？要一起出門嗎？",
  str_voice_1602371_17 = "你來啦？有什麼需要幫忙的嗎？",
  str_voice_1602371_18 = "呼～晚上了！要去看月亮嗎？",
  str_voice_1602371_19 = "呼～晚上了，摩耶好想睡喔。你也別熬夜嘛。",
  str_voice_1602371_20 = "好泊城的大家對摩耶很好，所以摩耶會幫艾維斯大哥哥保護好泊城。",
  str_voice_1602371_21 = "真理結社的大姐姐想要搞清楚泡泡外面是什麼，可是打破泡泡，大家都會醒過來。",
  str_voice_1602371_22 = "只有摩耶睡著了，世界才會醒覺自己是一場夢。",
  str_voice_1602371_23 = "幻影的泡泡裡，還有一些雜色。那些壞蛋在做噩夢，所以自己也變成了別人的噩夢。",
  str_voice_1602371_24 = "克娜莉姐姐吹的曲子真好聽，摩耶喜歡她。",
  str_voice_1602371_25 = "澤塔妹妹每次經過都會送我糖果，摩耶喜歡她。嗯？你說我怎麼記得？笨蛋PlayerName，因為我糖果都放在這忘了吃呀。",
  str_voice_1602371_26 = "冰咖啡真好喝，不知不覺就喝飽了。",
  str_voice_1602371_27 = "摩耶不想吃辣辣的東西，怎麼拒絕不會讓人傷心呢？",
  str_voice_1602371_28 = "在摩耶的夢裡，先祖大人也會帶著摩耶飛，但祂就沒這麼多房間呢。",
  str_voice_1602371_29 = "PlayerName，我記得你，摩耶有把你記在備忘錄裡。嗯？想看寫了什麼？不行哦，摩耶也想有自己的祕密呀～",
  str_voice_1602371_30 = "先祖在夢裡呼喚我了。",
  str_voice_1602371_31 = "煩惱是刹那泡影。",
  str_voice_1602371_32 = "命運是先祖吹出的泡泡。",
  str_voice_1602371_33 = "世界說不定是摩耶的夢。",
  str_voice_1602371_34 = "摩耶能幫你的忙。",
  str_voice_1602371_35 = "要上囉！",
  str_voice_1602371_36 = "祂要醒了。",
  str_voice_1602371_37 = "摩耶～出擊！",
  str_voice_1602371_38 = "摩耶～終結技！",
  str_voice_1602371_39 = "泡泡的旋律。",
  str_voice_1602371_40 = "泡泡的光輝。",
  str_voice_1602371_41 = "摩耶會保護你們的。",
  str_voice_1602371_42 = "嘿嘿，大家沒受傷就好。",
  str_voice_1602371_43 = "先祖大人，請幫幫摩耶。",
  str_voice_1602371_44 = "這裡有好多書喔。有童話書嗎？摩耶想看童話書。",
  str_voice_1602371_45 = "你人真好，摩耶會報答你。",
  str_voice_1602371_46 = "你是摩耶的好夢。",
  str_voice_1602371_47 = "謝謝！摩耶的臉好熱！",
  str_voice_1602371_48 = "喜歡！摩耶的胸口砰砰跳了。",
  str_voice_1602371_49 = "摩耶還記得，小時候，媽媽睡前都會拉著摩耶的手，講童話故事給摩耶聽。船兒在浪上搖啊搖，媽媽很快就睡著了。",
  str_voice_1602371_50 = "這支螺號是爸爸帶摩耶找到的。那時候，摩耶聽見有人在叫我，一下就拿起來了。摩耶不用學就懂得怎麼吹螺號，它帶摩耶在夢裡找到了先祖大人。",
  str_voice_1602371_51 = "有時候，摩耶沒吹螺號也能看到先祖大人。它好像在指引摩耶，要摩耶去縫補一個好大、好大的夢。唔，如果我們都醒了，世界會怎麼樣呢？",
  str_voice_1602371_52 = "白夜……唔？噢噢！白夜極光！",
  str_voice_1602371_53 = "泡泡～",
  str_voice_1602371_54 = "太陽亮晶晶的。",
  str_voice_1602371_55 = "摩耶懶洋洋～",
  str_voice_1602371_56 = "有做夢嗎？",
  str_voice_1602371_57 = "今天是每個新的一天裡，最最最特別的那一天！摩耶準備了好多禮物要給你，請陪摩耶一起度過今天吧！",
  str_voice_1702361_1 = "許久以前，王國需要星辰去劃破黑暗，於是我的戰友們挺身而出，將自己燃燒殆盡。星辰的灰燼仍是星塵，高貴的靈魂不會被時間磨滅。",
  str_voice_1702361_2 = "我們舊時的空裔戰友，路德維希，她為了我們付出一切。哪怕只剩我還記得，我也會將她的意志延續下去。",
  str_voice_1702361_3 = "弗萊格桑其實是個堅韌的孩子。她和艾德拉斯一樣，不曾擁有幸福的童年，甚至連可以留念的對象都沒有。別責備她的態度，她只是太累了。",
  str_voice_1702361_4 = "謝謝你，空裔。你彌補了我們所有的遺憾，讓我能完成承諾……與隊友們重逢。",
  str_voice_1702361_5 = "我知道空裔都是很友善的人。讓你來參與我們的戰鬥，真是對不起。我發誓，絕不會讓你成為「代價」。",
  str_voice_1702361_6 = "「空之末裔」……真悲傷的稱呼。你也曾在孤獨中守望，期待遇上同胞吧？別露出那麼寂寞的表情，既然我能與隊友們重逢，你或許也會遇上族人。讓我們來幫你吧。",
  str_voice_1702361_7 = "歇息吧，感受自由的風，傾聽生命的樂章。",
  str_voice_1702361_8 = "以阿克琉斯之名，我將守護你。",
  str_voice_1702361_9 = "我曾經也會驅使魔法，但如今，這副軀殼已不受光能眷顧。沒關係，縱使陷入深淵，我仍能招來星光，反抗命運。",
  str_voice_1702361_10 = "我將這股纏繞著我的力量稱為「星辰之力」，因為它常常對我竊竊私語，述說星芒間的景象。",
  str_voice_1702361_11 = "在路德維希之後，還有一位空裔曾找到我。他不像路德維希那樣目睹過希望的光，卻一樣堅定燃燒著自己的靈魂。他們才是英雄，我必須傳唱他們的故事。",
  str_voice_1702361_12 = "那些執迷於利益和權柄中的人，他們不配評價我們，更不配以狹隘的視野記下我們的故事！",
  str_voice_1702361_13 = "我們將堅守本心，沉默守望，與邪惡至死方休。兩千年前如此，兩千年後亦是。",
  str_voice_1702361_14 = "當年的我沒有足夠魄力，才讓隊友們經歷那麼多悲劇。但幸好還有愛著我們的人，他們薪火相傳，讓我們得以再聚。我欠大家太多，怎麼述說這份感激才好。",
  str_voice_1702361_15 = "生日快樂。我去拜託艾德拉斯，學做了個蛋糕給你。",
  str_voice_1702361_16 = "有什麼見聞可以分享嗎？",
  str_voice_1702361_17 = "沒想到我還能見到朝陽。",
  str_voice_1702361_18 = "要不要來篝火邊暖暖身子？",
  str_voice_1702361_19 = "夜深了，警惕那些聲音。別輕易相信腦海裡的聲音，尤其是晚上。",
  str_voice_1702361_20 = "「寂靜獵兵」本該是已經掩埋的稱號，它寓意著英雄、犧牲、背叛，還有……希望。",
  str_voice_1702361_21 = "「北境」嗎？啊……「王國」現在沐浴寧和的光輝下，這就夠了。",
  str_voice_1702361_22 = "我們是正義的守望者。",
  str_voice_1702361_23 = "牠們並非我們唯一的敵人，但我希望自己的劍只指向牠們。",
  str_voice_1702361_24 = "路德維希喜歡記錄手記，而我答應她會繼承她的一切。如今，我正替她愛著這個世界。",
  str_voice_1702361_25 = "請別恐懼我的隊友。放下武器，他們也只不過是麵包師、愛笑的少女、怕生的禁衛和渴望寧靜的人。",
  str_voice_1702361_26 = "大家在這裡過得很開心，謝謝你。",
  str_voice_1702361_27 = "現代的書籍甚至會吹捧那些惡徒，我搞不懂。",
  str_voice_1702361_28 = "能和夥伴相守，完成正義的壯舉，你們很幸運。",
  str_voice_1702361_29 = "空裔……啊，別見怪，很久以前，曾有高貴的空裔戰友為我們犧牲了一切。現在，我將守護她們最後的族人。",
  str_voice_1702361_30 = "濃郁的黑暗，為我所用。",
  str_voice_1702361_31 = "請當心，空裔。",
  str_voice_1702361_32 = "星辰之力滿盈。",
  str_voice_1702361_33 = "滿溢的力量……",
  str_voice_1702361_34 = "晦暗星光，爆發吧！",
  str_voice_1702361_35 = "不屈的流星，反抗命運吧！",
  str_voice_1702361_36 = "殲滅！",
  str_voice_1702361_37 = "見敵必殺！",
  str_voice_1702361_38 = "很久沒人叫我隊長了。",
  str_voice_1702361_39 = "都沒受傷吧？",
  str_voice_1702361_40 = "保護空裔，我來殿後！",
  str_voice_1702361_41 = "你好，我正在記錄新的見聞。",
  str_voice_1702361_42 = "謝謝，空裔。",
  str_voice_1702361_43 = "不愧是瞭解人心的空裔。",
  str_voice_1702361_44 = "我會記下你的好意。",
  str_voice_1702361_45 = "我沒東西回禮……想看看我的手記嗎？",
  str_voice_1702361_46 = "從前人們稱我「國王的右手」，我秉持著忠誠的信念行動，為王國披荊斬棘。王座上的人那時還是我的摯友，是他支持著不擅妥協的我。",
  str_voice_1702361_47 = "不知從何時起，我的身邊只剩下朋友們。或許是我始終堅持不動搖的立場，反而讓其他人都視我為敵。但我唯一不能接受的，是來自王的背叛。",
  str_voice_1702361_48 = "後來，我選擇封印隊友們，卻沒想到代價是摯友的犧牲。我發誓要為他們開闢未來，所以我必須留在過去。不必悲傷，現在你看到我，表示我已經跨越了歲月。",
  str_voice_1702361_49 = "白夜極光。",
  str_voice_1702361_50 = "空裔。",
  str_voice_1702361_51 = "早安。",
  str_voice_1702361_52 = "太陽真刺眼。",
  str_voice_1702361_53 = "你也該休息了。",
  str_voice_1702361_54 = "跨越舊的歲月，又是嶄新的未來。懷抱希望吧，會有更多好事發生的。",
  str_voice_1602381_1 = "我還在學習，如何平衡信使和正義使者的生活。",
  str_voice_1602381_2 = "小心一點，以免在塔塔面前拆穿了我的偽裝。我還不想讓她看到我真正的羽翼。",
  str_voice_1602381_3 = "這項鍊裡的「星辰紋章」，本來是阿克琉斯大人送給我們家族的護身符，現在卻變成我們守護的信物。這種忠誠很笨吧？但，這正是我最自傲的傳承。",
  str_voice_1602381_4 = "羽毛下收著刀片，又把雙翼藏入斗篷。朗基努斯一族的歷史就像我的偽裝，銳利又深沉。",
  str_voice_1602381_5 = "可能是隱藏得夠久，接觸的人夠多，我和誰都能合作。但要是能選，還是選熟悉的人吧。",
  str_voice_1602381_6 = "有朝一日，我會從這項鍊裡的「星辰紋章」中，提取出一把屬於我的至尊鋒刃。",
  str_voice_1602381_7 = "從前為了隱藏身分，朗基努斯一族不會久居在一處，更不會和人產生交集。不過，現在的我卻被你解放了，真是有點不習慣。",
  str_voice_1602381_8 = "你想聽我叫「前輩」？不行，絕對不行。那只有我在假扮身分時才會叫。你想和我變回不熟的關係嗎？",
  str_voice_1602381_9 = "在你解放我家族使命的那天，我向自己下了新的誓約。我想見證你未來的路，看你那明亮的光輝能傳遞多遠。",
  str_voice_1602381_10 = "累了嗎？好吧，適度休息不算違約。辛苦了。",
  str_voice_1602381_11 = "再確認一次，你是要我監督你工作，對吧？",
  str_voice_1602381_12 = "弗雷雅大人開朗到令我震驚。看來我還有得學。",
  str_voice_1602381_13 = "鴉羽並非真正的純黑，仔細觀察，你才會找到其中的「色彩」。怎麼了？分辨光譜不是你最拿手的嗎？",
  str_voice_1602381_14 = "幾位星辰戰士好像對我們一族感到愧疚，尤其是阿克琉斯大人。希望你能告訴他們不必那樣，我們非常榮幸。",
  str_voice_1602381_15 = "生日快樂。嗯？別詫異，我一定會記得在每年的今天，為你獻上祝福。",
  str_voice_1602381_16 = "想跟我去體驗多樣化的工作嗎？",
  str_voice_1602381_17 = "這麼早起，你也有很多工作嗎？",
  str_voice_1602381_18 = "辛苦了，你很努力，我都看在眼裡喔。",
  str_voice_1602381_19 = "到烏鴉巡邏的時間了……別問太多，去睡覺吧。",
  str_voice_1602381_20 = "信使公會掌握許多情報，但她們從未想過窺探，亦絕不洩密。這是最適合我的棲身之所。",
  str_voice_1602381_21 = "若不是影主的約束，影鎮恐怕還是一片混沌。人無信不立，影鎮應該感謝影主給予人民尊嚴。",
  str_voice_1602381_22 = "我們是最忠誠的守密者。",
  str_voice_1602381_23 = "那些黝黑的怪物，冷血無情，更沒有意識到自己該做些什麼。可悲的是，牠們本質上和我們是一樣的。",
  str_voice_1602381_24 = "歌爾蒂和我不一樣。她更適合白日的閃耀偶像，而我的真面目是午夜的烏鴉。我們只是偶然在夜晚相遇罷了。",
  str_voice_1602381_25 = "塔塔是真心喜歡送信的工作，而且非常快樂。光是看著她，就讓人心情很好。",
  str_voice_1602381_26 = "像這樣把刀刃仔細塗黑、晾乾，藏進羽毛裡的過程，很紓壓。",
  str_voice_1602381_27 = "克萊肯……那個男人為什麼滿口謊言呢？無法理解。",
  str_voice_1602381_28 = "巨像上的風真舒服。車爾尼先生最後，有沒有因為能翱翔天際而展露笑容呢？",
  str_voice_1602381_29 = "空之末裔，別害怕，你並不孤單。從今以後，我將成為你的力量。沒錯，這是我的誓言。",
  str_voice_1602381_30 = "磨礪我的羽翼。",
  str_voice_1602381_31 = "我是惡人的冥河。",
  str_voice_1602381_32 = "我是午夜的報喪鳥。",
  str_voice_1602381_33 = "我是信念的踐行者。",
  str_voice_1602381_34 = "集結。",
  str_voice_1602381_35 = "千年的啟示……",
  str_voice_1602381_36 = "指引出現了。",
  str_voice_1602381_37 = "朗基努斯的命運顯現！",
  str_voice_1602381_38 = "流星啊，刻入心底吧。",
  str_voice_1602381_39 = "黑羽送葬。",
  str_voice_1602381_40 = "刹那凋亡。",
  str_voice_1602381_41 = "我不適合擔任領袖的。",
  str_voice_1602381_42 = "祕密又守住了。",
  str_voice_1602381_43 = "快跑，笨蛋。",
  str_voice_1602381_44 = "在這裡歇腳也好。",
  str_voice_1602381_45 = "謝謝。",
  str_voice_1602381_46 = "你怎麼知道我的喜好？",
  str_voice_1602381_47 = "我會準備回禮的。",
  str_voice_1602381_48 = "一直以來……謝謝你。",
  str_voice_1602381_49 = "我的父母為了保護影鎮死去時，伯利恆女王正在訓練我，不讓我離開北境去找雙親。那時候，我的心裡除了使命，還有許多怨恨。對暗鬼的怨恨、對女王的怨恨，還有對父母送走我的怨恨。",
  str_voice_1602381_50 = "有一陣子，我一邊阻止別人發掘星辰戰士的祕密，一邊自我懷疑。明明空之山谷早已覆滅，預言也落了空，我還堅守什麼呢？這種迷惘，催生了我的憤怒。",
  str_voice_1602381_51 = "有人說我是影鎮夜晚的英雄，其實並非如此。我和歌爾蒂不同，她在夜晚行俠仗義，而我只是找些壞人發洩憤怒。再那樣下去，也許我哪天就會開始以殺人為樂吧。",
  str_voice_1602381_52 = "白夜極光。",
  str_voice_1602381_53 = "你好。",
  str_voice_1602381_54 = "打起精神。",
  str_voice_1602381_55 = "好熱。",
  str_voice_1602381_56 = "還醒著嗎？",
  str_voice_1602381_57 = "新的一年，祝你能脫離迷惘，向著嶄新未來大步前進。",
  str_voice_1602183_1 = "事情好壞總是有多個角度的。您看，就算偶爾我讓一些人失去老闆，他們還是會得到更好的老闆，就是我啊。",
  str_voice_1602183_2 = "親愛的，您在看什麼呢？嗯……？我看起來更年輕了？呵呵，油嘴滑舌的少年。過來一點，看著我。告訴我，我變了嗎？",
  str_voice_1602183_3 = "您不用急著瞭解我，親愛的。相信我，繼續合作，您會知道的。",
  str_voice_1602183_10 = "呼～忙了這麼久，真想去泡個澡呢。",
  str_voice_1602183_11 = "親愛的，我們真是相看兩不厭的黃金搭檔。這次你還有什麼商業技巧想學嗎？",
  str_voice_1602183_12 = "商會的首領即是商會的門面，不管心裡想什麼，樣子總是要裝夠的。好了，親愛的，給我個意見：我今天的香水如何？",
  str_voice_1602183_13 = "做生意，當然要盡量避免得罪人。不過嘛～有些時候，我不介意制裁一下那些不愛聽漂亮話的老闆。",
  str_voice_1602183_14 = "我擅長的商法不是壓榨利潤，而是以小博大。親愛的，正和您一樣，我們都喜歡且擅長創造奇蹟。",
  str_voice_1602183_16 = "呵呵，您來了，親愛的客人。怎麼樣，還想不想去管理您的產業呢？",
  str_voice_1602183_17 = "哎呀，這麼早來還真是勤奮呢，親愛的。要有耐心～學會等待是種美德。",
  str_voice_1602183_18 = "時機正巧，不如賞臉讓我做東，請您與我共度晚餐時光如何？",
  str_voice_1602183_19 = "這麼晚還要堅持和我打招呼，親愛的，我都要懷疑您的動機了呢。",
  str_voice_1602183_35 = "準備吞併。",
  str_voice_1602183_36 = "別猶豫哦～",
  str_voice_1602183_37 = "打上我的徽記吧。",
  str_voice_1602183_38 = "把靈魂也～奉獻給我吧。",
  str_voice_1602183_39 = "合法兼併～",
  str_voice_1602183_40 = "善意收購！",
  str_voice_1602183_44 = "親愛的，您不覺得這裡越來越像我的風格了嗎？",
  str_voice_1602183_58 = "浮空商會開門的時間到了。",
  str_voice_1602183_59 = "想跟我出去見識一下嗎？",
  str_voice_1602183_60 = "早安呀～親愛的～",
  str_voice_1602183_61 = "我把禮物放在您桌前了。",
  str_voice_1602183_62 = "飛空艇不像巨像，這時候很曬呢。",
  str_voice_1602183_63 = "哎呀，不請我進來坐坐嗎？",
  str_voice_1602183_64 = "我看到您在甲板吹風，是有大人的煩惱嗎？",
  str_voice_1602183_65 = "親愛的，想要幫我按摩嗎？",
  str_voice_1602183_66 = "夜色真美呢。",
  str_voice_1602183_67 = "「坐而言不如起而行。」",
  str_voice_1602183_68 = "影鎮的生意該是誠信至上。",
  str_voice_1602183_69 = "投資浮空商會，您絕不會後悔。",
  str_voice_1602183_70 = "改變人生的契機也許就是現在。",
  str_voice_1602183_71 = "機會稍縱即逝，而我緊握每個瞬間。",
  str_voice_1600014_1 = "我說過了，這是一條舞裙。現在這個距離正好，我可以為你做一點小小的示範……雙人舞，你不介意吧？",
  str_voice_1600014_2 = "姐姐，尼珀里絲姐姐，妳何時才能穿越鏡面的阻隔，回到這邊的世界？我好想念我們的裙擺共同搖曳的時刻……",
  str_voice_1600014_3 = "我不在的時候，鏡湖的花田恬靜依舊。是有人在替我照顧它們嗎？",
  str_voice_1600014_10 = "「妳是否記得那美麗的白花？一道出葉，一道生花。共飲朝露，根系纏扎。」",
  str_voice_1600014_11 = "別注視鏡子太久，即使有姐姐和我在，此物隱藏的祕密仍不容小覷。",
  str_voice_1600014_12 = "我……和姐姐很不一樣吧？在孿生姊妹中，我是更加沉默、悶悶不樂的那個……對，所以我嚮往她。",
  str_voice_1600014_13 = "我和姐姐是一體的，從靈魂、記憶到光能術。我們共用這一切帶來的恩惠，也承受強行分離帶來的空虛。",
  str_voice_1600014_14 = "姐姐她喜歡你……不要告訴我，你忘了她送給你的花。你問我怎麼知道的？哼，當然是因為我們本就一心同體。",
  str_voice_1600014_16 = "不用太在意我，我休息得很好，請放心。",
  str_voice_1600014_17 = "抱歉，如果我再次陷入鏡中，請叫醒我，讓我保持清醒。",
  str_voice_1600014_18 = "剛才，我好像聽見姐姐跟你打招呼的聲音？",
  str_voice_1600014_19 = "很明顯，我是來打擾你的，作為你之前「嘲弄」我的回禮。",
  str_voice_1600014_35 = "雙生鏡花，永不分離。",
  str_voice_1600014_36 = "姐姐，請借我力量——",
  str_voice_1600014_37 = "白花綻於墨雪！",
  str_voice_1600014_38 = "我們於鏡中相誓。",
  str_voice_1600014_39 = "像詩篇一樣……",
  str_voice_1600014_40 = "如寓言一般……",
  str_voice_1600014_44 = "水仙、百合、鈴蘭、風信子……啊，我還準備了些蒲公英。",
  str_voice_1600014_58 = "鏡中世界是如此兇險，幸好有你在。",
  str_voice_1600014_59 = "在鏡中，我似乎見到了女王陛下的另一種模樣……那是你們的祕密？",
  str_voice_1600014_60 = "你說得對，那究竟是本來的姐姐，還是魔鏡的化身，已經不重要了。",
  str_voice_1600014_61 = "北境的安危有我的一份責任，我不會放棄魔鏡的力量。",
  str_voice_1600014_62 = "我以鏡湖的守護者自居，沒想到竟是鏡湖守護了我。",
  str_voice_1600014_63 = "鏡子之中，究竟有些什麼？",
  str_voice_1600014_64 = "夢的世界，會不會和鏡中很像？",
  str_voice_1600014_65 = "希望裙擺不會沾濕。",
  str_voice_1600014_66 = "是冰凝，還是彩泊石？",
  str_voice_1600014_67 = "是的，我應該……一直與尼珀里絲姐姐在一起。",
  str_voice_1600014_68 = "神祕的少女，疑團重重的鏡子，你們到底是誰？",
  str_voice_1600014_69 = "不……不……我的記憶……姐姐！！",
  str_voice_1600014_70 = "女王在守護我……尼珀里絲姐姐，也還在守護我！",
  str_voice_1600014_71 = "鏡湖……在這裡，為詩畫下句點吧。",
  str_voice_1602411_1 = "只有我的心臟硬梆梆的，很不公平吧？想要的話我也弄一個給你，很酷喲！",
  str_voice_1602411_2 = "呼～看我的紙飛機。呼呼呼～飛得這麼遠，很厲害吧？比起你的巨像也不遑多讓吧？",
  str_voice_1602411_3 = "「不自由，毋寧死」這句格言，是我最喜歡的一句話，送給你吧。",
  str_voice_1602411_4 = "我們去做點瘋狂的事情吧？搶劫啟光怎麼樣？還是潛入白夜城，幫那些高高在上的神像化個妝？",
  str_voice_1602411_5 = "沒人可以指點我，我才要對所有人指指點點。呃好吧，維多利亞大人除外，畢竟她是那麼全知全能嘛。",
  str_voice_1602411_6 = "我還在跳！我的心臟還在躍動！我不屬於任何人！",
  str_voice_1602411_7 = "汪汪！嚇到你了？哈哈哈，你真有趣！別怕，我不會咬人。嗯，起碼不隨便咬人。",
  str_voice_1602411_8 = "你教我怎麼駕駛巨像吧？我來帶你兜風！現在的速度太慢啦～不行？哎喲，明明我跟你這麼要好的說～",
  str_voice_1602411_9 = "只偷偷告訴你唷，我想要的朋友，就像你這樣子。不管我太多，關心我就好。嗯……一直以來，謝謝你了。",
  str_voice_1602411_10 = "悶得身上快要長珊瑚囉。",
  str_voice_1602411_11 = "我輔助你？是你幫我幹活才對吧！我會盯住你的，別偷懶喔。",
  str_voice_1602411_12 = "嗯嗯，大鬧啟光的傳奇闖入者就是我！竊走白夜城寶物的神偷也是我！怎麼樣？多給點崇拜的目光吧，佩皮塔大人承受得起！",
  str_voice_1602411_13 = "朋友是要講義氣的，你要是有事，我和魔寵絕對不會坐視不管！你也有一樣的心情對吧？那借我點錢，我想買東西。",
  str_voice_1602411_14 = "佩皮塔·菲魯茲是個唬人用的名字。因為你看，掛上個尊姓，大家就會真的變得恭敬起來，好笑吧？",
  str_voice_1602411_15 = "祝你生日快樂，祝你生日快樂～怎麼樣，驚喜吧？",
  str_voice_1602411_16 = "冒險的最佳時間，你就來了。",
  str_voice_1602411_17 = "做好準備，才不會缺席各種典禮～",
  str_voice_1602411_18 = "最好的飯是和朋友一起分享，來吃晚餐吧。",
  str_voice_1602411_19 = "好玩的事情通常都發生在這個時間點。",
  str_voice_1602411_20 = "真理不束縛任何人，維多利亞大人允許讓我自由自在。",
  str_voice_1602411_21 = "白夜城的狗狗汪汪叫，追著我上竄下跳。啟光的鷹隼靜悄悄，全是陰謀的味道。",
  str_voice_1602411_22 = "我，佩皮塔！自由之光！真理的寵兒！",
  str_voice_1602411_23 = "要是牠們都跟烏蘇拉一樣好玩，我倒是不介意和牠們一起玩。",
  str_voice_1602411_24 = "維多利亞大人，她把快樂的鑰匙給了我。她很懂我，不過還放得不夠開。",
  str_voice_1602411_25 = "烏蘇拉剛好瘋得跟我差不多，所以我們是朋友～朋友！耶！",
  str_voice_1602411_26 = "巨像上的調製飲料，好喝～",
  str_voice_1602411_27 = "這裡的啟光隊長有點太多了，空氣都變得壓抑啦！",
  str_voice_1602411_28 = "誰敢攔我們，就用巨像轟爛他們！哈哈，開個玩笑而已，別緊張～",
  str_voice_1602411_29 = "好～該自我介紹了。我不是「那女孩」，不是「小狗狗」，我叫佩皮塔。「鬥士佩皮塔」。",
  str_voice_1602411_30 = "跳得更快！",
  str_voice_1602411_31 = "心臟在狂舞！",
  str_voice_1602411_32 = "鼓動不會停歇！",
  str_voice_1602411_33 = "我是躍動的烈火！",
  str_voice_1602411_34 = "佩皮～塔！",
  str_voice_1602411_35 = "心跳加速囉。",
  str_voice_1602411_36 = "熱血沸騰喔。",
  str_voice_1602411_37 = "自由地綻放！",
  str_voice_1602411_38 = "世界都給我狂歡！",
  str_voice_1602411_39 = "燃燒殆盡吧。",
  str_voice_1602411_40 = "盛大落幕吧！",
  str_voice_1602411_41 = "包在佩皮塔大人身上！",
  str_voice_1602411_42 = "看吧，完美的胡鬧！",
  str_voice_1602411_43 = "跑路囉～跟我來～",
  str_voice_1602411_44 = "噢噢，我有點懼高症……才怪啦！笨蛋，被騙了吧～看你緊張的樣子，真好玩。",
  str_voice_1602411_45 = "哇，真不錯。",
  str_voice_1602411_46 = "佩皮塔大人喜歡這個！",
  str_voice_1602411_47 = "又來討我歡心啦？",
  str_voice_1602411_48 = "不回禮都不好意思了。",
  str_voice_1602411_49 = "我和啟光所有人一樣，都有個不幸的童年。那個……我不想稱為父親的傢伙，是個不折不扣的軟骨頭。他害死我媽媽，又把我送上實驗台。",
  str_voice_1602411_50 = "委員會的人幫我換個心臟，就以為能夠控制我。但我還是跑了出去，認識維多利亞大人，還用自己的腿丈量了暗面……貝利撒留，我才不是瑕疵品。",
  str_voice_1602411_51 = "不管怎麼樣，佩皮塔大人都不會低頭，永遠不會！總有一天，我會奪回自己的心臟，殺了那個背叛我們的男人。",
  str_voice_1602411_52 = "鏘鏘～白夜極光！",
  str_voice_1602411_53 = "喂！",
  str_voice_1602411_54 = "你還真早起。",
  str_voice_1602411_55 = "我要吃午餐！",
  str_voice_1602411_56 = "做賊去囉～",
  str_voice_1602411_57 = "新年了，來幫大家準備個狂歡舞會吧！喔，差點忘了，新年快樂。",
  str_voice_1701103_1 = "夢裡的冒險真有趣對吧？下次再帶我去其他人的夢裡冒險吧。先說好，我可不去隊友們的夢，那些太沉重啦。",
  str_voice_1701103_2 = "好啦好啦，作為認識這麼久的福利，本聖女特別允許你向我懺悔。還愣著幹嘛？本聖女可不是隨時都這麼閒唷。",
  str_voice_1701103_3 = "慢著，我知道你要吐槽什麼！但誰規定「寂靜聖女」就真的要安安靜靜的？你是「空裔」也不會自己飛呀。",
  str_voice_1701103_10 = "嗯？怎麼在發呆？難道說……你被本聖女迷得神魂顛倒了？",
  str_voice_1701103_11 = "想必導航員先生已經充分瞭解我的偉大，才會想渴求我的智慧吧～什麼？還是要幫忙工作？你小子……膽子不小嘛。",
  str_voice_1701103_12 = "北境是極寒之地，人們卻還能在風雪中砥礪前行，為了那些努力的人們，我很高興扮演救世主。",
  str_voice_1701103_13 = "我們曾征服過風暴、雷霆、酷寒，還有可憎的暗鬼。人的偉大不在於神的祝福，而在於內心那永不熄滅的火焰。",
  str_voice_1701103_14 = "歷代的寂靜聖女都燃燒生命去幫助他人，所以沒有人長壽過。跟她們相比，我已經很幸運啦。啊啊，話雖這麼說，但我還沒滿19歲唷。",
  str_voice_1701103_16 = "這個時間還在打轉，看來導航員先生還是學不會自己制訂計畫。沒辦法，讓更加成熟的我來幫你吧。",
  str_voice_1701103_17 = "我還要睡！我該吃的苦在聖女修行時就吃完了。",
  str_voice_1701103_18 = "我要去跟大家吃飯了，你要來嗎？今天可是艾德拉斯下廚，艾德拉斯喔！",
  str_voice_1701103_19 = "都幾點了還在我面前晃，難道是想聽睡前故事嗎？這個就拜託辛西婭吧。",
  str_voice_1701103_35 = "轟臨準備。",
  str_voice_1701103_36 = "讓我仲裁。",
  str_voice_1701103_37 = "雷殛淨化！",
  str_voice_1701103_38 = "萬千雜音，靜謐——！",
  str_voice_1701103_39 = "駕馭風暴！",
  str_voice_1701103_40 = "執掌狂雷！",
  str_voice_1701103_44 = "什麼嘛，原來和平就是這種樣子……真了不起呀。",
  str_voice_1701103_58 = "雷轟！然後，靜謐！",
  str_voice_1701103_59 = "宴會？！在哪裡？",
  str_voice_1701103_60 = "嗯嗯，我就是為了這一口吃的才來的。",
  str_voice_1701103_61 = "導航員先生要不要來陪我練拳？我會注意力道的。",
  str_voice_1701103_62 = "寂靜獵兵最銳利的矛，弗雷雅參上！",
  str_voice_1701103_63 = "完美無瑕的弗雷雅，參上！",
  str_voice_1701103_64 = "耶？大家都跑哪去了？",
  str_voice_1701103_65 = "啊……有這麼遠？早知道我就騎馬過來了。",
  str_voice_1701103_66 = "嗯嗯，小小的驚喜，弗雷雅大人我就勉強收下吧。"
}
return config
